/* हवलदारनी — पूरी किताब (आवरण, शीर्षक पृष्ठ, सभी अंतराल, अध्याय 1–54 और एपिलॉग) */
window.chaptersData = [{"chapter": 0, "title": "हवलदारनी", "content": "<div class=\"kr-cover\"><img src=\"cover-hi.jpg\" alt=\"हवलदारनी — पुस्तक का आवरण\"></div>"}, {"chapter": 0, "title": "शीर्षक पृष्ठ", "content": "<div class=\"tp\"><h3>हवलदारनी</h3>\n<h3><i>एक जवाब, बहुत देर से</i></h3>\n<h3>एक उपन्यास</h3>\n<p class=\"bold-line\"><b>शारदा अशोक यदुवंशी</b></p>\n<p class=\"scenebreak\">***</p>\n<p>हवलदारनी: एक जवाब, बहुत देर से</p>\n<p>कॉपीराइट © शारदा अशोक यदुवंशी, 2026</p>\n<p>सर्वाधिकार सुरक्षित। यह एक काल्पनिक रचना है। इसके नाम, पात्र, स्थान और घटनाएँ लेखिका की कल्पना से उपजे हैं या काल्पनिक रूप में इस्तेमाल किए गए हैं। किसी भी जीवित या मृत व्यक्ति, घटना या स्थान से कोई समानता केवल संयोग है।</p>\n<p>लेखिका की लिखित अनुमति के बिना इस पुस्तक का कोई भी अंश किसी भी रूप में, फ़ोटोकॉपी, रिकॉर्डिंग या किसी भी इलेक्ट्रॉनिक या यांत्रिक माध्यम से, पुनः प्रकाशित, वितरित या प्रसारित नहीं किया जा सकता; समीक्षा में दिए गए छोटे उद्धरण इसके अपवाद हैं।</p>\n<p class=\"scenebreak\">***</p>\n<p><i>उन सबके नाम,<br>जिनकी लड़ाई सरहद पर नहीं,<br>आँगन में लड़ी गई—</i></p>\n<p><i>फ़ौजियों की माँएँ, पत्नियाँ, बच्चे,<br>और वे प्रेमिकाएँ,<br>जो किसी गिनती में नहीं आईं।</i></p>\n<p><i>जिनके अपने लौट आए,<br>और जिनके कभी नहीं लौटे।</i></p>\n<p class=\"scenebreak\">***</p>\n<p><i>ग्यारह साल तक नैना यही मानती रही कि एक वादा टूट गया था।</i></p>\n<p><i>वह इक्कीस साल की थी, जब सरहद से आई पंद्रह दिन की चुप्पी उससे सही नहीं गई, और उसने अपने ख़ून से तीन पंक्तियाँ लिखीं: मैं इंतज़ार कर रही हूँ। तुमने वादा किया है कि लौटोगे। ज़िंदा लौटना, विक्रम।</i></p>\n<p><i>विक्रम लौटा। पर वह ज़िंदगी नहीं लौटी जो दोनों ने साथ चाही थी, और उन तीन पंक्तियों का जवाब कभी लिखकर नहीं आया।</i></p>\n<p><i>ग्यारह साल बाद, फ़रवरी की एक साधारण शाम, एक छोटी-सी दुकान में एक किताब उसे रोक लेती है। उसे हाथ में लेते ही, बिना किसी वजह के, उसके भीतर सब कुछ एक पल के लिए थम जाता है, जैसे बारिश से ठीक पहले हवा साँस रोक लेती है।</i></p>\n<p><i>और उस किताब में उसे अपना ही ख़त मिलता है। वही तीन पंक्तियाँ, वही लिखावट, जो उसने ग्यारह साल पहले अपने ख़ून से लिखकर सिर्फ़ एक इंसान को भेजी थीं।</i></p>\n<p><i>वह ख़त यहाँ तक कैसे पहुँचा?</i></p>\n<p><i>एक जवाब, बहुत देर से।</i></p>\n<p><i>हर उस दिल के लिए, जिसने कभी सच्चा प्यार किया, और फिर चुपचाप इंतज़ार किया।</i></p>\n<p class=\"scenebreak\">***</p></div>"}, {"chapter": 1, "title": "अंतराल — कहीं, एक फाइल पहले ही खुल चुकी थी", "content": "<h1>अंतराल — कहीं, एक फाइल पहले ही खुल चुकी थी</h1>\n<p>उसके करीब रहने वाले लोगों को उसकी ज़िंदगी की पूरी तस्वीर समझ आने से बहुत पहले, दिल्ली के किसी और हिस्से में, एक अलग कमरे में, विक्रम राठौड़ की ज़िंदगी से जुड़े कुछ फ़ैसले लिए जाने शुरू हो चुके थे—उसकी जानकारी के बिना।</p>\n<p>एक मेज़ के दो ओर दो आदमी बैठे थे। उनके बीच एक पतली-सी फाइल रखी थी। ऊपर जलती फ्लोरोसेंट रोशनी भी उस कमरे की सोची-समझी सादगी को कम नहीं कर पा रही थी—एक ऐसा गुमनाम-सा दफ़्तर, जिसके बाहर कोई तख़्ती नहीं थी, और जिसकी मौजूदगी का कोई परिचय नहीं दिया जाता था।</p>\n<p>बरसों बाद भी विक्रम ख़ुद कभी नहीं जान पाएगा कि ऐसी कोई बैठक हुई थी।</p>\n<p>दोनों में वरिष्ठ अधिकारी की उम्र साठ के पार थी। चाँदी जैसे बाल अब भी उसी पुराने फौजी अंदाज़ में छोटे कटे हुए थे, जिसे उसने कभी पूरी तरह छोड़ा नहीं था। उसके भीतर एक ऐसी स्थिरता थी, जो दशकों तक हर कमरे में सबसे धैर्यवान आदमी बने रहने के बाद ही आती है।</p>\n<p>उसके बगल में उससे कम उम्र का एक आदमी बैठा था—इतना साधारण कि भीड़ में किसी की नज़र उस पर दोबारा न पड़े। और यही साधारण दिखना उसके काम ने उसे धीरे-धीरे सिखाया था।</p>\n<p>उस कमरे के लिए, और उसके बाद ऐसे हर कमरे के लिए, उसका नाम था—कामथ।</p>\n<p>“कैप्टन विक्रम राठौड़।”</p>\n<p>वरिष्ठ अधिकारी ने एक तस्वीर मेज़ पर उसकी ओर सरका दी।</p>\n<p>“इसकी पूरी पृष्ठभूमि खंगालो। सिर्फ सर्विस रिकॉर्ड नहीं—निजी ज़िंदगी भी।”</p>\n<p>वह एक पल रुका।</p>\n<p>“और उसके बाद इस पर चुपचाप नज़र बनाए रखना। मैं ठीक-ठीक जानना चाहता हूँ कि यह आदमी आगे चलकर क्या बनता है—इससे बहुत पहले कि हम कभी इसे यह बताएँ कि हम इसे देख रहे हैं… या क्यों।”</p>\n<p>“जी, सर।”</p>\n<p>कामथ ने अपनी नोटबुक की ओर हाथ बढ़ाते हुए कहा।</p>\n<p>हालाँकि उस समय वह ख़ुद भी नहीं जानता था कि आख़िर वे विक्रम में तलाश क्या रहे थे।</p>\n<p>उस दिन उन दोनों ने विक्रम राठौड़ के बारे में फिर कोई बात नहीं की।</p>\n<p>लेकिन उसका नाम उन रास्तों पर चलना शुरू कर चुका था, जिन्हें किसी बाहरी आदमी की नज़र के लिए बनाया ही नहीं गया था।</p>\n<p>और कहीं बहुत दूर—इन सब घटनाओं से अभी कई वर्ष पहले खड़ा—विक्रम राठौड़ नाम का एक युवा सैनिक इस बात से पूरी तरह अनजान था कि उसकी ज़िंदगी अब चुपचाप केवल उसकी अपनी नहीं रह गई थी।</p>\n<p>और यह समझने में कि आख़िर ऐसा क्यों हुआ था—</p>\n<p>अभी कई साल बाकी थे।</p>"}, {"chapter": 2, "title": "अध्याय 1 — पीतल की ट्रे", "content": "<h1>अध्याय 1 — पीतल की ट्रे</h1>\n<p>उसने उसे देखा ही नहीं। कम-से-कम उस रात तो नहीं।</p>\n<p>इक्कीस वर्ष का विक्रम राठौड़ उस विवाह में बस एक बाराती था। सामने अग्नि जल रही थी—हर फेरे के साथ उसकी लौ हवा में झुकती और फिर सीधी हो जाती—और उसी रोशनी में लाल-सुनहरे जोड़े में सजी एक अनजान लड़की किसी और के साथ फेरे ले रही थी। उसके लिए वह भी उस भीड़ का ही एक चेहरा थी—इतना अनजान कि कुछ देर बाद याद भी न रहता।</p>\n<p>उसे क्या मालूम था कि यही अनजान चेहरा एक दिन उसे भीतर से इस तरह तोड़कर रख देगा, जिसके लिए कोई ट्रेनिंग उसे तैयार नहीं कर पाई थी।</p>\n<p>उन दिनों विक्रम सेना से छुट्टी पर घर आया हुआ था। विश्वविद्यालय की ओर से तीन साल कबड्डी खेलकर उसका शरीर पहले ही गठ चुका था; फौज ने उसमें बस एक कसाव और जोड़ दिया था। लंबा कद, चौड़े कंधे, छरहरा बदन, गोरा रंग और गहरी, ठहरी हुई आँखें—जो सामने वाले को देखती पूरी थीं, मगर अपने भीतर झाँकने की जगह बहुत कम देती थीं।</p>\n<p>शादी में कई निगाहें उसकी ओर उठीं, कुछ लौट-लौटकर भी आईं। विक्रम को इसका भान तक नहीं हुआ।</p>\n<p>वर्दी उस शाम उसने पहन नहीं रखी थी, पर कुछ वर्दियाँ शरीर से उतर जाने के बाद भी आदमी के साथ चलती रहती हैं।</p>\n<p>शादी कविता के गाँव कोसली में थी। बादशाहपुर से पटौदी रोड होते हुए करीब सत्तर किलोमीटर का रास्ता था और पहुँचते-पहुँचते लगभग दो घंटे लग गए थे।</p>\n<p>हाईवे से कुछ पीछे, ढाबों की कतार के पार मैरिज हॉल था—टीन की छत वाली साधारण-सी इमारत, जिसकी चारदीवारी पर नंगे बल्बों की झालर लटक रही थी। आधे बल्ब शाम पूरी होने से पहले ही बुझ चुके थे, और बाकी हवा के हर झोंके पर काँपते हुए जैसे अपनी बारी का इंतज़ार कर रहे थे।</p>\n<p>अंदर लकड़ी के ऊँचे चबूतरे पर मंडप सजा था। लाल कपड़े से ढके खंभों पर गेंदे की मालाएँ लटक रही थीं, जिनकी पंखुड़ियाँ रस्मों के शुरू होने से पहले ही किनारों से मुरझाकर भूरी पड़ने लगी थीं।</p>\n<p>गाँव का दोस्त चौधरी उसके साथ आया था। उसने बुफे के पास अपने और विक्रम के बैठने की जगह ढूँढ़ ली।</p>\n<p>गर्म घी और सरसों के तड़के की महक खाने से पहले ही उन तक पहुँच गई थी। स्टील की प्लेटें थीं; दाल, जीरा चावल, गरम लैंपों के नीचे रखा शाही पनीर, तंदूर से लगातार आती रोटियाँ, छोले, कचूमर और एक ओर करीने से रखी पूरियाँ।</p>\n<p>विक्रम ने बिना ज़्यादा ध्यान दिए प्लेट में खाना ले लिया।</p>\n<p>बैठने के बाद खाने में भी उसका कोई खास मन नहीं लगा। बीच-बीच में उसकी निगाह भीड़ के पार मंडप की ओर चली जाती—किसी आकर्षण से नहीं, बस यूँ ही।</p>\n<p>दुल्हन अग्नि के सामने बैठी थी। लौ की सुनहरी काँप उसके झुके चेहरे पर आती-जाती रही, और वह गहनों के बोझ तले, रस्मों के बीच, पूरी तरह शांत थी।</p>\n<p>उसकी शादी विक्रम के ही गाँव के एक लड़के से हो रही थी। गाँव का रिश्ता था, इसलिए आना लगभग तय था; वरना साझा उपनाम के अलावा विक्रम दूल्हे को भी मुश्किल से जानता था।</p>\n<p>उसने दुल्हन को देखा और कुछ महसूस नहीं किया।</p>\n<p>न कोई उत्सुकता।</p>\n<p>न कोई आकर्षण।</p>\n<p>यहाँ तक कि वह साधारण जिज्ञासा भी नहीं, जो किसी अनजान चेहरे को देखकर कुछ क्षण के लिए ठहर जाती है।</p>\n<p>उसने खाना ख़त्म किया, दोबारा मिठाई लेने गया और बाकी समय चौधरी की उन लोगों पर चलती टिप्पणियाँ आधे मन से सुनता रहा, जिन्हें दोनों इतनी अच्छी तरह जानते भी नहीं थे कि उन पर इतनी चर्चा की जाए।</p>\n<p>कई महीने बाद उसे समझ आना था कि उस शाम उसकी आँखों से क्या छूट गया था।</p>\n<p>अग्नि के चारों ओर लाल-सुनहरे जोड़े में फेरे लेती वही स्त्री, जिसे उस रात उसने ठीक से देखा तक नहीं था, एक दिन गाँव के एक आँगन में उसके सामने चाय की ट्रे लिए खड़ी होगी—</p>\n<p>बस एक पल ज़्यादा।</p>\n<p>और वही एक पल उस उदासीनता में पहली दरार डालेगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>शादी के बाद कविता बादशाहपुर आ गई।</p>\n<p>मध्यम कद, छरहरा शरीर और ऐसा व्यक्तित्व कि राह चलते किसी की निगाह अनायास उठ जाए। रंग साफ़ था, मगर सबसे पहले ध्यान उसकी आँखों पर जाता—हल्की नीली-सलेटी, जैसे बारिश से ठीक पहले का आसमान। हरियाणा के उस इलाके में उनका रंग इतना असामान्य था कि शादी में भी लोगों के बीच उनकी चर्चा हुई थी।</p>\n<p>लेकिन उनकी खूबसूरती से अलग भी उनमें कुछ था—एक तेज़, परखती हुई नज़र। कमरे में दाखिल होते ही जैसे वह बोलने से पहले वहाँ मौजूद लोगों और माहौल को पढ़ लेती हो।</p>\n<p>कमर से नीचे तक आते घने बालों में तेल लगाकर वह लंबी चोटी बाँधती थी, जैसे गाँव की अधिकतर नई बहुएँ बाँधती थीं। फिर भी उस सादगी में वह साधारण नहीं लगती थी—जैसे मिट्टी के साधारण दीये में जलती कोई सीधी, ऊँची लौ।</p>\n<p>पीठ सीधी। ठोड़ी सहज ही कुछ ऊँची।</p>\n<p>उसे देखकर कई बार नई-नई ब्याही लड़की से अधिक ऐसी स्त्री का आभास होता था, जो ऐसे जीवन की प्रतीक्षा में हो, जो अब तक आया ही नहीं।</p>\n<p>शादी के कुछ ही महीने बाद विक्रम अगली छुट्टी पर गाँव लौटा।</p>\n<p>और उसी छुट्टी में उसने पहली बार रामफल के घर जाने की एक वजह ढूँढ़ ली।</p>\n<p>उसके पिता के लिए कोई संदेश था, ज़मीन के किसी काग़ज़ की बात थी—ऐसा काम जो चाहें तो अगले दिन तक भी रुक सकता था।</p>\n<p>लेकिन विक्रम ने ख़ुद से यह सवाल ही नहीं किया कि उसे उसी दिन जाना क्यों ज़रूरी लगा।</p>\n<p>कविता बिना कहे चाय ले आई।</p>\n<p>पीतल की ट्रे।</p>\n<p>ससुर घर पर होते तो दो प्याले, नहीं होते तो एक।</p>\n<p>ट्रे से अदरक और इलायची की भाप उठती, और पीतल पर प्याला रखने की हल्की खनक आँगन की चुप्पी में दूर तक सुनाई देती।</p>\n<p>प्याले के नीचे की तश्तरी में अक्सर चाय की दो-चार बूँदें छलक जातीं, मानो डालते समय हाथ एक क्षण के लिए ठहर गया हो।</p>\n<p>और चाय रख देने के बाद भी कविता तुरंत नहीं जाती थी—एक क्षण और रुकती, बस उतना ही, और देखती रहती।</p>\n<p>पहले-पहल विक्रम ने इसे संयोग माना।</p>\n<p>फिर एक गर्म दोपहर उसे पहली बार लगा कि वह जो देख रहा है, केवल उसका भ्रम नहीं।</p>\n<p>आँगन लगभग खाली था। उन दोनों के अलावा वहाँ एक कुत्ता बैठा था—आवारा, मगर ऐसा जिसे पूरा गाँव अपना मानता था और कोई भी अपना नहीं।</p>\n<p>विक्रम फिर ज़मीन के किसी काग़ज़ का संदेश लेकर आया था।</p>\n<p>रामफल घर पर नहीं था। उसका पिता भीतर के कमरे में सो रहा था।</p>\n<p>कविता हमेशा की तरह चाय लाई। कुर्ती की बाँह कोहनी तक चढ़ी हुई थी। कलाई में पड़ी पतली सोने की चूड़ी ट्रे से हल्के से टकराई और एक छोटी-सी आवाज़ हुई।</p>\n<p>उसने चाय पास रखे छोटे स्टूल पर रख दी।</p>\n<p>“धन्यवाद,” विक्रम ने कहा।</p>\n<p>कविता वहीं खड़ी रही।</p>\n<p>“गरम है।”</p>\n<p>“पता है।”</p>\n<p>“तो धीरे पीना।”</p>\n<p>विक्रम ने चाय की चुस्की ली।</p>\n<p>कविता की आँखें एक क्षण उसके गले पर ठहरीं।</p>\n<p>प्याला खाली हुआ तो उसने ट्रे आगे कर दी। विक्रम ने प्याला रखा।</p>\n<p>उँगलियाँ नहीं छुईं।</p>\n<p>“तुम बहुत आते हो,” कविता ने कहा।</p>\n<p>“काम होता है।”</p>\n<p>“काम…”</p>\n<p>उसके होंठों से हल्की-सी साँस निकली। हँसी शायद ऐसी ही होती, अगर दोनों में से कोई उसे हँसी मानने को तैयार होता।</p>\n<p>“रामफल तो काम के लिए कभी घर पर नहीं मिलता।”</p>\n<p>“मुझे पता है।”</p>\n<p>कविता ने उसकी ओर देखा।</p>\n<p>“मुझे पता है कि तुम्हें पता है।”</p>\n<p>बात वहीं ख़त्म हो गई।</p>\n<p>मगर कुछ बातें ख़त्म होकर भी ख़त्म नहीं होतीं।</p>\n<p>एक दूसरी दोपहर कविता फिर सामने बैठी थी। विक्रम चाय पी रहा था और वह उसकी ओर सीधे देखने के बजाय प्याले को देख रही थी।</p>\n<p>“किशोरावस्था में सोचती थी,” उसने अचानक कहा, “मेरा पति कैसा होगा।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>“कैसा?”</p>\n<p>“ठहरा हुआ। ऐसा आदमी जो मुझे सच में देखे… सिर्फ मेरे आर-पार नहीं। जैसे शादी की तस्वीरें पुरानी पड़ जाने के बाद अक्सर आदमी अपनी पत्नी को देखना ही भूल जाते हैं।”</p>\n<p>विक्रम कुछ क्षण चुप रहा।</p>\n<p>फिर पूछा, “मिला?”</p>\n<p>कविता के चेहरे पर एक भाव आया और उतनी ही जल्दी चला गया। विक्रम समझ नहीं पाया वह क्या था।</p>\n<p>“नहीं,” उसने सहज स्वर में कहा, “अभी तक तो नहीं।”</p>\n<p>वह मुड़कर चली गई।</p>\n<p>विक्रम वहीं बैठा रहा।</p>\n<p>मुँह में चीनी और इलायची का स्वाद बचा था, और मन में यह साफ़ अहसास कि अभी-अभी कुछ ऐसा कहा गया था जिसमें एक भी अनुचित शब्द नहीं था—</p>\n<p>फिर भी बात उतनी निर्दोष नहीं थी जितनी सुनाई दी थी।</p>\n<p>उस शाम विक्रम घर लौटते हुए मोटरसाइकिल सामान्य से कुछ धीमी चला रहा था।</p>\n<p>वह बार-बार उसी बातचीत को मन में दोहराता और फिर ख़ुद को समझाता कि इसमें सोचने जैसा कुछ है ही नहीं।</p>\n<p>वह एक अच्छे किसान परिवार का लड़का था। एक दिन पिता जिसे ज़मीन, खानदान और घर के योग्य समझेंगे, उससे उसकी शादी हो जाएगी।</p>\n<p>और किसी दूसरे की पत्नी के हाथ की चाय—</p>\n<p>वह कोई ऐसी चीज़ नहीं थी जिसे उसके जैसा आदमी दूसरी बार याद रखे।</p>\n<p>फिर भी उसने याद रखी।</p>\n<p>और इस बात पर उसे अपने आप से हल्की-सी नाराज़गी भी हुई।</p>\n<p>उसके बाद रामफल के घर जाने के कारण जैसे अपने आप बनने लगे।</p>\n<p>विक्रम ख़ुद से कहता, वह उन्हें बनाता नहीं है।</p>\n<p>कभी उसके पिता के लिए कोई संदेश।</p>\n<p>कभी किसी रिश्तेदार की सेना में भर्ती को लेकर सवाल।</p>\n<p>कभी तहसील से लौटते हुए वही लंबा रास्ता, जो संयोग से रामफल के दरवाज़े के सामने से निकलता था—उस समय जब सफ़र के लिए धूप कुछ ज़्यादा होती और चाय के लिए बिल्कुल ठीक।</p>\n<p>हर बार वही आँगन।</p>\n<p>वही पीतल की ट्रे।</p>\n<p>और हर बार चाय रखने के बाद कविता का पहले से कुछ अधिक देर तक ठहर जाना।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस वर्ष रामफल पच्चीस का था, मगर उसमें एक अजीब-सी बासी थकान थी जो उसकी उम्र से कहीं अधिक पुरानी लगती थी।</p>\n<p>कद लगभग कविता जितना ही। शरीर में न अनुशासन का कोई निशान था, न ताकत का। रंग कविता से कुछ गहरा था; धूप ने चेहरे और त्वचा को खुरदरा कर दिया था—हालाँकि उस धूप में उसका अधिकांश समय किसी मेहनत में नहीं बीतता था।</p>\n<p>एक दोपहर विक्रम ने उसे आँगन की दीवार से टिके देखा था। सामने खाने की थाली रखी थी और वह अधनींद में बैठा था। उसकी माँ को दो बार कहना पड़ा कि खाना खा ले।</p>\n<p>रामफल तेज़ समझ वाला आदमी भी नहीं था। बातचीत अक्सर उसके सामने से निकल जाती और वह उसे पकड़ने की कोशिश भी नहीं करता।</p>\n<p>कविता के लिए यह फ़र्क़ धीरे-धीरे साफ़ होता गया।</p>\n<p>एक ओर रामफल था।</p>\n<p>दूसरी ओर विक्रम—इतना लंबा कि आँखों में देखने के लिए कविता को सचमुच ठोड़ी ऊपर करनी पड़ती; शरीर जिसे लापरवाही ने नहीं, अनुशासन ने गढ़ा था; और सबसे बढ़कर एक ऐसा मन, जो उसकी बात सुनकर जवाब देता था। वह तर्क करती तो विक्रम तर्क से मिलता। वह सवाल करती तो उसके सामने कोई दीवार नहीं, एक दूसरा विचार खड़ा होता।</p>\n<p>रामफल ठीक से कोई काम नहीं करता था।</p>\n<p>घर उसके पिता की खेती की आमदनी और रामफल की इधर-उधर की छोटी-मोटी कमाई पर चलता था। मगर उस घर को वास्तव में कौन सँभाल रहा था, यह किसी से छिपा नहीं था।</p>\n<p>कविता—चुपचाप, जैसे ऐसे घरों में अक्सर औरतें करती हैं।</p>\n<p>विक्रम उन चुराए हुए कुछ मिनटों में जितना समझ पाया था, कविता के दिन लगभग एक ही साँचे में ढले रहते—सूरज निकलने से पहले पानी, पशुओं का काम, रसोई; ऐसा ससुर जो उससे अधिकतर तभी बोलता जब कोई काम बताना होता; और ऐसा पति जो दोपहरें या तो सोकर काटता या शराब में।</p>\n<p>कविता ने कभी सीधे शिकायत नहीं की।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>उसके काम करने के ढंग में ही बहुत कुछ लिखा था—हर हरकत नपी-तुली, जैसे उसने सीख लिया हो कि कुछ भी व्यर्थ नहीं करना है।</p>\n<p>न पानी।</p>\n<p>न समय।</p>\n<p>न शब्द।</p>\n<p>क्योंकि उस घर में ऐसा बहुत कम था जिसे वह सचमुच अपना कह सके।</p>\n<p>कुछ महीने बाद की एक दोपहर रामफल दिन में ही शराब पीकर भीतर सो रहा था। यह कोई असामान्य बात नहीं थी। उसका पिता खेतों पर गया हुआ था।</p>\n<p>विक्रम एक काग़ज़ लेकर पहुँचा—ऐसा काग़ज़ जो आसानी से एक सप्ताह और इंतज़ार कर सकता था।</p>\n<p>इस बार कविता उसे आँगन में नहीं, दरवाज़े पर ही मिल गई।</p>\n<p>“वो अंदर है,” उसने कहा। “सो रहा है। अंदर मत जाना।”</p>\n<p>“मैं तो बस—”</p>\n<p>“मुझे पता है तुम क्यों आए हो।”</p>\n<p>कविता रास्ते से नहीं हटी।</p>\n<p>विक्रम ने भी उसे हटने के लिए नहीं कहा।</p>\n<p>कुछ क्षण दोनों वैसे ही खड़े रहे।</p>\n<p>फिर विक्रम ने बहुत धीमे पूछा, “अगर मैं चाय पीने अंदर आऊँ… तो क्या होगा?”</p>\n<p>कविता ने उसकी आँखों में देखा।</p>\n<p>“चाय होगी।”</p>\n<p>वह रुकी।</p>\n<p>“फिर तुम चले जाओगे। जैसे हर बार चले जाते हो। और मैं प्याला धो दूँगी। जैसे हर बार धोती हूँ।”</p>\n<p>एक और ठहराव।</p>\n<p>“हाँ, अगर तुम्हें चाय नहीं पीनी तो अलग बात है।”</p>\n<p>“पीनी है।”</p>\n<p>“तो आओ।”</p>\n<p>आँगन में चाय डालते समय कविता का हाथ पूरी तरह स्थिर नहीं था।</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>चाय ख़त्म हुई। वह उठकर जाने लगा तो कविता पीछे नहीं हटी।</p>\n<p>दोनों के बीच जितनी दूरी होनी चाहिए थी, उससे बहुत कम बची थी—इतनी कि बिना छुए भी विक्रम को उसकी गर्माहट अपने सीने तक पहुँचती महसूस हो रही थी, जैसे बुझते अलाव के पास बैठने पर राख के नीचे दबी आँच चेहरे को छू जाती है।</p>\n<p>एक क्षण के लिए उसका हाथ कविता की कमर के पास तक आया—</p>\n<p>रुका—</p>\n<p>मगर छुआ नहीं।</p>\n<p>कविता ने छोटी-सी तेज़ साँस भीतर खींची, जैसे स्पर्श हो चुका हो।</p>\n<p>“विक्रम…”</p>\n<p>“जानता हूँ।”</p>\n<p>कविता की आवाज़ धीमी थी, मगर उसमें हल्का-सा रोष उतर आया।</p>\n<p>“नहीं। तुम नहीं जानते।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“तुम्हें लगता है कि जानते हो। तुम चले जाते हो, विक्रम। मैं यहीं रह जाती हूँ।”</p>\n<p>उसने उसकी आँखों में देखते हुए कहा—</p>\n<p>“तुम बस इतना जानते हो।”</p>\n<p>विक्रम चला गया।</p>\n<p>दरवाज़े से निकलकर एक बार पीछे मुड़ा।</p>\n<p>और उस क्षण उसने बिना किसी बहाने के अपने भीतर एक सच स्वीकार किया—कोई भला आदमी उसी दोपहर तय कर लेता कि वह फिर कभी इस घर में चाय पीने नहीं आएगा।</p>\n<p>उसे अपने पिता का नाम याद आया।</p>\n<p>गाँव में वर्षों से बनी परिवार की साख याद आई।</p>\n<p>उसने ख़ुद को समझाया कि ये आना-जाना अपने आप बंद हो जाएगा।</p>\n<p>नहीं हुआ।</p>\n<p>कुछ ही समय बाद उसकी छुट्टी समाप्त हो गई और वह वापस अपनी यूनिट चला गया।</p>\n<p>दो महीने बीते।</p>\n<p>घर से माँ का पत्र आया।</p>\n<p>घर-गाँव की सामान्य बातों के बीच एक बात ऐसे ही लिखी हुई थी—रामफल की पत्नी पुलिस में भर्ती हो गई है। कांस्टेबल की ट्रेनिंग करने गई है।</p>\n<p>विक्रम ने वह पंक्ति पढ़ी।</p>\n<p>फिर दोबारा पढ़ी।</p>\n<p>और एक तीसरी बार भी।</p>\n<p>उसके बाद उसने बड़ी दृढ़ता से ख़ुद को समझाया कि कविता क्या कर रही है, कहाँ गई है, किसलिए गई है—</p>\n<p>इनमें से किसी बात से अब उसे कोई फ़र्क़ नहीं पड़ता।</p>\n<p>उस रात उसने पत्र तह करके कमीज़ की जेब में रख लिया।</p>\n<p>सुबह परेड से पहले उसने उसे निकालकर चौथी बार पढ़ा।</p>"}, {"chapter": 3, "title": "अध्याय 2 — एक नई साँस", "content": "<h1>अध्याय 2 — एक नई साँस</h1>\n<p>एक दिन विक्रम के फोन पर एक ग़लत नंबर आया।</p>\n<p>या शायद वह नंबर ग़लत था ही नहीं।</p>\n<p>“हैलो?”</p>\n<p>दूसरी ओर कुछ क्षण की चुप्पी रही।</p>\n<p>“सॉरी… शायद ग़लत नंबर लग गया।”</p>\n<p>“कोई बात नहीं। किससे बात करनी थी?”</p>\n<p>“किसी से नहीं। मतलब… किसी खास से नहीं।”</p>\n<p>विक्रम एक पल चुप रहा। उस आवाज़ को पहचानने में उसे दो साँसें लगीं—उसने उसे पहले एक ही बार इस तरह सुना था: “गरम है।”</p>\n<p>फिर बोला—</p>\n<p>“कविता?”</p>\n<p>उधर की चुप्पी इस बार कुछ लंबी थी।</p>\n<p>“…हाँ। मैं हूँ।”</p>\n<p>कविता की पुलिस ट्रेनिंग का दूसरा महीना चल रहा था, और विक्रम तब श्रीनगर में तैनात था। उसे उस समय यह नहीं मालूम था कि फोन ग़लती से नहीं आया था।</p>\n<p>उस पहली बातचीत की यही साधारणता दोनों के काम आ गई। एक ग़लत नंबर पर हुई बातचीत को कोई नाम देने की ज़रूरत नहीं थी। इसलिए फोन उस जगह भी नहीं कटा जहाँ उसे कट जाना चाहिए था।</p>\n<p>और जब आख़िर में कटा, तो बात वहीं समाप्त नहीं हुई।</p>\n<p>कुछ पीछे रह गया था।</p>\n<p>अगली बार बात करने की एक छोटी-सी वजह।</p>\n<p>फिर दूसरा फोन आया।</p>\n<p>इस बार बहाना थोड़ा कम था।</p>\n<p>“थकी हुई लग रही हो,” विक्रम ने कहा।</p>\n<p>“ट्रेनिंग आदमी की आवाज़ से भी ताकत निकाल लेती है। सुबह पाँच बजे से पहले उठो, फिर तब तक दौड़ो जब तक टाँगें अपनी शिकायत करना बंद न कर दें। ऊपर से एक इंस्ट्रक्टर है जिसे ज़रूरत से थोड़ा ज़्यादा चिल्लाने का शौक है।”</p>\n<p>विक्रम हँसा।</p>\n<p>“अच्छा लगता है वहाँ?”</p>\n<p>कविता ने जवाब देने में अपेक्षा से कुछ अधिक समय लिया।</p>\n<p>“जितना सोचा था, उससे ज़्यादा।”</p>\n<p>फिर धीमे से बोली—</p>\n<p>“यहाँ मैं अपने उस रूप से मिली हूँ जिसे मेरे गाँव में किसी ने कभी देखा ही नहीं। शायद… मुझे वह औरत ज़्यादा पसंद है।”</p>\n<p>उस एक वाक्य में ट्रेनिंग से कहीं अधिक कुछ था।</p>\n<p>विक्रम ने कुरेदा नहीं।</p>\n<p>उसके बाद बातचीत बढ़ती गई।</p>\n<p>ड्रिल कैसी होती है, अनुशासन कितना कठोर है, बैरक की ज़िंदगी कैसी है—विक्रम पूछता और कविता बताती। वह उससे ऐसी बातें भी कहने लगी जो उसने वहाँ अपनी सबसे करीबी सहेली से भी नहीं कही थीं।</p>\n<p>लेकिन वे केवल ट्रेनिंग की बातें नहीं रह गईं।</p>\n<p>कविता उसे उस दुनिया के बारे में बताने लगी जहाँ एक ही बैरक में रहने वाली बहुत-सी औरतें पहली बार अपने लिए कुछ चाहना सीख रही थीं। वहाँ अकेलापन भी था और एक अजीब-सी आज़ादी भी।</p>\n<p>विक्रम सुनता।</p>\n<p>बिना बीच में टोके। बिना हर बात का कोई हल बताए।</p>\n<p>कई बार कविता बोलते-बोलते रुक जाती और दूसरी ओर से विक्रम की आवाज़ नहीं आती। फिर भी उसे मालूम रहता—वह सुन रहा है।</p>\n<p>यही बात उसे और कहने की हिम्मत देती गई।</p>\n<p>उन बातचीतों के बीच विक्रम के सामने कविता का एक ऐसा रूप खुल रहा था जिसे उसने बादशाहपुर के उस आँगन में कभी पूरा नहीं देखा था।</p>\n<p>और कविता भी पहली बार अपने भीतर उस स्त्री को पहचान रही थी, जिसे इतने वर्षों तक किसी ने ठीक से जगह नहीं दी थी।</p>\n<p>लेकिन एक सच दोनों के बीच हर समय मौजूद था।</p>\n<p>विक्रम अविवाहित था।</p>\n<p>कविता नहीं।</p>\n<p>यह बात किसी बातचीत में बार-बार कही नहीं जाती थी।</p>\n<p>कहने की ज़रूरत भी नहीं थी।</p>\n<p>वह हर फोन के पीछे मौजूद रहती थी।</p>\n<p>आगे जो भी होना था, उसकी पहली और सबसे भारी कीमत कविता को ही चुकानी थी।</p>\n<p>विक्रम यह बात समझता था।</p>\n<p>कविता भी।</p>\n<p>फिर भी फोन आते रहे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>करनाल के पास मधुबन की हरियाणा पुलिस अकादमी उस आँगन से बिल्कुल अलग दुनिया थी, जिसे कविता पीछे छोड़ आई थी। यहाँ कंक्रीट की बैरक थी, लोहे के पलंग थे, और हवा में जूतों की पॉलिश और पीतल चमकाने वाली पॉलिश की तीखी गंध बसी रहती थी। भोर से पहले रसोई में बजने वाली चूड़ियों की खनक की जगह अब पाँच बजे की सीटी थी—सीधी, बेरहम, और किसी का इंतज़ार न करने वाली।</p>\n<p>दिन कठिन थे। शाम तक शरीर पत्थर हो जाता और कई रातें वह पलंग पर गिरते ही सो जाती। मगर यह थकान उस पुरानी थकान जैसी नहीं थी, जो घर में बिना नाम के उसकी हड्डियों में जमती रही थी। यह थकान उसकी अपनी थी—जैसे कोई किसान दिन भर अपने ही खेत में हल चलाकर लौटे: पीठ दुखती है, मगर हिसाब अपना है। इसलिए कठिन ट्रेनिंग भी उसे सज़ा जैसी नहीं लगी। बरसों से बंद किसी कोठरी की खिड़की जैसे पहली बार खुली थी, और भीतर हवा की एक पतली धार उतर आई थी।</p>\n<p>आज़ादी उसे किसी बड़ी घोषणा में नहीं मिली।</p>\n<p>वह छोटी-छोटी चीज़ों में आई।</p>\n<p>सुबह आँख खुलने पर यह देखने की ज़रूरत नहीं कि घर में उससे पहले कौन जाग चुका है।</p>\n<p>खाना खाते समय यह हिसाब नहीं कि उससे पहले किसका खाना ज़रूरी है।</p>\n<p>अपने समय के कुछ हिस्सों पर अपना अधिकार।</p>\n<p>अपने शरीर की थकान पर भी अपना अधिकार।</p>\n<p>बहुत छोटी बातें थीं।</p>\n<p>लेकिन कविता के लिए पहली बार छोटी नहीं थीं।</p>\n<p>जो गाँठ बरसों से उसके भीतर चुपचाप बँधी थी, वह धीरे-धीरे ढीली होने लगी।</p>\n<p>कुछ समय बाद उसने आँगन के सपने देखना बंद कर दिया।</p>\n<p>तभी उसे पहली बार एहसास हुआ कि वह इतने समय से सपनों में भी उसी आँगन में लौटती रही थी।</p>\n<p>कविता अपने बैच की सबसे तेज़ लड़की नहीं थी।</p>\n<p>न सबसे ताकतवर।</p>\n<p>लेकिन पहले ही सप्ताह में प्रशिक्षकों ने एक बात पहचान ली थी—उसे कोई आदेश दूसरी बार देने की ज़रूरत नहीं पड़ती थी।</p>\n<p>एक चक्कर और लगाने को कोई न कहे, तो भी वह लगा सकती थी।</p>\n<p>थककर बैठ जाने का कारण मिल जाए, तो भी वह पहले काम पूरा करती थी।</p>\n<p>बादशाहपुर के आँगन में पीतल की ट्रे थामे खड़ी कविता यहाँ हर परेड, हर थकी हुई रात के साथ थोड़ी-थोड़ी पीछे छूटती जा रही थी—जैसे पतझड़ में कोई पेड़ अपने पुराने पत्ते एक-एक करके गिराता है। मगर वह मिट नहीं रही थी। झड़ते पत्तों के नीचे, छाल की किसी दरार में, एक कोंपल जगह बना रही थी—हरी, ढीठ, और अभी इतनी नन्ही कि किसी की नज़र न पड़े। वह दूसरी कविता थी, जो अपने जीवन में पहली बार अपनी ही ओर बढ़ रही थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>नैना की नज़र कविता पर पहले पड़ी थी।</p>\n<p>एक शाम वह बिना पूछे कविता के पलंग के पास आ बैठी।</p>\n<p>“तुम शादीशुदा हो।”</p>\n<p>कविता ने उसकी ओर देखा।</p>\n<p>“मुझे मालूम है।”</p>\n<p>नैना की बात में कटुता नहीं थी। वह बस उन लोगों में से थी जो बात को घुमाकर कहने की मेहनत नहीं करते।</p>\n<p>“बुरा मत मानना। मैं ताना नहीं मार रही। बस… यहाँ ज़्यादातर लड़कियाँ इसलिए हैं क्योंकि उनके पिता चाहते थे कि वे भर्ती हों। तुम ऐसे दौड़ती हो जैसे यहाँ आने का फ़ैसला तुम्हारा अपना था।”</p>\n<p>“मेरा ही था।”</p>\n<p>नैना मुस्कराई।</p>\n<p>“दोनों ही अपने फ़ैसले से यहाँ हैं।”</p>\n<p>उनकी दोस्ती वहीं से शुरू हुई।</p>\n<p>इसके अलावा दोनों में समानता बहुत कम थी।</p>\n<p>नैना ऐसे परिवार से आई थी जहाँ पैसे की इतनी कमी नहीं थी कि नौकरी उसके लिए मजबूरी बनती। ज़ुबान तेज़ थी और धीमे लोगों के लिए धैर्य बहुत कम।</p>\n<p>कविता गाँव से आई थी। नई-नई शादी हुई थी। पैसे भी सोचकर खर्च करती थी और शब्द भी। ज़िंदगी ने उसे मुँह से कहने से ज़्यादा आँखों से कहना सिखाया था।</p>\n<p>नैना वे बातें बिना झिझक कह देती जिन्हें कविता वर्षों से भीतर रोकती आई थी।</p>\n<p>और कविता की स्थिरता ने नैना की बेचैनी को टिकने की एक जगह दे दी।</p>\n<p>इसी फ़र्क़ ने दोनों को एक-दूसरे के करीब ला दिया।</p>\n<p>लगभग एक वर्ष तक दोनों एक ही कमरे में रहीं।</p>\n<p>बीच-बीच में बैरक और पलंगों का फेरबदल हुआ, उन्हें अलग करने की कोशिश भी हुई; आख़िर एक प्रशिक्षक ने हार मान ली और दोनों फिर साथ ही रहने लगीं।</p>\n<p>उनकी शामों की अपनी दिनचर्या बन गई।</p>\n<p>कभी नैना दिन भर में किसी प्रशिक्षक द्वारा किए गए ‘अन्याय’ की लंबी शिकायत करती और कविता चुपचाप अपने जूतों पर तेल लगाते हुए बीच में कोई सूखी-सी बात कह देती।</p>\n<p>नैना उस बात पर ज़रूरत से ज़्यादा हँसती।</p>\n<p>हफ्ते में एक दिन, अगर ट्रेनिंग इजाज़त देती, दोनों कैंटीन में गरम समोसे की एक प्लेट बाँट लेतीं—हालाँकि उन्हें वहाँ खाने की इजाज़त नहीं थी।</p>\n<p>धीरे-धीरे नैना उन बहुत कम लोगों में शामिल हो गई जिनके सामने कविता को हर समय ख़ुद को सँभालकर रखने की ज़रूरत महसूस नहीं होती थी।</p>\n<p>पहली बार उसे ऐसी दोस्ती मिली थी जिसे निभाने के लिए उसे कुछ उठाकर नहीं ले जाना पड़ता था।</p>\n<p>न चाय की ट्रे।</p>\n<p>न किसी रिश्ते का बोझ।</p>\n<p>न अपने मन पर कोई दूसरा चेहरा।</p>\n<p>बस वह ख़ुद।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>एक रात कमरे की बत्ती बुझ चुकी थी।</p>\n<p>दोनों अपने-अपने पलंग पर लेटी थीं।</p>\n<p>उसी अँधेरे में कविता ने पहली बार रामफल के बारे में बात की।</p>\n<p>सब कुछ नहीं।</p>\n<p>बस इतना कि बाकी का अनुमान लगाया जा सके।</p>\n<p>“फोन करता है तो या पैसे चाहिए होते हैं…” कविता छत की ओर देखते हुए बोली, “या फिर बस अपनी साँस सुनाना चाहता है, ताकि मुझे याद रहे कि मैं किसी की हूँ।”</p>\n<p>नैना ने कोई सहानुभूति नहीं जताई।</p>\n<p>“तो फोन मत उठाया करो।”</p>\n<p>“इतना आसान नहीं है।”</p>\n<p>“उतना ही आसान है।”</p>\n<p>कविता उसकी ओर मुड़ी।</p>\n<p>अँधेरे में नैना का चेहरा साफ़ नहीं दिख रहा था।</p>\n<p>“तुम्हें बस पूरी ज़िंदगी यह सिखाया गया है कि आसान नहीं है।”</p>\n<p>कविता ने उस रात उससे बहस नहीं की।</p>\n<p>बहुत देर तक कुछ बोली भी नहीं।</p>\n<p>मगर वह वाक्य उसके भीतर कहीं रह गया।</p>\n<p>कुछ वाक्य सुनते ही सही नहीं लगते।</p>\n<p>फिर भी मन उन्हें फेंक नहीं पाता।</p>\n<p>यह भी वैसा ही था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कुछ समय बाद नैना ने कविता की एक और चुप्पी पकड़ ली।</p>\n<p>जब भी श्रीनगर के आसपास के एक खास इलाके का ज़िक्र होता, कविता के भीतर जैसे अचानक कुछ स्थिर हो जाता।</p>\n<p>उसकी सामान्य बेबाक़ी एक क्षण के लिए गायब हो जाती।</p>\n<p>एक रात नैना ने सीधे कह दिया—</p>\n<p>“कोई है।”</p>\n<p>नैना सवाल नहीं पूछ रही थी। कह रही थी।</p>\n<p>कविता ने इनकार नहीं किया।</p>\n<p>नैना ने उसकी ओर देखा, फिर कंधे उचकाए।</p>\n<p>“ठीक है। अपने राज़ अपने पास रखो।”</p>\n<p>काफी देर बाद कविता बोली—</p>\n<p>“राज़ जैसा कुछ नहीं है। हमारे गाँव का एक लड़का है। आर्मी में है। पिछली बार सुना था श्रीनगर के आसपास पोस्टेड है। बस।”</p>\n<p>“बस।”</p>\n<p>नैना ने वही शब्द दोहराया।</p>\n<p>उसके चेहरे पर साफ़ था कि उसे इस ‘बस’ पर विश्वास नहीं हुआ।</p>\n<p>मगर उसने आगे कुछ नहीं पूछा।</p>\n<p>कविता ने भी कुछ नहीं कहा।</p>\n<p>क्योंकि कुछ रिश्ते उस समय तक रिश्ते बने ही नहीं होते—फिर भी उनके बारे में बोलते हुए डर लगता है कि कहीं नाम दे देने से वे सच न हो जाएँ।</p>\n<p>उस रात कविता ने विक्रम का नाम नहीं बताया।</p>\n<p>बहुत समय तक नहीं बताया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उधर फोन अब नियमित होने लगे थे।</p>\n<p>अब वे केवल बातचीत का ज़रिया नहीं रहे।</p>\n<p>दिन भर की अपनी-अपनी दुनिया के बीच दोनों ने जाने-अनजाने एक-दूसरे के लिए थोड़ी-सी जगह बना ली थी।</p>\n<p>कितनी—यह दोनों जानते थे।</p>\n<p>मानना अभी किसी ने शुरू नहीं किया था।</p>\n<p>कुछ ही हफ्तों में कविता विक्रम की चुप्पियों तक को पहचानने लगी थी।</p>\n<p>कब वह सचमुच चुप है।</p>\n<p>कब मुस्करा रहा है मगर आवाज़ में आने नहीं दे रहा।</p>\n<p>कब उसका सूखा-सा मज़ाक केवल एक वाक्य में छिपा है।</p>\n<p>और उसे यह भी समझ आ गया था कि विक्रम सुनता है।</p>\n<p>फोन करने के लिए बहानों की ज़रूरत ख़त्म हो गई।</p>\n<p>तीसरे सप्ताह तक कविता ने ‘ग़लत नंबर’ का अभिनय भी छोड़ दिया।</p>\n<p>“कल आठ बजे फोन करूँगी,” कविता ने एक दिन कहा।</p>\n<p>“ठीक है।”</p>\n<p>“ठीक है नहीं। फोन उठा लेना।”</p>\n<p>विक्रम हल्का-सा मुस्कराया।</p>\n<p>“उठा लूँगा।”</p>\n<p>“देखना, इंतज़ार मत करवाना… मेजर साहब।”</p>\n<p>विक्रम तब कैप्टन था।</p>\n<p>मेजर बनने में अभी एक पद बाकी था।</p>\n<p>‘मेजर साहब’ की शुरुआत उसी आँगन के दिनों में हुई थी। किसी ने एक बार ग़लती से उसे ग़लत रैंक से पुकार दिया था और कविता को वह संबोधन पसंद आ गया।</p>\n<p>विक्रम ने कभी सुधारा नहीं।</p>\n<p>फिर वह नाम कविता का हो गया।</p>\n<p>उसमें सम्मान से ज़्यादा छेड़ थी—और उस छेड़ के भीतर वह आकर्षण, जिसे दोनों अभी खुलकर कहने से बच रहे थे।</p>\n<p>कविता जब उसे “मेजर साहब” कहती, विक्रम उसे केवल मज़ाक की तरह नहीं सुन पाता था।</p>\n<p>एक रात बात फिर रामफल पर चली गई।</p>\n<p>“आज फिर उसका फोन आया था,” कविता ने कहा। “पैसे चाहिए थे।”</p>\n<p>“कविता…”</p>\n<p>“नहीं।”</p>\n<p>उसने तुरंत रोक दिया।</p>\n<p>“मेरा नाम उस तरह मत लो जैसे तुम्हें मुझ पर तरस आ रहा हो। मैं तुम्हें तरस खाने के लिए फोन नहीं करती।”</p>\n<p>“तो क्यों करती हो?”</p>\n<p>कविता चुप रही।</p>\n<p>जब बोली तो आवाज़ पहले से धीमी थी।</p>\n<p>“क्योंकि इतने समय तक मैं तुम्हारे हाथ में चाय देती रही… और तुम्हारी आँखों से सब कुछ साफ़ था। मैं बस जानना चाहती थी कि आँगन और उस ट्रे के बिना भी तुम्हारी वह ट्रेनिंग टिकती है या नहीं।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>देर तक किसी ने कुछ नहीं कहा।</p>\n<p>फिर विक्रम बोला—</p>\n<p>“नहीं टिकती।”</p>\n<p>कविता की ओर से बहुत हल्की-सी साँस सुनाई दी।</p>\n<p>“यही सुनना था।”</p>\n<p>उसके बाद बात किसी और विषय पर चली गई।</p>\n<p>लेकिन जो कहा गया था, वह वहीं रह गया।</p>\n<p>अब दोनों के बीच केवल पुराना आँगन और चाय की ट्रे नहीं थी।</p>\n<p>उससे आगे कुछ बनने लगा था।</p>\n<p>धीरे।</p>\n<p>बिना नाम के।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उनके बीच की सीमा किसी एक रात नहीं टूटी। वह हर फोन के साथ थोड़ी-थोड़ी पीछे खिसकती गई—जैसे कटाव में नदी का किनारा खिसकता है, बिना आवाज़ किए, और किसी सुबह देखने पर पता चलता है कि पुरानी रेखा कहीं पीछे रह गई।</p>\n<p>बातें लंबी होने लगीं।</p>\n<p>कई बार कहने के लिए कुछ खास नहीं होता, फिर भी फोन नहीं कटता।</p>\n<p>किसी दिन कविता की आवाज़ सुनते ही विक्रम समझ जाता कि दिन अच्छा नहीं गया।</p>\n<p>किसी रात विक्रम सामान्य से कम बोलता तो कविता पूछती नहीं—बस फोन पर बनी रहती।</p>\n<p>और यही वे छोटे क्षण थे जिनमें दोनों एक-दूसरे के जीवन का हिस्सा बनने लगे।</p>\n<p>कुछ और हफ्तों बाद विक्रम के लिए भी इसे सामान्य बातचीत कहना कठिन हो गया।</p>\n<p>एक रात कविता की आवाज़ अचानक पहले से बहुत धीमी हो गई।</p>\n<p>“मैं तुम्हारे बारे में जितना सोचती हूँ… उतना सोचने का मुझे कोई हक नहीं है।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“तुम यह बात सीधे कह सकते हो, विक्रम। मैं नहीं।”</p>\n<p>“क्यों?”</p>\n<p>कविता हल्का-सा हँसी, मगर उस हँसी में खुशी नहीं थी।</p>\n<p>“क्योंकि मैं शादीशुदा हूँ।”</p>\n<p>विक्रम के पास इसका कोई जवाब नहीं था।</p>\n<p>दोनों जानते थे कि यही वह सच था जिससे बाकी सारी बातें छोटी हो जाती थीं।</p>\n<p>कुछ देर बाद उसने कहा—</p>\n<p>“तो मत कहो।”</p>\n<p>लेकिन शब्दों में जितना निषेध था, आवाज़ में उतना नहीं।</p>\n<p>कविता समझ गई।</p>\n<p>“नहीं कहूँगी,” उसने कहा।</p>\n<p>फिर कुछ क्षण बाद—</p>\n<p>“कम-से-कम बाकी हिस्सा तो नहीं।”</p>\n<p>बाकी हिस्सा कहने की ज़रूरत नहीं पड़ी।</p>\n<p>उसके बाद जो चुप्पी आई, वह असहज नहीं थी। वह उस बात से भरी थी जिसे दोनों समझ चुके थे और अभी शब्दों में नहीं रखना चाहते थे—जैसे दो हाथ एक ही प्याला थामे हों, और दोनों जानते हों कि पहले छोड़ना किसी को नहीं है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>महीनों तक वे मिले नहीं।</p>\n<p>फिर भी दूरी ने उस अनकहे को कम नहीं किया।</p>\n<p>कई बार तो फोन कटने के बाद उसकी मौजूदगी और अधिक महसूस होती।</p>\n<p>विक्रम रात को देर तक जागता रहता।</p>\n<p>सोचता—यह सब किस राह की ओर बढ़ रहा है?</p>\n<p>हर पोस्टिंग पर वह अपने परिवार का नाम साथ लेकर चलता था। पिता की प्रतिष्ठा, घर की मर्यादा, गाँव की निगाह—इनमें से कोई चीज़ वर्दी पहन लेने से पीछे नहीं छूटती थी।</p>\n<p>और दूसरी ओर कविता थी।</p>\n<p>एक विवाहित स्त्री।</p>\n<p>जिसकी आवाज़ अब उसके दिन का ऐसा हिस्सा बनने लगी थी जिसे वह चाहकर भी साधारण नहीं मान पा रहा था।</p>\n<p>वह कई बार तय करता—</p>\n<p>अब बस।</p>\n<p>अगला फोन नहीं।</p>\n<p>लेकिन अगली बार फोन बजता और स्क्रीन पर नंबर देखते ही पिछली रात का फ़ैसला उतना मजबूत नहीं रह जाता।</p>\n<p>कुछ सप्ताह बाद कविता ने कहा—</p>\n<p>“मैं गुरुग्राम आ रही हूँ।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“घर जाने से पहले तुमसे मिलना चाहती हूँ।”</p>\n<p>वह जवाब नहीं दे पाया।</p>\n<p>फिर कहा कि छुट्टी नहीं मिल सकती।</p>\n<p>फोन कट गया।</p>\n<p>मगर झूठ वहीं नहीं गया।</p>\n<p>लगभग पूरा दिन वह विक्रम के साथ रहा।</p>\n<p>वह जानता था कि मिलने का अर्थ केवल मिलना नहीं रह गया है।</p>\n<p>उसे अपनी नौकरी और अनुशासन का भी पता था।</p>\n<p>और उससे कहीं ज़्यादा इस बात का कि अगर गाँव तक इस रिश्ते की परछाईं भी पहुँची, तो सबसे पहले उँगली कविता पर उठेगी।</p>\n<p>उसके लिए ख़तरा था।</p>\n<p>कविता के लिए—पूरा जीवन।</p>\n<p>यही बात उसे रोकनी चाहिए थी।</p>\n<p>फिर भी वह ख़ुद को पूरी तरह रोक नहीं पा रहा था।</p>\n<p>उसे पिता याद आए।</p>\n<p>वह नाम याद आया जिसे परिवार की दो पीढ़ियों ने गाँव में बेदाग रखने की कोशिश की थी।</p>\n<p>उसने सोचा—</p>\n<p>वह नहीं जाएगा।</p>\n<p>लेकिन वह फ़ैसला उसने अपने मन से ज़्यादा अपनी समझ को सुनाकर किया था।</p>\n<p>दो दिन बाद कविता ने फिर फोन किया।</p>\n<p>“आओगे?”</p>\n<p>इस बार बीच में कोई लंबी बात नहीं हुई।</p>\n<p>विक्रम चुप रहा।</p>\n<p>और उन्हीं कुछ क्षणों में वह सारी वजहें एक बार फिर उसके भीतर से गुज़रीं जिनके कारण उसे नहीं जाना चाहिए था।</p>\n<p>फिर भी उसने इस बार ख़ुद को कोई तर्क नहीं दिया।</p>\n<p>कोई बहाना नहीं बनाया।</p>\n<p>वह चला गया।</p>"}, {"chapter": 4, "title": "अध्याय 3 — अनकहे से आगे", "content": "<h1>अध्याय 3 — अनकहे से आगे</h1>\n<p>विक्रम एक शाम पहले ही गुरुग्राम पहुँच गया था। पूरे रास्ते उसकी हथेलियाँ नम रहीं। बाइक की सीट से उसकी कमीज़ गीली हो चुकी थी, जबकि हवा ठंडी थी।</p>\n<p>उसका दिमाग लगातार कोई वाक्य बनाने की कोशिश करता—सही शब्द, सही टोन—लेकिन हर बार सोच अधूरी रह जाती थी। वह ख़ुद को समझाता रहा कि यहाँ तक आना ही उसके फ़ैसले का सबूत है।</p>\n<p>लेकिन अगर वह सचमुच इतना तय था, तो उसके साथ रात रुकने भर का सामान क्यों पड़ा था?</p>\n<p>उस रात कविता का फोन आया। सुबह आठ बजे वह मधुबन, करनाल स्थित हरियाणा पुलिस अकादमी से हरियाणा रोडवेज़ की बस पकड़ेगी और करीब ग्यारह बजे गुरुग्राम बस स्टैंड पहुँच जाएगी।</p>\n<p>विक्रम समय से पहले वहाँ मौजूद था। डीज़ल की गंध, गन्ने के रस की मशीन की खड़खड़ाहट, रोडवेज़ बसों के हॉर्न—वह इन सबके बीच एक खंभे से टिका खड़ा रहा।</p>\n<p>कविता के लिए ट्रेनिंग से एक दिन, यहाँ तक कि एक रात बाहर रह जाना बहुत असामान्य नहीं था। उसने घर पर ट्रेनिंग से जुड़े किसी काम का इतना अस्पष्ट-सा कारण बताया था कि आगे ज़्यादा सवाल पूछने की गुंजाइश न रहे।</p>\n<p>फिर भी बस में बैठी कविता पूरे रास्ते अपने फ़ैसले का जोखिम सोचती रही। कोई परिचित देख ले, गाँव का कोई आदमी उसी रास्ते पर मिल जाए, किसी तरह बात घर तक पहुँच जाए—उसके लिए इसकी कीमत विक्रम से कहीं ज़्यादा हो सकती थी।</p>\n<p>लगभग आधा रास्ता बीतने तक वह इन सबके बारे में सोचती रही।</p>\n<p>फिर उसने सोचना छोड़ दिया।</p>\n<p>फ़ैसला तो वह पहले ही कर चुकी थी।</p>\n<p>ग्यारह बजे के आसपास वह बस से उतरी। साधारण सलवार-कमीज़, कोई वर्दी नहीं, कोई ऐसा गहना नहीं जिससे वह अलग पहचानी जाए। तेज़ धूप में भी दुपट्टा आदतन अपने करीब समेटे हुए।</p>\n<p>भीड़ के बीच उसकी नीली-धूसर आँखों ने विक्रम को लगभग उसी क्षण ढूँढ़ लिया।</p>\n<p>और विक्रम ने रास्ते भर जो कुछ कहने की तैयारी की थी, वह सब वहीं ख़त्म हो गया।</p>\n<p>बाइक पर बैठते समय कविता ने सहारे के लिए उसका हाथ पकड़ा। इतने समय में पहली बार उनकी उँगलियाँ इस तरह छुई थीं—त्वचा से त्वचा, बीच में कुछ भी नहीं।</p>\n<p>किसी ने कुछ नहीं कहा।</p>\n<p>उसकी उँगलियाँ बाइक की धातु से ठंडी थीं। विक्रम की नहीं।</p>\n<p>स्पर्श एक पल से भी कम रहा, मगर वह विक्रम के भीतर ऐसे उतरा जैसे किसी ऐसे तार को छू लिया हो जिसे वह बरसों से बेजान समझता आया था—एक झटके में, पूरा।</p>\n<p>होटल स्काईलार्क सेक्टर 14 में था, बस स्टैंड से करीब एक किलोमीटर दूर। लॉबी में अलमारियों पर लगी पीतल की मूर्तियाँ रखी थीं और कोने में एक पुरानी कुर्सी पर सूखे फूलों वाला एक गमला रखा था। जगह में न तो ताज़ेपन का अहंकार था और न ही गिरावट का शर्मसार भाव—बस एक जगह जो वर्षों से अपने मेहमानों की गोपनीयता का सम्मान करती आई थी।</p>\n<p>विक्रम ने इसे सोच-समझकर चुना था। उनके बीच जो कुछ भी होने वाला था, उसके लिए वह ऐसी जगह चाहता था जहाँ चाहे कोई भी आए-जाए, पर उनकी कहानी किसी की कहानी में शामिल न हो।</p>\n<p>रजिस्टर में कविता ने ऐसा नाम लिखा जो पूरी तरह उसका नहीं था। भुगतान नकद हुआ। रिसेप्शन पर दो-चार सामान्य सवाल पूछे गए और फिर दोनों लिफ्ट में थे। धातु के डिब्बे की संकीर्ण जगह में फिनाइल की तीखी गंध थी—हजारों अजनबियों की गंध, जो इन दीवारों में महीनों तक रहती है। उसका कंधा कविता के कंधे से छू रहा था। उस गंध के बीच भी उसे अपनी कमीज़ में पसीना और सड़क की धूल महसूस होती रही। उसने कंधा हटाया नहीं।</p>\n<p>कमरे का दरवाज़ा उनके पीछे हल्की-सी आवाज़ के साथ बंद हुआ।</p>\n<p>पर्दे आधे खिंचे थे और बाहर की रोशनी कालीन पर एक सीधी पट्टी की तरह पड़ी हुई थी। खिड़की के बाहर होटल की दीवार के साथ लगे नीम और अमलतास के पेड़ों से मार्च की हल्की हवा में सूखे पत्ते गिर रहे थे। उनकी सरसराहट सड़क के सामान्य शोर के साथ कमरे तक आ रही थी। एक मौसम, जो चुपचाप ख़ुद को ख़त्म कर रहा था; नई कोंपलें अभी हफ्तों दूर थीं और किसी भी सूनी शाखा पर दिखाई नहीं देती थीं।</p>\n<p>कुछ देर दोनों केवल एक-दूसरे को देखते रहे।</p>\n<p>अब उनके बीच कोई फोन नहीं था, कोई चाय की ट्रे नहीं, कोई आँगन नहीं।</p>\n<p>“मैं इसे ख़त्म करने आया था,” विक्रम ने आख़िर कहा।</p>\n<p>शांत कमरे में उसकी अपनी आवाज़ उसे कुछ अजीब लगी।</p>\n<p>कविता ने उसकी ओर देखा। बाइक से आते हुए उसके बालों की एक लट खुलकर गर्दन के पास आ गई थी और दुपट्टा कंधे से थोड़ा खिसक चुका था।</p>\n<p>“मुझे पता है,” उसने कहा। “फिर भी मैं आ गई।”</p>\n<p>विक्रम उसके पास आया।</p>\n<p>जल्दी में नहीं, मगर अब इतना धीरे भी नहीं कि इसे सावधानी कहा जा सके। उसने कविता को अपने करीब किया और अपना माथा उसके माथे से लगा दिया।</p>\n<p>इतने पास कि दोनों की साँसें एक-दूसरे से मिल रही थीं।</p>\n<p>विक्रम के हाथों में हल्की कंपन थी जब उसने कविता को अपने करीब किया। उसकी साँस को नियंत्रण में रखना पड़ रहा था।</p>\n<p>बरसों उसने ख़ुद को वर्दी, अनुशासन और एक सीधी रेखा में बाँधकर रखा था। उस रेखा के भीतर वह कभी किसी के इतने करीब नहीं आया था कि किसी की साँस अपने चेहरे पर महसूस कर सके।</p>\n<p>और अब कविता उसके सामने थी।</p>\n<p>विक्रम ने उसका चेहरा अपनी हथेलियों में लिया। कविता ने आँखें बंद कर लीं। उनके होंठ मिले—पहले ठहरे हुए, फिर बेसब्र। विक्रम की उँगलियाँ गर्दन के पास खुली लट में उलझ गईं, और कविता ने उसकी कमीज़ का कॉलर मुट्ठी में भींच लिया, जैसे महीनों तक चाय की ट्रे थामे रही मुट्ठी को आख़िर कुछ और मिल गया हो।</p>\n<p>कविता ने बहुत धीमे कहा—</p>\n<p>“दरवाज़ा लॉक कर दो।”</p>\n<p>विक्रम ने दरवाज़ा बंद किया। लॉक की खट के बाद कमरा एकदम चुप हो गया। जब वह उसकी ओर मुड़ा, तब कविता की साँस पहले से तेज़ हो चुकी थी।</p>\n<p>कविता के हाथों में हल्की कंपन थी। उसने इस पल को न जाने कितनी बार अपने मन में देखा था, फिर भी सामने आने पर उसके हाथ उतने निश्चित नहीं थे जितना उसने सोचा था। उसका दुपट्टा कंधों से फिसलकर नीचे गिर गया।</p>\n<p>कुछ क्षण दोनों वैसे ही एक-दूसरे के बहुत करीब खड़े रहे।</p>\n<p>“विक्रम…”</p>\n<p>बस उसका नाम।</p>\n<p>उसके बाद जो कुछ उनके बीच था, उसमें जल्दबाज़ी नहीं रही। चाहत जैसे धीरे-धीरे अपना संकोच छोड़ रही थी।</p>\n<p>कुछ ही देर में कमरे के बाहर की दुनिया जैसे बहुत दूर चली गई।</p>\n<p>न सड़क का शोर सुनाई दे रहा था, न आधी खुली खिड़की से आती सूखे पत्तों की सरसराहट। कमरे की उस गहरी शांति में बस उनकी तेज़ होती साँसें थीं—कभी एक-दूसरे में उलझती हुईं, कभी कुछ पल के लिए थमती हुईं।</p>\n<p>उस ख़ामोशी के बीच कभी-कभी केवल एक नाम सुनाई देता—</p>\n<p>“विक्रम…”</p>\n<p>कविता की आवाज़ बहुत धीमी थी, लगभग साँस में घुली हुई।</p>\n<p>और हर बार अपना नाम उसकी आवाज़ में सुनकर विक्रम उसे थोड़ा और करीब महसूस करता।</p>\n<p>बहुत समय से जो एहसास दोनों के बीच अनकहा ठहरा हुआ था, उस दिन पहली बार उसे किसी शब्द की ज़रूरत नहीं रही।</p>\n<p>बहुत देर बाद कविता का सिर विक्रम की छाती पर था और उसका हाथ उसकी साँसों के साथ धीरे-धीरे उठता-गिरता रहा।</p>\n<p>काफी देर तक दोनों में से किसी ने कुछ नहीं कहा।</p>\n<p>फिर विक्रम ने धीमे स्वर में कहा, “तुम तो आग हो, कविता—पूरी की पूरी आग।”</p>\n<p>कविता हँस पड़ी। कोहनी के सहारे थोड़ा ऊपर उठकर उसने उसकी ओर देखा।</p>\n<p>“आग?”</p>\n<p>उसकी आँखों में हल्की शरारत लौट आई थी।</p>\n<p>“इतने महीनों तक चाय की ट्रे पकड़े रही और आख़िर में ये निकला मुझमें? तुम्हें तो बहुत पहले ही पता चल जाना चाहिए था।”</p>\n<p>शाम की रोशनी धीरे-धीरे सुनहरी होती गई और कुछ समय बाद वे फिर एक-दूसरे के करीब आए—इस बार पहले से अधिक सहज, बिना उस शुरुआती घबराहट के। बाद में दोनों देर तक साथ पड़े रहे और बीच-बीच में ऐसी बातों पर हँसते रहे जिनकी वजह वे किसी को समझा नहीं सकते थे—न किसी पति को, न किसी अदालत को, न बरसों बाद व्हिस्की के गिलास थामे बैठे तीन दोस्तों को।</p>\n<p>कुछ देर बाद कविता शांत हो गई।</p>\n<p>“कब से राह देख रही हूँ कि अपराध-बोध आए,” उसने कहा। “अब तक नहीं आया।”</p>\n<p>विक्रम कुछ क्षण चुप रहा।</p>\n<p>“शायद जो भीतर हमेशा से सच था, उसके लिए अपराध-बोध इतनी जल्दी नहीं आता।”</p>\n<p>कविता ने सिर उठाकर उसकी ओर देखा।</p>\n<p>वही पुरानी नज़र—जो कभी चाय के कप के उस पार से उसे देखा करती थी। फ़र्क़ इतना था कि आज उसमें कुछ अधूरा नहीं था।</p>\n<p>“इतने समय तक मुझे लगता रहा कि शायद मैं तुम्हारी निगाहों का मतलब अपने मन से बना रही हूँ। कई रातें ख़ुद को समझाया कि एक शादीशुदा औरत को वो सब चाहने का हक नहीं जो मैं चाह रही थी।”</p>\n<p>“तुमने कुछ भी अपने मन से नहीं बनाया था।”</p>\n<p>“अब जानती हूँ।”</p>\n<p>उसकी उँगली धीरे से विक्रम की कॉलरबोन पर चली।</p>\n<p>“मुझे नहीं पता इसका आगे क्या होगा, विक्रम। बस इतना पता है कि मुझे यहाँ आने का अफसोस नहीं है।”</p>\n<p>कुछ देर बाद कविता ने धीमे से पूछा—</p>\n<p>“याद है, आँगन में एक दिन मैंने तुमसे कहा था कि किशोरावस्था में सोचती थी मेरा पति कैसा होगा?”</p>\n<p>“याद है।”</p>\n<p>“मैंने कहा था कि वो अभी तक नहीं मिला।” वह कोहनी के सहारे थोड़ा उठी, ताकि उसे ठीक से देख सके। “वो पूरा सच नहीं था।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“जिस दिन मैंने तुम्हें पहली बार सच में देखा—रामफल के यहाँ कभी-कभार आने वाले किसी आदमी की तरह नहीं—उसी पल मेरे भीतर से, बिना चाहे, एक आवाज़ आई: यही है। वही आदमी, जिसकी मैंने कल्पना की थी। मेरे अपने आँगन में खड़ा… बस एक साल देर से।”</p>\n<p>वह धीमे से हँसी, मगर उस हँसी में कुछ भी हल्का नहीं था।</p>\n<p>“मैं चाहती रही, विक्रम। उसी पहली दोपहर से।”</p>\n<p>उसके बाद दोपहर कब शाम में बदल गई, दोनों को ठीक से पता नहीं चला। वे बहुत देर तक बातें करते रहे—कविता के बचपन के बारे में, उसकी उस बहन के बारे में जिससे अब बहुत कम बात होती थी, विक्रम के अकादमी के दिनों के बारे में और उन दूर की पोस्टिंग्स के बारे में जहाँ कभी-कभी ठंड में दोस्ती निभाना तक मेहनत जैसा लगने लगता था।</p>\n<p>शाम को वे होटल के ही रेस्टोरेंट में नीचे खाना खाने गए। लाल मेज़पोश और उजली रोशनी में उनके चेहरे एक-दूसरे के करीब दिख रहे थे। उन्होंने दाल मखनी और तंदूरी रोटी मँगाई। रोटी का एक कौर तोड़कर कविता कटोरी में घुमाती रही, विक्रम ने चम्मच उठाकर रख दिया। दाल ठंडी होकर ऊपर से जम गई और आधे से अधिक वापस चली गई।</p>\n<p>मेज़ के नीचे एक बार उनके हाथ छुए।</p>\n<p>इस बार किसी ने तुरंत हाथ नहीं हटाया।</p>\n<p>बिल आया तो विक्रम के पर्स निकालने से पहले ही कविता भुगतान कर चुकी थी और उसने उसकी कोई दलील नहीं सुनी।</p>\n<p>रात दस बजे के बाद कविता थोड़ी दूर जाकर रामफल को फोन करने लगी। उसकी आवाज़ अचानक सपाट और व्यावहारिक हो गई थी। ट्रेनिंग की अनिश्चित दिनचर्या उसके लिए पहले भी पर्याप्त बहाना बनती रही थी; उसने बस इतना कहा कि वह अगले दिन दोपहर तक घर पहुँच जाएगी।</p>\n<p>रामफल ने ज़्यादा कुछ नहीं पूछा।</p>\n<p>फोन ख़त्म हुआ और कविता वापस कमरे में आ गई।</p>\n<p>दोनों ने उस बातचीत का फिर ज़िक्र नहीं किया।</p>\n<p>अब किसी बस को पकड़ने की जल्दी नहीं थी, न कमरे में कोई घड़ी उनके लिए समय गिन रही थी। आधी रात के बाद कब दोनों एक-दूसरे में उलझे सो गए, पता नहीं चला।</p>\n<p>सुबह शहर का शोर उनसे पहले जाग चुका था।</p>\n<p>अगले दिन कविता फिर बस में थी—रामफल के घर लौटती हुई, उस ज़िंदगी की ओर जिसे इस बात का कोई अंदाज़ा नहीं था कि गुरुग्राम के एक कमरे में क्या बदल चुका है। वापसी का रास्ता उसे आते समय से लंबा लगा, जबकि दूरी वही थी।</p>\n<p>खिड़की के बाहर नीम और अमलतास की सूनी शाखाएँ पीछे छूटती जा रही थीं—आसमान की ओर फैली खाली हथेलियों जैसी। सड़क के किनारे सूखे पत्तों के ढेर हवा के हर झोंके पर करवट बदलते, और मार्च की रोशनी धीरे-धीरे सुनहरी-धूसर होती जा रही थी। छाल की दरारों में अगर कोई कोंपल थी भी, तो इतनी नन्ही कि गुज़रती बस की नज़र उस तक नहीं पहुँच सकती थी।</p>\n<p>कविता ने माथा ठंडे शीशे से लगा लिया।</p>\n<p>उसने फिर अपने भीतर उस अपराध-बोध को ढूँढ़ने की कोशिश की जिसके आने की बात उसने विक्रम से कही थी।</p>\n<p>वह अब भी नहीं था।</p>\n<p>और शाम को उसे उसी घर में वापस जाना था। वही मेज़ लगानी थी। उसी आदमी के पास सोना था, जिसने कभी उससे ऐसा सवाल ही नहीं पूछा था जिसके जवाब में उसे अपने भीतर की कोई सचमुच महत्वपूर्ण बात छिपानी पड़े।</p>\n<p>बस अपने ठिकाने पर पहुँची तो कविता ने उस पूरे दिन को अपने भीतर समेट लिया—जैसे कोई कीमती चीज़ रुमाल में बाँधकर कपड़ों की तह के सबसे नीचे रख देता है। चेहरे पर वही सामान्य भाव लौट आए, और वह ट्रेनिंग के किसी काम से लौटती एक साधारण औरत की तरह नीचे उतर गई।</p>\n<p>लेकिन जो बदल चुका था, उसे दोनों जानते थे।</p>\n<p>अगली सुबह नहाते समय विक्रम ने आईने में अपनी पीठ पर कविता के नाखूनों के पतले अर्धचंद्राकार निशान देखे—हल्के गुलाबी, जो पानी की गर्मी में और उभर आए थे। उसने उन पर उँगली नहीं फेरी; बस देखता रहा, जब तक भाप ने शीशा धुँधला नहीं कर दिया—और उस धुँधलके में उस शाम की सुनहरी रोशनी लौट आई, और उसके ऊपर झुकी कविता।</p>\n<p>दोनों ने दोबारा मिलने की बात उस समय नहीं कही।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>दोनों जानते थे—</p>\n<p>यह आख़िरी बार नहीं था।</p>"}, {"chapter": 5, "title": "अध्याय 4 — चुराए हुए कुछ पल", "content": "<h1>अध्याय 4 — चुराए हुए कुछ पल</h1>\n<p>कुछ दिन बाद विक्रम उसे फिर उसी बस स्टैंड पर लेने पहुँचा। मधुबन की बस पकड़ने के बजाय कविता ने एक शाम पहले फोन करके ख़ुद कहा था कि वह उसे छोड़कर आए।</p>\n<p>“एक बार सड़क को महसूस करना चाहती हूँ,” उसने फोन पर कहा था, “अजनबियों से भरी बस में बैठकर उसे झेलने के बजाय। तुम ख़ुद छोड़कर आओ।”</p>\n<p>विक्रम ने बहस नहीं की।</p>\n<p>मुरथल के पास वे अमरीक सुखदेव ढाबे पर रुके, जहाँ तंदूर का धुआँ उठ रहा था और सड़क पर ट्रकों के हॉर्न लगातार बज रहे थे। कविता ने गर्म पराठे के साथ अचार उठाया; तीखी मिर्च से उसकी आँखों में पानी आया तो वह ख़ुद ही हँस पड़ी, और विक्रम कुछ देर उसे देखता रहा।</p>\n<p>“मुझे ये अच्छा लग रहा है,” आख़िर उसने ढाबे के शोर के बीच कहा। “ऐसी जगह होना जहाँ कोई ये नहीं देख रहा कि मैं कितनी ज़ोर से हँस रही हूँ।”</p>\n<p>“ये तुम्हें मिल सकता है,” विक्रम ने कहा। “सिर्फ आज के लिए नहीं।”</p>\n<p>कविता ने पराठे का कौर तोड़ा और नज़र थाली पर ही रखी।</p>\n<p>“मत कहो। आज नहीं। आज मुझे बस ये पराठा चाहिए, ये सड़क, और सामने बैठे तुम—ये जताते हुए कि तुमने अभी-अभी ख़ुद को ये कहते नहीं सुना।”</p>\n<p>विक्रम ने बात वहीं छोड़ दी।</p>\n<p>दोनों फिर निकल पड़े।</p>\n<p>कुछ दूर आगे सड़क के दोनों ओर सफेदे के लंबे पेड़ हरे खड़े थे—सदाबहार, पतझड़ से बेअसर—जबकि बाकी पेड़ों के पत्ते झड़ चुके थे और उनकी नंगी शाखाएँ आसमान की ओर उठी थीं। हवा अब हल्की हो चली थी। बाइक के पीछे बैठी कविता ने अचानक एक हाथ विक्रम की कमर से हटाया और खुली हवा में फैला दिया।</p>\n<p>उसने सिर थोड़ा पीछे किया और हँस पड़ी।</p>\n<p>वह हँसी किसी बात पर नहीं थी।</p>\n<p>बस उस क्षण पर थी।</p>\n<p>बरसों उसने आवाज़ धीमी और हाथ अपनी जगह पर रखे थे। आज उसकी खुली हथेली से हवा बहती जा रही थी, जैसे बरसों से मुट्ठी में भींचा कोई पानी आख़िर रास्ता पा गया हो।</p>\n<p>जब उसने हाथ वापस खींचा तो इस बार केवल सहारे के लिए विक्रम को नहीं पकड़ा, बल्कि दोनों बाँहें उसके चारों ओर लपेटकर अपना चेहरा उसकी पीठ से लगा लिया।</p>\n<p>बाकी रास्ते वह वैसे ही बैठी रही।</p>\n<p>“अगली छुट्टी में फिर यही सड़क?” उसने हल्के से पूछा। फिर उसकी दोनों बाँहें विक्रम के चारों ओर और भी मज़बूती से लपट गईं।</p>\n<p>“यही सड़क,” उसने कहा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस रास्ते के बाद उन्हें फिर ऐसा मौका मिलने में कई महीने लग गए।</p>\n<p>अगली छुट्टी पर विक्रम घर आया तो कविता ने फोन पर बताया कि रामफल तीन दिनों के लिए पानीपत जा रहा है। कई महीनों में पहली बार वह उस घर में अकेली होगी।</p>\n<p>दूसरी रात विक्रम मोटरसाइकिल लेकर नहीं गया। घरों की खिड़कियों से बचता हुआ वह खेतों का लंबा रास्ता पैदल पार करता गया—अँधेरे में मेड़ों पर पाँव जमाते हुए, सूखी मिट्टी की हल्की चरमराहट के बीच, और दूर किसी कुत्ते के भौंकते ही पूरा-का-पूरा रुककर। श्रीनगर के ख़तरे वाले इलाकों में ऑपरेशनों के दौरान भी उसका दिल इतनी तेज़ नहीं धड़का था।</p>\n<p>कविता पूरे दिन उसका इंतज़ार करती रही थी।</p>\n<p>कई बार बिना किसी वजह के चेहरे पर मुस्कान आ जाती और वह होंठ दबाकर उसे लौटा देती। उसने चादर दो बार बदली और हर बार साँकल को जाकर देखा।</p>\n<p>रात को विक्रम दरवाज़े तक पहुँचा तो दस्तक देने की ज़रूरत नहीं पड़ी।</p>\n<p>कविता ने पहले ही दरवाज़ा खोल दिया।</p>\n<p>“पैदल आए हो?”</p>\n<p>“बाइक की आवाज़ से आधी गली जाग जाती।”</p>\n<p>“पूरी गली जाग जाती। अंदर आओ, इससे पहले कि किसी का कुत्ता तुम्हें यहाँ खड़ा देख ले।”</p>\n<p>कविता उसे तुरंत भीतर ले गई।</p>\n<p>घर के पिछले हिस्से का छोटा कमरा शादी के बाद धीरे-धीरे केवल उसका रह गया था।</p>\n<p>“सूरज निकलने से पहले तक,” कविता ने उसका हाथ थामते हुए कहा—दरवाज़े से भीतर आने के बाद पहली बार उसने उसे छुआ था। “तब तक पूरी रात हमारी है। यहाँ, मेरी अपनी दीवारों के बीच। मैं जानना चाहती हूँ कि ये कैसा लगता है।”</p>\n<p>उसने हथेली विक्रम के चेहरे पर रखी। “गुरुग्राम के बाद हर रात, विक्रम। इसी घर में। कई रातें वो मुझसे तीन फुट दूर सोया होता था… और मैं तुम्हें याद करती थी।”</p>\n<p>फिर वे एक-दूसरे के करीब आए।</p>\n<p>लेकिन बाद में, जब कविता उसके सीने पर सिर रखकर सो गई और नींद में भी उसका हाथ विक्रम के हाथ पर ढीला-सा टिका रहा, तो विक्रम बहुत देर तक जागता रहा।</p>\n<p>उसकी बाँह कंधे के नीचे सुन्न हो चली थी, पर उसने उसे हिलाया नहीं। कविता की साँस एक लय में चल रही थी—जैसे कुछ घंटों के लिए उसे किसी चीज़ की रखवाली नहीं करनी हो।</p>\n<p>सुबह आसमान में हल्की सफ़ेदी उतरनी शुरू हुई तो विक्रम ने ख़ुद उसे जगाया।</p>\n<p>दरवाज़े तक पहुँचकर कविता ने उसकी बाँह पकड़ ली।</p>\n<p>“शुक्रिया,” उसने कहा। आवाज़ पहले से कहीं धीमी थी। “पूरी रात रुकने के लिए। यहाँ—किसी ऐसी जगह नहीं, जिसके पैसे देने पड़ें और सुबह होते ही छोड़नी पड़े।”</p>\n<p>वह एक पल रुकी।</p>\n<p>“इस शादी की हर सुबह मैंने ऐसे आदमी के पास आँख खोली है, जो करवट बदल चुका होता है या जा चुका होता है। आज कोई रुका था।”</p>\n<p>विक्रम ने उसके माथे को चूमा और निकल गया।</p>\n<p>अगली मुलाक़ात की कोई तारीख़ तय नहीं हुई।</p>\n<p>कविता दरवाज़े पर तब तक खड़ी रही, जब तक विक्रम के कदमों की आहट पहले गली के मोड़ पर, फिर खेतों की धुंध में, फिर सुबह की पहली चिड़ियों की आवाज़ों में घुलकर खो नहीं गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>चार महीने बाद विक्रम 23 राष्ट्रीय राइफल्स से दस दिनों की छुट्टी लेकर लौटा।</p>\n<p>छुट्टी के दो दिन ही बीते थे कि कविता का फोन आया।</p>\n<p>“इस बार मैं रामफल के यहाँ नहीं जा रही,” उसने बिना किसी भूमिका के कहा। “घर पर कह दिया है कि आराम चाहिए। माँ के यहाँ हूँ, कोसली में। मिलना है तो यहीं मिलना होगा।”</p>\n<p>सर्दियों की सुबह थी। खेत सरसों के पीले फूलों से लदे थे और घना कोहरा नौ बजे के बाद भी ज़मीन छोड़ने को राज़ी नहीं था—जैसे रात जाते-जाते खेतों पर अपनी सफ़ेद चादर भूल गई हो। हवा में सरसों की तीखी-कड़वी गंध घुली थी, जो हर बार भीतर खिंचने पर जीभ पर आकर टिक जाती थी।</p>\n<p>कविता उसे खेतों के बीच उस जगह ले गई जहाँ सरसों का छोटा-सा जंगल इतना ऊँचा और घना था कि भीतर बैठा आदमी बाहर से दिखता ही नहीं था—पीली लहरों के बीच एक छिपा हुआ घेरा, जहाँ दुनिया की नज़र पहुँचने से पहले ही ठहर जाती थी।</p>\n<p>“बचपन में यहीं छिपकर बैठा करती थी,” उसने कहा, “जब भी कोई घंटा चाहिए होता था, जो सिर्फ मेरा हो।”</p>\n<p>कविता ने शॉल का आधा हिस्सा गीली मिट्टी पर बिछाया, आधा दोनों के कंधों पर डाल दिया, और सरककर विक्रम को भीतर अपनी जगह पर बिठा लिया। पौधों की पत्तियों से ओस उसके बालों पर टपक रही थी।</p>\n<p>“कोई ऐसी बात बताओ जो तुमने कभी किसी से नहीं कही,” उसने अचानक कहा।</p>\n<p>विक्रम कुछ देर सोचता रहा।</p>\n<p>“लगता था कश्मीर में मेरे भीतर कुछ मर जाएगा। मरा नहीं। बस जो पहले से सख़्त था, उसे और सख़्त कर दिया।”</p>\n<p>कविता कुछ देर चुप रही।</p>\n<p>“मुझे भी लगता था तुम्हारे गाँव में मेरे भीतर कुछ मर जाएगा,” आख़िर उसने कहा। “वो इंतज़ार। ट्रे पर एक पल ज़्यादा ठहरा हाथ। एक नज़र, जिसे मैंने कभी ज़ुबान तक नहीं आने दिया।”</p>\n<p>वह उसकी ओर पूरी तरह मुड़ी।</p>\n<p>“मारा नहीं। बस उसे सब्र सिखा दिया।”</p>\n<p>विक्रम ने उसका हाथ अपने हाथ में ले लिया और कविता ने अपनी ठंडी उँगलियाँ उसके जबड़े पर रख दीं।</p>\n<p>“चार महीने,” उसने धीमे से कहा। “ये सब भीतर अधूरा लिए मैं उस घर में वापस नहीं जाऊँगी।”</p>\n<p>सरसों के ऊँचे पौधों के बीच वे एक-दूसरे के करीब आए और बाद में बहुत देर तक वहीं बैठे रहे, कविता का सिर विक्रम के कंधे पर था और उनके चारों ओर पीले फूलों के बीच सर्द सुबह धीरे-धीरे खुल रही थी।</p>\n<p>दूर खेतों में लोगों की आवाज़ें सुनाई देने लगीं। कविता ने शॉल झाड़कर कंधों पर डाली; विक्रम ने उसके बालों से सरसों की एक पंखुड़ी हटाई।</p>\n<p>वे अलग-अलग दिशाओं में निकल गए।</p>\n<p>धूप चढ़ी तो पीले फूलों के बीच एक जगह दबी रह गई—गीली मिट्टी पर शॉल की सिलवटें, कुचले हुए कुछ डंठल। बाकी जंगल धीरे-धीरे अपनी पीठ सीधी करता गया, मगर वह घेरा खेत में उनका अकेला सबूत बनकर वहीं पड़ा रहा।</p>"}, {"chapter": 6, "title": "अध्याय 5 — आख़िरी बार—और उसे पता भी नहीं था", "content": "<h1>अध्याय 5 — आख़िरी बार—और उसे पता भी नहीं था</h1>\n<p>तब तक दो साल बीत चुके थे, हालाँकि दोनों ने कभी बैठकर उन दो वर्षों का हिसाब नहीं लगाया था। उनकी यादों में समय तारीखों से नहीं, कुछ छोटी-छोटी चीज़ों से दर्ज था—जैसे लंबे सफ़र में रास्ता मील के पत्थरों से नहीं, कुछ मोड़ों से याद रहता है: चाय की वह ट्रे जो हाथों में एक पल ज़्यादा ठहर जाती थी, सफेदों की कतार के बीच से गुज़रती वह सड़क, कविता के अपने कमरे की वह रात, और सरसों के खेत में चुराए कुछ घंटे। मुलाक़ातों के बीच लंबे इंतज़ार थे, और मिला हुआ समय इस तरह बचाकर रखा जाता था, जैसे सूखे के दिनों में घड़े का आख़िरी पानी।</p>\n<p>इस बार कहीं दूर जाने की बात कविता ने ही उठाई थी। बहुत समय बाद विक्रम की छुट्टियाँ और कविता की जमा छुट्टियाँ एक साथ पड़ रही थीं। वह कुछ दिन ऐसी जगह रहना चाहती थी जहाँ साथ चलते हुए उन्हें बार-बार पीछे मुड़कर न देखना पड़े।</p>\n<p>विक्रम ने गाड़ी ख़ुद चलाई। मुख्य सड़क उस साल इतनी ख़राब थी कि उसने मुरादाबाद बाइपास से होते हुए काशीपुर, बाजपुर और कालाढूंगी वाला लंबा रास्ता चुना। मैदान धीरे-धीरे पीछे छूटते गए और सड़क जंगलों के बीच चढ़ने लगी। ऊँचाई बढ़ने के साथ हवा भी बदलती गई; मैदानों की भारी गर्मी कम होती गई और चीड़ की हल्की गंध आने लगी। रास्ते में उन्होंने दो बार सड़क किनारे चाय के लिए गाड़ी रोकी।</p>\n<p>नैनीताल आख़िरी मोड़ के बाद अचानक सामने आया—जैसे पहाड़ों ने अपनी ओट एकाएक हटा ली हो। नीचे झील थी, चारों ओर चीड़ से ढकी ढलानें, और मैदानों से बिल्कुल अलग ठंडी हवा, जिसमें कहीं दूर जलती लकड़ी के धुएँ की हल्की गंध घुली थी।</p>\n<p>उन्होंने मॉल रोड के पास द पवेलियन में कमरा लिया। होटल साधारण था, मगर झील इतनी पास थी कि सुबह कमरे तक पानी और पक्षियों की आवाज़ पहुँचती थी।</p>\n<p>दो दिन उनके पास कोई योजना नहीं थी। झील के किनारे चलते रहे, छोटे रेस्तराँ में खाते रहे, ठंडी हवा में गरम मोमोज बाँटकर खाए और शाम को कमरे की छोटी बालकनी में एक ही कंबल में बैठे रहे। ठंड कम हो जाने के बाद भी कविता के हाथ विक्रम की जैकेट के भीतर ही रहते।</p>\n<p>दूसरी शाम कविता ने धीमे से, लगभग सँभलकर, विक्रम से नीचे के छोटे बार से ड्रिंक्स मँगवाने को कहा—ग्रीन एप्पल वोडका, दो बड़े गिलास उसके लिए और दो विक्रम के लिए। मेन्यू में बस यही एक चीज़ थी जो उसे चेतावनी कम और फल ज़्यादा लगी थी। कमरे के लिए नहीं, उसने कहा, बालकनी के लिए—जहाँ किसी अजनबी की छत के बजाय झील उन्हें देख सके।</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“तुम तो पीती नहीं हो।”</p>\n<p>“नहीं पीती,” उसने माना। “कभी नहीं पी। न किसी शादी में, न अकेले, न जिज्ञासा में, न दुख में… हालाँकि दुख ने कई बार कहा।”</p>\n<p>वह विक्रम की बजाय झील की ओर देख रही थी। ढलती रोशनी में पानी सीसे-सा धूसर हो चला था—ठीक उसकी अपनी आँखों के उस रंग जैसा, जो कभी शीशे की तरह साफ़ रहता है और कभी बादल की तरह भारी।</p>\n<p>“अपने घर में सारी ज़िंदगी देखा है कि ये आदमियों के साथ क्या करती है। बहुत छोटी उम्र में ख़ुद से कह दिया था कि मेरे भीतर जो कुछ बचाने लायक बचा है, उसके पास इसे फटकने नहीं दूँगी।”</p>\n<p>एक पल के लिए उसके चेहरे पर कोई पुरानी, दबी हुई कड़वाहट उभरी।</p>\n<p>“फिर कहीं रास्ते में मैं ख़ुद से एक दूसरा सवाल पूछने लगी। अगर रामफल हर शाम उस पैसे से बेसुध हो सकता है, जो उतना ही मेरा भी था, तो मैंने पूरी शादी में अपने हिस्से की एक शाम तक ख़ुद से क्यों छीन रखी है? आज रात मैंने तय कर लिया है कि इस सवाल को जवाब की ज़रूरत नहीं।”</p>\n<p>फिर वह उसकी ओर मुड़ी।</p>\n<p>“आज मुझे तुमसे कुछ कहना है, और होश में रहकर शायद कह नहीं पाऊँगी। इसलिए ये।”</p>\n<p>विक्रम ने आगे कुछ नहीं पूछा। वह नीचे गया और दो चक्करों में चार गिलास लेकर लौट आया। वोडका का हल्का हरा रंग ढलती रोशनी को वैसे ही पकड़ रहा था, जैसे झील पकड़ रही थी—सुनहरा, धीरे-धीरे धूसर होता हुआ।</p>\n<p>कविता ने पहला घूँट बहुत धीरे लिया, जैसे कोई अनजान पानी में उतरने से पहले एक पैर से उसे परखता है। हल्की खाँसी आई, जिसे उसने हँसी में छिपाने की कोशिश की; आँखें एक पल को भर आईं। दूसरा घूँट पहले से सहज था, तीसरा उससे भी।</p>\n<p>विक्रम का हाथ अपने गिलास की ओर बढ़ा और बीच में ही रुक गया। वह बिना कुछ कहे उसे देखता रहा।</p>\n<p>पहला गिलास ख़त्म होने और दूसरे का आधा रह जाने तक उसके कंधे ढीले पड़ चुके थे। उसने अपनी ठंडी उँगलियाँ एक पल अपने तपते गाल पर रखीं, जैसे जाँच रही हो कि यह गर्माहट सचमुच उसकी है।</p>\n<p>“बस,” उसने कहा—धीमे, थोड़े लड़खड़ाते स्वर में—और गिलास मेज़ पर रख दिया।</p>\n<p>उस रात दोनों फिर एक-दूसरे के करीब आए। बाहर पहाड़ों की ठंड खिड़की से लगी थी और कमरे के भीतर उनके पास कुछ समय के लिए केवल एक-दूसरे की गर्माहट थी। बाद में कविता बहुत देर तक विक्रम के सीने पर सिर रखे चुप रही, उसकी उँगलियाँ अनजाने में उसकी त्वचा पर छोटे-छोटे निशान बनाती रहीं।</p>\n<p>“अब ठीक से कह सकती हूँ,” आख़िर उसने कहा। उसकी आवाज़ उससे छोटी थी, जितनी विक्रम सुनने का आदी था। “यह कहना मेरे लिए मुश्किल है, विक्रम। मैं चाहती हूँ तुम पूरी बात सुनो—सिर्फ वह हिस्सा नहीं जो सुनने में आसान है।”</p>\n<p>“सुन रहा हूँ।”</p>\n<p>“मैं तुम्हें छोड़ नहीं रही। यह बात सबसे पहले साफ़ रहे। ज़िंदगी हम जैसे दो लोगों को जिस भी रूप में साथ रहने देगी, उस रूप में मैं हमेशा तुम्हारे साथ रहूँगी।”</p>\n<p>वह एक पल चुप रही।</p>\n<p>“लेकिन अब तुम्हें आगे बढ़ना होगा। सच में। तुम्हारी शादी का वक्त आ गया है—और यह मैं तुम्हें दूर करने के लिए नहीं, तुम्हारी फ़िक्र में कह रही हूँ।”</p>\n<p>“जब तक तुम सच में इससे आगे नहीं निकल जाते, मैं यहीं हूँ। यह भी जान लो। मेरे लिए भी आसान नहीं है यह सोचना कि किसी दिन तुम्हारे पास कोई खुशी या कोई परेशानी होगी, और तुम मुझे सबसे पहले फोन नहीं करोगे। लेकिन मैं तुम्हारे साथ यह करती नहीं रह सकती। यह तुम्हारे साथ ठीक नहीं है, विक्रम।”</p>\n<p>“कविता—”</p>\n<p>“हम दोनों पहले से जानते हैं कि इसका कोई भविष्य नहीं। हम दो साल में सत्रह बार मिले हैं। मैंने हर मुलाक़ात गिनी है, विक्रम—उन्हें भी, जिन्हें हम दोनों ने किसी कैलेंडर पर नहीं लिखा। बस कभी इन शब्दों में कहा नहीं।”</p>\n<p>उसने सिर उठाकर उसे ठीक से देखा। कम रोशनी में उसकी आँखें चमक रही थीं—उनमें कुछ था जो न पूरी तरह आँसू थे, न उनकी ग़ैरमौजूदगी।</p>\n<p>“एक बात और, फिर चुप हो जाऊँगी। बाकी सब बदल जाए तो बदल जाए—मैं हमेशा तुम्हारी दोस्त रहूँगी। इस हिस्से पर कोई सौदा नहीं होगा, चाहे यह बातचीत हम दोनों से कुछ भी ले ले।”</p>\n<p>विक्रम बहुत देर चुप रहा। सीने में कसाव-सा उठा था, जिसका पहाड़ की ठंड से कोई लेना-देना नहीं था। उसका जबड़ा कसा, उसने मुँह खोला—और बिना कुछ कहे बंद कर लिया।</p>\n<p>“तुम सही हो,” आख़िर विक्रम ने कहा। आवाज़ जितनी चाही थी, उससे ज़्यादा खुरदरी निकली। “मैं भी जानता था। गुरुग्राम से ही… बस कभी इसे सामने रखकर सोचने की हिम्मत नहीं की।”</p>\n<p>“जान लेने से कहना आसान नहीं हो जाता,” कविता ने धीमे से कहा।</p>\n<p>“नहीं,” विक्रम ने माना। “नहीं होता।”</p>\n<p>उसने कविता को और करीब खींच लिया।</p>\n<p>“कहने के लिए शुक्रिया,” उसने उसके बालों में कहा। “मैं कभी नहीं कह पाता।”</p>\n<p>कविता उसके सीने से लगी हल्का-सा मुस्कराई; उसकी पलकों के कोने गीले थे।</p>\n<p>“किसी को तो कहना था। मैं चाहती थी कि यह बात मैं प्यार से कहूँ, इससे पहले कि ज़िंदगी इसे बेरहमी से कहे।”</p>\n<p>उसके बाद विक्रम बहुत देर तक उसे थामे रहा। खिड़की के बाहर झील पर कोहरा उतरता रहा—पहले दूर की रोशनियाँ मिटीं, फिर किनारा, फिर पानी; आख़िर में शीशे पर बस उन दोनों की परछाइयाँ बची रहीं।</p>\n<p>अगली सुबह झील पर हल्का कोहरा अब भी ठहरा हुआ था और दोनों होटल की छोटी मेज़ पर पराठे और दही के साथ नाश्ता कर रहे थे, जब कविता ने बिना पूछे विक्रम का फोन उठा लिया।</p>\n<p>उसने उसमें एक नंबर सेव किया और फोन वापस उसकी ओर सरका दिया।</p>\n<p>“मेरे साथ ट्रेनिंग की थी,” उसने कहा। “नैना। गुरुग्राम की है, अब घर के पास ही पोस्टेड है। तेज़ ज़ुबान वाली, थोड़ी अकेली भी।”</p>\n<p>कविता एक पल विक्रम की आँखों में कुछ खोजती रही।</p>\n<p>“तुम्हें कोई ऐसी चाहिए, जिसे तुमसे प्यार करने की कीमत हर बार अपनी बाकी पूरी ज़िंदगी से तौलनी न पड़े।”</p>\n<p>“कविता—”</p>\n<p>“इसे जितना है, उससे बड़ा मत बनाओ,” कविता ने कहा, और इस बार उसकी नज़र दही की कटोरी पर चली गई। “मैं बस तुम्हारे सामने एक दरवाज़ा रख रही हूँ।”</p>\n<p>विक्रम ने फोन में सेव हुआ नाम देखा, फिर कविता को।</p>\n<p>“तो अब मेरी होने वाली पत्नी भी तुम ही ढूँढ़ोगी? कोई ऐसी चीज़ बची भी है, कविता, जिसे सँभालने का ज़िम्मा तुम ख़ुद पर न ले लो?”</p>\n<p>कविता हँस पड़ी।</p>\n<p>“किसी को तो करना पड़ेगा। तुम्हें अपने भरोसे छोड़ दूँ, तो तुम्हारे फ़ैसले कभी अच्छे नहीं निकलते।”</p>\n<p>उस सुबह विक्रम को अंदाज़ा नहीं था कि वह दरवाज़ा असल में कितना बड़ा था।</p>"}, {"chapter": 7, "title": "अंतराल — फाइल का पहला पन्ना", "content": "<h1>अंतराल — फाइल का पहला पन्ना</h1>\n<p><i>बरसों बाद, जिस दिन विक्रम का नाम पहली बार किसी खास मेज़ से गुज़रा, एक फाइल चुपचाप खोली गई। उसमें पन्ने गिने-चुने थे, पर सारे बहुत ध्यान से लिखे हुए।</i></p>\n<p>पहला पन्ना एक नाम से शुरू होता था: <i>कविता।</i></p>\n<p>मोटे तौर पर दो साल—हालाँकि फाइल की भाषा बहुत सधी हुई थी, जैसे लिखने वाले को पता था कि कौन-से शब्द छोड़ देने हैं। रिश्ता बिना किसी शोर के ख़त्म हुआ था: कोई शिकायत नहीं, कोई गवाह नहीं, कोई ऐसी बात नहीं जो किसी असरदार आदमी के कानों तक पहुँचती।</p>\n<p>पन्ने के आख़िर में एक पंक्ति बाकी सब से अलग थी। आख़िरी मुलाक़ात की सुबह वही औरत विक्रम को किसी बिल्कुल दूसरी लड़की का फोन नंबर थमा गई थी।</p>\n<p>उस पंक्ति के नीचे दो बार रेखा खिंची थी।</p>\n<p>फाइल अपडेट रखने का ज़िम्मा जिस अफसर के पास था, वह देर तक उस रेखा को देखता रहा। फिर उसने हाशिये पर बस तीन शब्द लिखे, फाइल बंद की और उसे वापस दराज़ में सरका दिया।</p>\n<p><i>दिलचस्प। नज़र रखो।</i></p>"}, {"chapter": 8, "title": "अध्याय 6 — सूनी शामें", "content": "<h1>अध्याय 6 — सूनी शामें</h1>\n<p>नैना का नंबर विक्रम के फोन में कई महीनों तक वैसे ही पड़ा रहा।</p>\n<p>कविता पूछती तो विक्रम कोई सोची-समझी वजह गिना देता। सच यह था कि जब भी उसका अँगूठा उस नंबर तक पहुँचता, वह स्क्रीन बंद कर देता।</p>\n<p>उधर कविता से उसकी बातचीत भी धीरे-धीरे कम होने लगी थी।</p>\n<p>उनके बीच कोई झगड़ा नहीं हुआ था। कभी विक्रम फोन करता तो घंटी बजती रहती और कविता उठाती ही नहीं; कभी उठाती भी तो कुछ देर बाद ड्यूटी या किसी दूसरे काम का कहकर फोन रख देती।</p>\n<p>विक्रम को उस समय यह नहीं मालूम था कि कविता की कुछ शामों में अब कोई और भी शामिल होने लगा था।</p>\n<p>उसका नाम कमल था।</p>\n<p>कविता की ही पोस्टिंग पर तैनात एक कांस्टेबल।</p>\n<p>शुरुआत वैसे ही हुई, जैसे कविता के साथ ऐसी चीज़ें अक्सर शुरू होती थीं—चाय से। एक ठंडी रात कविता चाय का एक अतिरिक्त फ्लास्क लेकर बाहर की पोस्ट तक चली गई, जहाँ कमल की ड्यूटी थी। दूर से कमल कई घंटों से अकेला खड़ा दिख रहा था, साँस की भाप उसके सामने उठती हुई; किसी ने उससे यह तक नहीं पूछा होगा कि उसे चाय चाहिए या नहीं।</p>\n<p>कमल ने दोनों हाथों से कप लिया।</p>\n<p>“इतनी दूर आने की ज़रूरत नहीं थी।”</p>\n<p>कविता ने कंधे उचकाए। “कोई और आने वाला भी नहीं था।”</p>\n<p>वह लौटने लगी तो कमल बोला, “एक मिनट रुक जाओ। कोई बात करने वाला न हो, तो ये ड्यूटी बहुत लंबी लगती है।”</p>\n<p>कविता रुक गई।</p>\n<p>उस पहली रात उनकी बातचीत में ऐसा कुछ नहीं था जिसे बाद में याद करके कोई शुरुआत कहा जा सके। वे बस कुछ देर ठंड से कसे, तारों से चमकते आसमान के नीचे खड़े बातें करते रहे और फिर कविता बैरक की ओर लौट चली। कमल भी कविता के साथ हो लिया।</p>\n<p>सीधा रास्ता छोटा था, मगर दोनों पुराने बरगद की तरफ से घूमकर गए।</p>\n<p>पाँच मिनट ज़्यादा लगे।</p>\n<p>अगली बार भी वे उसी रास्ते से लौटे।</p>\n<p>फिर धीरे-धीरे वही उनका रास्ता बन गया।</p>\n<p>ड्यूटी साथ पड़ती तो कमल कविता को वापस छोड़ने आता और रास्ते भर छोटी-छोटी बातें पूछता रहता। उसके सवालों में कोई जल्दबाज़ी नहीं होती थी।</p>\n<p>बहुत पहले आँगन में चाय के प्याले के उस पार से विक्रम भी कविता से इसी तरह बातें किया करता था—तब, जब दोनों के बीच जो बन रहा था, उसका कोई नाम नहीं था।</p>\n<p>एक शाम कमल ने चलते-चलते कहा, “तुम कभी-कभी एकदम चुप हो जाती हो। जैसे कुछ ऐसा साथ लेकर चल रही हो जिसे कहीं रख नहीं सकती।”</p>\n<p>“इस वर्दी में हर कोई कुछ न कुछ लेकर चलता है।”</p>\n<p>“तुम्हारा अलग है।”</p>\n<p>कमल ने इसके आगे कुछ नहीं पूछा।</p>\n<p>इसी वजह से वह बात कविता के भीतर कुछ देर और ठहरी रही।</p>\n<p>कविता ने ख़ुद को समझाया कि इसमें कुछ नहीं है। साथ ड्यूटी करने वाले दो लोग हैं, बातें कर लेते हैं, कभी लंबा रास्ता चुन लेते हैं। उसने इस पर ज़्यादा विचार नहीं किया कि उसकी शामें कब से कमल की ड्यूटी के हिसाब से अपने आप बदलने लगी थीं—लगभग उसी तरह, जैसे कभी वे विक्रम की छुट्टियों के आसपास बदलती थीं।</p>\n<p>पहली नज़र में कमल में विक्रम की हल्की-सी झलक थी। वह भी लंबा था, कंधे चौड़े थे, हालाँकि उसका रंग विक्रम जितना साफ़ नहीं था और खुले इलाकों की पोस्टिंग की धूप उसके चेहरे पर दिखती थी। विक्रम के चेहरे पर जहाँ फौज की स्थिरता थी, वहाँ कमल के नैन-नक्श तीखे थे, और अपने बालों तथा पहनावे पर वह बाकी कांस्टेबलों से कुछ ज़्यादा ध्यान देता था।</p>\n<p>लेकिन कविता को उसकी ओर खींचने वाली बात उसका चेहरा नहीं था।</p>\n<p>कमल के साथ रहना आसान था।</p>\n<p>वह हँसता था, दूसरों को हँसाता था और महिलाओं से बात करते समय उसके व्यवहार में एक सहज सम्मान था, जिसे दिखाने के लिए उसे अलग से कोई कोशिश नहीं करनी पड़ती थी। मेस में किसी ने ठीक से खाना नहीं खाया हो तो वह बिना कुछ कहे अपनी प्लेट उसकी तरफ सरका देता। सामने वाला बोल रहा हो तो उसकी नज़र इधर-उधर नहीं भटकती थी—पूरी, बिना जल्दी के, जैसे उस पल उसे कहीं और होने की कोई चाह ही न हो।</p>\n<p>और सबसे बड़ी बात—वह वहाँ था। हर दिन।</p>\n<p>विक्रम की आवाज़ कविता ने दो वर्षों में बहुत सुनी थी, मगर उसकी मौजूदगी हमेशा चुराए हुए दिनों और घंटों में मिली थी।</p>\n<p>कमल के साथ ऐसा नहीं था।</p>\n<p>कभी बाज़ार के पास किसी कैफे में एक शाम निकल जाती, कभी दोनों की ड्यूटी जल्दी ख़त्म होती तो बातें लंबी हो जातीं।</p>\n<p>करीब तीन हफ्तों बाद की एक शाम कमल की किसी मामूली बात पर कविता खुलकर हँस पड़ी। अपनी आवाज़ सुनकर उसे ख़ुद हैरानी हुई। कमल उसे देख रहा था।</p>\n<p>“यही वाली,” कमल ने कहा।</p>\n<p>“क्या?”</p>\n<p>“तुम्हारी असली हँसी। इसे ऐसे बचाकर रखती हो जैसे खर्च हो जाएगी।”</p>\n<p>कविता कुछ नहीं बोली।</p>\n<p>कमल मुस्कराया। “अच्छा लगता है कि मेरे सामने इसे बचाना नहीं पड़ता।”</p>\n<p>उसके बाद दोनों कुछ देर चुप चलते रहे, मगर वह पहले वाली सहज ख़ामोशी नहीं थी। कविता जेब में हाथ डाले, नज़र सामने रखकर चलती रही; दोनों के बीच का फ़ासला आज एक कदम कम था।</p>\n<p>विक्रम ने उसे दो वर्षों में ऐसा प्रेम दिया था जो गहरा था, तीखा था और लगभग असंभव भी। कमल उसे कुछ और दे रहा था—साथ होने की साधारण-सी सुविधा। और कविता को अब जाकर समझ आया कि वह इसके लिए भी उतनी ही प्यासी थी।</p>\n<p>एक सप्ताहांत वे पोस्टिंग से करीब दो घंटे दूर एक छोटे-से रिज़ॉर्ट तक गए; घरवालों के लिए वजह एक ट्रेनिंग थी, जिसके बारे में किसी ने ज़्यादा सवाल नहीं किए। शाम को दोनों रिज़ॉर्ट के पीछे बने बरामदे में अकेले बैठे थे। नीचे दूर कस्बे की रोशनियाँ दिखाई दे रही थीं, जब कमल ने आख़िर वह बात कह दी जिसके आसपास वे कई हफ्तों से घूम रहे थे।</p>\n<p>“मुझे तुम अच्छी लगती हो, कविता। सिर्फ इतनी नहीं कि साथ ड्यूटी करना अच्छा लगता है। उससे ज़्यादा। काफी समय से। और अब ये नाटक करते-करते थक गया हूँ कि हम बरगद वाले उस लंबे रास्ते से यूँ ही लौटते हैं।”</p>\n<p>कमल का हाथ कविता के हाथ पर आकर ठहरा। कविता ने उसे हटाया नहीं; वह कस्बे की रोशनियों को देखती रही।</p>\n<p>फिर वह कमल की ओर वैसे ही बढ़ी, जैसे बरसों से किनारे अटका कोई सूखा लट्ठा आख़िर तब बहता है, जब नदी की धारा पूरी ताकत से उस तक पहुँचती है—दिशा चुनते हुए नहीं, बस टिके रहने की कोशिश छोड़ते हुए।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम को बस इतना दिखाई दे रहा था कि कविता अब पहले की तरह उसके पास नहीं थी। कारण वह अपने हिसाब से खोज लेता—शायद रामफल को कुछ शक हुआ होगा, शायद कविता सावधान हो रही होगी।</p>\n<p>विक्रम भी उन दिनों कश्मीर घाटी की एक ऊँची पोस्ट पर था, जहाँ सर्दियाँ आदमी को बाहर से कम और भीतर से ज़्यादा थकाती थीं। लगातार दो ऑपरेशनों के बाद उसकी चुप्पी और गहरी हो गई थी—किसी जमी हुई झील की तरह, जिसकी सतह पर कुछ नहीं हिलता और तल में बहुत कुछ दबा रहता है। कुछ बातें ऐसी थीं जो वह अपने साथियों तक से नहीं कहता था, और कविता से कहने की तो कभी आदत ही नहीं बनी। कविता विक्रम के जीवन में थी, पर उसकी फौजी ज़िंदगी का एक बड़ा हिस्सा हमेशा कविता की पहुँच से बाहर रहा था—किसी ऊँचे दर्रे के उस पार के इलाके जैसा, जहाँ कोई पहुँच ही नहीं सकता।</p>\n<p>उस सर्दी की ठंड भी अलग थी—मैदानों की सूखी, चटखती ठंड नहीं, बल्कि नम और भारी, जो जूतों के रास्ते हड्डियों में उतरकर बैठ जाती और भीतर लौट आने के बहुत देर बाद तक वहीं रहती। कभी-कभार की साफ़ सुबहों में आसपास के पहाड़ इतनी घनी धुंध में लिपटे दिखते, जैसे साँस रोके बैठे हों।</p>\n<p>पोस्ट के नीचे एक नदी बहती थी—ठिठुरती सर्दी में भी तेज़, भरी हुई, अपनी ही धुन में। उसकी गहरी, अनथक गूँज धुंध को चीरती ऊपर चढ़ती रहती, दिन-रात, जैसे घाटी की छाती के भीतर कोई पुराना, ज़िद्दी दिल धड़क रहा हो। कुछ रातों में वह इतनी ज़ोर से गरजती कि पानी कम और नीचे करवट बदलती कोई जीती-जागती चीज़ ज़्यादा लगती—ऐसी चीज़, जो कभी सोती नहीं। पहले कुछ हफ्तों के बाद वहाँ के जवान उसे सुनना भूल जाते, जैसे आदमी हर उस आवाज़ को भूल जाता है जो कभी बदलती नहीं—अपनी ही साँस की तरह। विक्रम भी भूल गया था। नदी उन्हें तभी याद आती, जब किसी सुबह वह गूँज बेवजह थम जाती—और हर बार वह सन्नाटा उन्हें उस शोर से कहीं ज़्यादा बेचैन कर जाता।</p>\n<p>कुछ शामों विक्रम घेरे के किनारे खड़ा होता, मुँह से निकलती भाप सर्द हवा में घुलती जाती, और वह सोचता कि उसकी ज़िंदगी में जो कुछ भी गर्म था, वह असल में कितनी दूर था—घर, गाँव, धूप ओढ़े सरसों के पीले खेत, और कविता की आवाज़, जो अब फोन पर भी ढलान उतरती किसी गूँज की तरह दूर होती जा रही थी। सब कुछ एक ऐसी दूरी के उस पार था, जिसे किलोमीटर नाप ही नहीं सकते थे।</p>\n<p>ऐसी ही रातों में—जब कमरे के पीछे जेनरेटर घरघराता रहता और खिड़की के शीशे पर ठंड अपनी हथेली टिकाए धीरज से भीतर आने का इंतज़ार करती—नैना का नंबर बार-बार विक्रम की नज़र में आने लगा। कविता ने वह नंबर उसे आगे बढ़ने के लिए दिया था, मगर विक्रम महीनों तक उसे बिना छुए पड़ा रहने देता—बर्फ़ में दबे किसी बीज की तरह, जिसे अभी मौसम का भरोसा नहीं था।</p>\n<p>जब वह नंबर पर लौटा, तो उसके पीछे कोई योजना नहीं थी। कविता ने जिस लड़की को तेज़ और आसानी से प्रभावित न होने वाली बताया था, वह उस रात ध्यान बँटाने का एक छोटा, बेनुकसान-सा ज़रिया लगी—जैसे कुएँ में पत्थर डालकर यह सुनना कि पानी कितना नीचे है।</p>\n<p>एक रात उसने ज़्यादा सोचे बिना एक फॉरवर्डेड मैसेज भेज दिया और उसके पीछे लिख दिया—</p>\n<p>“सॉरी, ग़लत नंबर।”</p>\n<p>भेजने से पहले उसका अंगूठा कुछ देर स्क्रीन पर रुका ज़रूर, लेकिन मैसेज चला गया।</p>\n<p>जवाब उसकी उम्मीद से जल्दी आया, और उसके सीने की गाँठ ढीली हो गई।</p>\n<p>“कोई बात नहीं। किसे भेजना था?”</p>\n<p>“किसी खास को नहीं।”</p>\n<p>बस इतनी-सी बातचीत हुई और फिर नैना चुप हो गई। उस रात विक्रम देर तक जागता रहा, वही तीन लाइनें मन में दोहराता रहा—लगभग यकीन के साथ कि जो ठीक से शुरू भी नहीं हुआ था, उसे वह पहले ही बिगाड़ चुका है।</p>\n<p>उसके बाद विक्रम ने ख़ुद को समझा लिया कि बात वहीं ख़त्म हो चुकी है। मगर चार-पाँच दिन बाद, एक और लंबी शाम में, उसकी उँगलियाँ अपने-आप वही नंबर खोल बैठीं। इस बार भी उसने ज़्यादा सोचे बिना एक फॉरवर्डेड मैसेज भेजा और नीचे वही दो शब्द जोड़ दिए—</p>\n<p>“सॉरी, फिर ग़लत नंबर।”</p>\n<p>इस बार कोई जवाब नहीं आया। स्क्रीन पर “डिलीवर्ड” के नीचे पहली रात सन्नाटा पड़ा रहा, दूसरी रात भी। विक्रम ने फोन उल्टा करके तकिये के नीचे दबा दिया—जैसे जो चीज़ आँख से हट जाए, वह मन से भी हट जाती हो।</p>\n<p>तीसरे दिन, बिना किसी आहट के, फोन पर नैना का मैसेज चमका—और खोलने से पहले ही वह पसलियों के ठीक नीचे कहीं आकर लगा।</p>\n<p>“फिर वही ग़लत नंबर वाले हो, या इस हफ्ते किसी और का फोन परेशान कर रहा है?”</p>\n<p>विक्रम अपने फोन को देखकर किसी बेवकूफ़ की तरह मुस्करा दिया। कमरा, जो एक मिनट पहले खाली लग रहा था, अचानक उतना खाली नहीं रहा।</p>\n<p>“आदमी वही है। कन्फ्यूजन भी शायद वही है।”</p>\n<p>“या तो तुम्हें नंबर टाइप करना नहीं आता, या ये सब जानबूझकर कर रहे हो। कौन-सी बात है?”</p>\n<p>“अगर कहूँ कि जानबूझकर?”</p>\n<p>“तो ये भी बताओ, मेरा नंबर मिला कहाँ से?”</p>\n<p>यह सवाल आते ही विक्रम की मुस्कान ठहर गई। उसने कविता का नाम टाइप किया और मिटा दिया। नाम बताना आसान था, मगर जिस कहानी से यह नंबर आया था, उसे खोलने का हक अकेले उसका नहीं था।</p>\n<p>“एक कॉमन फ्रेंड से। नाम नहीं बताऊँगा।”</p>\n<p>“इतनी मिस्ट्री मुझे पसंद नहीं।”</p>\n<p>“बोरिंग है,” विक्रम ने लिखा।</p>\n<p>“लगता तो है,” नैना ने जवाब दिया।</p>\n<p>“फिर सही है। बोरिंग मिस्ट्री के लिए नींद ख़राब नहीं की जा सकती!”</p>\n<p>“ये मैं डिसाइड करूँगी,” नैना ने लिखा।</p>\n<p>उस शाम तीन-चार मैसेज और हुए, हर एक पिछले से थोड़ा कम सावधान—जैसे कोई मुट्ठी धीरे-धीरे खुलती है, जब उसे चोट की उम्मीद नहीं रहती। फिर अगले दिनों में कभी दो मैसेज हुए, कभी दस, कभी बीच में एक-दो दिन कुछ नहीं हुआ। किसी ने इसे नियमित बनाने की कोशिश नहीं की, फिर भी दोनों के बीच एक छोटी-सी जगह अपने आप बनती चली गई।</p>\n<p>एक दिन नैना ने पूछ लिया—</p>\n<p>“वैसे करते क्या हो?”</p>\n<p>“आर्मी।”</p>\n<p>कुछ देर जवाब नहीं आया। विक्रम स्क्रीन को घूरता रहा, और पोस्ट के नीचे नदी की गूँज अचानक फिर सुनाई देने लगी। फिर स्क्रीन चमकी।</p>\n<p>“ज़ाहिर है। तभी इतनी मिस्ट्री है। तुम फौजी लोगों को तो बातें छिपाने की ट्रेनिंग ऐसे दी जाती है, जैसे उसमें भी मेडल मिलते हों।”</p>\n<p>“सिर्फ ज़रूरी बातें छिपाता हूँ। बाकी पूछकर देख लो।”</p>\n<p>“देखते हैं।”</p>\n<p>विक्रम को नैना का यही अंदाज़ अच्छा लगने लगा था। वह उसकी बातों से आसानी से प्रभावित नहीं होती थी—कभी सवाल करती, कभी उसकी बात काट देती, तो कभी अचानक जवाब देना बंद कर देती। उसके सामने विक्रम को कुछ साबित नहीं करना पड़ता था।</p>\n<p>नैना के साथ न कोई वादा था, न कोई उम्मीद—बस बातचीत थी, और धीरे-धीरे विक्रम को उसके जवाब का इंतज़ार रहने लगा।</p>\n<p>जिस नंबर को उसने महीनों तक अपने फोन में यूँ ही पड़ा रहने दिया था, अब उसी नंबर से आने वाले मैसेज और कॉल उसकी शामों का हिस्सा बनने लगे थे।</p>\n<p>कुछ दिनों बाद विक्रम को लगा कि अब वह केवल नैना के मैसेज नहीं पढ़ना चाहता, उसकी आवाज़ भी सुनना चाहता है। इसके लिए किसी बहाने की ज़रूरत नहीं पड़ी और जल्द ही उनकी बातचीत मैसेज से फोन तक पहुँच गई।</p>\n<p>शुरुआती कॉल्स कभी कुछ मिनट चलतीं, कभी काफी देर तक। इसी दौरान विक्रम को कभी-कभी लगता कि कुछ शामों में नैना के बोलने का ढंग और मिज़ाज थोड़ा बदला हुआ है, मगर उसने इसे सामान्य बात समझकर ज़्यादा ध्यान नहीं दिया।</p>\n<p>असल में उन शुरुआती कॉल्स में एक-दो बार फोन नैना ने नहीं, किसी और ने उठाया था। ख़राब लाइन और आवाज़ की मिलती-जुलती लय के कारण विक्रम फ़र्क़ नहीं पकड़ पाया और फिलहाल विक्रम के लिए यह जानने की कोई वजह भी नहीं थी।</p>"}, {"chapter": 9, "title": "अध्याय 7 — आवाज़ की आदत", "content": "<h1>अध्याय 7 — आवाज़ की आदत</h1>\n<p>आठ बजने से कुछ पहले ही विक्रम के पाँव अपने-आप मेस के बाहर वाले संकरे कॉरिडोर की ओर मुड़ने लगे थे। ऐसा कोई दिन नहीं था जब दोनों ने तय किया हो कि अब रोज़ बात करेंगे, न आठ बजे का समय कभी आपस में निश्चित किया गया था; बस धीरे-धीरे उनकी शामें इस तरह बदलती गईं कि आठ से नौ के बीच किसी एक का फोन आना लगभग तय हो गया।</p>\n<p>हर रात बात हो पाना संभव नहीं था। दोनों की ड्यूटी थी और कई बार चाहकर भी समय नहीं मिलता, लेकिन जिन शामों में फोन नहीं आता, उनमें अब कुछ अधूरा-सा रहने लगा था—जैसे कोई वाक्य अपने आख़िरी शब्द के बिना रह गया हो।</p>\n<p>मेस के बाहर का संकरा कॉरिडोर ही वह इकलौती जगह थी जहाँ सिग्नल पकड़ता था, इसलिए विक्रम वहीं खड़ा होकर बात करता। कंक्रीट के फर्श से उठती ठंड जूतों की सिलाई तक चढ़ आती, और दीवार के उस पार किसी का रेडियो रोज़ वही पुराने फिल्मी गाने खरखराती आवाज़ में बजाता रहता—घिसी हुई रीलों जैसे, जो टूटकर भी चलना नहीं छोड़तीं। पहले यह सब उसकी शाम का हिस्सा भर था; अब आठ बजते ही फर्श की ठंड कहीं पीछे छूट जाती, और घड़ी पर टिकी उसकी नज़र वैसी ही हो जाती जैसी कभी भोर की पेट्रोलिंग से पहले क्षितिज पर टिकती थी—चौकन्नी, इंतज़ार में, एक पतली लकीर के उजले होने की राह देखती हुई।</p>\n<p>नैना की तरफ भी बहुत अलग हाल नहीं था। सोमवार उसके लिए हमेशा भारी होते—थाने का एक सीनियर अफसर अपनी सबसे ओछी हिदायतें हफ्ते की शुरुआत के लिए ऐसे बचाकर रखता, जैसे कोई छोटी-छोटी क्रूरताएँ जमा करता हो। ड्यूटी स्टेशन से कुछ दूर गुरुग्राम में उसका अपना क्वार्टर था, और वह शाम की ड्यूटी इस तरह निपटाने लगी थी कि आठ बजे से पहले वहाँ पहुँच जाए। अक्सर जब विक्रम का फोन आता, वह बिस्तर पर पैर मोड़कर बैठी होती, पीठ ठंडी दीवार से टिकी, और पास रखे चाय के कप से भाप की एक पतली लकीर उठकर बल्ब की रोशनी में घुलती रहती। बगल के क्वार्टर से छौंक की महक दीवार पार करके चली आती, और सामने वही उपन्यास औंधा पड़ा रहता, जिसके तीन-चार पन्नों से आगे वह कई रातों से नहीं बढ़ पाई थी—फोन ख़त्म होने के बाद पढ़ने बैठती और कुछ ही देर में नींद उसे पन्ने से उठाकर ले जाती।</p>\n<p>इन बातचीतों में दोनों एक-दूसरे के बारे में कोई बड़ी बातें नहीं खोज रहे थे, फिर भी छोटी-छोटी आदतें अपने आप सामने आने लगी थीं। नैना ने जल्दी समझ लिया था कि किसी गंभीर सवाल का जवाब देने से पहले विक्रम एक पल चुप रहता है, जैसे बोलने से पहले शब्दों को भीतर ही तौल रहा हो; और विक्रम ने यह जान लिया था कि नैना की बातों में जितनी तेज़ी थी, उसके पीछे उतनी ही बारीकी से सामने वाले को देखने की आदत भी थी।</p>\n<p>विक्रम नैना के मज़ाक पर ज़्यादातर लोगों से आधा पल देर से हँसता था—जैसे कोई लकड़ी के पुल पर पहला कदम रखने से पहले एक पाँव से तख़्ते को आज़माता है, कि यह सचमुच मज़ाक ही है और इस पर पूरा वज़न रखा जा सकता है। नैना को यह देरी खलती नहीं थी; उल्टे वह उसी का इंतज़ार करने लगी थी। उस आधे पल में उसे दिखता कि उसकी बात विक्रम के भीतर कहीं तक उतरी है, शिष्टाचार में सुनकर किनारे नहीं रख दी गई।</p>\n<p>एक रात नैना ने कोई मज़ाक किया और विक्रम को हँसने में हमेशा की तरह एक पल ज़्यादा लग गया।</p>\n<p>“तुम थोड़े स्लो हो,” नैना ने कहा।</p>\n<p>“स्लो नहीं, सावधान हूँ।”</p>\n<p>“सावधान आदमी कई बार बहुत बोरिंग भी होते हैं।”</p>\n<p>विक्रम हँसा। “कोशिश करूँगा तुम्हारे लिए थोड़ा कम सावधान रहने की।”</p>\n<p>“ज़्यादा मेहनत मत करना,” नैना ने कहा।</p>\n<p>बात वहीं निकल गई, लेकिन ऐसी ही छोटी-छोटी बातों के बीच दोनों एक-दूसरे के लिए जगह बनाते जा रहे थे।</p>\n<p>उनकी बातचीत शुरू हुए करीब चार हफ्ते हुए थे, जब नैना ने आख़िर वह बात बता दी जिसे विक्रम शुरुआती कॉल्स में केवल उसके बदलते मिज़ाज की तरह महसूस करता रहा था। कुछ शामों में जिस आवाज़ से वह बात करता रहा था, वह नैना की नहीं, उसकी छोटी बहन सुनैना की थी, जो कभी-कभी रात रुकने गाँव से उसके क्वार्टर आ जाती थी। सुनैना कुछ ही हफ्तों में यूके जाने वाली थी—वहाँ दो साल की पढ़ाई के लिए—इसलिए इन दिनों उसके चक्कर बहन के पास बढ़ गए थे। दोनों बहनों ने मज़ाक में एक-दो बार फोन सुनैना के हाथ में दे दिया था, और नैना ने बाद में इसे ठीक करने की ज़रूरत नहीं समझी।</p>\n<p>विक्रम कुछ क्षण चुप रहा।</p>\n<p>“तो मैं इतने दिनों से दो लोगों से बात कर रहा था?” विक्रम ने पूछा।</p>\n<p>नैना हँस पड़ी। “इतने दिनों से नहीं। बस कुछ बार।”</p>\n<p>बाद में तीनों की बाकायदा बात कराई गई। सुनैना ने माफ़ी भी माँगी, हालाँकि उसकी आवाज़ में पछतावे से ज़्यादा हँसी थी। उसका अंदाज़ विक्रम को पहली ही बातचीत में भा गया—तेज़, बेबाक, और ऐसी लड़की जिसे इस बात से ज़्यादा फ़र्क़ नहीं पड़ता था कि सामने वाला उसके बारे में क्या सोचता है; ऐसी, जो जहाँ जाए, अपना मौसम अपने साथ लेकर चलती हो।</p>\n<p>दूसरा महीना आते-आते फोन केवल शाम की एक अच्छी आदत नहीं रहा; अब पूरा दिन आठ बजे की ओर ऐसे झुकने लगा था, जैसे नई बनी इमारत की दीवारें धीरे-धीरे अपनी नींव पर बैठती जाती हैं—सुबह की परेड, दिन की ड्यूटी, सब उसी एक घंटे की ओर ढलते हुए। विक्रम भी कई बार साथी अफसरों के साथ चल रही बेकार की हँसी-मज़ाक बीच में छोड़कर निकल आता—जब आठ बजे का वक्त अपना वही धैर्य भरा सवाल लेकर उसके सामने आ खड़ा होता।</p>\n<p>दोनों में से किसी ने कभी नहीं कहा कि वह इंतज़ार करता है। पर जब भी घंटी बजती, पहली घंटी पूरी होने से पहले ही उठा ली जाती, और कोई यह कभी नहीं पूछता था कि इतनी जल्दी कैसे।</p>\n<p>सुनैना के जाने से एक रात पहले तीनों फिर स्पीकर पर थे। वह बहन के क्वार्टर पर आख़िरी रात बिताने आई थी, और सुनैना के आधे खुले सूटकेस की आवाज़ें बातचीत के बीच लगातार आती रहीं—कभी जिप बंद करने की कोशिश, कभी कोई चीज़ फिर बाहर निकालने की खड़खड़ाहट।</p>\n<p>बातों के बीच नैना अचानक कुछ शांत हो गई।</p>\n<p>“मैं ख़ुद को समझा रही हूँ कि दो साल बहुत लंबे नहीं होते… लेकिन अभी ये बात सच जैसी नहीं लग रही।”</p>\n<p>वह वाक्य नैना की आम तेज़ रफ्तार से धीमा निकला था। विक्रम ने उसकी बातों में इतना लंबा ठहराव पहले कभी नहीं सुना था।</p>\n<p>सुनैना अपनी बहन को अच्छी तरह पहचानती थी।</p>\n<p>“मेरी बहन का ध्यान रखना,” उसने विक्रम से कहा। “ये दिखाती ऐसे है जैसे इसे किसी की ज़रूरत ही नहीं पड़ती।”</p>\n<p>“रखूँगा,” विक्रम ने कहा।</p>\n<p>सुनैना के यूके चले जाने के बाद नैना की दिनचर्या लगभग वही रही। वह पहले की तरह बात करती, विक्रम को छेड़ती, उसकी बातों पर हँसती भी—मगर क्वार्टर में सुनैना की निशानियाँ बाकी थीं। एक रात नैना ने यूँ ही बताया कि सुनैना का दुपट्टा अब भी खूँटी पर टँगा है और उसने उसे हटाया नहीं; बाथरूम में दो टूथब्रश रखे हैं, जिनमें से एक को वह रोज़ देखती है और रोज़ वहीं रहने देती है। यह बताते हुए वह हँसी थी—मगर हँसी बीच में ही कहीं रुक गई, और फोन पर कुछ क्षण केवल लाइन की हल्की सरसराहट रही।</p>\n<p>विक्रम सैकड़ों किलोमीटर दूर, ठंडे कॉरिडोर में फोन कान से लगाए, उस ठहराव को सुनता रहा।</p>\n<p>वह उस जगह को भर नहीं सकता था।</p>\n<p>कुछ जगहें धूप के उस टुकड़े जैसी होती हैं जो दीवार पर किसी एक ही खिड़की से गिरता है; कोई दूसरा चिराग़ उसकी जगह नहीं ले सकता। बस इतना किया जा सकता था कि जब तक वह टुकड़ा खाली रहे, उस कमरे में कोई जागता रहे—आवाज़ के दूसरी तरफ।</p>\n<p>और उन दिनों विक्रम ने वही किया।</p>\n<p>रात के आठ बजे फोन अब भी बजता रहा।</p>"}, {"chapter": 10, "title": "अध्याय 8 — गुलमोहर के नीचे", "content": "<h1>अध्याय 8 — गुलमोहर के नीचे</h1>\n<p>फोन पर बनी यह आदत जितनी आसान थी, मिलने की बात उतनी ही भारी निकली। तीन महीने हो चुके थे, और हर बार जब बातचीत उस मोड़ के पास पहुँचती, कोई एक उसे मोड़ देता—छुट्टी का हिसाब, ड्यूटी का रोस्टर, किसी पुराने किस्से की ओर मुड़ती हँसी। दोनों जानते थे कि अब तक वे एक-दूसरे के लिए सिर्फ एक आवाज़ थे; मिलने के बाद उस आवाज़ के साथ एक चेहरा जुड़ जाता, और चेहरे के साथ वे उम्मीदें, जिनसे फिर अनजान बने रहना आसान नहीं रहता।</p>\n<p>आख़िर एक दिन विक्रम ने बातों-बातों में बताया कि उसकी छुट्टी आने वाली है और वह गुरुग्राम में होगा। उसने मिलने के लिए नहीं पूछा, बस इतना कहकर बात वहीं छोड़ दी और फ़ैसला नैना पर रहने दिया।</p>\n<p>नैना ने लेज़र वैली पार्क, सेक्टर 29 का नाम लिया। दिन का समय, खुली जगह और आसपास सामान्य लोग—एक ऐसी जगह जहाँ दो लोगों का मिलना सिर्फ दो लोगों का मिलना भी माना जा सकता था। जैसे दोनों में से कोई भी एक पल के लिए भी सचमुच ऐसा मानता हो।</p>\n<p>तय दिन विक्रम पहले पहुँच गया।</p>\n<p>हफ्ते के बीच की दोपहर थी और पार्क में ज़्यादा भीड़ नहीं थी। हवा में कटी हुई घास की हल्की गंध थी, प्रवेश द्वार के पास किसी ठेले से चाट-मसालों की खुशबू भीतर तक चली आ रही थी। पक्के रास्ते पर इक्का-दुक्का लोग दौड़ रहे थे, एक बुज़ुर्ग दंपती कुछ दूरी पर बेंच पर बैठा था और कहीं नज़रों से ओझल बच्चों के खेलने की आवाज़ बीच-बीच में सुनाई दे रही थी।</p>\n<p>नैना ने जिस जगह का ज़िक्र किया था, उसे ढूँढ़ने में विक्रम को कोई मुश्किल नहीं हुई। पार्क के दूर वाले हिस्से में एक पुराना गुलमोहर था और उसकी चौड़ी शाखाओं के नीचे सीमेंट की एक बेंच। तना मोटा था, छाल उम्र के साथ खुरदरी और धूसर हो चुकी थी और शाखाएँ आसपास के करीने से लगे पेड़ों की तरह सधी हुई नहीं, बल्कि अपनी मर्ज़ी से दूर-दूर तक फैली थीं।</p>\n<p>अभी उस पर फूल नहीं आए थे। शाखाओं पर नई कोंपलों की हल्की हरी नोकें ही दिख रही थीं—छोटी, कसी हुई, अपने खुलने का वक्त तौलती हुई। कुछ हफ्तों बाद यही पेड़ लाल-नारंगी फूलों से इस तरह भर जाएगा कि दूर से देखने पर लगेगा जैसे पूरा पेड़ आग पकड़ चुका हो। फिर भी वह बाकी पेड़ों के बीच अलग दिखाई देता था—बहुत पुराना, थोड़ा बेतरतीब, और इतना विशाल कि पास से गुज़रते हुए नज़र अपने आप उस पर चली जाए।</p>\n<p>अगर कोई पेड़ याद रख सकता, तो यह रखता। यह इस ज़मीन पर तब से खड़ा था, जब पार्क का कोई नाम नहीं था—जब सेक्टर 29 बस खुली ज़मीन थी, जो किसी शहर के आकर उसे अपना लेने का इंतज़ार कर रही थी। इन चुपचाप बीते दशकों में उसने अंत कम और शुरुआतें ज़्यादा देखी थीं, जैसे पुरानी और धीरज वाली चीज़ें अक्सर देखती हैं।</p>\n<p>इन दोनों के पैदा होने से पहले भी जवान जोड़े उसकी छाँव में बैठे थे—आधे-अधूरे यकीन वाले वादे फुसफुसाते, ऐसी चोर निगाहें डालते जिनके बारे में उन्हें लगता था कि कोई नहीं देख रहा। पहली स्वीकारोक्तियाँ, शब्दों से ज़्यादा कह जाने वाली पहली चुप्पियाँ, और वह खास सिहरन, जब दो अजनबी किसी वाक्य के बीच अचानक समझ जाते हैं कि अब वे अजनबी नहीं रहे—सब कुछ उसके तने की परतों में चुपचाप तह होता गया, और हर कहानी अपने वक्त में यही मानती रही कि बस वही मायने रखती है।</p>\n<p>उसे इसका कोई पता नहीं था, और पता होने की ज़रूरत भी नहीं थी, कि आज वह एक और कहानी थामने जा रहा है।</p>\n<p>विक्रम बेंच के पास खड़ा इंतज़ार करता रहा और बहुत समय बाद ख़ुद को लेकर असामान्य रूप से सचेत था। उसने एक बार अपनी शर्ट ठीक की, फिर बेवजह दोबारा; कभी घड़ी देखता, कभी पिछले महीनों की बातचीत याद करता। उसे ख़ुद पर हल्की झुँझलाहट भी हुई जब उसने महसूस किया कि उसके हाथ पूरी तरह स्थिर नहीं थे। जो आदमी घात वाले इलाकों में बिना इस काँपन के उतर चुका हो, उसके लिए पार्क की एक बेंच पर किसी लड़की का इंतज़ार करना तो मामूली बात होनी चाहिए थी।</p>\n<p>फिर उसकी नज़र सामने वाले रास्ते पर पड़ी।</p>\n<p>नैना आ रही थी।</p>\n<p>विक्रम का दिल एक बार पसलियों से ज़ोर से टकराया—एक सख़्त, अकेली दस्तक, जैसी किसी असली मुठभेड़ से पहले भी उसे बरसों से महसूस नहीं हुई थी, पार्क की बेंच की ओर आती किसी लड़की के लिए तो बिल्कुल नहीं। उसने नैना को पहले कभी देखा नहीं था, फिर भी पहचानने में एक पल नहीं लगा। महीनों से जिस आवाज़ को वह लगभग हर रात कॉरिडोर की ठंड में खड़ा सुनता आया था, उसे आज पहली बार एक चेहरा मिला था—जैसे बरसों रेडियो पर सुनी किसी आवाज़ का मालिक अचानक सामने आकर खड़ा हो जाए, और पहली ही नज़र में लगे कि आवाज़ ने उसके साथ पूरा इंसाफ़ नहीं किया था। कुछ क्षणों तक विक्रम की धड़कन अपनी सामान्य रफ्तार पर लौटने को तैयार ही नहीं हुई।</p>\n<p>नैना लंबी थी। कंधे सीधे, कदम लंबे, सधे हुए और बेझिझक। वह जिस तरह उसकी ओर चली आ रही थी, उसमें न किसी को प्रभावित करने की कोशिश थी, न आसपास की निगाहों को लेकर कोई संकोच—बस वही बेपरवाह तेज़ी, जो विक्रम महीनों से उसकी आवाज़ में सुनता आया था, आज उसकी चाल में दिखाई दे रही थी।</p>\n<p>दोपहर की रोशनी नैना के साफ़, गोरे रंग पर पड़ रही थी। चेहरे की बनावट तीखी और स्पष्ट थी, आँखें गहरी काली। ड्यूटी के दौरान बँधे रहने वाले उसके लंबे, घने काले बाल आज खुले थे, और चलते हुए कभी कंधों के पीछे चले जाते, कभी हवा के साथ चेहरे के पास लौट आते। उसने साधारण जींस और कुर्ती पहन रखी थी; कपड़ों में दिखावे जैसा कुछ नहीं था, फिर भी वह भीड़ में अलग से पहचान ली जाती थी।</p>\n<p>कुर्ती इतनी फिट थी कि बिना कुछ जताए अपनी बात कह दे। विक्रम की नज़र एक पल ज़्यादा ठहर गई—बस एक पल, मगर इतना कि जब उसकी नज़र दोबारा ऊपर उठी, नैना की गहरी काली आँखें पहले से उसी पर टिकी थीं।</p>\n<p>एक क्षण के लिए दोनों की नज़रें वहीं बँधी रहीं।</p>\n<p>विक्रम समझ गया कि वह पकड़ा गया है, और उसने नज़र हटाई नहीं।</p>\n<p>नैना भी विक्रम को देखते हुए अपनी तरफ से यही हिसाब लगा रही थी, और उसने इसे छिपाने की कोई कोशिश नहीं की—हालाँकि दूर से विक्रम को पहचानते ही नैना के कदमों की लय एक पल को टूटी थी, जबकि पूरी सुबह वह ख़ुद को समझाती आई थी कि यह एक मामूली-सी मुलाक़ात होगी। विक्रम उसकी कल्पना से लंबा था; साफ़ रंग, मजबूत चेहरा, और फौजी ट्रेनिंग से तराशी हुई देह। उसकी नज़र में एक ठहराव था, बाँह पर हल्का-सा सफ़ेद निशान, और बाल छुट्टी से पहले कटवाने की ज़रूरत से कुछ आगे निकल चुके थे। फोन पर वह जितना खुलकर बात करता था, सामने उससे कहीं ज़्यादा शांत और स्थिर दिखाई दे रहा था।</p>\n<p>नैना उसके पास आकर रुकी।</p>\n<p>“घूर रहे हो।”</p>\n<p>पकड़े जाने पर विक्रम के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“एक बार देखने का हक तो है। इतने महीनों से सिर्फ आवाज़ सुनी है।”</p>\n<p>“सिर्फ एक बार?” नैना ने उसे देखते हुए कहा। “काफी उदार हो।”</p>\n<p>वह बेंच पर बैठ गई और विक्रम भी उसके पास आकर बैठ गया। दोनों के बीच थोड़ी-सी दूरी थी—इतनी कि पहली मुलाक़ात की झिझक अभी साफ़ दिखाई दे सके।</p>\n<p>फोन पर जो सहजता दोनों को बिना कोशिश मिल जाती थी, सामने बैठकर उसके लौटने में कुछ मिनट लगे। अब तक वे बिना सोचे एक-दूसरे से कुछ भी कह देते थे; अब हर वाक्य के साथ यह भी दिख रहा था कि सामने वाला कब मुस्करा रहा है, कब नज़रें हटा रहा है, और किस बात पर उसके चेहरे का रंग बदल जाता है।</p>\n<p>कुछ देर बाद नैना ने ख़ुद ही उस असहजता को तोड़ दिया।</p>\n<p>“ये थोड़ा अजीब है। फोन पर इतनी बातें करती हूँ और अब समझ नहीं आ रहा कि कहाँ देखूँ।”</p>\n<p>विक्रम ने ऊपर गुलमोहर की ओर देखा।</p>\n<p>“पेड़ को देख लो। पेड़ों को देखना आसान होता है।”</p>\n<p>नैना हँस पड़ी।</p>\n<p>वही हँसी जिसे विक्रम महीनों से फोन पर सुनता आया था। बस इस बार वह किसी स्पीकर से नहीं आ रही थी; उसके ठीक सामने बैठी थी।</p>\n<p>उस हँसी के बाद जैसे शुरुआती झिझक भी टूट गई।</p>\n<p>बातें फिर उसी लय में लौटने लगीं जिसे दोनों पहले से जानते थे। नैना ने अपने एक मामले के बारे में बताया जिसने पिछले कुछ दिनों से उसे परेशान कर रखा था, विक्रम ने अपनी पिछली सर्दियों की पोस्टिंग के कुछ किस्से सुनाए। एक बात से दूसरी निकलती गई और जिस मुलाक़ात की शुरुआत में दोनों यह तय नहीं कर पा रहे थे कि नज़र कहाँ रखें, उसमें कब लगभग दो घंटे बीत गए, इसका किसी को ध्यान नहीं रहा।</p>\n<p>बीच में नैना उसे कुछ देर देखती रही।</p>\n<p>“तुम सामने से अलग हो।”</p>\n<p>“अच्छा या बुरा?”</p>\n<p>“अभी फ़ैसला नहीं किया।” उसके होंठों पर हल्की मुस्कान आई। “फोन पर ज़्यादा बोलते हो। यहाँ ज़्यादा देखते हो।”</p>\n<p>“मैं हिसाब लगा रहा हूँ।”</p>\n<p>“किस बात का?”</p>\n<p>“आवाज़ और इंसान एक जैसे हैं या नहीं।”</p>\n<p>नैना ने भौंह उठाई। “और?”</p>\n<p>विक्रम ने इस बार जवाब देने से पहले नज़र नहीं हटाई।</p>\n<p>“इंसान बेहतर है।”</p>\n<p>नैना के चेहरे पर एक भाव कौंधा—छोटा-सा, बेपर्दा, और पूरी तरह दिखने से पहले ही गायब। उसने नज़र रास्ते की ओर कर ली और एक पल में ख़ुद को सँभालकर लौटी, वही तीखापन फिर अपनी जगह—जैसे किसी रोशन खिड़की पर फिर से पर्दा खींच दिया गया हो।</p>\n<p>“तुम्हें ऐसी बातें इतनी सीधे नहीं कहनी चाहिए।”</p>\n<p>“क्यों?”</p>\n<p>“क्योंकि मुझे उन लोगों की आदत है जो सीधी बात तक पहुँचने से पहले उसके चार चक्कर लगाते हैं।”</p>\n<p>“मुझे चक्कर लगाने का धैर्य नहीं है।”</p>\n<p>इस बार नैना की मुस्कान कुछ देर उसके चेहरे पर रही।</p>\n<p>बातचीत फिर आगे बढ़ी, मगर अब दोनों के बीच शुरुआती सावधानी उतनी नहीं थी। नैना ने जूते की नोक से पास पड़ा सूखा पत्ता एक तरफ सरका दिया, और विक्रम ने बेंच के किनारे टिका अपना हाथ अनजाने में उसकी ओर कुछ इंच खिसका लिया—दोनों में से किसी ने इस पर ध्यान नहीं दिया।</p>\n<p>कुछ देर की चुप्पी के बाद नैना ने कहा, “आज तुमने सीधी बात का नियम बना रखा है, तो सुनो। पूरे रास्ते मैं इस मुलाक़ात का इंतज़ार करती रही, और ख़ुद से भी यह बात मानने में मुझे वक्त लगा।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>“मैं भी।”</p>\n<p>इस बार किसी ने बात को मज़ाक में नहीं उड़ाया।</p>\n<p>वे वहीं बैठे रहे। आसपास पार्क की सामान्य आवाज़ें चलती रहीं—कहीं बच्चे, किसी ठेले वाले की पुकार—और ढलती दोपहर की रोशनी रास्ते पर धीरे-धीरे ऐसे फैलती रही, जैसे कोई शहद सँभालकर उड़ेल रहा हो। उनके बीच की दूरी अब भी बनी हुई थी और दोनों में से किसी ने दूसरे को छुआ तक नहीं था; फिर भी महीनों से फोन के दोनों सिरों के बीच जो फ़ासला था, वह उस बेंच पर बैठे-बैठे घुल चुका था—गुलमोहर की छाया के साथ-साथ, जो अपनी जगह धीरे-धीरे खिसकती हुई उनके पैरों तक आ पहुँची थी।</p>\n<p>कुछ देर बाद नैना ने घड़ी देखी।</p>\n<p>“मुझे निकलना चाहिए। सुबह जल्दी ड्यूटी है।”</p>\n<p>उसने कहा ज़रूर, मगर उठी नहीं।</p>\n<p>विक्रम ने भी उसे जाने की याद नहीं दिलाई।</p>\n<p>कुछ क्षण बाद नैना ने सामने रास्ते की ओर देखते हुए कहा, “मैं दोबारा मिलना चाहती हूँ। फोन पर नहीं।”</p>\n<p>विक्रम चुपचाप उसकी ओर देखता रहा।</p>\n<p>“मुझे नहीं पता अभी ये क्या है,” नैना ने कहा, “लेकिन जितना है… उससे थोड़ा और चाहती हूँ।”</p>\n<p>“मैं भी।”</p>\n<p>नैना ने पहली बार उस जवाब के बाद नज़र नहीं हटाई।</p>\n<p>फिर ऊपर फैली गुलमोहर की शाखाओं की ओर देखते हुए बोली, “अगली बार भी यही गुलमोहर?”</p>\n<p>विक्रम के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“यही गुलमोहर।”</p>\n<p>नैना पहले चली गई। विक्रम वहीं खड़ा उसे तब तक जाते देखता रहा, जब तक वह पार्क के गेट के पास भीड़ में घुलकर दिखना बंद नहीं हो गई—और उसके बाद भी कुछ देर रास्ते की ओर देखता रहा, जैसे वहाँ अब भी कुछ बाकी हो।</p>\n<p>उसने नैना को उस दिन भी नहीं बताया कि उसका नंबर उसे कहाँ से मिला था। लंबे समय तक नहीं बताया। नैना उसे संयोग समझती रही। किस्मत। वह सब, जो इंसान किसी ऐसी शुरुआत के बारे में मानना चाहता है, जिसके बारे में उसे अभी पता ही न हो कि वह आगे चलकर कितनी मायने रखेगी।</p>\n<p>उसके जाने के बाद पार्क का वह कोना फिर पहले जैसा शांत हो गया।</p>\n<p>गुलमोहर कुछ नहीं बोला—बोल भी कैसे सकता था। हवा चली तो उसकी शाखाओं पर नई कोंपलों की नोकें एक साथ हिलीं, जैसे किसी ने सिर हिलाकर हामी भरी हो; मगर वह आगे का हाल नहीं जानता था। उसकी छाँव में शुरू हुई ज़्यादातर कहानियाँ चुपचाप मुरझा जाती थीं, जैसे ज़्यादातर शुरुआतें मुरझा जाती हैं। कुछ हफ्तों बाद यही पेड़ लाल-नारंगी फूलों से दहक उठेगा, और राह चलते लोग रुककर कहेंगे कि जैसे इसमें आग लग गई है—पर किसी को पता नहीं चलेगा कि उसकी जड़ों के पास बैठी वह एक दोपहर आगे चलकर बाकी सब कहानियों से कहीं ज़्यादा माँगने वाली थी।</p>"}, {"chapter": 11, "title": "अध्याय 9 — आदत पड़ जाएगी", "content": "<h1>अध्याय 9 — आदत पड़ जाएगी</h1>\n<p>पार्क की उस पहली मुलाक़ात के बाद के हफ्तों में उनका रिश्ता एक ऐसी जगह आकर ठहर गया था, जिसका नाम दोनों में से कोई तय नहीं करना चाहता था। रात के आठ बजे का फोन अब भी बजता था, मगर कटने से पहले कोई एक पूछ लेता, “अगली बार कब?”—और दूसरा तारीख़ की जगह बस “देखते हैं” कह देता, जैसे उस “अगली बार” को पक्का कर देने में भी कोई जोखिम हो। फिलहाल वे एक-दूसरे को जान रहे थे—फोन पर सुनी हुई आवाज़ के पीछे मौजूद उस असली इंसान को, जिसकी आदतें, फ़ैसले और अपनी ज़िंदगी को लेकर कुछ ऐसी ज़िदें थीं जिन्हें समझने में समय लगना था—वैसे ही, जैसे कोई हाथ किसी नए साज़ को धीरे-धीरे पहचानता है, उस पर सधने का हक कमाने से पहले।</p>\n<p>अगली मुलाक़ात में विक्रम उसे बाइक पर जयपुर रोड के पास हाईवे मूड्स नाम के एक छोटे-से रिसॉर्ट में ले गया। उस दिन उनके बीच पहली मुलाक़ात जैसी घबराहट नहीं थी। खाली लॉन में चाय के सामने बैठे दोनों काफी सहज थे, फिर भी अभी इतनी सावधानी बाकी थी कि दोनों के हाथ मेज़ पर सामने ही रहते—जैसे ताश के खिलाड़ी दिखा रहे हों कि उनके पास कोई छिपा पत्ता नहीं है।</p>\n<p>बातों-बातों में नैना ने विक्रम की बजाय सामने फैले खेतों की ओर देखते हुए कहा—जैसे इस बात को बाहर आने के लिए कोई और जगह चाहिए हो— “मैं हमेशा से फोर्स में आना चाहती थी। मैं यहाँ किसी संयोग से नहीं पहुँची। मैंने इसे चुना है… और चुनती रहूँगी।”</p>\n<p>विक्रम को नैना की बात पर ज़रा भी हैरानी नहीं हुई।</p>\n<p>“तुम्हें देखकर लगता भी नहीं कि तुमने वर्दी बस नौकरी की तरह पहनी है,” विक्रम ने कहा। “जैसे यह हमेशा से तुम्हारी ज़िंदगी का हिस्सा होनी थी।”</p>\n<p>नैना ने चाय का कप मेज़ पर रखा—धीरे, बिना आवाज़ किए, जैसे किसी बात को सँभालकर रख रही हो। कुछ ही हफ्तों से जानने वाला आदमी उसे इतनी आसानी से समझ लेगा, इसकी उसे उम्मीद नहीं थी।</p>\n<p>फिर विक्रम ने अपने घर के बारे में बताया—उस पिता के बारे में, जिनके लिए आदमी की कीमत उसकी ज़मीन और उसके अनुशासन से तय होती थी; उस माँ के बारे में, जो हर दिन बेटे की सलामती की प्रार्थना करती थी, लेकिन उससे कभी यह नहीं कहती थी कि वह कोई सुरक्षित ज़िंदगी चुन ले। उसने अपने खेतों और आम-जामुन के उन पेड़ों का भी ज़िक्र किया जिन्हें उसके दादा ने लगाया था और जो उनके जाने के बहुत बाद भी हर साल फल देते थे।</p>\n<p>नैना कुछ देर सुनती रही, फिर बोली, “तुम अपने घर की बात ऐसे करते हो जैसे घर में रहकर भी तुम्हें उसकी याद आती हो।”</p>\n<p>विक्रम हल्का-सा मुस्कराया।</p>\n<p>“शायद ट्रेनिंग के लिए पहली बार घर छोड़ने के बाद से ही आती रही है।”</p>\n<p>“ये बात मैं तुम्हारी सोच से ज़्यादा अच्छी तरह समझती हूँ,” नैना ने कहा।</p>\n<p>वह अपने कप के किनारे पर उँगली फिराती रही, जैसे आगे की बात के लिए सही शब्द ढूँढ़ रही हो।</p>\n<p>“मेरे लिए फोर्स भी कुछ ऐसी ही है। आगे मेरी ज़िंदगी में चाहे जो आए, मैं इसका हिस्सा रहूँगी। किसी भी कीमत पर। मैंने ख़ुद को कभी इसके बाहर खड़ा हुआ सोचा ही नहीं।”</p>\n<p>विक्रम ने उस बात को हल्के में नहीं लिया। नैना उसे अपनी पसंद नहीं बता रही थी; वह अपनी ज़िंदगी की उन चीज़ों में से एक बता रही थी जिन पर आगे कभी समझौता नहीं होना था।</p>\n<p>अगली बार विक्रम उसे एम्बियंस मॉल में फिल्म दिखाने ले गया। फिल्म में दोनों की कोई खास दिलचस्पी नहीं थी; वह बस दो घंटे साथ बैठने का एक बहाना थी। अँधेरे हॉल में स्क्रीन की बदलती रोशनी कभी उनके चेहरों पर नीली गिरती, कभी सुनहरी; दोनों के कंधे कभी-कभी हल्के से छू जाते, और हर बार छूने के बाद कोई एक ज़रा-सा हट जाता—फिर कुछ देर में वही दूरी अपने-आप घट जाती।</p>\n<p>फिल्म के बाद कॉफी पीते हुए नैना ने कहानी और किरदारों की ऐसी धज्जियाँ उड़ाईं कि विक्रम फिल्म के दौरान जितना नहीं हँसा था, उससे ज़्यादा वहाँ हँसता रहा।</p>\n<p>“तुम बहुत सख़्त आलोचक हो,” विक्रम ने कहा।</p>\n<p>“सख़्त नहीं, ईमानदार हूँ। दोनों में फ़र्क़ होता है,” नैना ने कहा। “काम की राय चाहिए तो ईमानदार वाली ही बेहतर होती है, सिर्फ अच्छी लगने वाली नहीं।”</p>\n<p>एक और बार उन्होंने कहीं जाने का तय ही नहीं किया। बाइक शहर से बाहर निकलती चली गई—खेतों, ईंट-भट्ठों और सूनी पुलियाओं को पीछे छोड़ती—और फिर उसी रास्ते वापस लौट आई। रास्ते में न जाने कहाँ से बहस शुरू हो गई कि जब फर्ज और अपनी खुशी आमने-सामने खड़े हों, तो पहले किसे चुना जाना चाहिए। हवा उनके कई शब्द रास्ते में ही उड़ा ले जा रही थी; जो पहुँचते, आधे-अधूरे पहुँचते, और दोनों बाकी हिस्सा अंदाज़े से भरते रहे—फिर भी बहस चलती रही।</p>\n<p>कुछ देर बाद नैना को अचानक समझ आया कि विक्रम असल में उससे असहमत था ही नहीं।</p>\n<p>“तुम मेरी बात से सहमत हो। सिर्फ ये देखने के लिए बहस कर रहे हो कि मैं अपनी बात के बचाव में क्या कहती हूँ।”</p>\n<p>विक्रम बिना किसी शर्मिंदगी के हँसा। “गुनाह कबूल।”</p>\n<p>“बहुत परेशान करने वाली आदत है।”</p>\n<p>“आदत पड़ जाएगी।”</p>\n<p>नैना कुछ क्षण चुप रही। जब उसने दोबारा कहा तो स्वर में पहले वाली छेड़छाड़ थोड़ी कम थी।</p>\n<p>“तुम्हें भी मेरी आदतें पड़ेंगी, विक्रम। और पहले ही बता दूँ—एक बार मेरी ठीक से आदत पड़ गई, तो फिर इतनी आसानी से पीछा नहीं छुड़ा पाओगे। मैं उन आदतों में से नहीं हूँ जो वक्त के साथ अपने-आप छूट जाती हैं।”</p>\n<p>विक्रम ने जवाब नहीं दिया। उसने बाइक की चाबी उँगली में घुमाई और देर तक सड़क के पार खेतों को देखता रहा।</p>\n<p>नैना ने अनजाने में अपनी बात के भीतर यह मान लिया था कि उनके पास एक-दूसरे की आदत पड़ने जितना समय होगा—और वह भी हमेशा के लिए। विक्रम ने उस अनकहे हिस्से को वैसे ही महसूस किया, जैसे कोई किसी की रुकी हुई साँस महसूस करता है। नैना ने अपनी बात वापस नहीं ली, और विक्रम ने भी उसे वहीं रहने दिया।</p>\n<p>एक शाम दोनों बिना पहले से तय किए फिर उसी पार्क में पहुँच गए।</p>\n<p>वही बेंच। वही पुराना गुलमोहर।</p>\n<p>उस शाम सेक्टर 29 पर हल्की धुंध उतर आई थी। स्ट्रीट लाइटों की रोशनी धुंध में फैलकर मुलायम-सी हो गई थी, और आम दिनों में जॉगर्स और टहलने वालों से भरे रहने वाले रास्ते लगभग खाली थे। गुलमोहर की कोंपलें कुछ और खुल चुकी थीं; सबसे ऊँची शाखाओं के सिरों पर एक-दो कलियों की हल्की सूजन दिखाई देने लगी थी, जैसे कोई कहने वाली बात होंठों तक आकर ठहर गई हो।</p>\n<p>नैना ने शॉल अपने चारों ओर थोड़ा और कस लिया और इस बार विक्रम के पहले से ज़्यादा करीब बैठ गई। दोनों की बाँहें कंधे से कोहनी तक एक-दूसरे से लगी हुई थीं।</p>\n<p>“आज हवा में ठंडक है,” नैना ने कहा।</p>\n<p>“किसी गर्म जगह चलने को कह सकती थीं,” विक्रम ने कहा।</p>\n<p>“कह सकती थी। लेकिन मुझे ये बेंच पसंद है।”</p>\n<p>नैना ने ऊपर गुलमोहर की शाखाओं की ओर देखा। धुंध में लटकी स्ट्रीट लाइट उसके चेहरे पर पीली-सी परछाईं डाल रही थी।</p>\n<p>“मुझे लगता है मैंने तय कर लिया है कि अब ये हमारी बेंच है। इतनी कम मुलाक़ातों में ऐसा कहना अजीब है?”</p>\n<p>“नहीं,” विक्रम ने सहजता से कहा। “शायद मैंने तो पहले दिन ही तय कर लिया था। बस कहा नहीं था।”</p>\n<p>नैना ने जवाब शब्दों में नहीं दिया।</p>\n<p>उसने धीरे से अपना सिर विक्रम के कंधे पर रख दिया।</p>\n<p>दोनों काफी देर वैसे ही बैठे रहे। बातें बहुत कम हुईं। सामने धुंध खाली रास्तों पर ऐसे सरकती रही, जैसे कोई सफ़ेद चादर खिसकाकर पूरे पार्क को धीरे-धीरे सुला रहा हो; और उनके बीच पहली बार चुप्पी ऐसी थी जिसे किसी बात से भरने की ज़रूरत नहीं थी।</p>\n<p>वह बेंच अब पार्क की बाकी बेंचों जैसी नहीं रही थी। वहाँ उनकी पहली मुलाक़ात हुई थी, फिर वे लौटकर वहीं आए थे—और आज नैना ने बैठने से पहले उस पर से सूखे पत्ते हाथ से झाड़े थे, उसी सहज अधिकार से, जिससे कोई अपनी ही कुर्सी झाड़ता है।</p>\n<p>उस छुट्टी के ख़त्म होने के बाद अगली लंबी छुट्टी तक करीब दो महीने निकल गए। इस बीच एक दिन के लिए भी मिलना संभव नहीं हुआ। उनकी शामें फिर फोन पर लौट आईं और रात के आठ बजे के आसपास आने वाली आवाज़ ही दोनों के बीच की दूरी को थामे रही।</p>\n<p>मगर अब उन फोन कॉल्स में एक फ़र्क़ था।</p>\n<p>वे एक-दूसरे को सिर्फ आवाज़ से नहीं जानते थे। अब हर शब्द के पीछे एक चेहरा था, हर हँसी के साथ उसका भाव और हर चुप्पी के साथ वह इंसान, जिसे दोनों सामने बैठकर देख चुके थे। रिश्ता अब ऊपर से कम दिखता था और भीतर ज़्यादा बढ़ता था—ठीक उस गुलमोहर की तरह, जिसके नीचे वे बैठे थे: ऊपर अभी कोंपलों की नोकें भर थीं, पर नीचे ज़मीन में जड़ें हर रात थोड़ा और गहरे उतर रही थीं, इससे बहुत पहले कि किसी को पेड़ का आने वाला रंग दिखाई दे।</p>\n<p>दोनों जानते थे कि अगली छुट्टी जब भी आएगी, बहुत कुछ बदल देगी। अब तक उन्होंने एक-दूसरे को छोटे-छोटे हिस्सों में जाना था—कुछ फोन कॉल्स, कुछ मुलाक़ातें, साथ बिताई कुछ दोपहरें। अगली बार दूरी के पीछे छिपने की गुंजाइश नहीं होगी।</p>\n<p>जो कुछ उनके बीच बन रहा था, उसे पहली बार रोज़मर्रा की ज़िंदगी में एक-दूसरे के सामने रहकर परखा जाना था।</p>"}, {"chapter": 12, "title": "अध्याय 10 — साठ दिन", "content": "<h1>अध्याय 10 — साठ दिन</h1>\n<p>आख़िर विक्रम की छुट्टी मंज़ूर हो गई—पूरे साठ दिन की।</p>\n<p>कई वर्षों में उसे एक साथ इतनी लंबी छुट्टी नहीं मिली थी। आम तौर पर ऐसी छुट्टी का मतलब होता था कि पोस्टिंग में कोई बदलाव आने वाला है और ऊपर बैठे लोग उससे पहले उसके हिस्से का काम समेट रहे हैं। वजह जो भी थी, विक्रम ने ज़्यादा सवाल नहीं किए। उसने छुट्टी ऐसे स्वीकार की जैसे अचानक मिली कोई अच्छी चीज़—इससे पहले कि देने वाला अपना इरादा बदल दे।</p>\n<p>उस शाम फोन पर उसने नैना को बताया।</p>\n<p>कुछ क्षण दूसरी ओर चुप्पी रही।</p>\n<p>“साठ दिन?” नैना ने दोहराया, जैसे उस संख्या को ठीक से समझ रही हो। “मुझे नहीं लगता ट्रेनिंग के अलावा मेरी ज़िंदगी में कभी लगातार साठ दिन किसी एक चीज़ के रहे हैं।”</p>\n<p>“ड्यूटी तो तुम्हारी रहेगी। छुट्टी सिर्फ मेरी है।”</p>\n<p>“मेरे पास शामें हैं। संडे हैं। और मेरा इरादा दोनों का ज़रूरत से ज़्यादा इस्तेमाल करने का है।”</p>\n<p>वह एक पल रुकी, फिर अपनी आवाज़ को लापरवाह बनाने की नाकाम कोशिश के साथ बोली, “अच्छा लग रहा है कि छुट्टी इतनी लंबी है, विक्रम। एक महीने पहले शायद मैं ये बात नहीं कहती।”</p>\n<p>उस रात अपने कमरे तक लौटते हुए नैना का वही वाक्य—“अच्छा लग रहा है कि छुट्टी इतनी लंबी है”—देर तक विक्रम के साथ चलता रहा, जैसे बूट के तले में दबा कोई कंकड़, जो हर कदम पर अपनी याद दिलाए। चारों ओर ठंडी, चुप पहाड़ियाँ अपनी रोज़ की बेपरवाही से खड़ी थीं, चोटियों पर बर्फ़ की धुँधली लकीरें ओढ़े—जैसे उन्होंने अभी-अभी कुछ ऐसा देखा ही न हो, जिस पर ध्यान दिया जाए।</p>\n<p>छुट्टी के पहले ही हफ्ते में, बिना कोई योजना बनाए, दोनों की एक छोटी-सी दिनचर्या बनने लगी। नैना की ड्यूटी ख़त्म होने से कुछ पहले विक्रम उसे फोन कर देता। ज़रूरी नहीं था कि हर बार मिलने का कार्यक्रम बने; कई शामें सिर्फ बीस-पच्चीस मिनट की बातचीत में निकल जातीं—नैना थाने की कोई घटना सुनाती, विक्रम दिन भर की कोई मामूली बात। लेकिन कई बार वही फोन अचानक मिलने की वजह बन जाता और एक घंटे के भीतर तय हो जाता कि कहाँ जाना है। पहले से कुछ तय करना दोनों टालते थे—जैसे प्लान को जल्दी नाम दे देने से उसे नज़र लग जाएगी।</p>\n<p>पहली शाम जब विक्रम उसे बाकायदा कहीं बाहर ले गया, जगह थी लीजर वैली रोड के पास रिन्यूएबल एनर्जी पार्क में बना छोटा-सा कैफे—रूट्स। खुले में पेड़ों के बीच रखी मेज़ें, लकड़ी का सादा-सा माहौल और शाम ढलते ही टहनियों से लटकी छोटी रोशनियाँ, जो एक-एक करके जुगनुओं की तरह जल उठती थीं, उस जगह को शहर के बीच होते हुए भी उससे थोड़ा अलग कर देती थीं। मेज़-कुर्सियाँ पेड़ों के बीच ऐसे बिखरी थीं, जैसे वे भी वहीं उग आई हों। आसपास की मेज़ों की बातचीत के बीच की खाली जगहें पंछियों की आवाज़ भर देती थी, और रसोई से किसी तली जाती चीज़ की महक बाहर तक आ रही थी।</p>\n<p>विक्रम बीस मिनट पहले पहुँच गया था और उनमें से काफी समय उसने सिर्फ यह तय करने में लगा दिया कि बैठना कहाँ है। दरवाज़े के पास वाली मेज़ उसे ज़रूरत से ज़्यादा खुली लगी; पेड़ों के बहुत भीतर वाली ऐसी, जैसे वह जानबूझकर नैना को किसी की नज़र से छिपा रहा हो। आख़िर उसने बीच की एक मेज़ चुन ली।</p>\n<p>नैना बारह मिनट देर से पहुँची और बिना किसी अपराधबोध के सामने वाली कुर्सी पर बैठ गई।</p>\n<p>उसके बैठते ही विक्रम एक पल को आधा खड़ा हो गया—मेस की पुरानी आदत—और अगले ही पल उसे ख़ुद इस पर झेंप आई।</p>\n<p>“फोन कर सकती थीं,” विक्रम ने कहा।</p>\n<p>“कर सकती थी। फिर सोचा, बारह मिनट इंतज़ार करके तुम बच जाओगे।”</p>\n<p>नैना ने आसपास नज़र दौड़ाई। पेड़ों के बीच छोटी रोशनियाँ जलने लगी थीं, और उसके कंधे ढीले पड़ गए—जैसे किसी जगह पहुँचकर समझ आ जाए कि यहाँ कोई दिखावा नहीं करना पड़ेगा।</p>\n<p>“जगह अच्छी चुनी है,” नैना ने कहा। “तुमसे इतनी उम्मीद नहीं थी।”</p>\n<p>“उम्मीद कम रखो तो आदमी आसानी से अच्छा लगने लगता है।”</p>\n<p>नैना ने मेन्यू उठाया, कुछ सेकंड देखा और वापस रख दिया।</p>\n<p>“मेरे लिए तुम ऑर्डर करो।”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“टेस्ट है?”</p>\n<p>“बिल्कुल। देखना है पार्क में मेरी बातें सच में सुन रहे थे, या बाकी आदमियों की तरह बस सिर हिला रहे थे—जो समझते हैं कि सिर हिलाना ही पर्सनैलिटी है।”</p>\n<p>“अभी बैठे पाँच मिनट भी नहीं हुए और परीक्षा शुरू हो गई?”</p>\n<p>“तैयारी के लिए दो महीने मिले थे। मुझे कोई हमदर्दी नहीं है।”</p>\n<p>विक्रम ने चिली मशरूम मँगाया, फिर शाही पनीर, वेज रायता और दोनों के लिए नान। वह सिर्फ एक चीज़ भूल गया—नैना को साथ में अलग से हरी मिर्च चाहिए थी।</p>\n<p>नैना ने पूरी गंभीरता से फ़ैसला सुनाया, “शुरुआत स्वीकार करने लायक है। इससे ज़्यादा खुश मत होना।”</p>\n<p>खाना धीरे-धीरे आता रहा और उसके साथ उनकी बातचीत भी ढीली होती गई। अब हर वाक्य बोलने से पहले सोचने की ज़रूरत नहीं पड़ रही थी। दोनों एक-दूसरे को छेड़ सकते थे, बात काट सकते थे और बिना वजह हँस सकते थे—और किसी ने ध्यान नहीं दिया कि यह छूट कब मिल गई थी।</p>\n<p>उनसे दो मेज़ दूर साफ़ तौर पर किसी अरेंज मैरिज की पहली मुलाक़ात चल रही थी—और बुरी तरह बिगड़ रही थी। लड़का बार-बार फोन देख रहा था और लड़की से ज़्यादा उसकी माँ बोल रही थी।</p>\n<p>नैना कुछ देर उन्हें देखती रही, फिर धीमे से बोली, “देखना, ग्यारह सेकंड में फिर फोन देखेगा। दो बार टाइम कर चुकी हूँ।”</p>\n<p>ठीक ग्यारह सेकंड बाद लड़के ने फोन उठा लिया।</p>\n<p>विक्रम को हँसी रोकने के लिए नैपकिन मुँह पर रखना पड़ा।</p>\n<p>“तुम ख़तरनाक हो,” विक्रम ने कहा।</p>\n<p>“ऑब्ज़र्वेंट हूँ,” नैना ने कहा। “फ़र्क़ होता है। हमारी नौकरी में इसी फ़र्क़ से प्रमोशन मिलता है।”</p>\n<p>खाते-खाते विक्रम ने हमेशा की तरह खाने को छोटे और लगभग बराबर टुकड़ों में काटना शुरू कर दिया। नैना करीब एक मिनट तक उसे देखती रही।</p>\n<p>“तुम खाना भी ऐसे खाते हो जैसे कोई इंस्पेक्शन चल रहा हो।”</p>\n<p>“पुरानी आदत है।”</p>\n<p>“तुम्हारी हर चीज़ पुरानी आदत है। बैठने का तरीका, नैपकिन रखने का तरीका… मुझे पूरा यकीन है कि सोते हुए कोई कमांड दे दे तो तुम नींद में भी सावधान खड़े हो जाओगे।”</p>\n<p>“मैंने तय किया है कि तुम्हारी कुछ नई आदतें बनानी हैं,” नैना ने कहा। “ये छुट्टी ख़त्म होने से पहले।”</p>\n<p>“धमकी लग रही है।”</p>\n<p>“लक्ष्य है। साथ चलने की कोशिश करना।”</p>\n<p>खाना ख़त्म होने पर नैना ने बिना विक्रम से पूछे आइसक्रीम मँगवा ली। अपने लिए दो स्कूप। विक्रम ने लेने से मना कर दिया तो नैना ने उसे ऐसे देखा जैसे उसने कोई बेहद चिंताजनक बात कह दी हो।</p>\n<p>“तुम्हें आइसक्रीम पसंद नहीं है?”</p>\n<p>“आइसक्रीम में ऐसा क्या खास है, ये मुझे कभी समझ नहीं आया। ठंडी होती है, दो मिनट में ख़त्म हो जाती है… और आख़िर है तो चीनी ही, बस सज-धजकर आती है।”</p>\n<p>नैना कुछ क्षण उसे देखती रही।</p>\n<p>“पिछले कई महीनों में किसी भी इंसान के मुँह से सुना हुआ ये सबसे बेरस वाक्य है।”</p>\n<p>विक्रम हँस पड़ा।</p>\n<p>“इसे भी ठीक करूँगी,” नैना ने चम्मच उठाते हुए कहा। “नैपकिन के ठीक नीचे लिस्ट में डाल रही हूँ।”</p>\n<p>“मैं तैयार रहूँगा।”</p>\n<p>“रहना भी चाहिए। जो लड़ाई मैं ख़ुद चुनती हूँ, आसानी से हारती नहीं।”</p>\n<p>उसके बाद भी दोनों काफी देर तक बैठे रहे, जबकि कैफे के कर्मचारियों के चेहरे धीरे-धीरे बता रहे थे कि अब उन्हें उठ जाना चाहिए। बातें भी किसी खास विषय पर नहीं थीं। नैना ने <i>हमशकल्स</i> की ऐसी आलोचना की जैसे फिल्म ने निजी तौर पर उसका अपमान किया हो; फिर अपने एक सीनियर अफसर की नकल उतारी, जो महिला कॉन्स्टेबलों से ऐसे बात करता था जैसे उन्हें हर बात दो बार समझानी पड़े। विक्रम ने अपनी एक पुरानी ठंडी पोस्टिंग का किस्सा सुनाया, जहाँ जवानों ने पूरी गंभीरता से बहस की थी कि चाय स्टील के कप में जल्दी ठंडी होती है या प्लास्टिक में।</p>\n<p>नैना उस बात पर ज़रूरत से ज़्यादा हँसी।</p>\n<p>और विक्रम को वह हँसी अपनी कमाई हुई लगी—वैसे ही, जैसे किसी को वह पहली आग लगती है, जो उसने बिना किसी की मदद के जलाई हो: कुछ तिनके, एक फूँक, और फिर लौ का वह पहला काँपता हुआ भरोसा।</p>\n<p>बिल आया तो दोनों के बीच उसे चुकाने को लेकर छोटी-सी लड़ाई हुई। नैना हमेशा की तरह तेज़ निकली; विक्रम के बटुए तक हाथ पहुँचने से पहले ही उसने पैसे निकालकर वेटर को दे दिए।</p>\n<p>बाहर निकलने के बाद भी दोनों में से कोई तुरंत शाम ख़त्म करने की जल्दी में नहीं था।</p>\n<p>“साठ दिन,” नैना ने पार्किंग की ओर चलते हुए फिर कहा। “मैं इनका बिल्कुल समझदारी से इस्तेमाल नहीं करने वाली।”</p>\n<p>“मुझे भी यही उम्मीद है।”</p>\n<p>चलते-चलते नैना का हाथ विक्रम के हाथ तक आया और उसकी उँगलियाँ विक्रम की उँगलियों में समा गईं—बिना रुके, बिना किसी झिझक के, जैसे वह रास्ता उसे पहले से मालूम हो।</p>\n<p>नैना ने कुछ नहीं कहा, न विक्रम ने।</p>\n<p>जैसे हाथ पकड़ना कोई फ़ैसला नहीं था। बस चलते-चलते वही सबसे सहज जगह थी जहाँ दोनों के हाथों को होना चाहिए था।</p>\n<p>विक्रम चलता रहा।</p>\n<p>पिछले दो घंटों में कोई बड़ी बात नहीं हुई थी—न किसी ने प्रेम कहा था, न कोई वादा किया था। फिर भी कुछ बदल चुका था। अब उनके बीच सिर्फ मिलने की इच्छा नहीं थी; रोज़मर्रा की छोटी-छोटी चीज़ों में भी एक-दूसरे के लिए जगह बनने लगी थी—हरी मिर्च, आइसक्रीम की लिस्ट, नैपकिन का मोड़।</p>\n<p>छुट्टी का अधिकांश हिस्सा अभी बाकी था।</p>\n<p>पार्किंग में बाइक की चाबी निकालते हुए विक्रम ने बिना चाहे उँगलियों पर गिनना शुरू कर दिया कि साठ में से कितने दिन बाकी हैं—और गिनते-गिनते उसकी उँगलियाँ कुछ ज़्यादा ही जल्दी ख़त्म हो गईं।</p>"}, {"chapter": 13, "title": "अध्याय 11 — वर्दी के भीतर", "content": "<h1>अध्याय 11 — वर्दी के भीतर</h1>\n<p>नैना के साथ बिताई हर शाम हँसी और हल्की बातों से भरी नहीं होती थी। कुछ दिन वह ड्यूटी से ऐसी थकान लेकर लौटती थी जिसे कुछ घंटे की नींद दूर नहीं कर सकती थी।</p>\n<p>विक्रम की छुट्टी को करीब दो हफ्ते हुए थे। गुरुवार की उस शाम नैना ने रोज़ के समय का इंतज़ार किए बिना सीधे ड्यूटी से उसे फोन किया। उसकी आवाज़ सपाट और बहुत संभली हुई थी—इतनी संभली हुई कि विक्रम समझ गया, वह अपने भीतर कुछ रोककर बैठी है।</p>\n<p>“मिल सकते हो?” नैना ने पूछा, फिर जवाब का इंतज़ार किए बिना कहा, “कहीं बंद जगह पर नहीं। थोड़ी खुली हवा चाहिए।”</p>\n<p>विक्रम को जगह पूछने की ज़रूरत नहीं पड़ी।</p>\n<p>वही पार्क। वही बेंच। वही गुलमोहर, जिसकी शाखाओं पर हल्की हरी कोंपलें अभी-अभी फूटी थीं—फूल आने में अभी देर थी।</p>\n<p>विक्रम पहुँचा तो नैना पहले से वहाँ बैठी थी। वह अब भी वर्दी में थी, जबकि उससे मिलने से पहले वह हमेशा कपड़े बदलती थी। उसके लिए यह एक छोटी-सी सीमा थी—ड्यूटी पर मौजूद पुलिसवाली और विक्रम के साथ रहने वाली नैना के बीच। मगर आज उसमें वह सीमा निभाने की भी ताकत नहीं बची थी।</p>\n<p>कैप सिर पर थोड़ा पीछे खिसका हुआ था। दिन भर की धूल, धूप और भागदौड़ से बालों की कुछ लटें माथे पर चिपकी थीं। वह बेंच पर बिल्कुल सीधी बैठी थी, जैसे शरीर को ढीला छोड़ दिया तो भीतर सँभालकर रखा सब कुछ भी बिखर जाएगा।</p>\n<p>विक्रम उसके पास आकर बैठ गया।</p>\n<p>“मुश्किल दिन था?”</p>\n<p>नैना ने हल्का-सा सिर हिलाया।</p>\n<p>“एक केस आया था,” नैना ने सामने देखते हुए कहा। “लड़का-लड़की की कुछ महीने पहले शादी हुई है। इंटर-कास्ट लव मैरिज। दोनों के घरवाले ख़िलाफ़ थे। आज शाम दोनों प्रोटेक्शन माँगने आए थे।”</p>\n<p>उसकी आवाज़ थोड़ी कस गई।</p>\n<p>“सुबह लड़की का अपना पिता परिवार के तीन लोगों को लेकर उनके घर पहुँच गया। पूरी गली के सामने दोनों को धमकी देकर गया है।”</p>\n<p>विक्रम ने धीरे से उसके सिर की कैप उतारकर दोनों के बीच बेंच पर रख दी—जैसे सिपाही का दर्जा उतारकर कुछ देर के लिए एक तरफ रख दिया हो। बाल खुलकर चेहरे के आसपास आ गए। विक्रम ने माथे पर चिपकी एक लट दो उँगलियों से पीछे कर दी।</p>\n<p>“लड़की क्या कह रही थी?”</p>\n<p>नैना कुछ क्षण चुप रही।</p>\n<p>“कह रही थी, बचपन में उसके पिता से ज़्यादा प्यार उसे किसी ने नहीं किया। हर मेले में उसे कंधे पर बैठाकर ले जाते थे। स्कूल से पास हुई तो रो पड़े थे। उसने बचपन में जो माँगा, किसी न किसी तरह लाकर दिया।”</p>\n<p>नैना की नज़र अब भी सामने थी।</p>\n<p>“और आज वही आदमी उसके किराए के घर के बाहर तीन लोगों के साथ खड़ा होकर बिल्कुल शांत आवाज़ में कह रहा था कि बेटी को इस तरह घर की इज़्ज़त मिटाते देखने से अच्छा है कि वह उसे मरा हुआ देख ले।”</p>\n<p>विक्रम ने कहा, “फिर वह वही आदमी नहीं रहा।”</p>\n<p>नैना ने पहली बार उसकी ओर देखा।</p>\n<p>उसके चेहरे पर सिर्फ उस केस की परेशानी नहीं थी। बात कहीं और भी जाकर लगी थी।</p>\n<p>“मैं यही नहीं समझ पा रही, विक्रम। इतना प्यार इतनी नफ़रत कैसे बन जाता है? धीरे-धीरे कम हो जाए, दूर हो जाए… वह समझ में आता है। लेकिन एक फ़ैसला पसंद न आया और वही प्यार एकदम उलट गया?”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>“उस लड़की ने मुझसे बार-बार पूछा कि क्या उसके पिता अब भी उससे प्यार करते होंगे। कहीं भीतर, इन सबके नीचे। मेरे पास उसके लिए कोई ईमानदार जवाब नहीं था।”</p>\n<p>“तुमने उसे क्या कहा?” विक्रम ने पूछा।</p>\n<p>“जो हम कह सकते थे। शिकायत दर्ज होगी। धमकी रिकॉर्ड में जाएगी। पते पर नज़र रखेंगे।”</p>\n<p>नैना ने जबड़ा भींच लिया।</p>\n<p>“सब सच है। लेकिन उसके सवाल का जवाब इनमें से कुछ भी नहीं है। मेरे सवाल का भी नहीं।”</p>\n<p>विक्रम समझ गया कि नैना यहाँ किसी समाधान के लिए नहीं आई थी। पुलिस की तरफ से जो किया जा सकता था, वह उसे उससे बेहतर मालूम था। जिस बात ने उसे भीतर से परेशान किया था, उसका जवाब किसी प्रक्रिया या नियम में था ही नहीं।</p>\n<p>विक्रम ने बस अपना हाथ नैना के कंधों के चारों ओर रख दिया।</p>\n<p>कुछ क्षण बाद नैना उसकी ओर झुक गई और सिर उसके कंधे पर टिका दिया। कैप वहीं पड़ी रही—बेंच पर रखा थाने का एक छोटा-सा हिस्सा, जिसे आज की शाम किसी ने नहीं उठाया।</p>\n<p>“और भी है तो बताओ,” विक्रम ने धीमे से कहा। “मैं सुन रहा हूँ। जितना कहना है, कहो।”</p>\n<p>और भी था।</p>\n<p>करीब आधे घंटे तक नैना बोलती रही। कई बार एक ही बात दोबारा लौटकर आती, जैसे भँवर में पानी नीचे उतरने से पहले एक ही जगह घूमता रहता है—लड़की के पिता की वह असामान्य रूप से शांत आवाज़; अपनी पत्नी के पास असहाय खड़ा उसका पति; बिना चीखे, बिना गाली दिए दी गई वे धमकियाँ, जो इसी वजह से और ज़्यादा डरावनी लग रही थीं।</p>\n<p>विक्रम ने बीच में उसे नहीं रोका।</p>\n<p>उसने ऐसा पहले देखा था—अपने भीतर भी। पहली पोस्टिंग में एक आतंकी हमले के दौरान वह एक छोटी-सी बच्ची को बचा नहीं पाया था, और उस रात की वही दो-तीन बातें वह कई दिनों तक मन में दोहराता रहा था, जब तक एक पुराने हवलदार ने उससे नहीं कहा था कि अब उन्हें छोड़ दे। मगर विक्रम ने नैना को वह किस्सा नहीं सुनाया। इस समय नैना को उसकी अपनी कहानी की ज़रूरत नहीं थी।</p>\n<p>उसे बस अच्छा लगा कि नैना इस बोझ को अकेले लेकर घर जाने के बजाय उसके पास आई थी।</p>\n<p>बोलते-बोलते नैना उसके और करीब आ गई। सिर कंधे से खिसककर उसकी छाती पर टिक गया और एक हाथ ने उसकी कमीज़ को हल्के से पकड़ लिया। विक्रम ने उसे वहीं रहने दिया, बाँह उसके चारों ओर थोड़ी और सहजता से आ गई।</p>\n<p>कुछ देर बाद नैना ने पैर बेंच पर समेट लिए और करवट लेकर लेट गई। उसका सिर अब विक्रम की गोद में था। विक्रम का एक हाथ उसे सँभाले हुए था और दूसरे हाथ की उँगलियाँ धीरे-धीरे उसके बालों में चल रही थीं।</p>\n<p>नैना कुछ पल के लिए चुप हुई तो विक्रम ने नीचे देखते हुए कहा, “रुकने की ज़रूरत नहीं है। जो कहना है, पूरा कहो। जितना समय लगे।”</p>\n<p>नैना ने वहीं लेटे-लेटे फिर बोलना शुरू किया।</p>\n<p>“उसकी बातें सुनते हुए मैं अपने बाबा के बारे में सोच रही थी। उन्होंने कभी मुझ पर आवाज़ तक ऊँची नहीं की। ऐसी धमकी देने की तो मैं कल्पना भी नहीं कर सकती।”</p>\n<p>वह कुछ क्षण रुकी।</p>\n<p>“लेकिन सच ये भी है कि मैंने उन्हें कभी ऐसी वजह दी ही नहीं। मुझे नहीं पता, विक्रम… अगर कभी मैंने उस लड़की जैसा कोई फ़ैसला लिया तो वे क्या करेंगे। मैंने कभी उन्हें उस जगह तक पहुँचाकर देखा ही नहीं।”</p>\n<p>विक्रम की उँगलियाँ उसी धीमी गति से उसके बालों में चलती रहीं।</p>\n<p>जब नैना के पास कहने को कुछ नहीं बचा और वह चुप हो गई, विक्रम ने उसके चेहरे पर हाथ रखा और अंगूठे से गाल को हल्के से छुआ।</p>\n<p>नैना ने उसकी ओर देखा।</p>\n<p>“तुमने जवाब में कुछ कहा ही नहीं।”</p>\n<p>“मुझे लगा तुम्हें मेरे जवाब की ज़रूरत नहीं थी,” विक्रम ने कहा। “तुम्हें बस ये सब कहना था… और किसी को बीच में रोके बिना पूरा सुनना था।”</p>\n<p>नैना कुछ देर उसकी आँखों में देखती रही। फिर आँखें बंद कर लीं और वैसे ही उसकी गोद में पड़ी रही।</p>\n<p>काफी देर बाद नैना ने कहा, “थैंक यू।”</p>\n<p>विक्रम की उँगलियाँ अब भी उसके बालों में थीं।</p>\n<p>“किसलिए?”</p>\n<p>“इसे ठीक करने की कोशिश न करने के लिए। हर कोई तुरंत कोई समाधान देने लगता है। बाबा भी। मेरे साथ वाले भी। फिर ऐसा लगने लगता है जैसे असली समस्या वो चीज़ नहीं जो हुई है… समस्या ये है कि मैं उससे परेशान क्यों हूँ।”</p>\n<p>“जो हुआ है, उसमें सचमुच कुछ ग़लत है,” विक्रम ने कहा। “सिर्फ तुम्हें अच्छा महसूस कराने के लिए मैं उसे छोटा नहीं बनाऊँगा।”</p>\n<p>नैना ने आँखें खोलीं। चेहरे पर थकी हुई-सी छोटी मुस्कान आई।</p>\n<p>“इसीलिए घर जाने के बजाय तुम्हें फोन किया। घर जाती तो कहते ज़्यादा मत सोचो। तुमने मुझे सोचने दिया… और जब तक मैं सोचती रही, मेरे साथ बैठे रहे।”</p>\n<p>इसके बाद उनके बीच जो चुप्पी आई, उसमें पहले जैसा बोझ नहीं था—जैसे दिन भर तना रहा कोई तार आख़िर ढील पा गया हो।</p>\n<p>कुछ देर बाद विक्रम ने ऊपर गुलमोहर की कोंपलों भरी शाखाओं की ओर देखते हुए कहा, “एक बात बताऊँ? उसके बाद इंडियन आर्मी के काग़ज़ी हिसाब-किताब पर तुम्हारा भरोसा थोड़ा कम हो सकता है।”</p>\n<p>नैना के मुँह से, विक्रम की कमीज़ में दबा हुआ-सा, स्वर निकला, जिसमें हँसी की शुरुआत थी।</p>\n<p>“बताओ।”</p>\n<p>“पहाड़ों में एक तय ऊँचाई से ऊपर पोस्टेड यूनिट्स को ठंड के लिए एक्स्ट्रा रम राशन मिलता है। मेरी पहली पहाड़ी पोस्टिंग में यूनिट ने पूरा हिसाब लगाकर उसके लिए आवेदन कर दिया। सब खुश। कुछ महीने बाद ऑडिट वाले आए और उन्होंने बेस कैंप की ऊँचाई अपने हिसाब से नापी।”</p>\n<p>विक्रम एक क्षण रुका।</p>\n<p>“हम तय सीमा से बीस मीटर नीचे निकले।”</p>\n<p>नैना ने आँखें खोलीं।</p>\n<p>“फिर?”</p>\n<p>“फिर बाकायदा चर्चा हुई कि बीस मीटर ऊँचा प्लेटफॉर्म बनाया जा सकता है या नहीं।”</p>\n<p>नैना ने सिर उठाकर उसे देखा।</p>\n<p>“रम के लिए?”</p>\n<p>“बहुत गंभीरता से।”</p>\n<p>अब उसके चेहरे पर अविश्वास के साथ मुस्कान फैलने लगी थी।</p>\n<p>“आख़िर किसी ने याद दिलाया कि फ्लैग पोल पहले से एक ऊँची जगह पर लगा है और उससे कुछ मीटर पूरे हो जाते हैं। बाकी के लिए लकड़ी का प्लेटफॉर्म बनाते तो किसी दिन ब्रिगेडियर को समझाना पड़ता कि यूनिट ने ये इमारत किस महान सैन्य उद्देश्य से खड़ी की है। इसलिए मामला छोड़ दिया।”</p>\n<p>नैना हँस पड़ी।</p>\n<p>इस बार खुलकर।</p>\n<p>नैना का सिर फिर विक्रम की गोद में लुढ़क गया और उसने एक हाथ से अपना चेहरा ढक लिया—हँसी अब भी रुकने का नाम नहीं ले रही थी।</p>\n<p>“ये सच है?”</p>\n<p>“एक-एक शब्द।”</p>\n<p>विक्रम भी मुस्करा रहा था।</p>\n<p>“हमारे यहाँ कहते थे कि हर लड़ाई दो अलग स्केल वाले नक्शों के जोड़ पर लड़ी जाती है। उस पोस्टिंग में पता चला, रम की लड़ाई भी दो अलग ऊँचाइयों के जोड़ पर लड़ी जा सकती है।”</p>\n<p>नैना की हँसी धीरे-धीरे थमी। उसने आँखों के किनारे पोंछे और सिर हिलाया।</p>\n<p>“मुझे नहीं पता तुम बीस मीटर और लकड़ी के प्लेटफॉर्म को इस हफ्ते की सबसे मज़ेदार बात कैसे बना सकते हो।”</p>\n<p>नैना अब भी उसी वर्दी में थी, जिसमें पूरे दिन का बोझ लेकर आई थी। केस वही था, सवाल वहीं थे; विक्रम ने उनमें से किसी का जवाब नहीं दिया था।</p>\n<p>विक्रम ने बस इतना किया था कि जब तक नैना के भीतर वह सब था, उसे अकेले ढोने नहीं दिया।</p>\n<p>शाम और गहरी हो चुकी थी। बेंच के ऊपर पुराना गुलमोहर चुपचाप फैला था और नैना अब भी विक्रम की गोद में सिर रखे लेटी थी।</p>\n<p>इस बार दोनों को उस चुप्पी से बाहर आने की कोई जल्दी नहीं थी।</p>\n<p>गुलमोहर उन दोनों से कहीं पुराना था। अपने धीमे, जड़ों वाले ढंग से उसने सीख लिया था कि एक साधारण शाम और वज़न वाली शाम में क्या फ़र्क़ होता है।</p>\n<p>उसने इन दोनों को अजनबी बनकर आते देखा था, महीनों पहले—दो आवाज़ें, जिन्हें आख़िर शरीर मिले थे, उसकी तब लगभग नंगी शाखाओं के नीचे झिझकते हुए, सँभल-सँभलकर बैठते हुए। तब से हर मुलाक़ात की छोटी-छोटी गर्माहट उसकी जड़ों में जमा होती आई थी: एक हाथ, जो दूसरे हाथ तक पहुँचा; एक हँसी, जो ज़रूरत से ज़्यादा ज़ोर से निकल गई; एक चुप्पी, जिसमें शब्दों से ज़्यादा था।</p>\n<p>और आज यह—एक लड़की, वर्दी में ही, दिन भर का सारा बोझ लिए एक आदमी की गोद में सिर रखे लेटी थी।</p>\n<p>उसने बेंच के ऊपर ख़ुद को वैसे ही थामे रखा, जैसे इससे पहले की हर ऐसी कहानी के ऊपर थामा था—चुपचाप, धीरज से, जो कुछ देखता उसे अपने भीतर वैसे ही समेटता, जैसे जड़ें पानी समेटती हैं। उसे नहीं पता था कि यह कहानी कैसे ख़त्म होगी।</p>\n<p>बस इतना चाहता था—बहुत शिद्दत से—कि इस बार, इन दोनों के लिए, उसकी शाखाओं की ये कोंपलें पूरे फूल बन सकें।</p>\n<p>उसे अभी पता नहीं था कि वह इनसे कितना माँगने वाला है।</p>"}, {"chapter": 14, "title": "अध्याय 12 — एक बोझ, दो कंधे", "content": "<h1>अध्याय 12 — एक बोझ, दो कंधे</h1>\n<p>छुट्टी के करीब तीन हफ्ते गुज़र चुके थे और इन दिनों में विक्रम और नैना के बीच मिलने-जुलने की वह शुरुआती औपचारिकता लगभग ख़त्म हो गई थी, जिसमें हर मुलाक़ात के लिए कोई जगह, कोई वक्त और कोई बहाना पहले से तय करना पड़ता है। अब कभी शाम अपने-आप उन्हें एक जगह ले आती, कभी एक फोन आधे घंटे की बातचीत बन जाता और कभी मिलने निकले तो पता ही नहीं चलता कि दो घंटे कहाँ चले गए।</p>\n<p>इसीलिए जब विक्रम अचानक बदल गया, नैना को समझने में ज़्यादा वक्त नहीं लगा।</p>\n<p>बदलाव की वजह एक फोन था।</p>\n<p>कश्मीर से।</p>\n<p>उस शाम स्क्रीन पर कैप्टन रुद्र प्रताप सिंह का नाम देखकर विक्रम ने सहजता से फोन उठाया था। रुद्र उसके ही ट्रूप, 23 राष्ट्रीय राइफल्स, में था—कमांडो ट्रेनिंग के दिनों का साथी। विक्रम छुट्टी पर घर आ गया था और रुद्र पीछे कश्मीर में ही रह गया था; मगर फौज की कुछ दोस्तियाँ ऐसी होती हैं जिनमें न दूरी फ़ासला बनती है, न महीनों की ख़ामोशी—अगली बार बात होती है तो आदमी वहीं से शुरू करता है जहाँ पिछली बार छोड़ा था।</p>\n<p>लेकिन उस रात रुद्र ने कुछ शुरू नहीं किया।</p>\n<p>दूसरी तरफ से बस कुछ वाक्य आए—छोटे, सीधे, बिना किसी भूमिका के। विक्रम चुप रह गया। लाइन पर हल्की सरसराहट थी, जिसमें रुद्र की भारी चुप्पी दबी थी।</p>\n<p>वे चंद वाक्य उसके भीतर कहीं उतरते रहे, बिना किसी आवाज़ के—जैसे गहरे कुएँ में फेंका पत्थर, जिसके तल से टकराने की आवाज़ बहुत देर बाद आती है।</p>\n<p>फोन कटने के बाद विक्रम वहीं बैठा रहा। न जाने कितनी देर।</p>\n<p>हाथ में फोन की स्क्रीन धीरे-धीरे बुझ गई, और कमरे का अँधेरा उसके और उस एक नाम के बीच आकर बैठ गया।</p>\n<p>उस रात उसने खाना नहीं खाया। भूख सचमुच नहीं थी, इसलिए ख़ुद से कोई बहाना भी नहीं बनाना पड़ा।</p>\n<p>नैना को फोन करने का ख़याल आया ज़रूर, मगर विक्रम ने फोन नहीं किया।</p>\n<p>अगली शाम उससे मिला तो जैसे अपने साथ आधा ही पहुँचा था। सामने नैना बैठी थी, बीच में खाना रखा था, आसपास लोगों की आवाज़ें थीं; वह हर बात सुन भी रहा था और उसका जवाब भी दे रहा था, फिर भी उसका एक हिस्सा लगातार कहीं और अटका हुआ था।</p>\n<p>नैना ने पहली शाम कुछ नहीं कहा।</p>\n<p>दूसरी शाम नैना ने काँटा प्लेट में रख दिया।</p>\n<p>“क्या हुआ है?” नैना ने पूछा।</p>\n<p>“कुछ नहीं।”</p>\n<p>नैना ने पहले उसकी तरफ देखा, फिर लगभग अछूती पड़ी प्लेट की तरफ।</p>\n<p>“ये ‘कुछ नहीं’ खाना भी नहीं खाता क्या?”</p>\n<p>विक्रम ने नज़र उठाई।</p>\n<p>“भूख नहीं है।”</p>\n<p>“तुम्हें भूख नहीं है?”</p>\n<p>नैना के लहजे में चिंता थी, मगर अब उसके नीचे हल्की नाराज़गी भी उतर आई थी।</p>\n<p>“कल से देख रही हूँ। तीन निवाले खाते हो, बाकी प्लेट में घुमाते रहते हो। बात करो तो आधा जवाब देते हो। सामने बैठे हो, मगर दिमाग कहीं और है।”</p>\n<p>विक्रम फिर चुप रहा।</p>\n<p>नैना कुछ देर उसका चेहरा पढ़ती रही।</p>\n<p>“तुम्हारी परेशानी से मुझे शिकायत नहीं है, विक्रम। शिकायत ये है कि जैसे ही परेशानी तुम्हारी होती है, तुम मुझे बाहर खड़ा कर देते हो।”</p>\n<p>“ऐसी कोई बात नहीं है।”</p>\n<p>“है।”</p>\n<p>इस बार नैना ने विक्रम को बात टालने का मौका नहीं दिया।</p>\n<p>“मैंने तुम्हें अपने बारे में ऐसी बातें बताई हैं जो शायद किसी और से कभी नहीं कही। उस दिन मैं वर्दी समेत तुम्हारे पास चली आई थी क्योंकि मुझे पता था कि तुम सुनोगे। लेकिन तुम्हारी बारी आती है तो तुम इतने आराम से अपने भीतर दरवाज़ा बंद कर लेते हो जैसे मुझे मालूम ही नहीं पड़ेगा।”</p>\n<p>एक नाम विक्रम के होंठों तक आया।</p>\n<p>बस नाम कह देना था।</p>\n<p>फिर बाकी सब अपने-आप निकल आता—रुद्र का फोन, रिज लाइन, वे छह किलोमीटर, वह आदमी जिसके होने की उसे ऐसी आदत थी कि कभी उसके न होने की कल्पना ही नहीं की।</p>\n<p>मगर विक्रम फिर पीछे हट गया।</p>\n<p>“पुरानी बात है। तुमसे मिलने से पहले की।”</p>\n<p>नैना के चेहरे पर जो आया, वह गुस्सा कम और चोट ज़्यादा थी।</p>\n<p>“मैंने ये नहीं पूछा कि बात तुमसे मिलने से पहले की है या बाद की।”</p>\n<p>वह कुछ पल रुकी।</p>\n<p>“मैं बस चाहती हूँ कि जब तुम किसी मुश्किल जगह पर हो तो मुझे दरवाज़े के बाहर मत छोड़ो।”</p>\n<p>उसके बाद उस शाम में कुछ खास बचा नहीं।</p>\n<p>नैना चली गई।</p>\n<p>विक्रम दो ठंडी प्लेटों के सामने बैठा रहा और पहली बार ख़ुद से यह सवाल ठीक तरह से पूछा कि आख़िर वह नैना को बता क्यों नहीं पा रहा।</p>\n<p>अगले दिन न उसका फोन गया, न नैना का आया।</p>\n<p>वह ख़ामोशी ज़रूरी थी।</p>\n<p>उसी में विक्रम को अपने डर की असली शक्ल दिखाई दी।</p>\n<p>वह नैना पर भरोसा नहीं करता—बात ऐसी बिल्कुल नहीं थी। डर बस इतना था कि जो दुःख वह अकेले उठा रहा है, उसे बाँटते ही नैना के हिस्से में भी हर रोज़ थोड़ा-सा खौफ आ जाएगा और एक दिन वह उससे थक जाएगी।</p>\n<p>एक दोस्त को वह खो चुका था; नैना को खो देने का वहम भी उस वक्त उसे बर्दाश्त नहीं था।</p>\n<p>वह दिन भी निकल गया।</p>\n<p>उस पूरे दिन उसने ठीक से खाना भी नहीं खाया, और उसे ख़ुद इसका एहसास तब हुआ जब शाम ढले वह बिना फोन किए नैना के दरवाज़े पर जा खड़ा हुआ।</p>\n<p>दरवाज़ा खुला।</p>\n<p>नैना ने उसे देखा। चेहरे पर पिछली नाराज़गी की परछाईं अभी बाकी थी, मगर दो ही पल में नैना की नज़र विक्रम के धँसे हुए चेहरे पर टिक गई।</p>\n<p>“आख़िरी बार खाना कब खाया था?”</p>\n<p>“याद नहीं।”</p>\n<p>“विक्रम।”</p>\n<p>“शायद… दो दिन।”</p>\n<p>बस इतना सुनना था।</p>\n<p>नैना ने न डाँटा, न कोई सवाल किया। पलटी और रसोई में चली गई।</p>\n<p>विक्रम कमरे में अकेला बैठा रहा। बाहर सड़क का शोर रात उतरने के साथ धीमा हो चुका था। नीचे कहीं किसी ठेले वाले ने घंटी बजाई—दो बार—फिर आवाज़ दूर चली गई। कुछ देर में रसोई से जीरे और गर्म होती दाल की खुशबू कमरे में फैलने लगी।</p>\n<p>नैना लौटी तो हाथ में एक प्लेट थी।</p>\n<p>दाल। चावल।</p>\n<p>जो घर में था।</p>\n<p>नैना ने प्लेट विक्रम के सामने रखी।</p>\n<p>“खाओ।”</p>\n<p>“पहले मेरी बात सुनो।”</p>\n<p>“सुनूँगी।”</p>\n<p>“नैना—”</p>\n<p>“विक्रम, दो दिन से भूखे हो। पहले पहला निवाला खाओ, फिर जितना बोलना है बोलते रहना। इस बात पर बहस नहीं होगी।”</p>\n<p>नैना ने जिस अंदाज़ में कहा, उसमें बहस की गुंजाइश सचमुच नहीं थी।</p>\n<p>विक्रम ने चम्मच उठा लिया।</p>\n<p>पहले कुछ कौर सिर्फ नैना की खातिर उतरे। फिर जैसे पेट को याद आया कि उससे दो दिनों से उसकी राय पूछी ही नहीं गई थी। भूख लौट आई और खाने की रफ्तार अपने-आप बढ़ गई।</p>\n<p>नैना सामने बैठी रही।</p>\n<p>न कोई सवाल।</p>\n<p>न जल्दी।</p>\n<p>जब प्लेट का अच्छा-खासा हिस्सा ख़त्म हो गया, नैना ने बहुत सहजता से कहा—</p>\n<p>“अब बताओ।”</p>\n<p>विक्रम ने चम्मच प्लेट में रख दिया।</p>\n<p>कुछ क्षण नैना की तरफ देखा।</p>\n<p>फिर कहा—</p>\n<p>“रेड्डी शहीद हो गया।”</p>\n<p>इतने दिनों से भीतर अटके हुए सच को बाहर आने के लिए बस इतने ही शब्द चाहिए थे।</p>\n<p>वेंकटेश श्रीनिवास रेड्डी—सिर्फ तेईस साल का, आंध्र प्रदेश के अनंतपुर जिले के छोटे-से गाँव लेपाक्षी का रेड्डी; 23 राष्ट्रीय राइफल्स में विक्रम के साथ रहे सबसे अच्छे कमांडो में से एक; वह आदमी जो अपनी खैर बताने से पहले अपने साथियों की कुशलता पूछता था—अब नहीं था।</p>\n<p>रुद्र ने जैसा बताया था, विक्रम वही दोहराता गया। एम्बुश था। रिज लाइन थी। फ़ैसला लेने के लिए एक पल से भी कम वक्त मिला था और नतीजा किसी भी तरफ जा सकता था।</p>\n<p>मगर गया सिर्फ एक तरफ।</p>\n<p>इसके बाद बात किसी तरतीब में नहीं निकली।</p>\n<p>कभी रुद्र का फोन आया, कभी वह रिज लाइन; फिर अचानक विक्रम छह किलोमीटर पीछे चला गया—उस दिन तक, जब रेड्डी ने बिना पूछे उसका पैक अपने कंधे पर उठा लिया था।</p>\n<p>“छह किलोमीटर चला था मेरा सामान लेकर,” विक्रम ने कहा। “ढलान पर पैर फिसला और फ्रैक्चर हो गया। मैं उसी के सहारे घिसटता रहा, और अपना बोझ ढोते हुए उसने मेरा भी उठा लिया। मैंने माँगा भी नहीं था।”</p>\n<p>नैना सुनती रही।</p>\n<p>“बाद में मैंने पूछा, क्यों उठाया था? बोला—‘साहब, आप पैर से कम और बैग से ज़्यादा परेशान दिख रहे थे। सोचा, एक की तकलीफ़ तो कम कर दूँ।’”</p>\n<p>विक्रम के होंठों पर बहुत हल्की मुस्कान आई।</p>\n<p>बस एक पल।</p>\n<p>फिर चली गई।</p>\n<p>“ऐसा था वो।”</p>\n<p>उसके बाद कुछ देर कमरे में ख़ामोशी रही।</p>\n<p>नैना ने उसे तोड़ा नहीं।</p>\n<p>“उस रात मुझे क्यों नहीं बताया?” नैना ने आख़िर पूछा।</p>\n<p>विक्रम ने इस बार जवाब से बचने की कोशिश नहीं की।</p>\n<p>“डर गया था।”</p>\n<p>“मुझसे?”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“तुम्हारे डर से।”</p>\n<p>नैना की भौंहें हल्की-सी सिकुड़ीं।</p>\n<p>“अगर मैं तुम्हें रेड्डी के बारे में बता देता, तो अगली बार जब भी मैं कहीं जाता… तुम सिर्फ मेरी पोस्टिंग के बारे में नहीं सोचतीं। तुम्हें पता होता कि वहाँ क्या हो सकता है। किसी का नाम होता तुम्हारे पास। चेहरा होता।”</p>\n<p>वह थोड़ी देर चुप रहा।</p>\n<p>“मुझे लगा फिर हर बार फोन देर से आएगा तो तुम डरोगी। हर ऑपरेशन की ख़बर पर डरोगी। और शायद एक दिन…”</p>\n<p>“एक दिन?”</p>\n<p>विक्रम ने उसकी आँखों में देखा।</p>\n<p>“शायद एक दिन तुम्हें लगे कि मुझसे प्यार करना इस डर के लायक नहीं है।”</p>\n<p>नैना बहुत देर तक कुछ नहीं बोली।</p>\n<p>फिर उठकर उसके पास आ बैठी।</p>\n<p>“मेरी एक बात ध्यान से सुनो।”</p>\n<p>विक्रम उसकी तरफ मुड़ा।</p>\n<p>“मैं कितना डर सह सकती हूँ, कितना दुःख उठा सकती हूँ और किस बात के बाद भाग जाऊँगी—ये सारे फ़ैसले तुम मेरी तरफ से मत लिया करो।”</p>\n<p>नैना के लहजे में तल्ख़ी नहीं थी। इसीलिए बात और भीतर गई।</p>\n<p>“तुम्हें लगता है मुझे बाहर रखोगे तो बचा लोगे। लेकिन फिर होता क्या है? तुम अकेले अंदर बैठे रहते हो और मैं बाहर खड़ी सोचती रहती हूँ कि आख़िर हुआ क्या है। इसे हिफ़ाज़त मत समझो, विक्रम। ये सिर्फ दो लोगों का अलग-अलग अकेला होना है।”</p>\n<p>विक्रम ने नज़रें झुका लीं।</p>\n<p>नैना ने उसकी खाली होती प्लेट की ओर देखा।</p>\n<p>“और ये दो दिन भूखे रहने वाला तमाशा दोबारा मत करना। इससे मुझे एक बात की जगह दो बातों का डर लगेगा—एक तुम्हारी पोस्टिंग का, दूसरा तुम्हारी अक्ल का।”</p>\n<p>विक्रम के चेहरे पर इस बार मुस्कान कुछ देर ठहरी।</p>\n<p>नैना का स्वर भी थोड़ा नरम पड़ गया।</p>\n<p>“रेड्डी की बात सुनकर मुझे डर लगा है। बहुत साफ़ बात है—लगा है। आगे तुम ऐसी जगह रहोगे जहाँ मैं तुम तक नहीं पहुँच सकती, तो शायद ये सब याद भी आए।”</p>\n<p>नैना ने विक्रम का हाथ अपने हाथ में ले लिया।</p>\n<p>“लेकिन मुझे सच के साथ डरना मंज़ूर है। झूठी तसल्ली के साथ जीना नहीं।”</p>\n<p>विक्रम कुछ कहता, उससे पहले नैना ने आगे कहा—</p>\n<p>“और तुमने दोस्त खोया है। अभी तुम्हारा दुःख तुम्हारा है। मेरे डर का बोझ भी अपने सिर पर रखकर मत बैठो। मुझे मेरे हिस्से का ख़ुद उठाने दो।”</p>\n<p>इसी एक बात ने विक्रम के भीतर बची हुई आख़िरी गिरह भी खोल दी—जैसे भीतर का वह दरवाज़ा, जिसे वह सिर्फ अंदर से बंद करना जानता था, पहली बार किसी और के सामने खुल गया।</p>\n<p>वह नैना की ओर झुक गया।</p>\n<p>नैना ने उसे बाँहों में ले लिया।</p>\n<p>कुछ दिन पहले गुलमोहर के नीचे वह ख़ुद इसी तरह उसके पास आई थी—थकी हुई, परेशान, अपने भीतर जमा एक सवाल लेकर। तब विक्रम ने उसे कोई जवाब नहीं दिया था; बस अपने पास जगह दी थी।</p>\n<p>आज वही जगह नैना की बाँहों में विक्रम के लिए थी।</p>\n<p>विक्रम ने सिर नैना के कंधे पर रख दिया।</p>\n<p>दो रातों की अधूरी नींद, भूख और भीतर दबाए रखा दुःख जैसे एक साथ शरीर पर उतर आए। नैना का हाथ उसकी गर्दन के पीछे था। कुछ देर बाद विक्रम और करीब खिसक आया, सिर उसकी छाती से लग गया और नैना की उँगलियाँ बिना कुछ कहे उसके बालों में चलने लगीं।</p>\n<p>“आज मेरे सामने ख़ुद को सँभालने की ज़रूरत नहीं है,” नैना ने बहुत धीमे कहा।</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>पहली बार विक्रम को किसी ने यह इजाज़त दी थी।</p>\n<p>या इजाज़त हमेशा थी और उसने कभी ख़ुद को दी ही नहीं थी।</p>\n<p>कुछ देर बाद वह नैना की गोद में सिर रखे लेटा था।</p>\n<p>नैना ने उसके चेहरे पर हाथ रखा। अंगूठा थकी हुई आँखों के नीचे से बहुत हल्के से गुज़रा।</p>\n<p>फिर नैना ने पूछा—</p>\n<p>“रेड्डी कैसा था?”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“मतलब?”</p>\n<p>“कैसे मरा, ये बता चुके हो। मैं पूछ रही हूँ—था कैसा?”</p>\n<p>विक्रम जवाब देने ही वाला था, फिर रुक गया।</p>\n<p>इतने बरसों की दोस्ती में से किसी आदमी को निकालकर दो-चार वाक्यों में कैसे बताया जाए?</p>\n<p>कुछ देर बाद उसके चेहरे पर फीकी-सी मुस्कान आई।</p>\n<p>“पागल कम था, बहादुर ज़्यादा था।”</p>\n<p>विक्रम की आँखों के सामने वह पूरा आदमी खड़ा हो गया—चौड़े कंधे, तगड़ा बदन, पूरा कमांडो।</p>\n<p>“स्वभाव से नम्र, बोलचाल में शालीन—और एक्शन में सबसे आगे,” विक्रम ने कहा। “ऑपरेशन में न कभी डरा, न कभी पीछे हटा। जिस दरवाज़े पर सब एक पल को रुकते, पहला कदम उसी का होता था।”</p>\n<p>नैना भी हल्का मुस्कराई, जैसे इन वाक्यों से रेड्डी की पहली झलक उसे मिल गई हो।</p>\n<p>“अच्छा। आगे बताओ।”</p>\n<p>और न जाने क्यों सबसे पहले विक्रम को वह गेट याद आया।</p>\n<p>कमांडो ट्रेनिंग के बाद दोनों लगभग एक साथ 23 राष्ट्रीय राइफल्स में पोस्ट हुए थे—एक ऐसा संयोग, जिसकी कीमत आदमी को बाद में समझ आती है। पहली शाम दोनों अपने किट बैग लेकर, जिनसे अब भी रेल के सफ़र की गंध आ रही थी, उस गेट तक पहुँचे थे। गेट की मेहराब के ऊपर एक खोपड़ी बनी थी, उसके जबड़े के आर-पार लंबी खुखरी धँसी हुई और दाँत ऐसे निकले हुए जैसे वह आने वालों पर हँस रही हो।</p>\n<p>“हम दोनों नीचे खड़े उसे देख रहे थे,” विक्रम ने कहा। “रेड्डी ने धीरे से पूछा—‘साहब, ये हमारा स्वागत कर रही है या पहले ही दिन हमारी औकात बता रही है?’”</p>\n<p>नैना हँस दी—रेड्डी के उस सवाल पर, जो उसने सीधे खोपड़ी से पूछ लिया था।</p>\n<p>“फिर?” नैना ने पूछा।</p>\n<p>“संतरी ने हमारी शक्ल देख ली। नीचे लगी प्लेट दिखाई।”</p>\n<p>पीतल की उस छोटी-सी प्लेट के अक्षर बरसों से वहाँ ठहरती निगाहों ने घिसकर चिकने कर दिए थे। विक्रम को आज भी वे शब्द याद थे—</p>\n<p><b>थोड़ा मुस्कराओ। स्वागत है—तुम हेड हंटर्स में हो।</b></p>\n<p>“रेड्डी वहीं हँस पड़ा था—बिना किसी घबराहट के, खुलकर।”</p>\n<p>विक्रम भी मुस्कराया।</p>\n<p>महीनों बाद, कुछ ऑपरेशनों के बाद, विक्रम को समझ आया था कि वह खोपड़ी किसी पर हँस नहीं रही थी। वह अपनी उस हालत में भी मुस्कराने का रास्ता ढूँढ़ चुकी थी—और हर गुज़रते आदमी से चुपचाप पूछती थी: जो अब भी पूरा है, जीता-जागता है, वह इतना भी क्यों नहीं कर सकता?</p>\n<p>रेड्डी यह विक्रम से हमेशा बेहतर कर पाता था। आख़िरी दिन तक, ज़्यादातर दिनों, वह कर भी लेता था।</p>\n<p>फिर यादें खुलती चली गईं—बिना किसी सिलसिले के, जैसे बरसों से बंद संदूक में रखी चीज़ें एक-एक करके हाथ लगती जाएँ।</p>\n<p>कभी कोई बर्फीली पोस्ट याद आती जहाँ ट्रूप की दाल बनते ही रेड्डी तड़के पर अपना हक जमा लेता था। उस छोटे-से भगोने के सामने उसका रौब ऐसा होता जैसे पूरी यूनिट की इज़्ज़त उसी तड़के पर टिकी हो; रैंक का फ़र्क़ जितनी इजाज़त देता था, वह इस रस्म को उससे कहीं ज़्यादा गंभीरता से निभाता था।</p>\n<p>कभी किसी पेट्रोलिंग के बाद मिली पूड़ियाँ याद आतीं।</p>\n<p>कभी उसकी बेसिर-पैर की बातें, जिन पर सबसे पहले और सबसे ज़्यादा वही ख़ुद हँसता था।</p>\n<p>कभी वह जमा देने वाली रात जब आग के पास बैठने की बारी रेड्डी की थी, मगर वह बिना कुछ कहे उठ गया और विक्रम को अपनी जगह की आँच दे गया।</p>\n<p>“अगले दिन मैंने कहा, बड़ी मेहरबानी की कल।”</p>\n<p>“क्या बोला?”</p>\n<p>“बोला—‘कौन-सी मेहरबानी, साहब? आप ऐसे काँप रहे थे कि आपको देखकर मुझे ठंड लगने लगी थी।’”</p>\n<p>नैना की हँसी इस बार थोड़ी देर रही—रेड्डी के उस जवाब पर, जिसमें उसने अपनी मेहरबानी को ठंड का बहाना बना दिया था।</p>\n<p>विक्रम भी हँसा।</p>\n<p>और वही सबसे तकलीफ़देह था—किसी मर चुके आदमी की कोई बात याद करके अचानक हँस पड़ना और अगले ही पल याद आ जाना कि अब वह आदमी ख़ुद कभी नहीं हँसेगा।</p>\n<p>विक्रम की मुस्कान धीरे-धीरे बुझ गई।</p>\n<p>“माँ-बाप का इकलौता बेटा था।”</p>\n<p>नैना का हाथ उसके बालों में चलता रहा।</p>\n<p>“और उसकी शादी होने वाली थी।”</p>\n<p>हाथ एक पल को थमा।</p>\n<p>“कब?”</p>\n<p>“जल्दी। छुट्टी पर जाने वाला था।”</p>\n<p>कुछ क्षण बाद नैना ने पूछा—</p>\n<p>“लड़की?”</p>\n<p>“सुजाता।”</p>\n<p>नाम कहते ही विक्रम की आवाज़ का रंग बदल गया।</p>\n<p>“उसी के गाँव की थी। बचपन से साथ पढ़े थे। दोनों घर भी एक-दूसरे को जानते थे।”</p>\n<p>“तुमने उसे देखा था?”</p>\n<p>“फोटो में।”</p>\n<p>विक्रम की आँखें कहीं और चली गईं, जैसे वह तस्वीर इतने महीनों बाद भी उसके सामने रखी हो।</p>\n<p>“लंबे बाल थे। मोटी-सी चोटी बनाती थी… और मुस्कराती थी तो आँखों से पता चलता था कि सच में हँस रही है।”</p>\n<p>नैना चुप रही।</p>\n<p>विक्रम भी कुछ देर चुप रहा, फिर ख़ुद ही आगे बोला—</p>\n<p>“रेड्डी उसके बारे में बड़ी छोटी-छोटी बातें बताता था। कहता था, मेरी माँ का मूड मुझसे ज़्यादा उसे समझ आता है। घर में किसी को कुछ चाहिए हो तो पूछने से पहले पकड़ लेती है। दो साल से अपनी दादी वाला सांभर बनाना सीख रही थी क्योंकि ‘रेड्डी साहब’ को वही पसंद था।”</p>\n<p>“रेड्डी साहब?”</p>\n<p>“ख़ुद को यही कहता था—सुजाता की बात करते वक्त।”</p>\n<p>नैना के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“बहुत प्यार करता था?”</p>\n<p>विक्रम ने बिना सोचे कहा—</p>\n<p>“बेइंतहा।”</p>\n<p>इस बार कमरे में जो ख़ामोशी उतरी, वह पहले जैसी नहीं थी।</p>\n<p>छुट्टी पर आने से कुछ ही दिन पहले रेड्डी ने विक्रम से कहा था कि वह शादी के लिए छुट्टी पर जाने वाला है। फिर हँसी-मज़ाक में बोला था—‘देखते हैं साहब, पहले घोड़ी कौन चढ़ता है।’</p>\n<p>उस वक्त बात इतनी मामूली थी कि दोनों हँसकर आगे बढ़ गए थे।</p>\n<p>अब वही मज़ाक याद आया तो विक्रम की आँखें बंद हो गईं।</p>\n<p>“अब कोई शादी नहीं होगी।”</p>\n<p>नैना की उँगलियाँ उसके बालों में और धीमी हो गईं।</p>\n<p>“पता नहीं सुजाता को ख़बर मिल गई होगी या…”</p>\n<p>वाक्य बीच में रह गया।</p>\n<p>विक्रम ने उस लड़की को कभी देखा नहीं था, सिर्फ एक तस्वीर में; फिर भी उस रात वह बार-बार उसके बारे में सोच रहा था। लेपाक्षी में कहीं एक लड़की, जिसने आने वाले महीनों को शादी के हिसाब से बाँट रखा होगा—क्या लेना है, क्या पहनना है, कौन आएगा, छुट्टी कब मिलेगी—और फिर एक ख़बर ने उन सारी छोटी-बड़ी तैयारियों को एक ही पल में बेमानी कर दिया होगा।</p>\n<p>विक्रम ने गहरी साँस ली।</p>\n<p>“और उसके माँ-बाप…”</p>\n<p>अब आवाज़ में थकान थी।</p>\n<p>“इकलौता बेटा था, नैना। सेना मेडल मिला था उसे। उसकी फोटो शायद हर रिश्तेदार को दिखाई होगी उन्होंने। कितने गर्व से बताते होंगे कि हमारा बेटा वहाँ पोस्टेड है…”</p>\n<p>उसकी आवाज़ फिर अटक गई।</p>\n<p>नैना का हाथ उसके गाल पर आ गया।</p>\n<p>“और अब वही बेटा एक ऐसी रिज पर रह गया, जिसे उसके माँ-बाप ने कभी देखा तक नहीं,” विक्रम ने कहा।</p>\n<p>कुछ पल विक्रम बिल्कुल शांत पड़ा रहा।</p>\n<p>फिर बहुत धीमे बोला—</p>\n<p>“अजीब है न… ख़बर सुनते ही आदमी शब्द समझ जाता है। ‘नहीं रहा’ का मतलब भी जानता है। फिर भी अंदर कहीं बहुत देर तक लगता रहता है कि नहीं… ऐसा कैसे हो सकता है।”</p>\n<p>नैना ने कोई तसल्ली नहीं दी।</p>\n<p>रेड्डी वापस नहीं आने वाला था और उस सच के सामने कोई तसल्ली काफी भी नहीं थी।</p>\n<p>वह बस विक्रम के साथ बैठी रही।</p>\n<p>कभी उसके बालों में हाथ फेरती, कभी माथे पर; और विक्रम जब किसी याद पर रुक जाता तो उसे आगे बोलने के लिए नहीं कहती। कुछ देर बाद वह ख़ुद दूसरी याद से शुरू हो जाता।</p>\n<p>उस रात रेड्डी की मौत की कहानी धीरे-धीरे रेड्डी के जीने की कहानी बन गई।</p>\n<p>कभी दोनों हँसे।</p>\n<p>कभी बहुत देर चुप रहे।</p>\n<p>कभी विक्रम की आवाज़ भर्रा गई और इस बार उसने उसे छिपाने के लिए चेहरा दूसरी तरफ नहीं किया।</p>\n<p>दुःख कम नहीं हुआ था।</p>\n<p>सुबह होने तक भी रेड्डी मरा ही रहने वाला था। लेपाक्षी में उसके माँ-बाप के घर का एक कमरा खाली ही रहने वाला था। सुजाता की शादी नहीं होने वाली थी।</p>\n<p>नैना इनमें से कुछ बदल नहीं सकती थी।</p>\n<p>उसने कोशिश भी नहीं की।</p>\n<p>बस जिस दुःख को विक्रम इतने दिनों से अपने भीतर बंद करके बैठा था, अब उसमें वह अकेला नहीं था।</p>\n<p>नैना की गोद में सिर रखे, उसकी उँगलियों की धीमी हरकत महसूस करते हुए विक्रम को उस रात एक बहुत साधारण-सी बात समझ आई—जिसे वह अपनी पूरी फौजी ज़िंदगी में नहीं समझ पाया था।</p>\n<p>हर बोझ अकेले उठा लेना मज़बूती नहीं होती।</p>\n<p>कुछ बोझ ऐसे भी होते हैं जिन्हें कोई आपसे छीन नहीं सकता, न आधा कर सकता है; लेकिन अगर कोई अपना बिना कुछ कहे आपके साथ उस वज़न के नीचे कंधा लगा दे—जैसे किसी भारी बल्ली के नीचे दूसरा कंधा आ जाए—तो रास्ता थोड़ा कम तन्हा ज़रूर हो जाता है।</p>\n<p>उस रात नैना ने रेड्डी के जाने का दुःख कम नहीं किया।</p>\n<p>उसने बस विक्रम को उसमें अकेला नहीं रहने दिया।</p>\n<p>जैसे कभी रेड्डी ने छह किलोमीटर विक्रम का पैक उठाया था—बिना माँगे, बिना जताए।</p>\n<p>मगर उस राहत के नीचे कहीं एक छोटा, ठंडा ख़याल उभरा, जिसे वह फिर नीचे नहीं रख पाया—दुःख को एक बार पूरा भीतर आने दो, तो वह शायद ही कभी एक बार आकर रुकता है।</p>\n<p>विक्रम ने यह कहा नहीं।</p>\n<p>बस नैना को थोड़ा और कसकर पकड़ लिया—जैसे इतना भर कर देने से वह ख़याल कभी सच न हो पाए।</p>"}, {"chapter": 15, "title": "अध्याय 13 — एक दोस्त की शादी", "content": "<h1>अध्याय 13 — एक दोस्त की शादी</h1>\n<p>रेड्डी के जाने के बाद के दिनों में नैना ने विक्रम के भीतर आई ख़ामोशी को धीरे-धीरे उतरते देखा था। दुःख कहीं गया नहीं था, बस अब हर वक्त उसके चेहरे पर बैठा नहीं रहता था। वह फिर हँसने लगा था, खाने की मेज़ पर बहस करने लगा था और कभी-कभी नैना की किसी बेवकूफ़ी पर उसी पुराने अंदाज़ में सिर हिलाकर मुस्करा भी देता था।</p>\n<p>इसीलिए नैना ने उस शाम को थोड़ा पहले से सँभालकर रखना चाहा।</p>\n<p>उसने तीन दिन पहले एक रेस्तराँ में टेबल बुक कर दी।</p>\n<p>यह उसके मिज़ाज के बिल्कुल उलट था। वह उन लोगों में नहीं थी जो शाम को पहले से सजाकर रखते हैं—कहाँ जाना है, कितने बजे पहुँचना है, कौन-सी टेबल चाहिए। मगर इस बार उसने विक्रम को कुछ बताए बिना तय किया था कि उसे एक ऐसी शाम देगी जिसमें किसी ख़तरे का ज़िक्र न हो, किसी बात का हिसाब न लगाना पड़े और दोनों को कुछ देर के लिए किसी चीज़ से जूझना न पड़े।</p>\n<p>बस एक अच्छी शाम।</p>\n<p>बिना किसी वजह के।</p>\n<p>रेस्तराँ गुरुग्राम की नई ऊँची इमारतों में से एक की ऊपरी मंज़िल पर था। शीशे की बड़ी-बड़ी खिड़कियों के उस पार आधा बन चुका शहर रात में दूर तक फैला दिखाई देता था; कहीं रोशन इमारतें थीं, कहीं अधूरे ढाँचे और उनके बीच खड़ी क्रेनें, जिन पर लगी छोटी बत्तियाँ अँधेरे में टिमटिमा रही थीं—जैसे अजीब-से, धीरज वाले पंछी, जो रात भर शहर के बनने का इंतज़ार कर रहे हों।</p>\n<p>अंदर सफ़ेद मेज़पोश, धीमी रोशनी और इतनी नपी-तुली ख़ामोशी थी कि सामने वाले को सुनने के लिए आवाज़ ऊँची करने की ज़रूरत नहीं पड़ती थी। रसोई का दरवाज़ा खुलता तो मक्खन और भुनते मसालों की खुशबू कुछ पल के लिए हवा में घुल जाती।</p>\n<p>जगह नैना ने चुनी थी और यही बात विक्रम को सबसे ज़्यादा हैरान कर रही थी।</p>\n<p>“क्या देख रहे हो?”</p>\n<p>“सोच रहा हूँ तुम्हें अचानक इतनी शरीफ जगह कैसे पसंद आ गई।”</p>\n<p>“मुझे शरीफ जगह पसंद नहीं आई। मुझे ऊपर से शहर देखना पसंद है।”</p>\n<p>उसने शीशे के पार इशारा किया।</p>\n<p>“देखो इसे। दो साल पहले इसमें से आधा था ही नहीं। मुझे अच्छा लगता है कि शहर आदमी की आँखों के सामने बदलता रहता है।”</p>\n<p>विक्रम ने बाहर देखा।</p>\n<p>नैना ने धीरे से कहा—</p>\n<p>“शायद इसलिए कि फिर लगता है कोई चीज़ हमेशा वैसी रहने के लिए मजबूर नहीं है जैसी कभी थी।”</p>\n<p>विक्रम की नज़र बाहर से लौटकर उसके चेहरे पर आ गई।</p>\n<p>वह बात शहर के बारे में कह रही थी।</p>\n<p>विक्रम ने उसे शहर के बारे में ही रहने दिया।</p>\n<p>शाम बढ़ती गई तो विक्रम को एक और बात महसूस हुई। यह पहली बार था जब वे किसी ऐसी जगह बैठे थे जहाँ उन्हें देखकर किसी को उनके रिश्ते का अंदाज़ा लगाने की ज़रूरत नहीं पड़ती। सामने से देखने पर वे ठीक वही लग रहे थे जो अब थे—दो लोग जिन्हें एक-दूसरे की मौजूदगी पसंद थी और जिन्हें फिलहाल इस बात की कोई जल्दी नहीं थी कि दुनिया उस रिश्ते को क्या नाम देती है।</p>\n<p>नैना ने उसे तीसरी बार आसपास देखते पकड़ लिया।</p>\n<p>“किसे ढूँढ़ रहे हो?”</p>\n<p>“किसी को नहीं।”</p>\n<p>“फिर बार-बार दरवाज़ा क्यों देख रहे हो?”</p>\n<p>विक्रम हल्का-सा मुस्कराया।</p>\n<p>“पुरानी आदत।”</p>\n<p>“आज छुट्टी दे दो अपनी पुरानी आदतों को। यहाँ न कोई हमें जानता है, न किसी को फ़र्क़ पड़ता है।”</p>\n<p>इतना कहकर नैना ने बिना पूछे विक्रम की प्लेट से नान का एक टुकड़ा उठा लिया।</p>\n<p>“और आज एक शाम मुझे ऐसी चाहिए जिसमें तुम हर जगह से बाहर निकलने का रास्ता नापते न रहो।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“तुम मेरी प्लेट से खाना चुराना कब बंद करोगी?”</p>\n<p>“जिस दिन तुम अपनी प्लेट में मेरे लिए ख़ुद रख दिया करोगे।”</p>\n<p>“मतलब कभी नहीं।”</p>\n<p>“तो फिर शिकायत मत करना।”</p>\n<p>रेस्तराँ से निकले तो रात काफी हो चुकी थी। आसपास की ऊँची इमारतों में कहीं-कहीं ही रोशनी बची थी और सड़क पर दिन वाला शोर नहीं था। चलते हुए नैना ने बिना कुछ कहे अपना हाथ उसके हाथ में डाल दिया।</p>\n<p>विक्रम ने भी कुछ नहीं कहा।</p>\n<p>कुछ रिश्तों में एक वक्त के बाद हाथ पकड़ना कोई घटना नहीं रह जाता।</p>\n<p>बस चलते समय हाथ वहीं चला जाता है जहाँ उसकी आदत पड़ चुकी होती है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>शादी का न्योता नैना की ट्रेनिंग बैच की एक दोस्त का था। शादी गुरुग्राम में ही थी और इतनी बड़ी कि एक अतिरिक्त मेहमान पर किसी की नज़र टिकने वाली नहीं थी।</p>\n<p>नैना ने ख़ुद कहा था—</p>\n<p>“मेरे साथ चलोगे?”</p>\n<p>“किस हैसियत से?”</p>\n<p>“प्लस वन।”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“इतना आधुनिक?”</p>\n<p>“ज़्यादा खुश मत हो। मेरे घर का कोई आदमी वहाँ नहीं होगा। मेरी तरफ से बस ट्रेनिंग वाले कुछ लोग होंगे। इसलिए तुम्हें ले जा रही हूँ।”</p>\n<p>“मतलब सुरक्षित इलाका है।”</p>\n<p>“बिल्कुल। तुम्हें मेरे साथ किसी शादी में देखने का इससे आसान ट्रायल नहीं मिल सकता।”</p>\n<p>शादी वाले दिन विक्रम ने अपना इकलौता ढंग का कुर्ता निकाला।</p>\n<p>वेन्यू पर पहुँचकर विक्रम ने नैना को प्रवेश द्वार के पास खड़ा देखा तो उसके कदम अपने-आप एक पल के लिए धीमे पड़ गए।</p>\n<p>नैना ने गहरे हरे रंग का लहँगा पहन रखा था—उसी हरे का, जो उस गुलमोहर की नई कोंपलों में उतर रहा था—जिसके घेर और ब्लाउज़ पर सुनहरी कढ़ाई रोशनी पड़ते ही चमक उठती थी। ड्यूटी पर हमेशा बँधे या क्लिप में समेटे रहने वाले उसके बाल आज खुले थे—घने, लंबे, कमर से नीचे तक उतरते हुए और सिरों पर हल्के घुँघराले; चलते समय वे उसकी पीठ पर लहराते तो आसपास की झालरों की रोशनी उनमें अटक जाती।</p>\n<p>आँखों में गहरा काजल था, होंठों पर हल्का सुर्ख रंग।</p>\n<p>विक्रम उसे देखता रह गया।</p>\n<p>खूबसूरत वह पहले भी थी। बात यह थी कि उसने नैना को हमेशा किसी हरकत के बीच देखा था—कभी तेज़-तेज़ बोलते, कभी बहस करते, कभी हँसते, कभी वर्दी में कहीं पहुँचने की जल्दी में। उसे यूँ सामने खड़े होकर देखने का मौका ही कम मिला था, जहाँ कुछ पल के लिए वह सिर्फ नैना थी और विक्रम के पास उसे देखने के अलावा कोई दूसरा काम नहीं था।</p>\n<p>“तुम…”</p>\n<p>नैना ने तुरंत हाथ उठा दिया।</p>\n<p>“आगे मत बोलना।”</p>\n<p>“क्यों?”</p>\n<p>“सोमवार को जिन लोगों के साथ मुझे ड्यूटी करनी है, उनके सामने मुझे शर्मिंदा मत करो।”</p>\n<p>विक्रम हँस पड़ा—ड्यूटी की उस चिंता पर, जो इस क्षण भी नैना का पीछा नहीं छोड़ रही थी।</p>\n<p>नैना ने उसकी बाँह पकड़ी और भीतर खींच लिया।</p>\n<p>“चलो।”</p>\n<p>उसकी चूड़ियाँ खनकीं और वह आगे बढ़ गई।</p>\n<p>शाम सचमुच उतनी ही आसान निकली जितनी नैना ने कही थी। ट्रेनिंग बैच के कुछ पुराने साथी थे—अपनापन था, जिज्ञासा भी, मगर किसी ने विक्रम को कटघरे में खड़ा करके सवाल-जवाब शुरू नहीं किए। उल्टा ज़्यादातर मज़ा नैना को छेड़ने में लिया जा रहा था।</p>\n<p>“हमने तो उम्मीद छोड़ दी थी,” उसकी एक साथी ने हँसते हुए कहा। “तीन साल से जो रिश्ता आया, मैडम ने मना किया। और आज ख़ुद एक लड़के को साथ लेकर पहुँची हैं।”</p>\n<p>नैना ने बिना झिझके जवाब दिया—</p>\n<p>“उन सबको मैंने मना किया था। इसे नहीं किया। फ़र्क़ है।”</p>\n<p>सामने वाली ने विक्रम को ऊपर से नीचे तक देखा, मगर उस नज़र में जाँच कम, मज़ाक ज़्यादा था।</p>\n<p>“आर्मी?” उसने विक्रम से पूछा।</p>\n<p>“हाँ। पैरा एसएफ़।”</p>\n<p>पास खड़ी दो और सहेलियों की भौंहें एक साथ ऊपर चढ़ गईं।</p>\n<p>“वाओ,” एक ने आँखें फैलाकर कहा। “पैरा एसएफ़?”</p>\n<p>“वैसे देखकर लगता भी है,” दूसरी ने विक्रम की सीधी पीठ और चौड़े कंधों पर नज़र फिराते हुए धीमे से कहा।</p>\n<p>नैना ने भौंह उठाकर दोनों को घूरा, पर उसके होंठों के कोने पर छिपी मुस्कान को कोई रोक नहीं पाया।</p>\n<p>“तभी,” सामने वाली ने जैसे अपनी कोई शंका पक्की करते हुए कहा, फिर नैना की तरफ देखकर मुस्कराई, “अब समझ आया मैडम ने तीन साल में किसी को भाव क्यों नहीं दिया।”</p>\n<p>“ज़्यादा मत सोच,” नैना ने तुरंत टोका। “बस ये बाकी लोगों से थोड़ा कम परेशान करता है।”</p>\n<p>“अच्छा?”</p>\n<p>“अभी तक तो।”</p>\n<p>विक्रम दोनों की बातें सुनकर मुस्कराता रहा।</p>\n<p>“मेरे सामने ही मेरी खूबियाँ गिनाई जा रही हैं?”</p>\n<p>नैना ने उसकी तरफ देखा। “खूबियाँ कहाँ गिनाईं? मैंने तो सिर्फ इतना कहा है कि अभी तक झेला जा सकता है।”</p>\n<p>“बहुत मेहरबानी।”</p>\n<p>“वेलकम।”</p>\n<p>उसकी सहेली हँस पड़ी—दोनों की इस नोक-झोंक पर। “ठीक है, अब समझ आया तुम दोनों की बन कैसे रही है।”</p>\n<p>खाने-पीने और हँसी-मज़ाक के बीच कब डीजे शुरू हो गया, पता ही नहीं चला। मंडप से कुछ दूर बड़े-बड़े स्पीकर लगे थे और पहली तेज़ बीट के साथ ही नैना के साथियों ने उसे पकड़ लिया।</p>\n<p><b>गजबण पानी नै चाली</b> बजते ही कई लोग एक साथ खुले हिस्से की ओर निकल गए।</p>\n<p>नैना ने पलटकर विक्रम की बाँह खींची।</p>\n<p>“चलो।”</p>\n<p>“मैं नहीं नाचता।”</p>\n<p>“तुमसे किसने कहा अच्छा नाचना है?”</p>\n<p>“दोनों बातें लगभग एक ही हैं।”</p>\n<p>“पहले देखो। फिर जितना हो सके उतना कर लेना।”</p>\n<p>विक्रम किनारे खड़ा रहा तो नैना वापस आई और इस बार उसका हाथ नहीं, कुर्ते की बाँह पकड़कर उसे भीड़ में खींच लाई।</p>\n<p>“बस कंधे हिलाओ। कोई तुम्हारा कोर्ट मार्शल नहीं करेगा।”</p>\n<p>उसने कोशिश की।</p>\n<p>बहुत ख़राब कोशिश।</p>\n<p>नैना ने मुँह फेरकर हँसी रोकने की कोशिश की, फिर कोशिश छोड़कर खुलकर हँस पड़ी।</p>\n<p>“इतना बुरा?”</p>\n<p>“तुम गोली चला लेना। नाचने का काम मैं कर लूँगी।”</p>\n<p>नैना उससे कुछ कदम दूर थी। आसपास बाकी लोग भी उसी खुले, बेफ़िक्र अंदाज़ में नाच रहे थे—हाथ हवा में, कंधे ताल पर, कोई किसी का स्टेप देखकर हँस रहा था, कोई अपनी ही धुन में था। छूने की ज़रूरत नहीं थी। नैना और विक्रम के बीच भी कुछ कदम का फ़ासला बना रहा, मगर कभी-कभी एक नज़र उस दूरी को इतनी आसानी से पार कर जाती कि पास आने की ज़रूरत ही नहीं पड़ती।</p>\n<p>विक्रम कोई स्टेप बिगाड़ता तो नैना भौंह उठाकर उसे देखती।</p>\n<p>वह जानबूझकर वही ग़लती दोबारा करता।</p>\n<p>और फिर वह हँसती।</p>\n<p>जब डीजे ने <b>बावन गज का घाघरा</b> लगा दिया तो आसपास ऐसा शोर उठा जैसे पूरी मंडली उसी गाने का इंतज़ार कर रही हो। नैना की सहेलियाँ उसे फिर बीच में खींच ले गईं।</p>\n<p>विक्रम इस बार किनारे नहीं गया।</p>\n<p>वहीं खड़ा उसे देखता रहा।</p>\n<p>दूर मंडप में हवन की आग धीमी पड़ चुकी थी, पर हवा में उसकी आँच अब भी बाकी थी।</p>\n<p>खुले बाल हर बार घूमने पर उसके साथ घूमते, चूड़ियाँ रोशनी पकड़तीं, कभी स्टेप बिगड़ जाता तो वह ख़ुद पर ही हँस पड़ती। उसके चेहरे पर उस समय न ड्यूटी थी, न किसी केस का बोझ, न घर-परिवार की कोई फ़िक्र और न यह हिसाब कि कल क्या होगा।</p>\n<p>सिर्फ खुशी थी।</p>\n<p>बिल्कुल बेफ़िक्र।</p>\n<p>विक्रम ने उसे गुस्से में देखा था, थका हुआ देखा था, परेशान देखा था; गुलमोहर के नीचे अपनी गोद में सिर रखे, भीतर से टूटते हुए भी देखा था।</p>\n<p>मगर नैना को यूँ सिर्फ खुश होते हुए उसने पहली बार देखा था।</p>\n<p>और न जाने क्यों वही रूप उसे सबसे ज़्यादा भीतर तक छू गया।</p>\n<p>वह उसके चेहरे का हर झुकाव याद करता रहा—वह खास ढंग, जिससे वह अपने ही बिगड़े स्टेप पर हँसती थी—जैसे उसका कोई हिस्सा पहले से जानता हो कि किसी ठंडी रात, यहाँ से बहुत दूर, उसे यह रूप फिर बुलाना पड़ेगा।</p>\n<p>वह उसे देखता रहा।</p>\n<p>नैना घूमते हुए अचानक उसकी तरफ हुई और दोनों की नज़र मिली।</p>\n<p>नैना के कदम की ताल एक पल को बिगड़ गई।</p>\n<p>विक्रम की आँखों में इस बार वह रोज़ वाली ठहरी हुई नरमी नहीं थी। कुछ ज़्यादा खुला हुआ था—कुछ ऐसा, जिसे उसने ख़ुद भी अभी कोई नाम नहीं दिया था।</p>\n<p>नैना ने कुछ नहीं पूछा।</p>\n<p>बस उस नज़र को अपने भीतर कहीं रख लिया और अगले ही पल फिर संगीत में लौट गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>शादी ख़त्म होने से पहले ही दोनों निकल आए।</p>\n<p>पार्किंग तक आते-आते पीछे बजता संगीत धीमा होकर दूर की आवाज़ बन चुका था। मंडप की झालरों से बची कुछ रोशनियाँ पार्किंग तक चली आई थीं और नैना के खुले बालों में अब भी झालरों की सुनहरी रोशनी की हल्की चमक अटकी हुई थी।</p>\n<p>“आने के लिए थैंक यू,” नैना ने चलते हुए कहा। “मुझे पता है शादी में जाना किसी का पसंदीदा शौक नहीं होता।”</p>\n<p>“ये वाली बुरी नहीं थी,” विक्रम ने कहा।</p>\n<p>“मेरे लोग अच्छे हैं।”</p>\n<p>“उम्मीद से ज़्यादा,” विक्रम ने कहा।</p>\n<p>नैना ने उसे कोहनी मारी।</p>\n<p>“मेरे दोस्तों के बारे में तुम्हारी उम्मीद इतनी ख़राब क्यों थी?”</p>\n<p>“पुलिस वालों की शादी थी,” विक्रम ने कहा।</p>\n<p>“तुम आर्मी वाले हो।”</p>\n<p>“इसीलिए अनुभव से बोल रहा हूँ,” विक्रम ने कहा।</p>\n<p>नैना हँस दी—फौज और पुलिस की उस पुरानी खींचतान पर।</p>\n<p>फिर कुछ नरम होकर बोली—</p>\n<p>“अच्छा लगा कि तुमने मेरे इस हिस्से को भी देखा। बिना छह मौसियों और चार चाचाओं के तुम्हारी नीयत पूछे।”</p>\n<p>“वो भी होगा?”</p>\n<p>“अगर बात वहाँ तक पहुँची तो बहुत होगा।”</p>\n<p>वाक्य हल्का था।</p>\n<p>दोनों ने उसे हल्का ही रहने दिया।</p>\n<p>विक्रम उसे घर छोड़ने गया। रास्ते भर शहर लगभग शांत रहा, मगर विक्रम की अपनी ख़ामोशी अब पहले जैसी नहीं थी।</p>\n<p>उस दोपहर आया एक फोन उसके भीतर तब से रखा था।</p>\n<p>विक्रम ने तय किया था कि शादी से पहले नहीं बताएगा।</p>\n<p>कम-से-कम यह शाम नैना से नहीं छीनेगा।</p>\n<p>उसकी बिल्डिंग के नीचे पहुँचकर दोनों एकमात्र जलती स्ट्रीट लाइट के पास रुके तो विक्रम ने आख़िर कहा—</p>\n<p>“ऊपर जाने से पहले एक बात बतानी है।”</p>\n<p>नैना की मुस्कान उसी क्षण हल्की पड़ गई।</p>\n<p>“क्या हुआ?”</p>\n<p>“आज दोपहर कॉल आया था।”</p>\n<p>वह रुक गया।</p>\n<p>“मुझे जल्दी वापस रिपोर्ट करना है। साठ दिन पूरे नहीं होंगे।”</p>\n<p>नैना ने कुछ नहीं कहा।</p>\n<p>विक्रम उसके चेहरे पर आते-जाते भाव देखता रहा।</p>\n<p>“कब?”</p>\n<p>“कल सुबह।”</p>\n<p>बस इतना।</p>\n<p>नैना ने न पूछा कहाँ, न क्यों, न यह कि कोई ख़तरा है या नहीं।</p>\n<p>नैना एक कदम आगे बढ़ी और अपनी बाँहें विक्रम के चारों ओर डाल दीं।</p>\n<p>इस बार आधा-अधूरा नहीं।</p>\n<p>पूरा।</p>\n<p>उसका गाल विक्रम की छाती से लगा था और विक्रम की बाँहें उसकी पीठ के चारों ओर थीं। कुछ देर दोनों वैसे ही खड़े रहे—एक साधारण विदाई के लिए ज़रूरत से थोड़ी ज़्यादा देर, मगर यह साधारण विदाई थी भी कहाँ।</p>\n<p>“जाओ,” नैना ने आख़िर उसकी कमीज़ में मुँह छिपाए हुए कहा। “जो करना है, करो।”</p>\n<p>फिर उसकी पकड़ थोड़ी और कस गई।</p>\n<p>“बस पूरे वापस आना। मुझे और कुछ नहीं चाहिए।”</p>\n<p>विक्रम ने ठुड्डी उसके सिर पर रख दी। उसके बालों में परफ्यूम के साथ शादी की अगरबत्ती और धुएँ की बहुत हल्की-सी मिली-जुली खुशबू अब भी थी।</p>\n<p>“वापस आऊँगा।”</p>\n<p>“मुझे पता है।”</p>\n<p>नैना उससे थोड़ा अलग हुई।</p>\n<p>आँखों में नमी थी, मगर आवाज़ स्थिर।</p>\n<p>“मैं अपने ही घर के नीचे रोकर इसे और मुश्किल नहीं बनाऊँगी। बस सावधान रहना। और जैसे ही मौका मिले, फोन करना।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>फिर माथे को चूमा।</p>\n<p>बहुत हल्के से।</p>\n<p>उस स्पर्श में चाहत से ज़्यादा भरोसा था—जैसे वह विदा नहीं ले रहा, लौटने की बात वहीं छोड़कर जा रहा हो।</p>\n<p>नैना ने उसे जाने दिया।</p>\n<p>विक्रम गाड़ी में बैठा तो वह वहीं खड़ी रही, दोनों बाँहें अपने चारों ओर समेटे हुए। गाड़ी दूर निकल गई, तब वह मुड़ी और अकेली सीढ़ियाँ चढ़ने लगी।</p>\n<p>कुछ देर पहले तक वही रात रोशनी, संगीत और हँसी से भरी हुई थी।</p>\n<p>अब उसी रात में उसकी ग़ैरमौजूदगी की ठंड उतरने लगी थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कुछ हफ्तों बाद नैना घर गई तो विक्रम का ज़िक्र पहली बार उसकी माँ के सामने ठीक से आया।</p>\n<p>नैना ने उस दिन बताने की कोई तैयारी नहीं की थी। फोन रसोई की मेज़ पर खुला छूट गया था और स्क्रीन पर शादी की एक तस्वीर थी—हरे और सुनहरे रंग की रोशनी के बीच नैना के साथ खड़ा विक्रम।</p>\n<p>माँ प्लेटें समेटते हुए रुकीं।</p>\n<p>तस्वीर देखी।</p>\n<p>फिर नैना की तरफ।</p>\n<p>“कौन है?”</p>\n<p>एक सवाल के बाद छिपाने जैसा कुछ खास बचा नहीं।</p>\n<p>नैना ने बाकी तस्वीरें भी दिखा दीं। एक छोटा-सा वीडियो भी, जिसमें दोनों शादी में नाचने की नाकाम कोशिश के बीच हँस रहे थे।</p>\n<p>माँ ने वीडियो दो बार देखा।</p>\n<p>फिर फोन मेज़ पर रख दिया।</p>\n<p>“लड़का ठीक लगता है।”</p>\n<p>नैना ने इससे ज़्यादा की उम्मीद नहीं की थी, फिर भी उसके चेहरे पर हल्की मुस्कान आ गई।</p>\n<p>माँ ने वह मुस्कान देख ली।</p>\n<p>“मैंने सिर्फ इतना कहा है कि ठीक लगता है। ये नहीं कहा कि मुझे सब मंज़ूर है।”</p>\n<p>मुस्कान थोड़ी कम हुई।</p>\n<p>“मैंने मंज़ूरी माँगी भी नहीं।”</p>\n<p>“नहीं माँगी। लेकिन तस्वीरें दिखाईं, वीडियो दिखाया। कहीं न कहीं चाहती तो थी कि मैं उसे पसंद करूँ।”</p>\n<p>उनकी आवाज़ में डाँट नहीं थी। चिंता थी—उस तरह की, जिसमें माँ सामने खड़ी बेटी से ज़्यादा उन रास्तों को देख रही होती है जिनसे बेटी अभी गुज़री ही नहीं।</p>\n<p>“नैना, तू इक्कीस साल की है। इस उम्र में अपने दिल की बात बहुत साफ़ लगती है। हो सकता है तू बिल्कुल सही हो। लेकिन मैंने तेरी उम्र की लड़कियों को किसी आदमी में इतनी दूर तक जाते देखा है कि बाद में उन्हें फ़र्क़ ही नहीं समझ आता—सामने वाला सच में कैसा है और वे उसे कैसा देखना चाहती हैं।”</p>\n<p>“विक्रम सिर्फ अच्छा चेहरा नहीं है, माँ।”</p>\n<p>“मैंने ऐसा कहा भी नहीं।”</p>\n<p>माँ ने कुछ पल रुककर शब्द चुने।</p>\n<p>“मैं बस कह रही हूँ कि तू अभी उसके बहुत करीब है। और जब दिल बहुत करीब चला जाए न, तो आँखें कभी-कभी थोड़ा कम देखती हैं।”</p>\n<p>नैना ने जवाब नहीं दिया।</p>\n<p>“तेरे पापा ने अभी उसका नाम तक नहीं सुना। सुनेंगे तो पहला सवाल क्या होगा, तू जानती है। कौन है? कहाँ का है? जात क्या है? परिवार कैसा है? अपनी बिरादरी में लोग क्या कहेंगे कि लड़की अपनी मर्ज़ी से किसी आर्मी वाले के साथ घूम रही है, जिससे घरवालों ने मिलवाया तक नहीं।”</p>\n<p>नैना की नज़र मेज़ पर पड़े फोन पर चली गई।</p>\n<p>“मुझे पता है।”</p>\n<p>“तो फिर आगे की बात भी समझती है।”</p>\n<p>माँ की आवाज़ इस बार और नरम हो गई।</p>\n<p>“बाकी सब सँभालने से पहले अपने दिल को सँभालकर रखना, बेटा।”</p>\n<p>नैना चुप रही।</p>\n<p>माँ ने उसके चेहरे को देखा और वहीं समझ गईं कि यह चेतावनी कुछ देर से आई है।</p>\n<p>“अगर तू इस लड़के में बहुत दूर चली गई और बात वहाँ तक नहीं पहुँची जहाँ तू चाहती है—चाहे वजह उसका घर हो, हमारा घर हो या बीच में खड़ी कोई और दीवार—चोट तुझे लगेगी। मुझे नहीं। उसे भी शायद नहीं। सबसे ज़्यादा तुझे।”</p>\n<p>नैना की साँस एक पल को अटक गई।</p>\n<p>मगर उसी के साथ उसका वह ज़िद्दी हिस्सा भी जागा जो हर डर के सामने पहले सवाल करता था—क्यों?</p>\n<p>“मैं आपकी बात समझ रही हूँ, माँ।”</p>\n<p>वह रुकी।</p>\n<p>फिर पहली बार ख़ुद से भी बिना बचते हुए बोली—</p>\n<p>“लेकिन मैं ये झूठ नहीं बोलूँगी कि अभी बहुत शुरुआत है। शायद मैं काफी आगे जा चुकी हूँ।”</p>\n<p>माँ ने लंबी साँस छोड़ी।</p>\n<p>उसमें नाराज़गी कम थी, फ़िक्र ज़्यादा।</p>\n<p>“फिर मैं सिर्फ इतना कह सकती हूँ कि दिल जहाँ जाना चाहता है, जाए… मगर आँखें खुली रखना। माँ आख़िर इससे ज़्यादा कर भी क्या सकती है।”</p>\n<p>नैना ने कोई जवाब नहीं दिया।</p>\n<p>क्योंकि कुछ जवाब उस वक्त उसके पास थे भी नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कई हजार मील दूर बैठी सुनैना ने वही तस्वीरें और वही वीडियो कुछ दिन बाद अपने फोन पर देखे। नैना ने ख़ुद भेजे थे।</p>\n<p>सुनैना की राय माँ से कहीं लंबी थी, हालाँकि उस समय उसका ज़्यादातर हिस्सा उसने अपने मन में ही रख लिया।</p>\n<p>नैना ने उस शाम विक्रम को फोन किया।</p>\n<p>“मैंने माँ को तुम्हारे बारे में बता दिया।”</p>\n<p>“सब?”</p>\n<p>“सब मतलब जितना अभी बताने लायक है। लड़का है। आर्मी में है। नाम विक्रम है। चेहरा भी दिखा दिया।”</p>\n<p>“फ़ैसला?”</p>\n<p>“उम्मीद से बेहतर। उन्हें तुम शरीफ लगे।”</p>\n<p>“ये बड़ी उपलब्धि है?”</p>\n<p>“मेरी माँ के हिसाब से बहुत बड़ी।”</p>\n<p>विक्रम हँसा—‘शरीफ’ को उपलब्धि की तरह सुनकर।</p>\n<p>नैना की आवाज़ फिर थोड़ी गंभीर हुई।</p>\n<p>“लेकिन उन्हें लगता है मैं तुम्हारे बहुत करीब हूँ, इसलिए शायद साफ़ नहीं देख रही। और उन्होंने मुझे याद दिलाया कि अगर ये कभी… आगे गया, तो रास्ते में कितनी चीज़ें खड़ी हो सकती हैं।”</p>\n<p>“जैसे?”</p>\n<p>“परिवार। जात। लोग। बाबा। बाकी दुनिया।”</p>\n<p>कुछ पल ख़ामोशी रही।</p>\n<p>फिर नैना ने कहा—</p>\n<p>“उन्होंने पूछा, तुमसे कब मिलेंगी।”</p>\n<p>विक्रम ने जवाब देने में देर नहीं की।</p>\n<p>“मैं मिलना चाहूँगा।”</p>\n<p>नैना चुप रही।</p>\n<p>विक्रम ने नैना के स्वर में छिपी झिझक पहचान ली।</p>\n<p>“जब तुम सच में तैयार हो। सिर्फ इसलिए नहीं कि माँ के सामने बहादुर बनने के लिए कह दिया।”</p>\n<p>“मैं बहादुर हूँ।”</p>\n<p>“मुझे पता है।”</p>\n<p>“नहीं। तुम्हें ये भी पता होना चाहिए कि कभी-कभी बहादुर रहने के लिए मुझे मेहनत करनी पड़ती है।”</p>\n<p>विक्रम मुस्कराया—उस ईमानदारी पर, जो अपनी कमज़ोरी भी नहीं छिपाती।</p>\n<p>“वो भी पता है।”</p>\n<p>फोन कटने के बाद नैना के चेहरे पर मुस्कान थी।</p>\n<p>मगर माँ का एक शब्द उसके भीतर कहीं अटका रह गया था—</p>\n<p><b>रुकावटें।</b></p>\n<p>उसने चाहा कि उस पर ज़्यादा न सोचे।</p>\n<p>फिर भी जाने-अनजाने वह गिनने लगी कि अगर यह रिश्ता सचमुच उस मंज़िल की तरफ बढ़ा, जिसकी कल्पना अब दोनों ने कभी-कभी चुपचाप करनी शुरू कर दी थी—</p>\n<p>तो उनके बीच कितनी दीवारें खड़ी हो सकती थीं।</p>\n<p>जैसे विक्रम ने कभी उँगलियों पर दिन गिने थे, वैसे ही नैना की उँगलियाँ अब दीवारें गिनने लगी थीं।</p>"}, {"chapter": 16, "title": "अध्याय 14 — खोपड़ी फिर से हँसी", "content": "<h1>अध्याय 14 — खोपड़ी फिर से हँसी</h1>\n<p>दोपहर के उस कॉल का ज़िक्र उसने नैना से आधा ही किया था।</p>\n<p>फोन पर रुद्र का नाम आया तो विक्रम बरामदे में खड़ा था।</p>\n<p>“सुल्तान गंजा,” रुद्र ने कहा। “हिज़्बुल का एरिया कमांडर। रेड्डी को उसकी टोली ने मारा।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>“रामबन-बनिहाल, गाँव सुम्बड़ा। इंटेलिजेंस रिपोर्टें हैं कि उसे वहीं-कहीं देखा गया है। गाँव में हमारे सोर्स हैं। चार-पाँच उसके साथ हैं। सीओ शर्मा साहब कह चुके हैं, इसने हमारे बच्चों को बहुत तंग किया है।”</p>\n<p>“सर, आप?”</p>\n<p>“मैं नहीं जा पाऊँगा। शर्मा साहब ने मुझे दूसरी ड्यूटी पर भेज दिया। कमान तुम्हारी। आ सकते हो?”</p>\n<p>विक्रम ने रेलिंग पर हाथ रखा।</p>\n<p>“आ रहा हूँ। कल यूनिट में हूँगा।” फिर धीरे से, “छोड़ेंगे नहीं, सर। रेड्डी का बदला लिए बिना न उसे शांति मिलेगी, न हमें।”</p>\n<p>रात को, गली की बत्ती के नीचे, उसने नैना को विदा किया था। उसने बहुत कुछ नहीं कहा, बस इतना कि कल सुबह जाना है। जो असली बात थी, वह भीतर ही रह गई, जैसे कोई चिट्ठी जो लिखी तो गई हो, पर डाक में न डाली गई हो।</p>\n<p>वह बात यह थी: प्यार के लिए वक्त बाद में भी मिल जाएगा। उसके आगे पूरी ज़िंदगी पड़ी है। गुलमोहर इंतज़ार कर सकता है, बदला नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>यूनिट में पहुँचकर उसने पहली बात यही तय की कि इंतज़ार यूनिट में नहीं होगा।</p>\n<p>ब्रीफिंग हॉल में नक़्शा दीवार पर था और तीस-पैंतीस जवान सामने। विक्रम यूनिट की घातक टुकड़ी, यानी विशेष टीम, का कमांडर था, और ये सभी जवान उसकी अपनी टीम के थे। वे उसे जानते थे। उसकी काबिलियत पर उन्हें पहले से भरोसा था, और उसके आने की ख़बर मिलते ही यूनिट में जोश फैल गया था। जो कल तक थके दिखते थे, आज सीधे बैठे थे। हॉल में दबी हुई फुसफुसाहट थी: “राठौड़ साहब आ गए हैं, अब तो हो ही जाएगा।”</p>\n<p>यह भरोसा बेवजह नहीं था। 23 राष्ट्रीय राइफल्स में घातक टुकड़ी का कमांडर विक्रम जब भी अपनी पार्टी को लेकर निकला, बिना शिकार किए कभी यूनिट नहीं लौटा। चाहे पाँच दिन लगे हों या दस, एक महीना या दो महीने, वह टीम को जंगलों में ही रखता, ख़ाक छानता, जब तक कोई आतंकी न मार लेता। उसके साथ गई पार्टी खाली हाथ नहीं लौटती थी। यही उसकी साख थी, और यूनिट का हर जवान यह जानता था।</p>\n<p>“सुम्बड़ा!” विक्रम ने नक़्शे पर उँगली ठोकी। “बारह घंटे पैदल। तीस-पैंतीस जवान चाहिए, और हम पूरे हैं!”</p>\n<p>एक सूबेदार खड़ा हुआ। “सर, सोर्स की ख़बर का इंतज़ार करें?”</p>\n<p>“नहीं! हम पहले जाएँगे। गाँव से एक घंटे की दूरी पर छिपेंगे। एक दिन लगे या चार, बर्फ़ में, बिना आग, बिना आवाज़!”</p>\n<p>उसने जवानों को एक-एक करके देखा।</p>\n<p>“कोई शक? कोई शंका? जिसे हो, यहीं रुक जाए!”</p>\n<p>एक पल की ख़ामोशी रही। फिर पूरा हॉल एक साथ गरजा:</p>\n<p>“नो सर!”</p>\n<p>“आवाज़ नहीं आई!”</p>\n<p>“नो सर!!”</p>\n<p>हॉल में जोश चरम पर था। सभी जवान बदला चाहते थे। रेड्डी उनका भी साथी था, और हर मुट्ठी भिंची हुई थी, हर आँख में एक ही बात थी: जब तक सुल्तान गंजा नहीं मिलता, कोई पीछे नहीं हटेगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>रात का मार्च बारह घंटे चला।</p>\n<p>न कोई सड़क थी, न सड़क का किनारा, न कोई गाड़ी। रात के अँधेरे में सीधे जंगल के रास्तों से, बिना एक शब्द बोले, कतार चुपचाप आगे बढ़ती रही। विक्रम सबसे आगे था। उसका हाथ उठता तो पूरी कतार रुक जाती, गिरता तो चल पड़ती।</p>\n<p>उत्तर की रात थी, और उत्तर की रात अपनी ठंड को ढोल बजाकर नहीं, चुपके से उतारती है। हवा चीड़ की सुइयों में सीटी-सी बजाती हुई घाटी में दौड़ती, और कभी सूखे पत्तों की सरसराहट बनकर पाँवों के नीचे बिछ जाती। साँसें सफ़ेद धुएँ की तरह मुँह से निकलकर रात में खो जाती थीं। मूँछों और भौंहों पर पाला जमने लगा था। ऊपर आसमान में तारे इतने पास थे कि लगता था हाथ उठाओ तो उँगलियों से छू जाएँगे, और उतने ही ठंडे।</p>\n<p>जंगल जहाँ बर्फ़ से ढका था, वहाँ उसने कतार नाले के पत्थरों पर उतार दी। इशारे से, बिना बोले: बर्फ़ में पाँव के निशान रह जाते हैं, गीले पत्थर निशान नहीं रखते। नाला अपने ऊपर जमी बर्फ़ की परत के नीचे धीमे-धीमे बुदबुदा रहा था, जैसे पहाड़ अपनी नींद में कुछ कह रहा हो। पाँव फिसलते रहे, पर निशान कहीं नहीं छूटा।</p>\n<p>तीसरे घंटे में एक जवान लड़खड़ा गया। विक्रम ने बिना कुछ कहे उसका पैक अपने कंधे पर उठा लिया और आगे चल दिया। उस कंधे पर बोझ रेड्डी का भी था, पर यह किसी को पता नहीं था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>गाँव से एक घंटा पहले, पौ फटने से पहले, उसने कतार रोक दी।</p>\n<p>“यहीं।”</p>\n<p>जवान बर्फ़ में गड्ढे खोदकर उतर गए और ऊपर सफ़ेद चादरें खींच लीं। चट्टानों के पीछे दो निगरानी चौकियाँ बनीं। रेडियो पर सिर्फ सुनना था, बोलना नहीं।</p>\n<p>न आग थी, न धुआँ। राशन सूखा था, पानी बर्फ़ पिघलाकर।</p>\n<p>दिन निकलता तो धूप बर्फ़ पर पड़कर आँखों में चुभती, और रात उतरती तो हवाएँ तेज़ हो जातीं, इतनी तेज़ कि सफ़ेद चादरों को फाड़ ले जाना चाहतीं। शरीर काँपते थे। दाँत बजते थे, जबड़े भींचकर उन्हें चुप कराना पड़ता। पलकों पर पाला जम जाता, और बर्फ़ गिरती तो जवान धीरे-धीरे सफ़ेद टीलों में बदल जाते, जिन्हें पास से गुज़रने वाला भी पहचान न पाता। दूसरे दिन से ठंड हड्डियों में उतरने लगी, उँगलियाँ सुन्न होने लगीं, कुछ के पैर सूजने लगे।</p>\n<p>विक्रम हर रात रेंगकर हर जवान के पास गया। मोज़े छूकर देखता कि गीले हैं या सूखे। जिसके गीले निकलते, उसे अपना सूखा जोड़ा दे देता। बस इतना कहता, “पैर सूखे रखो।”</p>\n<p>अपनी निगरानी की पाली उसने किसी को नहीं दी। दूरबीन से रात-रात भर गाँव देखता रहा: किस घर का दरवाज़ा कब खुलता है, कुत्ते कब भौंकते हैं।</p>\n<p>“साहब, तीन रात से पलक नहीं झपकाई,” सूबेदार रणजीत सिंह ने कहा।</p>\n<p>“वह मिलेगा, तब।”</p>\n<p>तीसरे दिन की शाम सोर्स ने छत पर तय रंग का कपड़ा टाँगा: सुल्तान गंजा गाँव में है, ठिकाना पक्का नहीं। चौथी रात के आख़िरी पहर में कपड़ा दो जगह टँगा। ऊपर वाला पक्का घर, वही कमरा।</p>\n<p>विक्रम ने नक़्शा खोला। उसकी उँगली गाँव पर नहीं, पीछे के नाले पर थी।</p>\n<p>“नाला। भागेगा तो यहीं से। यहाँ मैं, तीन रोक-दल मेरे साथ। खोज-दल रणजीत के साथ। उत्तर में ढलान है, वह दक्षिण में आएगा।”</p>\n<p>आधे घंटे में तीस-पैंतीस जवान चार दिशाओं में बँट गए। दो-दो रोक-दल पूरब और उत्तर में, एक पश्चिम में, ऊपर निगरानी चौकी, पीछे रिज़र्व। गाँव ऐसे बँध गया जैसे उस पर किसी ने मुट्ठी कस ली हो।</p>\n<p>नाले के किनारे बैठकर विक्रम ने रेडियो पर कहा, “सब चौकियाँ पुष्टि करें।”</p>\n<p>एक-एक कर आवाज़ें आईं।</p>\n<p>“खोज-दल आगे बढ़े।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले तीन मिनट में सब हो गया।</p>\n<p>दरवाज़ा खुलते ही अंदर से गोलियाँ चलीं। खिड़की से तीन आकृतियाँ पिछवाड़े कूदीं और नाले की तरफ दौड़ीं, ठीक उसी रास्ते पर जिसे विक्रम ने उनके लिए खुला छोड़ा था। रोक-दल से टकराते ही दो वहीं गिर गए। तीसरा ढलान पर लुढ़कता रहा।</p>\n<p>फिर सुल्तान गंजा आया। उसके आगे एक बुज़ुर्ग औरत थी, जिसे उसने बाँह से खींचकर ढाल बना रखा था।</p>\n<p>“कोई गोली नहीं,” विक्रम ने रेडियो पर कहा। उसकी आवाज़ बिल्कुल सामान्य थी।</p>\n<p>वह औरत को घसीटता हुआ एक-एक कदम पीछे हटा। विक्रम उसके ठीक ऊपर की चट्टान पर था। औरत की चुन्नी हवा में उड़ी, उसका सिर ज़रा झुका, और सुल्तान गंजा का कंधा ओट से बाहर आ गया।</p>\n<p>एक गोली चली।</p>\n<p>वह सुल्तान गंजा का जान लेने वाला निशाना नहीं था। गोली उसके कंधे में लगी, ठीक वहाँ जहाँ विक्रम ने चाही थी। हथियार उसके हाथ से छूट गया और वह औरत को छोड़कर घुटनों के बल बर्फ़ पर गिरा, घायल, पर ज़िंदा। औरत काँपती हुई दूर जा बैठी। जवानों ने उसे थाम लिया।</p>\n<p>जवान सुल्तान गंजा को क़ाबू में लेकर बर्फ़ पर लिटा चुके थे। कंधे से खून बर्फ़ को गहरा लाल करता जा रहा था।</p>\n<p>विक्रम नीचे उतरकर उसके पास खड़ा हुआ। उसने कुछ नहीं कहा।</p>\n<p>चार आतंकी मारे गए थे। पाँचवाँ घायल पड़ा था। गाँव का कोई घर नहीं जला। विक्रम के किसी जवान की जान नहीं गई, बस एक के हाथ में मामूली घाव था।</p>\n<p>रणजीत सिंह उसके पास आया। “साहब, आपको कैसे पता था कि वह यहीं से भागेगा?”</p>\n<p>“उसकी जगह खड़े होकर सोचा था।”</p>\n<p>“और अगर न भागता?”</p>\n<p>“तब तीन रास्ते और थे।”</p>\n<p>रणजीत सिंह ने उसे सलाम किया, नियम से नहीं, भीतर से।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अब एक सवाल बचा था।</p>\n<p>बर्फ़ रात भर गिरकर घुटनों तक हो चुकी थी, और यूनिट तक बारह घंटे का पहाड़ी रास्ता था। पाँच लोगों को उठाकर इतनी दूर ले जाने का मतलब था अपने ही जवानों को ख़तरे में डालना, और घायल सुल्तान गंजा को ज़िंदा ले जाने का मतलब था उसे बचाने के लिए जवानों की जान जोखिम में डालना।</p>\n<p>विक्रम ने रिले के ज़रिए यूनिट को संदेश भेजा। पहाड़ों में सीधी आवाज़ नहीं पहुँचती थी, इसलिए संदेश रिज की एक चौकी से होकर गया। थोड़ी देर बाद शर्मा साहब की भारी आवाज़ लौटी।</p>\n<p>“सर, चार ढेर। सुल्तान गंजा घायल, ज़िंदा। खून बहुत बह चुका है।”</p>\n<p>कुछ पल लाइन पर सिर्फ हवा रही।</p>\n<p>“बारह घंटे की बर्फ़ में वह नहीं पहुँचेगा,” शर्मा साहब ने कहा। “खोपड़ियाँ ले आओ। पहचान के लिए काफी है।”</p>\n<p>“यस, सर।”</p>\n<p>विक्रम ने गाँव वालों को घरों की तरफ भिजवाया। किसी को यह नहीं देखना चाहिए था।</p>\n<p>रणजीत सिंह उसके पास आया। “साहब, पहले मार दीजिए। खोपड़ियाँ हम उतार लेंगे।”</p>\n<p>“नहीं,” विक्रम ने कहा। “ज़िंदा ही काटूँगा।”</p>\n<p>उसने अपनी खुखरी निकाली और सुल्तान गंजा के पास घुटनों के बल बैठ गया।</p>\n<p>सुल्तान गंजा की आँखें खुली थीं, और उनमें डर था। वही आतंकी जो गाँव का गढ़ चलाता था, अब बर्फ़ पर पड़ा काँप रहा था।</p>\n<p>“वेंकटेश श्रीनिवास रेड्डी,” विक्रम ने कहा। “तेईस साल का था।”</p>\n<p>“ग़लती हो गई,” सुल्तान गंजा ने काँपती आवाज़ में कहा।</p>\n<p>“फिर सज़ा तो भुगतनी पड़ेगी, सुल्तान,” विक्रम ने कहा। “तूने बहुत ग़लत किया। यह गर्दन नहीं, रेड्डी की मौत का बदला है।”</p>\n<p>विक्रम के चेहरे पर न उत्तेजना थी, न उल्लास, बस वही ठंडी एकाग्रता जो पूरे ऑपरेशन में थी। उसने ज़िंदा सुल्तान गंजा की गर्दन पर खुखरी चलाई, एक ही बार में।</p>\n<p>कुछ पल वह वहीं घुटनों पर रहा।</p>\n<p>“बदला पूरा हुआ,” उसने धीमे से कहा। इतना धीमे कि पास का हवलदार भी न सुन पाया।</p>\n<p>रणजीत सिंह और तीन जवानों ने बाकी चार मारे गए आतंकियों के साथ वही किया जो आदेश था, चुपचाप। बर्फ़ पर कोई नारा नहीं था, सिर्फ हवा।</p>\n<p>पाँचों खोपड़ियाँ बोरों में बाँधी गईं। बाकी शरीर बर्फ़ के नीचे एक आड़ में रखकर पुलिस को उठाने की सूचना भेज दी गई। विक्रम ने खुखरी साफ़ की, म्यान में रखी, और हाथ तब तक बर्फ़ में धोता रहा जब तक उँगलियाँ सुन्न नहीं हो गईं।</p>\n<p>वापसी का बारह घंटे का रास्ता उसी रात शुरू हुआ।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>यूनिट के गेट पर वे अगली सुबह पहुँचे, पाँच बोरे जवानों के कंधों पर।</p>\n<p>शर्मा साहब ख़ुद गेट तक आए। उन्होंने बोरों पर नज़र डाली, फिर विक्रम के कंधे पर हाथ रखा।</p>\n<p>“वेल डन, विक्रम।”</p>\n<p>शर्मा साहब हर ऑपरेशन के बाद यही कहते थे।</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>वह मेहराब के नीचे से गुज़रा। ऊपर वही खोपड़ी थी, जबड़े में धँसी खुखरी, निकले हुए दाँत। पहली शाम जब वह और रेड्डी यहाँ किट बैग लिए खड़े थे, तब लगा था कि वह उन पर हँस रही है। महीनों बाद उसे समझ आया था कि वह किसी पर नहीं हँस रही।</p>\n<p>आज उसने ऊपर देखा, और पहली बार लगा कि वह सचमुच हँस रही है। इस बार उसमें न ताना था, न सवाल। वह किसी लंबी लड़ाई के बाद की थकी हुई, हल्की हँसी थी, जैसे कोई बहुत दिनों का बोझ उतार दे।</p>\n<p>“अब आराम कर, दोस्त रेड्डी,” उसने मन में कहा। “तेरा हिसाब चुका दिया।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसी शाम शर्मा साहब ने उसे बुलाया। “विक्रम, एक हफ्ते की छुट्टी जाओ। फिर 9 पैरा एसएफ़, अपनी यूनिट में रिपोर्ट करो।”</p>\n<p>वह नैना के पास पहुँचा तो शाम ढल रही थी। आसमान के किनारे पर हल्का सिंदूरी रंग बचा था, और गुलमोहर की डालियों पर कोंपलें वैसी ही थीं जैसी वह छोड़ गया था, जैसे समय ने उन्हें उसकी वापसी तक रोक रखा हो।</p>\n<p>नैना ने दरवाज़ा खोला। उसने पहले उसके चेहरे को देखा, फिर हाथों को, जैसे गिन रही हो कि वह पूरा लौटा है या नहीं। फिर उसकी आँखों में वह चीज़ उतर आई जो शब्दों से पहले पहुँचती है।</p>\n<p>“तुम पूरे लौट आए।”</p>\n<p>“वादा किया था।”</p>\n<p>उसने चाय का कप उसके हाथ में थमाया और सामने बैठ गई। उसने कुछ पूछा नहीं। वह जानती थी कि कुछ बातें पूछने से नहीं, इंतज़ार से खुलती हैं।</p>\n<p>“उस दिन तुमने पूछा था मैं क्यों जा रहा हूँ,” विक्रम ने कहा। “मैंने पूरा नहीं बताया था।”</p>\n<p>“हाँ।”</p>\n<p>“रेड्डी…” उसकी आवाज़ पहली बार काँपी। “वह मेरा भाई था, नैना। उसके क़ातिल ज़िंदा थे। जब तक सैनिक अपने साथी का बदला नहीं लेता, उसे शांति नहीं मिलती। उस बोझ के साथ तुम्हारे पास बैठ नहीं सकता था।”</p>\n<p>नैना कुछ नहीं बोली।</p>\n<p>उसके सामने जो इंसान बैठा था, उसने बारह घंटे की बर्फ़ पर अपने दोस्त की याद ढोई थी, और वही अब चाय के कप को दोनों हाथों से ऐसे थामे था जैसे उसे टूटने का डर हो। दुनिया के लिए वह जितना कठोर था, उसके सामने उतना ही कोमल। नैना को डर नहीं लगा। उसे गर्व हुआ, चुपचाप, भीतर तक। उसने जिससे प्यार किया था, वह ऐसा था कि अपने साथी के लिए पहाड़ चढ़ जाए, और लौटकर भी उसके सामने बैठे तो सिर झुकाकर सच बोले।</p>\n<p>सैनिकों को सिखाया जाता है कि वह टूट नहीं सकता। पर जो महसूस नहीं कर सकता, वह जीना भूल जाता है।</p>\n<p>नैना ने मन ही मन सोचा: विक्रम की यही भावुकता उसे उसके सबसे करीब ला रही थी, और यही उसकी सबसे बड़ी ताकत भी थी, कमज़ोरी नहीं।</p>\n<p>“मुझे तुम पर नाज़ है,” उसने कहा।</p>\n<p>विक्रम ने नज़र उठाई।</p>\n<p>“तुम मुझे बता सकते थे। मैं रोकती नहीं।”</p>\n<p>“जानता हूँ। इसीलिए नहीं बताया। अगर तुम रोक लेतीं, तो शायद मैं रुक जाता।”</p>\n<p>नैना की आँखें भर आईं, पर होंठ मुस्कराए। उसने उसकी मुट्ठी अपनी दोनों हथेलियों में ले ली। “और प्यार?”</p>\n<p>“प्यार के लिए वक्त बाद में भी मिल जाता है,” विक्रम ने कहा। “उसके लिए पूरी ज़िंदगी है। बदले के लिए नहीं है। इसलिए उसे पहले करना था।”</p>\n<p>“तो तुमने मुझे बाद के लिए रख छोड़ा,” नैना ने धीरे से कहा, “क्योंकि मैं तुम्हारी पूरी ज़िंदगी थी।”</p>\n<p>विक्रम ने कुछ नहीं कहा। उसकी चुप्पी ही जवाब थी।</p>\n<p>कुछ देर बाद उसने कहा, “अब मुझे अपनी यूनिट, 9 पैरा एसएफ़, में रिपोर्ट करना है। नॉर्थ-ईस्ट में।”</p>\n<p>“कितनी दूर?”</p>\n<p>“बहुत।”</p>\n<p>नैना हँस दी, इस बात पर कि इतनी बड़ी दूरी भी उसने कितने कम शब्दों में कह दी। “फिर जाओ। पर इस बार बता कर जाना।”</p>\n<p>“बता कर जाऊँगा।”</p>\n<p>उसने उसके माथे को चूमा।</p>\n<p>बाहर शाम रात में ढल रही थी, और नैना उसका हाथ थामे रही।</p>"}, {"chapter": 17, "title": "अध्याय 15 — पंद्रह सौ किलोमीटर", "content": "<h1>अध्याय 15 — पंद्रह सौ किलोमीटर</h1>\n<p>मंगलवार का दिन था जब विक्रम के फोन पर सुनैना का नाम आया।</p>\n<p>वह उस वक्त मणिपुर में, अपनी यूनिट में था और लंदन से सुनैना का उस अजीब वक्त पर फोन आना ही काफी था यह समझने के लिए कि बात मामूली नहीं है। फोन उठाते ही उसकी आवाज़ में वह खिंचाव सुनाई दिया जिसे वह छिपाना चाह रही थी, मगर पूरी तरह छिपा नहीं पा रही थी।</p>\n<p>“नैना मेदांता में है… गुरुग्राम में।”</p>\n<p>विक्रम सीधा होकर बैठ गया।</p>\n<p>“क्या हुआ?”</p>\n<p>“डॉक्टर कह रहे हैं अब जान का कोई ख़तरा नहीं है, लेकिन तीन दिन से अस्पताल में है। माँ-पापा को भी ठीक से नहीं बता रही कि हालत कितनी बिगड़ी थी। मैं यहाँ से पहुँच नहीं सकती और…”</p>\n<p>सुनैना कुछ पल चुप रही।</p>\n<p>“मुझे समझ नहीं आया तुम्हारे अलावा किसे फोन करूँ।”</p>\n<p>उसके बाद विक्रम ने ज़्यादा सवाल नहीं किए।</p>\n<p>कुछ बातें फोन पर पूरी सुन लेने के लिए नहीं होतीं। उनका मतलब पहली दो पंक्तियों में ही समझ आ जाता है।</p>\n<p>अगले कुछ घंटों में उसने इमरजेंसी क्लॉज़ के तहत छुट्टी मंज़ूर करवाई—एक ऐसा रास्ता जिसे सर्विस के इतने वर्षों में उसे पहले कभी इस्तेमाल करने की ज़रूरत नहीं पड़ी थी। उसी शाम एयरफोर्स का एक ट्रांसपोर्ट विमान दिल्ली जा रहा था। अपनी यूनिट के एक परिचित के ज़रिए उसने उसमें जगह निकलवा ली।</p>\n<p>सुबह तक वह दिल्ली में था।</p>\n<p>और वहाँ से सीधे गुरुग्राम।</p>\n<p>पूरी दूरी उसके लिए शहरों और किलोमीटरों में बँटी ही नहीं। मणिपुर से दिल्ली, दिल्ली से गुरुग्राम—सब एक ही बेचैनी का लंबा रास्ता बन गया था, जिसके दूसरे छोर पर बस नैना थी।</p>\n<p>विमान जब उत्तर प्रदेश के ऊपर से गुज़र रहा था, नीचे अँधेरे में खेतों की धुँधली चौखटें पीछे छूट रही थीं। बीच-बीच में किसी गाँव की इक्का-दुक्का बत्ती टिमटिमा जाती, जैसे अँधेरे ने साँस लेते-लेते पलक झपकाई हो। विक्रम काफी देर तक उन्हें देखता रहा।</p>\n<p>रेड्डी के जाने के बाद पहली बार उसके भीतर एक ख़याल उठा, और उठते ही उसने उसे दबाने की कोशिश की।</p>\n<p>क्या किसी अपने को खो देने का डर सिर्फ किसी पहाड़ी मोर्चे, किसी गोली या किसी ऑपरेशन के साथ ही आता है?</p>\n<p>कभी-कभी एक मामूली-सा बुखार भी इंसान को वहाँ पहुँचा सकता है जहाँ से कोई वापस नहीं आता।</p>\n<p>एक साधारण अस्पताल का कमरा।</p>\n<p>एक बिस्तर।</p>\n<p>और ख़बर आने में हुई थोड़ी-सी देर।</p>\n<p>उसने ख़याल को आगे नहीं बढ़ने दिया।</p>\n<p>नज़र वापस खिड़की के बाहर कर ली और तब तक वहीं देखता रहा जब तक विमान उतरने नहीं लगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>मेदांता के वार्ड के शीशे वाले दरवाज़े से नैना पहली बार दिखाई दी तो विक्रम के कदम एक पल को धीमे पड़ गए।</p>\n<p>उसने नैना को कई रूपों में देखा था—वर्दी में, गुस्से में, हँसते हुए, थककर उसकी गोद में सिर रखे हुए, शादी में खुले बालों और हरे लहँगे में बेफ़िक्र नाचते हुए।</p>\n<p>अस्पताल के उस बिस्तर पर वह उन सबसे अलग लग रही थी।</p>\n<p>छोटी-सी, जैसे वर्दी उतारकर तह करके तकिए के पास रख दी गई हो।</p>\n<p>एक हाथ के पीछे आईवी लगी थी और चेहरे पर बीमारी की वह सफ़ेदी उतर आई थी जो इंसान की सारी अकड़ कुछ दिनों के लिए चुप करा देती है।</p>\n<p>वार्ड में एंटीसेप्टिक और दोबारा गर्म की गई चाय की मिली-जुली गंध थी। दूर गलियारे में किसी ट्रॉली का एक पहिया हर चक्कर पर चरमराता था और मशीनों की धीमी आवाज़ के बीच वही आवाज़ बार-बार अलग सुनाई देती।</p>\n<p>नैना की नज़र दरवाज़े की तरफ गई।</p>\n<p>फिर वहीं ठहर गई।</p>\n<p>उसकी आँखें फैल गईं।</p>\n<p>“विक्रम?”</p>\n<p>नैना ने नाम ऐसे लिया जैसे सामने खड़ा इंसान जवाब दे दे तो ही यकीन होगा कि बुखार कोई वहम नहीं दिखा रहा।</p>\n<p>अगले ही पल उसके कंधे ढीले पड़ गए, जैसे बहुत देर से रोकी हुई साँस आख़िर छूट गई हो।</p>\n<p>“तुम यहाँ क्या कर रहे हो?”</p>\n<p>विक्रम उसके पास आ गया।</p>\n<p>“तुम्हें देखने आया हूँ।”</p>\n<p>“मुझे दिख रहा है।” उसकी आवाज़ कमज़ोर थी, मगर पुरानी नैना उसमें लौटने लगी थी। “मेरा मतलब है—तुम मणिपुर में थे।”</p>\n<p>“था।”</p>\n<p>“वो ढाई हजार किलोमीटर है, विक्रम। तुम—”</p>\n<p>“इतना नहीं है।”</p>\n<p>नैना ने उसे घूरा।</p>\n<p>“क्या?”</p>\n<p>“हवाई दूरी करीब पंद्रह सौ किलोमीटर है। सड़क से ज़्यादा पड़ेगा, लेकिन मणिपुर से कोई गाड़ी चलाकर थोड़े आएगा।”</p>\n<p>कुछ क्षण वह उसे देखती रही।</p>\n<p>फिर तीन दिन की बीमारी, हाथ में लगी आईवी और चेहरे की सारी थकान के बावजूद हँस पड़ी—उसकी उस पक्की गिनती पर, जो अस्पताल के बिस्तर के पास भी नहीं छूटी थी।</p>\n<p>“तुम पंद्रह सौ किलोमीटर उड़कर मेरे अस्पताल के बिस्तर के पास पहुँचे हो और तुम्हें सबसे पहले मेरी दूरी ठीक करनी है?”</p>\n<p>विक्रम के चेहरे पर भी आख़िर मुस्कान आ गई।</p>\n<p>“ग़लत आँकड़ा सुनकर चुप कैसे रहूँ?”</p>\n<p>“बिल्कुल। बहुत ज़रूरी है।”</p>\n<p>“स्टैंडर्ड बनाए रखने पड़ते हैं।”</p>\n<p>उसने गंभीर चेहरा बनाकर नैना को देखा।</p>\n<p>“खासकर तब, जब तुम यहाँ बुखार लेकर पूरे वार्ड की नर्सों को अपना फैन बनाने में लगी हो।”</p>\n<p>“मैंने सिर्फ एक नर्स को इंप्रेस किया है।”</p>\n<p>“एक दिन में?”</p>\n<p>“तीन दिन में। और वो भी इसलिए कि उसे लगा मैं बहुत बहादुर हूँ। असल में मैं बस इस ड्रिप से परेशान थी।”</p>\n<p>“तुम सुधरोगी नहीं।”</p>\n<p>“बीमार हूँ, मरी नहीं हूँ।”</p>\n<p>विक्रम की मुस्कान वहीं ठहर गई।</p>\n<p>नैना ने ख़ुद भी महसूस किया कि उसने क्या कह दिया है।</p>\n<p>एक छोटा-सा सन्नाटा आया।</p>\n<p>फिर उसने हाथ आगे बढ़ाया।</p>\n<p>विक्रम ने बिना कुछ कहे उसका हाथ अपने दोनों हाथों में ले लिया।</p>\n<p>“थैंक यू,” नैना ने धीमे से कहा।</p>\n<p>“किसलिए?”</p>\n<p>“पंद्रह सौ किलोमीटर के लिए।”</p>\n<p>इस बार विक्रम ने मज़ाक नहीं किया।</p>\n<p>कुर्सी खींचकर बिस्तर के बिल्कुल पास बैठ गया।</p>\n<p>“अब सच-सच बताओ। हालत कितनी ख़राब हुई थी?”</p>\n<p>नैना की आँखें कुछ पल उसके चेहरे पर रहीं।</p>\n<p>तीन दिनों से वह हर किसी को वही हिस्सा बता रही थी जिससे सामने वाला ज़्यादा परेशान न हो। विक्रम ने सवाल कुछ इस तरह पूछा था कि आधा सच बोलने की गुंजाइश कम बची थी।</p>\n<p>“पहली रात बुखार बहुत ऊपर चला गया था,” उसने आख़िर कहा। “डॉक्टरों को भी शुरू में समझ नहीं आ रहा था कि वजह क्या है। कुछ घंटे…”</p>\n<p>वह रुक गई।</p>\n<p>विक्रम का अंगूठा उसके हाथ की पीठ पर बहुत धीरे चलता रहा।</p>\n<p>“कुछ घंटे मैं बहुत डर गई थी।”</p>\n<p>विक्रम ने बीच में कुछ नहीं कहा।</p>\n<p>“किसी को बताया नहीं। माँ-बाबा को बताती तो वे घबरा जाते। सुनैना इतनी दूर थी। और मैं यहाँ…”</p>\n<p>नैना ने नज़रें नीचे कर लीं।</p>\n<p>“अकेली थी।”</p>\n<p>उसकी उँगलियों की पकड़ ज़रा ढीली पड़ गई।</p>\n<p>“और पता है उस वक्त मैं किसके बारे में सोच रही थी?”</p>\n<p>विक्रम जानता था, फिर भी पूछा—</p>\n<p>“किसके?”</p>\n<p>“तुम्हारे।”</p>\n<p>नैना ने उसकी उँगलियाँ थोड़ा कसकर पकड़ लीं।</p>\n<p>“मैं सोच रही थी, अगर तीन दिन की बीमारी में, एक अस्पताल के बिस्तर पर पड़े-पड़े मुझे इतना डर लग सकता है… तो जब तुम कहीं ऐसी जगह होते हो जहाँ मैं तुम्हें फोन तक नहीं कर सकती, तब तुम्हारे लिए इंतज़ार करने वाले पर क्या गुज़रती होगी।”</p>\n<p>उसकी आवाज़ धीमी हो गई।</p>\n<p>“क्या तुम्हें हर बार ऐसा ही लगता है?”</p>\n<p>“हाँ।”</p>\n<p>“हर बार?”</p>\n<p>“हर बार।”</p>\n<p>नैना काफी देर चुप रही।</p>\n<p>“मुझे पहले समझ नहीं आया था।”</p>\n<p>“क्या?”</p>\n<p>“इंतज़ार की कीमत।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“जब तुम कहीं जाते थे और मैं फोन पर कह देती थी—‘सावधान रहना’—मुझे लगता था मैंने अपनी फ़िक्र कह दी। अब समझ आया कि उसके बाद बचता क्या है। बस इंतज़ार। और उस इंतज़ार में इंसान के पास करने को कुछ भी नहीं होता।”</p>\n<p>“तुम्हें इसके लिए माफ़ी माँगने की ज़रूरत नहीं है।”</p>\n<p>“थोड़ी-सी है।”</p>\n<p>“नहीं,” विक्रम ने कहा।</p>\n<p>“है,” नैना ने कहा। “क्योंकि अब पता चला है कि किसी की ख़बर का इंतज़ार करना भी अपने आप में कितना थका देता है।”</p>\n<p>कुछ देर दोनों वैसे ही बैठे रहे।</p>\n<p>फिर नैना ने बिस्तर पर अपने पास की पतली-सी जगह थपथपाई।</p>\n<p>“यहाँ आओ।”</p>\n<p>विक्रम ने कुर्सी की तरफ देखा।</p>\n<p>“मैं यहीं ठीक हूँ।”</p>\n<p>“मैं नहीं हूँ। वो कुर्सी देखकर मेरी कमर दुख रही है और मुझे तुम इतनी दूर भी नहीं चाहिए।”</p>\n<p>विक्रम उठकर बिस्तर के किनारे बैठ गया। आईवी की लाइन का ध्यान रखते हुए नैना धीरे से खिसकी और कुछ ही देर में उसका सिर विक्रम की गोद में था।</p>\n<p>यह मुद्रा दोनों के लिए नई नहीं थी।</p>\n<p>गुलमोहर के नीचे वह पहले भी ऐसे ही लेटी थी।</p>\n<p>तब डालियों पर हल्की हरी कोंपलें थीं। आज सिर्फ अस्पताल की ट्यूबलाइट थी।</p>\n<p>मगर उस दिन की थकान मन की थी।</p>\n<p>आज उसका शरीर भी थका हुआ था।</p>\n<p>विक्रम ने एक हाथ उसके सिर के नीचे रखा और दूसरे की उँगलियाँ धीरे-धीरे उसके बालों में फेरने लगा।</p>\n<p>उसी स्पर्श ने वह कर दिया जो तीन दिन की बीमारी, डॉक्टरों के सवाल और अकेले बिताई रातें नहीं कर पाई थीं।</p>\n<p>नैना रो पड़ी।</p>\n<p>पहले बिल्कुल चुपचाप, जैसे बाँध की दीवार पर पहली रिसन।</p>\n<p>फिर साँसें टूटने लगीं और कंधे हल्के-हल्के काँपने लगे।</p>\n<p>विक्रम ने उसे चुप कराने की कोशिश नहीं की।</p>\n<p>न यह कहा कि सब ठीक है।</p>\n<p>न यह कि रो मत।</p>\n<p>बस उसकी उँगलियाँ उसी धीमी रफ्तार से उसके बालों में चलती रहीं।</p>\n<p>काफी देर बाद नैना ने कहा—</p>\n<p>“सॉरी।”</p>\n<p>“किस बात का?”</p>\n<p>“पता नहीं। अब रो रही हूँ जब सबसे बुरा वक्त निकल चुका है।”</p>\n<p>“शायद इसीलिए।”</p>\n<p>नैना ने आँखें खोलीं।</p>\n<p>विक्रम ने उसके माथे से बाल हटाए।</p>\n<p>“तीन दिन अकेले ख़ुद को संभालती रही। अब अकेली नहीं हो, तो मत संभालो।”</p>\n<p>नैना की आँखों से फिर दो आँसू निकले, मगर इस बार उनमें पहले वाली घबराहट नहीं थी।</p>\n<p>कुछ देर बाद विक्रम ने बहुत धीमे कहा—</p>\n<p>“जब भी तुम्हें मेरी ज़रूरत होगी, मैं आऊँगा।”</p>\n<p>नैना स्थिर हो गई।</p>\n<p>“जहाँ भी हुआ। जितना भी दूर हुआ। जो करना पड़ा।”</p>\n<p>विक्रम ने नीचे नैना की तरफ देखा।</p>\n<p>“ये बात सिर्फ सुनना मत, नैना। यकीन करना।”</p>\n<p>नैना ने उसकी गोद में सिर थोड़ा मोड़ा ताकि उसका चेहरा देख सके।</p>\n<p>“करती हूँ।”</p>\n<p>फिर कुछ पल बाद बोली—</p>\n<p>“शायद आज से पहले पूरी तरह नहीं करती थी। आज करती हूँ।”</p>\n<p>विक्रम की उँगलियाँ फिर उसके बालों में चलने लगीं।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>कुछ देर बाद उसके आँसू थम गए और साँसें बराबर होने लगीं। कमरे में कुछ भी बदला नहीं था—वही अस्पताल की गंध, वही मशीनों की आवाज़, वही आईवी, वही चरमराती ट्रॉली।</p>\n<p>मगर उसके भीतर तीन दिनों से जमा खौफ अब उतना तन्हा नहीं था।</p>\n<p>विक्रम अगले दो दिन वहीं रहा।</p>\n<p>उसने एक बार भी यह नहीं कहा कि अब उसे लौट जाना चाहिए। रात में उसी गद्देदार विज़िटर चेयर पर अधूरी नींद लेता, सुबह फिर उसके पास बैठा मिलता। बुखार पूरी तरह उतर गया और डॉक्टरों ने आख़िर नैना को घर जाने की इजाज़त दे दी, तब जाकर उसने वापसी के बारे में सोचा।</p>\n<p>उसने नैना को उस रात यह नहीं बताया कि उत्तर प्रदेश के ऊपर उड़ते हुए उसके मन में क्या ख़याल आया था।</p>\n<p>रेड्डी के जाने के बाद उसने नैना से वादा किया था कि वह अपने दुःख के दरवाज़े उसके लिए बंद नहीं करेगा।</p>\n<p>मगर डर और दुःख हमेशा एक ही चीज़ नहीं होते।</p>\n<p>कुछ खौफ ऐसे होते हैं जिन्हें इंसान जानता है कि किसी दिन बाँटना पड़ेगा—</p>\n<p>जैसे बीज जानता है कि उसे मिट्टी के भीतर अपनी बारी का इंतज़ार करना है—</p>\n<p>बस आज नहीं।</p>"}, {"chapter": 18, "title": "अध्याय 16 — सोहना किला", "content": "<h1>अध्याय 16 — सोहना किला</h1>\n<p>अस्पताल से छुट्टी मिले नैना को एक हफ्ता हो चुका था। एंटीबायोटिक्स का कोर्स लगभग पूरा था, बुखार लौटकर नहीं आया था और डॉक्टर भी उसे पूरी तरह ठीक मान चुके थे। तीन दिन की निगरानी ज़रूरत से कुछ ज़्यादा चली थी, मगर अस्पताल वाले भी उस इंसान की मौजूदगी को देखकर थोड़े ज़्यादा एहतियाती हो गए थे, जो मणिपुर से पंद्रह सौ किलोमीटर का सफ़र तय करके सिर्फ उसके बिस्तर के पास बैठने चला आया था।</p>\n<p>अब विक्रम की छुट्टी में दो दिन बचे थे।</p>\n<p>उस शाम नैना का फोन आया तो उसकी आवाज़ में एक ऐसी बेचैनी थी जिसे दोनों पहचानते थे, मगर कोई उसका नाम नहीं लेना चाहता था।</p>\n<p>“मुझे कहीं ले चलो।”</p>\n<p>“कहाँ?”</p>\n<p>“कहीं भी। मुझे फ़र्क़ नहीं पड़ता। बस एक दिन और चाहिए जो अस्पताल का कमरा न हो… और ऐसी विदाई भी नहीं, जो आने से पहले ही हमारे बीच बैठ जाए।”</p>\n<p>विक्रम कुछ पल चुप रहा।</p>\n<p>“सोहना किला?”</p>\n<p>“क्यों?”</p>\n<p>“कई महीने पहले तुमने कहा था कभी जाना है।”</p>\n<p>नैना को याद करने में एक पल लगा।</p>\n<p>“तुम्हें वो भी याद है?”</p>\n<p>“तुम बोलती बहुत हो। कुछ न कुछ याद रह ही जाता है।”</p>\n<p>“अच्छा।”</p>\n<p>उसकी आवाज़ में मुस्कान लौट आई।</p>\n<p>“तो कल सोहना किला। और कल हम किसी दूसरी चीज़ के बारे में नहीं सोचेंगे।”</p>\n<p>“कोशिश करेंगे।”</p>\n<p>“नहीं। करेंगे।”</p>\n<p>विक्रम हँस दिया।</p>\n<p>नैना की यही आदत थी—जिन चीज़ों पर उसका कोई बस नहीं होता, उनके बारे में भी फ़ैसला ऐसे सुनाती थी जैसे दुनिया को मानना ही पड़ेगा।</p>\n<p>उस रात उसने दोबारा फोन करके बस इतना कहा—</p>\n<p>“वीकडे है, भीड़ नहीं होगी। तुम, मैं और कुछ सौ साल पुरानी किसी और की महत्वाकांक्षाएँ।”</p>\n<p>“बहुत रोमांटिक योजना है।”</p>\n<p>“मुझे पता था तुम्हें पसंद आएगी।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सुबह वे निकले तो आसमान का रंग फीका धूसर था, जैसे किसी पुराने अख़बार का पन्ना ऊपर तान दिया गया हो।</p>\n<p>किला लगभग वैसा ही खाली मिला जैसा नैना चाहती थी। झाड़ियों और सूखी घास के बीच पुरानी बलुआ पत्थर की दीवारें खड़ी थीं; टिकट देने वाला एक ऊबा हुआ केयरटेकर था, जिसने दो टिकट काटे और फिर अपने काम में लग गया।</p>\n<p>बाकी वहाँ कोई नहीं था।</p>\n<p>बाहरी दीवार के कई हिस्से बरसों पहले ढह चुके थे। कहीं-कहीं इतनी बड़ी दरार थी कि बिना किसी दरवाज़े से गुज़रे सीधे भीतर जाया जा सकता था—जैसे किसी वक्त किले ने तय कर लिया हो कि अब दुनिया से ख़ुद को बचाने की मशक्कत बेकार है, जिसे आना है आए।</p>\n<p>टूटी दीवार की एक दरार में कहीं से एक नन्हीं हरी कोंपल फूट आई थी—पत्थरों की उस पुरानी थकान के बीच अकेली जीती-जागती चीज़।</p>\n<p>दोनों बिना किसी तय रास्ते के घूमते रहे।</p>\n<p>सदियों के कदमों से घिस चुकी सँकरी पत्थर की सीढ़ियाँ चढ़ीं, छोटे-छोटे आँगनों में निकले, कभी किसी टूटी मेहराब के नीचे रुक गए।</p>\n<p>एक बड़े से हॉल में पहुँचकर नैना ठहर गई। छत बहुत पहले गिर चुकी थी और ऊपर पूरा आसमान दिखाई दे रहा था।</p>\n<p>“कभी कोई यहाँ पूरी ज़िंदगी रहा होगा।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“शादी हुई होगी यहीं। बच्चे हुए होंगे। पैसे की चिंता की होगी, ससुराल वालों से परेशान हुआ होगा… कोई औरत बैठकर सोचती होगी कि उसका पति उससे उतनी मोहब्बत करता भी है या नहीं जितनी वह चाहती है।”</p>\n<p>उसने चारों तरफ देखा।</p>\n<p>“और अब?”</p>\n<p>टूटी दीवारें।</p>\n<p>उगी हुई घास।</p>\n<p>खुला आसमान।</p>\n<p>“अब बस ये बचा है। और सदियों बाद हम दोनों यहाँ खड़े उनकी ज़िंदगी के बारे में अंदाज़ा लगा रहे हैं।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“मंगलवार की सुबह के लिए काफी भारी ख़याल है।”</p>\n<p>“मुझे उल्टा सुकून देता है।”</p>\n<p>नैना उसकी तरफ मुड़ी।</p>\n<p>“जो चीज़ आज हमें बहुत बड़ी लगती है न… शायद थोड़ी दूरी से उतनी बड़ी नहीं रहती।”</p>\n<p>विक्रम कुछ कहता, उससे पहले बारिश की पहली बूँद उसके हाथ की पीठ पर गिरी।</p>\n<p>उसने ऊपर देखा।</p>\n<p>दूसरी बूँद का इंतज़ार नहीं करना पड़ा।</p>\n<p>एकाएक पानी टूट पड़ा।</p>\n<p>कुछ ही पलों में धूल कीचड़ बनने लगी। नैना चौंककर हँसी और विक्रम की बाँह पकड़कर पास की एक मेहराब की तरफ भागी।</p>\n<p>“इधर!”</p>\n<p>दोनों दौड़े, मगर छत के नीचे पहुँचते-पहुँचते भीग चुके थे।</p>\n<p>कमरा छोटा था और किले के उन गिने-चुने हिस्सों में से था जिसकी छत अब भी पूरी बची थी। पत्थर की सँकरी दीवारें, ऊपर एक छोटी खिड़की और बाहर गिरती बारिश की लगातार आवाज़; हवा में भीगी मिट्टी और पुराने पत्थर की गंध भर गई थी।</p>\n<p>नैना ने अपने दुपट्टे का सिरा निचोड़ा।</p>\n<p>“ये योजना में नहीं था।”</p>\n<p>“योजना तुम्हारी थी।”</p>\n<p>“बारिश मेरी नहीं थी।”</p>\n<p>उसने बाहर देखा। पानी कम होने के बजाय और तेज़ पड़ रहा था।</p>\n<p>फिर विक्रम की तरफ मुड़ी।</p>\n<p>“लगता है कुछ देर यहीं फँसे हैं।”</p>\n<p>बैठने को पत्थर के फर्श के अलावा कुछ नहीं था।</p>\n<p>दोनों दीवार से पीठ लगाकर बैठ गए। कंधे आपस में छू रहे थे और सामने खुले दरवाज़े के पार बारिश एक मोटे पर्दे की तरह गिर रही थी।</p>\n<p>“मैंने आज की कल्पना ऐसी नहीं की थी,” विक्रम ने कहा।</p>\n<p>“मैं शिकायत नहीं कर रही।”</p>\n<p>नैना ने सिर पीछे पत्थर से टिका दिया।</p>\n<p>कुछ देर बारिश सुनती रही।</p>\n<p>“पता है मुझे इसमें क्या अच्छा लग रहा है?”</p>\n<p>“भीगे कपड़े?”</p>\n<p>“चुप रहो।”</p>\n<p>वह मुस्कराई, फिर आवाज़ अपने-आप थोड़ी धीमी हो गई।</p>\n<p>“मुझे रुकना नहीं आता, विक्रम। मेरी पूरी ज़िंदगी में कुछ न कुछ मुझसे माँगता रहता है—घर, नौकरी, ड्यूटी, लोग… हमेशा अगली चीज़।”</p>\n<p>उसने चेहरा उसकी तरफ किया।</p>\n<p>“तुम शायद मेरी ज़िंदगी की इकलौती चीज़ हो जो मुझसे कुछ माँगती नहीं।”</p>\n<p>विक्रम की नज़र उस पर ठहर गई।</p>\n<p>नैना ने आगे कहा—</p>\n<p>“तुम्हारे साथ मैं बस रह सकती हूँ। मुझे हर वक्त कुछ साबित नहीं करना पड़ता, किसी की उम्मीद पूरी नहीं करनी पड़ती।”</p>\n<p>एक हल्की-सी मुस्कान उसके होंठों पर आई।</p>\n<p>“अभी तक ठीक से समझ नहीं पाई कि इसे क्या नाम दूँ।”</p>\n<p>“आज नाम देना ज़रूरी भी नहीं है।”</p>\n<p>“शायद नहीं।”</p>\n<p>कुछ क्षण बीते।</p>\n<p>फिर नैना पूरी तरह उसकी तरफ मुड़ गई।</p>\n<p>इस बार उसकी आँखों में वह पुरानी हिचक नहीं थी। महीनों से अपने भीतर हर बात को पहले परखने, फिर स्वीकार करने और आख़िर में बोलने वाली नैना जैसे उस दिन पहली बार अपनी ही सावधानी से थक चुकी थी।</p>\n<p>“एक बात पर नाम की ज़रूरत नहीं है।”</p>\n<p>“किस पर?”</p>\n<p>“इस पर कि मैं तुम्हें चाहती हूँ।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>नैना की आँखें उसकी आँखों से नहीं हटीं।</p>\n<p>“और अब मैं ये भी नहीं सोच रही कि मुझे पक्का यकीन है या नहीं। कई हफ्तों से है। बस मानने में देर कर रही थी।”</p>\n<p>बाहर बारिश पत्थरों पर लगातार गिरती रही।</p>\n<p>विक्रम ने हाथ उठाकर उसके गाल से चिपकी भीगी लट हटाई।</p>\n<p>नैना ने उसका हाथ जाने नहीं दिया।</p>\n<p>नैना ने उसकी कलाई पकड़कर हथेली अपने गाल पर रख ली और एक पल के लिए आँखें बंद कर लीं।</p>\n<p>विक्रम झुका।</p>\n<p>नैना भी उसकी ओर बढ़ी।</p>\n<p>दोनों के बीच बची थोड़ी-सी दूरी ख़त्म हुई और उसके होंठ नैना के होंठों से आ मिले। पहले स्पर्श में एक पल की नरमी थी, फिर नैना की उँगलियाँ उसकी कमीज़ पर कस गईं और वह ख़ुद उसके और करीब आ गई।</p>\n<p>बारिश तो बस चिंगारी थी। आग उस चीज़ ने पकड़ी, जो दोनों के भीतर हफ्तों से सूखी और तैयार पड़ी थी—और एक बार पकड़ ली, तो उसे बुझाने की न कोई सूरत बची, न दोनों में से किसी के भीतर ऐसी कोई चाह।</p>\n<p>कुछ पलों के लिए दोनों भूल गए कि वे पत्थर के ठंडे फर्श पर हैं, एक ऐसे पुराने किले में, जिसने अपने चार सौ सालों में ऐसा न जाने कितनी बार देखा होगा।</p>\n<p>विक्रम का हाथ उसके कंधे के पास ठहरा तो वह और करीब आ गई। भीगे कपड़ों की ठंड के बावजूद दोनों की साँसें गर्म और तेज़ थीं। नैना की धड़कन उसकी हथेली के नीचे इतनी साफ़ महसूस हो रही थी कि उसे अपनी धड़कन से अलग करना मुश्किल था।</p>\n<p>विक्रम थोड़ा पीछे हुआ।</p>\n<p>“नैना…”</p>\n<p>“मत पूछना।”</p>\n<p>“क्या?”</p>\n<p>“फिर से ये मत पूछना कि मैं पक्की हूँ या नहीं।”</p>\n<p>उसने अपना माथा उसके माथे से लगा दिया।</p>\n<p>“बता चुकी हूँ।”</p>\n<p>विक्रम फिर उसकी ओर झुका। उसके होंठ दोबारा नैना के होंठों को छू गए—इस बार पहले से धीमे, ठहरे हुए। नैना का हाथ उसके भीगे बालों में चला गया और उसने उसे अपने और करीब खींच लिया।</p>\n<p>कुछ पल बाद विक्रम के होंठ उसके होंठों से अलग हुए और धीरे-धीरे उसके गाल को छूते हुए गर्दन तक उतर आए। नैना ने सिर पीछे पत्थर से टिका दिया; उसकी साँस एक पल को अटककर फिर और तेज़ लौट आई।</p>\n<p>विक्रम के हाथ उसकी कमर और पीठ पर ठहरे, भीगे कपड़े के ऊपर से उसकी देह की गर्माहट महसूस करते हुए। नैना उससे दूर नहीं हुई। उल्टा उसकी उँगलियाँ विक्रम की कमीज़ के बटनों तक पहुँच गईं।</p>\n<p>नैना की उँगलियों से पहला बटन खुला।</p>\n<p>फिर दूसरा।</p>\n<p>विक्रम ने धीरे से उसकी दोनों कलाइयाँ थाम लीं। वह उसे रोक नहीं रहा था, बस उनकी बढ़ती हुई रफ्तार को एक पल थाम रहा था।</p>\n<p>उसने नैना की एक कलाई अपने करीब की और होंठ बहुत हल्के से उसकी कलाई की भीतरी तरफ रख दिए।</p>\n<p>“धीरे,” विक्रम ने वहीं ठहरी आवाज़ में कहा। “हमें किसी बात की जल्दी नहीं है।”</p>\n<p>नैना ने उसकी तरफ देखा।</p>\n<p>“धीरे,” नैना ने दोहराया। उसकी आवाज़ कुछ काँपी।</p>\n<p>फिर नैना ने विक्रम को अपनी ओर खींच लिया।</p>\n<p>“बस रुकना मत।”</p>\n<p>विक्रम नहीं रुका।</p>\n<p>मगर जल्दबाज़ी भी नहीं की।</p>\n<p>उसके होंठ नैना के कंधे तक गए जहाँ भीगा कुर्ता थोड़ा खिसक आया था। उँगलियाँ उसकी कमर और पीठ पर धीरे-धीरे चलती रहीं, जैसे किसी अनजानी जगह को जीतना नहीं, पहचानना चाहती हों। नैना ने उसे वैसे पकड़ा हुआ था जैसे बहुत दिनों से ख़ुद को इस अधिकार से रोकती आई हो।</p>\n<p>एक जगह उसके होंठ गर्दन पर ठहरे तो नैना का पूरा शरीर एक पल के लिए सिहर गया।</p>\n<p>फिर दोनों वहीं ठहर गए।</p>\n<p>साँसें तेज़ थीं।</p>\n<p>विक्रम की कमीज़ आधी खुल चुकी थी। नैना का दुपट्टा जाने कब पत्थर के फर्श पर गिर गया था। उनके बीच की महीनों पुरानी सावधानी लगभग पूरी तरह पिघल चुकी थी।</p>\n<p>फिर भी एक आख़िरी सीमा थी।</p>\n<p>किसी ने उसका नाम नहीं लिया।</p>\n<p>दोनों जानते थे।</p>\n<p>और दोनों वहीं रुक गए।</p>\n<p>कुछ देर उनके माथे एक-दूसरे से लगे रहे।</p>\n<p>फिर नैना ने बहुत सीधे, बिना किसी शर्म या बनावट के कहा—</p>\n<p>“मैं तुम्हें चाहती हूँ, विक्रम।”</p>\n<p>विक्रम की आँखें उसके चेहरे पर टिक गईं।</p>\n<p>“मुझे पता है।”</p>\n<p>“नहीं।”</p>\n<p>उसने हल्का-सा सिर हिलाया।</p>\n<p>“ठीक से जानो।”</p>\n<p>उसकी आवाज़ अब धीमी थी, मगर उसमें कोई हिचक नहीं थी।</p>\n<p>“मैं तुम्हारे साथ वो सब चाहती हूँ जो अभी हमारे बीच बाकी है। आज नहीं… इस पुराने किले के पत्थर पर नहीं।”</p>\n<p>उसके होंठों पर हल्की मुस्कान आई।</p>\n<p>“लेकिन किसी दिन। जल्दी।”</p>\n<p>विक्रम ने उसके चेहरे को दोनों हाथों में लिया।</p>\n<p>“मैं भी चाहता हूँ।”</p>\n<p>उसने अपना माथा उसके माथे पर टिकाए रखा।</p>\n<p>“जब सही वक्त होगा।”</p>\n<p>नैना ने आँखें बंद करके सिर हिला दिया।</p>\n<p>उसके बाद वे काफी देर वहीं बैठे रहे—एक-दूसरे में सिमटे हुए। नैना का गाल विक्रम की खुली कमीज़ के पास उसकी छाती से लगा था और विक्रम का हाथ उसके लंबे भीगे बालों पर धीरे-धीरे चलता रहा।</p>\n<p>चाहत ख़त्म नहीं हुई थी।</p>\n<p>बस उसकी जल्दबाज़ी उतर गई थी।</p>\n<p>मोहब्बत का एक हिस्सा यही भी था—किसी को इतना चाहना कि उसके और करीब जाने की तमन्ना हो, और फिर भी उस एक कदम के लिए सही वक्त का इंतज़ार कर सकना।</p>\n<p>बाहर बारिश भी धीरे-धीरे हल्की पड़ गई।</p>\n<p>जब दोनों कमरे से निकले तो किला वही था, मगर बारिश ने उसका रंग बदल दिया था। धूल बैठ चुकी थी, पत्थर चमक रहे थे, जगह-जगह पानी जमा था और हवा में गीली मिट्टी के साथ कहीं से नई घास की महक आ रही थी। दीवार की दरार वाली कोंपल पर बारिश की बूँदें टिकी थीं, हर बूँद में आसमान का एक नन्हा टुकड़ा।</p>\n<p>कार तक लौटते हुए दोनों बहुत कम बोले।</p>\n<p>कहने को बचा भी कम था।</p>\n<p>वापसी में नैना पहले की तरह अपनी तरफ सिमटकर नहीं बैठी। वह विक्रम के करीब थी, उसका हाथ पूरे रास्ते विक्रम के घुटने पर टिका रहा।</p>\n<p>न विक्रम ने हटाया।</p>\n<p>न नैना ने।</p>\n<p>शहर करीब आने लगा तो बाहर की दुनिया धीरे-धीरे फिर लौटने लगी—ट्रैफिक, रोशनी, लोग, रास्ते।</p>\n<p>मगर उनके बीच कुछ पीछे नहीं लौटा।</p>\n<p>अब दोनों जानते थे कि मोहब्बत सिर्फ फ़िक्र और इंतज़ार तक नहीं रह गई थी। उसमें स्पर्श भी था, नज़दीकी भी, और उस चाहत से अब कोई नज़र नहीं चुरा रहा था।</p>\n<p>दो दिन बाद विक्रम की छुट्टी ख़त्म होनी थी, और अगली कब मिलेगी, इसका कोई भरोसा नहीं था। दोनों ने रास्ते में इसका ज़िक्र नहीं किया।</p>\n<p>आने वाली दूरी उनके साथ ही शहर लौटी, इस बार पहले से कुछ ज़्यादा भारी। क्योंकि अब उनके बीच सिर्फ मिलने की आदत नहीं थी, एक अधूरी नज़दीकी भी थी, जिसे दोनों पूरा करना चाहते थे।</p>\n<p>और पीछे किले की दरार में वह कोंपल अब भी बूँद थामे खड़ी थी, बिना किसी के देखे।</p>"}, {"chapter": 19, "title": "अध्याय 17 — तुम्हें चुना है", "content": "<h1>अध्याय 17 — तुम्हें चुना है</h1>\n<p>छुट्टी लगभग अचानक मिली थी।</p>\n<p>पूरे पाँच दिन।</p>\n<p>बीच में न कोई ड्यूटी, न वापस रिपोर्ट करने की कोई मजबूरी। दोनों को एक साथ एहसास हुआ कि जब से यह रिश्ता शुरू हुआ था, पहली बार उनके पास इतने दिन थे जिन्हें बीच से कोई और आकर नहीं बाँट रहा था।</p>\n<p>नैना ने फोन पर फ़ैसला सुना दिया—</p>\n<p>“हिमाचल।”</p>\n<p>उसकी आवाज़ ऐसी थी जैसे आधा रास्ता वह पहले ही तय कर चुकी हो।</p>\n<p>“लेकिन कोई ऐसा हिल स्टेशन नहीं जहाँ हर तरफ हनीमून वाले सेल्फी लेते मिलें। छोटी-सी जगह। मेरे दिमाग में एक है।”</p>\n<p>“गाड़ी ले आऊँगा। छह घंटे का रास्ता है।”</p>\n<p>“नहीं। बाइक।”</p>\n<p>“नैना—”</p>\n<p>“बाइक।”</p>\n<p>उस लहजे का मतलब विक्रम अब अच्छी तरह समझता था।</p>\n<p>“पूरी ज़िंदगी लोग मुझे कहीं न कहीं गाड़ी में बैठाकर पहुँचाते रहे हैं। इस बार सिर्फ पहुँचना नहीं है। रास्ता भी महसूस करना है।”</p>\n<p>विक्रम ने बहस नहीं की।</p>\n<p>इतने महीनों में वह एक बात सीख चुका था—नैना जिस फ़ैसले पर अपने भीतर पहुँच चुकी हो, वहाँ तर्क सिर्फ समय बर्बाद करता है।</p>\n<p>वे सूरज निकलने से पहले गुरुग्राम से निकल गए।</p>\n<p>शहर अभी आधी नींद में था। सड़कें खाली थीं और शुरुआती कुछ घंटों में नैना की बाँहें उसकी कमर के चारों तरफ ढीली-सी टिकी रहीं। पहाड़ शुरू हुए, सड़कें मुड़ने लगीं तो उसकी पकड़ अपने-आप कसती गई। कभी किसी मोड़ पर दूर कुछ देखने के लिए वह आगे झुकती और उसका माथा हल्के से विक्रम के कंधे को छू जाता।</p>\n<p>बातें बहुत कम हुईं।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>दो लोगों के बीच जब ख़ामोशी असहज न रहे, तो लंबे रास्ते अक्सर छोटे लगने लगते हैं।</p>\n<p>करीब दो घंटे बाद वे सड़क किनारे एक पुराने ढाबे पर रुके। एक औरत तंदूर सँभाल रही थी, उसका बेटा ऑर्डर ले रहा था और छाँव में बिछी चारपाई पर एक बूढ़ा ऊँघ रहा था, जो उनके बैठने पर बस आँखें खोलकर सिर हिलाता और फिर अपनी नींद में लौट जाता।</p>\n<p>विक्रम ने नैना से पूछे बिना खाना मँगवा दिया।</p>\n<p>अब वह जानता था उसे क्या पसंद है।</p>\n<p>गाढ़ी दाल आई, तंदूर से उतरती गर्म रोटियाँ आईं और कुछ देर दोनों चुपचाप खाते रहे।</p>\n<p>नैना ने रोटी का टुकड़ा तोड़ते हुए कहा—</p>\n<p>“मेरी नानी एक बात कहती थीं।”</p>\n<p>“क्या?”</p>\n<p>“इंसान को समझना हो तो उसे ऐसी जगह खाना खाते देखो जहाँ दिखावा करने को कुछ न हो। फिर पता चलता है कि उसे जो मिला है उसकी कद्र है, या उसे सिर्फ वही चीज़ें अच्छी लगती हैं जिनसे दूसरे प्रभावित हों।”</p>\n<p>विक्रम ने पानी पिया।</p>\n<p>“आज क्या पता चला?”</p>\n<p>नैना कुछ क्षण उसे देखती रही।</p>\n<p>“तुम पानी भरने वाले उस बच्चे को भी थैंक यू बोलते हो जिससे कोई उम्मीद भी नहीं करता कि उसे थैंक यू कहा जाएगा।”</p>\n<p>विक्रम ने सहजता से कंधे उचकाए।</p>\n<p>“उसने पानी भरा।”</p>\n<p>“मुझे पता है। बात वही है।”</p>\n<p>नैना के चेहरे पर एक पुरानी याद की नरमी उतर आई।</p>\n<p>“नानी ने कहा था, कभी जीवनसाथी चुनना तो देखना कि वह उन लोगों से कैसे पेश आता है जिनसे उसे कुछ हासिल नहीं करना। ऐसा इंसान ढूँढ़ना जिसके दिल में सफाई हो।”</p>\n<p>वह हल्का-सा हँसी।</p>\n<p>“तब मुझे समझ नहीं आया था कि उनका मतलब क्या है।”</p>\n<p>“और अब?”</p>\n<p>“अभी तुम्हें देखते हुए थोड़ा समझ आया।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>उसे अपनी दादी याद आईं—इतनी जल्दी चली गई थीं कि उनकी साफ़ तस्वीर भी अब याद में नहीं बची थी। जाने क्यों वर्षों बाद पहली बार उसके मन में आया कि काश वह कुछ और साल जीवित रहतीं। किसी ऐसे ही ढाबे की मेज़ पर उसके सामने बैठतीं और नैना को देखकर अपनी कोई राय बनातीं।</p>\n<p>“उम्मीद है मैं उनका टेस्ट पास कर लेता।”</p>\n<p>“कर लेते।”</p>\n<p>“इतना भरोसा?”</p>\n<p>“लोगों को पहचानने में मैं अच्छी हूँ।”</p>\n<p>“ये दावा थोड़ा संदिग्ध है।”</p>\n<p>नैना ने आख़िरी निवाला खाया और उठ खड़ी हुई।</p>\n<p>“चलो। अभी चार घंटे और हैं।”</p>\n<p>विक्रम ने उसके पर्स तक हाथ पहुँचने से पहले पैसे दे दिए।</p>\n<p>इस छोटी-सी जीत पर उसने कुछ नहीं कहा।</p>\n<p>मुस्कराकर बाइक की तरफ चल पड़ा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>आख़िरी कुछ घंटों ने शरीर से छह घंटे की बाइक यात्रा की पूरी कीमत वसूल ली।</p>\n<p>जब वे शोजा पहुँचे, दोनों की कमर और कंधे रास्ते की शिकायत कर रहे थे और हवा चेहरे पर अपनी खुरदरी छाप छोड़ चुकी थी।</p>\n<p>शोजा सेराज घाटी का एक छोटा-सा गाँव था, जिसका नाम विक्रम ने नैना से पहले कभी नहीं सुना था। आख़िरी हिस्सा ऐसी सँकरी सड़क से होकर आया था जिसे सड़क कहना भी कुछ उदारता थी।</p>\n<p>शाम उतरने लगी थी।</p>\n<p>पहाड़ की ढलान पर लकड़ी और पत्थर के घर एक-दूसरे के ऊपर चढ़े दिखाई देते थे। आख़िरी छतों के बाद देवदार और चीड़ का जंगल ऊपर उठता चला गया था और उससे भी आगे उन चोटियों तक पहुँचता था जहाँ अब भी बर्फ़ ठहरी हुई थी।</p>\n<p>गेस्टहाउस की छोटी बालकनी में खड़ी नैना देर तक सामने देखती रही।</p>\n<p>“बहुत खूबसूरत है।”</p>\n<p>“फोटो देखकर चुना था न?”</p>\n<p>“हाँ। इसीलिए भरोसा नहीं था। तस्वीरें बहुत झूठ बोलती हैं।”</p>\n<p>“इसने नहीं बोला।”</p>\n<p>नैना ने अपनी कमर पर हाथ रखा।</p>\n<p>“और छह घंटे बाइक पर बैठने ने भी कोई झूठ नहीं बोला। मेरा पूरा शरीर मुझसे नाराज़ है।”</p>\n<p>“कल आराम करेंगे।”</p>\n<p>“किसने कहा?”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>उसकी आँखों की चमक देखकर ही उसे शक हो गया।</p>\n<p>रात को खाने के दौरान नैना ने अगली सुबह का कार्यक्रम सुना दिया।</p>\n<p>“रिज तक जाएँगे। चार घंटे ऊपर, दो घंटे वापस।”</p>\n<p>“तुम्हारे हिसाब से छुट्टी का मतलब क्या होता है?”</p>\n<p>“अपनी मर्ज़ी से थकना।”</p>\n<p>“आज छह घंटे बाइक पर अपनी मर्ज़ी से नहीं बैठी थीं?”</p>\n<p>“बैठी थी। कल अपनी मर्ज़ी से पहाड़ चढ़ूँगी।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“पूरी सर्विस पहाड़ इसलिए चढ़ता रहा हूँ क्योंकि किसी ने ऑर्डर दिया। छुट्टी में भी यही करना है?”</p>\n<p>“फ़र्क़ यही है। कल कोई ऑर्डर नहीं देगा।”</p>\n<p>उस रात सोने से पहले वे छोटी खिड़की के पास कुछ देर खड़े रहे। बाहर का आसमान इतना साफ़ था कि शहरों में भुला दिए गए तारे भी दिखाई दे रहे थे।</p>\n<p>नैना ने बिना उसकी तरफ देखे कहा—</p>\n<p>“मैं नहीं चाहती कि कभी हम इस ट्रिप को याद करके कहें—वो हमारी आख़िरी अच्छी याद थी।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“मैं चाहती हूँ ये पहली हो। ऐसी बहुत सारी यात्राओं में से पहली।”</p>\n<p>विक्रम ने जवाब देने में देर नहीं की।</p>\n<p>“मैं भी।”</p>\n<p>खिड़की के काँच पर दोनों की साँस की धुंध एक ही जगह मिल गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगली सुबह पूरी रोशनी फैलने से पहले वे निकल पड़े।</p>\n<p>आसमान में रात का गहरा नीला रंग अब भी बचा था और हवा इतनी ठंडी थी कि शुरुआती हर साँस सीने में चुभती थी। घास पर जमी ओस ने कुछ ही देर में उनकी पैंट के निचले हिस्से भिगो दिए।</p>\n<p>पहाड़ों के पीछे से रोशनी इतनी धीरे उठ रही थी जैसे कोई परदे के किनारे उठाकर दुनिया को जगा रहा हो।</p>\n<p>रास्ता पहले देवदार के बीच से ऊपर चढ़ता था। गिरी हुई सूइयों की मोटी तह उनके कदमों की आवाज़ तक सोख लेती। रोशनी बढ़ी तो पेड़ छँटने लगे; फिर झाड़ियाँ और खुली चट्टानें आईं और हवा में पहाड़ की वह साफ़, तीखी ठंड उतर आई जो त्वचा को छूकर भीतर तक पहुँचती है।</p>\n<p>नैना की चाल ने विक्रम को हैरान किया।</p>\n<p>न तेज़, न सुस्त।</p>\n<p>बस लगातार।</p>\n<p>वर्षों पहले किसी और पहाड़ी इलाके में उसके पिता ने उसे यही चाल सिखाई थी।</p>\n<p>एक जगह दोनों समतल चट्टान पर बैठकर पराँठे खाने लगे। नीचे पूरी घाटी फैली थी और जिस गाँव से चले थे वह अब कुछ छोटी छतों और उठते धुएँ जितना रह गया था।</p>\n<p>नैना नीचे देखती रही।</p>\n<p>“ऊपर से सब कितना छोटा लगता है।”</p>\n<p>“नीचे जाकर फिर बड़ा हो जाएगा।”</p>\n<p>“पता है।”</p>\n<p>उसने पराँठे का टुकड़ा तोड़ा।</p>\n<p>“शायद इसीलिए कभी-कभी ऊपर आना चाहिए।”</p>\n<p>रिज पर पहुँचकर दृश्य अचानक उनके सामने खुला।</p>\n<p>एक के पीछे एक सफ़ेद चोटियाँ दूर धुँधले क्षितिज तक चली गई थीं। हवा दर्रे की चट्टानों के बीच से गुज़रती हुई एक लगातार धीमी गूँज पैदा कर रही थी, जो उन दोनों से कहीं पुरानी लगती थी। जैसे पहाड़ ख़ुद साँस ले रहे हों, और दो लोग उसकी हर साँस के बीच बैठे हों। इसके अलावा वहाँ लगभग कोई आवाज़ नहीं थी।</p>\n<p>दोनों करीब एक घंटे वहीं बैठे रहे।</p>\n<p>थर्मस की आख़िरी चाय अब गुनगुनी रह गई थी। नैना पहले विक्रम के कंधे से लगी, फिर थोड़ा और नीचे खिसककर उसकी छाती से टिक गई। दोनों सामने पहाड़ देख रहे थे।</p>\n<p>विक्रम ने अचानक गहरी साँस ली।</p>\n<p>हवा में चीड़ की हल्की-सी राल जैसी महक थी।</p>\n<p>उसके भीतर कहीं कोई बहुत पुराना दरवाज़ा खुला।</p>\n<p>“डोडा।”</p>\n<p>नैना ने सिर थोड़ा उठाया।</p>\n<p>“क्या?”</p>\n<p>“कश्मीर में डोडा डिस्ट्रिक्ट। मेरे ज़्यादातर ऑपरेशन्स वहीं हुए थे।”</p>\n<p>उसने फिर वही हवा भीतर खींची।</p>\n<p>“वहाँ के चीड़ की महक बिल्कुल ऐसी थी। महीनों से उस पोस्टिंग के बारे में सोचा तक नहीं था। अभी एकदम सब याद आ गया।”</p>\n<p>नैना ने ख़ुद हवा सूँघी।</p>\n<p>“मुझे तो कुछ अलग नहीं लग रहा।”</p>\n<p>“अभी नहीं लगेगा।”</p>\n<p>“फिर?”</p>\n<p>विक्रम की उँगलियाँ उसके बालों में धीरे-धीरे चल रही थीं।</p>\n<p>“कभी लगेगा। शायद यहाँ नहीं। शायद सालों बाद किसी बिल्कुल दूसरी जगह। यही महक अचानक दोबारा मिलेगी और उसी पल पहचान जाओगी।”</p>\n<p>नैना ने ऊपर उसकी तरफ देखा।</p>\n<p>“और क्या पहचानूँगी?”</p>\n<p>“कि ये मुझसे होकर कभी तुम्हारे पास पहले भी आई थी।”</p>\n<p>नैना के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“महक से भी वादे करते हो?”</p>\n<p>“हर वादे को जगह थोड़े चाहिए। कभी-कभी एक खुशबू और थोड़ा वक्त काफी होता है।”</p>\n<p>नैना फिर उसकी छाती से लग गई।</p>\n<p>“तो इंतज़ार करूँगी।”</p>\n<p>एक पल रुकी।</p>\n<p>“जितना वक्त लगे।”</p>\n<p>कुछ देर दोनों चुप रहे।</p>\n<p>फिर नैना ने कहा—</p>\n<p>“मुझे कुछ सच बताओ।”</p>\n<p>“मैं झूठ बहुत बोलता हूँ?”</p>\n<p>“मज़ाक में बताई हुई कोई कहानी नहीं। ऐसी बात जो तुमने सचमुच कभी किसी से नहीं कही।”</p>\n<p>विक्रम काफी देर सामने पहाड़ों को देखता रहा।</p>\n<p>विक्रम का हाथ अब भी नैना के बालों में था।</p>\n<p>“मुझे लगता था मोहब्बत दूसरे लोगों के साथ होती है।”</p>\n<p>नैना स्थिर हो गई।</p>\n<p>“मेरे साथ नहीं। मुझे हमेशा लगा ज़िंदगी में कभी कोई रिश्ता होगा तो बस… तय हो जाएगा। घर वाले देखेंगे, बात होगी, शादी हो जाएगी और फिर इंसान धीरे-धीरे उसी ज़िंदगी में ढल जाएगा।”</p>\n<p>“और दूसरी वाली?”</p>\n<p>“कौन-सी?”</p>\n<p>“जिसमें इंसान ढलता नहीं। गिरता है।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>“उस पर यकीन नहीं था।”</p>\n<p>“अब?”</p>\n<p>इस बार उसने नीचे नैना की तरफ देखा।</p>\n<p>“अब लगता है तुमसे मिलने से पहले मैं बहुत-सी चीज़ों के बारे में ग़लत था।”</p>\n<p>नैना की नज़र पल भर को ठहरी।</p>\n<p>फिर वह सामने पहाड़ों पर लौट गई।</p>\n<p>“मुझे लगता था मुझसे ठीक तरह मोहब्बत करना मुश्किल है।”</p>\n<p>विक्रम का हाथ उसके बालों में रुक गया।</p>\n<p>“क्यों?”</p>\n<p>“माँ कहा करती थीं—थोड़ी नरम हुआ कर, नैना। हर बात में इतनी तेज़ मत रहा कर। अच्छे-भले लड़के डरकर भाग जाएँगे।”</p>\n<p>उसकी आवाज़ में शिकायत नहीं थी; बस कोई पुरानी बात थी जो बहुत दिनों बाद बाहर आई थी।</p>\n<p>“सालों तक लगा शायद सही कहती हैं। कि जिसे मेरे साथ रहना होगा, उसके लिए मुझे अपना कुछ हिस्सा कम करना पड़ेगा।”</p>\n<p>वह पलटकर उसे देखने लगी।</p>\n<p>“तुमने कभी नहीं कहा।”</p>\n<p>“क्या?”</p>\n<p>“कि मैं थोड़ी कम हो जाऊँ।”</p>\n<p>विक्रम ने बिना सोचे जवाब दिया—</p>\n<p>“मुझे तुम कम चाहिए ही नहीं थीं।”</p>\n<p>नैना की आँखें उससे नहीं हटीं।</p>\n<p>“जैसी हो, वैसी ही चाहिए थीं।”</p>\n<p>कई क्षण वह कुछ नहीं बोली।</p>\n<p>फिर बहुत धीरे कहा—</p>\n<p>“मेरे लिए शायद आज तक किसी ने इससे ज़्यादा सच्ची बात नहीं कही।”</p>\n<p>उसने सिर वापस उसकी छाती पर रख दिया।</p>\n<p>“और पता है सबसे अजीब क्या है?”</p>\n<p>“क्या?”</p>\n<p>“मैं हर हफ्ते इंतज़ार करती हूँ कि तुम अपना मन बदलोगे।”</p>\n<p>विक्रम की बाँह उसके चारों तरफ थोड़ी और सिमट आई।</p>\n<p>“और जब नहीं बदलते… तो हर हफ्ते थोड़ा और यकीन हो जाता है।”</p>\n<p>उसके बाद ख़ामोशी आई।</p>\n<p>मगर वह खाली ख़ामोशी नहीं थी।</p>\n<p>कई बार दो लोगों के बीच कुछ बातें कह दिए जाने के बाद उन्हें तुरंत किसी और बात से ढक देना उनकी कीमत कम कर देता है।</p>\n<p>इसलिए दोनों वहीं बैठे रहे।</p>\n<p>नैना उसकी छाती से लगी रही और विक्रम की उँगलियाँ उसके बालों में चलती रहीं।</p>\n<p>सामने पहाड़ थे।</p>\n<p>और उनके बीच पहली बार मोहब्बत सिर्फ महसूस की हुई चीज़ नहीं रही थी।</p>\n<p>फिर नैना ने अपनी हथेली उसकी हथेली में रख दी और विक्रम ने उँगलियाँ बंद कर लीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दोपहर ढलने से पहले वे नीचे लौट आए।</p>\n<p>पैर थके हुए थे, मगर वह अच्छी थकान थी जो किसी दिन को पूरा जी लेने के बाद शरीर में रहती है।</p>\n<p>आख़िरी रास्ते में नैना बहुत शांत हो गई।</p>\n<p>विक्रम ने महसूस किया, मगर पूछा नहीं।</p>\n<p>अब वह उसकी हर ख़ामोशी को तुरंत सवाल से खोलने की कोशिश नहीं करता था।</p>\n<p>रात के खाने पर, उसी नीची मेज़ के सामने, नैना ने ख़ुद बात शुरू की।</p>\n<p>“मैं सोहना वाली बात के बारे में सोच रही थी।”</p>\n<p>विक्रम समझ गया।</p>\n<p>“मुझे याद है।”</p>\n<p>“वो उस वक्त की बात नहीं थी।”</p>\n<p>उसने कप मेज़ पर रख दिया।</p>\n<p>“मतलब… मैं सिर्फ बहाव में नहीं कह रही थी। उसके बाद कई बार सोचा है। ठीक से।”</p>\n<p>उसने विक्रम की आँखों में देखा।</p>\n<p>“मैं तैयार हूँ।”</p>\n<p>विक्रम कुछ कहने लगा।</p>\n<p>“पहले मुझे पूरा बोलने दो। वरना हिम्मत चली जाएगी।”</p>\n<p>वह चुप हो गया।</p>\n<p>नैना ने साँस ली।</p>\n<p>“मैं जानती हूँ मेरे लिए इसका क्या मतलब है। सिर्फ शरीर वाली बात नहीं। मेरे घर में इन चीज़ों को हल्के में नहीं लिया जाता। मैं भी नहीं लेती।”</p>\n<p>उसकी आवाज़ बिल्कुल स्थिर थी।</p>\n<p>“अगर मैं तुम्हारे साथ उस सीमा के आगे जाती हूँ, तो अगले दिन उठकर ये नहीं कह सकती कि बस हो गया, भूल जाओ। मैं ऐसी नहीं हूँ। मेरे लिए उसके बाद कुछ बदल जाएगा।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“इसलिए मैं चाहती हूँ कि तुम्हें साफ़ पता हो—मैं ये तुम्हें इसलिए नहीं दे रही कि हम यहाँ अकेले हैं, या क्योंकि मौका है।”</p>\n<p>एक पल को उसकी आवाज़ धीमी हुई।</p>\n<p>“मैंने तुम्हें चुना है।”</p>\n<p>विक्रम ने कप उठाया, फिर बिना पिए रख दिया।</p>\n<p>“आगे जो भी हो… मेरे लिए ये मामूली नहीं होगा।”</p>\n<p>“मेरे लिए भी नहीं।”</p>\n<p>“मुझे पता है।”</p>\n<p>उसके चेहरे पर हल्की-सी नरमी आई।</p>\n<p>“इसीलिए तुम्हें कह पा रही हूँ।”</p>\n<p>उसके बाद दोनों तुरंत कमरे की तरफ नहीं भागे।</p>\n<p>शाम अपनी रफ्तार से चलती रही।</p>\n<p>विक्रम ने पिछले दिन गेस्टहाउस के पास एक छोटी-सी दुकान देखी थी जहाँ मंदिर के लिए गेंदे के फूल बिकते थे। नैना बर्तन धोने गई तो वह बाहर निकला और थोड़े-से फूल ले आया।</p>\n<p>न कोई गुलदस्ता।</p>\n<p>न कोई बड़ी तैयारी।</p>\n<p>बस कुछ गेंदे के फूल—पीले, मंदिर के, जिनमें देवता से पहले किसी की हथेली की गर्माहट थी।</p>\n<p>कमरे की मेज़ पर रख दिए।</p>\n<p>नैना अंदर आई तो उसकी नज़र तुरंत उन पर गई।</p>\n<p>फिर विक्रम पर।</p>\n<p>“ये क्यों?”</p>\n<p>“बस।”</p>\n<p>“बस?”</p>\n<p>“कमरा सिर्फ कमरा न लगे।”</p>\n<p>नैना ने फूलों को देखा और फिर उसे।</p>\n<p>“तुम्हारे साथ तो पहले ही नहीं लग रहा।”</p>\n<p>उस एक वाक्य के बाद विक्रम के पास कहने को कुछ नहीं बचा।</p>\n<p>दोनों बिस्तर के किनारे काफी देर बैठे रहे।</p>\n<p>हाथ एक-दूसरे में थे, मगर बात उन चीज़ों की होती रही जिनका उस रात से कोई सीधा रिश्ता नहीं था—नैना का बचपन, उसके पिता का लंबी ड्राइव पर बेसुरा गाना, पहाड़ों में रात को कहीं से आती वह अजीब-सी आवाज़ जिसे दोनों पहचान नहीं पा रहे थे।</p>\n<p>विक्रम समझ रहा था।</p>\n<p>नैना वहाँ पहुँच चुकी थी जहाँ वह पहुँचना चाहती थी; अब बस अपने डर को पीछे आने का थोड़ा वक्त दे रही थी।</p>\n<p>कुछ देर बाद नैना ने कहा—</p>\n<p>“माँ ने एक बात कही थी कभी।”</p>\n<p>विक्रम ने हल्के से छेड़ा—</p>\n<p>“आज उनकी बहुत याद आ रही है।”</p>\n<p>“चुप रहो।”</p>\n<p>वह मुस्कराई।</p>\n<p>“उन्होंने कहा था, पहली बार उस इंसान के साथ होना जिसके सामने तुम इतनी महफ़ूज़ महसूस करो कि बेवकूफ़ भी हो सको।”</p>\n<p>उसने विक्रम की उँगलियों को देखा।</p>\n<p>“तब समझ नहीं आया था।”</p>\n<p>“अब?”</p>\n<p>“अब आता है।”</p>\n<p>विक्रम ने उसके चेहरे पर आई एक लट पीछे की।</p>\n<p>वही छोटा-सा स्पर्श जो सोहना में भी हुआ था।</p>\n<p>फ़र्क़ इतना था कि इस बार नैना ने सिर्फ उसकी हथेली नहीं थामी; अपना पूरा चेहरा उसमें रख दिया।</p>\n<p>“महफ़ूज़ महसूस करती हो?” विक्रम ने पूछा।</p>\n<p>“बहुत।”</p>\n<p>उसने उसकी तरफ देखा।</p>\n<p>“इसीलिए यहाँ हूँ। वरना शायद कहीं बैठकर बहादुर होने का नाटक कर रही होती।”</p>\n<p>विक्रम ने कुछ क्षण उसे देखा।</p>\n<p>“अभी भी ज़रूरी नहीं है।”</p>\n<p>नैना की आँखें नरम हो गईं।</p>\n<p>“क्या?”</p>\n<p>“आज। या कभी भी। सिर्फ इसलिए नहीं कि हमने बात कर ली है।”</p>\n<p>“मैं चाहती हूँ।”</p>\n<p>वह रुकी।</p>\n<p>“पहले कभी नहीं हुआ मेरे साथ। तुम्हें पता है।”</p>\n<p>“पता है।”</p>\n<p>“तो मुझे शीशे की तरह मत छूना कि टूट जाऊँगी।”</p>\n<p>नैना ने उसकी उँगलियाँ कसकर पकड़ लीं।</p>\n<p>“और इतनी जल्दी भी मत करना जैसे तुम्हें डर हो कि मैं फ़ैसला बदल दूँगी।”</p>\n<p>फिर बहुत साफ़ कहा—</p>\n<p>“नहीं बदलूँगी।”</p>\n<p>उसके बाद उनके बीच शब्द धीरे-धीरे कम होने लगे।</p>\n<p>विक्रम उसके करीब आया तो नैना पीछे नहीं हटी। उसके होंठ बहुत हल्के से नैना के होंठों से मिले और कुछ पल वहीं ठहरे रहे—जैसे दोनों आख़िरी बार एक-दूसरे को वक्त दे रहे हों कि चाहें तो रुक जाएँ।</p>\n<p>कोई नहीं रुका।</p>\n<p>नैना की उँगलियाँ उसके कंधों पर आ गईं।</p>\n<p>विक्रम के हाथ उसके चेहरे से होते हुए उसकी पीठ तक पहुँचे, मगर हर स्पर्श में वही ठहराव था—चाहत को कम करने वाला नहीं, उसे भरोसे के भीतर रखने वाला।</p>\n<p>नैना उसकी आँखों में बार-बार देखती रही।</p>\n<p>जैसे हर अगले पल से पहले सिर्फ इतना जान लेना चाहती हो कि सामने अब भी वही इंसान है जिस पर उसने भरोसा किया था।</p>\n<p>और हर बार उसे वही मिला।</p>\n<p>न कोई जीत का भाव।</p>\n<p>न कोई जल्दबाज़ी।</p>\n<p>सिर्फ वह नरमी जिसमें वह जितनी घबराई हुई थी, उतनी ही रह सकती थी; जितनी तैयार थी, उतनी ही आगे बढ़ सकती थी।</p>\n<p>कुछ देर बाद उनके बीच की आख़िरी दूरी भी नहीं रही।</p>\n<p>कमरे में पहाड़ की ठंडी हवा थी और मेज़ पर रखे गेंदे के फूलों की हल्की-सी महक।</p>\n<p>“ठंड लग रही है?” विक्रम ने धीमे से पूछा।</p>\n<p>“थोड़ी।”</p>\n<p>वह एक पल रुकी।</p>\n<p>“कमरे से नहीं।”</p>\n<p>विक्रम ने चादर उठा दी। नैना उसके भीतर आ गई और अगले ही पल अपनी ही घबराहट पर हल्का-सा हँस पड़ी।</p>\n<p>विक्रम भी मुस्कराया।</p>\n<p>उसकी यही हँसी उस रात की सबसे ज़रूरी चीज़ थी।</p>\n<p>क्योंकि उसके बाद डर उतना बड़ा नहीं रहा।</p>\n<p>नैना ने ख़ुद उसे अपने और करीब खींच लिया।</p>\n<p>इस बार नैना के होंठ विक्रम के होंठों को पहले से ज़्यादा यकीन के साथ छू रहे थे। उँगलियाँ विक्रम की पीठ पर ठहर गईं और उनके बीच बची हुई आख़िरी सावधानियाँ भी धीरे-धीरे उतरने लगीं।</p>\n<p>किसी पल नैना को तकलीफ़ हुई तो उसने तुरंत बता दिया।</p>\n<p>विक्रम वहीं रुक गया।</p>\n<p>अपना माथा उसके माथे से लगाए तब तक ठहरा रहा जब तक उसके चेहरे का तनाव ढीला नहीं पड़ा।</p>\n<p>नैना ने उसकी आँखों में देखा।</p>\n<p>फिर ख़ुद उसे वापस अपने करीब खींच लिया।</p>\n<p>“रुको मत।”</p>\n<p>उसकी आवाज़ विक्रम के कान के पास बहुत धीमी थी।</p>\n<p>“डरकर इतना संभालो भी मत मुझे।”</p>\n<p>उसकी बाँहें उसके चारों तरफ कस गईं।</p>\n<p>“बस मेरे करीब रहो।”</p>\n<p>और विक्रम रहा।</p>\n<p>उसके बाद जो कुछ उनके बीच था, उसमें जल्दबाज़ी नहीं थी, मगर अब झिझक भी नहीं बची थी। दोनों एक-दूसरे की साँसों, स्पर्श और हर छोटी प्रतिक्रिया से अपनी रफ्तार समझते रहे।</p>\n<p>और जब आख़िर उनके बीच कोई दूरी नहीं रही, नैना ने अपना चेहरा उसके कंधे में छिपा लिया।</p>\n<p>उसके होंठों से विक्रम का नाम निकला।</p>\n<p>एक बार।</p>\n<p>फिर दोबारा।</p>\n<p>फिर जैसे उस पल उसके पास कहने के लिए वही एक शब्द बचा हो—</p>\n<p>“विक्रम…”</p>\n<p>और उन्हीं साँसों के बीच एक बार एक और शब्द निकला।</p>\n<p>बहुत धीमे।</p>\n<p>लगभग अपने-आप।</p>\n<p>“मोहब्बत…”</p>\n<p>नैना ने उसे वापस नहीं लिया।</p>\n<p>विक्रम ने भी उससे कोई जवाब नहीं माँगा।</p>\n<p>उस पल ज़रूरत नहीं थी।</p>\n<p>काफी देर बाद भी दोनों अलग नहीं हुए।</p>\n<p>नैना की उँगलियाँ उसकी पीठ पर धीरे-धीरे चल रही थीं, जैसे वह सिर्फ यह महसूस कर लेना चाहती हो कि वह सचमुच वहीं है।</p>\n<p>“ठीक हो?” विक्रम ने पूछा।</p>\n<p>नैना ने तुरंत जवाब नहीं दिया।</p>\n<p>अपने शरीर को, अपने मन को, उस पूरे पल को जैसे भीतर से जाँचकर फिर बोली—</p>\n<p>“थोड़ी तकलीफ़ है।”</p>\n<p>कुछ पल बाद उसके होंठों पर मुस्कान आई।</p>\n<p>“अलग लग रहा है।”</p>\n<p>और फिर—</p>\n<p>“लेकिन अच्छा।”</p>\n<p>विक्रम की बाँह उसके गिर्द और गहरी हो गई।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>“ऐसा नहीं लगा कि हमने कोई पल चुरा लिया।”</p>\n<p>उसकी आवाज़ उसकी छाती के पास से आ रही थी।</p>\n<p>“ऐसा लगा जैसे गुलमोहर के नीचे उस बेंच से जिस जगह की तरफ चलना शुरू किया था… आज वहाँ पहुँच गए।”</p>\n<p>विक्रम के होंठ उसके माथे से बहुत हल्के से छुए और वहीं एक पल ठहरे रहे।</p>\n<p>नैना उसके और करीब सिमट गई।</p>\n<p>कमरे में फिर ख़ामोशी उतर आई।</p>\n<p>मेज़ पर रखे गेंदे के फूलों की हल्की मीठी महक उनके आसपास बनी रही।</p>\n<p>कुछ देर बाद नैना ने कहा—</p>\n<p>“जो मैंने पहले कहा था… वो सच था।”</p>\n<p>“क्या?”</p>\n<p>“कि मैंने तुम्हें चुना है।”</p>\n<p>उसने अपना गाल उसकी छाती पर और आराम से रख लिया।</p>\n<p>“मुझे इसका अफसोस नहीं है।”</p>\n<p>एक लंबी साँस।</p>\n<p>“मुझे नहीं लगता कभी होगा।”</p>\n<p>विक्रम का हाथ उसके बालों में ठहर गया।</p>\n<p>“मुझे भी नहीं।”</p>\n<p>फिर बहुत धीमे बोला—</p>\n<p>“और आज की रात तुम्हारे लिए क्या मायने रखती है, ये मैं कभी हल्के में नहीं लूँगा।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सुबह नैना पहले जाग गई।</p>\n<p>विक्रम की आँख खुली तो वह उसके पास बैठी एक गीले कपड़े से उसके कंधे पर पड़े अपने नाखूनों के हल्के निशान साफ़ कर रही थी।</p>\n<p>“ये करने की ज़रूरत नहीं है।”</p>\n<p>उसकी आवाज़ अभी नींद से भारी थी।</p>\n<p>“मुझे करनी है।”</p>\n<p>नैना ने बिना रुके कपड़ा उसके कंधे से हंसली और फिर छाती तक फेर दिया।</p>\n<p>“रात तुमने मेरा ख़याल रखा था।”</p>\n<p>उसने ऊपर उसकी तरफ देखा।</p>\n<p>“सुबह मेरी बारी है।”</p>\n<p>काम ख़त्म करके वह उठने लगी तो विक्रम ने उसकी कलाई पकड़ ली।</p>\n<p>“पाँच मिनट और।”</p>\n<p>नैना हँस पड़ी।</p>\n<p>“पाँच मिनट?”</p>\n<p>विक्रम ने उसे वापस अपनी तरफ खींच लिया।</p>\n<p>इस बार नैना उसकी बाँहों में पिछली रात की तरह सँभलकर नहीं आई। उसकी उँगलियाँ विक्रम की उँगलियों में फँसीं और अगले ही पल उनके बीच की जगह पूरी तरह ख़त्म हो गई।</p>\n<p>“विक्रम…”</p>\n<p>वह उसके गाल के पास मुस्कराई।</p>\n<p>अब उसे समझ आ चुका था कि वे पाँच मिनट सिर्फ पाँच मिनट नहीं थे।</p>\n<p>“क्या चाहिए?”</p>\n<p>विक्रम ने जवाब नहीं दिया।</p>\n<p>सिर्फ उसे देखा।</p>\n<p>चेहरे पर वह धीमी-सी मुस्कान थी जिसे अब नैना पढ़ना सीख चुकी थी।</p>\n<p>नैना को दूसरी बार पूछने की ज़रूरत नहीं पड़ी।</p>\n<p>रात की झिझक सुबह तक नहीं बची थी।</p>\n<p>अब दोनों एक-दूसरे को थोड़ा और जानते थे—सिर्फ मन से नहीं, स्पर्श से भी। कौन-सा स्पर्श साँस रोक देता है, कहाँ हाथ ठहरता है तो दूसरा अपने-आप और करीब आ जाता है; रात ने उन्हें एक-दूसरे की वह भाषा भी सिखा दी थी जिसमें शब्द बहुत कम पड़ते थे।</p>\n<p>इस बार नैना ने भी ख़ुद को उतना नहीं रोका।</p>\n<p>उसकी बाँहें विक्रम के चारों तरफ कस गईं, उँगलियाँ उसकी पीठ पर और मज़बूती से ठहरीं और साँसों में पिछली रात वाली घबराहट की जगह एक खुली हुई चाहत थी।</p>\n<p>कुछ देर बाद वह उसका नाम लेने लगी।</p>\n<p>बस नाम।</p>\n<p>“विक्रम…”</p>\n<p>फिर वही।</p>\n<p>और फिर।</p>\n<p>जैसे उस सुबह बाकी सारे शब्द ग़ैरज़रूरी हो गए हों।</p>\n<p>इस बार उनके बीच की नज़दीकी पिछली रात से ज़्यादा तेज़ थी, ज़्यादा बेझिझक—इसलिए नहीं कि रात की नरमी कम हो गई थी, बल्कि इसलिए कि अब दोनों को मालूम था सामने वाला कहाँ खड़ा है।</p>\n<p>और दोनों वहीं होना चाहते थे।</p>\n<p>बहुत देर बाद नैना ने अपना चेहरा उसके कंधे में छिपाकर हँसते हुए कहा—</p>\n<p>“मुझे नहीं पता था तुम्हारे साथ सुबह ऐसी भी हो सकती है।”</p>\n<p>विक्रम की साँस अभी पूरी तरह सामान्य नहीं हुई थी।</p>\n<p>“मुझे भी करीब बीस मिनट पहले तक नहीं पता था।”</p>\n<p>नैना खुलकर हँस पड़ी।</p>\n<p>फिर वापस उसकी बाँहों में सिमट गई।</p>\n<p>कुछ देर दोनों चादर के नीचे वैसे ही उलझे पड़े रहे।</p>\n<p>बाहर सुबह पूरी तरह आ चुकी थी, पर भीतर किसी ने परदा नहीं हटाया।</p>\n<p>मेज़ पर गेंदे के फूल अब भी महक रहे थे, और घाटी की धूप खिड़की तक आकर रुक गई थी, जैसे उसे भी भीतर आने की जल्दी नहीं थी।</p>\n<p>कल तक विक्रम को लगता था कि कोई ज़िंदगी में आता है तो साथ चलता है। आज उसे पता चला कि कोई भीतर भी रह सकता है।</p>"}, {"chapter": 20, "title": "अध्याय 18 — मैं इंतज़ार कर रही हूँ", "content": "<h1>अध्याय 18 — मैं इंतज़ार कर रही हूँ</h1>\n<p>ड्यूटी पर लौटने से एक शाम पहले नैना ने तय कर लिया कि वह विक्रम को स्टेशन छोड़ने जाएगी।</p>\n<p>विक्रम ने एक से ज़्यादा बार कहा कि इसकी ज़रूरत नहीं है।</p>\n<p>नैना ने हर बार एक ही जवाब दिया—</p>\n<p>“तुम जा रहे हो और मैं घर बैठी रहूँ? नहीं।”</p>\n<p>“नैना—”</p>\n<p>“फ़ैसला कर चुकी हूँ। इस एक बात पर बहस मत करना।”</p>\n<p>स्टेशन पहुँचकर दोनों प्लेटफॉर्म पर खड़े रहे। ट्रेन आने में अभी बीस मिनट थे।</p>\n<p>उनके चारों तरफ रेलवे स्टेशन अपनी रोज़ की रफ्तार में चल रहा था—कुली सामान लेकर निकल रहे थे, दुकानदार आवाज़ लगा रहे थे, कोई परिवार बच्चों को सँभालते हुए डिब्बे का नंबर ढूँढ़ रहा था, कोई देर हो जाने के डर से भागता हुआ सामने से गुज़र रहा था।</p>\n<p>उस पूरी भागदौड़ के बीच वे दोनों थे जो जैसे अपनी जगह से हिलना नहीं चाहते थे।</p>\n<p>प्लेटफॉर्म की पीली बत्तियों के नीचे दो परछाइयाँ एक-दूसरे में इतनी मिली थीं कि भीड़ उनके आसपास से बहती हुई गुज़र रही थी।</p>\n<p>नैना काफी देर चुप रही।</p>\n<p>फिर बोली—</p>\n<p>“मुझे नहीं पता तुम्हारे बिना कैसे रहूँगी।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“रह लोगी। इससे मुश्किल चीज़ें सँभाली हैं तुमने।”</p>\n<p>“सँभाल लेना और किसी चीज़ को चाहना एक बात नहीं होती।”</p>\n<p>नैना ने हाथ बढ़ाकर विक्रम का कॉलर ठीक किया।</p>\n<p>कॉलर पहले से ठीक था।</p>\n<p>नैना के हाथों को उस वक्त कुछ करना ज़रूरी था, वरना उनकी हल्की-सी थरथराहट साफ़ दिखाई देती।</p>\n<p>“मैं कहीं नहीं जा रही, विक्रम।”</p>\n<p>नैना की उँगलियाँ कॉलर पर एक पल और ठहरी रहीं।</p>\n<p>“अब से तुम्हारी अगली छुट्टी तक जो भी हो… मैं इंतज़ार करूँगी।”</p>\n<p>विक्रम की आँखें उसके चेहरे पर टिक गईं।</p>\n<p>“जो भी हो,” विक्रम ने बहुत धीमे कहा, “बस एक बात याद रखना।”</p>\n<p>“क्या?”</p>\n<p>“मैं वापस आऊँगा।”</p>\n<p>नैना ने जवाब नहीं दिया।</p>\n<p>विक्रम को देखती रही।</p>\n<p>जैसे उस वाक्य को सुन नहीं, अपने भीतर कहीं रख रही हो।</p>\n<p>कुछ देर बाद ट्रेन प्लेटफॉर्म पर घुसी। पहियों और पटरियों की तेज़ आवाज़, ब्रेक की चीख, कुलियों की पुकार और यात्रियों की अचानक बढ़ी हलचल ने उनके आसपास की दुनिया फिर से उनके बीच ला खड़ी की।</p>\n<p>विक्रम ने कुछ और कहने के बजाय नैना को अपनी बाँहों में भर लिया।</p>\n<p>नैना का चेहरा उसके कंधे में छिप गया।</p>\n<p>नैना की मुट्ठियाँ विक्रम की कमीज़ की पीठ पर कस गईं—जैसे कुछ पल और पकड़कर रखने से जाने का वक्त भी कुछ पल पीछे खिसक जाएगा।</p>\n<p>“ज़िंदा लौटना।”</p>\n<p>नैना की आवाज़ विक्रम के कंधे में दबकर निकली।</p>\n<p>“बस इतना माँग रही हूँ।”</p>\n<p>विक्रम की बाँहें उसके चारों तरफ और गहरी हो गईं।</p>\n<p>“ज़िंदा लौटना, विक्रम।”</p>\n<p>“आऊँगा।”</p>\n<p>विक्रम को ट्रेन में चढ़ना पड़ा।</p>\n<p>विक्रम ने खिड़की के पास जगह ढूँढ़ ली। नैना वहीं प्लेटफॉर्म पर खड़ी रही।</p>\n<p>ट्रेन धीरे-धीरे चलने लगी तो नैना का एक हाथ उठा।</p>\n<p>वह ठीक से हाथ भी नहीं हिला रही थी।</p>\n<p>उठाए रही।</p>\n<p>जब तक उनके बीच की दूरी इतनी नहीं बढ़ गई कि उस इशारे का कोई मतलब ही नहीं बचा।</p>\n<p>फिर ट्रेन दूर होती गई।</p>\n<p>पहले डिब्बे छोटे हुए।</p>\n<p>फिर सिर्फ आवाज़ बची।</p>\n<p>और कुछ देर बाद वह भी नहीं।</p>\n<p>पटरियाँ देर तक काँपती रहीं, जैसे उन्हें भी कुछ याद रह गया हो।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>म्यांमार बॉर्डर पर पहुँचने के तीसरे दिन विक्रम को वह जगह दिखाई गई, जो नक़्शे पर सिर्फ एक पेंसिल का गोला थी।</p>\n<p>कर्नल ने गोले पर उँगली रखी।</p>\n<p>“चालीस के आसपास। हथियारों का डिपो। और वह इंसान जो हर महीने किसी न किसी गाँव को जलाता है।”</p>\n<p>एक पल।</p>\n<p>“यह काम 9 पैरा एसएफ़ को सौंपा गया है। तैयारी में कितना वक्त चाहिए?”</p>\n<p>“सात दिन।”</p>\n<p>“सात?”</p>\n<p>“सात दिन देखे बिना अंदर नहीं जाऊँगा, सर।”</p>\n<p>कर्नल ने उसे देखा, फिर सिर हिला दिया।</p>\n<p>“वक्त तुम्हारा।”</p>\n<p>“पहले मैं अकेला नहीं, चार जवानों के साथ जाऊँगा। रेकी। बाकी टीम बाद में।”</p>\n<p>“ठीक।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसी रात विक्रम चार जवान लेकर निकल गया—उनमें हवलदार थापा भी था।</p>\n<p>कोई सड़क नहीं। कोई गाड़ी नहीं। रेडियो साथ था, मगर बंद। रात भर पैदल जंगल के रास्ते, और दिन में किसी खाई या झाड़ी में छिपकर।</p>\n<p>जंगल रात में जागता था। झींगुरों की न थमने वाली झनकार, पत्तों के नीचे सरसराते कीड़े-पतंगे, दूर कहीं किसी उल्लू की भारी पुकार। एक बार झाड़ियों में कोई बड़ा जानवर खड़-खड़ करता हुआ गुज़रा, और पाँचों पत्थर बन गए। अँधेरे में उसकी आँखें दो पल चमकीं, फिर वह भी चला गया।</p>\n<p>तीसरे दिन पाँचों सरहद पार कर चुके थे।</p>\n<p>कैंप ढलान के नीचे था, घने बाँस के पीछे, जहाँ एक छोटी नदी बगल से गुज़रती थी। नदी की आवाज़ इतनी लगातार थी कि दूर से कोई कुछ और सुन ही नहीं सकता था। और कैंप के पीछे एक जेनरेटर घरघराता रहता था, जिसकी धीमी गूँज रात भर पूरे जंगल में फैली रहती।</p>\n<p>नदी रात में किसी पुरानी, अनथक साँस की तरह बहती थी—पत्थरों से टकराती, मोड़ों पर गहराती, और अपनी ही आवाज़ में हर दूसरी आवाज़ को डुबोती हुई।</p>\n<p>विक्रम सब गिनता गया।</p>\n<p>पहरेदार कहाँ खड़े होते हैं। कब बदलते हैं। किस झोंपड़ी में रोशनी देर तक रहती है। कौन-सी झोंपड़ी में कभी कोई नहीं जाता।</p>\n<p>चौथे दिन उसे ऐसी चीज़ दिखी जो किसी रिपोर्ट में नहीं थी।</p>\n<p>रात के दो बजे जेनरेटर बंद हो जाता था। डीज़ल बचाने के लिए। ठीक दो बजे।</p>\n<p>उसके बाद करीब बीस मिनट पूरे कैंप में अँधेरा रहता, और पहरेदार जागने की जगह बीड़ी सुलगाने बैठ जाते।</p>\n<p>हवलदार थापा ने उसकी तरफ देखा, और विक्रम ने बस एक उँगली उठाई।</p>\n<p>यही बीस मिनट।</p>\n<p>पाँचवें दिन बारिश आई, और पूरा जंगल एक साथ बोल पड़ा—पत्तों पर बूँदों की थाप, मेंढकों की गूँजती टर्र-टर्र, नदी का और भारी होता स्वर। बारिश की आड़ में उसने ख़ुद नदी का किनारा नापा—कहाँ पानी घुटनों तक है, कहाँ कमर तक, कहाँ पत्थर चिकने हैं।</p>\n<p>छठे दिन वह सबसे पास तक गया।</p>\n<p>पूरा दिन ठंडी, गँदली खाई में पड़ा रहा। एक जोंक कलाई तक चढ़ आई। उसने हटाई नहीं। दोपहर में पत्तों पर एक पतला हरा साँप सरकता आया और उसकी बाँह के ऊपर से गुज़र गया, ठंडा और बेआवाज़। विक्रम ने पलक तक नहीं झपकाई। थोड़ी दूर एक पहरेदार बैठा था, इतना पास कि उसकी साँस सुनाई देती थी। एक बार उसके बूट की नोक विक्रम के हाथ से बस दो इंच दूर रही।</p>\n<p>विक्रम की साँस रुकी रही।</p>\n<p>उस पल उसे ट्रेन की खिड़की की याद आई। प्लेटफॉर्म पर उठा एक हाथ, जो हिल नहीं रहा था, बस उठा रहा।</p>\n<p><i>जो भी हो, मैं वापस आऊँगा।</i></p>\n<p>पहरेदार उठा। आगे बढ़ गया।</p>\n<p>उस रात विक्रम ने पूरा नक़्शा एक पत्थर पर कोयले से खींच दिया।</p>\n<p>पाँच झोंपड़ियाँ। दो पहरेदार-चौकियाँ। एक डिपो। और बीच की सबसे बड़ी झोंपड़ी, जहाँ वह इंसान सोता था।</p>\n<p>पाँच निशाने।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले पंद्रह दिन—</p>\n<p>कुछ नहीं।</p>\n<p>विक्रम के आख़िरी फोन के अगले दिन नैना ने विक्रम का नंबर मिलाया।</p>\n<p>नैना को हमेशा की तरह घंटी सुनाई देने की उम्मीद थी।</p>\n<p>मगर दूसरी तरफ न घंटी थी, न कोई आवाज़।</p>\n<p>एक ऐसी चुप्पी जो कुछ नहीं बताती।</p>\n<p>अगले दिन उसने फिर फोन किया।</p>\n<p>फिर उसके अगले दिन।</p>\n<p>हर बार वही खालीपन।</p>\n<p>अगर सिर्फ नेटवर्क नहीं था तो वह इंतज़ार कर सकती थी।</p>\n<p>अगर कोई ऑपरेशन था तो भी।</p>\n<p>मुश्किल सिर्फ इतनी थी कि उसे पता ही नहीं था कि वह किस बात का इंतज़ार कर रही है।</p>\n<p>पाँचवें दिन तक खाना सामने रखा रहता और आधा भी ख़त्म नहीं होता।</p>\n<p>आठवें दिन तक नींद कुछ घंटों की चीज़ नहीं रही थी। वह छोटे-छोटे टुकड़ों में आती—और हर थोड़ी देर बाद नैना इस यकीन के साथ जाग जाती कि उसका फोन बजा है।</p>\n<p>फोन नहीं बजा होता।</p>\n<p>विक्रम की आख़िरी बात बार-बार भीतर लौटती—</p>\n<p><b>जो भी हो, याद रखना। मैं वापस आऊँगा।</b></p>\n<p>जिस वक्त उसने कहा था, वह एक भरोसा था।</p>\n<p>दिन गुज़रते गए तो वही शब्द नैना के सीने में कहीं अटक गए।</p>\n<p>बारहवीं शाम उसने रसोई में दो बार गैस जलाई और दोनों बार बिना कुछ पकाए बंद कर दी।</p>\n<p>फ्लैट में अजीब-सी ख़ामोशी थी।</p>\n<p>दो हफ्तों से उस जगह से वह एक आवाज़ गायब थी जिसकी नैना को आदत हो चुकी थी।</p>\n<p>बाहर सड़क की आवाज़ उस ऊँचाई तक नहीं आ रही थी। पंखा बंद था। कमरे में सिर्फ रसोई की घड़ी की लगातार टिक-टिक थी और अपनी ही साँसें, जो उस रात उसे ज़रूरत से ज़्यादा सुनाई दे रही थीं।</p>\n<p>नैना अपनी छोटी-सी मेज़ के सामने बैठ गई।</p>\n<p>सामने एक खाली काग़ज़ रखा था।</p>\n<p>टेबल लैम्प की रोशनी सिर्फ उस काग़ज़ तक सीमित थी; बाकी कमरा लगभग अँधेरे में था।</p>\n<p>रोशनी का वह गोल घेरा उस रात पूरी दुनिया था, और उसके बाहर अँधेरे में विक्रम कहीं था, जिसे वह देख नहीं सकती थी।</p>\n<p>कुछ देर वह यूँ ही बैठी रही।</p>\n<p>फिर जाने किस ख़याल से उसकी नज़र उस छोटी ब्लेड पर गई जिससे वह पेंसिलें छीलती थी।</p>\n<p>उसने उसे उठा लिया।</p>\n<p>अँगूठे के पोर पर बहुत हल्का-सा दबाया।</p>\n<p>फिर कलम उठाई।</p>\n<p>और काग़ज़ पर तीन पंक्तियाँ लिखीं—</p>\n<p><i>I am waiting.</i></p>\n<p><i>You promised me you will come back.</i></p>\n<p><i>Come back alive, Vikram.</i></p>\n<p>मैं इंतज़ार कर रही हूँ।</p>\n<p>तुमने वादा किया है कि लौटोगे।</p>\n<p>ज़िंदा लौटना, विक्रम।</p>\n<p>तीसरी पंक्ति तक पहुँचते-पहुँचते खून इतना हल्का पड़ चुका था कि आगे उससे कुछ लिखा नहीं जा सकता था।</p>\n<p>नैना ने दोबारा अँगूठा नहीं काटा।</p>\n<p>बस ब्लेड एक तरफ रख दी।</p>\n<p>लिफाफे के ऊपर विक्रम का नाम और उसकी यूनिट का पता साधारण स्याही से लिखा—साफ़, सीधी लिखावट में; इतनी सँभली हुई कि बाहर से देखने वाला अंदाज़ा भी नहीं लगा सकता था कि अंदर रखे काग़ज़ तक पहुँचते-पहुँचते वही हाथ कितना काँपा था।</p>\n<p>उसी रात उसने खत पोस्ट कर दिया।</p>\n<p>लाल डिब्बे में लिफाफा गिरने की हल्की-सी आवाज़ आई, और नैना को लगा जैसे उसने अपना कुछ हिस्सा भी साथ गिरा दिया हो।</p>\n<p>उसे यह तक नहीं मालूम था कि वह विक्रम तक पहुँचेगा भी या नहीं।</p>\n<p>फिर भी भेज दिया।</p>\n<p>उस वक्त पहुँचने से ज़्यादा ज़रूरी यह था कि वे तीन पंक्तियाँ अब सिर्फ उसके भीतर न रहें।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सातवीं शाम सूरज ढलते ही विक्रम ने पहली बार रेडियो चालू किया।</p>\n<p>दो वाक्य, फुसफुसाहट से भी धीमी आवाज़ में।</p>\n<p>“निर्देशांक भेज रहा हूँ। टीम को वहीं उतारिए।”</p>\n<p>और रेडियो फिर बंद।</p>\n<p>घना जंगल था। हेलिकॉप्टर के उतरने की जगह ही नहीं थी। इसलिए वह कैंप से कई किलोमीटर दूर, पेड़ों की चोटियों के ठीक ऊपर, हवा में ठहर गया—बिना रोशनी, बस उसके पंखों की धीमी थरथराहट।</p>\n<p>रस्सियाँ नीचे गिरीं।</p>\n<p>और 9 पैरा एसएफ़ के बारह कमांडो एक-एक करके उन पर फिसलते हुए अँधेरे जंगल में उतर गए। आख़िरी के ज़मीन छूते ही रस्सियाँ ऊपर खिंच गईं, और हेलिकॉप्टर उतनी ही चुपचाप दूर होता गया।</p>\n<p>नीचे जंगल ने उन्हें निगल लिया—नम मिट्टी, सड़े पत्तों की गंध, और ऊपर कहीं बंदरों की अचानक जागी बेचैन चीख, जो कुछ पल में फिर थम गई।</p>\n<p>इसके बाद फिर वही पैदल रास्ता। दो घंटे, नदी के मोड़ तक।</p>\n<p>विक्रम वहाँ पहले से इंतज़ार कर रहा था।</p>\n<p>किसी ने कुछ नहीं कहा।</p>\n<p>उसने नदी किनारे के एक चपटे पत्थर की तरफ इशारा किया। कोयले की लकीरें टॉर्च की ढकी हुई हल्की रोशनी में उभर आईं।</p>\n<p>उसकी उँगली एक-एक निशाने पर रुकी। हर निशाने के साथ एक टुकड़ी का इशारा।</p>\n<p>पहली टुकड़ी, दोनों चौकियाँ। दूसरी, डिपो। तीसरी, झोंपड़ियाँ। और बीच की सबसे बड़ी झोंपड़ी—</p>\n<p>उसने अपनी छाती पर हाथ रखा।</p>\n<p>“दो बजे जेनरेटर बंद होगा।”</p>\n<p>फुसफुसाहट से भी धीमी आवाज़।</p>\n<p>“उसके पहले कोई गोली नहीं। जब तक मैं इशारा न दूँ, कोई नहीं।”</p>\n<p>“जी, सर।”</p>\n<p>“सिर्फ निशाने। एक भी गोली फ़ालतू नहीं।”</p>\n<p>फिर कुछ पल रुककर—</p>\n<p>“एक भी इंसान पीछे नहीं छूटेगा।”</p>\n<p>इस बार कोई जवाब नहीं आया।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>नदी पार करना सबसे लंबा काम था। पानी बर्फ़-सा ठंडा था और चारों तरफ सिर्फ उसकी आवाज़। हर कदम पर पैर जमाना पड़ता। विक्रम सबसे आगे चला, एक हाथ में रस्सी का सिरा।</p>\n<p>सब अपनी-अपनी जगह पहुँच गए।</p>\n<p>फिर इंतज़ार।</p>\n<p>इंतज़ार में जंगल की आवाज़ें और साफ़ सुनाई देने लगीं—झींगुरों की झनकार, नदी की गूँज, और कहीं दूर किसी जानवर की कराहती-सी पुकार।</p>\n<p>दो बजकर एक मिनट पर जेनरेटर की गूँज अचानक थम गई।</p>\n<p>पूरा कैंप एक साँस में अँधेरे में डूब गया।</p>\n<p>और जो आवाज़ें अब तक उसकी घरघराहट के नीचे दबी थीं, एक साथ ऊपर आ गईं—झींगुर, नदी, पत्तों की सरसराहट। जैसे पूरा जंगल कैंप के अँधेरे में उतर आया हो।</p>\n<p>पहरेदार की बीड़ी की लाल नोक हवा में चमकी।</p>\n<p>विक्रम पहले ही उसके पीछे था।</p>\n<p>एक हाथ, एक पल, और बीड़ी ज़मीन पर गिरकर बुझ गई। पहरेदार बिना आवाज़ के नीचे बैठ गया।</p>\n<p>उसने हाथ उठाया।</p>\n<p>एक इशारा।</p>\n<p>और सब कुछ एक साथ हुआ—</p>\n<p>दोनों चौकियों पर एक ही पल में दो चिंगारियाँ चमकीं। डिपो की तरफ से बस एक धीमी, दबी आवाज़ आई। झोंपड़ियों के दरवाज़ों पर एक-एक जवान पहुँचकर रुक गया।</p>\n<p>कैंप में किसी को सँभलने का वक्त ही नहीं मिला।</p>\n<p>विक्रम बीच की झोंपड़ी के दरवाज़े पर था।</p>\n<p>भीतर से किसी ने उठते हुए कुछ कहा।</p>\n<p>दरवाज़ा खुला।</p>\n<p>कुछ पल बाद वह इंसान जो हर महीने किसी गाँव को जलाता था, फर्श पर था।</p>\n<p>बाहर कहीं हवलदार थापा की चीख आई। एक गोली उसकी जाँघ को चीरती निकली थी।</p>\n<p>विक्रम बिना रुके उसके पास पहुँचा और उसे कंधे पर लाद लिया।</p>\n<p>“सर, मुझे छोड़िए—”</p>\n<p>“चुप।”</p>\n<p>बस इतना।</p>\n<p>दो मिनट बाद डिपो में विस्फोट हुआ।</p>\n<p>आधा जंगल पल भर के लिए दिन जैसा रोशन हो गया। पेड़ों पर सोए पक्षी चीखते हुए एक साथ उड़े, और फड़फड़ाते पंखों का शोर कुछ पल तक नदी की आवाज़ से भी ऊँचा रहा। फिर आग की लाल लपटें और धुएँ का काला पर्दा।</p>\n<p>“निकलो!”</p>\n<p>टीम पीछे हटी। एक-एक करके, गिनती के साथ।</p>\n<p>विक्रम ने थापा को कंधे पर लिए नदी में उतरकर आख़िरी बार गिनती पूरी की।</p>\n<p>सब थे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>भोर से ठीक पहले वे सरहद के इस तरफ लौट आए। पूरब में आसमान राख-सा हल्का पड़ रहा था, और जंगल पहली चिड़ियों की पुकार से धीरे-धीरे जाग रहा था—जैसे रात भर कुछ हुआ ही न हो।</p>\n<p>थापा को मेडिकल टेंट तक पहुँचाया गया। डॉक्टर ने उसकी जाँघ की चोट देखी और कहा कि वह बच जाएगा।</p>\n<p>कर्नल पास आए।</p>\n<p>“पूरा कैंप ख़त्म। डिपो भी। कोई नहीं खोया।”</p>\n<p>एक पल रुके।</p>\n<p>फिर बोले—</p>\n<p>“सात दिन सही कहे थे तुमने।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>उसने अपने हाथ देखे। हथेली पर कोयले की काली लकीरें अब भी बची थीं।</p>\n<p>उसकी जेब में फोन चुप पड़ा था। यहाँ सिग्नल नहीं आता था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>पंद्रहवें दिन फोन आया।</p>\n<p>स्क्रीन पर विक्रम का नाम देखते ही नैना एक पल उसे देखती रह गई।</p>\n<p>पंद्रह दिन बाद उस नाम से कमरे की रोशनी जैसे थोड़ी बढ़ गई।</p>\n<p>फिर फोन उठाया।</p>\n<p>विक्रम ने नैना को कुछ पूछने का मौका नहीं दिया।</p>\n<p>“मैं ठीक हूँ।”</p>\n<p>नैना की साँस वहीं अटक गई।</p>\n<p>“एक खरोंच तक नहीं है। बिल्कुल ठीक हूँ।”</p>\n<p>नैना ने पंद्रह दिन से जो कुछ भीतर कसकर पकड़ रखा था, विक्रम की आवाज़ सुनते ही वह ढीला पड़ गया।</p>\n<p>नैना कुछ नहीं बोल पाई।</p>\n<p>विक्रम भी चुप रहा।</p>\n<p>दोनों तरफ सिर्फ साँसें थीं।</p>\n<p>लेकिन पंद्रह दिनों में पहली बार ख़ामोशी का मतलब डर नहीं था।</p>\n<p>कुछ देर बाद विक्रम बोला—</p>\n<p>“मुझे तुम्हें बताना है क्या हुआ था।”</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>“बोलो।”</p>\n<p>“रिपोर्ट करते ही म्यांमार बॉर्डर भेज दिया गया। वहाँ सिग्नल नहीं था, और संपर्क की इजाज़त भी नहीं।”</p>\n<p>वह रुका।</p>\n<p>“मैं इतना भी नहीं बता पाया कि कुछ दिन फोन नहीं होगा।”</p>\n<p>नैना अब भी कुछ नहीं बोली।</p>\n<p>“सॉरी।”</p>\n<p>“तुम्हारी ग़लती नहीं थी।”</p>\n<p>“पता है।”</p>\n<p>विक्रम की आवाज़ धीमी हो गई।</p>\n<p>“फिर भी मुझे पता है उन दिनों ने तुम्हारे साथ क्या किया होगा… जब तुम्हें इनमें से कुछ भी मालूम नहीं था।”</p>\n<p>नैना ने बहुत देर बाद साँस छोड़ी।</p>\n<p>“अब तुम ठीक हो।”</p>\n<p>“हाँ।”</p>\n<p>उस वक्त उसके लिए बस इतना ही काफी था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>खत विक्रम तक उसके सात दिन बाद पहुँचा।</p>\n<p>आर्मी पोस्ट अपनी ही रफ्तार से रास्ते तय करती थी। जब तक वह लिफाफा उसके हाथ में आया, विक्रम जान चुका था कि नैना ठीक है और नैना जान चुकी थी कि वह सुरक्षित है।</p>\n<p>दोपहर ढल रही थी।</p>\n<p>विक्रम मेस के बाहर खड़ा था जब उसने लिफाफा खोला।</p>\n<p>काग़ज़ खुलते ही विक्रम की नज़र उन हल्की जंग-सी भूरी पड़ चुकी पंक्तियों पर गई।</p>\n<p>पहली पंक्ति पूरी पढ़ने से पहले ही वह समझ गया कि वह क्या देख रहा है।</p>\n<p>उसका हाथ स्थिर हो गया।</p>\n<p>उसने तीनों पंक्तियाँ पढ़ीं।</p>\n<p>फिर दोबारा।</p>\n<p>काग़ज़ पकड़े विक्रम की मुट्ठी भिंच गई।</p>\n<p>फिर अपने ही ऊपर एक बेबस गुस्सा उठा।</p>\n<p>इतने दिन वह उससे संपर्क नहीं कर सकता था।</p>\n<p>उसमें उसकी कोई ग़लती नहीं थी।</p>\n<p>वह कुछ अलग कर भी नहीं सकता था।</p>\n<p>मगर इन सारी सच्चाइयों से उस तस्वीर में कुछ नहीं बदल रहा था जो अब उसके दिमाग में बन चुकी थी—नैना अकेली, सामने खाली काग़ज़, हाथ में ब्लेड, और वह ख़ुद उससे इतनी दूर कि उसे यह तक बताने का कोई रास्ता नहीं कि वह ज़िंदा है।</p>\n<p>विक्रम अपने शरीर पर लगी कोई चोट ज़्यादा आसानी से सह लेता।</p>\n<p>यह बेबसी उससे कहीं ज़्यादा भारी थी।</p>\n<p>विक्रम ने उसी शाम फोन किया।</p>\n<p>आवाज़ जितनी सामान्य रखना चाहता था, उतनी रही नहीं।</p>\n<p>“तुम्हारा खत मिला।”</p>\n<p>दूसरी तरफ कुछ पल चुप्पी रही।</p>\n<p>“अच्छा।”</p>\n<p>“नैना…”</p>\n<p>विक्रम ने काग़ज़ फिर देखा।</p>\n<p>“तुमने इसे खून से लिखा है।”</p>\n<p>नैना ने कुछ नहीं कहा।</p>\n<p>“ख़ुद को चोट क्यों पहुँचाई?”</p>\n<p>“चोट नहीं थी।”</p>\n<p>जवाब ज़रूरत से ज़्यादा जल्दी आया।</p>\n<p>फिर नैना ने ख़ुद ही बात ठीक की—</p>\n<p>“मतलब… शरीर वाली चोट नहीं। बस हल्की-सी चुभन थी। लगभग कुछ भी नहीं।”</p>\n<p>“फिर क्यों?”</p>\n<p>इस बार नैना काफी देर चुप रही।</p>\n<p>जब बोली तो उसकी आवाज़ में वह तेज़ी नहीं थी जो अक्सर मुश्किल बातों के सामने उसकी ढाल बन जाती थी।</p>\n<p>“क्योंकि जो दर्द था वो कहीं और था, विक्रम।”</p>\n<p>उसने साँस ली।</p>\n<p>“पंद्रह दिन तक ये न जानना कि तुम कहाँ हो, कैसे हो, ज़िंदा हो भी या…”</p>\n<p>वाक्य वहीं रुक गया।</p>\n<p>वह शब्द नैना से नहीं बोला गया।</p>\n<p>“वो तकलीफ़ उस छोटी-सी ब्लेड से कहीं ज़्यादा थी। शायद उस रात मुझे लगा कि जो भीतर हो रहा है उसका थोड़ा-सा निशान बाहर भी दिखाई देना चाहिए।”</p>\n<p>वह ख़ुद भी जैसे अपनी बात समझने की कोशिश कर रही थी।</p>\n<p>“ठीक से समझा नहीं सकती। शायद कुछ चीज़ें समझाने बैठो तो और ग़लत लगने लगती हैं।”</p>\n<p>उसकी आवाज़ टूट गई।</p>\n<p>और फिर नैना रोई।</p>\n<p>अँगूठे की उस मामूली चुभन के लिए नहीं।</p>\n<p>उन पंद्रह दिनों के लिए।</p>\n<p>हर उस रात के लिए जब फोन नहीं बजा।</p>\n<p>हर उस सुबह के लिए जब उसने ख़ुद को समझाया कि आज ख़बर आएगी।</p>\n<p>हर उस पल के लिए जब उसके पास डर था, मगर उसे रखने के लिए कोई दूसरा कंधा नहीं।</p>\n<p>विक्रम फोन पर रहा।</p>\n<p>बहुत कम बोला।</p>\n<p>दूरी के उस पार वह उसे बाँहों में नहीं भर सकता था, उसके बालों पर हाथ नहीं फेर सकता था, उसके पास बैठ नहीं सकता था।</p>\n<p>उस रात उसकी आवाज़ ही वह एक चीज़ थी जो वह नैना को दे सकता था।</p>\n<p>इसलिए वह वहीं रहा।</p>\n<p>जब तक उसका रोना धीरे-धीरे थमा नहीं।</p>\n<p>जब तक साँसें फिर बराबर नहीं हुईं।</p>\n<p>काफी देर बाद नैना बोली—</p>\n<p>“अब ठीक हूँ।”</p>\n<p>फिर कुछ पल रुककर—</p>\n<p>“बस तुम्हें पता होना चाहिए था कि वो पंद्रह दिन असल में कैसे थे। वो वाला जवाब नहीं जो मैं किसी और को देती।”</p>\n<p>उसकी आवाज़ बहुत धीमी थी।</p>\n<p>“सच वाला।”</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>“अब पता है।”</p>\n<p>विक्रम के हाथ में अब भी वही काग़ज़ था।</p>\n<p>“और भूलूँगा नहीं।”</p>\n<p>कुछ पल बाद उसने कहा—</p>\n<p>“न खत।”</p>\n<p>फिर बहुत धीरे—</p>\n<p>“न ये कि उसे लिखने की कीमत तुम्हें क्या देनी पड़ी।”</p>\n<p>फोन रखने के बाद विक्रम ने काग़ज़ को बहुत सावधानी से तह किया।</p>\n<p>इतना छोटा कि उसकी वर्दी की छाती वाली जेब में आ जाए।</p>\n<p>वही जेब जिसमें कभी रेड्डी एक तस्वीर रखा करता था—किनारों से घिस चुकी उस लड़की की तस्वीर, जिसकी शादी कभी नहीं हो पाई और जिससे किया गया वादा कभी पूरा नहीं हुआ।</p>\n<p>विक्रम ने उस ख़याल को पूरा होने नहीं दिया।</p>\n<p>विक्रम ने नैना का खत जेब में रखा।</p>\n<p>फ्लैप बंद किया।</p>\n<p>और हथेली कुछ पल वहीं ठहरी रही, जैसे किसी वादे पर हाथ रखा हो।</p>"}, {"chapter": 21, "title": "अध्याय 19 — चार दिन, एक घर", "content": "<h1>अध्याय 19 — चार दिन, एक घर</h1>\n<p>म्यांमार बॉर्डर की उस ख़ामोश तैनाती के करीब दो महीने बाद विक्रम को अगली छुट्टी मिली।</p>\n<p>इस बार सिर्फ चार दिन।</p>\n<p>मगर पंद्रह दिनों की उस ख़ामोशी के बाद चार दिन भी किसी दौलत से कम नहीं लग रहे थे।</p>\n<p>नैना उसे लेने दिल्ली एयरपोर्ट पहुँची।</p>\n<p>पिछली विदाई वाले रेलवे प्लेटफॉर्म की घबराहट इस बार उसके चेहरे पर नहीं थी। विक्रम अराइवल गेट से बाहर निकला ही था—एक कंधे पर डफल बैग अब भी टँगा हुआ—कि नैना सीधे उसके पास गई और दोनों बाँहें उसकी गर्दन के चारों तरफ डाल दीं।</p>\n<p>सामान्य मुलाक़ात में जितनी देर कोई किसी को थामता है, उससे थोड़ी देर ज़्यादा वह उसी तरह उससे लगी रही।</p>\n<p>“तुम सच में यहाँ हो।”</p>\n<p>नैना की आवाज़ विक्रम के कंधे के पास दब गई।</p>\n<p>“हर बार तुम्हें देखकर पहले ख़ुद को यकीन दिलाना पड़ता है।”</p>\n<p>“यहाँ हूँ।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>“पूरे चार दिन।”</p>\n<p>नैना उससे अलग हुई।</p>\n<p>“चार दिन जिन्हें मैं सोने की तरह बचाकर रखने वाली हूँ।”</p>\n<p>नैना का फ्लैट विक्रम के लिए नया नहीं था। वह इसमें पहले भी आ चुका था।</p>\n<p>दो बेडरूम का वह छोटा-सा फ्लैट था—एक तरफ छोटा लिविंग रूम और किचनेट, एक कमरा नैना का और दूसरा छोटा कमरा जो अब ज़्यादातर सामान रखने के काम आता था। नैना को वहाँ रहते काफी वक्त हो चुका था और अब उस घर की हर चीज़ पर उसकी अपनी छाप थी।</p>\n<p>विक्रम का बैग छोटे कमरे के कोने में रखा था—बस पहली शाम तक; फिर वह उसे उठाकर बादशाहपुर अपने घर चला गया। नैना का फ्लैट उसके लिए दिन भर का ठिकाना था, रात का नहीं।</p>\n<p>पहले ही दिन उसने ख़ुद को रसोई की अलमारी से बिना पूछे गिलास निकालते पाया।</p>\n<p>सुबह वह बादशाहपुर से पहुँचता तो नैना पूछती नहीं—दो कप चाय बना देती।</p>\n<p>सुबह की धूप में दोनों कप की भाप एक-दूसरे में मिल जाती, जैसे वे हमेशा से वहीं रखे जाते रहे हों।</p>\n<p>नैना बर्तन धोती तो विक्रम पास खड़ा उन्हें पोंछकर रख देता। किसका काम क्या है, इस पर कोई बात नहीं हुई; दूसरी सुबह तक यही उनका तरीका बन गया था।</p>\n<p>दूसरी शाम नैना ने ठीक से खाना बनाया।</p>\n<p>अपनी माँ से सीखी हुई पनीर की सब्ज़ी, जिसे वह अकेले अपने लिए बनाने की मेहनत शायद ही कभी करती थी।</p>\n<p>विक्रम किचन के पास खड़ा उसे काम करते देख रहा था।</p>\n<p>“इतना सब करने की ज़रूरत नहीं थी।”</p>\n<p>नैना ने पलटकर उसे देखा।</p>\n<p>“ज़रूरत नहीं थी।”</p>\n<p>फिर वापस कड़ाही की तरफ मुड़ गई।</p>\n<p>“मन था।”</p>\n<p>“फ़र्क़?”</p>\n<p>“बहुत।”</p>\n<p>नैना ने चम्मच चलाते हुए कहा—</p>\n<p>“भूख लगी हो इसलिए खाना बनाना अलग बात है। किसी को कुछ ऐसा खिलाना हो जिस पर तुम्हें ख़ुद थोड़ा गर्व हो, वो अलग।”</p>\n<p>दोनों ने फर्श पर पालथी मारकर खाना खाया। प्लेटें घुटनों पर थीं और पीछे टीवी पर कोई पुरानी हिंदी फिल्म धीमी आवाज़ में चल रही थी।</p>\n<p>छोटे-से फ्लैट में ताज़े बने खाने की गर्म महक थी।</p>\n<p>और पहली बार उस महक में किसी के आने का इंतज़ार नहीं, किसी के होने का सुकून था।</p>\n<p>विक्रम ने दूसरी बार सब्ज़ी लेते हुए कहा—</p>\n<p>“इसकी आदत पड़ सकती है।”</p>\n<p>नैना ने तुरंत उसकी तरफ देखा।</p>\n<p>“ये सिर्फ पनीर की तारीफ है तो अभी साफ़ कर दो।”</p>\n<p>विक्रम हँसा।</p>\n<p>“पनीर से ज़्यादा की बात कर रहा हूँ।”</p>\n<p>नैना एक पल उसे देखती रही।</p>\n<p>“अच्छा है।”</p>\n<p>नैना ने अपनी प्लेट में नज़र झुका ली, मगर चेहरे पर आती मुस्कान छिपी नहीं।</p>\n<p>“क्योंकि मैंने सोचना शुरू कर दिया है कि इससे दोगुनी बड़ी किचन कैसी लगेगी।”</p>\n<p>विक्रम का हाथ एक पल के लिए रुक गया।</p>\n<p>नैना ने सहजता से आगे कहा—</p>\n<p>“और उसमें ठीक-ठाक कुर्सियाँ होंगी। हर बार फर्श पर नहीं बैठना पड़ेगा।”</p>\n<p>विक्रम अब भी उसे देख रहा था।</p>\n<p>नैना ने उसकी नज़र पकड़ ली।</p>\n<p>“क्या?”</p>\n<p>“कुछ नहीं।”</p>\n<p>“ऐसे मत देखो।”</p>\n<p>“कैसे?”</p>\n<p>“जैसे मैंने कुछ बहुत बड़ा बोल दिया।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>नैना ने रोटी का टुकड़ा तोड़ा।</p>\n<p>“मैं उन चीज़ों की कल्पना नहीं करती जिन्हें चाहती नहीं हूँ।”</p>\n<p>इस बार विक्रम ने कुछ नहीं कहा।</p>\n<p>कहने की ज़रूरत भी नहीं थी।</p>\n<p>तीसरे दिन की दोपहर दोनों सोफे पर बैठे थे।</p>\n<p>कहीं जाने का कोई कार्यक्रम नहीं था।</p>\n<p>दरवाज़े पर दस्तक हुई।</p>\n<p>नैना ने भौंहें सिकोड़कर देखा।</p>\n<p>“मैं किसी को एक्सपेक्ट नहीं कर रही।”</p>\n<p>दरवाज़ा खोला तो सामने उसकी छोटी बहन खड़ी थी—चेहरे पर ऐसी मुस्कान जैसे किसी को बिना बताए पहुँच जाना अपने-आप में कोई बड़ी जीत हो।</p>\n<p>“सुनैना?”</p>\n<p>नैना उसे देखती रह गई।</p>\n<p>“तुम यहाँ क्या—”</p>\n<p>“सीधे एयरपोर्ट से आ रही हूँ। घर पर किसी को नहीं बताया—न माँ को, न पापा को। आज तुम्हारे यहाँ रुकूँगी, कल घर जाकर ऐसे पहुँचूँगी जैसे अभी-अभी लैंड हुई हूँ।”</p>\n<p>बिना बाकायदा बुलाए वह अंदर आ गई।</p>\n<p>फिर सुनैना की नज़र सोफे से उठते विक्रम पर पड़ी।</p>\n<p>कदम वहीं रुक गए।</p>\n<p>“ओह।”</p>\n<p>नैना अब भी दरवाज़े के पास खड़ी थी।</p>\n<p>“तुमने बताया क्यों नहीं कि आ रही हो?”</p>\n<p>“क्योंकि सरप्राइज़ देना था।”</p>\n<p>सुनैना ने फिर विक्रम को देखा।</p>\n<p>“हालाँकि लगता है सरप्राइज़ दोनों तरफ हो गया।”</p>\n<p>सुनैना उसे बिना किसी झिझक के देख रही थी—ठीक उसी सीधेपन से जो नैना में भी था; सुनैना के भीतर उसका थोड़ा ज़्यादा शरारती रूप था।</p>\n<p>“आप ही हैं,” सुनैना ने कहा।</p>\n<p>विक्रम ने हाथ आगे बढ़ाया।</p>\n<p>“विक्रम।”</p>\n<p>फिर मुस्कराया।</p>\n<p>“और तुम वही बहन हो जिसके बारे में काफी कुछ सुन चुका हूँ।”</p>\n<p>सुनैना ने हाथ मिलाया। अब वह विक्रम को ठीक से देख रही थी—उसकी लंबाई, कंधों की बनावट, चेहरे की मजबूत, साफ़ रेखाएँ। एक पल के लिए सुनैना के चेहरे पर कुछ आया—तेज़, अनचाहा—और उतनी ही जल्दी गायब भी हो गया।</p>\n<p>“उम्मीद है ज़्यादातर अच्छा।”</p>\n<p>“ज़्यादातर,” नैना ने पीछे से कहा।</p>\n<p>सुनैना ने बहन की तरफ देखा।</p>\n<p>“सिर्फ ज़्यादातर?”</p>\n<p>“पहले फोन करना सीखो, फिर बाकी तारीफें मिलेंगी।”</p>\n<p>“फोन कर देती तो ये सब कैसे पता चलता?”</p>\n<p>सुनैना आर्मचेयर पर ऐसे बैठ गई जैसे पिछले कई महीनों से वहीं रह रही हो।</p>\n<p>नैना भी वापस सोफे पर आ गई।</p>\n<p>“बेडफोर्डशायर कैसा चल रहा है?”</p>\n<p>सुनैना के होंठों पर शरारती मुस्कान आई।</p>\n<p>“आयरनी से भरा हुआ।”</p>\n<p>“मतलब?”</p>\n<p>“मेरी मेन क्लास में चालीस स्टूडेंट हैं। पच्चीस इंडियन, पाँच पाकिस्तानी, चार बांग्लादेशी, तीन श्रीलंकन, दो नेपाली…”</p>\n<p>सुनैना ने नाटकीय विराम लिया।</p>\n<p>“और एक ब्रिटिश।”</p>\n<p>विक्रम हँस पड़ा।</p>\n<p>“बेचारा।”</p>\n<p>“वही तो। ग्रुप प्रोजेक्ट में जब कोई समोसे लेकर आता है तो सबसे ज़्यादा कन्फ्यूज़ वही दिखता है। कई बार भूल जाती हूँ कि मैं इंग्लैंड में हूँ। पूरा सबकॉन्टिनेंट बैठा है—बस ब्रिटिश राज गायब है और उसकी जगह एक बेचारा असली ब्रिटिश लड़का बैठा है।”</p>\n<p>तीनों हँसे।</p>\n<p>मगर सुनैना की हँसी कुछ ही क्षण में हल्की पड़ गई।</p>\n<p>“वैसे मज़ाक से हटकर सोचो तो बात दिलचस्प है।”</p>\n<p>नैना ने उसकी तरफ देखा।</p>\n<p>“पूरे देशों की डेमोग्राफी धीरे-धीरे बदलती रहती है। क्लासरूम में छोटी बात लगती है, मगर बीस-तीस साल बाद वही चीज़ पॉलिटिक्स बदल देती है—कौन वोट करता है, किसकी नुमाइंदगी होती है।”</p>\n<p>वह एक पल रुकी।</p>\n<p>“मुझे नहीं लगता ब्रिटेन ने अभी ठीक से सोचा है कि लंबे वक्त में इसका मतलब क्या होगा।”</p>\n<p>नैना उसे थोड़ी देर देखती रही।</p>\n<p>नैना की भौंहें ऊपर उठीं और होंठों पर वही मुस्कान आ गई, जो तब आती है जब कोई अपना छोटा अचानक बड़ा निकल आए।</p>\n<p>“तुम इतनी सीरियस कब से हो गई?”</p>\n<p>“हमेशा से थी।”</p>\n<p>सुनैना ने कंधे उचकाए।</p>\n<p>“बस पहले जोक पूरा होने देती हूँ।”</p>\n<p>फिर सुनैना की नज़र नैना और विक्रम के बीच घूमी।</p>\n<p>“वैसे घर में किसी एक को तो बोरिंग मगर ज़रूरी चीज़ों पर सोचना पड़ेगा। तुम दोनों पिछले कुछ महीनों से एक-दूसरे को देखने में इतने बिज़ी हो कि शायद कोई डेमोग्राफिक ट्रेंड नोटिस भी न किया हो।”</p>\n<p>“सुनैना।”</p>\n<p>“क्या? ग़लत बोल रही हूँ?”</p>\n<p>“माँ-पापा को जाकर सुनाना अपना लेक्चर।”</p>\n<p>“उन्हें लगता है जियोपॉलिटिक्स वो चीज़ है जो दूसरे देशों के साथ होती है।”</p>\n<p>इस बार विक्रम हँसी रोक नहीं पाया।</p>\n<p>अगला करीब एक घंटा सुनैना के सवालों में निकल गया।</p>\n<p>सुनैना सवाल पूछती भी ऐसे थी जैसे सिर्फ बातचीत कर रही हो, जबकि असल में सामने वाले को लगातार परख रही होती।</p>\n<p>विक्रम ने किसी जवाब को सजाने की कोशिश नहीं की।</p>\n<p>जो पूछा गया, उसका सीधा जवाब दिया।</p>\n<p>कहीं बातचीत के बीच विक्रम ने सुनैना के चेहरे पर वही बदलाव देखा जो कभी-कभी नैना के चेहरे पर आता था—जैसे भीतर कोई फ़ैसला हो चुका हो और उसे दुनिया के सामने घोषित करने की ज़रूरत न हो।</p>\n<p>कुछ देर बाद विक्रम पानी लेने किचन में गया।</p>\n<p>उसके जाते ही सुनैना अपनी बहन की तरफ झुकी।</p>\n<p>“अच्छा।”</p>\n<p>नैना ने उसे देखा।</p>\n<p>“क्या?”</p>\n<p>“अब समझ आया।”</p>\n<p>“क्या समझ आया?”</p>\n<p>“इतना हल्ला क्यों था।”</p>\n<p>“शुरू मत हो जाना।”</p>\n<p>“कुछ शुरू नहीं कर रही।”</p>\n<p>सुनैना ने आवाज़ थोड़ी और धीमी कर ली।</p>\n<p>“कह रही हूँ—काग़ज़ पर जैसा इंसान तुम चाहतीं, वैसा तो है ही। सामने उससे भी बेहतर है।”</p>\n<p>नैना ने कुछ नहीं कहा।</p>\n<p>“तमीज़ है। दिखावा नहीं करता। हर बात में ख़ुद को साबित करने की कोशिश नहीं करता।”</p>\n<p>सुनैना ने किचन की तरफ एक नज़र डाली।</p>\n<p>“और कम-से-कम दिखता ऐसा है कि ज़रूरत पड़े तो किसी की हिफ़ाज़त कर सके, सिर्फ बातें न करे।”</p>\n<p>“तुमने एक घंटे में पूरा कैरेक्टर सर्टिफिकेट बना दिया?”</p>\n<p>“मैं पत्रकार हूँ। जल्दी फ़ैसला करना पड़ता है।”</p>\n<p>नैना की हँसी निकल गई।</p>\n<p>सुनैना का चेहरा फिर थोड़ा गंभीर हुआ।</p>\n<p>“इसे जाने मत देना, नैना।”</p>\n<p>नैना की मुस्कान हल्की पड़ गई।</p>\n<p>“सीरियसली कह रही हूँ।”</p>\n<p>सुनैना ने उसकी आँखों में देखा।</p>\n<p>“जो भी हो, इसे जाने मत देना।”</p>\n<p>नैना का जवाब सीधा था।</p>\n<p>“इरादा नहीं है।”</p>\n<p>“अच्छा है। वरना मुझे यूके से फोन करके ‘मैंने कहा था’ बोलना पड़ेगा—और इंटरनेशनल कॉल बहुत महँगी पड़ती है।”</p>\n<p>विक्रम पानी लेकर लौट आया और बात वहीं बदल गई।</p>\n<p>विक्रम को पता भी नहीं चला कि उन तीस सेकंड में उसके बारे में एक फ़ैसला हो चुका था।</p>\n<p>सुनैना के आने के बाद छुट्टी के बाकी दिन वैसे नहीं रहे जैसे दोनों ने सोचे थे।</p>\n<p>दो लोगों की शांत दुनिया अचानक तीन लोगों की हो गई।</p>\n<p>डिनर देर तक खिंचता, फिल्म के बीच सुनैना अपनी राय देती रहती, फिर खाने पर भी राय, फिर फिल्म पर दोबारा राय।</p>\n<p>विक्रम सोफे के कोने में बैठा दोनों को देखता रहता—दोनों के बीच की वह पुरानी सहजता, छोटी नोकझोंक, आधी बात पर पूरी बात समझ लेना—और हर नोकझोंक पर उसकी मुस्कान थोड़ी और खिंच जाती।</p>\n<p>शाम तक विक्रम को निकलना पड़ा।</p>\n<p>रात घर पर बितानी थी। घर वाले उसका इंतज़ार कर रहे थे और यह वह ज़िम्मेदारी थी जिसे वह सिर्फ इसलिए टाल नहीं सकता था क्योंकि उसका मन अभी इस फ्लैट से जाने का नहीं था।</p>\n<p>नैना उसे दरवाज़े तक छोड़ने आई।</p>\n<p>“जाओ।”</p>\n<p>“इतनी जल्दी निकाल रही हो?”</p>\n<p>“मेरी बहन को तुम्हारे लिए सवालों का दूसरा सेट तैयार करने का मौका मिलने से पहले।”</p>\n<p>सोफे से सुनैना की आवाज़ आई—</p>\n<p>“सुन रही हूँ।”</p>\n<p>नैना ने बिना पलटे जवाब दिया—</p>\n<p>“सुनाने के लिए ही बोला।”</p>\n<p>विक्रम के होंठों पर हँसी आ गई।</p>\n<p>दरवाज़े पर पहुँचकर उसने एक बार फिर नैना की तरफ देखा।</p>\n<p>“चार दिन वैसे ही कम थे। अब शाम का एक टुकड़ा रास्ते में जाएगा।”</p>\n<p>“और छुट्टियाँ आएँगी।”</p>\n<p>नैना ने यह बात ऐसे कही जैसे सिर्फ उम्मीद नहीं जता रही हो।</p>\n<p>“मैं तब तक ज़ोर-ज़ोर से यही मानती रहूँगी जब तक इसे मानना मेरी मजबूरी न रह जाए।”</p>\n<p>विक्रम ने उसे अपनी बाँहों में लिया।</p>\n<p>इस बार बहुत थोड़ी देर के लिए—अगले कमरे में बैठी सुनैना का ख़याल दोनों को था।</p>\n<p>फिर वह निकल गया।</p>\n<p>सीढ़ियाँ उतरते हुए भी ऊपर से दोनों बहनों की हँसी सुनाई देती रही।</p>\n<p>वह हँसी सीढ़ियों तक उतरती रही, जैसे दो जोड़ी पाँव बिना आवाज़ उसके पीछे-पीछे आ रहे हों।</p>\n<p>उसके भीतर एक शांत-सी गर्माहट थी। दो ऐसी लड़कियाँ, जो अपने-अपने तरीके से उसके लिए मायने रखती थीं, एक ही कमरे में इतनी आसानी से घुल-मिल गई थीं जितनी उसने उम्मीद नहीं की थी।</p>\n<p>कैब में बैठने के बाद फ्लैट की रोशन खिड़की धीरे-धीरे पीछे छूटने लगी। मोड़ पर मुड़ते ही वह अँधेरे में गुम हो गई, जैसे किसी ने परदा गिरा दिया हो।</p>"}, {"chapter": 22, "title": "अध्याय 20 — घर की एक शाम", "content": "<h1>अध्याय 20 — घर की एक शाम</h1>\n<p>बादशाहपुर पहुँचते-पहुँचते अँधेरा हो चुका था। बादशाहपुर गुरुग्राम से बस दस किलोमीटर था, पर शाम की भीड़ ने उसे आधे घंटे से ज़्यादा का बना दिया था। आख़िरी हिस्सा उसी जानी-पहचानी सड़क से होकर जाता था जिसके दोनों ओर खेत फैले थे। हेडलाइट की रोशनी में बीच-बीच में धूल उठती और फिर पीछे अँधेरे में खो जाती। खिड़की खुली थी, और रात की हवा में कटी फसल और गोबर की मिट्टी-सी गंध थी—वही गंध जो शहर के किसी कोने में नहीं मिलती। शहर की रोशनी पीछे छूटती जा रही थी।</p>\n<p>घर करीब एक एकड़ पुश्तैनी ज़मीन पर बना था। चारदीवारी के किनारे आम और जामुन के वे पेड़ अब काफी बड़े हो चुके थे जिन्हें विक्रम के दादा ने लगाया था। गेट के पास टीन की छत के नीचे महिंद्रा थार खड़ी थी और उसके बगल में छोटे भाई की रॉयल एनफील्ड बुलेट। थोड़ा पीछे पशुओं के बाड़े के पास फार्मट्रैक 60 ट्रैक्टर दिन भर के काम के बाद खड़ा था। नीम के बड़े पेड़ के नीचे बँधी भैंसों की कभी-कभार आती आवाज़ के अलावा रात लगभग शांत थी।</p>\n<p>विक्रम की कैब भीतर आकर रुकी तो उसके पिता अब भी बरामदे में बैठे थे। बाकी घर रात के लिए लगभग सिमट चुका था।</p>\n<p>विक्रम को उतरते देख पिता उठे।</p>\n<p>“आ गया?”</p>\n<p>सवाल कम, उसके पहुँच जाने की तसल्ली ज़्यादा थी।</p>\n<p>“जी हाँ।”</p>\n<p>“खाना खा लिया?”</p>\n<p>“जी हाँ, रास्ते में खा लिया।”</p>\n<p>पिता ने सिर हिलाया।</p>\n<p>“ठीक है। जा, सो जा। सुबह बात करते हैं।”</p>\n<p>विक्रम उनके पास गया, झुककर पैर छुए। पिता का हाथ एक पल उसके सिर पर ठहरा, फिर हट गया।</p>\n<p>उनके बीच अपनापन जताने का तरीका हमेशा से ऐसा ही था—कम शब्दों वाला, मगर अधूरा नहीं।</p>\n<p>तीन दिन से घर से उसकी मुलाक़ात बस आते-जाते की थी। सबके साथ ठीक से बैठना अगली सुबह हुआ।</p>\n<p>बड़ा भाई विक्रम से पहले उठ चुका था और आँगन के उस पार पशुओं को देख रहा था। विक्रम को देखकर बड़े भाई ने वहीं से सिर हिलाया।</p>\n<p>“रात को आया?”</p>\n<p>“हाँ, देर हो गई थी।”</p>\n<p>“चाय?”</p>\n<p>“हाँ।”</p>\n<p>कुछ देर बाद छोटा भाई बाँह के नीचे किताबों का ढेर दबाए निकला।</p>\n<p>“मॉर्निंग, भैया।”</p>\n<p>इतना कहकर वह लगभग तुरंत वापस अपने कमरे की तरफ मुड़ गया। जाते-जाते भी किसी चैप्टर की लाइनें बुदबुदा रहा था जिसे परीक्षा के लिए याद कर रहा था।</p>\n<p>विक्रम मुस्कराकर उसे देखता रहा।</p>\n<p>नाश्ते के वक्त वह हमेशा की तरह चूल्हे के पास छोटी चौकी पर बैठ गया। माँ आग के सामने बैठी एक के बाद एक बाजरे की रोटियाँ बना रही थीं—हथेलियों के बीच थपथपाकर उन्हें फैलातीं, गर्म तवे पर डालतीं और आख़िर में सीधे आँच पर फुलाकर विक्रम की थाली में रख देतीं।</p>\n<p>लकड़ी के धुएँ और सिकते बाजरे की महक पूरे कमरे में भरी थी।</p>\n<p>विक्रम की थाली में गर्म रोटियों पर ताज़ा मक्खन रखा गया, साथ में धनिया की चटनी, थोड़ा-सा गुड़ और स्टील का लंबा गिलास भरकर ठंडी छाछ।</p>\n<p>विक्रम ने अभी पहली रोटी भी पूरी नहीं की थी कि माँ ने दूसरी विक्रम की थाली में रख दी।</p>\n<p>“तीन दिन से सुबह निकल जाता है और रात को लौटता है। कितना दुबला हो गया है।”</p>\n<p>विक्रम ने माँ की तरफ देखा।</p>\n<p>“माँ, मैं बिल्कुल ठीक हूँ।”</p>\n<p>“ठीक कहाँ है? वहाँ आर्मी वाले ढंग से खिलाते भी हैं कि नहीं?”</p>\n<p>“बहुत खिलाते हैं।”</p>\n<p>“जो मिलता है वो खा लेना और ढंग से खाना—दोनों अलग बात हैं। चुपचाप खा।”</p>\n<p>विक्रम ने विरोध करना छोड़ दिया।</p>\n<p>इस बहस में जीतने की उसकी उम्र कभी आई ही नहीं थी।</p>\n<p>पास बैठा बड़ा भाई फसल का पूरा हिसाब सुना रहा था—इतनी तफ़सील से जितनी किसी ने उससे माँगी भी नहीं थी। बड़े भाई की पत्नी अपने दोनों छोटे बच्चों को सँभाल रही थी, जो मौका मिलते ही कमरे के कोने में रखे अपने चाचा के फौजी बैग की तरफ भाग जाते।</p>\n<p>छोटा भाई बीच-बीच में अपनी परीक्षा के लिए याद किया कोई तथ्य बातचीत में डाल देता, चाहे उसका उस समय चल रही बात से कोई लेना-देना हो या नहीं।</p>\n<p>विक्रम चुपचाप खाता रहा।</p>\n<p>कई महीनों बाद घर पर रहने पर यही बात उसे सबसे ज़्यादा छूती थी—उसकी ग़ैरमौजूदगी ने यहाँ किसी चीज़ को रुकने पर मजबूर नहीं किया था, फिर भी उसके लौटते ही उसके लिए जगह वैसे ही बन जाती थी जैसे वह कहीं गया ही न हो।</p>\n<p>शाम ढलने के बाद घर के लोग भीतर लौटने लगे तो विक्रम पैदल चौधरी के खेत की तरफ निकल गया।</p>\n<p>घर से ज़्यादा दूर नहीं था। जब भी छुट्टी में आता, एक चक्कर वहाँ ज़रूर लगता। इस बार तीन दिन निकल गए थे; आज जाकर मौका मिला।</p>\n<p>फतेह सिंह चौधरी पशुओं के बाड़े के पास ही था। विक्रम पर नज़र पड़ते ही चौधरी के चेहरे पर चौड़ी मुस्कान फैल गई।</p>\n<p>वर्षों की खेती ने चौधरी के शरीर को किसी जिम से ज़्यादा मज़बूती दी थी—चौड़े कंधे, भरी हुई बाँहें, धूप में पकी त्वचा और आँखों के किनारों पर समय से पहले आई महीन लकीरें। घनी, बेपरवाह मूँछों के नीचे वह चेहरा गंभीर रहने की कोशिश भी करे तो ज़्यादा देर निभा न पाता। कुर्ते की बाँहें कोहनियों से ऊपर चढ़ी थीं और पैरों पर अब भी खेत की धूल लगी थी।</p>\n<p>चौधरी के हाथ रस्सियों, ट्रैक्टर और खेत के काम से बहुत पहले ही खुरदरे हो चुके थे।</p>\n<p>चौधरी को देखकर हमेशा लगता था कि मिट्टी ने उसे सिर्फ पाला नहीं, अपने पास रोक भी लिया है—और उसे कभी इससे शिकायत नहीं रही।</p>\n<p>चौधरी बोला—</p>\n<p>“तीन दिन से कहाँ गायब था? सुना था आया हुआ है।”</p>\n<p>फिर उसने विक्रम को खींचकर गले लगाया।</p>\n<p>“बैठ। चाय बनवाता हूँ।”</p>\n<p>दोनों फार्महाउस के बाहर चारपाइयों पर बैठ गए। ऊपर आसमान धीरे-धीरे गहरा रहा था और खेतों से झींगुरों की आवाज़ आने लगी थी। बरामदे में लटका एक नंगा बल्ब उनके बीच की ज़मीन पर पीली रोशनी का छोटा-सा घेरा बना रहा था, जिसके चारों तरफ पतंगे चक्कर काट रहे थे।</p>\n<p>चौधरी ने चाय का गिलास उसकी तरफ बढ़ाया।</p>\n<p>“कितने दिन की छुट्टी है?”</p>\n<p>“चार की थी। अब गिनती के घंटे बचे हैं।”</p>\n<p>“इसे छुट्टी कहते हैं?”</p>\n<p>विक्रम हँस दिया।</p>\n<p>चौधरी विक्रम को गौर से देखता रहा।</p>\n<p>“एक बात कहूँ?”</p>\n<p>“कह।”</p>\n<p>“इस बार कुछ अलग लग रहा है तू।”</p>\n<p>विक्रम ने भौंह उठाई।</p>\n<p>“क्या अलग?”</p>\n<p>“पता नहीं।”</p>\n<p>चौधरी ने फिर उसे देखा, जैसे सही शब्द तलाश रहा हो।</p>\n<p>“हल्का-सा। पहले से हल्का।”</p>\n<p>विक्रम ने कंधे उचका दिए और चाय का घूँट भर लिया।</p>\n<p>विक्रम ने कुछ नहीं बताया।</p>\n<p>चौधरी ने भी दोबारा नहीं पूछा।</p>\n<p>पुरानी दोस्ती की अपनी एक समझ होती है—कब सवाल करना है, और कब सामने वाले के चेहरे पर आए बदलाव को देखकर भी उसे वहीं छोड़ देना है।</p>\n<p>फिर बातें अपने पुराने रास्तों पर निकल गईं।</p>\n<p>स्कूल के दिनों के किस्से, गाँव के पुराने नाम, कौन कहाँ पहुँच गया, किसने क्या कर लिया, किसकी शादी हो गई और कौन अब भी वैसा ही था जैसा सालों पहले हुआ करता था।</p>\n<p>बातों का कोई मकसद नहीं था।</p>\n<p>इसी वजह से वे इतनी देर चलती रहीं।</p>\n<p>जब विक्रम वहाँ से उठा तब रात काफी हो चुकी थी।</p>\n<p>वापसी में वह उसी कच्चे रास्ते से धीरे-धीरे घर की तरफ चला। ऊपर आसमान तारों से भरा था—इतने साफ़ तारे दिल्ली या गुरुग्राम में शायद ही कभी दिखाई देते थे। सिर के ऊपर आकाशगंगा की धुँधली पट्टी दिखी, ठीक वैसी जैसी बचपन में इसी रास्ते पर लगती थी।</p>\n<p>विक्रम रास्ते के बीच एक पल रुक गया और गहरी साँस ली—मिट्टी, कटी फसल और दूर कहीं जलते उपलों की महक एक साथ भीतर उतरी।</p>\n<p>उस मिट्टी पर फिर कुछ देर खड़े होने की, जहाँ से वह निकला था; उन लोगों के बीच बैठने की, जो उसे तब से जानते थे जब उसके नाम के आगे कोई रैंक नहीं था।</p>\n<p>आर्मी उसे कितनी भी दूर ले जाए, यहाँ की कुछ चीज़ें उसके लौटने का इंतज़ार उसी पुराने ढंग से करती थीं।</p>\n<p>जेब में फोन हल्का-सा काँपा। नैना का संदेश था: \"पहुँच गए? सुनैना तुम्हारा पूरा बायोडाटा माँग रही है।\"</p>\n<p>विक्रम मुस्कराया और जवाब में सिर्फ इतना लिखा: \"पहुँच गया।\"</p>\n<p>उस रात विक्रम को नहीं पता था कि उसके अतीत का एक नाम फिर उसकी ज़िंदगी की तरफ बढ़ रहा है।</p>\n<p>और उसकी शुरुआत एक फोन कॉल से होनी थी।</p>"}, {"chapter": 23, "title": "अध्याय 21 — अतीत की एक आवाज़", "content": "<h1>अध्याय 21 — अतीत की एक आवाज़</h1>\n<p>एक शाम कमल का फोन आया।</p>\n<p>स्कूल के दिनों का पुराना दोस्त, जो अब ख़ुद पुलिस में था।</p>\n<p>तब तक विक्रम की छुट्टी ख़त्म हुए काफी वक्त बीत चुका था और वह वापस नॉर्थ-ईस्ट में अपनी पोस्ट पर लौट आया था। शाम ढल रही थी। वह ऑफिसर्स मेस के बाहर सीढ़ियों पर बैठा था, फोन कान से लगाए सामने तारबंदी के पार फैली पहाड़ियों को देख रहा था। जंगलों के पीछे दिन की आख़िरी रोशनी धीरे-धीरे बुझ रही थी और हवा में उस इलाके की वही नम, हरियाली से भरी गंध थी जो मौसम बदलने पर भी जैसे पूरी तरह जाती नहीं थी।</p>\n<p>दोनों की ढंग से बात हुए एक साल से ज़्यादा हो चुका था, इसलिए शुरुआत वहीं से हुई जहाँ ऐसे पुराने दोस्तों की बातचीत अक्सर होती है—पुराने नाम, स्कूल के किस्से, भूले-बिसरे मज़ाक और उन लोगों की ख़बरें जिनसे दोनों का रिश्ता अब बस यादों भर का रह गया था।</p>\n<p>कुछ देर बाद कमल ने पूछा, “और बता, कोई लव स्टोरी चल रही है कि नहीं? कश्मीर में कोई लड़की-वड़की तो मिली होगी। सुना है उधर की लड़कियाँ बड़ी खूबसूरत होती हैं।”</p>\n<p>विक्रम हँसा।</p>\n<p>“ग़लत जगह पकड़ ली तूने। जम्मू-कश्मीर से निकले महीनों हो गए। अब नॉर्थ-ईस्ट में हूँ—जगह अलग, मुश्किलें अलग। म्यांमार सीमा पर एक ऑपरेशन भी हुआ था, इससे ज़्यादा नहीं बता सकता। बस इतना कि टीम सही-सलामत लौट आई।”</p>\n<p>फिर थोड़ी देर रुककर बोला, “और खूबसूरती वाली बात ग़लत नहीं है। जहाँ भी पोस्टिंग रही, खूबसूरत लोग देखे हैं। लेकिन वहाँ हम इश्क करने नहीं जाते, कमल। जिन लोगों के बीच तैनात होते हैं, उन्हें हमारी हिफ़ाज़त चाहिए, हमारी उस तरह की नज़र नहीं। हमारा काम है उनका ख़याल रखना, उन्हें महफ़ूज़ रखना। ड्यूटी वही है, रोमांस नहीं।”</p>\n<p>एक पल चुप रहकर उसने आगे कहा, “वैसे भी किसी को खूबसूरत समझना और किसी से सच में मोहब्बत करना दो अलग बातें हैं। असली मोहब्बत के लिए कोई ऐसा चाहिए जो तुम्हें ठीक से समझे—तुम्हारी परवरिश, तुम्हारा माहौल, तुम्हारी छोटी-छोटी बातें… जिसे हर बात का मतलब समझाने की ज़रूरत न पड़े। वो समझ, वो ख़याल… छोड़, तू नहीं समझेगा।”</p>\n<p>कमल हँस पड़ा।</p>\n<p>“अरे, इतनी गहरी मोहब्बत शायद न समझूँ, फिलॉसफर साहब, लेकिन उसका लाइव वर्जन ज़रूर समझता हूँ। अब ये बता—तेरे वाला वही गहरा मामला है या बाकी हम लोगों की तरह अभी भी हल्के-फुल्के में काम चला रहा है?”</p>\n<p>विक्रम की मुस्कान कुछ नरम पड़ गई।</p>\n<p>“गहरा वाला।”</p>\n<p>इतना कहते ही उसे ख़ुद महसूस हुआ कि बात पहली बार उसके और नैना के बीच से निकलकर किसी तीसरे इंसान के सामने आई है। जो अब तक सिर्फ उन दोनों का था, उसे आवाज़ मिलते ही जैसे उसका वज़न थोड़ा और बढ़ गया।</p>\n<p>“कोई है,” उसने कहा। “और सीरियस है।”</p>\n<p>“कितना सीरियस?”</p>\n<p>“हिमाचल गए थे साथ। बस हम दोनों। कुछ दिन।”</p>\n<p>उसने नाम नहीं बताया।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>कुछ बातें इंसान अपने बहुत पुराने दोस्त से भी पूरी नहीं खोलता।</p>\n<p>कमल ने धीमी-सी सीटी बजाई।</p>\n<p>“हिमाचल तक पहुँच गए? फिर तो मामला सच में सीरियस है। अच्छा है, यार। बहुत टाइम लगा दिया तूने।”</p>\n<p>विक्रम हँसा।</p>\n<p>“और तू? तेरी कोई कहानी?”</p>\n<p>“कोई है,” कमल ने कहा। “बस शादी थोड़ी जल्दी हो गई थी उसकी।”</p>\n<p>“अच्छा। कौन है?”</p>\n<p>“तू भी जानता होगा उसे। बादशाहपुर की ही है, पुलिस में है।”</p>\n<p>“कौन?”</p>\n<p>“कविता।”</p>\n<p>पहाड़ियों के पीछे आख़िरी रोशनी इस तरह बुझ गई, जैसे किसी ने नाम सुनकर दिया फूँक दिया हो।</p>\n<p>देर तक विक्रम कुछ नहीं बोला।</p>\n<p>सीढ़ी के किनारे पर रखा उसका खाली हाथ एक बार कस गया, फिर ढीला पड़ गया।</p>\n<p>बिना बुलाए एक पुराना आँगन याद में खुल गया। चाय की ट्रे। मंगलवार की वे शामें। दो साल का वह हिस्सा जिसे उसने महीनों से जानबूझकर छुआ तक नहीं था।</p>\n<p>जब बोला तो आवाज़ उम्मीद से ज़्यादा सधी हुई थी।</p>\n<p>“अच्छा है… मुझे खुशी है तेरे लिए, कमल। सच में।”</p>\n<p>और काफी हद तक वह सच ही कह रहा था। शब्द दिखावे के नहीं थे, उन्हें बाहर आने में सामान्य से थोड़ा ज़्यादा वक्त लगा था।</p>\n<p>कमल ने उसकी चुप्पी को हैरानी समझा और बात आगे बढ़ा दी। फिर क्रिकेट आया, किसी पुराने दोस्त की शादी आई और बातचीत धीरे-धीरे किसी दूसरी दिशा में निकल गई।</p>\n<p>विक्रम जवाब देता रहा, हँसता भी रहा, लेकिन उसका मन बीच-बीच में उस पुराने आँगन तक लौट जाता जहाँ वह बहुत समय से नहीं गया था।</p>\n<p>कुछ हफ्ते बाद कमल ने कविता से फोन पर उस ऑपरेशन का ज़िक्र किया, जिसकी ख़बर कुछ महीने पहले आधी-अधूरी, सूत्रों के हवाले से चली थी—म्यांमार सीमा के पास एक क्रॉस-बॉर्डर स्ट्राइक, जिसमें एक आतंकी कैंप तबाह किया गया था। आधिकारिक पुष्टि कभी नहीं आई।</p>\n<p>कमल ने सहजता से बताया कि विक्रम ने ख़ुद फोन पर उस ऑपरेशन का ज़िक्र किया था—बस दो वाक्यों में। उसी की टीम थी। उसका पुराना स्कूल का दोस्त। बादशाहपुर का ही।</p>\n<p>विक्रम।</p>\n<p>नाम सुनते ही कविता चुप हो गई।</p>\n<p>आज भी उस नाम का कविता के भीतर कहीं वही असर था—अब वह इतना सीख चुकी थी कि उसे अपनी आवाज़ तक न पहुँचने दे।</p>\n<p>इतने समय में कविता को कभी पता ही नहीं चला था कि कमल और विक्रम एक-दूसरे को जानते हैं। यह तो और भी नहीं कि दोनों एक ही स्कूल में पढ़े थे, बचपन साथ गुज़रा था और एक-दूसरे को उन पुराने नामों से बुलाते थे जो अक्सर सिर्फ स्कूल के दोस्त याद रखते हैं।</p>\n<p>कविता की ज़िंदगी के दो हिस्से, जिन्हें उसने हमेशा एक-दूसरे से बिल्कुल अलग समझा था, दरअसल इतने दूर कभी थे ही नहीं।</p>\n<p>“तुमने उसे कुछ बताया?” कविता ने आख़िर पूछा। “हमारे बारे में?”</p>\n<p>“बिल्कुल नहीं। ऐसी बातें कोई यूँ बैठकर थोड़े बताता है।”</p>\n<p>कमल को जैसे सवाल में कुछ खास लगा ही नहीं।</p>\n<p>“हाँ, उसने किसी और का ज़िक्र ज़रूर किया था। सीरियस है शायद। दोनों हिमाचल गए थे साथ।”</p>\n<p>कविता की उँगलियाँ फोन पर ठहर गईं।</p>\n<p>वह कभी विक्रम के साथ हिमाचल नहीं गई थी।</p>\n<p>जिस भी लड़की के साथ विक्रम गया था, विक्रम की ज़िंदगी में उसे वह जगह मिली थी जो कविता को कभी नहीं मिली—एक पूरा सफ़र, खुले दिन में, बिना किसी से छिपे, बिना चुराए हुए वक्त के।</p>\n<p>उसके बाद कविता ने ज़्यादा कुछ नहीं कहा।</p>\n<p>फोन ख़त्म होने तक कविता के भीतर कोई पुराना हिस्सा उस प्रेम के लिए एक बार फिर शोक मना चुका था, जो उस रूप में कभी उसका था ही नहीं।</p>\n<p>तीन रात बाद, दस बजने के बाद, कविता ने विक्रम को फोन किया।</p>\n<p>उस वक्त डिपार्टमेंट लगभग शांत हो चुका था। गलियारे में कहीं एक ट्यूबलाइट लगातार भिनभिना रही थी और सामने की डेस्क से किसी कांस्टेबल के रेडियो की धीमी खरखराहट आ रही थी।</p>\n<p>दूसरी घंटी पर विक्रम ने फोन उठा लिया।</p>\n<p>कविता का नाम स्क्रीन पर देखते ही विक्रम की पीठ अपने-आप सीधी हो गई थी।</p>\n<p>“कविता।”</p>\n<p>“ऑपरेशन के बारे में सुना,” कविता ने कहा। “कमल से। उसने बताया तुमने लीड किया था। देर से ही सही, बधाई हो, मेजर साहब।”</p>\n<p>“थैंक यू।”</p>\n<p>आवाज़ सामान्य थी, मगर विक्रम उसे इतना जानता था कि उसके नीचे की सावधानी पहचान सके। कविता जब किसी बात को भीतर रोकने की कोशिश करती थी, उसकी आवाज़ कुछ ज़्यादा ही संभली हुई हो जाती थी।</p>\n<p>“पूरा गाँव तुम्हारी बात कर रहा है। तुम्हारे पापा तो ऐसे घूम रहे होंगे जैसे पूरा जिला उन्हीं का हो।”</p>\n<p>विक्रम के मुँह से हल्की हँसी निकली।</p>\n<p>“जितना दिखाएँगे उससे ज़्यादा खुश होंगे।”</p>\n<p>फिर विक्रम ने पूछा, “डिपार्टमेंट कैसा चल रहा है?”</p>\n<p>कविता बोली, “जैसा हमेशा चलता है। फाइलें, काग़ज़ और सीनियर अफसर जिन्हें लगता है ज़ोर से बोलना भी कोई मैनेजमेंट टेक्नीक है।”</p>\n<p>कविता हँसी, मगर उसकी हँसी एक पल देर से आई और ज़रूरत से कुछ ज़्यादा हल्की थी।</p>\n<p>कविता फिर बोली, “रामफल की माँ ने भी आख़िर पूछना छोड़ दिया है कि वीकेंड पर मैं कहाँ गायब रहती हूँ। शायद अब हिसाब रखना छोड़ दिया है।”</p>\n<p>इसके बाद दोनों काफी देर तक ऐसी बातों पर बात करते रहे जिनका कोई खास मतलब नहीं था—किसी रिश्तेदार की सगाई, पुराने बस स्टैंड के पास बनती सड़क, गाँव की छोटी-मोटी ख़बरें।</p>\n<p>ऊपर से देखा जाए तो यह दो पुराने दोस्तों की बिल्कुल सहज बातचीत थी।</p>\n<p>मगर उसके नीचे दोनों एक ही काम कर रहे थे—उन दो नामों से बची जगह को साधारण बातों से भर रहे थे जिन्हें कोई भी अपनी तरफ से छूना नहीं चाहता था।</p>\n<p>विक्रम की हर चुप्पी में नैना थी।</p>\n<p>कविता की हर चुप्पी में कमल।</p>\n<p>आख़िर कविता ने कहा, “अब रखती हूँ। बस ठीक से बधाई देनी थी। ऐसी बात पर सिर्फ मैसेज भेजना अच्छा नहीं लगा।”</p>\n<p>“अच्छा लगा कि तुमने फोन किया।”</p>\n<p>विक्रम ने सच कहा था—उन साधारण शब्दों से कहीं ज़्यादा सच जितना सुनाई दिया।</p>\n<p>फिर विक्रम के मुँह से निकला—</p>\n<p>“कविता…”</p>\n<p>“मत,” कविता ने तुरंत कहा, मगर आवाज़ में सख़्ती नहीं थी। “जो भी कहने वाले हो, आज मत कहो। आज इसे बस इतना ही रहने देते हैं—बधाई… और एक पुराने दोस्त की आवाज़। इससे ज़्यादा मुश्किल कुछ नहीं।”</p>\n<p>विक्रम पल भर चुप रहा।</p>\n<p>वह समझ गया।</p>\n<p>और उसने बात वहीं छोड़ दी।</p>\n<p>कविता ने कहा—“अपना ख़याल रखना, विक्रम।”</p>\n<p>इस बार कविता की आवाज़ बहुत धीमी थी।</p>\n<p>“तुम भी, कविता।”</p>\n<p>फिर लाइन कट गई।</p>\n<p>विक्रम ने मोबाइल अपने बगल वाली सीढ़ी पर रख दिया और काफी देर उसे दोबारा हाथ नहीं लगाया। सामने अँधेरे में डूबी पहाड़ियों को देखते हुए वह उन दस साधारण मिनटों को याद करता रहा—बातें नहीं, बल्कि बातों के बीच की छोटी चीज़ें; कविता की हँसी का एक पल देर से आना, और उसका “बधाई हो, मेजर साहब” कहना, जैसे उसने वह वाक्य फोन मिलाने से पहले कई बार अपने भीतर दोहराया हो।</p>\n<p>बगल की सीढ़ी पर फोन की स्क्रीन बुझ चुकी थी, और नीचे कहीं झींगुरों की आवाज़ और तेज़ हो गई।</p>\n<p>विक्रम ने उससे आगे कुछ समझने की कोशिश नहीं की।</p>\n<p>कुछ दरवाज़े, जब कोई औरत ख़ुद बंद कर चुकी हो, तो सिर्फ अपने सवालों की तसल्ली के लिए उन्हें दोबारा खोलना उसका हक नहीं था।</p>\n<p>उधर कविता फोन कटने के बहुत देर बाद तक उसे गोद में रखे बैठी रही। बाहर वही ट्यूबलाइट अब भी भिनभिना रही थी।</p>\n<p>कुछ मिनटों के लिए कविता ने ख़ुद को रोकना छोड़ दिया।</p>\n<p>दो साल।</p>\n<p>एक फोन लाइन।</p>\n<p>एक आँगन।</p>\n<p>और एक इंसान जो कभी पूरी तरह उसका नहीं हुआ था—और अब कभी हो भी नहीं सकता था।</p>\n<p>कविता ने अपना दुपट्टा ठीक किया, मेज़ की लाइट बंद की और उठ खड़ी हुई।</p>\n<p>ट्यूबलाइट की भिनभिनाहट कमरे में अकेली रह गई।</p>\n<p>बाकी दुनिया के लिए उसे फिर वही कविता बनना था जिसे उसकी ज़िंदगी उससे हर रोज़ माँगती थी—</p>\n<p>संभली हुई।</p>\n<p>काबिल।</p>\n<p>और अपने भीतर की बात अपने भीतर रखने वाली।</p>"}, {"chapter": 24, "title": "अध्याय 22 — आने वाले कल की बात", "content": "<h1>अध्याय 22 — आने वाले कल की बात</h1>\n<p>कविता के फोन के कुछ हफ्ते बाद विक्रम को फिर छुट्टी मिल गई। ऑपरेशन के बाद की हलचल अब पूरी तरह थम चुकी थी, और आर्मी ने फिर कुछ दिनों की छुट्टी दे दी।</p>\n<p>उस रात ग्यारह बज चुके थे।</p>\n<p>नैना के फ्लैट में अँधेरा था—बस बालकनी का दरवाज़ा खुला था। विक्रम शाम से नैना के पास था; रात उसे बादशाहपुर में अपने घर बितानी थी, मगर वक्त जाने कब ग्यारह के पार निकल गया था। दोनों सोफे पर बैठे थे, मगर बातों के बीच की चुप्पी लंबी होती जा रही थी। ऊपर पंखा धीमी रफ्तार से लगभग बेआवाज़ घूम रहा था और बाहर मुख्य सड़क से आती ट्रैफिक की हल्की-सी आवाज़ ही बता रही थी कि शहर का कुछ हिस्सा अब भी जाग रहा है। कभी-कभार कोई गाड़ी गुज़रती, और छत पर उसकी रोशनी एक पल दौड़कर बुझ जाती।</p>\n<p>उसी अँधेरे में नैना ने अचानक पूछा—</p>\n<p>“तुम्हें कितने बच्चे चाहिए?”</p>\n<p>विक्रम ने तुरंत जवाब नहीं दिया।</p>\n<p>पंखा घूमता रहा। विक्रम की उँगलियाँ सोफे के कुशन पर कुछ गिनने लगीं—एक, दो।</p>\n<p>“मैंने कभी ख़ुद को इसके बारे में ठीक से सोचने ही नहीं दिया,” विक्रम ने आख़िर कहा।</p>\n<p>“क्यों?”</p>\n<p>“क्योंकि सोचने लगूँगा तो सब सच लगने लगेगा। और मैंने बहुत वक्त ऐसे गुज़ारा है कि किसी ऐसी चीज़ की चाह ही मत रखो जो कभी तुमसे छिन सकती हो।”</p>\n<p>अँधेरे में वह कुछ देर शब्द टटोलता रहा—जैसे कोई अनजान कमरे में अँधेरे में बत्ती का बटन टटोलता है।</p>\n<p>“लेकिन अगर तुम पूछ रही हो… तो दो। शायद तीन, अगर तुम्हें ज़्यादा चाहिए हुए।”</p>\n<p>“दो…” नैना ने जैसे उस संख्या को मन ही मन अपने भविष्य में रखकर देखा। “मैं हमेशा सोचती थी मुझे तीन चाहिए। बड़ा-सा घर हो, खूब शोर हो… लेकिन अब लगता है शायद मुझे तीन बच्चे नहीं चाहिए थे। शायद मैं बस ऐसा घर चाहती थी जिसमें वैसी ख़ामोशी न हो जैसी कभी-कभी मेरे बचपन के घर में हुआ करती थी।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“इतनी ख़ामोशी थी?”</p>\n<p>“बाबा अक्सर बाहर रहते थे। कभी पोस्टिंग, कभी ट्रेनिंग, कभी आर्मी को जहाँ उनकी ज़रूरत पड़ गई। घर माँ ने ही ज़्यादा संभाला।”</p>\n<p>नैना थोड़ा खिसककर उसके करीब आ गई। अँधेरे में उसका कंधा विक्रम के कंधे से लग गया।</p>\n<p>“बचपन में कई रात मैं जागती रहती थी। बाहर बजरी पर उनकी जीप के पहियों की आवाज़ सुनने के लिए। लगता था अभी आएगी… अभी गेट के बाहर रुकेगी। फिर कुछ रात वह आवाज़ आती ही नहीं थी और इंतज़ार करते-करते मेरी आँख लग जाती थी।”</p>\n<p>विक्रम ने छत की तरफ देखा। बाहर से किसी गाड़ी के पहियों की आवाज़ आई, और दोनों ने एक साथ साँस रोक ली—फिर आवाज़ आगे निकल गई।</p>\n<p>विक्रम की आवाज़ धीमी हो गई।</p>\n<p>“मैं तुम्हारे लिए ऐसी ज़िंदगी नहीं चाहता, नैना। मैं नहीं चाहता कि तुम रात भर किसी ऐसी जीप की आवाज़ सुनती रहो जो उस रात आने वाली ही नहीं है।”</p>\n<p>“मुझे पता है तुम नहीं चाहते।”</p>\n<p>“लेकिन किसी चीज़ को न चाहना और उसे रोक पाना एक बात नहीं होती, विक्रम।”</p>\n<p>“मैं महीनों से ख़ुद को समझा रही हूँ कि मैं ये ज़िंदगी संभाल सकती हूँ। तुम्हारी पोस्टिंग, तुम्हारा जाना, इंतज़ार… सब। लेकिन वो पंद्रह दिन याद हैं? जब तुम्हारी कोई ख़बर नहीं थी?”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“मैंने वो पंद्रह दिन निकाल तो लिए,” नैना बोली, “लेकिन किस हालत में निकाले, ये याद करना भी अच्छा नहीं लगता। कभी-कभी सोचती हूँ माँ ने बीस साल ये सब कैसे जिया होगा।”</p>\n<p>“तुम टूटी नहीं थीं।”</p>\n<p>“बहुत करीब पहुँच गई थी।”</p>\n<p>नैना की साँस अँधेरे में थोड़ी असमान हो गई।</p>\n<p>“और फिर मैं हमारे बच्चों के बारे में सोचती हूँ… अगर कभी हुए तो। क्या वे भी वैसे ही बड़े होंगे जैसे मैं हुई? सड़क पर किसी गाड़ी की आवाज़ सुनकर सोचेंगे कि बाबा आए हैं? उस हफ्ते कितना डरना है, ये अपनी माँ का चेहरा देखकर समझेंगे?”</p>\n<p>वह चुप रही।</p>\n<p>फिर बहुत धीमे बोली—</p>\n<p>“मुझे समझ नहीं आता कि ये सब जानते हुए भी तुम्हारे साथ वही ज़िंदगी चाहना मुझे ख़ुदग़र्ज़ बनाता है… या तुम्हें इतना चाहना कि फिर भी कोशिश करना चाहती हूँ।”</p>\n<p>विक्रम उसकी तरफ मुड़ गया।</p>\n<p>अँधेरे में उसने नैना का हाथ ढूँढ़ा और अपनी हथेली में ले लिया। विक्रम की आवाज़ में जो काँपना नहीं आया था, वह उसकी उँगलियों में बहुत हल्का-सा मौजूद था।</p>\n<p>“ये तुम्हें ख़ुदग़र्ज़ नहीं बनाता।”</p>\n<p>विक्रम ने उसका हाथ अपने सीने पर रख लिया, ठीक वहीं जहाँ नैना अक्सर अपना हाथ रखती थी।</p>\n<p>“बल्कि मुझे लगता है, यही बात तुम्हें वैसी माँ बनाएगी जैसी मैं अपने बच्चों के लिए चाहूँगा। जो किसी फ़ैसले की कीमत पहले देखती है, फिर उसे चुनती है। सिर्फ इसलिए आँखें बंद नहीं कर लेती कि कीमत है ही नहीं।”</p>\n<p>नैना चुप रही।</p>\n<p>“मैं तुमसे ये वादा नहीं कर सकता कि मेरी जीप हर बार वक्त पर घर के बाहर आकर रुकेगी। ऐसा वादा मैं अपनी माँ से भी नहीं कर सकता था, और तुमसे भी नहीं कर सकता।”</p>\n<p>विक्रम की उँगलियाँ नैना के हाथ पर और कस गईं।</p>\n<p>“लेकिन एक वादा कर सकता हूँ। हमारे जितने भी बच्चे होंगे, उन्हें कभी ये शक नहीं होगा कि उनके पिता को उनके पास घर लौटना कितना पसंद था। हर बार। चाहे लौटने में कभी ज़रूरत से ज़्यादा वक्त ही क्यों न लग जाए।”</p>\n<p>पंखा घूमता रहा, और बीच-बीच में नैना के दुपट्टे का सिरा उसकी साँस के साथ हिलता रहा।</p>\n<p>नैना ने तुरंत कुछ नहीं कहा।</p>\n<p>अँधेरे में नैना का दूसरा हाथ अपने चेहरे तक गया। उसने आँखों के पास की नमी चुपचाप पोंछ ली, इसलिए कि उसकी आवाज़ में वह बात न उतर आए जिसे वह अभी शब्द नहीं देना चाहती थी।</p>\n<p>थोड़ी देर बाद नैना की आवाज़ फिर संभली हुई थी, मगर पहले से कहीं नरम।</p>\n<p>“दो।”</p>\n<p>“हूँ?”</p>\n<p>“मैंने तय कर लिया। दो बच्चे।”</p>\n<p>विक्रम के होंठों पर हल्की मुस्कान आई।</p>\n<p>नैना ने कहा, “और घर में ख़ामोशी नहीं होगी। तुम बाहर भी हुए तो मैं इतना शोर करूँगी कि तुम्हारे हिस्से की कमी भी पूरी हो जाए, जब तक तुम वापस नहीं आ जाते।”</p>\n<p>“मुझे मंज़ूर है।”</p>\n<p>“होना भी चाहिए।”</p>\n<p>नैना पूरी तरह विक्रम के करीब सिमट आई और अपना सिर उसकी ठोड़ी के नीचे टिका दिया।</p>\n<p>उसके बाद काफी देर तक दोनों ने कुछ नहीं कहा।</p>\n<p>फिर नैना की साँसें धीरे-धीरे नींद की लय में उतरने लगीं, और विक्रम जागता रहा।</p>\n<p>अब उसका मन अनचाहे उस हिसाब की तरफ चला गया जिससे वह पूरी शाम बचता रहा था। पोस्टिंग अगर हमेशा की तरह चली तो अगला आदेश बहुत कम वक्त देकर आ सकता था, और उसके बाद अगली छुट्टी कब मिलेगी, इसका कोई भरोसा नहीं था।</p>\n<p>विक्रम ने नैना को नहीं जगाया।</p>\n<p>बताया भी नहीं।</p>\n<p>घड़ी में बारह बजने को थे। उसे बादशाहपुर लौटना था—घर पर माँ अब भी जागी होंगी। उसने कुशन खिसकाकर नैना का सिर सोफे पर टिकाया और शॉल उसके कंधों तक खींच दिया। उँगलियाँ छुड़ाते हुए नैना की उँगलियाँ नींद में बस पल भर कसीं, और विक्रम कुछ देर उन्हें अपनी हथेली में बंद रखे बैठा रहा—फिर धीरे से छुड़ा लीं।</p>\n<p>दरवाज़ा उसने बाहर से खींचकर बंद किया। ताला हल्की खट की आवाज़ के साथ अपनी जगह बैठ गया।</p>\n<p>सीढ़ियाँ उतरते हुए बाहर किसी गाड़ी के पहियों की आवाज़ आई, और विक्रम पल भर को ठिठक गया—फिर आगे बढ़ गया।</p>\n<p>उस रात उन्होंने पहली बार अपने बच्चों की बात की थी।</p>\n<p>भविष्य अभी आया नहीं था।</p>\n<p>मगर पहली बार दोनों ने उसे एक ही घर के भीतर खड़े होकर देखा था।</p>"}, {"chapter": 25, "title": "अध्याय 23 — मुझे वैसा ही रहने देना", "content": "<h1>अध्याय 23 — मुझे वैसा ही रहने देना</h1>\n<p>छुट्टी का वह रविवार, करने को कुछ खास नहीं था।</p>\n<p>नैना के फ्लैट के फर्श पर दोनों आमने-सामने बैठे नैना की पुरानी तस्वीरों का एक डिब्बा खंगाल रहे थे। यह नैना का ही ख़याल था। डिब्बे का ढक्कन खुलते ही हर बार पुराने काग़ज़ और हल्की-सी सीलन की मिली-जुली गंध बाहर आती। खिड़की के पास चंदन की अगरबत्ती लगभग बुझने को थी और दोपहर की ठहरी हुई रोशनी में उसके धुएँ की पतली लकीर ही कमरे की अकेली चीज़ थी जो लगातार हिल रही थी।</p>\n<p>एक तस्वीर हाथ में आते ही नैना अचानक चुप हो गई।</p>\n<p>काफी देर तक बस उसे देखती रही।</p>\n<p>“क्या हुआ?” विक्रम ने पूछा।</p>\n<p>नैना ने तस्वीर उसकी ओर बढ़ा दी।</p>\n<p>तस्वीर में वह शायद सोलह साल की थी। किसी धूल भरे मैदान में खड़ी, एक कंधे पर क्रिकेट का बल्ला टिकाए कैमरे की तरफ खुलकर हँस रही थी। बाल छोटे थे, चेहरे पर बेफिक्री थी और खड़े होने के अंदाज़ में भी कुछ ऐसा था जैसे दुनिया में अपनी जगह घेरने के लिए उसे किसी की इजाज़त की ज़रूरत कभी पड़ी ही न हो। धूल भरे मैदान की धूप तस्वीर के भीतर से अब भी चमक रही थी।</p>\n<p>नैना ने तस्वीर वापस ले ली और उसे देखती रही।</p>\n<p>“मैं बहुत लाउड हुआ करती थी।”</p>\n<p>विक्रम मुस्कराया। “सिर्फ हुआ करती थी?”</p>\n<p>नैना ने उसकी तरफ देखा, मगर मुस्कराई नहीं।</p>\n<p>“आवाज़ की बात नहीं कर रही। मैं… पूरी की पूरी ऐसी थी। जो चाहिए होता था, खुलकर कहती थी। टीचर्स से बहस करती थी। बाबा से कह दिया था कि मुझे पुलिस में जाना है, जबकि उस उम्र में मुझे ठीक से पता भी नहीं था कि पुलिस की नौकरी होती क्या है। मुझे ये बात अच्छी लगती थी कि एक लड़की वो काम करना चाहती है जिसकी उससे कोई उम्मीद नहीं करता।”</p>\n<p>नैना की उँगली तस्वीर के किनारे पर धीरे-धीरे फिरती रही, जैसे उस काग़ज़ के भीतर मौजूद लड़की तक पहुँचने का कोई रास्ता वहीं से निकलता हो।</p>\n<p>“पता नहीं कब थोड़ी शांत हो गई। शर्मीली नहीं हुई—वो मैं आज भी नहीं हूँ। बस… संभलकर रहने लगी। ये समझने लगी कि कहाँ मुझे कितनी जगह लेनी चाहिए और कितनी दूसरों के लिए छोड़ देनी चाहिए।”</p>\n<p>विक्रम ने कहा, “मेरे साथ तो तुम शांत नहीं रहती।”</p>\n<p>“वही तो,” नैना बोली।</p>\n<p>इस बार नैना ने सीधे विक्रम की आँखों में देखा।</p>\n<p>“तुम्हारे साथ मैं ख़ुद को रोकती नहीं हूँ। और कभी-कभी इसी बात से डर लगता है। क्योंकि मुझे नहीं पता शादी के बाद इसका क्या होगा। जब घर संभालना होगा, तुम्हारे परिवार की अपनी उम्मीदें होंगी, बच्चे होंगे जिन्हें एक माँ की ज़रूरत शायद उस लड़की से ज़्यादा होगी जो कभी सिर्फ अपनी इच्छा से पुलिस अफसर बनना चाहती थी।”</p>\n<p>“इन सब से तुम बदल क्यों जाओगी?” विक्रम ने पूछा।</p>\n<p>नैना की आवाज़ में हल्की धार आ गई।</p>\n<p>“क्योंकि मैंने अपने आसपास लगभग हर औरत को बदलते देखा है।”</p>\n<p>नैना की नज़र विक्रम से हटकर सामने दीवार पर टिक गई।</p>\n<p>“मेरी माँ भी पहले ऐसी नहीं थीं जैसी अब हैं। उनकी पुरानी तस्वीरें देखी हैं मैंने। बाबा के दोस्तों से राजनीति पर बहस करती थीं। हर चीज़ पर अपनी राय होती थी।”</p>\n<p>नैना ने तस्वीर पलटकर देखी, फिर दोबारा सीधी कर ली।</p>\n<p>“फिर पता नहीं कब वह ख़ुद होने के साथ-साथ पत्नी रहने के बजाय बस पत्नी होती चली गईं। मुझे नहीं लगता किसी ने एक दिन उनसे उनकी ज़िंदगी छीन ली। शायद वह ख़ुद ही अपने हिस्से की छोटी-छोटी चीज़ें एक-एक करके पीछे रखती गईं… और एक दिन इतना कुछ पीछे छूट चुका था कि जो औरत कभी हर बात पर अपनी राय रखती थी, उसकी जगह बहुत कम बची।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>नैना को यह कहने में जितना वक्त लगा था, उतना वक्त विक्रम ने उसे दिया।</p>\n<p>“मैं वैसी नहीं होना चाहती।”</p>\n<p>अब नैना की आवाज़ धीमी पड़ गई थी। तस्वीर उसके हाथों में कुछ ज़्यादा कस गई।</p>\n<p>“मैं नहीं चाहती कि पंद्रह साल बाद किसी दिन ये फोटो देखूँ और मुझे लगे कि इसमें खड़ी लड़की कभी मैं थी ही नहीं। मैं तब भी बेकार की बातों पर ज़रूरत से ज़्यादा बहस करना चाहती हूँ। मैं तब भी चाहती हूँ कि कहीं थोड़ी-सी ज़मीन हो जिसके काग़ज़ों पर मेरा अपना नाम लिखा हो।”</p>\n<p>वह रुकी।</p>\n<p>“और मुझे ये भी नहीं पता कि किसी इंसान से इसका वादा कैसे माँगा जाता है। क्योंकि शायद ये वादा करना उसके हाथ में भी नहीं होता।”</p>\n<p>विक्रम ने धीरे से तस्वीर उसके हाथ से ली और बगल में रख दी।</p>\n<p>फिर तस्वीर की जगह उसके दोनों हाथ अपने हाथों में ले लिए।</p>\n<p>“मैं ये वादा नहीं कर सकता कि दुनिया कभी तुमसे तुम्हारे हिस्से छीनने की कोशिश नहीं करेगी। मैंने अपनी माँ के साथ भी ऐसा होते देखा है।”</p>\n<p>विक्रम की आवाज़ में कोई बड़ी घोषणा नहीं थी।</p>\n<p>“लेकिन इतना वादा कर सकता हूँ कि छीनने वालों में मैं कभी नहीं रहूँगा।”</p>\n<p>नैना की आँखें उस पर टिक गईं।</p>\n<p>“तुम्हें ऊँची आवाज़ में बहस करनी है तो करो। मैं उसी कमरे में बैठकर सुनना चाहूँगा, तुम्हें चुप कराने के लिए नहीं। तुम्हें अपने नाम की ज़मीन चाहिए तो ज़मीन तुम्हारे नाम पर होगी, सिर्फ मेरे नाम पर नहीं।”</p>\n<p>विक्रम ने उसके हाथ हल्के से दबाए।</p>\n<p>“तुम्हें अपने बारे में जिस भी चीज़ के खो जाने का डर है, मैं नहीं चाहता कि तुम उसे मेरे लिए छोड़ो।”</p>\n<p>विक्रम ने एक पल बगल में रखी तस्वीर की ओर देखा।</p>\n<p>“मुझे इसी लड़की से मोहब्बत हुई है, नैना। बस अब ये बड़ी हो गई है।”</p>\n<p>नैना की आँखें उससे नहीं हटीं।</p>\n<p>“मुझे इसका छोटा किया हुआ रूप नहीं चाहिए। कभी नहीं।”</p>\n<p>थोड़ी देर वह चुप रही।</p>\n<p>नैना की उँगली फिर तस्वीर के किनारे तक गई और धीरे से उस पर फिरने लगी।</p>\n<p>“मैंने ये बात कभी किसी को नहीं बताई,” नैना ने आख़िर कहा। “सुनैना को भी नहीं। शायद आज से पहले मैंने भी इसे इतने साफ़ शब्दों में कभी नहीं सोचा था।”</p>\n<p>“अच्छा किया मुझे बता दिया,” विक्रम ने कहा।</p>\n<p>“हाँ।”</p>\n<p>नैना ने तस्वीर फिर उठाई।</p>\n<p>सोलह साल की उस लड़की को देर तक देखा और इस बार उसे बाकी तस्वीरों के बीच दबाकर रखने के बजाय सबसे ऊपर रख दिया—जैसे इतने साल बाद उसे उसकी अपनी जगह वापस दे रही हो।</p>\n<p>फिर नैना ने विक्रम की ओर देखा।</p>\n<p>“मुझे लाउड ही रखना, विक्रम।”</p>\n<p>विक्रम चुपचाप उसे देखता रहा।</p>\n<p>“हमारे साथ जो भी हो… ज़िंदगी हम दोनों को जहाँ भी ले जाए, मुझसे वादा करो कि मुझे लाउड ही रहने दोगे।”</p>\n<p>“वादा।”</p>\n<p>विक्रम ने कहा, और उस वक्त जितनी सच्चाई से कोई कह सकता था, उतनी ही सच्चाई से कहा।</p>\n<p>शांत दोपहर में ऐसा वादा करना आसान था। चंदन की अगरबत्ती लगभग बुझ चुकी थी और अभी ज़िंदगी ने उन दोनों से उस वादे को साबित करने के लिए कुछ माँगा भी नहीं था।</p>\n<p>विक्रम यह बात जानता था।</p>\n<p>फिर भी उसने वादा किया।</p>\n<p>अगरबत्ती की राख की आख़िरी लकीर हिली और बिखर गई।</p>\n<p>विक्रम के मन में एक ख़याल ज़रूर आया—</p>\n<p>जब इस वादे की परीक्षा होगी, ज़िंदगी पहले किसे आजमाएगी?</p>"}, {"chapter": 26, "title": "अध्याय 24 — बात महाकाल की नहीं थी", "content": "<h1>अध्याय 24 — बात महाकाल की नहीं थी</h1>\n<p>बात इतनी छोटी-सी थी कि झगड़े के बीच दोनों में से कोई ठीक-ठीक नहीं बता सकता था कि वह इतनी बड़ी कैसे हो गई। कभी-कभी एक छोटी-सी चिंगारी को बस सही सूखा मौसम मिल जाता है, और फिर आग उस बात से कहीं आगे निकल जाती है जहाँ से वह शुरू हुई थी।</p>\n<p>नैना ने विक्रम की अगली छुट्टी के लिए उज्जैन जाने का प्लान बना लिया था—महाकाल के दर्शन के लिए। पूरा वीकेंड तय कर दिया था, जबकि विक्रम ने अभी यह भी पक्का नहीं किया था कि उसे कितनी छुट्टी मिलेगी। यह इस छुट्टी की नहीं, अगली बार की योजना थी।</p>\n<p>गुरुवार की शाम थी। नैना ने खाने के लिए सब्ज़ी चढ़ा रखी थी, जो बातचीत बढ़ते-बढ़ते लगभग भुला दी गई। गैस पर धीमी आँच में पकती सब्ज़ी की खुशबू अब धीरे-धीरे जलने की गंध में बदल रही थी। बंद खिड़की के उस पार सोहना रोड का ट्रैफिक हमेशा की तरह शोर कर रहा था—शहर को उनके झगड़े से कोई लेना-देना नहीं था।</p>\n<p>“तुम्हें मुझसे पूछ लेना चाहिए था,” विक्रम ने कहा।</p>\n<p>विक्रम की आवाज़ में जितनी सख़्ती वह चाहता था, उससे कुछ ज़्यादा आ गई।</p>\n<p>“मुझे नहीं लगा मंदिर जाने का प्लान बनाने के लिए तुम्हारी परमिशन चाहिए।”</p>\n<p>“मैंने ये नहीं कहा, और तुम जानती हो। मैं सिर्फ कह रहा हूँ कि हम दोनों का पूरा वीकेंड तय करने से पहले एक बार पूछ तो सकती थीं कि मैं उस वक्त फ्री भी हूँ या नहीं। अगर छुट्टी नहीं मिली तो? अगर ड्यूटी ने रोक लिया तो?”</p>\n<p>“तो तुम कह दोगे आर्मी को तुम्हारी ज़रूरत है—जैसे हमेशा होती है। और मैं अकेली चली जाऊँगी, जैसे बहुत-सी जगह तुम्हारे बिना जाती रही हूँ।”</p>\n<p>नैना की आवाज़ में अब वह पुरानी धार उतर आई थी जिसे कभी विक्रम पसंद करता था, मगर इस वक्त वही धार चुभ रही थी।</p>\n<p>“अपनी ज़िंदगी तुम्हारी छुट्टियों और पोस्टिंग के हिसाब से चलाने की आदत हो गई है मुझे, विक्रम। बस ये नहीं पता था कि अपना कोई प्लान बनाने से पहले भी तुम्हारी इजाज़त लेनी पड़ेगी।”</p>\n<p>“ये बात ठीक नहीं है,” विक्रम ने कहा। वह रसोई के दरवाज़े पर बाँहें बाँधे खड़ा था।</p>\n<p>“और महाकाल ही क्यों? तुमने पहले कभी नहीं कहा कि तुम्हें वहाँ जाना है।”</p>\n<p>नैना का चेहरा ज़रा-सा बदल गया।</p>\n<p>नैना ने हाथ में पकड़ा चम्मच नीचे रख दिया। गैस पर कड़ाही से धुआँ उठने लगा था। किसी ने उधर नहीं देखा।</p>\n<p>“क्योंकि मुझे डर लग रहा है, विक्रम।”</p>\n<p>विक्रम की बाँहें अपने-आप ढीली हो गईं।</p>\n<p>“मुझे डर है कि अगर बाबा हमारे ख़िलाफ़ हो गए तो क्या होगा। मैंने अपनी कितनी सहेलियों के रिश्ते सिर्फ इसलिए टूटते देखे हैं कि घरवाले लव मैरिज के लिए तैयार नहीं हुए।”</p>\n<p>वह रुकी।</p>\n<p>“मैं महाकाल के सामने जाकर कुछ माँगना चाहती थी। ऐसी चीज़ जिसे शायद अभी खुलकर माँगने का हक भी पूरी तरह नहीं है मुझे—कि आगे जो भी आए, हम दोनों उसमें साथ रहें।”</p>\n<p>अब नैना की आवाज़ में गुस्सा कम था।</p>\n<p>“मैं तुम्हें ये सब तब तक नहीं बताना चाहती थी जब तक ख़ुद नहीं समझ लेती कि मेरे भीतर चल क्या रहा है। इसलिए मैंने बस प्लान बना दिया। ग़लत तरीके से बनाया, ज़ाहिर है… क्योंकि जिसके लिए ये सब था, उसी से पूछना भूल गई।”</p>\n<p>“तुमने मुझे बताया नहीं कि तुम्हें अपने पापा को लेकर इतना डर लग रहा है।”</p>\n<p>“क्योंकि उसे बोल देती तो वह और सच लगने लगता।”</p>\n<p>नैना ने नज़र फेर ली। बाँहें अब भी सीने पर बँधी थीं, मगर उनमें पहले वाली अकड़ नहीं रही थी।</p>\n<p>“जिन चीज़ों में तुम्हारी जान ख़तरे में पड़ती है, उनमें मेरी कोई राय नहीं चलती। मैं जानती हूँ। मुझे लगा कम-से-कम इतना तो कर सकती हूँ कि हम दोनों के लिए किसी मंदिर में जाकर कुछ माँग लूँ। और अब हम यहाँ खड़े एक वीकेंड को लेकर लड़ रहे हैं।”</p>\n<p>“ऑपरेशन में तुम्हारी राय कैसे शामिल करूँ, नैना? आर्मी मुझे उस तरह की गुंजाइश देती ही नहीं।”</p>\n<p>“मैं तुमसे आर्मी के साथ बैठकर अपनी ड्यूटी तय करने को नहीं कह रही।”</p>\n<p>नैना ने तुरंत विक्रम की तरफ देखा।</p>\n<p>“मैं सिर्फ ये चाहती हूँ कि तुम मुझे उस इंसान की तरह देखो जिसके डर भी उतने ही मायने रखते हैं जितने तुम्हारे। फ़ैसले में राय देना एक बात है, और डर का सुना जाना दूसरी—मुझे नहीं लगता तुमने अभी तक इस फ़र्क़ को पूरी तरह समझा है।”</p>\n<p>“तो मुझे साफ़-साफ़ बताया करो कि तुम्हें मुझसे चाहिए क्या। मुझसे अंदाज़ा लगाने की उम्मीद मत रखो।”</p>\n<p>नैना ने बिना देर किए कहा—</p>\n<p>“बताना ही तो सबसे मुश्किल है।”</p>\n<p>बस इतना।</p>\n<p>मगर उन शब्दों का वज़न किसी लंबी शिकायत से ज़्यादा था।</p>\n<p>विक्रम चुप हो गया।</p>\n<p>“मैं तुमसे लड़ने की कोशिश नहीं कर रही,” नैना ने थोड़ी देर बाद कहा। आवाज़ अब धीमी थी, जैसे गुस्सा जलकर थकान में बदल चुका हो। “मैं कई हफ्तों से अपने भीतर एक बात दबाकर बैठी थी। आज ग़लत तरीके से बाहर आ गई। और अब हम मंदिर जाने पर चिल्ला रहे हैं, जबकि बात कभी मंदिर की थी ही नहीं।”</p>\n<p>कुछ पल दोनों वहीं खड़े रहे।</p>\n<p>साँसें ज़रूरत से कुछ तेज़ थीं और वह छोटा-सा फ्लैट अचानक इतना छोटा लगने लगा था जैसे अभी-अभी कही गई सारी बातें उसकी दीवारों में समा नहीं पा रही हों।</p>\n<p>“मैं थोड़ी देर बाहर जा रही हूँ।”</p>\n<p>नैना ने जवाब का इंतज़ार नहीं किया।</p>\n<p>दरवाज़ा नैना के पीछे कुछ ज़्यादा ज़ोर से बंद हुआ—इतना नहीं कि उसे पटकना कहा जाए, मगर इतना ज़रूर कि विक्रम देर तक उस आवाज़ को सुनता रहा।</p>\n<p>कमरे में अकेला रह जाने के बाद विक्रम ने गैस बंद की। कड़ाही की तली में सब्ज़ी काली पड़ चुकी थी।</p>\n<p>उसने पूरे झगड़े को दोबारा अपने भीतर चलने दिया। उसे मानना पड़ा कि नैना पूरी तरह ग़लत नहीं थी।</p>\n<p>विक्रम नैना से मोहब्बत करने का एक तरीका सीख चुका था—उसकी हिफ़ाज़त करना, उसका ख़याल रखना, फ़ैसले लेना और फिर उन्हें जितना हो सके नरमी से उसके सामने रख देना। अपने मन में वह इसे परवाह समझता रहा था।</p>\n<p>मगर नैना की तरफ से कई बार वही परवाह उसकी ज़िंदगी को उसके लिए तय कर देने जैसी लगी थी।</p>\n<p>और इन सबके नीचे वह अपने पिता को लेकर एक डर अकेली उठाए घूम रही थी, इतना चुपचाप कि विक्रम ने उसके वज़न को पहचाना तक नहीं।</p>\n<p>उधर नैना बिना किसी मंज़िल के अपनी बिल्डिंग के आसपास की सड़क पर चलती रही। शाम की हल्की ठंड से बचने के लिए नैना ने बाँहें अपने चारों ओर समेट रखी थीं और वही झगड़ा अपने हिस्से से दोबारा देख रही थी।</p>\n<p>सोहना रोड की पीली बत्तियों के नीचे उसकी परछाईं कभी लंबी होती, कभी सिमट जाती।</p>\n<p>नैना ने अपनी दुआ एक ट्रैवल प्लान के भीतर रख दी थी और उम्मीद की थी कि विक्रम बिना बताए समझ जाएगा कि उस प्लान के भीतर क्या माँगा जा रहा है।</p>\n<p>करीब एक घंटे बाद नैना लौटी।</p>\n<p>गुस्सा रास्ते में कहीं छूट चुका था। शाम की ठंडी हवा ने वह काम कर दिया था जो थोड़ी देर पहले वे दोनों नहीं कर पाए थे।</p>\n<p>दरवाज़े पर खड़ी होकर नैना ने कहा, “सॉरी। मैंने आवाज़ ऊँची कर दी। और तुमसे पूछे बिना प्लान बना दिया।”</p>\n<p>“आवाज़ के लिए सॉरी मत बोलो।”</p>\n<p>विक्रम उठकर उसके पास आया।</p>\n<p>“ज़्यादातर बातों में तुम सही थीं। मैं कई बार फ़ैसले ख़ुद कर लेता हूँ और फिर तुम्हें बताता हूँ, जबकि मुझे उन्हें तुम्हारे साथ मिलकर तय करना चाहिए। आज तक मुझे ये फ़र्क़ ठीक से दिखाई नहीं दिया था।”</p>\n<p>नैना चुपचाप सुनती रही।</p>\n<p>“और मुझे ये भी नहीं पता था कि तुम अपने पापा को लेकर इतने वक्त से ये डर अकेली लिए घूम रही हो। दोनों बातों के लिए सॉरी।”</p>\n<p>नैना के कंधों में जो तनाव अब तक बचा हुआ था, वह थोड़ा ढीला पड़ा।</p>\n<p>“मैं दोबारा ऐसे नहीं लड़ना चाहती। इतनी छोटी-सी बात इतनी जल्दी इतनी बड़ी हो गई… थोड़ा डर लगा मुझे।”</p>\n<p>“मुझे भी।”</p>\n<p>विक्रम ने उसका हाथ थामा और इस बार नैना ने उसे पीछे नहीं खींचा।</p>\n<p>“मैं नहीं चाहता कि तुम्हें अपनी ही ज़िंदगी के बारे में फ़ैसले सुनने का इंतज़ार करना पड़े। मैं तुम्हारे साथ ज़िंदगी बनाना चाहता हूँ, नैना—पहले अकेले सब तय करके बाद में तुम्हें ख़बर नहीं देना चाहता।”</p>\n<p>विक्रम ने नैना की उँगलियाँ अपने हाथ में और कस लीं।</p>\n<p>“और हमारे बारे में जो डर हैं, उन्हें भी अकेले मत उठाया करो। तुम्हारे पापा हों या आगे कुछ और—जो भी आएगा, हम दोनों का होगा। मैं नहीं चाहता कि तुम हमारे हिस्से की दुआ भी किसी मंदिर में अकेली माँगने जाओ।”</p>\n<p>नैना के चेहरे की बची हुई सख़्ती आख़िर पिघल गई।</p>\n<p>“बस यही सुनना चाहती थी।”</p>\n<p>नैना उसके करीब आई और माथा विक्रम के सीने पर टिका दिया।</p>\n<p>फिर वहीं खड़े-खड़े बोली, “मैं अभी भी उज्जैन जाना चाहती हूँ। बस इस बार चाहती हूँ कि तुम भी मेरे साथ चलो—अगर आर्मी जाने दे। और इसलिए नहीं कि मैंने तारीख़ें तय कर दी हैं। इसलिए कि तुम ख़ुद वहाँ होना चाहते हो।”</p>\n<p>“मैं वहाँ होना चाहता हूँ।”</p>\n<p>नैना ने सिर उठाकर उसकी तरफ देखा।</p>\n<p>विक्रम ने कहा—</p>\n<p>“उसके लिए भी… और उसके बाद जो कुछ आएगा, उसके लिए भी।”</p>\n<p>उस शाम दोनों ने नैना के पिता का नाम फिर नहीं लिया।</p>\n<p>मगर वह बात कमरे से गई भी नहीं।</p>\n<p>वह वहीं कहीं उनके बीच ठहरी रही—बिना जल्दबाज़ी किए, अपने वक्त का इंतज़ार करती हुई।</p>\n<p>क्योंकि कुछ बातें आने से पहले कोई शोर नहीं करतीं।</p>\n<p>बस धीरे-धीरे करीब आती रहती हैं।</p>"}, {"chapter": 27, "title": "अध्याय 25 — महाकाल", "content": "<h1>अध्याय 25 — महाकाल</h1>\n<p>अगली छुट्टी आई तो विक्रम बादशाहपुर से बैग लेकर दोपहर में ही नैना के फ्लैट पहुँच गया। शाम को वहीं से उन्होंने नई दिल्ली रेलवे स्टेशन के लिए कैब ली और ट्रेन आने से काफी पहले पहुँच गए। रात की ट्रेन थी, अगले दिन उज्जैन पहुँचाने वाली—करीब पंद्रह घंटे का सफ़र।</p>\n<p>रिज़र्वेशन एसी थ्री-टियर के बी-3 कोच में था, सीट नंबर 41 और 44, दोनों लोअर बर्थ। नैना ने बुकिंग के वक्त इस बात का खास ख़याल रखा था।</p>\n<p>बैग सीट के नीचे रखते हुए नैना ने कहा, “चलती ट्रेन में आधी रात को सीढ़ी चढ़ने का मेरा कोई इरादा नहीं है। लोअर बर्थ मिलेगी, वरना कुछ नहीं।”</p>\n<p>धीरे-धीरे डिब्बा भरने लगा। दो हिस्से छोड़कर एक परिवार अपने दो छोटे बच्चों के साथ बैठा था; सामने कुछ दूरी पर एक बुज़ुर्ग दंपती ने ट्रेन चलने से पहले ही टिफिन खोल लिया था। ऊपर की जगह में बैग ठूँसने की आवाज़ें, सीटें ढूँढ़ते लोग और बीच-बीच में निकलता चायवाला—रेल का वही जाना-पहचाना संसार उनके चारों ओर बसने लगा।</p>\n<p>दिल्ली पूरी तरह पीछे भी नहीं छूटी थी कि विक्रम ने चायवाले से दो कप ले लिए। प्यास से ज़्यादा आदत में।</p>\n<p>शाम से नैना कुछ शांत थी, मगर वह पिछली लड़ाई के बाद वाली संभली हुई चुप्पी नहीं थी। वह खिड़की से बाहर सरकते अँधेरे को देखती रही और उसका हाथ दोनों के बीच बर्थ पर विक्रम के हाथ में ढीला-सा पड़ा रहा। काँच में दोनों के चेहरे धुँधले पड़ते और बाहर की रोशनियाँ उनके बीच से गुज़र जातीं।</p>\n<p>आधी रात के बाद, जब दोनों अब भी जाग रहे थे, नैना ने कहा, “मैंने शायद कभी ऐसे मंदिर का सफ़र नहीं किया।”</p>\n<p>“कैसे?” विक्रम ने पूछा।</p>\n<p>“सिर्फ कुछ माँगने के लिए। मंदिर जाती रही हूँ, लेकिन ज़्यादातर आदत में… या माँ को साथ चाहिए होता था इसलिए। ऐसा पहली बार है कि मैं किसी एक बात को लेकर जा रही हूँ।”</p>\n<p>“क्या माँगोगी?” विक्रम ने पूछा।</p>\n<p>नैना चुप रही।</p>\n<p>“पता नहीं माँगने से पहले उसे बोलना चाहिए या नहीं। बेवकूफ़ी है शायद, लेकिन लगता है पहले ही कह दिया तो जिस किस्मत के भरोसे उसे वहाँ तक पहुँचना है, उसका थोड़ा असर यहीं खर्च हो जाएगा।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>“तो मत बताओ। मैं भी कुछ माँग लूँगा। बाद में हिसाब मिलाना ज़रूरी नहीं है।”</p>\n<p>नैना के चेहरे पर हल्की-सी मुस्कान आई।</p>\n<p>“तुम क्या माँगोगे?”</p>\n<p>“शायद वही जो तुम नहीं बता रही।”</p>\n<p>विक्रम ने नैना का हाथ हल्के से दबाया।</p>\n<p>“मुझे नहीं लगता हम दोनों को उसे बोलने की ज़रूरत है। दोनों जानते हैं।”</p>\n<p>मथुरा के आगे कहीं ट्रेन अपनी स्थिर लय पकड़ चुकी थी। बर्थ लगने के बाद दोनों ने पतले कंबल खोल लिए। बाहर छोटे कस्बों की रोशनियाँ अब पहले से ज़्यादा दूरी पर दिखाई देतीं और अँधेरे में पीछे छूट जातीं।</p>\n<p>भोपाल पहुँचते-पहुँचते दोनों फिर पूरी तरह जाग चुके थे।</p>\n<p>सुबह का वक्त होने के बावजूद प्लेटफॉर्म में नींद का कोई निशान नहीं था। ऊपर रेलवे की वही कटी-छँटी अंग्रेज़ी में अनाउंसमेंट बार-बार दोहराई जा रही थी और बाकी आवाज़ों को चीरती हुई कहीं से पुकार उठ रही थी—</p>\n<p>“चाय… गरम चाय…”</p>\n<p>दोनों थोड़ी देर पैर सीधे करने के लिए नीचे उतर आए और दो कुल्हड़ ले लिए। चाय इतनी गर्म थी कि तुरंत पीना मुश्किल और इतनी मीठी कि स्टेशन की चाय होने में कोई शक नहीं रह जाता था।</p>\n<p>खुले दरवाज़े के पास खड़े होकर वे उसे पीते रहे। आसपास कुलियों और यात्रियों की आवाज़ें थीं, अनाउंसमेंट था, दूर किसी दूसरी ट्रेन के ब्रेक की लंबी-सी फुफकार थी।</p>\n<p>कुल्हड़ दोनों हथेलियों में थामे नैना ने कहा, “ऐसी सुबहों की आदत पड़ सकती है मुझे—शोर, कोई प्लान नहीं और ज़रूरत से ज़्यादा मीठी चाय।”</p>\n<p>“हमारी आम सुबहों से तो बेहतर है।”</p>\n<p>“बहुत बेहतर।”</p>\n<p>थोड़ी देर में ट्रेन फिर चल पड़ी। भोपाल के आगे किसी स्टेशन से नाश्ता लिया और बाकी सफ़र आसानी से कट गया। खिड़की के बाहर मध्य प्रदेश का भूगोल अपना रंग और उतार-चढ़ाव बदलता रहा।</p>\n<p>उज्जैन जंक्शन पर उतरते-उतरते दोपहर करीब आ चुकी थी। ट्रेन तय समय से कुछ देर पीछे थी, मगर इतनी नहीं कि दोनों को फ़र्क़ पड़ता। शहर जाग चुका था और प्लेटफॉर्म तक कहीं दूर बजती मंदिर की घंटियाँ सुनाई दे रही थीं।</p>\n<p>महाकाल मंदिर स्टेशन से मुश्किल से दो किलोमीटर था। आगे का रास्ता उन्होंने ऑटो से तय किया।</p>\n<p>पुराने शहर की ओर बढ़ते हुए क्षिप्रा एक झलक के लिए दिखाई दी—चौड़ी, शांत गति से बहती हुई; घाटों पर स्नान करते लोगों और रोज़मर्रा की हलचल के बीच जैसे सदियों से शहर की अपनी रफ्तार से बेपरवाह।</p>\n<p>उज्जैन की चाल में भी कुछ ऐसा था मानो यहाँ दिन घड़ी देखकर नहीं, मंदिर की घंटियों के साथ आगे बढ़ता हो।</p>\n<p>मंदिर सामने आया तो उसका प्रभाव उसकी ऊँचाई से ज़्यादा उसकी मौजूदगी में था। हल्के आसमान के सामने नक्काशीदार पत्थरों की परतों में ऊपर उठता शिखर—भूमिज, मराठा और चालुक्य स्थापत्य की अलग-अलग छापें, जिन्हें सदियों के निर्माण और पुनर्निर्माण ने एक-दूसरे पर रखा था। कुछ भी पूरी तरह एक जैसा नहीं था, फिर भी सब मिलकर ऐसा लगता था जैसे वह इमारत अपने किसी एक हिस्से से कहीं ज़्यादा पुरानी हो।</p>\n<p>बाहरी द्वार से ही श्रद्धालुओं की कतार शुरू हो चुकी थी। हवा में धूप-अगरबत्ती की गंध और मंत्रों का धीमा स्वर घुला था। वे आँगनों से होते हुए आगे बढ़ते रहे; बाहर बढ़ती गर्मी के बावजूद पैरों के नीचे पत्थर अब भी ठंडा था।</p>\n<p>गर्भगृह जितना करीब आता गया, नैना उतनी ही शांत होती गई। नैना की उँगलियाँ विक्रम के हाथ पर कसती चली गईं।</p>\n<p>आख़िरी सीढ़ियाँ उतरकर जब वे धरातल से नीचे बने गर्भगृह में पहुँचे, तो जैसे बाहर का शहर वहीं ऊपर छूट गया।</p>\n<p>हवा तक अलग महसूस होती थी—धुएँ से भारी, भस्म की मिट्टी-सी गंध और वर्षों से जलते घी के दीपकों की महक अपने भीतर समेटे हुए।</p>\n<p>सामने दक्षिणमुखी ज्योतिर्लिंग था—बारह ज्योतिर्लिंगों में महाकाल की वह विशिष्टता जिसे कतार आगे बढ़ाते हुए पुजारी ने लगभग सहज ढंग से कहा, मगर जाने क्यों वह छोटी-सी बात विक्रम के भीतर अपेक्षा से कहीं गहरी उतर गई।</p>\n<p>प्राचीन काला पत्थर उस सुबह की चढ़ी भस्म, फूलों और दूसरी पूजन सामग्री के नीचे मुश्किल से दिखाई दे रहा था। आसपास जलते दीपकों की काँपती नारंगी लौ कभी उसे उजाले में लाती, कभी फिर छाया में छोड़ देती। पुजारी अपनी पूजा में उसी सहज लय से लगे थे जो हजारों बार दोहराए गए कर्म से आती है।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>नैना के होंठ बहुत धीमे हिल रहे थे, मगर विक्रम ने शब्द सुनने की कोशिश नहीं की। नैना का खाली हाथ अपने सीने पर टिका था, जैसे भीतर की किसी चीज़ को वहीं थामे रखना चाहती हो। विक्रम ने नैना को इतनी स्थिरता से कभी नहीं देखा था—नींद में भी नहीं।</p>\n<p>थोड़ी देर बाद विक्रम ने भी आँखें बंद कर लीं।</p>\n<p>और हैरानी की बात यह थी कि विक्रम को अपनी दुआ सोचनी नहीं पड़ी।</p>\n<p>न प्रमोशन।</p>\n<p>न अगली पोस्टिंग में अपनी सलामती।</p>\n<p>न अपने लिए कुछ और।</p>\n<p>विक्रम ने बस इतना माँगा कि जिस ज़िंदगी को वे दोनों धीरे-धीरे साथ बुन रहे थे, उसके और उनके बीच जो कुछ भी खड़ा हो—एक पिता का डर, दूरियाँ, अपनी ड्यूटी या कोई ऐसी मुश्किल जिसका नाम वे अभी जानते भी न हों—वह रास्ता रोकने के बजाय किसी तरह रास्ते से हट जाए।</p>\n<p>बस इतना।</p>\n<p>जब दोनों सीढ़ियाँ चढ़कर वापस धूप में आए, नैना की आँखों में नमी थी। वह रो नहीं रही थी; जैसे भीतर कुछ इतना भर गया हो कि आँखों तक आ पहुँचा हो और अब उतरने के लिए थोड़ा वक्त माँग रहा हो।</p>\n<p>“ठीक हो?” विक्रम ने पूछा।</p>\n<p>“ठीक से भी ज़्यादा।”</p>\n<p>नैना ने आँखों के किनारे पोंछे और ख़ुद पर हल्का-सा हँस दी।</p>\n<p>“पता नहीं मुझे क्या हो गया था। ज़िंदगी में न जाने कितने मंदिर देखे हैं। लेकिन यहाँ… कुछ अलग लगा। जैसे एक ही वक्त में मन पर कुछ वज़न भी रख दिया हो और कुछ उतार भी दिया हो।”</p>\n<p>विक्रम ने कहा, “शायद साथ का असर है।”</p>\n<p>नैना ने उसे देखा।</p>\n<p>“शायद।”</p>\n<p>फिर नैना ने विक्रम का हाथ थाम लिया।</p>\n<p>संकरी गलियों से लौटते हुए शहर अपनी सामान्य ज़िंदगी में व्यस्त था। कहीं ठेले पर प्रसाद बिक रहा था, चमकीली साड़ियों में कुछ औरतें फोन पर तस्वीरें देख रही थीं, बच्चे श्रद्धालुओं और दुकानों के बीच से रास्ता बनाकर दौड़ रहे थे। पीछे कहीं क्षिप्रा पर अब भी दोपहर की रोशनी ठहरी हुई थी।</p>\n<p>कुछ दूर चलने के बाद नैना ने कहा, “मन हल्का लग रहा है, विक्रम। मैं यहाँ अपने भीतर कुछ लेकर आई थी जिसे मैंने तुमसे भी पूरी तरह माना नहीं था… लगता है उसका थोड़ा हिस्सा यहीं छोड़ दिया।”</p>\n<p>“अच्छी बात है।”</p>\n<p>“हाँ।”</p>\n<p>नैना चलते-चलते अचानक रुक गई और विक्रम की तरफ मुड़ गई। लोग दोनों ओर से निकलते रहे; उस भीड़ के बीच उस पल जैसे उसे किसी की परवाह नहीं थी।</p>\n<p>“मैं तुमसे प्यार करती हूँ।”</p>\n<p>विक्रम उसे देखता रहा।</p>\n<p>“शायद जितनी साफ़ तरह से, जितनी बार मुझे ये कहना चाहिए था, मैंने नहीं कहा। जितना इसका मतलब मेरे लिए है, उतना शब्दों में रखा ही नहीं।”</p>\n<p>नैना की आवाज़ में इस बार कोई झिझक नहीं थी।</p>\n<p>“मैं तुमसे प्यार करती हूँ, विक्रम। और आज इतने लोगों के बीच ये कहने से डर नहीं लग रहा।”</p>\n<p>“मैं भी तुमसे प्यार करता हूँ।”</p>\n<p>कुछ डर महीनों तक चुपचाप ढोने से बेहतर किसी मंदिर में एक बार कह देना था।</p>\n<p>वे दो दिन और उज्जैन में रहे। कोई खास योजना नहीं बनाई। छोटी जगहों पर खाना खाया, शामें नदी के किनारे बिताईं और कभी बहुत कुछ, कभी बिल्कुल बेकार की बातें करते रहे—उस बेफिक्री से जो अक्सर तभी लौटती है जब दो लोग मिलकर कोई भारी चीज़ थोड़ी देर के लिए ज़मीन पर रख चुके हों।</p>\n<p>वापसी की ट्रेन में बैठने तक उस छोटे-से फ्लैट में उनके बीच जो कुछ दरका था, वह पहले से मजबूत होकर जुड़ चुका था। इसलिए नहीं कि झगड़ा हुआ ही नहीं था, बल्कि इसलिए कि उन्होंने उसे सिर्फ बीत जाने नहीं दिया—उससे कुछ सीखा भी था।</p>\n<p>विक्रम की छुट्टी ख़त्म होने से पहले एक मंगलवार की शाम वे फिर लीजर वैली गए।</p>\n<p>वही पुरानी बेंच।</p>\n<p>वही गुलमोहर।</p>\n<p>मगर इस बार पेड़ वैसा नहीं था जैसा उनकी पहली मुलाक़ात के दिन था।</p>\n<p>वह पूरी तरह खिल चुका था।</p>\n<p>ऊपर शाखाओं पर नारंगी-लाल फूल इतने घने थे कि बेंच के ऊपर जैसे आग के रंग की एक छत तन गई हो।</p>\n<p>नैना ने सिर उठाकर देर तक उसे देखा।</p>\n<p>“हम कभी इसे ऐसे खिला हुआ देखकर यहाँ नहीं बैठे।”</p>\n<p>“नहीं।”</p>\n<p>“हर बार या तो खाली था, या बस कलियाँ आने लगी थीं। पहली बार लग रहा है जैसे ये वैसा दिख रहा है जैसा इसे होना चाहिए।”</p>\n<p>विक्रम ने ऊपर देखा।</p>\n<p>“पता नहीं क्यों… सही वक्त लगता है इसे ऐसे देखने का।”</p>\n<p>“मुझे भी।”</p>\n<p>नैना की नज़र पेड़ से उतरकर विक्रम पर आ गई और चेहरे पर धीरे-धीरे एक नरमी फैल गई।</p>\n<p>“मुझे ये जगह बहुत पसंद है, विक्रम। कभी-कभी लगता है हमारी कहानी यहीं से शुरू हुई थी… और उसका कुछ हिस्सा तब से यहीं रह गया।”</p>\n<p>वह चुप रही।</p>\n<p>जब दोबारा बोली तो आवाज़ पहले से धीमी थी।</p>\n<p>“तुम जानते हो न… मैं तुम्हारे बिना रह तो लूँगी। रहना सीख भी लूँगी।”</p>\n<p>विक्रम ने उसकी ओर देखा, मगर बीच में कुछ नहीं कहा।</p>\n<p>“पर वैसी नहीं रहूँगी जैसी अब हूँ। ये सोचकर ही सच में डर लगता है। मेरी हर भावना जाने कब तुमसे जुड़ती चली गई, मुझे ख़ुद पता नहीं चला।”</p>\n<p>नैना ने ऊपर फैली शाखाओं की तरफ देखा।</p>\n<p>“अगर ये पेड़ हमारी बात सुन सकता है तो आज इसे गवाह रहने दो।”</p>\n<p>फिर नैना की नज़र वापस विक्रम पर आई।</p>\n<p>“इसी डर की वजह से मैं महाकाल जाना चाहती थी। इसीलिए वहाँ वही माँगा जो माँगा।”</p>\n<p>नैना ने धीरे से साँस छोड़ी।</p>\n<p>“और अब दिल शांत है, विक्रम। सच में।”</p>\n<p>उसी समय ऊपर कहीं से गुलमोहर की एक पंखुड़ी शाखा से छूटी।</p>\n<p>हवा में धीरे-धीरे घूमती हुई नीचे आई और नैना की खुली हथेली पर आकर ठहर गई।</p>\n<p>नैना देर तक उसे देखती रही।</p>\n<p>चेहरे पर जो भाव आया, उसे विक्रम पढ़ नहीं पाया।</p>\n<p>वह चुप रही।</p>\n<p>फिर अपनी उँगलियाँ धीरे से बंद कर लीं—</p>\n<p>और उस छोटी-सी पंखुड़ी को हथेली में सहेज लिया।</p>\n<p>“सुन रहा है,” उसने लगभग ख़ुद से कहा।</p>\n<p>विक्रम ने उसका हाथ थाम लिया—पंखुड़ी अब भी उसकी उँगलियों के बीच थी—और देर तक कुछ नहीं बोला। उसके साथ उस पेड़ के नीचे बैठा रहा, जिसने आख़िर वह सब पहन लिया था जो बनना सीखने में उसे पूरा एक साल लगा था।</p>\n<p>उस पल दोनों में से किसी ने ध्यान नहीं दिया कि पूरा खिला हुआ पेड़ वही पेड़ भी होता है, जो चुपचाप, बिना किसी को दिखे, अपने फूल छोड़ने का काम शुरू कर चुका होता है।</p>"}, {"chapter": 28, "title": "अध्याय 26 — माँ से कही हुई बात", "content": "<h1>अध्याय 26 — माँ से कही हुई बात</h1>\n<p>नैना माँ के पास उस दोपहर आई जब पिता घर पर नहीं थे।</p>\n<p>रसोई में उसकी माँ रोटियाँ बना रही थीं। लोई के चकले पर पड़ने की मुलायम थपक, गर्म तवे पर रोटी डालते ही उठती हल्की-सी सिसकारी और गेहूँ व घी की वही जानी-पहचानी खुशबू कमरे में भरी थी, जो नैना के बचपन की न जाने कितनी शामों से इस रसोई का हिस्सा रही थी।</p>\n<p>नैना माँ के पास रखे छोटे स्टूल पर उसी तरह बैठ गई जैसे बचपन में बैठा करती थी। बात सीधे कहनी थी, मगर शब्द फिर भी रास्ता घुमाकर ढूँढ़ रहे थे।</p>\n<p>“माँ… मुझे इस बार तुमसे एक बात ठीक से करनी है। सिर्फ तस्वीरें दिखाकर नहीं।”</p>\n<p>माँ ने आटे से नज़र नहीं उठाई, लेकिन बेलन की रफ्तार थोड़ी धीमी पड़ गई।</p>\n<p>“विक्रम के बारे में?”</p>\n<p>“हाँ।”</p>\n<p>नैना ने एक साँस ली।</p>\n<p>“मैं उससे शादी करना चाहती हूँ।”</p>\n<p>बेलन एक पल के लिए रुक गया।</p>\n<p>लोई की थपक बंद हो गई और रसोई में सिर्फ तवे की हल्की सरसराहट रह गई।</p>\n<p>बस एक पल।</p>\n<p>फिर माँ ने रोटी बेलनी शुरू कर दी, मगर अब पहले से धीमे।</p>\n<p>“मैं सोच रही थी ये बात कब आएगी,” उन्होंने कहा। “जिस दिन शादी की तस्वीरें दिखा रही थी, उसी दिन तेरी आवाज़ में सुन लिया था। लगा नहीं था साफ़-साफ़ कहने में इतना वक्त लगाएगी।”</p>\n<p>“मुझे समझ नहीं आ रहा था कैसे कहूँ। जब तक बात सिर्फ मेरी ज़िंदगी में चुपचाप चल रही थी, तब तक वह मेरी थी। ये कह देने के बाद… अब तुम्हें और पापा को भी उसके बारे में फ़ैसला करना पड़ेगा।”</p>\n<p>माँ ने रोटी तवे पर डाली, हाथ दुपट्टे से पोंछे और पहली बार पूरी तरह नैना की ओर मुड़ीं।</p>\n<p>“तू पक्की है? शादी की बात कर रही है? सिर्फ… जो अभी तुम दोनों के बीच है उसकी नहीं?”</p>\n<p>“पूरी तरह पक्की हूँ।”</p>\n<p>माँ देर तक नैना को देखती रहीं।</p>\n<p>माँ की आँखों में हैरानी नहीं थी। उन्होंने आटे की परात थोड़ी दूर खिसका दी—जैसे इस बात के लिए जगह बना रही हों।</p>\n<p>“तुझे पता है तेरे पापा आसानी से नहीं मानेंगे।”</p>\n<p>“पता है।”</p>\n<p>“मैंने उस दिन भी कहा था। आर्मी… उनके लिए सिर्फ यही एक शब्द काफी होगा आधा मन बंद कर लेने के लिए, लड़के को ठीक से जानने से पहले।”</p>\n<p>नैना ने बहुत धीमे कहा, “तुम्हारी वजह से?”</p>\n<p>माँ की आँखों का भाव ज़रा-सा बदल गया।</p>\n<p>“मतलब… तुम्हारी ज़िंदगी जैसी रही उसकी वजह से?”</p>\n<p>जवाब नहीं आया।</p>\n<p>“उस दिन जो कहा था, याद है?”</p>\n<p>“सब याद है।”</p>\n<p>नैना ने आगे बढ़कर माँ का हाथ पकड़ लिया।</p>\n<p>“मुझे सच-सच बताओ। क्या इतना मुश्किल था जितना तुमने उस दिन कहा था?”</p>\n<p>माँ की नज़र दोनों के जुड़े हाथों पर टिक गई।</p>\n<p>जब बोलीं तो आवाज़ में अचानक उम्र कुछ ज़्यादा सुनाई दी।</p>\n<p>“कुछ साल उससे भी मुश्किल थे। कुछ आसान भी। बेटी को ऐसी ज़िंदगी समझाना आसान नहीं होता जब उसने उसे ख़ुद जिया न हो।”</p>\n<p>माँ ने नैना की हथेली एक बार दबाई।</p>\n<p>“मैंने तुझसे कहा था न—दिल जो कर रहा है उसे करने दे, मगर आँखें खुली रखना। अगर सच कहूँ तो मुझे नहीं लगता तूने आँखें उतनी खुली रखीं।”</p>\n<p>नैना कुछ नहीं बोली।</p>\n<p>“लेकिन अब उसका कोई मतलब नहीं। जो होना था, हो चुका। अब ज़रूरी ये है कि आगे क्या करना है।”</p>\n<p>“पापा से बात करोगी?”</p>\n<p>माँ ने लंबी साँस छोड़ी।</p>\n<p>उस साँस में थकान आज की नहीं थी।</p>\n<p>“मुझे पता है क्या करना है। मैं ये नहीं कहूँगी कि बात अच्छी जाएगी। तेरे पापा को मैं जानती हूँ; बातचीत शुरू होने से पहले ही लगभग बता सकती हूँ कि ख़त्म कहाँ होगी।”</p>\n<p>फिर उन्होंने बेटी की तरफ देखा।</p>\n<p>“लेकिन पूरा वज़न तेरे मुँह से उन पर पड़ने से पहले ज़मीन थोड़ी नरम कर देना मेरा काम है।”</p>\n<p>नैना के चेहरे पर हल्की-सी मुस्कान आई।</p>\n<p>“धन्यवाद।”</p>\n<p>“अभी मत दे धन्यवाद।”</p>\n<p>माँ ने आटे से लगी उँगली उसकी ओर उठाई।</p>\n<p>“मैं सिर्फ पहले बात कर रही हूँ। फ़ैसला तेरे पापा का होगा।”</p>\n<p>“और मेरा?”</p>\n<p>माँ नैना को देखती रहीं।</p>\n<p>“तेरा फ़ैसला तो तू मुझे अभी बता चुकी है।”</p>\n<p>उन शब्दों के बाद नैना के कंधे ढीले पड़ गए।</p>\n<p>माँ ने तवे की तरफ मुड़ते हुए कहा, “और एक बात—अगर तेरे पापा नहीं माने तो इसका मतलब ये नहीं कि वह तुझे समझते नहीं या तुझसे कम प्यार करते हैं। कई बार माँ-बाप जिस चीज़ से अपने बच्चे को बचाना चाहते हैं, वही चीज़ उनके अपने पुराने घाव से निकल रही होती है।”</p>\n<p>“मुझे पता है।”</p>\n<p>“अभी तुझे लगता है पता है।” माँ ने रोटी पलटी।</p>\n<p>“देखते हैं जब वह सामने बैठकर ख़ुद कहेंगे तब कितना पता रहता है।”</p>\n<p>नैना चुप हो गई।</p>\n<p>थोड़ी देर बाद माँ ने जैसे ख़ुद से कहा, “बच्चों को चीज़ों से बचाना भी अजीब काम है। वे चाहें या न चाहें, माँ-बाप को लगता रहता है यही उनका काम है।”</p>\n<p>फिर माँ ने आटे लगे हाथ से नैना का चेहरा एक पल के लिए छुआ और थकी-सी मुस्कान के साथ कहा—</p>\n<p>“आज रात मुझे उससे बात करने दे। उसके बाद ज़रूरत पड़ी तो तू ख़ुद बात करना। लेकिन पहले मुझे जाने दे।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>रात को खाना ख़त्म होने और घर शांत हो जाने के बाद नैना की माँ बरामदे में अपने पति के पास जाकर बैठीं।</p>\n<p>बाहर बगीचे में कहीं कोई आवारा कुत्ता दो बार भौंका और फिर चुप हो गया। रास्ते के किनारे कतार में लगे गेंदे के फूलों की हल्की, कुछ कड़वी-सी गंध ठंडी होती हवा में घुल रही थी।</p>\n<p>उन्होंने बिना बात घुमाए सब बता दिया।</p>\n<p>वह देर तक चुप बैठे रहे। जबड़ा कसा हुआ था और नज़र अँधेरे बगीचे में कहीं स्थिर।</p>\n<p>फिर सिर्फ एक शब्द कहा—</p>\n<p>“आर्मी।”</p>\n<p>उस एक शब्द में जितना कुछ था, उसकी पत्नी पहले से जानती थी।</p>\n<p>“मुझे पता है।”</p>\n<p>“तुम्हें तो सबसे पहले इसे रोकना चाहिए था। जिस दिन उसने पहली बार उस लड़के का ज़िक्र किया था, उसी दिन।”</p>\n<p>“मैंने कोशिश की थी। अपने तरीके से। जिस दिन तस्वीरें दिखाईं, उसी दिन कहा था आँखें खुली रखना।”</p>\n<p>उनकी आवाज़ स्थिर थी, लेकिन उसके नीचे पुरानी थकान की महीन परत थी।</p>\n<p>“वह आज मेरे पास प्यार करने की इजाज़त माँगने नहीं आई थी। वह बताने आई थी कि उसका दिल अपना फ़ैसला कई हफ्ते पहले कर चुका है।”</p>\n<p>पति ने कुछ नहीं कहा।</p>\n<p>“मैं भी कभी इक्कीस साल की थी,” उन्होंने धीरे से कहा। “मुझे भी याद है अपने दिल के फ़ैसले के लिए किसी की इजाज़त की कितनी कम ज़रूरत महसूस होती थी।”</p>\n<p>बरामदे में थोड़ी देर सिर्फ रात रही।</p>\n<p>फिर उन्होंने कहा, “मैं तुमसे आज ही हाँ कहने को नहीं कह रही। बस उससे ख़ुद बात करना। ठीक से। कोई फ़ैसला करने से पहले उसकी बात सुनना। इतना तो उसका हक है—अपने पिता के मुँह से निकले साफ़ शब्द, माँ के ज़रिए पहुँची चेतावनी नहीं।”</p>\n<p>वह बहुत देर और चुप रहे।</p>\n<p>गेट के बाहर बजरी पर किसी गाड़ी के पहिए रुके और आगे बढ़ गए। दोनों ने सुना, किसी ने सिर नहीं घुमाया।</p>\n<p>फिर जब बोले तो आवाज़ पहले से भारी थी।</p>\n<p>“बात करूँगा।”</p>\n<p>उन्होंने पहली बार पत्नी की तरफ पूरी तरह देखा। उनके चेहरे पर वह कच्चापन था जो वर्षों बाद भी बहुत कम बाहर आता था।</p>\n<p>“लेकिन एक बात तुम भी समझो। क्योंकि इस बातचीत में मैं क्या लेकर बैठने वाला हूँ, उसे इस घर में तुमसे बेहतर कोई नहीं जानता।”</p>\n<p>वह रुके।</p>\n<p>“मैंने देखा है उस ज़िंदगी ने तुम्हारे साथ क्या किया। अपनी तरफ से भी जिया और तुम्हारी तरफ से भी जितना देख सकता था, देखा। इतने साल बाद भी अपनी बेटी को वही बोझ उठाते देखने की इच्छा नहीं है मुझमें।”</p>\n<p>उन्होंने आगे कुछ नहीं कहा।</p>\n<p>कहने की ज़रूरत भी नहीं थी।</p>\n<p>उस डर के नीचे एक पुराना दुख था, जो वर्षों में ख़त्म नहीं हुआ था—बस इंसान ने उसके साथ रहना सीख लिया था। अपनी सर्विस के उन सालों का हिसाब, जिनमें उन्हें हमेशा लगता रहा कि उनकी वर्दी ने उनकी पत्नी से उतना माँग लिया जितना किसी मोहब्बत को माँगने का हक नहीं होना चाहिए था।</p>\n<p>वह कर्ज जिसे वह आज तक पूरा चुका नहीं पाया था।</p>\n<p>और जिसे विरासत की तरह अपनी बेटी के हाथों में देने का उनका कोई इरादा नहीं था।</p>\n<p>नैना की माँ ने बहुत धीरे कहा—</p>\n<p>“मुझे पता है।”</p>\n<p>फिर थोड़ी देर बाद—</p>\n<p>“लेकिन मैंने वह सब इसलिए उठाया क्योंकि तुमसे इतनी मोहब्बत थी कि उठा सकी। उसकी भी कोई कीमत है। जब नैना से बात करना, तो उस हिस्से को मत भूल जाना।”</p>\n<p>उन्होंने जवाब नहीं दिया।</p>\n<p>कंधों में वर्षों से अटका कोई तनाव एक पल के लिए थोड़ा ढीला पड़ा, जैसे रात के उस सुनसान बरामदे में बहुत देर से रोकी हुई साँस आख़िर चुपचाप बाहर निकल गई हो।</p>\n<p>उस समय दोनों में से किसी को नहीं मालूम था कि जिस लड़के को लेकर वे बैठकर बात कर रहे थे, उसने उनकी बातचीत का इंतज़ार करने का फ़ैसला ही नहीं किया था।</p>\n<p>कुछ ही दिनों में विक्रम ख़ुद उस दरवाज़े पर खड़ा होने वाला था—</p>\n<p>बिना बुलाए नहीं,</p>\n<p>मगर बिना किसी औपचारिकता की आड़ लिए।</p>\n<p>सिर्फ इतना माँगने कि फ़ैसला सुनाने से पहले एक बार उसकी बात भी सुन ली जाए।</p>"}, {"chapter": 29, "title": "अध्याय 27 — उसके पिता के सामने", "content": "<h1>अध्याय 27 — उसके पिता के सामने</h1>\n<p>किसी औपचारिक बात की शुरुआत होने से पहले विक्रम ने ख़ुद जाकर नैना के पिता से मिलने की ज़िद की।</p>\n<p>नैना चाहती थी कि बात थोड़ी सहज तरह से शुरू हो—किसी पारिवारिक मुलाक़ात में, किसी ऐसे मौके पर जहाँ विक्रम की मौजूदगी अपने साथ इतना साफ़ मकसद लेकर न आए। लेकिन विक्रम तैयार नहीं हुआ।</p>\n<p>“पहले एक बार मैं ख़ुद उनसे बात करना चाहता हूँ। मेरे घरवाले तुम्हारे घर आएँ, उससे पहले। दो परिवार सामने बैठें उससे पहले।”</p>\n<p>“अकेले?”</p>\n<p>“हाँ।”</p>\n<p>उसने कुछ पल रुककर कहा, “अगर उन्हें मना ही करना है तो पहले मैं उनके मुँह से सुनूँ। मेरे माँ-पापा को उस इंकार के सामने बैठाने से पहले।”</p>\n<p>रविवार की सुबह वह बादशाहपुर से कार लेकर गुरुग्राम के बाहर नैना के पुश्तैनी घर पहुँचा।</p>\n<p>घर बहुत बड़ा नहीं था, मगर सलीके से रखा हुआ था। सामने छोटे-से बगीचे में रास्ते के दोनों ओर गेंदे के पौधे सीधी कतारों में लगे थे—जैसे इस घर का मालिक खूबसूरती में भी थोड़ा अनुशासन पसंद करता हो।</p>\n<p>विक्रम ने कपड़े भी वैसे ही चुने थे जैसे कोई फौजी उस दिन चुनता है जब वर्दी नहीं पहननी, मगर दिन फिर भी मामूली नहीं है—सादी, ठीक नाप की कमीज़, प्रेस की हुई पतलून, चमकाए हुए काले जूते और उनसे मिलती बेल्ट। कुछ दिखावटी नहीं, लेकिन कुछ भी लापरवाह भी नहीं।</p>\n<p>दरवाज़ा खुला तो सामने खड़े आदमी को देखकर विक्रम एक पल ठहरा।</p>\n<p>नैना के पिता करीब पचास के थे, मगर उम्र अभी उनके शरीर पर ढील बनकर नहीं उतरी थी। कंधे अब भी चौड़े थे और पीठ उस सहज सीध में थी जो वर्षों तक ‘सावधान’ की मुद्रा में खड़े रहने के बाद आदेश नहीं रहती, इंसान की आदत बन जाती है। कनपटियों के पास बाल सफ़ेद हो चुके थे, मगर आँखों की धार में कोई उम्र नहीं आई थी।</p>\n<p>उन्होंने विक्रम को सिर से पैर तक एक बार देखा।</p>\n<p>बस कुछ सेकंड।</p>\n<p>उतने ही, जितने एक पुराने सैनिक को सामने खड़े दूसरे सैनिक को पढ़ने के लिए चाहिए होते हैं।</p>\n<p>“कैप्टन राठौड़।”</p>\n<p>उन्होंने पूछा नहीं था, पहचान लिया था।</p>\n<p>नैना के पिता को पता था कि कौन आने वाला है।</p>\n<p>“सर। मिलने के लिए धन्यवाद।”</p>\n<p>“अंदर आओ।”</p>\n<p>बैठक छोटी और व्यवस्थित थी। दीवार पर कुछ पुरानी तस्वीरें थीं। एक में नैना के पिता बहुत कम उम्र के, आर्मी ड्रेस में खड़े थे; पास कुछ ऐसे मेडल की तस्वीरें थीं जिन्हें विक्रम दो दशक पुराने एक अभियान से पहचानता था। एक फीकी पड़ चुकी तस्वीर में उनकी पत्नी उनके साथ थीं—दोनों इतने जवान कि वर्तमान में बैठे आदमी से उनका रिश्ता पहचानने में एक पल लगता था।</p>\n<p>दोनों आमने-सामने बैठ गए।</p>\n<p>कुछ देर बाद नैना की माँ चाय रख गईं—उनकी उँगलियों पर आटे का हल्का-सा निशान अब भी था। जाते हुए उनकी नज़र विक्रम पर कुछ पल ठहरी—जैसे चेहरे से वह जवाब पढ़ लेना चाहती हों जो इस कमरे में अभी दिया भी नहीं गया था।</p>\n<p>दरवाज़ा बंद हुआ।</p>\n<p>नैना के पिता ने कोई भूमिका नहीं बाँधी।</p>\n<p>“मेरी बेटी का हाथ माँगने आए हो।”</p>\n<p>विक्रम सीधा बैठा रहा।</p>\n<p>“जी, सर।”</p>\n<p>“तो साफ़-साफ़ कहो। मुझे बात घुमाने वाले आदमी कभी पसंद नहीं रहे।”</p>\n<p>“मैं नैना से शादी करना चाहता हूँ। मेरे परिवार की तरफ से कोई औपचारिक बात शुरू हो, उससे पहले मैं चाहता था कि आप ये बात सीधे मुझसे सुनें।”</p>\n<p>नैना के पिता कुछ देर उसे देखते रहे।</p>\n<p>विक्रम ने उस ख़ामोशी में ख़ुद को स्थिर रखा। वह समझ रहा था कि सवाल शुरू होने से पहले भी उसे परखा जा रहा था।</p>\n<p>“शॉर्ट सर्विस कमीशन?”</p>\n<p>“जी, सर।”</p>\n<p>“दस साल?”</p>\n<p>“जी।”</p>\n<p>“उसके बाद?”</p>\n<p>“अभी पूरी तरह तय नहीं किया। शायद कोई सरकारी सेवा। कुछ साल हैं, ठीक से सोचने के लिए।”</p>\n<p>“और उन कुछ सालों में पोस्टिंग होंगी। ट्रांसफर होंगे। ऐसे ऑपरेशन होंगे जिनके बारे में तुम अपनी पत्नी को तब तक नहीं बता सकोगे जब तक वे ख़त्म न हो जाएँ।”</p>\n<p>उनकी आवाज़ में कठोरता नहीं थी।</p>\n<p>बस वह ठहराव था जो किसी ऐसी बात में आता है जिसे आदमी किताब से नहीं, ज़िंदगी से जानता हो।</p>\n<p>“मैं ठीक-ठीक जानता हूँ तुम क्या हो, कैप्टन। बहुत साल पहले मैं भी तुम्हीं था। जवान, मजबूत… और इस भरोसे से भरा कि मोहब्बत इतनी मजबूत होती है कि इस ज़िंदगी का हर वज़न उठा लेगी।”</p>\n<p>“सर—”</p>\n<p>उन्होंने हाथ हल्का-सा उठा दिया।</p>\n<p>“पहले मेरी बात पूरी होने दो।”</p>\n<p>विक्रम चुप हो गया।</p>\n<p>“मैं तुम्हारे चरित्र पर सवाल नहीं उठा रहा। जितना सुना है, अच्छे आदमी हो। स्थिर हो। शायद ऐसे अफसर भी हो जिस पर उसके जवान अपनी जान का भरोसा कर सकें। ये बात मैं हल्के में नहीं कहता।”</p>\n<p>उन्होंने चाय का कप मेज़ पर रख दिया।</p>\n<p>“मसला तुम नहीं हो, कैप्टन राठौड़। मसला वह ज़िंदगी है जो तुम्हारे साथ आती है। मैंने बीस साल से ज़्यादा वही ज़िंदगी अपनी पत्नी के साथ जी है। और मैंने देखा है उसने उसके साथ क्या किया।”</p>\n<p>विक्रम की नज़र अनायास दीवार पर लगी उस पुरानी तस्वीर की ओर गई जिसमें दोनों बहुत जवान थे।</p>\n<p>“मैं अपनी बेटी के साथ वही होते नहीं देखना चाहता।”</p>\n<p>“मैं ख़तरा समझता हूँ, सर। जितनी ईमानदारी से सोच सकता था, मैंने इस बारे में सोचा है।”</p>\n<p>“सोचना और उसके भीतर जीना दो अलग चीज़ें हैं।”</p>\n<p>नैना के पिता थोड़ा आगे झुके।</p>\n<p>“मेरी पत्नी ने हमारी आधी शादी ऐसे बिताई कि कई-कई दिन उसे पता नहीं होता था मैं ज़िंदा हूँ या नहीं। मैंने ऐसी चीज़ें मिस कीं जो किसी पिता को नहीं करनी चाहिए थीं। एक बार चोट लेकर घर आया और उसे पूरी बात कभी बता भी नहीं पाया, क्योंकि पूरी बात बताने का हक ही मेरा नहीं था।”</p>\n<p>“वह हर बार अकेली संभालती रही। और बहुत अच्छे से संभाला, क्योंकि मजबूत औरत है। मगर मजबूत होना कीमत न चुकाना नहीं होता। मैंने वह कीमत साल-दर-साल, थोड़ा-थोड़ा उसके भीतर जमा होते देखी है।”</p>\n<p>कमरे में कुछ देर सिर्फ पंखे की धीमी आवाज़ रही।</p>\n<p>दोनों के बीच रखी चाय अब ठंडी हो चुकी थी।</p>\n<p>विक्रम के पास कोई चतुर जवाब नहीं था। यह तर्क किसी पुराने ख़याल या अहंकार पर खड़ा नहीं था—इसके नीचे एक इंसान की पूरी शादी थी। उसकी नज़र फिर दीवार की उस तस्वीर पर गई, और इस बार देर तक वहीं रुकी रही।</p>\n<p>“मैं आपको ऐसी ज़िंदगी का वादा नहीं कर सकता जिसमें इसकी कोई कीमत न हो, सर। ऐसा कहूँगा तो आपका अपमान होगा।”</p>\n<p>नैना के पिता ने उसकी तरफ देखा।</p>\n<p>“अच्छा है कि कम-से-कम इतना समझते हो।”</p>\n<p>फिर उन्होंने दोनों हाथ आपस में बाँध लिए।</p>\n<p>“क्या तुम्हें लगता है, आज तुम यहाँ जो भी कहोगे, उससे वह बदल जाएगा जो मैं पहले से जानता हूँ?”</p>\n<p>विक्रम ने जवाब नहीं दिया।</p>\n<p>“अट्ठाईस साल मैंने 18 ग्रेनेडियर्स को दिए हैं। तोलोलिंग—तेरह जून। उसके तीन हफ्ते बाद टाइगर हिल। उन दो पहाड़ों के बीच मेरी बटालियन ने चौंतीस जवान खोए। अठहत्तर और जवानों को स्ट्रेचर पर नीचे लाए।”</p>\n<p>उन्होंने ये आँकड़े सपाट आवाज़ में कहे—वैसे, जैसे कोई इंसान उन गिनतियों को दोहराता है जिन्हें वह इतनी बार पढ़ चुका हो कि अब वे ताज़ा चोट नहीं करतीं।</p>\n<p>“उस साल पूरा देश जोश में डूबा था, कैप्टन। हर छत पर तिरंगा। उन लड़कों के लिए मोमबत्तियाँ, जिनके नाम लोगों ने अख़बार के पहले पन्ने से सीखे और महीने भर में भूल गए।”</p>\n<p>उन्होंने खिड़की की ओर देखा, फिर वापस।</p>\n<p>“वह गर्व मैंने भी महसूस किया था। मगर बाद में, जब शोर थम गया, मैं उन दो पहाड़ों के बीच फिर खड़ा हुआ—और तब मैंने वह देखा जो अख़बारों ने कभी नहीं छापा। जिन माँ-बाप ने उस जोश में बेटे खोए, उस जोश ने उनकी मरम्मत कभी नहीं की। देश अगली सुर्ख़ी की ओर बढ़ गया। वे परिवार कहीं नहीं बढ़े। उन्होंने बस एक ऐसा खालीपन उठाना सीख लिया, जिसे हम बाकी लोग घर जाकर भूल सकते थे।”</p>\n<p>कुछ देर वह कप को मेज़ पर धीरे-धीरे घुमाते रहे, पिए बिना।</p>\n<p>“उन्हीं दो पहाड़ों के बीच—पीछे तोलोलिंग, सामने टाइगर हिल—मैंने ख़ुद से पूरा हिसाब माँगा कि उस गर्मी में मैंने असल में क्या जीता, और क्या खोया।”</p>\n<p>उन्होंने विक्रम की आँखों में सीधे देखा।</p>\n<p>“जो जीता, वह देश का गर्व था। गाँव, जो अब चैन से सोते थे क्योंकि एक हाईवे खुला रहा। जो खोया, वह मेरे सीने के कहीं ज़्यादा पास था। उस साल मैं पैंतीस का था—इतना सीनियर कि अपनी कमान में बीस-बाईस साल के लड़कों को उस पहाड़ पर भेज सकूँ। इतना सीनियर कि मेरी उम्र के किसी भी इंसान को जितनी चिट्ठियाँ माँओं को नहीं लिखनी चाहिए, उससे कहीं ज़्यादा लिख चुका था।”</p>\n<p>“बटालियन कोई पोस्टिंग नहीं होती, कैप्टन—भर्ती के पोस्टर चाहे जो कहें। वह एक परिवार होता है, जिसे तुमने चुना नहीं। उस परिवार के जितने लोग मैंने तीन हफ्तों में दफ़नाए और कंधों पर नीचे उतारे, उतने ज़्यादातर लोग पूरी ज़िंदगी के मामूली दुख में नहीं दफ़नाते।”</p>\n<p>इस बार वह विक्रम को गौर से देखते रहे।</p>\n<p>“नैना ने मुझे तुम्हारे दोस्त के बारे में बताया था। रेड्डी—जो शहीद हुए।”</p>\n<p>उनकी आवाज़ धीमी हो गई। उसमें कुछ लगभग नरम उतर आया।</p>\n<p>“मैं जानता हूँ इतने करीबी दोस्त का जाना आदमी के साथ क्या करता है। मैंने यह अपने से बेहतर इंसानों के साथ होते देखा है। ख़ुद भी जिया है, एक से ज़्यादा बार। अगर एक इंसान के जाने ने तुम्हें उतना गहरा काटा है जितना मुझे लगता है—तो वही ज़ख़्म चौंतीस बार सोचो। और फिर सोचो कि उसके बाद का हर साल इस डर में बीते कि अगला पहाड़ फिर वही माँगेगा।”</p>\n<p>फिर बोले—</p>\n<p>“मैं भी कभी तुम्हारी उम्र का था। कारगिल से बरसों पहले। नॉर्थ-ईस्ट में ऑपरेशन करता था—छोटी-छोटी मुठभेड़ें जीतता, जिनकी ख़बर किसी अख़बार तक नहीं पहुँचती; दोस्तों को उसी चुपचाप तरीके से खोता, जिसका शोक बटालियन के बाहर कोई ठीक से नहीं मनाता। बेख़ौफ़—वैसे, जैसे सिर्फ उस उम्र का इंसान हो सकता है।”</p>\n<p>“और आज जब तुम्हें वहाँ बैठा देखता हूँ तो कोई अजनबी लड़का नहीं दिखता। कई दशक पहले का अपना चेहरा दिखता है—उस समय का, जब मुझे अभी यह समझ नहीं आया था कि मेरी बेख़ौफ़ ज़िंदगी की कीमत मुझसे ज़्यादा वे लोग चुकाएँगे जो मुझसे प्यार करते हैं।”</p>\n<p>उन्होंने कुर्सी की पीठ से शरीर थोड़ा आगे किया।</p>\n<p>“मैं तुम्हें डराने के लिए नहीं कह रहा। तुम मेरे घर में बैठकर मेरी बेटी माँग रहे हो, इसलिए कह रहा हूँ कि तुमने अभी पूरा हिसाब नहीं लगाया है। मैं रिटायरमेंट के बाद से वही हिसाब लगाता आया हूँ।”</p>\n<p>“सर, अपनी सर्विस के ख़तरे समझता हूँ।”</p>\n<p>“अपने लिए।”</p>\n<p>जवाब तुरंत आया।</p>\n<p>“मैं उस हिसाब की बात नहीं कर रहा।”</p>\n<p>वह विक्रम को देखते रहे।</p>\n<p>“तुम पैरा एसएफ़ हो, कैप्टन। जिस इंसान ने ख़तरे के बीच अपना घर बना लिया हो, वह उसकी चाबी किसी और के हाथ में देकर उसे सुरक्षित जगह नहीं कह सकता।”</p>\n<p>विक्रम ने पूछा, “फिर ऐसा क्या है जिससे आपको भरोसा होगा?”</p>\n<p>जवाब आने में एक पल भी नहीं लगा।</p>\n<p>“रेज़िग्नेशन।”</p>\n<p>विक्रम चुप हो गया।</p>\n<p>शब्द छोटा था।</p>\n<p>उसके भीतर जो माँगा गया था, वह नहीं।</p>\n<p>आज उसके कंधे पर सितारे नहीं थे, फिर भी उसे वे वहीं महसूस हुए। आर्मी सिर्फ उसकी नौकरी नहीं थी। उसके खड़े होने के ढंग से लेकर बोलने तक, ज़िम्मेदारी समझने से लेकर ख़ुद अपनी कीमत समझने तक—सब उसी वर्दी के भीतर बना था।</p>\n<p>वह तुरंत कोई बड़ा वादा नहीं करना चाहता था।</p>\n<p>कुछ देर सचमुच उस माँग को अपने भीतर तौलता रहा।</p>\n<p>फिर बोला—</p>\n<p>“ये छोटी बात नहीं है, सर।”</p>\n<p>“मुझे पता है।”</p>\n<p>“लेकिन नैना के लिए कर सकता हूँ।”</p>\n<p>नैना के पिता की आँखें बहुत स्थिर हो गईं।</p>\n<p>“शादी के बाद,” विक्रम ने कहा। “मुझे उतना वक्त दीजिए। मैं रेज़ाइन कर दूँगा।”</p>\n<p>उनके चेहरे पर कोई राहत नहीं आई।</p>\n<p>“इस वक्त वहाँ बैठकर तुमने फ़ैसला किया है कि तुम ये करोगे। तुम्हारी नीयत पर मुझे शक नहीं।”</p>\n<p>“मुझे इस बात पर शक है कि ज़िंदगी तुम्हें वह वादा पूरा करने तक उसी जगह खड़ा रहने देगी जहाँ अभी हो।”</p>\n<p>विक्रम कुछ कहने ही वाला था कि उन्होंने आगे कहा—</p>\n<p>“ड्यूटी किसी इंसान के वादे पूरे होने का शराफत से इंतज़ार नहीं करती, कैप्टन। चाहे वह वादा कितनी ही सच्ची नीयत से किया गया हो।”</p>\n<p>“मैंने ज़िंदगी में कोई कमिटमेंट नहीं तोड़ा, सर।”</p>\n<p>पहली बार नैना के पिता की आँखों में कोई ऐसी बात दिखी जो बहस से भी पुरानी थी।</p>\n<p>“वादा मैंने भी कभी जानबूझकर नहीं तोड़ा, कैप्टन। वे टूटे, क्योंकि ड्यूटी ने उन्हें टूटने दिया।”</p>\n<p>उनकी नज़र कुछ देर अपने हाथों पर टिक गई।</p>\n<p>“मेरे परिवार ने वह सब जिया जो सैनिकों के परिवार जीते हैं। और उसका पूरा वज़न मुझे बहुत बाद में पता चला। टुकड़ों में। जैसे किसी इंसान को सालों बाद वे बातें मालूम होती हैं जिन्हें उसकी पत्नी ने उस वक्त यह सोचकर उससे छिपा लिया था कि वहाँ बैठकर वह उनका कर भी क्या लेगा।”</p>\n<p>कमरे की हवा जैसे कुछ भारी हो गई।</p>\n<p>“नैना बचपन में एक बार अस्पताल में भर्ती हुई थी।”</p>\n<p>विक्रम की आँखें उनकी ओर उठीं।</p>\n<p>“करीब-करीब मर गई थी।”</p>\n<p>उनकी आवाज़ में कोई नाटकीयता नहीं थी।</p>\n<p>इसी वजह से शब्द और गहरे लगे।</p>\n<p>“‘करीब-करीब’ वाला हिस्सा मुझे महीनों बाद पता चला। मेरे लिए बात हल्की करके बताई गई थी।”</p>\n<p>उन्होंने साँस ली।</p>\n<p>“मैं उस वक्त मणिपुर में था। उग्रवादियों के ख़िलाफ़ ऑपरेशन में। ऐसी जगह जहाँ हफ्ते निगल लिए जाते थे और इंसान को पता भी नहीं चलता।”</p>\n<p>“छुट्टी मंज़ूर नहीं हुई। हो भी जाती तो ढाई हजार किलोमीटर दूर अस्पताल के उस बिस्तर तक पहुँचने में करीब एक हफ्ता लग जाता।”</p>\n<p>उनकी नज़र सीधे विक्रम पर आ टिकी।</p>\n<p>“और शायद वह बिस्तर मेरा एक हफ्ता इंतज़ार नहीं करता।”</p>\n<p>विक्रम के पास कहने को कुछ नहीं था।</p>\n<p>“मेरी पत्नी उस अस्पताल में अकेली खड़ी थी, कैप्टन। ऐसे फॉर्म पर दस्तख़त कर रही थी जिन्हें वह पूरी तरह समझती भी नहीं थी। ऐसे फ़ैसले ले रही थी जो किसी माँ को अपने पति के बिना नहीं लेने चाहिए। अपनी बेटी को ज़िंदगी के लिए लड़ते देख रही थी।”</p>\n<p>उनकी आवाज़ अब बहुत धीमी थी।</p>\n<p>“और मैं उससे इतनी दूर अपने कमरे में बैठा था जितनी दूर बहुत-से आदमी अपनी पूरी ज़िंदगी में घर से नहीं जाते। मुझे पता तक नहीं था कि मेरे घर में कोई ज़िंदगी के लिए लड़ रहा है।”</p>\n<p>उन्होंने नज़र फेर ली।</p>\n<p>“हफ्तों बाद एक चिट्ठी पहुँची। तब तक नैना ठीक हो चुकी थी।”</p>\n<p>विक्रम ने बहुत धीमे कहा, “सर… मैं समझ सकता हूँ—”</p>\n<p>“नहीं।”</p>\n<p>आवाज़ ऊँची नहीं हुई।</p>\n<p>“इस बात को तुम अभी समझ नहीं सकते। क्योंकि इस जगह पर तुम्हारी परीक्षा हुई ही नहीं है।”</p>\n<p>फिर उन्होंने जो कहा, उसमें पहली बार पिता सैनिक से बड़ा हो गया।</p>\n<p>“मैंने नैना को जानबूझकर वैसा बड़ा किया जैसा वह है—लाउड, बेख़ौफ़, अपने बाप से भी बिना डरे बहस करने वाली। मेरी पूरी अनुशासित ज़िंदगी में शायद वही एक चीज़ थी जिसे मैं आर्मी की इजाज़त के बिना बिल्कुल अपने तरीके से बना सका।”</p>\n<p>विक्रम को नैना की वह तस्वीर याद आई जो उसने कभी उसे दिखाई थी—सोलह साल की नैना, कंधे पर क्रिकेट का बल्ला, दुनिया से अपनी जगह माँगने के बजाय उसे अपना मानकर खड़ी।</p>\n<p>“अगर उसकी शादी तुमसे होती है तो मुझे डर है कि मैं वही सब उससे भी धीरे-धीरे छिनते देखूँगा।”</p>\n<p>उन्होंने विक्रम की आँखों में देखते हुए कहा—</p>\n<p>“इसलिए नहीं कि तुम कभी उस पर हाथ उठाओगे। या जानबूझकर उसे छोटा करोगे। मुझे उसका डर नहीं है।”</p>\n<p>उनकी आवाज़ अब लगभग थक चुकी थी।</p>\n<p>“डर ये है कि जो औरत हर दिन किसी अनहोनी के साथ जीती है, वह धीरे-धीरे ख़ुद को छोटा करना सीख जाती है। कोई उसे सिखाता नहीं। वह अपने आप सीखती जाती है।”</p>\n<p>इस बार विक्रम ने तुरंत जवाब नहीं दिया।</p>\n<p>क्योंकि उसके पास उस डर को झूठा कहने का कोई ईमानदार तरीका नहीं था।</p>\n<p>“मैं आपको ये वादा नहीं कर सकता कि नैना कभी ख़ुद को छोटा नहीं करेगी, सर। और ये दिखावा भी नहीं करूँगा कि मेरे पास ऐसा कोई जवाब है जो आपका डर ख़त्म कर दे।”</p>\n<p>वह सीधा उनकी ओर देखता रहा।</p>\n<p>“लेकिन जो बात मैं नैना से कह चुका हूँ, वही आपसे कह सकता हूँ। मैं अपनी पूरी कोशिश करूँगा कि इस ज़िंदगी की कीमत उसे कभी अकेले न उठानी पड़े।”</p>\n<p>विक्रम रुका।</p>\n<p>“मैं इस मामले में ग़लती पहले ही कर चुका हूँ। पंद्रह दिन उसे ये तक नहीं पता था कि मैं ज़िंदा हूँ या नहीं। मैंने पहले से ठीक तरह नहीं बताया था कि ऐसा हो सकता है। उसने वे पंद्रह दिन कैसे निकाले, मैं जानता हूँ।”</p>\n<p>“उस ग़लती ने मुझे कुछ सिखाया है।”</p>\n<p>फिर उसने बहुत साफ़ कहा—</p>\n<p>“मैं अभी कोई पूरा बना हुआ आदमी नहीं हूँ, सर। नैना से सही तरह प्यार करना अभी सीख रहा हूँ। लेकिन सीख रहा हूँ। और सीखना बंद नहीं करूँगा।”</p>\n<p>नैना के पिता काफी देर उसे देखते रहे।</p>\n<p>चेहरे पर एक परछाईं-सी आई और चली गई; विक्रम उसे पढ़ नहीं पाया।</p>\n<p>“ईमानदार जवाब है।”</p>\n<p>कुछ देर बाद उन्होंने कहा—</p>\n<p>“लेकिन मेरा जवाब नहीं बदलता, कैप्टन। मुझे अफसोस है।”</p>\n<p>विक्रम की उँगलियाँ अपने घुटनों पर स्थिर रहीं।</p>\n<p>“मुझे यकीन है तुमने जो कहा, हर शब्द सच में कहा। मैं भी अपनी पत्नी से किए हर वादे के वक्त यही मानता था कि उसे निभाऊँगा।”</p>\n<p>उनकी आवाज़ में अब गुस्सा बिल्कुल नहीं था।</p>\n<p>“सिर्फ किसी बात को पूरे दिल से चाह लेना हमेशा काफी नहीं होता कि यह ज़िंदगी एक इंसान और उसके पीछे खड़ी औरत से क्या माँगेगी।”</p>\n<p>“सर—”</p>\n<p>“मैंने नैना की शादी की बात दूसरी जगह शुरू कर दी है।”</p>\n<p>कमरे में कुछ जैसे एकदम स्थिर हो गया।</p>\n<p>“परिवार को बरसों से जानता हूँ। लड़का स्थिर नौकरी में है। हर शाम घर लौटता है। कोई ऑपरेशन नहीं। कोई पंद्रह दिन की ख़ामोशी नहीं।”</p>\n<p>उन्होंने नज़र नहीं हटाई।</p>\n<p>“मुझे पता है अभी नैना यह नहीं चाहती। मैं उससे सिर्फ इतना कह रहा हूँ कि बीस साल बाद वह क्या चाहेगी, उसके बारे में शायद मुझे आज उससे थोड़ा ज़्यादा पता है।”</p>\n<p>सम्मान के साथ चल रही यह बातचीत अपनी आख़िरी जगह पर पहुँच चुकी थी। विक्रम ने घुटनों पर रखे हाथ सीधे कर लिए, जैसे उठने की तैयारी कर रहा हो।</p>\n<p>फिर भी उसने पूछा—</p>\n<p>“एक सवाल पूछ सकता हूँ, सर?”</p>\n<p>“पूछो।”</p>\n<p>“अगर आपकी बेटी उस जगह खड़ी होती जहाँ कभी आपकी पत्नी खड़ी थीं… और वह आपसे कहती कि उसे इतना भरोसा दीजिए कि वह ये ज़िंदगी ख़ुद चुन सके—तब भी आप उसे मना कर देते?”</p>\n<p>नैना के पिता का जबड़ा एक पल को कसा।</p>\n<p>बहुत थोड़ी देर के लिए।</p>\n<p>फिर ढीला पड़ गया।</p>\n<p>“पता नहीं।”</p>\n<p>“यही ईमानदार जवाब है, कैप्टन। मुझे नहीं पता।”</p>\n<p>उन्होंने कुछ क्षण बाद कहा—</p>\n<p>“लेकिन आज मुझे उस सवाल का जवाब नहीं देना है। आज मेरी बेटी उस तरफ नहीं खड़ी जहाँ मैं कभी खड़ा था। वह वहाँ खड़ी है जहाँ मेरी पत्नी खड़ी थी।”</p>\n<p>उनकी आँखों में वर्षों पुरानी कोई तस्वीर अब भी जीवित थी।</p>\n<p>“और उस तरफ खड़े होने की कीमत मैं जानता हूँ।”</p>\n<p>वह उठ गए।</p>\n<p>विक्रम भी समझ गया कि मुलाक़ात ख़त्म हो चुकी है।</p>\n<p>वह खड़ा हुआ।</p>\n<p>“मेरी बात सुनने के लिए धन्यवाद, सर।”</p>\n<p>फिर कुछ पल रुककर बोला—</p>\n<p>“आप जो भी फ़ैसला लें, मैं उसके पीछे की वजह का सम्मान करता हूँ। मुझे नहीं लगता आपका डर ग़लत है।”</p>\n<p>उसकी आवाज़ में पहली बार हल्की-सी थकान उतर आई।</p>\n<p>“बस काश उसकी कीमत वह न होती जो अब हम दोनों को चुकानी पड़ेगी।”</p>\n<p>मेज़ पर दोनों कप ज्यों-के-त्यों रह गए—ठंडी चाय, जिसे किसी ने नहीं पिया।</p>\n<p>नैना के पिता उसे दरवाज़े तक छोड़ने आए।</p>\n<p>चौखट पर पहुँचकर वह एक पल रुके, हाथ दरवाज़े के फ्रेम पर टिका रहा।</p>\n<p>“एक बात और, कैप्टन।”</p>\n<p>विक्रम मुड़ा।</p>\n<p>“अगर हालात अलग होते… अगर मैं ख़ुद वह ज़िंदगी न जी चुका होता जो जी है… तो शायद तुम्हें दामाद के रूप में पसंद करता।”</p>\n<p>उनके चेहरे पर मुस्कान नहीं थी।</p>\n<p>“और ये बात उस इंसान से आ रही है जो ऐसी बातें आसानी से नहीं कहता।”</p>\n<p>विक्रम ने बस सिर झुका दिया।</p>\n<p>कुछ मिनट बाद वह कार की तरफ लौट रहा था। रास्ते के दोनों ओर गेंदे की कतारें वैसी ही सीधी खड़ी थीं—बिना झुके, इस घर की तरह।</p>\n<p>कार मुड़ी तो बजरी पर पहियों की आवाज़ देर तक पीछे आती रही। शीशे में चौखट पर खड़े नैना के पिता दिखते रहे—एक हाथ अब भी फ्रेम पर।</p>\n<p>ऊपर आसमान बिल्कुल साफ़ था—इतना उदासीन कि जैसे नीचे उस घर में अभी-अभी किसी की पूरी आने वाली ज़िंदगी के बारे में कोई फ़ैसला हुआ ही न हो।</p>\n<p>आशीर्वाद नहीं मिला था।</p>\n<p>बस इंकार की वह शक्ल मिली थी जिसमें दरवाज़ा बंद नहीं होता, पर खुलता भी नहीं।</p>"}, {"chapter": 30, "title": "अध्याय 28 — आपने ही मुझे आवाज़ दी थी", "content": "<h1>अध्याय 28 — आपने ही मुझे आवाज़ दी थी</h1>\n<p>बरामदा बिल्कुल वैसा ही था।</p>\n<p>वही कुर्सी, उतरती हुई शाम, सामने धीरे-धीरे शांत होता बगीचा—जैसे पिछली बातचीत के बाद समय यहाँ से आगे बढ़ा ही न हो। फ़र्क़ बस इतना था कि रास्ते के किनारे खिले गेंदे के फूलों की खुशबू आज कुछ हल्की, कुछ ज़्यादा कड़वी लग रही थी और दूर किसी मंदिर की घंटी हवा में बजते हुए शाम को धीरे-धीरे घंटों में बाँट रही थी।</p>\n<p>नैना ने इस बार बैठने के लिए नहीं पूछा।</p>\n<p>सीधे सामने आकर बैठ गई।</p>\n<p>“वह आपसे मिलने आया था।”</p>\n<p>वह पूछ नहीं रही थी, बता रही थी।</p>\n<p>“हाँ।”</p>\n<p>“और आपने मना कर दिया।”</p>\n<p>पिता ने वह अख़बार नीचे रख दिया जिसे वह काफी देर से पढ़ने का सिर्फ दिखावा कर रहे थे।</p>\n<p>“हाँ। कर दिया।”</p>\n<p>नैना की पीठ सीधी थी। गोद में रखे दोनों हाथ चुप थे, मगर उँगलियाँ इतनी कसकर गुँथी थीं कि पोरें सफ़ेद पड़ गई थीं।</p>\n<p>“मैं वजह आपसे सुनना चाहती हूँ। माँ से नहीं। किसी और के ज़रिए नहीं। आप मेरी तरफ देखकर अपने शब्दों में बताइए कि आपने मना क्यों किया।”</p>\n<p>पिता कुछ देर उसे देखते रहे। चेहरे पर हल्की-सी नरमी आई।</p>\n<p>उन्होंने नैना के चेहरे पर ज़िद ढूँढी। वह नहीं मिली।</p>\n<p>उससे कहीं ज़्यादा ठोस कोई चीज़ मिली।</p>\n<p>“जो तुम्हारी माँ से कहा, वही विक्रम से भी कहा। मैंने देखा है इस ज़िंदगी ने तुम्हारी माँ से क्या लिया। वही तुम्हारे साथ होते नहीं देख सकता।”</p>\n<p>“ये आपकी वजह है। मैं जानना चाहती हूँ कि क्या ये वजह मेरे लिए भी सही है।”</p>\n<p>“सही-ग़लत की बात नहीं है, नैना। मैं निष्पक्ष फ़ैसला सुनाने नहीं बैठा। मैं तुम्हारा पिता हूँ। तुम्हें बचाने की कोशिश कर रहा हूँ।”</p>\n<p>उनकी आवाज़ में झुंझलाहट की हल्की धार आई, मगर नैना से ज़्यादा उस स्थिति के लिए जिसमें वह ख़ुद फँस चुके थे।</p>\n<p>“तुम्हें लगता है मुझे इसमें खुशी मिल रही है? तुम्हें सामने बैठकर मुझे ऐसे देखते हुए कि जैसे मैंने तुमसे कुछ छीन लिया हो?”</p>\n<p>उन्होंने साँस छोड़ी।</p>\n<p>“मुझे पता है मैं क्या छीन रहा हूँ। क्योंकि उसके दूसरे रास्ते को बीस साल से ऊपर जी चुका हूँ।”</p>\n<p>“तो मुझे भी जीने दीजिए।”</p>\n<p>जवाब बिना रुके आया।</p>\n<p>“मुझे भी आँखें खोलकर वही चुनाव करने दीजिए, जो आपने और माँ ने किया था।”</p>\n<p>“तुमने अभी वह ज़िंदगी जी ही नहीं है। तुम्हें पता नहीं तुम क्या माँग रही हो।”</p>\n<p>“आपको भी नहीं पता था, बाबा, जब आपने माँ से शादी की थी।”</p>\n<p>नैना थोड़ा आगे झुकी।</p>\n<p>गले में कसाव था, मगर आवाज़ अब भी सधी हुई।</p>\n<p>“किसी को पहले से नहीं पता होता कि वह क्या चुन रहा है। जब तक ज़िंदगी के भीतर पहुँच नहीं जाते, उसके पूरे मतलब का किसे पता होता है? किसी इंसान को चुनने का मतलब ही यही है।”</p>\n<p>वह रुकी नहीं।</p>\n<p>“मैंने उसे लोगों के बीच बैठकर मेरे बारे में पूछे गए हर सवाल का जवाब देते देखा है। मैंने उसे अपने दोस्त रेड्डी की शहादत का दुख उठाते देखा और फिर भी अगली शाम मेरे पास आते देखा, क्योंकि वह अपना दुख मेरा बोझ नहीं बनाना चाहता था।”</p>\n<p>“मैंने उसे पंद्रह दिन की उस ख़ामोशी के बाद हफ्तों ख़ुद को दोष देते देखा है। जितनी बार मैंने नहीं कहा, उससे ज़्यादा बार उसने माफ़ी माँगी।”</p>\n<p>नैना ने सीधे पिता की आँखों में देखा।</p>\n<p>“मैं जानती हूँ किस इंसान को चुन रही हूँ, बाबा। मुझे उससे बचाने की ज़रूरत नहीं कि कहीं आगे जाकर मुझे पता चले वह कैसा है।”</p>\n<p>एक लंबी ख़ामोशी रही।</p>\n<p>पिता की आँखों के पीछे कोई उधेड़बुन चल रही थी।</p>\n<p>ज़िद नहीं।</p>\n<p>दुख।</p>\n<p>“अपनी माँ जैसी लग रही हो,” उन्होंने आख़िर बहुत धीमे कहा। “वह भी मुझसे ऐसे ही बहस करती थी। वही ज़िद। सिर्फ इसलिए मुझे आख़िरी बात नहीं कहने देती थी कि मैं उम्र में बड़ा हूँ और मुझे लगता है मैं ज़्यादा जानता हूँ।”</p>\n<p>“शायद माँ ठीक करती थीं।”</p>\n<p>उनके चेहरे पर बहुत हल्की, थकी हुई-सी मुस्कान आई और चली गई।</p>\n<p>“शायद।”</p>\n<p>“और आपने ही मुझे सिखाया था कि सवाल पूछना बदतमीज़ी नहीं होती,” नैना ने कहा। “आपने ही मुझे आवाज़ दी थी, बाबा। आज उसे वापस मत माँगिए।”</p>\n<p>पिता की नज़र एक पल को नीचे चली गई।</p>\n<p>उन्होंने हथेली चेहरे पर फेर ली। शाम की उतरती रोशनी में वह अचानक नैना को अपनी उम्र से भी कुछ बड़े लगे।</p>\n<p>“लेकिन मुझे चाहने में उसका सही होना उन सालों को उसके लिए आसान नहीं बना पाया, नैना।”</p>\n<p>नैना चुप रही।</p>\n<p>फिर पूछा—</p>\n<p>“वह खुश थीं, बाबा?”</p>\n<p>पिता की नज़र उस पर ठहर गई।</p>\n<p>“इतना सब होने के बाद भी… क्या उन्हें खुशी थी कि उन्होंने आपको चुना?”</p>\n<p>जवाब देर से आया।</p>\n<p>“मुझे लगता है, हाँ।”</p>\n<p>उनकी आवाज़ भर्रा गई थी।</p>\n<p>“कभी सीधे पूछने की हिम्मत नहीं हुई। डर था कि कहीं जवाब ऐसा न हो जिसे सुनकर मैं बाकी ज़िंदगी ख़ुद के साथ न रह पाऊँ।”</p>\n<p>नैना की आँखें नम होने लगीं, मगर उसने पलकें नहीं झुकाईं।</p>\n<p>“तो मुझे भी वही सवाल ख़ुद से पूछने का मौका दीजिए। इतने साल बाद।”</p>\n<p>उसकी आवाज़ अब धीमी थी।</p>\n<p>“आज ही मेरे लिए उसका जवाब मत तय कर दीजिए सिर्फ इसलिए कि आपको डर है मेरा जवाब मुझे कितनी कीमत चुकवाएगा। कीमत मेरी है, बाबा। मुझे उसे तौलने दीजिए—जैसे माँ ने अपनी कीमत ख़ुद तौली थी।”</p>\n<p>शाम उनके चारों ओर और गहरी हो गई।</p>\n<p>किसी ने उठकर बत्ती नहीं जलाई।</p>\n<p>बगीचे में गेंदे पहले अपना रंग खोते गए, फिर सिर्फ आकार रह गए और आख़िर अँधेरे में वे भी घुलने लगे। कई घर छोड़कर कोई कुत्ता भौंका; शांत होती हवा में आवाज़ साफ़ यहाँ तक आई।</p>\n<p>पिता काफी देर कुछ नहीं बोले।</p>\n<p>फिर कहा—</p>\n<p>“मैं तुम्हारी बात सुन रहा हूँ।”</p>\n<p>नैना ने नज़र नहीं हटाई।</p>\n<p>“इतना ज़रूर जान लो। तुम्हारा एक भी शब्द अनसुना नहीं जा रहा। आख़िर मैं जो भी फ़ैसला करूँ।”</p>\n<p>“लेकिन जवाब अब भी वही है।”</p>\n<p>उन्होंने तुरंत जवाब नहीं दिया।</p>\n<p>“मुझे नहीं पता।”</p>\n<p>नैना ने उन्हें देखा।</p>\n<p>पूरी बातचीत में पहली बार उन्होंने ये शब्द ऐसे कहे थे जिनके पीछे कोई बचाव नहीं था।</p>\n<p>“मुझे थोड़ा वक्त दो, नैना। हमेशा के लिए नहीं। बस इतना कि आज तुमने जो कहा है, उसे ठीक से अपने भीतर रखकर देख सकूँ। अपने किसी पुराने घाव से तुरंत जवाब नहीं देना चाहता।”</p>\n<p>“और वह दूसरी बात?” नैना ने पूछा। “जो आपने उधर शुरू की है।”</p>\n<p>“जब तक मैं सोच न लूँ, वह आगे नहीं बढ़ेगी।”</p>\n<p>बस इतना सुनते ही गुँथी हुई उँगलियों की पोरें ढीली पड़ गईं। जिस संयम को वह पूरे समय दोनों हाथों से पकड़े बैठी थी, वह उसकी पकड़ से निकल गया।</p>\n<p>आँसू चुपचाप गिरने लगे।</p>\n<p>“इधर आ।”</p>\n<p>पिता की आवाज़ पहली बार उस शाम पूरी तरह पिता की थी।</p>\n<p>उन्होंने पास पड़ी चारपाई पर जगह थपथपाई।</p>\n<p>नैना बस एक पल झिझकी, फिर उठकर उनके पास बैठ गई।</p>\n<p>उन्होंने बाँह उसके कंधों के चारों ओर रखी और उसे अपने पास खींच लिया—वैसे ही जैसे बचपन में खींचते थे, जब वह इतनी छोटी थी कि उनके एक तरफ पूरी की पूरी समा जाती थी।</p>\n<p>दूसरा हाथ उसके सिर पर आया।</p>\n<p>उँगलियाँ धीरे-धीरे उसके बाल पीछे करती रहीं।</p>\n<p>वही पुराना ढंग।</p>\n<p>बचपन में किसी बुरे सपने से रोते हुए उठ जाने पर भी वह उसे इसी तरह शांत करते थे।</p>\n<p>नैना कुछ देर उनके कंधे से लगी रही।</p>\n<p>फिर पूछा—</p>\n<p>“आप सच में सोचेंगे?”</p>\n<p>“हाँ।”</p>\n<p>“सिर्फ मुझे चुप कराने के लिए नहीं कह रहे?”</p>\n<p>“नहीं।”</p>\n<p>उनका हाथ उसके बालों में चलता रहा।</p>\n<p>“मैं वादा करता हूँ, तुम्हारी कही हर बात पर सोचूँगा।”</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>बरामदे की ख़ामोशी में पिता की धड़कन उसे उतनी साफ़ सुनाई दे रही थी जितनी बहुत सालों से नहीं सुनी थी।</p>\n<p>यह वही सीना था जिस पर बचपन में वह उनकी जीप का इंतज़ार करते-करते सो जाया करती थी।</p>\n<p>वही पिता।</p>\n<p>वही बेटी।</p>\n<p>बस अब वह जिस चीज़ का इंतज़ार कर रही थी, उसकी आवाज़ किसी सड़क से नहीं आने वाली थी।</p>\n<p>फिर जैसे उसे अचानक कोई डर छू गया हो, उसने बहुत धीमे पूछा—</p>\n<p>“आप मुझसे नाराज़ तो नहीं हैं?”</p>\n<p>पिता का चेहरा उसी पल बदल गया।</p>\n<p>“नाराज़?”</p>\n<p>उन्होंने उसका चेहरा दोनों हाथों में लिया।</p>\n<p>“तुम्हें सच में लगता है मैं तुमसे नाराज़ हूँ?”</p>\n<p>“पता नहीं।”</p>\n<p>“नैना, मैं तुम्हारे साथ बेरहम नहीं हो रहा।”</p>\n<p>उनकी आवाज़ भी अब पहले जैसी सपाट नहीं थी।</p>\n<p>“आज जो भी हूँ, बेरहम नहीं हूँ। मैं तुम्हारे लिए डरा हुआ हूँ। और कई बार पिता का डर बाहर से बेरहमी जैसा दिखता है, जबकि भीतर उसका दिल उतना ही टूट रहा होता है जितना बेटी का।”</p>\n<p>नैना ने कोई जवाब नहीं दिया।</p>\n<p>“अभी प्यार जैसा नहीं लग रहा, बाबा।”</p>\n<p>“मुझे पता है।”</p>\n<p>उन्होंने उसके सिर को अपने सीने से लगा लिया।</p>\n<p>“प्यार हमेशा वैसा महसूस नहीं होता जैसा हम चाहते हैं। खासकर उस बाप का प्यार जिसने इतना कुछ देखा हो कि भरोसा करना भी डर के बिना न आता हो।”</p>\n<p>उन्होंने उसके सिर पर अपने होंठ रखे—वैसे ही जैसे बचपन में न जाने कितनी बार किया था।</p>\n<p>“तुम मेरी ज़िंदगी की सबसे अच्छी चीज़ हो, नैना।”</p>\n<p>“ये बहस, ये डर… यहाँ तक कि उस लड़के को दिया मेरा ‘ना’ भी—सब उसी जगह से आया है जहाँ मैं तुमसे इतना प्यार करता हूँ कि उसे ठीक से बोलना भी नहीं आता।”</p>\n<p>उन्होंने उसे और करीब कर लिया।</p>\n<p>“गुस्सा रहना मुझसे। लेकिन ये बात मत भूलना।”</p>\n<p>नैना अब सचमुच रो पड़ी।</p>\n<p>पिता ने कुछ और नहीं कहा।</p>\n<p>बस उसे थामे रहे और हाथ उसी पुरानी लय में उसके बालों पर चलता रहा, जब तक उसकी साँसें धीरे-धीरे फिर बराबर नहीं हो गईं।</p>\n<p>उस बरामदे में आख़िर ऐसी ख़ामोशी उतर आई जिसमें किसी एक को सही साबित करने की ज़रूरत नहीं थी।</p>\n<p>वह ख़ामोशी पिता के डर को भी जगह दे रही थी।</p>\n<p>और बेटी के दुख को भी।</p>\n<p>यह ‘हाँ’ नहीं थी।</p>\n<p>मगर उस सपाट इंकार से ज़्यादा ज़रूर थी जिसे कुछ दिन पहले विक्रम इसी घर के दरवाज़े से अपने साथ बाहर ले गया था।</p>\n<p>दूर मंदिर की घंटी कब की चुप हो चुकी थी।</p>\n<p>और उस पूरी शाम के दर्द के नीचे नैना कम-से-कम एक बात पकड़कर बैठी रही—</p>\n<p>उसके पिता का फ़ैसला जो भी हो, उसकी जड़ में मोहब्बत ही होगी।</p>"}, {"chapter": 31, "title": "अध्याय 29 — आख़िरी जवाब", "content": "<h1>अध्याय 29 — आख़िरी जवाब</h1>\n<p>उन्होंने एक हफ्ता लिया।</p>\n<p>और उस पूरे हफ्ते नैना ने अपने पिता को ज़िंदगी में पहली बार इतनी गौर से देखा।</p>\n<p>सुबह की चाय पर वह पहले से कुछ देर ज़्यादा बैठे रहते—चाय ठंडी हो जाती, फिर भी हाथ कप पर रखे रहते। कभी अख़बार का एक ही पन्ना बहुत देर तक खुला रहता। एक-दो बार ऐसा भी हुआ कि उन्होंने नैना की तरफ देखा, जैसे कुछ कहने वाले हों, फिर नज़र फेर ली।</p>\n<p>नैना ने कुछ नहीं पूछा।</p>\n<p>पिछली शाम उन्होंने उससे वक्त माँगा था।</p>\n<p>इस बार वह उन्हें वह वक्त देना चाहती थी।</p>\n<p>रविवार की शाम उन्होंने ख़ुद उसे बरामदे में बुलाया।</p>\n<p>वही जगह।</p>\n<p>वही कुर्सी।</p>\n<p>ऊपर घूमते पंखे से हर चक्कर के साथ आती बहुत हल्की-सी टिक की आवाज़, ढलती रोशनी और मौसम के पहले मच्छर, जिन्होंने शाम की हवा में अपनी मौजूदगी दर्ज करानी शुरू कर दी थी।</p>\n<p>नैना उनके सामने बैठी।</p>\n<p>और उनके पहला शब्द बोलने से पहले ही जान गई—</p>\n<p>एक हफ्ते ने जवाब को नरम ज़रूर किया था।</p>\n<p>बदला नहीं था।</p>\n<p>“तुमने उस दिन जो कुछ कहा था, मैंने सब सोचा है।”</p>\n<p>नैना चुप रही।</p>\n<p>“एक भी बात यूँ ही नहीं छोड़ी। ये तुम जान लो।”</p>\n<p>नैना ने कहा—</p>\n<p>“लेकिन…”</p>\n<p>पिता ने उसकी आँखों में देखा।</p>\n<p>“लेकिन मेरा जवाब अब भी ‘ना’ है, नैना।”</p>\n<p>इस बार शब्द में पिछली कठोरता नहीं थी।</p>\n<p>सिर्फ थकान थी।</p>\n<p>ऐसी थकान जो किसी दूसरे को हराने के बाद नहीं, ख़ुद से कई दिन लड़ने के बाद आती है।</p>\n<p>“इसलिए नहीं कि मुझे उस पर भरोसा नहीं। इसलिए भी नहीं कि मुझे तुम पर भरोसा नहीं है।”</p>\n<p>उन्होंने साँस ली।</p>\n<p>“लेकिन जिस डर के बारे में तुम मुझसे कह रही हो कि उसे छोड़ दूँ, उसे मैंने बीस साल से ऊपर जिया है। तुम्हारे बहुत अच्छे तर्क भी एक हफ्ते में उन सालों को मेरे भीतर से निकाल नहीं सकते।”</p>\n<p>उनकी आवाज़ और धीमी हुई।</p>\n<p>“काश निकाल पाते।”</p>\n<p>नैना की उँगलियाँ अपनी गोद में आपस में बँधी रहीं।</p>\n<p>“मैंने कोशिश की है इस पूरे हफ्ते। सच में की है।”</p>\n<p>“नहीं कर पाया।”</p>\n<p>नैना बिल्कुल स्थिर बैठी रही।</p>\n<p>उसका एक हिस्सा यह जवाब पहले ही जानता था।</p>\n<p>दूसरा हिस्सा अब भी उस एक शब्द की उम्मीद कर रहा था जिसे सुनने के लिए वह महाकाल तक गई थी।</p>\n<p>पिता ने आगे कहा—</p>\n<p>“जिस परिवार का मैंने ज़िक्र किया था, उनसे इस हफ्ते फिर बात हुई है।”</p>\n<p>नैना की आँखें उनकी ओर उठीं।</p>\n<p>“अच्छे लोग हैं। लड़का भी ठीक है। समझदार है, स्थिर नौकरी है। हर शाम घर लौटता है।”</p>\n<p>उन्होंने जैसे ख़ुद महसूस किया कि ये बातें इस वक्त बेटी के लिए कितनी बेमानी हैं।</p>\n<p>“मुझे पता है अभी इनमें से कोई बात तुम्हारे लिए मायने नहीं रखती।”</p>\n<p>“फिर?”</p>\n<p>“मैं चाहता हूँ तुम भरोसा करो कि कभी रखेगी।”</p>\n<p>नैना का चेहरा नहीं बदला।</p>\n<p>“अभी तुम प्यार में हो। मैं उस प्यार को छोटा नहीं कह रहा। लेकिन एक दिन यही तुम चालीस साल की शादी के भीतर खड़ी होगी—हर दिन, हर सुबह, हर शाम उसी ज़िंदगी को जीते हुए।”</p>\n<p>“मैं तुमसे कह रहा हूँ कि शायद उस नैना को आज की नैना से कुछ अलग चीज़ों की ज़रूरत होगी।”</p>\n<p>नैना ने बहुत देर बाद कहा—</p>\n<p>“आप मुझसे उस नैना पर भरोसा करने को कह रहे हैं जो अभी बनी ही नहीं… उस नैना से ज़्यादा जो आपके सामने बैठी है।”</p>\n<p>पिता की आँखों में दर्द उतर आया।</p>\n<p>“हाँ।”</p>\n<p>उन्होंने बात से बचने की कोशिश नहीं की।</p>\n<p>“और मुझे पता है ये कितना ग़लत सुनाई देता है।”</p>\n<p>उन्होंने आगे बढ़कर उसका हाथ अपने हाथ में ले लिया।</p>\n<p>“मुझे पता है मेरे फ़ैसला कर देने से तुम विक्रम से प्यार करना बंद नहीं कर दोगी। दिल फौजी नहीं होता, नैना। बाप चाहे जितना चाहे, उसे हुक्म देकर सावधान की मुद्रा में खड़ा नहीं किया जा सकता।”</p>\n<p>नैना की आँखें भर आईं।</p>\n<p>“तो फिर आप मुझसे क्या चाहते हैं?”</p>\n<p>“उस रिश्ते को होने दो।”</p>\n<p>शब्द बहुत धीरे आए।</p>\n<p>“और वक्त को अपना काम करने दो। कुछ चीज़ें वक्त के साथ हल्की होती हैं। कुछ साफ़ होने लगती हैं। मैंने लोगों के साथ ऐसा होते देखा है।”</p>\n<p>“और अगर मेरे साथ नहीं हुआ तो?”</p>\n<p>पिता चुप हो गए।</p>\n<p>नैना का हाथ अब भी उनके हाथ में था।</p>\n<p>“अगर चालीस साल बाद भी मुझे उसी ज़िंदगी की याद आती रही जिसे मुझे चुनने ही नहीं दिया गया?”</p>\n<p>उनके पास जवाब नहीं था।</p>\n<p>जबड़ा कस गया।</p>\n<p>बरामदे की मद्धम रोशनी में उनकी आँखों में भी नमी चमक रही थी।</p>\n<p>बहुत देर तक दोनों चुप रहे।</p>\n<p>फिर पिता बोले—</p>\n<p>“मुझे माफ़ करना।”</p>\n<p>आवाज़ पहली बार टूट गई।</p>\n<p>नैना ने उनकी ओर देखा।</p>\n<p>“मुझे पता है माफ़ी मेरे फ़ैसले को बदलती नहीं। फिर भी चाहता हूँ तुम इसे सुनो।”</p>\n<p>उन्होंने उसका हाथ और कसकर पकड़ लिया।</p>\n<p>“जो दर्द इस फ़ैसले से तुम्हें होगा, उसके लिए मुझे अफसोस है। लेकिन जिस दर्द को मैं तुमसे दूर रखने की कोशिश कर रहा हूँ, उसके लिए मुझे अफसोस नहीं है।”</p>\n<p>“क्योंकि उस दर्द को मैं तुमसे ज़्यादा जानता हूँ।”</p>\n<p>शायद पिता होने की सबसे कठिन जगह यही थी—जहाँ इंसान अपने बच्चे का दिल तोड़ते हुए भी ख़ुद को समझाता रहता है कि वह उसी दिल की हिफ़ाज़त कर रहा है।</p>\n<p>नैना उठी।</p>\n<p>पिता को लगा, वह चली जाएगी।</p>\n<p>लेकिन वह उनके सामने आकर नीचे बैठ गई, दोनों हाथ उनके घुटनों पर रख दिए।</p>\n<p>इस घर में बेटियाँ पिता के पैर छूकर अपनी बात नहीं कहती थीं। मगर यह मुद्रा उसके बहुत करीब थी—इतनी नीचे कि उसमें बहस से ज़्यादा विनती थी।</p>\n<p>“बाबा… मेरी तरफ देखिए।”</p>\n<p>उसकी आवाज़ काँप रही थी।</p>\n<p>मगर आँखें ऊपर थीं।</p>\n<p>“मैं आपसे कैप्टन राठौड़ की होने वाली पत्नी बनकर नहीं माँग रही।”</p>\n<p>पिता की उँगलियाँ कुर्सी के हत्थे पर कस गईं।</p>\n<p>“मैं आपकी वही बेटी बनकर माँग रही हूँ जो आपकी जीप का इंतज़ार करते-करते आपकी छाती पर सो जाती थी।”</p>\n<p>उनके चेहरे की कठोरता टूट गई।</p>\n<p>“आपने मुझसे कहा था—एक बार नहीं, कई बार—कि मुझे कभी ऐसी जगह खड़ा नहीं करेंगे जहाँ मुझे आपसे प्यार करने और अपनी ज़िंदगी जीने में से किसी एक को चुनना पड़े।”</p>\n<p>नैना की आँखों से आँसू उतरने लगे।</p>\n<p>“आपको शायद याद भी नहीं होगा। मैं शायद सात साल की थी।”</p>\n<p>उसने साँस खींची।</p>\n<p>“मुझे याद है, बाबा।”</p>\n<p>पिता कुछ नहीं बोले।</p>\n<p>“आपने मुझे लाउड बनाया।”</p>\n<p>उस एक शब्द में उसके बचपन से लेकर आज तक की पूरी नैना आकर खड़ी हो गई।</p>\n<p>“आपने मुझे सिखाया कि जो चाहती हूँ उसे बोलूँ। अपनी बात निगलूँ नहीं। माँ की तरह हर बात अपने भीतर रखकर छोटी न होती जाऊँ।”</p>\n<p>उसके हाथ उनके घुटनों पर और कस गए।</p>\n<p>“मैं वही कर रही हूँ आज।”</p>\n<p>आवाज़ टूटने लगी।</p>\n<p>“ठीक वही, जो आपने मुझे करना सिखाया।”</p>\n<p>उसने आँसू पोंछे, मगर नए आँसू उनकी जगह आ गए।</p>\n<p>“और आज आप ही मुझसे कह रहे हैं कि इसे निगल जाऊँ।”</p>\n<p>पिता की आँखें उससे हट नहीं सकीं।</p>\n<p>“मुझे समझ नहीं आता, बाबा… ये दोनों बातें एक ही इंसान के भीतर कैसे सही हो सकती हैं।”</p>\n<p>“नैना…”</p>\n<p>“बाबा, प्लीज़।”</p>\n<p>‘प्लीज़’ शब्द उसके गले में आधा ही निकला।</p>\n<p>“मैं कोई केस नहीं लड़ रही आपसे।”</p>\n<p>वह रो रही थी, फिर भी शब्द रोकना नहीं चाहती थी।</p>\n<p>“मैं आपकी बेटी हूँ। मैंने आपसे ज़िंदगी में कभी कुछ इस तरह नहीं माँगा।”</p>\n<p>उसने चेहरा पोंछा।</p>\n<p>“और मैं ये भी नहीं कह रही कि अपनी पूरी ज़िंदगी भूल जाइए। जो जानते हैं, उसे भूलिए मत। बस विक्रम को भी उसी ईमानदारी से देखिए।”</p>\n<p>वह रुकी।</p>\n<p>“वह शादी के बाद आर्मी छोड़ने को तैयार है।”</p>\n<p>पिता की आँखें हल्की-सी झुकीं।</p>\n<p>“आप जानते हैं इसका क्या मतलब है। वह सिर्फ नौकरी नहीं छोड़ रहा होगा। वह अपनी पूरी वयस्क ज़िंदगी की पहचान छोड़ने को तैयार है।”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“मैं आँखें बंद करके उसके पीछे नहीं जा रही। महीनों से उसे देखा है। दुख में। अपराधबोध में। ग़लती करते हुए भी… और ग़लती समझकर ख़ुद को ठीक करते हुए भी।”</p>\n<p>फिर उसने वही बात उनके सामने रखी जिससे वह ख़ुद भी बच नहीं सकते थे।</p>\n<p>“आपने पूरी ज़िंदगी इंसान को कुछ सेकंड में पढ़ना सीखा है।”</p>\n<p>पिता स्थिर हो गए।</p>\n<p>“जब वह उस दिन आपके सामने बैठा था, आपने क्या देखा?”</p>\n<p>“कोई लापरवाह लड़का?”</p>\n<p>एक पल।</p>\n<p>“या ऐसा इंसान जिसने आपको वह सच भी बताया जो उसके ख़िलाफ़ जाता था?”</p>\n<p>पिता ने नज़र नहीं हटाई।</p>\n<p>“मुझे पता है तुम आँखें बंद करके नहीं चल रही, बेटा।”</p>\n<p>“यही तो इसे इतना मुश्किल बनाता है।”</p>\n<p>उन्होंने आँखें बंद कर लीं।</p>\n<p>“तुम कोई छोटी चीज़ माँग रही होती तो बिना सोचे दे देता।”</p>\n<p>जब आँखें खुलीं तो उनमें पिता का डर पूरी तरह उघड़ा हुआ था।</p>\n<p>“तुम मुझसे कह रही हो कि मैं तुम्हें जोखिम में डाल दूँ।”</p>\n<p>नैना ने बिना झिझके कहा—</p>\n<p>“तो डाल दीजिए।”</p>\n<p>उसकी आवाज़ में न काँप थी, न झिझक।</p>\n<p>“जोखिम मेरा है।”</p>\n<p>उसने अपने आँसू पोंछे।</p>\n<p>“मुझे लेने दीजिए।”</p>\n<p>“मैं वह उन्नीस साल की लड़की नहीं हूँ जो माँ थीं, जब उनकी शादी हुई थी। मेरे सामने आपकी पूरी ज़िंदगी है। उनकी पूरी ज़िंदगी है। मुझे पहले से मालूम है इस रास्ते पर क्या हो सकता है।”</p>\n<p>उसने कहा—</p>\n<p>“फिर भी मैं उसे चुन रही हूँ।”</p>\n<p>पिता चुप रहे। जब बोले तो आवाज़ और नीचे उतर आई थी—उसमें अब लगभग विनती थी।</p>\n<p>“तुम सच में जानती हो, नैना, विक्रम कौन है? मैं जानता हूँ—उसकी फाइल से, उन लोगों से जो उसके साथ सर्विस कर चुके हैं।”</p>\n<p>नैना चुप रही।</p>\n<p>“वह कोई ऐसा फौजी नहीं जो दफ़्तर में बैठकर शांत पोस्टिंग के दिन गिन रहा हो। वह पैरा एसएफ़ है। साल-दर-साल एक्टिव ऑपरेशन। हमेशा गोली के आसपास—और हमेशा अपनी सरहद के भीतर भी नहीं। इससे ज़्यादा साफ़ मैं नहीं कहूँगा। इस घर में तो बिल्कुल नहीं।”</p>\n<p>“ऐसे जवानों को आम मायनों में घर-परिवार नहीं मिलता। छुट्टियाँ मिलती हैं—दो ऑपरेशनों के बीच छीनी हुई—और एक पत्नी, जो उन खाली जगहों के बीच जीना सीख लेती है।”</p>\n<p>“ज़्यादातर लोग एसएससी में आसान रास्ता लेते हैं। उसने जानबूझकर मुश्किल रास्ता चुना। एक बार नहीं, दो बार।”</p>\n<p>“और उसके रेज़िग्नेशन की बात, नैना—वह सच्चे मन से कही गई है। फिर भी तुम इंडियन आर्मी को नहीं जानती। ऐसे अफसर को सेना यूँ जाने नहीं देती। आज शॉर्ट सर्विस कमीशन है, कल परमानेंट कर देगी। तब वह चाहकर भी वर्दी नहीं उतार पाएगा—वह सेना के लिए एसेट है, और सेना अपना एसेट कभी नहीं छोड़ती।”</p>\n<p>नैना के हाथ अब भी उनके घुटनों पर थे। उसने कुछ नहीं कहा।</p>\n<p>“ऐसे लोग किसी पत्नी, किसी बच्चे या किसी ससुर के डर के लिए चढ़ना नहीं छोड़ते, नैना। और वही आगे बढ़ना परिवार से वह सब छीन लेता है, जिसे खोने का सौदा उसने कभी किया ही नहीं था।”</p>\n<p>“मैंने उसके जैसे दर्जनों नौजवान अफसर देखे हैं, और हर एक को साल-दर-साल वही चुपचाप फ़ैसला करते देखा है—तब भी, जब दीवार पर टँगी उनकी शादी की तस्वीरें बहुत पहले फीकी पड़ चुकी थीं।”</p>\n<p>फिर उन्होंने बेटी की आँखों में देखा।</p>\n<p>“और यह जोखिम कभी सिर्फ तुम्हारा था ही नहीं, नैना। उस दिन से नहीं, जिस दिन मैंने तुम्हें पहली बार गोद में लिया था।”</p>\n<p>उनकी हमेशा नपी-तुली रहने वाली आवाज़ अब किसी ऐसी चीज़ में बदल गई थी, जो नैना ने उनसे पहले कभी नहीं सुनी थी।</p>\n<p>“मैंने फ़ैसला कर लिया है। यह नहीं कहूँगा कि आसान था। यह भी नहीं कहूँगा कि मुझे इस पर पूरा यकीन है। लेकिन फ़ैसला यही है।”</p>\n<p>पिता का चेहरा थक गया।</p>\n<p>जैसे एक हफ्ते से भीतर चल रही लड़ाई अब शब्दों में नहीं, शरीर पर उतर आई हो।</p>\n<p>लेकिन इस बार उन्होंने “वक्त दो” नहीं कहा।</p>\n<p>वक्त वह ले चुके थे।</p>\n<p>और उसका जवाब नैना के सामने था।</p>\n<p>नैना ने यह भी समझ लिया।</p>\n<p>कुछ फ़ैसले इंसान से जीतकर नहीं लिए जा सकते।</p>\n<p>और कुछ हारें ऐसी होती हैं जिनमें सामने वाला दुश्मन भी नहीं होता।</p>\n<p>सिर्फ कोई अपना होता है—</p>\n<p>जो आपको खोना नहीं चाहता,</p>\n<p>और उसी कोशिश में आपसे वह चीज़ छीन लेता है जिसके बिना आप ख़ुद को पूरा नहीं देख पाते।</p>\n<p>नैना धीरे-धीरे उठी।</p>\n<p>पिता ने उसका हाथ पकड़ लिया।</p>\n<p>“मुझसे नफ़रत मत करना।”</p>\n<p>वह वहीं रुक गई।</p>\n<p>इतने वर्षों में उसने अपने पिता की आवाज़ में ऐसी असहायता कभी नहीं सुनी थी।</p>\n<p>उसने उनकी तरफ देखा।</p>\n<p>“नहीं कर सकती।”</p>\n<p>बस इतना।</p>\n<p>“लेकिन अभी समझ भी नहीं सकती।”</p>\n<p>उन्होंने सिर झुका लिया।</p>\n<p>नैना ने अपना हाथ उनके हाथ से नहीं छुड़ाया।</p>\n<p>कुछ देर दोनों वैसे ही रहे।</p>\n<p>फिर पिता ने उसे अपने पास खींच लिया।</p>\n<p>इस बार वह भी नहीं रुकी।</p>\n<p>उनके कंधे से लगते ही फिर रो पड़ी।</p>\n<p>पिता की हथेली उसके सिर पर थी।</p>\n<p>लेकिन आज वह पुरानी हथेली किसी बुरे सपने से जगाकर उसे यह नहीं कह सकती थी कि सब ठीक है।</p>\n<p>क्योंकि इस बार जिस चीज़ से बेटी डर रही थी—</p>\n<p>वह सपना नहीं था।</p>\n<p>और उसे सच करने वाला इंसान वही था जिसकी छाती से लगकर वह रो रही थी।</p>\n<p>बरामदे में रात उतरती रही।</p>\n<p>पंखा ऊपर अपनी धीमी टिक के साथ घूमता रहा।</p>\n<p>और पिता-बेटी एक-दूसरे को थामे रहे—इतने करीब कि एक-दूसरे की साँस सुन सकते थे, और उस एक फ़ैसले में इतने दूर कि कोई शब्द बीच की जगह भर नहीं सकता था।</p>\n<p>कुछ देर बाद नैना ने धीरे से कहा—</p>\n<p>“मुझे उसे बताना होगा।”</p>\n<p>पिता को पूछने की ज़रूरत नहीं थी कि किसे।</p>\n<p>“जानता हूँ।”</p>\n<p>“आसान नहीं होगा।”</p>\n<p>“इस पूरे मामले में कुछ भी आसान नहीं रहा, बेटा। वह हिस्सा भी नहीं होगा।”</p>\n<p>उन्होंने उसका हाथ एक बार दबाया, फिर छोड़ दिया।</p>\n<p>“जो भी कहना, जैसे भी कहना—मुझे भरोसा है कि तुम उसे उसी गरिमा से कहोगी जिससे आज की पूरी बातचीत में कहती रही हो। जिस बेटी का दिल मैंने अभी तोड़ा है, उस पर यह भरोसा करना मेरे लिए कम बात नहीं।”</p>\n<p>नैना उठी। पैर उसके नीचे ठीक से टिक नहीं रहे थे। वह बिना कुछ कहे घर के भीतर चली गई।</p>\n<p>जवाब आख़िर मिल चुका था।</p>\n<p>और कभी-कभी आख़िरी जवाब का सबसे बड़ा दुख यही होता है—</p>\n<p>उसके बाद उम्मीद को रखने के लिए कोई अगला सवाल नहीं बचता।</p>"}, {"chapter": 32, "title": "अध्याय 30 — जो उसे कहना था", "content": "<h1>अध्याय 30 — जो उसे कहना था</h1>\n<p>नैना ने विक्रम को गुलमोहर वाले पार्क में बुलाया।</p>\n<p>उसी बेंच पर।</p>\n<p>दोनों में से किसी ने नहीं पूछा कि आज के लिए उसने यही जगह क्यों चुनी थी।</p>\n<p>शायद कुछ जगहें रिश्तों में इतनी भीतर उतर जाती हैं कि उनके पास लौटने की वजह बतानी नहीं पड़ती।</p>\n<p>विक्रम उसके कुछ कहने से पहले ही समझ गया था।</p>\n<p>पिछले महीनों में उसने नैना के चेहरे को इतना पढ़ लिया था कि एक हफ्ते की ख़ामोशी और उस शाम बेंच तक आते उसके भारी कदमों का मतलब उससे छिप नहीं सकता था।</p>\n<p>वह उसके पास बैठ गया।</p>\n<p>जैसे जवाब सुनने नहीं—</p>\n<p>सहने आया हो।</p>\n<p>“उन्होंने मना कर दिया,” विक्रम ने धीमे से कहा। यह पूछना नहीं था—बस वह बात थी जो वह पहले से जानता था।</p>\n<p>“हाँ।”</p>\n<p>नैना की आवाज़ स्थिर थी, मगर उस स्थिरता की कीमत विक्रम सुन सकता था।</p>\n<p>“फाइनल।”</p>\n<p>उसने सामने देखा।</p>\n<p>“जो कुछ कह सकती थी, सब कहा। कुछ बातें तो मुझे ख़ुद नहीं पता थीं कि मेरे भीतर हैं, जब तक उनके सामने खड़े होकर कह नहीं दीं।”</p>\n<p>उसने बात को थोड़ा हल्का करना चाहा।</p>\n<p>नहीं कर पाई।</p>\n<p>“कुछ नहीं बदला।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>उसकी नज़र सामने उसी गुलमोहर पर थी जो कभी उनके पहली बार मिलने पर लगभग खाली था और अब फिर फूलों से भरा खड़ा था।</p>\n<p>“अब?”</p>\n<p>उसने पूछा।</p>\n<p>नैना ने साँस छोड़ी।</p>\n<p>“जिस परिवार से बाबा बात कर चुके हैं… वही। लड़का अच्छा है, ऐसा कहते हैं। स्थिर है। सुरक्षित है। वह सब कुछ है जो बाबा ने तय किया है कि मुझे चाहिए—सिवाय उसके जो मैं सच में चाहती हूँ।”</p>\n<p>उसका जबड़ा कस गया।</p>\n<p>“इसके आगे मेरे पास कोई प्लान नहीं है, विक्रम। इतने आख़िरी जवाब के साथ क्या किया जाता है, मुझे सच में नहीं पता।”</p>\n<p>विक्रम उसे देखता रहा।</p>\n<p>“हम अब भी लड़ सकते हैं।”</p>\n<p>नैना ने उसकी ओर देखा।</p>\n<p>“साथ में। ठीक से। अगर बात वहाँ तक पहुँचे तो… हम शादी कर सकते हैं। अपने आप। लोग करते हैं।”</p>\n<p>“मत कहो।”</p>\n<p>आवाज़ नरम थी।</p>\n<p>मगर उसमें कोई जगह नहीं थी।</p>\n<p>विक्रम चुप हो गया।</p>\n<p>“मैंने उसके बारे में भी सोचा है,” नैना ने कहा। “जितना मानना चाहती हूँ, उससे ज़्यादा।”</p>\n<p>उसने अपने हाथों की तरफ देखा।</p>\n<p>“लेकिन मैं नहीं कर सकती।”</p>\n<p>“क्यों?”</p>\n<p>“इसलिए नहीं कि तुमसे इतना प्यार नहीं करती।”</p>\n<p>उसने तुरंत उसकी तरफ देखा।</p>\n<p>“इसलिए कि मुझे पता है उसकी कीमत माँ को चुकानी पड़ेगी। एक तरफ उनका पति, दूसरी तरफ उनकी बेटी… और मेरे एक फ़ैसले के बाद दोनों शायद ज़िंदगी भर एक-दूसरे के लिए अजनबी हो जाएँ।”</p>\n<p>नैना की आवाज़ धीमी हो गई।</p>\n<p>“माँ ने मुझे पूरी ज़िंदगी सिर्फ प्यार और सब्र से पाला है। एक दिन भी बदले में अपने लिए कुछ नहीं माँगा।”</p>\n<p>उसने सिर हिलाया।</p>\n<p>“मैं उस पूरी ज़िंदगी का जवाब उनका घर तोड़कर नहीं दे सकती।”</p>\n<p>विक्रम के चेहरे पर दर्द उतर आया।</p>\n<p>“तो हम बस होने दें ये सब? तुम्हारे पिता तुम्हारे लिए फ़ैसला कर दें?”</p>\n<p>नैना की आँखों में उसी पल कुछ तेज़ हुआ—विक्रम के ख़िलाफ़ नहीं, उस अर्थ के ख़िलाफ़ जो उसके शब्दों में अनजाने आ गया था।</p>\n<p>“मैं उन्हें अपने लिए चुनने नहीं दे रही।”</p>\n<p>वह सीधी बैठ गई।</p>\n<p>“मैं उस पिता का सम्मान करना चुन रही हूँ जिसने इक्कीस साल में मुझे एक बार भी अपने प्यार पर शक करने की वजह नहीं दी। मैं उनके फ़ैसले से नफ़रत कर सकती हूँ और फिर भी उनके प्यार पर भरोसा कर सकती हूँ।”</p>\n<p>उसकी आवाज़ हल्की काँपी।</p>\n<p>“दोनों अलग बातें हैं।”</p>\n<p>फिर वह बोली—</p>\n<p>“और अभी मुझे ख़ुद भी ये फ़र्क़ मानना ज़रूरी है।”</p>\n<p>कुछ देर वह चुप रही।</p>\n<p>अपने भीतर की अगली बात को जैसे सही जगह से उठा रही हो।</p>\n<p>“तुम मुझे जानते हो, विक्रम। मैं उन लड़कियों में कभी नहीं रही जो सिर्फ इसलिए किसी बात के आगे सिर झुका दें कि परंपरा ऐसा कहती है।”</p>\n<p>“जानता हूँ।”</p>\n<p>“जिन नियमों को ग़लत समझा, तोड़े हैं। और फिर रात को बैठकर उनके टुकड़े भी नहीं गिने।”</p>\n<p>विक्रम के होंठों पर बहुत हल्की, दुखी-सी पहचान आई।</p>\n<p>“जानता हूँ।”</p>\n<p>“लेकिन ये वैसा नहीं है।”</p>\n<p>वह उसकी ओर पूरी तरह मुड़ी।</p>\n<p>“मुझे चाहिए तुम ये फ़र्क़ समझो। क्योंकि मुझे पता है तुम अभी भी कहीं न कहीं इंतज़ार कर रहे हो कि मैं एक और नियम तोड़ दूँ—जैसे हमेशा तोड़ती आई हूँ।”</p>\n<p>उसकी आँखों में आँसू थे।</p>\n<p>मगर उनके पीछे की नैना अब भी वैसी ही थी।</p>\n<p>लाउड।</p>\n<p>सीधी।</p>\n<p>अपनी बात से पीछे न हटने वाली।</p>\n<p>“ये कभी परंपरा की बात थी ही नहीं। न किसी ‘अच्छी बेटी’ के फर्ज की। न गाँव की उम्मीदों की। न उन उधार के नियमों की जिन्हें मैंने ज़िंदगी में कभी आँख बंद करके माना ही नहीं।”</p>\n<p>“नैना—”</p>\n<p>“मुझे पूरा कह लेने दो।”</p>\n<p>“मैं जो कुछ हूँ… मेरे भीतर की हर वह चीज़ जिससे तुमने प्यार किया, मेरी आवाज़, मेरी ज़िद, वह ‘लाउड’ लड़की जिसे तुमने कभी बदलने की कोशिश नहीं की—मैंने ये सब अकेले नहीं बनाया।”</p>\n<p>उसकी आँख से एक आँसू उतर आया।</p>\n<p>उसने लगभग झुँझलाकर उसे पोंछ दिया।</p>\n<p>“मुझे दिया गया है ये सब। सालों तक। बहुत सोचकर। बहुत सँभालकर। पिता चाहते तो मुझे चुप रहने वाली बेटी बना सकते थे। नहीं बनाया।”</p>\n<p>उसने साँस ली।</p>\n<p>“और माँ ने भी कभी नहीं कहा।”</p>\n<p>अब उसकी आवाज़ में दर्द था।</p>\n<p>“तो उन्होंने मेरे भीतर जो कुछ भरा है, मैं उसी को लेकर उस एक दरवाज़े से कैसे निकल जाऊँ जिसे उन्होंने मुझसे न खोलने को कहा है?”</p>\n<p>विक्रम चुप था।</p>\n<p>“अगर मैं ऐसा करती हूँ तो मैं बहादुर नहीं हो जाऊँगी। आज़ाद भी नहीं।”</p>\n<p>“मैं बस वह बेटी बन जाऊँगी जिसने जो कुछ पाया, उसे उसी दिन खर्च कर दिया जिस दिन उसे सँभालकर रखने की कोई कीमत सामने आई।”</p>\n<p>विक्रम ने कहा—</p>\n<p>“तो उसकी जगह ख़ुद को ख़त्म कर दोगी?”</p>\n<p>नैना ने उसकी ओर देखा।</p>\n<p>“यही कर रही हो न? अपनी खुशी जला दोगी ताकि बाकी किसी को उसकी राख न उठानी पड़े?”</p>\n<p>“नहीं।”</p>\n<p>जवाब तुरंत आया।</p>\n<p>“मैं ख़ुद को ख़त्म नहीं कर रही, विक्रम।”</p>\n<p>वह थोड़ा उसके करीब हुई।</p>\n<p>“मैं बस अपने हाथों से अपने परिवार में आग लगाने वाली नहीं बनना चाहती।”</p>\n<p>नैना ने उसकी आँखों में देखा।</p>\n<p>“दोनों में फ़र्क़ है। चाहे तुम्हें यहाँ बैठकर अभी वह फ़र्क़ दिखाई न दे।”</p>\n<p>“तो मुझे समझाओ।”</p>\n<p>विक्रम की आवाज़ में पहली बार कच्चापन उतर आया।</p>\n<p>“क्योंकि यहाँ से मुझे दोनों एक ही चीज़ लग रही हैं।”</p>\n<p>नैना ने लंबी साँस ली।</p>\n<p>“मेरे पिता ने इस देश को अपनी ज़िंदगी के वे साल दिए हैं जिन्हें इंसान आम तौर पर अपने लिए रखता है।”</p>\n<p>विक्रम शांत हो गया।</p>\n<p>“अपने बच्चों को बड़ा होते देखने के साल। हर शाम घर लौटने के साल। खाने की उस मेज़ पर बैठने के साल जहाँ मेरी याद में शायद ही कभी सारी कुर्सियाँ भरी रही हों।”</p>\n<p>“मेरे बचपन का आधा हिस्सा उनसे खाली था, विक्रम। और उन्होंने कभी हमें ये महसूस नहीं होने दिया कि उस खालीपन की कीमत उन्होंने भी चुकाई है।”</p>\n<p>विक्रम ने कहा, “मुझे पता है तुम्हारे पिता ने क्या दिया है।”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“नहीं। उस तरह नहीं जैसे मुझे पता है।”</p>\n<p>उसकी नज़र कहीं दूर चली गई।</p>\n<p>“मैं उस खाली कुर्सी के साथ बड़ी हुई हूँ।”</p>\n<p>उसकी नज़र बेंच के उस खाली सिरे पर गई, जहाँ कोई नहीं बैठा था।</p>\n<p>कुछ देर गुलमोहर की पत्तियों के बीच से आती हवा ही उनके बीच बोलती रही।</p>\n<p>“ये कभी इतना आसान हिसाब नहीं था कि एक तरफ मेरे परिवार की इज़्ज़त रख दो और दूसरी तरफ मेरी खुशी।”</p>\n<p>नैना फिर उसकी ओर मुड़ी।</p>\n<p>“ये उस पिता और माँ की बात है जिन्होंने जानबूझकर ऐसी बेटी पाली जो आज यहाँ बैठकर उनसे असहमत हो सकती है।”</p>\n<p>उसकी आवाज़ अब धीमी नहीं थी।</p>\n<p>“एक ऐसे समाज में जहाँ लड़कियों को हर दिन थोड़ा कम बोलना, थोड़ा कम माँगना, थोड़ा कम जगह घेरना सिखाया जाता है—तुम समझते हो हरियाणा के एक मध्यमवर्गीय घर में ऐसी बेटी पालना कितनी बड़ी बात है?”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>उसे बोलने दिया।</p>\n<p>“अगर मैं आज उनके ख़िलाफ़ घर छोड़ दूँ क्योंकि वह मेरे प्यार से डरते हैं, तो बाहर खड़ा कोई दूसरा पिता इससे क्या सीखेगा?”</p>\n<p>उसकी आँखें चमक रही थीं।</p>\n<p>“ये नहीं कि प्यार जीत गया।”</p>\n<p>“वह सीखेगा कि लाउड बेटी पालना ख़तरनाक है।”</p>\n<p>विक्रम बिल्कुल स्थिर हो गया।</p>\n<p>“कि उसे जितनी आज़ादी दोगे, किसी दिन उसी आज़ादी के सहारे वह तुम्हारा घर छोड़ जाएगी।”</p>\n<p>नैना की आवाज़ काँपी, लेकिन शब्द नहीं।</p>\n<p>“मैं किसी डरते हुए पिता के लिए वह सबूत नहीं बनूँगी कि बेटी को ज़्यादा आसमान दोगे तो एक दिन वह उसी आसमान से उड़कर हमेशा के लिए चली जाएगी।”</p>\n<p>आँसू अब उसकी पलकों से निकल आए थे।</p>\n<p>“मैं नहीं चाहती कि कहीं कोई पिता मेरी कहानी देखकर अपनी बेटी को मेरे जितना लाउड न होने दे।”</p>\n<p>उसने कहा—</p>\n<p>“उस कीमत पर भी नहीं, विक्रम।”</p>\n<p>एक साँस।</p>\n<p>“तुम्हारे लिए भी नहीं।”</p>\n<p>दूसरी।</p>\n<p>“हमारे लिए भी नहीं।”</p>\n<p>विक्रम काफी देर कुछ नहीं बोला।</p>\n<p>उसके भीतर जैसे कोई चीज़ एक साथ बहुत भारी और बहुत शांत हो गई थी।</p>\n<p>“मुझे नहीं पता इसे कैसे स्वीकार करूँ।”</p>\n<p>आख़िर उसने कहा।</p>\n<p>“और मैं ये दिखावा भी नहीं करना चाहता कि कर सकता हूँ।”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“मैं तुमसे आसानी से स्वीकार करने को कह भी नहीं रही।”</p>\n<p>उसकी आँखें अब आँसुओं से भरी थीं।</p>\n<p>“शायद मैंने भी नहीं किया है।”</p>\n<p>नैना ने बेंच पर रखा विक्रम का हाथ अपने हाथ में ले लिया।</p>\n<p>“बस एक बात जानना।”</p>\n<p>विक्रम उसकी तरफ मुड़ा।</p>\n<p>“हम जो महसूस करते हैं, उसका अंत नहीं हो रहा।”</p>\n<p>उसकी उँगलियाँ उसके हाथ के चारों ओर बंद हो गईं।</p>\n<p>“हमें जो ज़िंदगी साथ बनानी थी, शायद उसका हो रहा है।”</p>\n<p>विक्रम की साँस जैसे बीच में अटक गई।</p>\n<p>“लेकिन मुझे नहीं लगता दस साल बाद की कोई नैना होगी… या बीस साल बाद की… जिसके भीतर इसका कुछ हिस्सा नहीं रहेगा।”</p>\n<p>उसने उसका हाथ हल्के से दबाया।</p>\n<p>“तुम्हारा कुछ हिस्सा।”</p>\n<p>“नैना—”</p>\n<p>“प्लीज़, मुझे पूरा कह लेने दो। मैं ये दोबारा नहीं कह पाऊँगी।”</p>\n<p>अब वह पूरी तरह उसकी ओर थी।</p>\n<p>“तुमने मुझे मेरी ज़िंदगी के सबसे अच्छे महीने दिए हैं।”</p>\n<p>विक्रम की आँखें उससे नहीं हटीं।</p>\n<p>“तुमने मुझे बताया कि किसी ऐसे इंसान का प्यार कैसा होता है जो मुझे सच में देखता है।”</p>\n<p>उसकी आवाज़ टूटने लगी।</p>\n<p>“मेरे किसी छोटे, आसान, कम बोलने वाले रूप को नहीं।”</p>\n<p>वह मुस्कुराने की कोशिश करके रह गई।</p>\n<p>“मुझे।”</p>\n<p>एक आँसू उसके गाल से उतर गया।</p>\n<p>“इसके बाद जो भी हो… मेरी शादी जिससे भी हो, ज़िंदगी जहाँ भी जाए… ये बात कभी नहीं बदलेगी।”</p>\n<p>नैना ने उनका जुड़ा हुआ हाथ देखा।</p>\n<p>“इसे कोई हमसे वापस नहीं ले सकता।”</p>\n<p>फिर बहुत धीमे—</p>\n<p>“बाबा भी नहीं।”</p>\n<p>विक्रम को अपनी आवाज़ पर भरोसा नहीं था।</p>\n<p>इसलिए उसने जवाब नहीं दिया।</p>\n<p>बस उसका हाथ पकड़े रहा।</p>\n<p>दोनों उसी गुलमोहर के नीचे बैठे थे जो इस बार फूलों से भरा था—और अपने बीच उस दुख को थामे हुए थे जो सबसे कठिन इसलिए था क्योंकि इसमें दोष देने के लिए कोई आसान चेहरा नहीं था।</p>\n<p>न कोई धोखा।</p>\n<p>न कोई बेवफाई।</p>\n<p>न कोई खलनायक।</p>\n<p>बस एक पिता का बीस साल से भी पुराना डर—</p>\n<p>जिसे न नैना का प्यार मिटा सका,</p>\n<p>न विक्रम का।</p>\n<p>काफी देर बाद विक्रम ने पूछा—</p>\n<p>“कब?”</p>\n<p>नैना समझ गई।</p>\n<p>“शादी?”</p>\n<p>उसने सिर हिलाया।</p>\n<p>“जल्दी।”</p>\n<p>उसने आँखें पोंछीं।</p>\n<p>“शायद बाबा चाहते हैं जल्दी तय हो जाए। इससे पहले कि हम दोनों में से कोई उनका मन बदलने का कोई नया तरीका ढूँढ़ ले।”</p>\n<p>उसमें हल्की-सी पुरानी नैना थी।</p>\n<p>लेकिन आज उस वाक्य पर दोनों में से कोई हँसा नहीं।</p>\n<p>“मैं तुम्हें ख़ुद बताना चाहती थी। ठीक से।”</p>\n<p>नैना ने कहा।</p>\n<p>“किसी और से सुनो उससे पहले।”</p>\n<p>विक्रम ने बहुत देर बाद बस इतना कहा—</p>\n<p>“थैंक यू।”</p>\n<p>दो शब्द।</p>\n<p>जिनमें वह बात कहीं नहीं समा सकती थी जिसके लिए उसने उन्हें कहा था।</p>\n<p>फिर दोनों वहीं बैठे रहे।</p>\n<p>किसी को जल्दी नहीं थी।</p>\n<p>दोनों जानते थे कि उनमें से जो पहले उठेगा, वह इस शाम को एक कदम और अंत की तरफ ले जाएगा।</p>\n<p>लेकिन इतना दोनों जानते थे कि शादी के बाद उनका यह रूप—यह नैना और यह विक्रम, जो एक-दूसरे के सामने बिना किसी रिश्ते का नाम माँगे इतने पूरे थे—फिर नहीं रहेगा।</p>\n<p>और यह बेंच।</p>\n<p>यह पेड़।</p>\n<p>यह शाम।</p>\n<p>यह दुख।</p>\n<p>इनमें से कोई भी उनके भीतर से कभी पूरी तरह नहीं जाएगा।</p>\n<p>बहुत देर की उस ख़ामोशी में आख़िर नैना ने अपने भीतर बची आख़िरी पकड़ भी छोड़ दी।</p>\n<p>वह धीरे से उसकी ओर झुकी और सिर उसकी गोद में रख दिया—वैसे ही जैसे न जाने कितनी बार पहले रख चुकी थी।</p>\n<p>लेकिन आज आँसू वैसे नहीं थे।</p>\n<p>अब उन्हें सँभालकर रखने की कोई वजह नहीं बची थी।</p>\n<p>उसके कंधे काँपने लगे।</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>उसका हाथ नैना के बालों में उतर गया और उसी धीमी, पहचानी हुई लय में चलता रहा जिसे दोनों के बीच अब शब्दों की ज़रूरत नहीं थी।</p>\n<p>उसका अपना गला भी कई बार भर आया।</p>\n<p>मगर उसने उसे रोका।</p>\n<p>आज नैना को उसके दुख की बराबरी नहीं चाहिए थी।</p>\n<p>उसे बस इतना चाहिए था कि जब वह टूटे—</p>\n<p>विक्रम वहीं रहे।</p>\n<p>काफी देर बाद नैना की आवाज़ उसकी गोद से आई—</p>\n<p>“सॉरी।”</p>\n<p>विक्रम का हाथ नहीं रुका।</p>\n<p>“किसलिए?”</p>\n<p>“मैंने सोचा था बिना इस तरह टूटे पूरी बात कह लूँगी।”</p>\n<p>“उसके लिए मुझसे कभी माफ़ी मत माँगना।”</p>\n<p>उसने बहुत धीरे कहा—</p>\n<p>“कभी नहीं।”</p>\n<p>नैना वैसे ही पड़ी रही।</p>\n<p>और विक्रम उसके बालों में हाथ फेरता रहा, आँसू थम जाने के बहुत देर बाद तक।</p>\n<p>कुछ दुख समझाए नहीं जाते।</p>\n<p>उनके पास बैठा जाता है।</p>\n<p>उस शाम उन्होंने वही किया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>मैं उस शाम उनके ऊपर अपने पूरे शबाब में खड़ा था।</p>\n<p>मेरी कोई शाख ऐसी नहीं थी जिस पर फूल न हों। नारंगी आग-से मेरे फूल हर ओर फैले थे—वही रंग जिसे उन दोनों की पहली दोपहर मैं उन्हें दे नहीं पाया था। तब मैं लगभग खाली था, जैसे मौसम ने मुझे रोक रखा हो, जैसे खिलने से पहले मैं ख़ुद भी किसी बात का इंतज़ार कर रहा था।</p>\n<p>मुझे वह पहली दोपहर आज भी याद है।</p>\n<p>पेड़ तस्वीरों में याद नहीं रखते। हमारी याद कहीं और बसती है—छाल की तहों में, जड़ों के अँधेरे में, मौसमों के लौटने में; ठीक वैसे जैसे कोई पुराना घाव बरसों बाद भी शरीर को याद रहता है, भले मन ने उसकी तारीख़ गिननी छोड़ दी हो।</p>\n<p>मुझे याद हैं वे दो अजनबी।</p>\n<p>एक-दूसरे के पास बैठे हुए, फिर भी अपने बीच थोड़ी-सी जगह बचाए हुए।</p>\n<p>नज़रें कभी मिलतीं, कभी बचतीं।</p>\n<p>और एक आवाज़—</p>\n<p>जिसे उस दिन पहली बार एक चेहरा मिला था।</p>\n<p>मैं तब नहीं जानता था कि वे मेरे नीचे कितनी बार लौटेंगे। नहीं जानता था कि मेरी छाँव उनकी खामोशियों को पहचानेगी, कि मेरी शाखों के नीचे उनके हाथ एक-दूसरे तक पहुँचना सीखेंगे, कि मेरे मौसम बदलते-बदलते उनका रिश्ता भी किसी अनकहे से निकलकर इतना गहरा हो जाएगा कि एक दिन उसी जगह बैठकर उन्हें उसके अंत का बोझ उठाना पड़ेगा।</p>\n<p>मुझे उसके बाद की हर मामूली शाम याद है—एक के ऊपर एक जमा होती हुई, जैसे मिट्टी धीरे-धीरे बारिश को अपने भीतर जमा करती है। वह धुंध वाली शाम, जब खाली पार्क में उसने पहली बार इस बेंच को अपना कहा था। वर्दी में ही बैठी एक लड़की, पास रखी टोपी, और उसका बोझ—जिसे उसने बिना झिझके सौंपा और जिसे बिना झिझके थाम लिया गया। फिर उसका अपना दुख, जो उसी सावधानी से उसे लौटाया गया। चीड़ की महक का एक वादा, जो किसी पहाड़ तक गया और लौट आया।</p>\n<p>और वह शाम भी, कुछ ही दिन पहले की, जब उसने कहा था कि वह उसके बिना नहीं रह सकती—कि उसने ख़ुद से भी कभी इतनी मोहब्बत नहीं की—और मुझसे गवाह बनने को कहा था। तब मैंने अपनी एक पंखुड़ी सीधी उसकी खुली हथेली पर गिराया था, ताकि बिना दोबारा कहे उसे पता रहे कि मैंने हर शब्द सुना है।</p>\n<p>आज वे फिर मेरे नीचे थे।</p>\n<p>लेकिन अब उनके बीच कोई अनजान जगह नहीं बची थी।</p>\n<p>वे एक-दूसरे को जानते थे।</p>\n<p>ज़रूरत से भी ज़्यादा।</p>\n<p>और मैं—</p>\n<p>जो उनकी पहली मुलाक़ात के दिन उन्हें एक पूरा फूल तक नहीं दे पाया था—</p>\n<p>आज उनके ऊपर इतना खिला हुआ था कि मेरी शाखाएँ अपने ही रंग के बोझ से झुकी जा रही थीं।</p>\n<p>नीचे नैना का सिर विक्रम की गोद में था।</p>\n<p>उसके कंधे काँप रहे थे।</p>\n<p>विक्रम का हाथ उसके बालों में उसी धीमी लय में चल रहा था जिसमें वह न जाने कितनी बार उसे सँभाल चुका था।</p>\n<p>मैं उनकी हर बात सुन रहा था। मगर मेरे पास उन्हें जवाब देने को कोई आवाज़ नहीं थी—और दुख को समझने के लिए वैसे भी शब्दों की ज़रूरत नहीं होती।</p>\n<p>अगर मैं बोल पाता, तो उन्हें वह सब बताता जो मैंने देखा था—दो लोगों का धीरे-धीरे, बार-बार एक-दूसरे को चुनना; ऐसे महीने, जो मेरी जगह से देखने पर उन सब चीज़ों में सबसे तेज़ बढ़े थे जिन्हें मैंने कभी उगते देखा। उन्हें बताता कि यह कितना दुर्लभ था—मेरी छाँव से अनगिनत मामूली दोपहरें गुज़रीं, और उनमें से कितनी कम कभी ऐसी दिखीं। उनसे कहता कि इसे अंत मत बनने दो—कि कुछ चीज़ें तभी खोती हैं, जब उन्हें उठाए चलने वाले उन्हें खोया हुआ मान लें।</p>\n<p>मगर मेरे पास इनमें से किसी बात के लिए आवाज़ नहीं थी। सिर्फ फूल थे—और अब फूल ही मेरी आख़िरी भाषा बचे थे।</p>\n<p>इसलिए मैंने उन्हें जाने दिया—वैसे ही, जैसे पहले भी सैकड़ों चीज़ों को जाने दिया था, जिन्हें रोकने की ताकत मेरे पास कभी नहीं थी।</p>\n<p>पहले एक पंखुड़ी छूटी।</p>\n<p>फिर दूसरी।</p>\n<p>फिर एक पूरा फूल।</p>\n<p>वही नारंगी रंग, जिसे सीखने में मुझे एक पूरा मौसम लगा था, अब मुझसे वैसे झर रहा था जैसे आँखों से आँसू झरते हैं—धीरे, अनचाहे, और एक बार निकल जाने के बाद किसी की ताकत में नहीं कि उन्हें वापस वहीं पहुँचा दे जहाँ से वे टूटे थे।</p>\n<p>उस शाम मुझे लगा, जैसे पूरा पार्क चुपचाप एक-दूसरे से बात करना सीख गया हो।</p>\n<p>मेरी इस एक बेंच पर जो हो रहा था, उसकी ख़बर बिना किसी आवाज़ के पेड़ से पेड़ तक पहुँच रही थी—उस भाषा में जिसे केवल जड़ें समझती हैं।</p>\n<p>दूर गेट के पास खड़ा पलाश भी उस समय अपने पूरे रंग में था।</p>\n<p>कुछ देर बाद उसने भी अपनी आग छोड़नी शुरू कर दी।</p>\n<p>उसकी नारंगी पंखुड़ियाँ मेरी पंखुड़ियों के साथ रास्ते पर उतरने लगीं।</p>\n<p>और प्रवेश के पास खड़ा अमलतास—</p>\n<p>जिसका पीला रंग अक्सर खुशियों का रंग होता है, शादियों का, शुभ ख़बरों का—</p>\n<p>उसने भी अपनी लंबी सुनहरी लड़ियों से फूल गिराने शुरू कर दिए।</p>\n<p>उस शाम उसका सोना भी उत्सव जैसा नहीं लग रहा था।</p>\n<p>जैसे कोई हमेशा खुश रहने वाली चीज़ पहली बार रोना सीख रही हो।</p>\n<p>कुछ ही मिनटों में रास्ता नारंगी और सुनहरे फूलों से भर गया।</p>\n<p>मैं अपने रंग में रो रहा था।</p>\n<p>पलाश अपने रंग में।</p>\n<p>अमलतास अपने।</p>\n<p>और हमारे नीचे बैठे वे दो इंसान, जिन्हें हमारी इस ख़ामोश भाषा का एक शब्द भी सुनाई नहीं दे सकता था, फिर भी उसी बरसात के बीच बैठे रहे—</p>\n<p>एक ऐसी बारिश में,</p>\n<p>जो शायद वह सब कह रही थी</p>\n<p>जिसे हममें से कोई भी आवाज़ देकर नहीं कह सकता था।</p>\n<p>मैं नहीं जानता था कि उस शाम अपने आख़िरी फूल गिराते हुए मुझे फिर कभी ऐसा प्रेम देखने को मिलेगा या नहीं।</p>\n<p>ऐसा प्रेम जो पूरा था।</p>\n<p>जो अपनी मर्ज़ी से दिया गया था।</p>\n<p>जिसमें किसी ने किसी को धोखा नहीं दिया था।</p>\n<p>और फिर भी जिसे वह अंत नहीं मिला जिसका वह हकदार था।</p>\n<p>लेकिन मैं जा भी कहाँ सकता था?</p>\n<p>पेड़ों के हिस्से में जाना नहीं आता।</p>\n<p>हम वहीं खड़े रहते हैं जहाँ हमें जड़ें मिली होती हैं—लोग आते हैं, बैठते हैं, प्रेम करते हैं, वादे करते हैं, बिछड़ जाते हैं… और हम उनके बाद भी उसी जगह खड़े रह जाते हैं।</p>\n<p>इसलिए मैं भी वहीं खड़ा रहा।</p>\n<p>अपनी उसी मिट्टी में।</p>\n<p>उसी बेंच के ऊपर।</p>\n<p>चुप।</p>\n<p>जड़ों में बँधा हुआ।</p>\n<p>और उम्मीद भी करता हुआ।</p>\n<p>किसी अगली दोपहर की।</p>\n<p>किसी अगली आवाज़ की जिसे पहली बार कोई चेहरा मिले।</p>\n<p>किसी अगली लड़की और किसी अगले लड़के की, जो मेरी छाँव में आकर बैठें और कुछ देर बाद उनका एक हाथ दूसरे हाथ को वैसे ही ढूँढ़ ले जैसे कभी इन दोनों ने एक-दूसरे को ढूँढ़ लिया था।</p>\n<p>बस अगली बार—</p>\n<p>अगर मेरे फूलों से कुछ माँगा जाए—</p>\n<p>तो मैं केवल इतना चाहूँगा कि मुझे किसी कहानी का अंत इस तरह न देखना पड़े।</p>\n<p>अगली बार जो दो लोग मेरे नीचे प्रेम में पड़ें—</p>\n<p>उन्हें साथ रहने दिया जाए।</p>\n<p>और कहानी को वहाँ तक पहुँचने दिया जाए,</p>\n<p>जहाँ तक नैना और विक्रम की कहानी</p>\n<p>कभी पहुँच नहीं सकी।</p>"}, {"chapter": 33, "title": "अध्याय 31 — आख़िरी शाम", "content": "<h1>अध्याय 31 — आख़िरी शाम</h1>\n<p>पिता के आख़िरी इनकार को एक हफ्ता हो चुका था, जब नैना के भीतर अपने दुख से अलग एक और डर धीरे-धीरे जगह बनाने लगा—वैसे ही जैसे आग बुझ जाने के बाद किसी घर में ठंड उतरती है; पहले महसूस नहीं होती, फिर अचानक पता चलता है कि वह हर कमरे में फैल चुकी है।</p>\n<p>उस शाम गुलमोहर की बेंच पर विक्रम एक बार भी नहीं रोया था।</p>\n<p>नैना पिछले कई दिनों से इसी बात के बारे में सोच रही थी।</p>\n<p>अब उसे लगने लगा था कि वह स्थिरता मज़बूती नहीं थी। शायद विक्रम अपने भीतर किसी चीज़ को इतनी ताकत से रोके हुए था कि वही रोकना ख़तरनाक हो सकता था। वह ऐसे जवानों को जानती थी, जिन्हें दुख को शब्द देने से ज़्यादा उसे भीतर बंद रखना सिखाया जाता है।</p>\n<p>वह ऐसा नहीं होने दे सकती थी।</p>\n<p>कम-से-कम अपनी वजह से नहीं।</p>\n<p>इसलिए शादी से तीन दिन पहले जब उसने विक्रम को फोन किया, तो वह सिर्फ आख़िरी बार मिलने के लिए नहीं था। वह चाहती थी कि इस रात के बाद विक्रम उससे और ज़्यादा टूटा हुआ नहीं, जितना संभव हो उतना सँभला हुआ लौटे।</p>\n<p>फोन उठते ही नैना ने कहा—</p>\n<p>“मैं तुमसे मिलना चाहती हूँ।”</p>\n<p>कुछ पल बाद—</p>\n<p>“एक बार और। सब बदलने से पहले।”</p>\n<p>“जहाँ कहो।”</p>\n<p>“लड़ने के लिए नहीं।”</p>\n<p>नैना ने जल्दी से कहा, जैसे यह बात पहले साफ़ कर देना ज़रूरी हो।</p>\n<p>“मैं बाबा का मन बदलवाने के लिए फोन नहीं कर रही। न तुम्हारे साथ भागने के लिए। पिछले तीन दिनों से रात-रात भर जागकर जो भी रास्ते दिमाग में आए हैं, मैं एक-एक करके सब सोच चुकी हूँ… और छोड़ चुकी हूँ।”</p>\n<p>लाइन पर कुछ क्षण ख़ामोशी रही।</p>\n<p>“बस एक शाम चाहिए, विक्रम।”</p>\n<p>उसकी आवाज़ हल्की पड़ गई।</p>\n<p>“बाद में याद रखने के लिए कुछ।”</p>\n<p>“मैं आऊँगा।”</p>\n<p>विक्रम ने बिना किसी सवाल के कहा।</p>\n<p>“जहाँ तुम चाहो।”</p>\n<p>फोन पर फिर ख़ामोशी हुई।</p>\n<p>इतनी लंबी कि विक्रम को लगा दूसरी तरफ नैना रो रही है और नहीं चाहती कि उसे आवाज़ सुनाई दे।</p>\n<p>जब वह फिर बोली तो आवाज़ पतली थी, मगर सँभली हुई।</p>\n<p>“थैंक यू… बहस न करने के लिए।”</p>\n<p>“अभी तुम्हें जो चाहिए, उससे बहस करने का हक नहीं है मुझे।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“सिर्फ देने का है।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम उससे पहले पहुँच गया था।</p>\n<p>शहर के किनारे का वह रिज़ॉर्ट उसने बहुत सोचकर चुना था—फैले हुए सँवरे लॉन, भीतर ही एक शांत रेस्तराँ, और उसके सामने पानी के भीतर से रोशन होता स्विमिंग पूल, जिसकी हल्की सुनहरी रोशनी रात में भी जैसे अपने लिए थोड़ी-सी चमक बचाकर रखे हुए थी।</p>\n<p>वह जगह ऐसी शामों के लिए बनी लगती थी जिन्हें लोग ठीक से याद रखना चाहते हैं—सालगिरहें, प्रस्ताव, ज़िंदगी के वे छोटे-बड़े अवसर जिन्हें बाद में किसी तारीख़ से ज़्यादा एक एहसास की तरह याद किया जाता है।</p>\n<p>विक्रम ने जानबूझकर ऐसी जगह चुनी थी जहाँ नैना पहले कभी न आई हो।</p>\n<p>जहाँ इस शाम में किसी और स्मृति की हिस्सेदारी न हो।</p>\n<p>और इतनी खूबसूरत कि जिस बात को यह रात अपने भीतर रखने वाली थी, उसके सामने जगह छोटी न लगे।</p>\n<p>वह मेज़ पर बैठा अपने गिलास को उँगलियों के बीच धीरे-धीरे घुमा रहा था और मन ही मन मिलने के न जाने कितने तरीके बनाकर मिटा चुका था।</p>\n<p>कोई भी ठीक नहीं लग रहा था।</p>\n<p>आख़िरी शाम के लिए सही पहला वाक्य शायद होता ही नहीं।</p>\n<p>नैना हरे रंग में आई।</p>\n<p>शादी वाले लहँगे का गहरा, सजा हुआ हरा नहीं—एक साधारण, मुलायम हरा कुर्ता, जैसा वह किसी और आम शाम को पहन सकती थी—वैसा हरा, जैसा गुलमोहर में फूलों से पहले आता है।</p>\n<p>विक्रम ने उसे देखते ही समझ लिया कि वह आने से पहले रो चुकी है और फिर बहुत सावधानी से चेहरे से उसके निशान मिटाकर आई है।</p>\n<p>वह सामने बैठी।</p>\n<p>विक्रम ने कहा—</p>\n<p>“बहुत खूबसूरत लग रही हो।”</p>\n<p>“मत कहो।”</p>\n<p>नैना ने तुरंत रोक दिया।</p>\n<p>“आज नहीं। तुमने ऐसी बातें शुरू कर दीं तो मैं डिनर तक नहीं पहुँच पाऊँगी।”</p>\n<p>फिर भी उसके होंठों पर छोटी-सी मुस्कान आ गई।</p>\n<p>सच्ची।</p>\n<p>और सिर्फ इतना सामान्य कह पाने से ही उसके कंधों का तनाव थोड़ा उतर गया।</p>\n<p>उन्होंने ज़रूरत से ज़्यादा खाना मँगाया।</p>\n<p>शायद इसलिए कि ऑर्डर देना भी उस असली बातचीत को कुछ देर और टालने का तरीका था जो दोनों के बीच मेज़ के नीचे कहीं पहले से बैठी थी।</p>\n<p>काफी देर तक वे उन्हीं बातों पर बोलते रहे जिनका आज की रात से कोई लेना-देना नहीं था—एक फिल्म जो नैना ने देखी थी और विक्रम को बताना भूल गई थी; बचपन का उसका कुत्ता जो हर शाम गेट पर उसके पिता की जीप का इंतज़ार करता था; ट्रेनिंग के दिनों की एक घटना जो इतने महीनों में भी किसी तरह विक्रम ने नहीं सुनी थी।</p>\n<p>वह अपनी ही किसी याद पर हँसती तो विक्रम उसे देखता रहता।</p>\n<p>बाल पीछे करती।</p>\n<p>पानी का गिलास उठाती।</p>\n<p>बात करते हुए अचानक आँखें बड़ी कर लेती।</p>\n<p>और हर छोटी चीज़ को वह अपने भीतर कहीं रखता जा रहा था।</p>\n<p>जानबूझकर।</p>\n<p>लगभग बेचैनी से।</p>\n<p>जैसे इंसान किसी ऐसी चीज़ को याद नहीं करता—</p>\n<p>उसे अपने भीतर बचाता है</p>\n<p>जिसे वह पहले से जानता हो कि खोने वाला है।</p>\n<p>दूसरा कोर्स लगभग ख़त्म होने के बाद नैना ने काँटा नीचे रखा।</p>\n<p>“मैंने तुम्हें कभी नहीं बताया कि उस दिन सुनैना ने मुझसे क्या कहा था।”</p>\n<p>विक्रम तुरंत समझ गया।</p>\n<p>“जब वह तुम्हारे फ्लैट पर अचानक आई थी?”</p>\n<p>“हाँ।”</p>\n<p>“मैंने बहुत सोचा था उस दिन उसने क्या कहा।”</p>\n<p>“मुझे पता है।”</p>\n<p>नैना ने पानी का गिलास मेज़ पर धीरे-धीरे आधा घुमाया।</p>\n<p>“कई हफ्तों तक तुम्हारे चेहरे पर देखती रही कि तुम जानना चाहते हो। लेकिन तब मैं ख़ुद भी उसे ज़ोर से कहने के लिए तैयार नहीं थी।”</p>\n<p>वह कुछ पल नीचे देखती रही।</p>\n<p>“उसने कहा था—इस इंसान को जाने मत देना। ज़िंदगी में दूसरा ऐसा नहीं मिलेगा।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“उसने कहा था, मुझे जो बात मानने में महीनों लगे, उसे उसने तुम्हारे साथ एक दोपहर बिताकर समझ लिया था।”</p>\n<p>नैना की आँखें उसकी ओर उठीं।</p>\n<p>“कि तुम मुझे संभाल सकते हो। मुझे चलाने की कोशिश नहीं करोगे… मुझे संभाल सकते हो।”</p>\n<p>उसकी आवाज़ में हल्की मुस्कान आई।</p>\n<p>“उसने कहा था कमज़ोर इंसान मेरे जैसी औरत को अपने हिसाब से छोटा करने लगेगा, ताकि उससे प्यार करना आसान हो जाए। और उससे भी छोटा इंसान शायद मेरे साथ खड़ा होना ही मुश्किल समझेगा।”</p>\n<p>विक्रम की आँखें उससे नहीं हटीं।</p>\n<p>“उसने कहा था तुम दोनों में से कोई नहीं हो। तुम्हारी शांति में भी अपना जुनून है—तुम्हें अपनी बात मनवाने के लिए आवाज़ ऊँची नहीं करनी पड़ती।”</p>\n<p>अब नैना की आँखें भर आई थीं।</p>\n<p>“और उसने कहा था अगर मैंने तुम्हें जाने दिया तो ज़िंदगी की सबसे बड़ी ग़लती होगी।”</p>\n<p>उसने एक गीली साँस छोड़ी—जो आधी हँसी थी, आधी रुलाई।</p>\n<p>दर्द उस साँस से कहीं बड़ा था।</p>\n<p>“मेरी छोटी बहन ने तुम्हें एक दोपहर जानकर ये कहा था।”</p>\n<p>उसने गहरी साँस ली।</p>\n<p>“और मैं आज यहाँ बैठी हूँ… शायद उसे सबसे बुरे तरीके से सही साबित करने के लिए।”</p>\n<p>“तुम उसे सही साबित नहीं कर रही।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“किसी से प्यार करना और फिर किसी ऐसी चीज़ की वजह से उसे खो देना जिस पर तुम दोनों का बस नहीं था—इससे उसकी बात ग़लत नहीं हो जाती।”</p>\n<p>नैना उसे देखती रही।</p>\n<p>“बस दुनिया उतनी आसान नहीं निकली जितनी उसे उस दोपहर लगी थी।”</p>\n<p>“मुझे बचाने का अच्छा तरीका है।”</p>\n<p>“तुम्हें बचा नहीं रहा।”</p>\n<p>विक्रम की आवाज़ स्थिर थी।</p>\n<p>“सच में यही मानता हूँ।”</p>\n<p>नैना ने मेज़ के पार हाथ बढ़ाया और उसका हाथ पकड़ लिया।</p>\n<p>गर्म कमरे में भी उसकी उँगलियाँ ठंडी थीं।</p>\n<p>“मैं पूरी रात का कोई ऐसा रूप ढूँढ़ रही हूँ जिसमें मुझे लगे कि मैं तुम्हारे साथ ग़लत नहीं कर रही।”</p>\n<p>उसने कहा।</p>\n<p>“अभी तक नहीं मिला।”</p>\n<p>“तुम मेरे साथ ग़लत नहीं कर रही, नैना।”</p>\n<p>“तो इसे क्या कहूँ?”</p>\n<p>उसकी आँखें सीधे उसकी आँखों में थीं।</p>\n<p>“जिस इंसान से ज़िंदगी में सबसे ज़्यादा प्यार किया, उसी के ऊपर अपने पिता को चुन रही हूँ।”</p>\n<p>विक्रम ने उसकी हथेली पलटी और उसकी लकीरों पर उँगली फिराई—वही पुरानी आदत, जैसे जवाब देने से पहले कुछ पल वहीं से उधार ले रहा हो।</p>\n<p>“मैं इसे वही प्यार कहूँगा जो तुम अपने परिवार से करती हो।”</p>\n<p>नैना की आँखों में एक परछाईं-सी हिली।</p>\n<p>“तुमने मुझे चुनना बंद नहीं किया। तुम उन्हें भी चुन रही हो, क्योंकि उनसे भी प्यार करती हो—बस दूसरे ढंग से।”</p>\n<p>उसने उसकी हथेली अपने सीने से लगा ली।</p>\n<p>“तुम जानती हो तुम्हारे पिता से टकराने की कीमत तुम्हारी माँ चुकाएँगी। और तुम इतनी ख़ुदग़र्ज़ नहीं हो कि अपनी खुशी उठा लो और उसका हिसाब बाकी लोगों के नाम छोड़ दो।”</p>\n<p>उसकी आवाज़ नरम हुई।</p>\n<p>“इसे हार मत कहो।”</p>\n<p>एक पल।</p>\n<p>“शायद ये प्यार का सबसे मुश्किल रूप है—जिसमें सबसे बड़ी कीमत वही देता है जो प्यार कर रहा होता है।”</p>\n<p>नैना कुछ नहीं बोली।</p>\n<p>बहुत देर तक उसका हाथ पकड़े रही।</p>\n<p>फिर लगभग फुसफुसाकर कहा—</p>\n<p>“मुझे नहीं पता तुम्हारे बिना अपनी ज़िंदगी कैसे जीऊँगी।”</p>\n<p>“जी लोगी।”</p>\n<p>विक्रम ने झूठी आसानी से नहीं कहा।</p>\n<p>“आसानी से नहीं। कई साल तक ऐसी जगहों पर मेरी याद आएगी जहाँ तुम्हें ख़ुद उम्मीद नहीं होगी।”</p>\n<p>विक्रम ने उसकी आँखों में देखा।</p>\n<p>“लेकिन जी लोगी। क्योंकि जितने लोगों को मैंने जाना है, उनमें सबसे मजबूत तुम हो।”</p>\n<p>फिर—</p>\n<p>“और अब जो भी ज़िंदगी बनाओगी, उसमें हमारा कुछ हिस्सा रहेगा। चाहे कभी उसका नाम लो या नहीं।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>फिर उसके चेहरे पर कोई फ़ैसला उतर आया।</p>\n<p>“एक बात कहूँ?”</p>\n<p>“कहो।”</p>\n<p>“और इसे सिर्फ ऐसी बात समझकर मत सुनना जो लोग बिछड़ते वक्त अंत को थोड़ा कम दर्दनाक बनाने के लिए कह देते हैं।”</p>\n<p>नैना स्थिर हो गई।</p>\n<p>विक्रम ने उसकी आँखों में देखते हुए कहा—</p>\n<p>“एक दिन मैं तुम तक पहुँचूँगा।”</p>\n<p>नैना की भौंहें हल्की सिकुड़ीं।</p>\n<p>“सालों बाद। बिना हमारे रास्ते दोबारा मिले। बिना मेरे सामने आए।”</p>\n<p>“न फोन पर।”</p>\n<p>एक ठहराव।</p>\n<p>“न दरवाज़े पर दस्तक देकर।”</p>\n<p>नैना बस उसे देख रही थी।</p>\n<p>“उसका वक्त मैं तय नहीं कर पाऊँगा। वह पहले से ख़बर देकर नहीं आएगा। किसी चिट्ठी की तरह अपना नाम लेकर भी नहीं।”</p>\n<p>विक्रम के शब्द अब जैसे उसी रात से आगे किसी ऐसी जगह जा रहे थे जिसे दोनों में से कोई देख नहीं सकता था।</p>\n<p>“वह ऐसे आएगा जैसे बहुत लंबे सूखे के बाद पहली बारिश आती है। बिना बुलाए। बिना तारीख़ बताए। लेकिन पहली बूँद गिरने से पहले ही मिट्टी जैसे जान लेती है कि पानी आने वाला है।”</p>\n<p>नैना की उँगलियाँ उसके हाथ पर कस गईं।</p>\n<p>“तुम किसी बिल्कुल साधारण जगह पर होगी। किसी ऐसे काम में लगी हुई जिसका मुझसे कोई रिश्ता नहीं होगा।”</p>\n<p>वह रुका।</p>\n<p>“और अचानक तुम्हारे भीतर सब कुछ एक पल के लिए शांत हो जाएगा।”</p>\n<p>उसकी आवाज़ अब लगभग फुसफुसाहट थी।</p>\n<p>“वैसा ठहराव… जैसे बारिश से ठीक पहले हवा साँस रोक लेती है और आसमान को याद आता है कि उसे बरसना है।”</p>\n<p>नैना की आँखों में नमी चमकी।</p>\n<p>“वह ठहराव मैं होऊँगा।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“तुम तक पहुँचने का मेरा आख़िरी तरीका।”</p>\n<p>विक्रम ने उसका हाथ थामे रखा।</p>\n<p>“और उस पल तुम्हें समझ आएगा कि हमारे बीच जो था, वह कितना गहरा था।”</p>\n<p>नैना बहुत देर चुप रही।</p>\n<p>“ये नामुमकिन वादा है।”</p>\n<p>“शायद।”</p>\n<p>विक्रम के चेहरे पर बहुत हल्की मुस्कान आई।</p>\n<p>“फिर भी कर रहा हूँ।”</p>\n<p>विक्रम ने उसकी आँखों से नज़र नहीं हटाई।</p>\n<p>“और जब कभी ऐसा हो… ये शाम याद रखना। ये वाक्य याद रखना।”</p>\n<p>एक साँस।</p>\n<p>“ताकि तुम्हें पता हो—मैंने अपना वादा निभाया।”</p>\n<p>कुछ पल बाद उसके चेहरे पर गंभीरता और गहरी हो गई।</p>\n<p>“और एक कर्ज भी है।”</p>\n<p>नैना की आँखें प्रश्न में उठीं।</p>\n<p>“तुम्हारी वो तीन लाइनें।”</p>\n<p>नैना की साँस एक पल को रुकी।</p>\n<p>विक्रम उन्हें भूल ही नहीं सकता था।</p>\n<p>खून से लिखे वे तीन वाक्य—</p>\n<p><b>मैं इंतज़ार कर रही हूँ।<br/>\nतुमने वादा किया है कि लौटोगे।<br/>\nज़िंदा लौटना, विक्रम।</b></p>\n<p>विक्रम ने कहा—</p>\n<p>“एक शब्द नहीं भूला।”</p>\n<p>नैना की आँखों से आँसू निकल आए।</p>\n<p>“ऐसी चीज़ का कर्ज शायद पूरी तरह कभी चुकता नहीं होता।”</p>\n<p>विक्रम की आवाज़ भारी हो गई।</p>\n<p>“लेकिन जितना वक्त लगे… जैसे भी हो… उनका जवाब दूँगा।”</p>\n<p>वह उसकी ओर झुका।</p>\n<p>“तीन लाइनों में नहीं।”</p>\n<p>हल्की-सी साँस।</p>\n<p>“इतना बड़ा जवाब जितना उन तीन लाइनों का हक है।”</p>\n<p>नैना का चेहरा थोड़ा टूट गया।</p>\n<p>इतने महीनों से दोनों ने उन पंक्तियों को इस तरह सामने रखकर कभी बात नहीं की थी।</p>\n<p>“तुमने मुझे इन महीनों में जितना दिया है, उसका पूरा हिसाब शायद ज़िंदगी भर नहीं चुका पाऊँगा।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“लेकिन ये कर्ज…”</p>\n<p>उसने उसका हाथ कसकर पकड़ा।</p>\n<p>“ये ज़रूर चुकाऊँगा।”</p>\n<p>नैना ने जवाब नहीं दिया।</p>\n<p>बस सिर हिला दिया।</p>\n<p>उसे नहीं मालूम था कि वह इस वादे पर क्यों भरोसा कर रही है।</p>\n<p>बस कर रही थी।</p>\n<p>फिर विक्रम ने कहा—</p>\n<p>“एक वादा मुझे भी चाहिए तुमसे।”</p>\n<p>“क्या?”</p>\n<p>“शादी के बाद… तुम्हारे और तुम्हारे पति के बीच चाहे जितनी नज़दीकी हो जाए, चाहे तुम्हें लगे अच्छे रिश्ते में हर सच बताया जाना चाहिए…”</p>\n<p>उसकी आवाज़ और गंभीर हो गई।</p>\n<p>“हमारे बारे में उसे मत बताना।”</p>\n<p>नैना का चेहरा बदल गया।</p>\n<p>“कभी नहीं, नैना। मुझसे वादा करो।”</p>\n<p>“तुम्हें नहीं लगता शादी सच पर बननी चाहिए?”</p>\n<p>“मुझे लगता है शादी उस चीज़ पर बननी चाहिए जिसमें दो लोग एक-दूसरे से ठीक तरह प्यार करने के लिए सुरक्षित रह सकें।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“हर सच देना ज़रूरी नहीं होता। कुछ सच सामने वाले को देने से ज़्यादा उस इंसान को चोट पहुँचाते हैं जिसने उन्हें जिया है।”</p>\n<p>“मैं ख़ुद को बचाने के लिए नहीं कह रहा। मैं वहाँ रहूँगा ही नहीं।”</p>\n<p>उसकी आँखें नैना पर थीं।</p>\n<p>“मैंने देखा है जलन इंसान की याद में उस औरत को भी बदल देती है जिससे वह प्यार करता है, जबकि वह औरत असल में बदली तक नहीं होती।”</p>\n<p>उसकी आवाज़ नरम हुई।</p>\n<p>“मैं वह ख़तरा तुम्हारे पास नहीं छोड़ना चाहता।”</p>\n<p>नैना काफी देर उसे देखती रही।</p>\n<p>उसके चेहरे पर असहमति अब भी थी।</p>\n<p>वह अभी भी पूरी तरह नहीं मानती थी कि किसी सच को न कहना भी कभी-कभी किसी रिश्ते की रक्षा हो सकता है।</p>\n<p>“वादा करो, नैना।”</p>\n<p>इस बार विक्रम की आवाज़ में आग्रह था।</p>\n<p>“प्लीज़।”</p>\n<p>बहुत देर बाद उसने कहा—</p>\n<p>“वादा करती हूँ।”</p>\n<p>विक्रम ने उसकी आँखों में कुछ क्षण और देखा।</p>\n<p>फिर बात वहीं छोड़ दी।</p>\n<p>आख़िर वादों के साथ इससे ज़्यादा किया भी क्या जा सकता है—</p>\n<p>उन्हें मान लिया जाता है,</p>\n<p>खासकर उन वादों को जिन्हें टूटते या निभते देखने के लिए आप वहाँ मौजूद नहीं होंगे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>डिनर के बाद नैना ने कहा—</p>\n<p>“कहीं शांत जगह चलें?”</p>\n<p>“बात करने?”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“नहीं।”</p>\n<p>फिर—</p>\n<p>“बस अभी ख़त्म नहीं होना चाहती।”</p>\n<p>विक्रम ने उसी रिज़ॉर्ट में एक कमरा लिया हुआ था।</p>\n<p>पहले से।</p>\n<p>लेकिन इस बार वह किसी चुराई हुई रात जैसा नहीं था।</p>\n<p>न कोई जल्दबाज़ी।</p>\n<p>न किसी से छिपने की ज़रूरत।</p>\n<p>अभी नैना की शादी नहीं हुई थी।</p>\n<p>छिपाने के लिए बस एक सच था—</p>\n<p>तीन दिन बाद दुनिया जिस तरह रिश्तों को पहचानती है, उस तरह वह किसी और की हो जाएगी।</p>\n<p>कमरा बड़ा था, रोशनी मुलायम। शीशे की पूरी दीवार के उस पार वही लॉन फैला था और नीचे पूल की सुनहरी रोशनी अब भी अँधेरे पानी में चुपचाप जल रही थी।</p>\n<p>दरवाज़ा बंद हुआ।</p>\n<p>फिर भी दोनों किसी चीज़ की ओर जल्दी नहीं बढ़े।</p>\n<p>नैना ने सैंडल उतारी और पलंग के किनारे बैठ गई।</p>\n<p>विक्रम उसके पास।</p>\n<p>काफी देर तक वे बस बात करते रहे।</p>\n<p>धीरे।</p>\n<p>बिना किसी मंज़िल के।</p>\n<p>उस एक बात के चारों ओर घूमते हुए जिसका नाम दोनों अभी नहीं लेना चाहते थे।</p>\n<p>कब विक्रम ने हाथ बढ़ाकर उसके बालों में लगी पिन खोलनी शुरू की, दोनों में से किसी ने उस क्षण को दर्ज नहीं किया।</p>\n<p>उसने बहुत सावधानी से पिन निकाली।</p>\n<p>बाल धीरे-धीरे खुलकर उसके कंधों पर आ गए।</p>\n<p>वैसे ही जैसे विक्रम को हमेशा अच्छे लगते थे।</p>\n<p>नैना ने उसे रोका नहीं।</p>\n<p>कुछ कहा भी नहीं।</p>\n<p>बस उसके चेहरे से थोड़ी-सी थकान उतर गई।</p>\n<p>फिर वह उसके करीब खिसकी और सिर उसकी छाती पर रख दिया।</p>\n<p>जैसे न जाने कितनी बार पहले रखा था।</p>\n<p>विक्रम का हाथ उसके बालों में चला गया।</p>\n<p>नैना की उँगलियाँ उसकी शर्ट पर बेवजह आकृतियाँ बनाती रहीं।</p>\n<p>कभी दोनों बात करते।</p>\n<p>कभी चुप हो जाते।</p>\n<p>उस साधारण-सी नज़दीकी को जितना खींच सकते थे, खींचते रहे—क्योंकि अब साधारण चीज़ें ही सबसे ज़्यादा कीमती थीं।</p>\n<p>“एक बात समझना।”</p>\n<p>नैना ने उसकी छाती से लगे-लगे कहा।</p>\n<p>“मैंने तुमसे प्यार किया है।”</p>\n<p>विक्रम का हाथ उसके बालों में चलता रहा।</p>\n<p>“पूरा।”</p>\n<p>उसने आँखें बंद कर लीं।</p>\n<p>“ऐसा नहीं कि दस साल बाद घर-गृहस्थी और ज़िंदगी के बीच इसे अपनी जवानी का कोई दौर कहकर समझा दूँगी।”</p>\n<p>उसकी आवाज़ काँपी।</p>\n<p>“इसके बाद ज़िंदगी जहाँ भी जाए… ये सच था।”</p>\n<p>उसने चेहरा उठाकर उसे देखा।</p>\n<p>“हम सच थे।”</p>\n<p>विक्रम ने कहा—</p>\n<p>“सिर्फ तुम्हारी तरफ से नहीं।”</p>\n<p>उसकी उँगलियाँ नैना के बालों में ठहर गईं।</p>\n<p>“तुम्हारे पिता कुछ भी मानें। दुनिया इस कहानी के बारे में कुछ भी माने जिसे वह कभी पूरा जानेगी ही नहीं…”</p>\n<p>उसने नैना की आँखों में देखा।</p>\n<p>“मैंने भी तुमसे प्यार किया है।”</p>\n<p>फिर—</p>\n<p>“तुम्हारे पूरे रूप से। सिर्फ आसान हिस्सों से नहीं।”</p>\n<p>नैना उठकर उसके सामने बैठ गई।</p>\n<p>“तो आज इसे कोई प्रदर्शन मत बनाना।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“और ये सोचकर जल्दी मत करना कि रात ख़त्म हो जाएगी।”</p>\n<p>उसकी आवाज़ एक पल टूटी।</p>\n<p>“रात तो वैसे भी ख़त्म होगी।”</p>\n<p>फिर ख़ुद को सँभालकर—</p>\n<p>“मैं चाहती हूँ हर मिनट जितना खिंच सकता है, उतना खिंचे।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“ठीक है।”</p>\n<p>“और विक्रम…”</p>\n<p>वह रुकी।</p>\n<p>“मेरे साथ वैसे रहना जैसे पहली बार थे।”</p>\n<p>उसकी आँखें उससे नहीं हटीं।</p>\n<p>“काँच समझकर मत छूना।”</p>\n<p>एक साँस।</p>\n<p>“ऐसी लड़की की तरह भी नहीं जिसे तुम अभी से खो चुका मान रहे हो।”</p>\n<p>उसने उसका हाथ अपने हाथ में लिया।</p>\n<p>“मैं अभी यहीं हूँ।”</p>\n<p>और फिर—</p>\n<p>“आज भी तुम्हें चुन रही हूँ। एक आख़िरी बार। मेरे पास जितना कुछ बचा है, उस सबके साथ।”</p>\n<p>विक्रम ने उसे अपने करीब खींच लिया।</p>\n<p>बिना किसी घोषणा के।</p>\n<p>जैसे पहली बार दोनों को वहाँ तक पहुँचने के लिए शब्दों की ज़रूरत नहीं पड़ी थी।</p>\n<p>आज भी नहीं पड़ी।</p>\n<p>इस बार कोई जल्दी नहीं थी।</p>\n<p>न पहाड़ वाली पहली रात की वह अनजान बेचैनी, न वह भूख जिसने तब दोनों को ख़ुद चौंका दिया था।</p>\n<p>यह उससे अलग था।</p>\n<p>धीमा।</p>\n<p>गहरा।</p>\n<p>हर ठहराव ज़रूरत से एक पल ज़्यादा—क्योंकि अब अगली बार के लिए कुछ बचाकर रखने का कोई अर्थ नहीं था।</p>\n<p>विक्रम ने उसके चेहरे को दोनों हाथों में लिया।</p>\n<p>कुछ क्षण बस उसे देखा।</p>\n<p>जैसे आँखें भी स्मृति बना सकती हों।</p>\n<p>फिर उसने माथा उसके माथे से टिका दिया।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>कमरे की मुलायम रोशनी, शीशे के पार अँधेरा, नीचे पानी में ठहरी सुनहरी चमक—</p>\n<p>धीरे-धीरे सब पीछे छूटता गया।</p>\n<p>फिर रोशनी बुझ गई।</p>\n<p>“मेरे साथ रहना।”</p>\n<p>नैना ने अँधेरे में फुसफुसाकर कहा।</p>\n<p>वह उसे कहीं जाने से रोक नहीं रही थी।</p>\n<p>बस उस क्षण में पूरा चाहती थी।</p>\n<p>“बस मेरे साथ रहना।”</p>\n<p>“मैं यहीं हूँ।”</p>\n<p>विक्रम ने उसे और करीब कर लिया।</p>\n<p>“आज रात कहीं नहीं जा रहा।”</p>\n<p>बाहर रात अपने समय से चल रही थी।</p>\n<p>अंदर दोनों उसे जितना हो सके रोक लेना चाहते थे।</p>\n<p>बाद में, जब कमरा फिर शांत हुआ, नैना की आँखों के किनारों से आँसू चुपचाप बह गए।</p>\n<p>न उसने उन्हें छिपाया।</p>\n<p>न विक्रम ने पोंछने की कोशिश की।</p>\n<p>बस उसे थामे रहा—और पहली बार उस रात ख़ुद को पूरी तरह यह महसूस करने दिया कि सुबह उससे क्या छीनने वाली है।</p>\n<p>उसके बाद भी दोनों बहुत देर तक अलग नहीं हुए।</p>\n<p>जैसे जो पहले हिलेगा वही रात को आगे बढ़ा देगा।</p>\n<p>नैना की उँगलियाँ उसकी पीठ पर बिना किसी मकसद के धीमी रेखाएँ बनाती रहीं।</p>\n<p>“एक दिन का भी अफसोस नहीं है मुझे।”</p>\n<p>नैना ने आख़िर कहा।</p>\n<p>आवाज़ भरी हुई थी।</p>\n<p>“एक भी नहीं।”</p>\n<p>कुछ पल बाद—</p>\n<p>“आज का भी नहीं… जबकि ये शायद ज़िंदगी की सबसे मुश्किल चीज़ है जो मैंने की है।”</p>\n<p>“मुझे भी नहीं।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>वे ठीक से सोए ही नहीं।</p>\n<p>रात के बचे हुए घंटे एक-दूसरे के पास लेटे, कभी बातें करते, कभी लंबे समय तक चुप रहते हुए गुज़रते रहे।</p>\n<p>वे ऐसी यादें एक-दूसरे को सौंपते रहे जिन्हें दोनों चाहते थे कि दूसरा भूल न जाए; ऐसी छोटी स्वीकारोक्तियाँ भी, जिनके लिए इतने महीनों में कभी सही वक्त नहीं मिला था।</p>\n<p>नैना ने उसे अपने बचपन के उन जन्मदिनों के बारे में बताया जिनमें पिता घर नहीं आ पाए थे—इतने कि अब वह आसानी से गिन भी नहीं सकती थी। जन्मदिन जैसी छोटी चीज़ के लिए छुट्टी कहाँ मिलती थी।</p>\n<p>किसी ऐसे ही जन्मदिन पर उसने ख़ुद से वादा किया था कि जिसे वह प्यार करेगी, उसे कभी उस तरह के इंतज़ार का अर्थ नहीं जानने देगी।</p>\n<p>विक्रम ने कहा—</p>\n<p>“जान चुकी हो।”</p>\n<p>नैना उसकी ओर देखती रही।</p>\n<p>“मेरी पोस्टिंग के हर ख़ामोश दिन में तुमने उसी इंतज़ार का थोड़ा-सा हिस्सा जिया है।”</p>\n<p>विक्रम ने नज़रें झुका लीं।</p>\n<p>“और कभी-कभी ख़ुद से नफ़रत होती है कि तुमसे इतना प्यार करके भी वही चीज़ तुम्हें दे दी जिससे तुम हमेशा बचना चाहती थीं।”</p>\n<p>नैना ने अपनी हथेली उसके सीने पर रख दी।</p>\n<p>ठीक दिल के ऊपर।</p>\n<p>“ख़ुद से नफ़रत मत करना।”</p>\n<p>“नैना—”</p>\n<p>“हालात से करो। बाबा के डर से कर लो, अगर गुस्सा कहीं रखना ही है।”</p>\n<p>उसकी हथेली वहीं रही।</p>\n<p>“लेकिन अपने उन हिस्सों से मत करना जिन्होंने मुझे ये महीने दिए।”</p>\n<p>“ये मेरी ज़िंदगी के सबसे अच्छे महीने हैं।”</p>\n<p>एक आँसू निकल गया।</p>\n<p>“इन्हें अपनी माफ़ी मत बनाना, विक्रम।”</p>\n<p>रात और गहरी हुई।</p>\n<p>और उसी गहराई में, बहुत देर तक ख़ुद को थामे रहने के बाद, विक्रम के भीतर भी कुछ आख़िर टूट गया।</p>\n<p>पूरी शाम वह सँभला रहा था।</p>\n<p>डिनर पर।</p>\n<p>कमरे में।</p>\n<p>नैना के आँसुओं के बीच।</p>\n<p>हर जगह वही इंसान जो उसके लिए अडिग रहता आया था।</p>\n<p>लेकिन अब, जब नैना की साँसें उसकी छाती पर कुछ शांत हुईं, उसके भीतर की पकड़ अचानक ढीली पड़ गई।</p>\n<p>वह बिना सोचकर करवट बदला और अपना सिर नैना की गोद में रख दिया।</p>\n<p>ठीक वैसे—</p>\n<p>जैसे नैना न जाने कितनी बार उसकी गोद में रख चुकी थी।</p>\n<p>नैना एक पल को ठिठकी।</p>\n<p>फिर उसकी उँगलियाँ अपने आप विक्रम के बालों में उतर गईं।</p>\n<p>वही लय।</p>\n<p>वही धीरज।</p>\n<p>बस इस बार सहारा देने वाला और सहारा लेने वाला बदल गए थे।</p>\n<p>और विक्रम रो पड़ा।</p>\n<p>सचमुच।</p>\n<p>नैना ने उसे इतने महीनों में इस तरह कभी नहीं देखा था।</p>\n<p>उसके कंधे काँप रहे थे।</p>\n<p>आवाज़ लगभग नहीं थी।</p>\n<p>और उसी वजह से उसका रोना और ज़्यादा गहरा लगता था—जैसे कोई इंसान जिसे ज़िंदगी ने रोना भी ठीक से नहीं सिखाया, पहली बार बिना तरीका जाने अपने दुख के सामने हार गया हो।</p>\n<p>नैना का अपना दुख कुछ देर के लिए पीछे चला गया।</p>\n<p>उसने बस उसके बालों में हाथ फेरते हुए कहा—</p>\n<p>“मैं हूँ।”</p>\n<p>विक्रम ने आँखें नहीं उठाईं।</p>\n<p>“छोड़ दो ख़ुद को।”</p>\n<p>उसकी उँगलियाँ उसके बालों में चलती रहीं।</p>\n<p>“मैं यहीं हूँ।”</p>\n<p>काफी देर बाद विक्रम ने टूटी हुई आवाज़ में कहा—</p>\n<p>“मुझे नहीं आता ये।”</p>\n<p>“शायद बचपन के बाद कभी इस तरह नहीं रोया।”</p>\n<p>उसने साँस खींची।</p>\n<p>“पता नहीं क्या करना होता है।”</p>\n<p>“कुछ नहीं करना होता।”</p>\n<p>नैना ने कहा।</p>\n<p>“बस होने दो।”</p>\n<p>उसकी हथेली उसके सिर पर टिकी रही।</p>\n<p>“जब तक ख़त्म नहीं होता, मैं कहीं नहीं जा रही।”</p>\n<p>विक्रम बहुत देर वैसे ही रहा।</p>\n<p>धीरे-धीरे उसके कंधों का काँपना कम हुआ।</p>\n<p>लेकिन उसके बाद भी दोनों ने काफी देर कुछ नहीं कहा।</p>\n<p>उस रात पहली बार नैना की ताकत ने विक्रम को उसी तरह थामा था—</p>\n<p>जैसे इतने समय से उसकी ताकत नैना को थामती आई थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>भोर के करीब कमरे के बाहर आसमान का सबसे दूर वाला किनारा हल्का होने लगा।</p>\n<p>और जैसे ही रात के ख़त्म होने का पहला सबूत दिखाई दिया, नैना की बची हुई हिम्मत भी टूट गई।</p>\n<p>इस बार आँसू रेस्तराँ वाले नहीं थे।</p>\n<p>न सँभले हुए।</p>\n<p>न चुपचाप पोंछे जा सकने वाले।</p>\n<p>उसका पूरा शरीर काँप रहा था।</p>\n<p>“मुझे नहीं पता तुम्हें अलविदा कैसे कहूँ।”</p>\n<p>काफी देर बाद वह बोल पाई।</p>\n<p>आवाज़ कच्ची थी।</p>\n<p>“दिमाग को समझाने की कोशिश कर रही हूँ कि ये आख़िरी बार है।”</p>\n<p>उसने विक्रम को कसकर पकड़ लिया।</p>\n<p>“कुछ दिनों के लिए आख़िरी नहीं।”</p>\n<p>साँस टूटी।</p>\n<p>“आख़िरी।”</p>\n<p>उसकी आँखें बंद थीं।</p>\n<p>“इस पूरी ज़िंदगी में।”</p>\n<p>विक्रम की पकड़ उसके चारों ओर और कस गई।</p>\n<p>“इतनी बड़ी बात दिमाग में टिकती ही नहीं। हर बार पकड़ने की कोशिश करती हूँ तो फिसल जाती है।”</p>\n<p>“मुझे पता है।”</p>\n<p>अब विक्रम की आवाज़ भी स्थिर नहीं थी।</p>\n<p>“मैं भी पूरी रात उसे पकड़ने की कोशिश कर रहा हूँ।”</p>\n<p>नैना उसके सीने से लगी रही।</p>\n<p>“अब कभी किसी छोटी बात पर डिनर के बीच तुमसे लड़ूँगी नहीं।”</p>\n<p>उसकी आवाज़ आँसुओं में टूट रही थी।</p>\n<p>“फिर कभी इस तरह सो नहीं पाऊँगी… तुम्हारा हाथ मेरे बालों में।”</p>\n<p>एक साँस।</p>\n<p>“तुम्हारी आवाज़ फोन के दूसरी तरफ फिर कभी वैसे नहीं सुनूँगी जैसे इतने महीनों से सुनती आई हूँ।”</p>\n<p>उसने आँखें बंद कर लीं।</p>\n<p>“एक इंसान कैसे जीता है ये जानते हुए कि उसकी ज़िंदगी की इतनी सारी चीज़ें एक ही रात में आख़िरी बार हो रही हैं?”</p>\n<p>विक्रम ने उसे और करीब कर लिया।</p>\n<p>अब दोनों काँप रहे थे।</p>\n<p>“तो जितना बचा है उसे अंत गिनने में मत खर्च करो।”</p>\n<p>उसने मुश्किल से कहा।</p>\n<p>“बस यहीं रहो।”</p>\n<p>नैना ने सिर उठाया।</p>\n<p>“अभी।”</p>\n<p>विक्रम ने उसकी आँखों में देखा।</p>\n<p>“इसके बाद कुछ नहीं।”</p>\n<p>उसने माथा उसके माथे से लगा दिया।</p>\n<p>“बस ये।”</p>\n<p>नैना ने सिर हिला दिया।</p>\n<p>फिर दोनों चुप हो गए।</p>\n<p>बाहर रोशनी धीरे-धीरे बदलती रही।</p>\n<p>अंदर हर गुज़रता सेकंड दोनों को उतनी ही साफ़ क्रूरता से बता रहा था कि यह समय दोबारा कभी उनका नहीं होगा।</p>\n<p>बहुत देर बाद नैना ने कहा—</p>\n<p>“आई लव यू।”</p>\n<p>विक्रम की आँखें बंद हो गईं।</p>\n<p>“एक बार और ठीक से कहना था।”</p>\n<p>उसने उसके चेहरे को छुआ।</p>\n<p>“जब तक मुझे कहने का हक है।”</p>\n<p>आँसू फिर बह निकले।</p>\n<p>“मैं तुमसे प्यार करती हूँ, विक्रम।”</p>\n<p>फिर धीरे-धीरे—</p>\n<p>“आज के बाद मैं जो भी बनूँ… किसी की पत्नी, किसी की माँ… मेरे भीतर कहीं एक हिस्सा ज़िंदगी भर तुमसे प्यार करता रहेगा।”</p>\n<p>उसकी आवाज़ लगभग फुसफुसाहट में बदल गई।</p>\n<p>“चाहे मुझे उसकी इजाज़त हो या नहीं।”</p>\n<p>विक्रम की आँखों से भी अब आँसू निकल आए।</p>\n<p>इस बार उसने उन्हें रोका नहीं।</p>\n<p>“मैं भी तुमसे प्यार करता हूँ।”</p>\n<p>उसने कहा।</p>\n<p>“और ज़िंदगी भर करता रहूँगा।”</p>\n<p>उसने नैना का हाथ अपने हाथ में ले लिया।</p>\n<p>“दस साल बाद का मैं हो या तीस साल बाद का… मेरे किसी भी रूप के भीतर यह सुबह कहीं न कहीं रहेगी।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>जब आख़िर नैना कपड़े पहनने लगी तो उसकी उँगलियाँ इतनी काँप रही थीं कि कुर्ते के बटन ठीक से बंद नहीं हो रहे थे।</p>\n<p>विक्रम उसके सामने आकर खड़ा हो गया।</p>\n<p>कुछ नहीं कहा।</p>\n<p>बस एक-एक बटन धीरे-धीरे बंद कर दिया।</p>\n<p>उसके अपने हाथ भी पूरी तरह स्थिर नहीं थे।</p>\n<p>अब दोनों रो रहे थे।</p>\n<p>छिपाने को कुछ नहीं बचा था।</p>\n<p>दो लोग आख़िरी बार एक-दूसरे को कपड़े पहना रहे थे—</p>\n<p>उसी कोमलता से</p>\n<p>जिससे कभी पहली बार उन्होंने अपने बीच की सारी सावधानियाँ उतारी थीं।</p>\n<p>दरवाज़े पर पहुँचकर नैना रुक गई।</p>\n<p>फिर पलटी।</p>\n<p>विक्रम वहीं खड़ा था।</p>\n<p>उसने हाथ बढ़ाकर उसके चेहरे को छुआ।</p>\n<p>उँगलियाँ धीरे-धीरे उसके चेहरे पर चलीं—</p>\n<p>जैसे आँखों से याद कर लेना काफी न हो,</p>\n<p>जैसे त्वचा भी अपनी अलग स्मृति रखती हो।</p>\n<p>“ये अलविदा है।”</p>\n<p>इस बार उसने शब्द पूरा कहा।</p>\n<p>न उससे बची।</p>\n<p>न उसे नरम किया।</p>\n<p>“अगली बार तक नहीं।”</p>\n<p>उसकी आवाज़ टूट गई।</p>\n<p>“जल्दी मिलेंगे भी नहीं।”</p>\n<p>वह उसे देखती रही।</p>\n<p>“अलविदा, विक्रम।”</p>\n<p>एक आँसू उसके चेहरे से उतर गया।</p>\n<p>“उस हर ज़िंदगी के लिए भी… जो अब हमें साथ नहीं मिलेगी।”</p>\n<p>विक्रम ने उसका हाथ अपने चेहरे पर कुछ पल और रहने दिया।</p>\n<p>“अलविदा, नैना।”</p>\n<p>फिर उसकी हथेली को धीरे से पकड़ा।</p>\n<p>“हर एक दिन के लिए शुक्रिया।”</p>\n<p>उसकी आवाज़ भर्रा गई।</p>\n<p>“मैं ज़िंदगी भर इस बात के लिए शुक्रगुज़ार रहूँगा कि मुझे वे दिन मिले… ये जानते हुए भी कि आख़िर में यह सुबह आने वाली थी।”</p>\n<p>नैना एक कदम आगे बढ़ी।</p>\n<p>और उससे लिपट गई।</p>\n<p>इस बार उस आलिंगन में कुछ भी सँभला हुआ नहीं था।</p>\n<p>विक्रम ने भी उसे उतनी ही ताकत से पकड़ लिया।</p>\n<p>दरवाज़े पर दोनों बहुत देर वैसे ही खड़े रहे।</p>\n<p>किसी की हिम्मत नहीं हुई पहले हाथ ढीले करने की।</p>\n<p>नैना के आँसू उसकी शर्ट में उतरते रहे।</p>\n<p>विक्रम के आँसू उसके बालों में।</p>\n<p>अब किसी को मजबूत दिखना नहीं था।</p>\n<p>न एक-दूसरे के लिए।</p>\n<p>न अपने लिए।</p>\n<p>आख़िर नैना गई।</p>\n<p>पहला कदम उसी ने पीछे लिया।</p>\n<p>फिर दूसरा।</p>\n<p>विक्रम दरवाज़े पर खड़ा रहा।</p>\n<p>उसका हाथ अपनी पकड़ से निकलते महसूस किया।</p>\n<p>उसके कदम कॉरिडोर में धीरे-धीरे दूर होते सुने—जैसे बजरी पर कोई गाड़ी धीमी पड़ती जाए।</p>\n<p>जब तक वह दिखाई देती रही, देखता रहा।</p>\n<p>फिर वह मुड़ी।</p>\n<p>और चली गई।</p>\n<p>विक्रम फिर भी वहीं खड़ा रहा।</p>\n<p>बहुत देर तक।</p>\n<p>चेहरा आँसुओं से भीगा हुआ।</p>\n<p>बाहर सुबह की धूसर रोशनी फैल रही थी।</p>\n<p>और उसे मालूम था—</p>\n<p>नैना का हाथ उसकी पकड़ से छूटने का वह क्षण,</p>\n<p>कॉरिडोर में दूर होती उसकी आहट,</p>\n<p>उस सुबह का वही फीका रंग—</p>\n<p>यही आख़िरी स्मृति थी जो ज़िंदगी ने उन दोनों को एक-दूसरे की मौजूदगी में दी थी।</p>\n<p>इसके बाद जो कुछ रहेगा,</p>\n<p>वह याद होगा।</p>\n<p>और याद, चाहे कितनी भी सावधानी से बचाकर रखी जाए, किसी मौजूद इंसान की जगह नहीं ले सकती।</p>\n<p>जैसे आग की तस्वीर में उसका आकार तो बचा रहता है—</p>\n<p>उसकी गर्मी नहीं।</p>"}, {"chapter": 34, "title": "अंतराल — फाइल का दूसरा पन्ना", "content": "<h1>अंतराल — फाइल का दूसरा पन्ना</h1>\n<p>वही फाइल।</p>\n<p>बस अब कई साल बाद उसमें एक पन्ना और जुड़ चुका था।</p>\n<p>इस बार एक दूसरी औरत का नाम था।</p>\n<p><b>नैना।</b></p>\n<p>लगभग दो साल।</p>\n<p>और पिछली एंट्री से कहीं ज़्यादा गंभीर रिश्ता।</p>\n<p>एक ऐसी सगाई जो कभी औपचारिक रूप नहीं ले सकी; ऐसा रिश्ता जिसे उन दोनों में से किसी ने ख़त्म नहीं किया था—एक पिता के इनकार ने कर दिया।</p>\n<p>फाइल लिखने वाला इंसान आम तौर पर भावनाओं के लिए जगह नहीं छोड़ता था। उसकी भाषा सूखी, नपी-तुली और लगभग चिकित्सकीय हुआ करती थी।</p>\n<p>लेकिन इस बार उसने नियम तोड़ा था।</p>\n<p>उसने लिखा—</p>\n<p><b>“कुछ अंत ऐसे होते हैं जिनका निशान इंसान ज़िंदगी भर ढोता है, मगर बाद में कभी ठीक से किसी को बता नहीं पाता कि वह निशान आया कहाँ से था।”</b></p>\n<p>इस बार हाशिये पर लिखी टिप्पणी पिछली बार से लंबी थी।</p>\n<p><b>अब दो।</b></p>\n<p><b>दोनों सच्चे रिश्ते।<br/>\nदोनों खो गए।<br/>\nऔर दोनों में उसकी ग़लती नहीं थी।</b></p>\n<p>फिर आख़िर में—</p>\n<p><b>इस बार देखना वह ख़ुद को दोबारा कैसे खड़ा करता है।</b></p>\n<p><b>उसके बारे में असली बात शायद उसके टूटने से नहीं—वापस बनने के तरीके से पता चलेगी।</b></p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>"}, {"chapter": 35, "title": "अध्याय 32 — घात", "content": "<h1>अध्याय 32 — घात</h1>\n<p>उस आख़िरी सुबह के अगले ही दिन विक्रम चला गया।</p>\n<p>काग़ज़ों में उसकी छुट्टी के लगभग दो हफ्ते अभी बाकी थे।</p>\n<p>सूरज आँगन की दीवार के ऊपर ठीक से चढ़ा भी नहीं था जब उसकी माँ ने उसे कमरे में वर्दी तह करके बैग में रखते देखा। वह दरवाज़े पर कुछ देर बिना बोले खड़ी रही—उस खास ख़ामोशी में जिसमें माँएँ अक्सर बेटे के कुछ कहने से बहुत पहले समझ जाती हैं कि उसके भीतर कुछ ठीक नहीं है।</p>\n<p>“तेरी छुट्टी तो अभी बाकी है।”</p>\n<p>विक्रम ने बैग से नज़र नहीं उठाई।</p>\n<p>“इतनी जल्दी वापस क्यों जा रहा है?”</p>\n<p>“बुलावा आया है, माँ।”</p>\n<p>उसके हाथ कपड़े तह करते रहे—ज़रूरत से कहीं ज़्यादा करीने से।</p>\n<p>“कुछ काम आ गया है। रिपोर्ट करना पड़ेगा।”</p>\n<p>माँ काफी देर उसे देखती रही।</p>\n<p>उसे यकीन नहीं हुआ था।</p>\n<p>यह विक्रम भी जानता था।</p>\n<p>लेकिन उसने अगला सवाल नहीं पूछा।</p>\n<p>माँ के भीतर किसी पुराने अनुभव ने उसे बता दिया था कि आज अगर वह बेटे के भीतर का दरवाज़ा जबरन खोलेगी, तो जो हाथ आएगा, वह जानकारी नहीं—बेटे की चोट होगी।</p>\n<p>गेट पर उसने बस लड्डुओं का छोटा-सा डिब्बा उसके हाथ में थमा दिया।</p>\n<p>डिब्बे से घी की महक आ रही थी।</p>\n<p>फिर उसका चेहरा दोनों हथेलियों में लिया।</p>\n<p>सामान्य से कुछ पल ज़्यादा।</p>\n<p>और जाने दिया।</p>\n<p>उसी दोपहर विक्रम दिल्ली से श्रीनगर की फ्लाइट में था।</p>\n<p>उड़ान भरते ही उसने खिड़की का शटर नीचे खींच लिया।</p>\n<p>नीचे वह शहर था जिसे वह अब नहीं देखना चाहता था।</p>\n<p>शाम तक वह कैंप पहुँच गया।</p>\n<p>नॉर्थ-ईस्ट का कार्यकाल पूरा होते ही टीम को वापस कश्मीर भेज दिया गया था—उन्हीं पहाड़ों में, जिन्हें वह कभी पीछे छोड़ आया था।</p>\n<p>छुट्टी ख़त्म होने से लगभग दो हफ्ते पहले—जब वहाँ किसी को उसके लौटने की उम्मीद तक नहीं थी।</p>\n<p>और उसके ठीक तीसरे दिन—</p>\n<p>जिस बात का ज़िक्र उसने वहाँ किसी से नहीं किया—</p>\n<p>गुरुग्राम में, श्रीनगर से करीब नौ सौ किलोमीटर दक्षिण में, लगभग उस दिशा के ठीक उलट जहाँ वह खड़ा था,</p>\n<p>नैना की शादी हो रही थी।</p>\n<p>उसी दिन ऑपरेशन बिगड़ गया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>इंटेलिजेंस के मुताबिक एलओसी के पास एक छोटे-से गाँव के ऊपर की रिज पर चार आतंकी मौजूद थे। विक्रम की टीम को कुछ किलोमीटर दूर हेलिकॉप्टर से उतारा गया था; आगे उन्हें पैदल बढ़कर उस छोटे समूह को सीमा पार निकलने से पहले ट्रैक करके रोकना था।</p>\n<p>काग़ज़ पर ऑपरेशन सीधा था।</p>\n<p>चार आतंकी।</p>\n<p>लोकेट करो।</p>\n<p>रास्ता काटो।</p>\n<p>एंगेज करो।</p>\n<p>लेकिन ज़मीन ने ब्रीफिंग की बात नहीं मानी।</p>\n<p>चार नहीं थे।</p>\n<p>दस थे।</p>\n<p>और वे रास्ते के तीन ओर पहले से पोज़िशन लेकर बैठे थे।</p>\n<p>विक्रम के दस जवान जैसे ही ट्री-लाइन से पहले वाले आख़िरी खुले हिस्से में पहुँचे, तीन दिशाओं से एक साथ भारी फायर खुल गया।</p>\n<p>जो थोड़ी-बहुत आड़ ज़मीन दे सकती थी, जवान उसी से चिपक गए।</p>\n<p>ब्रीफिंग वाले चार आतंकियों ने शायद ड्रॉप से पहले ही छह और लोगों के साथ लिंक-अप कर लिया था—ऐसे छह लोग जिनकी मौजूदगी की कोई सूचना नहीं थी।</p>\n<p>“सर, पीछे हटना पड़ेगा!”</p>\n<p>गोलियों के शोर के बीच सूबेदार साहब की आवाज़ आई। उनकी बाँह पर गोली छूकर निकल चुकी थी और खून बह रहा था।</p>\n<p>“इस तरफ हम पूरे खुले हैं। यहीं रुके तो कैज़ुअल्टी बहुत होगी। रिज तक वापस जाकर सपोर्ट बुलाना पड़ेगा।”</p>\n<p>“कोई पीछे नहीं हटेगा।”</p>\n<p>विक्रम की आवाज़ सपाट थी।</p>\n<p>इतनी निश्चित कि उसमें बहस की कोई जगह सुनाई नहीं देती थी।</p>\n<p>“हर जवान जितनी आड़ मिल सकती है, ले। मेरे मूव करते ही कवर फायर चाहिए।”</p>\n<p>उसने सामने देखा।</p>\n<p>“मैं अंदर जा रहा हूँ।”</p>\n<p>“सर—”</p>\n<p>“ऑर्डर है, सूबेदार साहब।”</p>\n<p>इसके बाद उसने जवाब का इंतज़ार नहीं किया।</p>\n<p>पास वाले जवान से एलएमजी ली, अपनी एके-47 पीठ पर डाली और आड़ से बाहर निकल गया।</p>\n<p>पहले कुछ सेकंड में ही तीन गोलियाँ उसके सिर से एक फुट से भी कम दूरी पर हवा चीरती हुई निकलीं।</p>\n<p>वह फिर भी आगे बढ़ता रहा।</p>\n<p>छोटे, नियंत्रित बर्स्ट।</p>\n<p>एक कमज़ोर-सी आड़ से दूसरी तक।</p>\n<p>उसके पीछे जवान जितना संभव था कवर फायर दे रहे थे, लेकिन उनकी आँखों में जो था उसे आदेश से छिपाया नहीं जा सकता था।</p>\n<p>वे अपने अफसर को गोलियों के बीच सीधा आगे बढ़ते देख रहे थे।</p>\n<p>विक्रम ने कुछ ही मिनटों में दूरी कम कर ली।</p>\n<p>पीछे खड़े लोगों को वे मिनट कहीं ज़्यादा लंबे लगे।</p>\n<p>करीब पहुँचकर उसने पोज़िशन साफ़ की।</p>\n<p>चार आतंकी वहीं गिरे।</p>\n<p>बाकी पेड़ों की ओर टूटकर भाग गए।</p>\n<p>जिस लड़ाई को उन्होंने आसान समझा था, उसकी कीमत अचानक उनके अनुमान से कहीं ज़्यादा हो गई थी।</p>\n<p>कुछ मिनट बाद विक्रम के जवान उसके पास पहुँचे तो उनमें जीत का वह अचानक फूट पड़ने वाला उन्माद था जो मौत को बहुत करीब से देखकर बच निकलने के बाद आता है—कोई ज़ोर से बोल रहा था, किसी ने उसकी पीठ थपथपाई, कोई अब भी एड्रेनालिन में हँस रहा था।</p>\n<p>लेकिन सूबेदार साहब उस जश्न में शामिल नहीं हुए।</p>\n<p>वे कुछ दूरी पर खड़े विक्रम को देखते रहे।</p>\n<p>उनके चेहरे पर राहत बहुत कम थी।</p>\n<p>और चिंता उससे कहीं ज़्यादा।</p>\n<p>एक घंटे के भीतर उन्होंने पूरी घटना कमांडिंग ऑफिसर को रिपोर्ट कर दी।</p>\n<p>नियम यही माँगता था।</p>\n<p>और नियम न भी माँगता—</p>\n<p>तो उनका ज़मीर माँगता।</p>\n<p>दो दिन बाद विक्रम को सीओ के ऑफिस में बुलाया गया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कर्नल करीब छह फुट के थे। बालों पर सफ़ेदी लगभग पूरी तरह उतर चुकी थी, मगर शरीर अब भी सैनिक की तरह सधा हुआ था। चेहरे के दाहिने हिस्से पर पुरानी मुठभेड़ का एक पतला निशान था जिसके बारे में उन्होंने अपने नीचे काम करने वाले किसी मातहत को कभी कुछ नहीं बताया था।</p>\n<p>सिर पर मैरून बेरेट।</p>\n<p>उस पर पैरा कमांडो का चिन्ह।</p>\n<p>दाहिनी छाती पर <b>बलिदान बैज</b>—कमांडो डैगर और उसके ऊपर उठे पंख।</p>\n<p>सीने पर वर्षों की सर्विस के मेडल।</p>\n<p>उनमें सेना मेडल की पट्टी।</p>\n<p>और सबसे अलग—</p>\n<p><b>कीर्ति चक्र</b> का रिबन।</p>\n<p>ऐसा सम्मान, जिसे पाने के लिए बहुत कम अफसर ज़िंदा बचते हैं।</p>\n<p>यह उस करियर की निशानी थी जिसके बारे में ज़्यादातर लोग सिर्फ पढ़ते हैं।</p>\n<p>उनकी आवाज़ में भी वही वज़न था—धीमी, निश्चित, बिना किसी जल्दबाज़ी के; ऐसे इंसान की आवाज़, जिसे हुक्म मनवाने के लिए उसे कभी ऊँचा करने की ज़रूरत नहीं पड़ी थी।</p>\n<p>ऑफिस में पुराना पंखा ऊपर बेकार-सा घूम रहा था। पीछे फाइलिंग कैबिनेट से पुराने काग़ज़ और गन ऑयल की मिली-जुली गंध आ रही थी। छोटी-सी खिड़की के बाहर बजरी पर चलते बूटों की आवाज़ कभी-कभी भीतर तक पहुँच जाती।</p>\n<p>कर्नल अपनी सर्विस में काफी जवान अफसरों की बहादुरी और बेवकूफ़ी—और दोनों के बीच की बेहद पतली रेखा—देख चुके थे।</p>\n<p>विक्रम के बैठने से पहले ही उन्हें अंदाज़ा था कि सामने किस तरह की परेशानी है।</p>\n<p>“बैठो, विक्रम।”</p>\n<p>यूनिट के भीतर निजी बातचीत में उन्होंने कभी किसी जूनियर को रैंक से नहीं पुकारा था।</p>\n<p>उनका मानना था—रैंक इंसान पहनता है, नाम इंसान होता है; और यूनिट, अनुशासन की जगह होने से पहले, उन लोगों का घर भी होती है जो उसमें साथ जीते हैं।</p>\n<p>विक्रम बैठ गया।</p>\n<p>“बताओ वहाँ क्या हुआ।”</p>\n<p>“सर, ऑपरेशन सफल रहा। चार कन्फर्म्ड किल। हमारी तरफ कोई कैज़ुअल्टी नहीं।”</p>\n<p>“मैंने रिज़ल्ट नहीं पूछा।”</p>\n<p>कर्नल की आवाज़ अब भी धीमी थी।</p>\n<p>“मैंने पूछा—हुआ क्या?”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“तुम्हारे दस जवान खुले इलाके में पिन-डाउन थे। तुम्हारे सूबेदार साहब टैक्टिकल विदड्रॉ की सलाह दे रहे थे। और तुमने मशीनगन उठाई और अकेले तीन तरफ से आती फायरिंग में चल पड़े।”</p>\n<p>वह थोड़ा आगे झुके।</p>\n<p>“क्यों?”</p>\n<p>“काम हो गया, सर।”</p>\n<p>“वह जवाब नहीं है।”</p>\n<p>अब आवाज़ में धार आई।</p>\n<p>“वह नतीजा है।”</p>\n<p>कमरे में कुछ पल सिर्फ पंखे की टिक-टिक सुनाई दी।</p>\n<p>“तुम्हें अंदाज़ा है तुमने वहाँ क्या जोखिम लिया?”</p>\n<p>कर्नल ने कहा।</p>\n<p>“सिर्फ अपनी जान का नहीं।”</p>\n<p>विक्रम की आँखें उनकी ओर उठीं।</p>\n<p>“तुम्हारे पीछे दस जवान थे। तुम्हें फॉलो कर रहे थे। भरोसा करके कि उन्हें कमांड करने वाला अफसर अभी भी इस बात की परवाह करता है कि वे अपने घर वापस जाएँ।”</p>\n<p>आवाज़ पहली बार ऊँची हुई।</p>\n<p>“अगर तुम उस मैदान में गिर जाते तो उन दस जवानों का क्या होता? बीच फायरफाइट में बिना लीडर के—ऐसे दुश्मन के सामने जिसकी संख्या ब्रीफिंग से दोगुनी से भी ज़्यादा निकली?”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>“इसे बहादुरी कैसे कहूँ मैं?”</p>\n<p>कर्नल की आँखें उस पर टिकी थीं।</p>\n<p>“बहादुरी कीमत समझती है, विक्रम। मिशन माँगे तो वह कीमत चुकाती भी है।”</p>\n<p>एक पल।</p>\n<p>“तुमने जो किया वह बहादुरी नहीं थी।”</p>\n<p>फिर साफ़ शब्दों में—</p>\n<p>“वह लापरवाही थी जिसने बहादुरी की वर्दी पहन रखी थी।”</p>\n<p>विक्रम का चेहरा नहीं बदला।</p>\n<p>“हिम्मत और बेवकूफ़ी के बीच फ़र्क़ होता है। मेरे नीचे काम करने वाले हर अफसर से मैं उम्मीद करता हूँ कि उसे ठीक-ठीक मालूम हो वह रेखा कहाँ है।”</p>\n<p>कर्नल ने उसे देखते हुए कहा—</p>\n<p>“तुम वह रेखा भूल गए।”</p>\n<p>“रैम्बो फिल्मों में बनते हैं, विक्रम। फौज में हीरो नहीं होते—टीम होती है, और टीम प्रोटोकॉल से चलती है।”</p>\n<p>कमरे में ख़ामोशी फैल गई।</p>\n<p>विक्रम ने अपने हाथों की तरफ देखा—वही हाथ जिनसे कुछ दिन पहले नैना की उँगलियाँ छूटी थीं।</p>\n<p>और वही ख़ामोशी उस सवाल का जवाब थी जो कर्नल ने अभी पूछा भी नहीं था।</p>\n<p>कुछ देर बाद उनकी आवाज़ फिर धीमी हो गई।</p>\n<p>“तुम्हारी ज़िंदगी में अभी कुछ ऐसा चल रहा है?”</p>\n<p>विक्रम स्थिर रहा।</p>\n<p>“जिसकी वजह से अपनी जान खर्च कर देना तुम्हें जितना मुश्किल लगना चाहिए… उतना मुश्किल नहीं लग रहा?”</p>\n<p>कोई जवाब नहीं।</p>\n<p>कर्नल ने धीरे से सिर हिलाया।</p>\n<p>उन्हें जवाब मिल चुका था।</p>\n<p>“अगले आदेश तक तुम कोई ऑपरेशन लीड नहीं करोगे।”</p>\n<p>विक्रम ने उनकी ओर देखा।</p>\n<p>“ऑपरेशन का हिस्सा भी नहीं बनोगे। कैंप के भीतर ट्रेनिंग तक सीमित रहोगे।”</p>\n<p>उनकी आवाज़ फिर कठोर हो गई।</p>\n<p>“और इसे साफ़ समझ लो। दोबारा ऐसा हुआ तो अगली बार सिर्फ ट्रेनिंग तक सीमित नहीं रखूँगा। औपचारिक अनुशासनात्मक कार्रवाई शुरू होगी।”</p>\n<p>“यस, सर।”</p>\n<p>“हम डिसिप्लिन्ड फोर्स हैं। प्रोटोकॉल इसलिए होता है क्योंकि कई बार वही एक चीज़ ऑपरेशन और कत्लेआम के बीच खड़ी होती है।”</p>\n<p>कर्नल ने कहा।</p>\n<p>“किसी एक अफसर का निजी दुख यह तय नहीं करेगा कि उसके साथ खड़े दस दूसरे जवान अपने परिवारों तक लौटेंगे या नहीं।”</p>\n<p>“यस, सर।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दो महीने उसी तरह बीते।</p>\n<p>ड्रिल।</p>\n<p>रेंज।</p>\n<p>बार-बार दोहराई जाती ट्रेनिंग।</p>\n<p>और उसके अंत में कोई ऑपरेशन नहीं।</p>\n<p>कई दिनों में वह शांति गोलीबारी से ज़्यादा भारी लगती थी।</p>\n<p>दूसरे महीने के आख़िर में विक्रम ख़ुद कर्नल के ऑफिस पहुँचा।</p>\n<p>वही ठंडा कमरा।</p>\n<p>वही ऊपर टिक-टिक करता पंखा।</p>\n<p>बस फाइलिंग कैबिनेट पर पिछली बार से कुछ नई फाइलें और जुड़ चुकी थीं।</p>\n<p>“सर, ऑपरेशंस में वापस जाने की अनुमति चाहिए।”</p>\n<p>कर्नल ने काफी देर उसे देखा।</p>\n<p>“जा सकते हो।”</p>\n<p>विक्रम के चेहरे पर कोई प्रतिक्रिया आने से पहले उन्होंने आगे कहा—</p>\n<p>“लेकिन लीड नहीं करोगे।”</p>\n<p>“सर।”</p>\n<p>“अभी काफी समय तक नहीं।”</p>\n<p>उन्होंने साफ़ किया—</p>\n<p>“अब जिस भी ऑपरेशन में जाओगे, मेजर रुद्र प्रताप सिंह के अंडर जाओगे। वह लीड करेंगे। तुम उनके हर आदेश का पालन करोगे। बिना अपवाद।”</p>\n<p>“यस, सर।”</p>\n<p>“अगर एक बार भी सुना कि उनके आदेश से बाहर गए हो तो औपचारिक इन्क्वायरी शुरू करूँगा। और तुम्हें पता है आर्मी उसे हल्के में नहीं लेती।”</p>\n<p>“समझ गया, सर।”</p>\n<p>कर्नल की आवाज़ थोड़ी नरम हुई।</p>\n<p>“मैं तुम्हें छोटा दिखाने के लिए नहीं कर रहा ये।”</p>\n<p>कुछ क्षण के लिए सामने कमांडिंग ऑफिसर कम और उम्र में बड़ा कोई इंसान ज़्यादा दिखाई दिया।</p>\n<p>“मैं चाहता हूँ तुम इस वर्दी में लंबे समय तक रहो।”</p>\n<p>उन्होंने कहा।</p>\n<p>“और वह तब नहीं होगा अगर तुमने यह तय कर लिया कि तुम्हारी जान तुम्हारे बगल में खड़े जवान से कम कीमत रखती है।”</p>\n<p>विक्रम ने बस कहा—</p>\n<p>“यस, सर।”</p>\n<p>दो दिन बाद कर्नल ने विक्रम के पिता को ख़ुद फोन किया।</p>\n<p>औपचारिक बातें ख़त्म होते ही सीधे मुद्दे पर आए।</p>\n<p>“आपका बेटा उन बेहतरीन कमांडोज़ में से है जिन्हें कमांड करने का मुझे मौका मिला है।”</p>\n<p>दूसरी ओर कुछ क्षण चुप्पी रही।</p>\n<p>“मैं उसकी शिकायत करने के लिए फोन नहीं कर रहा। मैं इसलिए कर रहा हूँ क्योंकि मैं उसे खोना नहीं चाहता।”</p>\n<p>फिर—</p>\n<p>“मुझे लगता है, इसमें सिर्फ आप ही मेरी मदद कर सकते हैं।”</p>\n<p>“क्या हुआ है?”</p>\n<p>“अभी कुछ नहीं हुआ।”</p>\n<p>कर्नल ने कहा।</p>\n<p>“यही मेरी चिंता है।”</p>\n<p>उन्होंने शब्द सोचकर चुने।</p>\n<p>“वह अपनी जान को लेकर लापरवाह होने लगा है। मैंने ऐसे जवानों को पहले भी देखा है—जो भीतर कुछ ऐसा लिए घूमते हैं जिसका नाम नहीं लेना चाहते।”</p>\n<p>“मुझे वजह नहीं जाननी।”</p>\n<p>उन्होंने आगे कहा।</p>\n<p>“मुझे सिर्फ इतना चाहिए कि उसकी शादी कराइए।”</p>\n<p>दूसरी ओर फिर चुप्पी।</p>\n<p>“जल्दी।”</p>\n<p>कर्नल की आवाज़ अब बहुत शांत थी।</p>\n<p>“जिस इंसान को लगता है कि घर लौटने पर कोई उसका इंतज़ार कर रहा है, वह लड़ाई अलग तरह से लड़ता है।”</p>\n<p>एक ठहराव।</p>\n<p>“और जिस इंसान ने मान लिया हो कि लौटने के लिए कुछ है ही नहीं—वह अलग।”</p>\n<p>फिर साफ़ कहा—</p>\n<p>“मैं चाहता हूँ मेरा सबसे अच्छा कमांडो पहले तरीके से लड़े।”</p>\n<p>विक्रम के पिता ने जवाब देने में समय लिया।</p>\n<p>“मैं देख लूँगा, कर्नल साहब।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले चार महीने विक्रम मेजर रुद्र प्रताप सिंह की कमांड में रहा।</p>\n<p>कुछ ऑपरेशन हुए।</p>\n<p>ज़्यादातर समय नहीं।</p>\n<p>लंबी पेट्रोलिंग।</p>\n<p>पहाड़।</p>\n<p>घाटियाँ।</p>\n<p>ऐसा भूभाग जो कई-कई दिनों तक अपने भीतर कुछ नहीं देता—सिर्फ चलते रहने की माँग करता है।</p>\n<p>इस बार विक्रम आगे चलने वाला आदमी नहीं था।</p>\n<p>उसे किसी और के आदेश पर चलना था।</p>\n<p>और उसने चलना सीखा।</p>\n<p>उसने छुट्टी के लिए एक बार भी आवेदन नहीं किया।</p>\n<p>उसने यह फ़ैसला कभी ख़ुद से साफ़ शब्दों में नहीं कहा था, मगर उसके भीतर कहीं तय हो चुका था कि वह गुरुग्राम वापस नहीं जाना चाहता।</p>\n<p>न उस शहर में।</p>\n<p>न उन सड़कों पर।</p>\n<p>न ऐसी किसी जगह पर जहाँ किसी मोड़, किसी पार्क, किसी शाम या किसी साधारण रास्ते के कोने में नैना का नाम अब भी तह करके रखा हो।</p>\n<p>पहाड़ आसान थे।</p>\n<p>वे उससे कुछ नहीं पूछते थे।</p>\n<p>उन्हें नहीं पता था कि गुरुग्राम में कौन-सी सड़क कहाँ जाती है।</p>\n<p>किस बेंच के ऊपर कौन-सा पेड़ खड़ा है।</p>\n<p>किस कमरे की सुबह कैसी थी।</p>\n<p>और किस दिन, नौ सौ किलोमीटर दूर, किसी और की शादी हुई थी।</p>\n<p>इसलिए वह वहीं रहा।</p>\n<p>जहाँ चलते रहना ज़रूरी था।</p>\n<p>क्योंकि इंसान चलते हुए कई बार उस चीज़ से बच जाता है—</p>\n<p>जो उसके रुकते ही उसे ढूँढ़ लेती है।</p>\n<p>घात को लगभग छह महीने हो चुके थे जब कर्नल ने उसे फिर बुलाया।</p>\n<p>“छह महीने में एक दिन की भी छुट्टी नहीं ली।”</p>\n<p>उन्होंने बिना भूमिका के कहा।</p>\n<p>“क्यों?”</p>\n<p>“ज़रूरत नहीं है, सर।”</p>\n<p>“मैंने तुम्हारी राय नहीं माँगी।”</p>\n<p>विक्रम चुप हो गया।</p>\n<p>कर्नल ने कुछ पल उसे देखा।</p>\n<p>“कल सुबह आठ बजे।”</p>\n<p>विक्रम की भौंह हल्की उठी।</p>\n<p>“श्रीनगर से बाहर जाने वाली फ्लाइट में तुम्हें देखना चाहता हूँ।”</p>\n<p>फिर उन्होंने वह जगह भी बंद कर दी जहाँ विक्रम कोई बहाना रख सकता था।</p>\n<p>“ऑर्डर है, विक्रम।”</p>\n<p>“सुझाव नहीं।”</p>\n<p>विक्रम ने एक बार कुछ कहने के लिए मुँह खोला।</p>\n<p>फिर बंद कर लिया।</p>\n<p>सीधे आदेश से बहस करने की गुंजाइश नहीं थी।</p>\n<p>और उसके भीतर का कोई हिस्सा यह भी जानता था कि बहस से ज़्यादा से ज़्यादा वही होगा जो पिछले छह महीने से करता आया था—</p>\n<p>वापसी को कुछ देर और टाल देना।</p>\n<p>“यस, सर।”</p>\n<p>इस बार पहाड़ों ने उसे रोककर नहीं रखा।</p>\n<p>उसे वापस जाना था।</p>"}, {"chapter": 36, "title": "अध्याय 33 — दूसरा दरवाज़ा", "content": "<h1>अध्याय 33 — दूसरा दरवाज़ा</h1>\n<p>विक्रम ने आँगन में अपना बैग अभी ठीक से नीचे रखा भी नहीं था कि उसे समझ आ गया—इस छुट्टी में कुछ अलग है।</p>\n<p>मंगलवार की एक साधारण दोपहर के हिसाब से उसकी माँ कुछ ज़्यादा ही तैयार थी। अच्छी वाली रेशमी साड़ी पहन रखी थी, हाथों में सोने की चूड़ियाँ थीं जो धूप पड़ने पर चमक रही थीं। पिता भी बरामदे में रोज़ वाले पुराने कुर्ते की जगह इस्त्री की हुई साफ़ कमीज़ पहने बैठे थे।</p>\n<p>दोनों के चेहरे पर ज़रूरत से ज़्यादा सहज बने रहने की वही कोशिश थी जो अक्सर तब दिखाई देती है जब लोग किसी बातचीत को आपके आने से पहले ही कई बार अपने मन में दोहरा चुके हों।</p>\n<p>विक्रम ने बैग धीरे से नीचे रखा।</p>\n<p>“आप दोनों इतने तैयार क्यों हैं?”</p>\n<p>माँ ने उसकी आँखों में देखे बिना कहा—</p>\n<p>“आज दोपहर कहीं जाना है।”</p>\n<p>विक्रम कुछ पल रुका।</p>\n<p>“कहाँ?”</p>\n<p>“पटौदी। एक परिवार है वहाँ।”</p>\n<p>फिर जैसे असली बात अब बची ही नहीं थी—</p>\n<p>“लड़की है।”</p>\n<p>“माँ—”</p>\n<p>“तूने अभी पूरी बात सुनी भी नहीं।”</p>\n<p>उसकी माँ ने आवाज़ ऊँची नहीं की, मगर लहजे में इतनी जगह भी नहीं छोड़ी कि बेटा आसानी से निकल सके।</p>\n<p>“नहा। अच्छी वाली शर्ट-पैंट पहन। और हमारे साथ चल।”</p>\n<p>“बस एक दोपहर माँग रही हूँ, विक्रम।”</p>\n<p>विक्रम ने पिता की तरफ देखा।</p>\n<p>उनका चेहरा बिल्कुल सपाट था।</p>\n<p>फिर माँ की तरफ।</p>\n<p>वहाँ फ़ैसला पहले ही हो चुका था।</p>\n<p>उसे उसी क्षण समझ आ गया कि यह बात उसके बैग के आँगन में पहुँचने से बहुत पहले तय की जा चुकी है।</p>\n<p>उसने हल्की साँस छोड़ी।</p>\n<p>“ठीक है।”</p>\n<p>फिर—</p>\n<p>“एक दोपहर।”</p>\n<p>रिश्ता उसी तरह आया था जैसे उनके जैसे परिवारों में अक्सर आता था—पहले दोनों माँओं के बीच फोन, फिर तस्वीरों का लेन-देन, फिर दोनों तरफ से शुरुआती हामी के बाद लड़का-लड़की का मिलना।</p>\n<p>बस विक्रम के हिस्से की सूचना उसे घर पहुँचते ही मिली थी।</p>\n<p>उसने बहुत विरोध नहीं किया।</p>\n<p>उम्मीद भी नहीं रखी।</p>\n<p>नैना की शादी को लगभग छह महीने हो चुके थे, मगर उसका दर्द उतना हल्का नहीं हुआ था जितना उसने कभी सोचा था कि समय के साथ हो जाएगा। वह अब हर पल दिखाई नहीं देता था; बस भीतर कहीं पड़ा रहता था—जैसे गहरे कुएँ के तल में कोई पत्थर, जो ऊपर से दिखता नहीं, मगर वहाँ से कभी जाता भी नहीं।</p>\n<p>माँ इतने महीनों से उसके अपने लिए किसी को चुनने का इंतज़ार कर चुकी थी।</p>\n<p>अब उसका धैर्य ख़त्म हो गया था।</p>\n<p>और सच पूछा जाए तो—</p>\n<p>विक्रम जानता था कि वह अपनी माँ का एक दोपहर से कहीं ज़्यादा कर्ज़दार है।</p>\n<p>बस उसने यह बात उससे कही नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>श्रद्धा का घर पटौदी में था, उसके गाँव से करीब एक घंटे की दूरी पर।</p>\n<p>सादा, साफ़-सुथरा घर।</p>\n<p>सामने छोटा-सा बगीचा।</p>\n<p>आख़िरी रास्ता इतना सँकरा था कि गाड़ी धीमी चलानी पड़ी और सफ़र ने उम्मीद से ज़्यादा समय ले लिया।</p>\n<p>विक्रम ने अपनी वही एक अच्छी शर्ट-पैंट पहन ली थी, जो माँ ने सुबह से निकालकर रख दी थी।</p>\n<p>सड़क किनारे एक गुलमोहर खड़ा था—पत्तियाँ झड़ चुकी थीं, टहनियाँ खाली आसमान की ओर खुली हुई।</p>\n<p>विक्रम ने खिड़की से नज़र हटा ली।</p>\n<p>पूरे रास्ते वह इस मुलाक़ात के बारे में बहुत कम सोच पाया।</p>\n<p>मन बार-बार कहीं और चला जाता—</p>\n<p>एक गुलमोहर के नीचे रखी बेंच तक।</p>\n<p>और उस लड़की तक जो अब किसी और की पत्नी थी।</p>\n<p>श्रद्धा अपने माता-पिता के साथ सामने वाले कमरे में पहले से बैठी थी।</p>\n<p>शुरुआती नमस्ते, चाय, रिश्तेदारियों और परिचय की औपचारिक बातें कुछ शांत हुईं, तब विक्रम ने पहली बार उसे ठीक से देखा।</p>\n<p>खिड़की से दोपहर की ढलती हुई सुनहरी रोशनी भीतर आ रही थी। हवा लगभग स्थिर थी और उस रोशनी में धूल के महीन कण बहुत धीरे-धीरे तैरते दिखाई दे रहे थे।</p>\n<p>श्रद्धा करीब पाँच फुट सात की थी—नैना से लंबी। रंग साफ़ था, जिस पर खिड़की से आती धूप और खुल रही थी। लंबे, घने बाल कंधों से नीचे तक ढीले प्राकृतिक घुँघरालेपन में उतर रहे थे; साफ़ दिखाई देता था कि सुबह उन्हें सँभालने की जो भी कोशिश की गई होगी, बालों ने उसे पूरी तरह मानने से इनकार कर दिया था।</p>\n<p>लेकिन विक्रम का ध्यान सबसे ज़्यादा उसके चेहरे की उस हल्की-सी मुस्कान पर गया जिसे वह पूरी तरह आने नहीं दे रही थी।</p>\n<p>जैसे उसे भी इस पूरे कार्यक्रम की औपचारिकता थोड़ी हास्यास्पद लग रही हो—</p>\n<p>और दोनों परिवारों के सामने यह बात खुलकर जताना उसने समझदारी नहीं समझी हो।</p>\n<p>लगभग आधा घंटा दोनों परिवार आपस में बातें करते रहे।</p>\n<p>फिर आख़िर किसी को याद आया कि जिन दो लोगों के बारे में फ़ैसला होना है, उन्होंने अभी तक एक-दूसरे से ठीक से बात ही नहीं की।</p>\n<p>“बगीचे में थोड़ा घूम आओ।”</p>\n<p>पाँच मिनट।</p>\n<p>बस इतना ही कहा गया।</p>\n<p>दोनों लगभग एक जैसी राहत के साथ उठ खड़े हुए।</p>\n<p>घरवालों की आवाज़ से पर्याप्त दूर पहुँचते ही श्रद्धा बोली—</p>\n<p>“हर बार यही करते हैं।”</p>\n<p>विक्रम ने श्रद्धा की ओर देखा।</p>\n<p>श्रद्धा की आवाज़ में सूखा, ठहरा हुआ मज़ाक था।</p>\n<p>“आधा घंटा फसल के भाव और पुराने रिश्तेदारों की बातें करेंगे। फिर अचानक याद आएगा कि जिन दो लोगों की जाँच-पड़ताल चल रही है, उन्होंने अभी तक आपस में एक शब्द नहीं बोला।”</p>\n<p>विक्रम के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“आप पहले भी कर चुकी हैं ये?”</p>\n<p>“दो बार।”</p>\n<p>श्रद्धा ने बिना किसी झिझक के कहा।</p>\n<p>“अब तो इस कार्यक्रम के ‘बगीचे में पाँच मिनट’ वाले हिस्से में काफी अनुभवी हो गई हूँ।”</p>\n<p>विक्रम हँस पड़ा।</p>\n<p>“कुछ भी पूछ लीजिए। ज़्यादातर तयशुदा सवालों के लिए मेरे पास ठीक-ठाक आकर्षक जवाब तैयार हैं।”</p>\n<p>“और अगर मैं तयशुदा सवाल न पूछूँ?”</p>\n<p>श्रद्धा ने उसकी ओर देखा।</p>\n<p>“तो मुझे वहीं जवाब बनाना पड़ेगा।”</p>\n<p>फिर हल्की मुस्कान—</p>\n<p>“जो हम दोनों के लिए ज़्यादा दिलचस्प होगा।”</p>\n<p>श्रद्धा उसे देख रही थी।</p>\n<p>पर उस निगाह में कोई जल्दबाज़ी नहीं थी।</p>\n<p>न कोई फ़ैसला सुनाने वाली धार।</p>\n<p>बस एक शांत-सा ध्यान—जैसे सामने वाले को समझने के लिए पहले उसे पूरा बोलने देना चाहिए।</p>\n<p>“तो असली सवाल पूछिए।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“वो नहीं जो आपको पूछना चाहिए।”</p>\n<p>विक्रम ने कुछ क्षण सोचा।</p>\n<p>फिर सीधे पूछा—</p>\n<p>“पहले दो बार बात क्यों नहीं बनी?”</p>\n<p>श्रद्धा के चेहरे पर क्षण-भर आश्चर्य आया।</p>\n<p>इतनी सीधी शुरुआत की उम्मीद नहीं थी।</p>\n<p>“अलग-अलग वजहें।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“एक को लगा मैं बहुत बोलती हूँ।”</p>\n<p>विक्रम के होंठ हल्के हिले।</p>\n<p>“और दूसरे की माँ को ऐसी लड़की पसंद नहीं थी जो बहुत पढ़ती हो।”</p>\n<p>“क्यों?”</p>\n<p>“किताबें पढ़ने वाली लड़कियों की अपनी राय बनने का ख़तरा रहता है।”</p>\n<p>श्रद्धा ने बिल्कुल सहजता से कहा।</p>\n<p>“और बहू की अपनी राय हो तो कुछ लोगों को घर चलाने में असुविधा होती है।”</p>\n<p>वह बात हल्के अंदाज़ में कह रही थी, लेकिन उसके नीचे कुछ बहुत स्थिर था।</p>\n<p>“सिर्फ इसलिए किसी से शादी करने की जल्दी नहीं है कि लोग पूछना बंद कर दें कि अब तक शादी क्यों नहीं हुई।”</p>\n<p>श्रद्धा ने रास्ते के किनारे लगे पौधों की ओर देखते हुए कहा।</p>\n<p>“थोड़ा इंतज़ार कर लूँगी। कम-से-कम ऐसा इंसान तो मिले जिसे मेरी किताबों और मेरी राय—दोनों से परेशानी न हो।”</p>\n<p>“मुझे दोनों से परेशानी नहीं है।”</p>\n<p>श्रद्धा ने तुरंत उसकी तरफ देखा।</p>\n<p>“बगीचे में हर लड़का यही कहता है।”</p>\n<p>विक्रम के कंधे हल्के से ढीले पड़े।</p>\n<p>“बगीचे की बात सच थी या नहीं, यह कहने से नहीं—निभाने से पता चलता है।”</p>\n<p>विक्रम के स्वर में कड़वाहट नहीं थी।</p>\n<p>बस अनुभव से निकली हुई एक साफ़ बात थी।</p>\n<p>फिर श्रद्धा ने पूछा—</p>\n<p>“और आप?”</p>\n<p>“मैं?”</p>\n<p>“आपकी अब तक बात क्यों नहीं बनी?”</p>\n<p>“पोस्टिंग।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“साल के बारह में से दस महीने बाहर रहो तो किसी को ठीक से जानना आसान नहीं होता।”</p>\n<p>“बहुत सुविधाजनक बहाना है।”</p>\n<p>“है।”</p>\n<p>“फिर भी आपकी माँ से रिश्तेदार सवाल पूछना शुरू कर चुके होंगे।”</p>\n<p>“कर चुके हैं।”</p>\n<p>“और आप क्या जवाब देते हैं?”</p>\n<p>विक्रम कुछ क्षण चुप रहा।</p>\n<p>ऐसा जवाब खोजते हुए जो झूठ न हो—</p>\n<p>लेकिन पूरा सच भी न माँगे।</p>\n<p>“अभी तक किसी को हाँ कहने की वजह नहीं मिली।”</p>\n<p>श्रद्धा ने उसे देखा।</p>\n<p>कुछ देर तक।</p>\n<p>“बहुत सावधानी से बनाया हुआ अधूरा जवाब है।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“कारीगरी अच्छी है।”</p>\n<p>श्रद्धा की आँखों में फिर वही हल्का मज़ाक आया।</p>\n<p>“लेकिन पूरा सच है, ये नहीं मानती।”</p>\n<p>इस बार विक्रम सचमुच मुस्कराया।</p>\n<p>श्रद्धा उसे देखती रही।</p>\n<p>न किसी जज की तरह।</p>\n<p>न ऐसे जैसे पाँच मिनट में इंसान का भविष्य पढ़ लेने का दावा कर रही हो।</p>\n<p>बस जैसे उसने तय किया हो कि सामने खड़े व्यक्ति पर ध्यान देना चाहिए।</p>\n<p>“मैं ये नाटक नहीं करूँगी कि पाँच मिनट में मेरे मन ने आपके बारे में कुछ बता दिया है।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“मुझे ऐसी चीज़ों पर भरोसा नहीं।”</p>\n<p>फिर कंधे हल्के से उचकाए।</p>\n<p>“लेकिन अभी तक आप बुरे नहीं लगे।”</p>\n<p>एक पल।</p>\n<p>“पिछले दोनों के बारे में इतना भी नहीं कह पाई थी।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“ये भी कम नहीं है।”</p>\n<p>“नहीं।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“कम नहीं है।”</p>\n<p>बगीचे का बाकी चक्कर दोनों ने लगभग चुपचाप पूरा किया।</p>\n<p>लेकिन वह चुप्पी असहज नहीं थी।</p>\n<p>रास्ते के किनारे लगे गेंदे मौसम ठंडा पड़ने के बावजूद अब भी अपना रंग थामे हुए थे।</p>\n<p>गेंदे की तीखी, कड़वी महक अब भी हवा में थी।</p>\n<p>जब वे वापस कमरे में पहुँचे तो दोनों परिवारों की निगाहें उनके चेहरों पर थीं—जैसे इतनी-सी देर की बातचीत का फ़ैसला किसी मुस्कान, किसी झिझक या आँखों के किसी छोटे-से बदलाव से पढ़ लिया जाएगा।</p>\n<p>दोनों ने कुछ साफ़ नहीं होने दिया।</p>\n<p>फिर भी—</p>\n<p>उन चंद मिनटों में कुछ बहुत छोटा-सा अपनी जगह बदल चुका था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>वापसी में माँ ने पूछा—</p>\n<p>“कैसी लगी?”</p>\n<p>विक्रम ने इस बार कम-से-कम इतना जवाब दिया जो पूरी तरह सच था।</p>\n<p>“अच्छी है, माँ।”</p>\n<p>फिर—</p>\n<p>“समझदार है। अपने पैरों पर खड़ी रहने वाली लगती है।”</p>\n<p>वह कुछ पल रुका।</p>\n<p>“लेकिन मैं शादी के लिए तैयार नहीं हूँ।”</p>\n<p>“अभी नहीं।”</p>\n<p>माँ ने उसी शब्द को पकड़ लिया।</p>\n<p>“तैयार नहीं है।”</p>\n<p>उसकी आवाज़ में थकान उतर आई।</p>\n<p>“विक्रम, उम्र रुक नहीं रही। और हर महीना जो तू ‘तैयार नहीं हूँ’ में निकालता है, रिश्तेदारों के सामने मुझे वही सुनना पड़ता है कि मेरे बेटे में कमी क्या है।”</p>\n<p>“माँ, बात ऐसी नहीं—”</p>\n<p>“मैं तुझसे ये नहीं कह रही कि कल सुबह उठते ही उससे प्यार करने लग।”</p>\n<p>उसने बीच में रोक दिया।</p>\n<p>“बस एक ठीक, अच्छे रिश्ते को ऐसे मत देख जैसे कोई तुझे सज़ा दे रहा हो।”</p>\n<p>“मैं ऐसा नहीं देख रहा।”</p>\n<p>“तो फिर क्या है?”</p>\n<p>माँ ने सीट पर मुड़कर उसे देखा।</p>\n<p>“एक बार साफ़ बोल दे। वैसे ही नपा-तुला आधा जवाब मत देना जैसा उस लड़की को बगीचे में देकर आया है।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>ख़ामोशी लंबी होती गई।</p>\n<p>आख़िर उसकी माँ ने एक छोटी-सी झुँझलाई साँस छोड़ी और सामने देखने लगी।</p>\n<p>लेकिन बात ख़त्म नहीं हुई थी।</p>\n<p>सिर्फ उस समय के लिए रोक दी गई थी।</p>\n<p>शाम को पिता ने उसे अकेले बरामदे में बुलाया।</p>\n<p>माँ खाना बनाने भीतर जा चुकी थी।</p>\n<p>“तेरी माँ कह रही थी लड़की में कोई परेशानी है।”</p>\n<p>पिता अपनी रोज़ वाली कुर्सी पर बैठते हुए बोले।</p>\n<p>“उसमें कोई परेशानी नहीं है, बाबा।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“अच्छी लड़की है।”</p>\n<p>“फिर दिक्कत क्या है?”</p>\n<p>विक्रम काफी देर चुप रहा।</p>\n<p>उसके पास सच था।</p>\n<p>बस इतना छोटा सच नहीं था कि उसे बरामदे की उस शाम में दो-चार वाक्यों में पिता के हाथ पर रख सके।</p>\n<p>पिता उसे देखते रहे।</p>\n<p>फिर उनके थके हुए चेहरे पर कुछ नरमी आई।</p>\n<p>“जो भी अपने भीतर लेकर घूम रहा है, उसका हिसाब मुझसे देने को नहीं कहूँगा।”</p>\n<p>उन्होंने शांत स्वर में कहा।</p>\n<p>“इंसान को कुछ बातें अपने पास रखने का हक होता है।”</p>\n<p>एक पल।</p>\n<p>“अपने बाप से भी।”</p>\n<p>विक्रम ने उनकी ओर देखा।</p>\n<p>“लेकिन एक बात साफ़ सुन।”</p>\n<p>पिता का स्वर अब भी शांत था।</p>\n<p>“अगर इस लड़की में कोई असली कमी दिखी है—उसके व्यवहार में, उसके परिवार में, किसी भी बात में—अभी बता दे। कल सुबह बात ख़त्म कर देंगे। चुपचाप। फिर कोई इसका ज़िक्र नहीं करेगा।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“लेकिन अगर दिक्कत उसमें नहीं है।”</p>\n<p>पिता की आँखें उसके चेहरे पर टिक गईं।</p>\n<p>“अगर बात कुछ और है, जिसका नाम तू मुझे नहीं बताना चाहता—तो फिर तू उससे शादी करेगा।”</p>\n<p>विक्रम की आँखों में हल्का-सा बदलाव आया।</p>\n<p>“मैं तुझे पूरी ज़िंदगी किसी ऐसे दुख की चौकीदारी करते नहीं देखूँगा जिसका नाम तक लेने को तैयार नहीं है।”</p>\n<p>पिता ने कहा।</p>\n<p>“खासकर तब नहीं जब दूसरी तरफ एक अच्छी लड़की सिर्फ इसलिए रुकी हो कि तू फ़ैसला करने से डर रहा है।”</p>\n<p>विक्रम काफी देर पिता को देखता रहा।</p>\n<p>और धीरे-धीरे वही थकी हुई साफ़गोई उसके भीतर उतर आई जो गाड़ी में बैठते हुए भी कहीं थी—</p>\n<p>श्रद्धा के ख़िलाफ़ उसके पास कुछ नहीं था।</p>\n<p>एक भी ईमानदार आपत्ति नहीं।</p>\n<p>जो कुछ था, वह श्रद्धा से जुड़ा ही नहीं था।</p>\n<p>“उसमें कोई दिक्कत नहीं है, बाबा।”</p>\n<p>पिता खड़े हो गए।</p>\n<p>“तो तय रहा।”</p>\n<p>बस इतना।</p>\n<p>“तेरी माँ कल उनके घर फोन कर देगी।”</p>\n<p>विक्रम ने कुछ क्षण बाद कहा—</p>\n<p>“ठीक है, बाबा।”</p>\n<p>और उसी शब्द के भीतर उसे अचानक नैना याद आई।</p>\n<p>कभी उसने भी अपने पिता के सामने इसी तरह एक फ़ैसला स्वीकार किया था—जो उसके भीतर पैदा नहीं हुआ था, उसके ऊपर रख दिया गया था; जिसे चुना नहीं गया, बस जितना हो सका उतनी ईमानदारी से मान लिया गया।</p>\n<p>दोनों परिस्थितियाँ एक जैसी नहीं थीं।</p>\n<p>नैना के पिता को डर ने रोका था।</p>\n<p>विक्रम के पीछे सेना की चिंता थी।</p>\n<p>फिर भी किसी बड़े निर्णय के सामने अपनी इच्छा को धीरे-धीरे जगह छोड़ते देखना—</p>\n<p>उसका आकार दोनों जगह अजीब तरह से मिलता-जुलता था।</p>\n<p>यह प्रेम नहीं था।</p>\n<p>इतना विक्रम जानता था।</p>\n<p>अब वह प्रेम और किसी दूसरी शांत संभावना के बीच का फ़र्क़ पहचानता था—यह फ़र्क़ उसने कड़ी कीमत चुकाकर सीखा था।</p>\n<p>लेकिन पिता के भीतर चले जाने के बाद बरामदे में अकेला बैठा तो उसे यह भी लगा कि बहुत समय बाद ज़िंदगी ने उसके सामने पहली बार कोई ऐसी चीज़ रखी है जो शांति जैसी दिखती है।</p>\n<p>न कोई उन्माद।</p>\n<p>न कोई भागती हुई घड़ी।</p>\n<p>न हर मुलाक़ात के पीछे बिछड़ने का डर।</p>\n<p>बस एक जीवन—</p>\n<p>जिसकी नींव इस बार आग की किसी पुरानी याद पर नहीं, साधारण ज़मीन पर रखी जा रही थी।</p>\n<p>और शायद घर आख़िर ज़मीन पर ही बनते हैं।</p>\n<p>आग की स्मृति पर नहीं।</p>\n<p>वह इतना ईमानदार ज़रूर था कि मान सके—पिता का फ़ैसला पूरी तरह ग़लत नहीं था।</p>\n<p>श्रद्धा ने उसे हिचकने की कोई वजह नहीं दी थी।</p>\n<p>और अगर विक्रम का दिल किसी को चुनने की हालत में होता—</p>\n<p>तो शायद वह ऐसी स्त्री को अपनी मर्ज़ी से भी चुन सकता था।</p>\n<p>फिर सिर्फ पिता की ज़िद ही इस फ़ैसले के पीछे नहीं थी।</p>\n<p>कर्नल का फोन भी कहीं मौजूद था।</p>\n<p>उस बरामदे में किसी ने उसका नाम नहीं लिया, लेकिन विक्रम जानता था कि उसके पिता तक यह रिश्ता केवल माँ की चिंता से नहीं पहुँचा था।</p>\n<p>एक कमांडिंग ऑफिसर ने उसे गोलियों के बीच ऐसे चलते देखा था जैसे लौटना अब उतना ज़रूरी न रह गया हो।</p>\n<p>और उसने अपने सीधे, सैनिक ढंग से इलाज यही समझा था—</p>\n<p>उस अफसर को घर पर कोई ऐसा कारण दे दो जिसके पास उसे लौटना हो।</p>\n<p>पिता के निर्णय और कर्नल की चिंता के बीच विक्रम ने पाया कि फिलहाल उसे उनके फ़ैसले पर अपने निर्णय से ज़्यादा भरोसा है।</p>\n<p>उसे तब नहीं मालूम था कि श्रद्धा उसकी ज़िंदगी की कैसी नींव बनने वाली है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>फेरे हो रहे थे।</p>\n<p>अग्नि में घी पड़ते ही धुआँ उठा और विक्रम की आँखें जल उठीं।</p>\n<p>सबने समझा, धुएँ से।</p>\n<p>सातवाँ और आख़िरी चक्कर लेते हुए विक्रम का मन कुछ क्षण के लिए वहाँ से बहुत दूर चला गया।</p>\n<p>एक गुलमोहर।</p>\n<p>उसके नीचे बेंच।</p>\n<p>एक आवाज़, जिसने कभी उससे कहा था—‘मुझे लाउड ही रखना।’</p>\n<p>और होटल के एक दरवाज़े पर कहा गया वह अलविदा, जिसका दुख उसने अब तक पूरा जी भी नहीं पाया था।</p>\n<p>ख़याल आया।</p>\n<p>और चला गया।</p>\n<p>लेकिन उसके आने भर से विक्रम के भीतर अपराधबोध की एक तेज़ लहर उठी।</p>\n<p>इसलिए नहीं कि याद उसके बस में थी।</p>\n<p>बल्कि इसलिए कि वह आज आई थी।</p>\n<p>उस सुबह।</p>\n<p>उस लड़की के बगल में बैठकर—</p>\n<p>जो ऐसे पति की हकदार थी जिसका मन अपनी ही शादी में कहीं और भटक न रहा हो।</p>\n<p>उसने श्रद्धा की ओर देखा।</p>\n<p>ठीक से।</p>\n<p>लाल और सुनहरे जोड़े में वह अग्नि के सामने बैठी थी। उसकी आँखें फेरों की हर छोटी रस्म पर थीं, चेहरे पर एक शांत एकाग्रता—उसमें कुछ भी अभिनय जैसा नहीं था।</p>\n<p>वह दुल्हन होने का कोई किरदार नहीं निभा रही थी।</p>\n<p>वह वहाँ सचमुच मौजूद थी।</p>\n<p>श्रद्धा ने उसकी नज़र महसूस की।</p>\n<p>चेहरा उसकी ओर थोड़ा मोड़ा।</p>\n<p>और एक बहुत छोटी-सी मुस्कान दी।</p>\n<p>सिर्फ उसके लिए।</p>\n<p>उसी क्षण विक्रम को पहली बार उस निर्णय का पूरा वज़न महसूस हुआ।</p>\n<p>वह सिर्फ श्रद्धा से शादी नहीं कर रहा था।</p>\n<p>वह उससे शादी करते हुए अपने भीतर दो और लड़कियों की पूरी, अनकही कहानी भी लेकर बैठा था—</p>\n<p>जिनके बारे में श्रद्धा कुछ नहीं जानती थी।</p>\n<p>उस शाम मेहमानों की भीड़ से कुछ पल के लिए दोनों अकेले हुए तो श्रद्धा ने कहा—</p>\n<p>“आप बहुत चुप हो गए हैं।”</p>\n<p>“आज दिन बहुत लंबा रहा।”</p>\n<p>“जवाब तो है।”</p>\n<p>श्रद्धा ने उसे देखा।</p>\n<p>“पूरा नहीं है, लेकिन आज के लिए मान लेती हूँ।”</p>\n<p>विक्रम के होंठों पर हल्की मुस्कान आई।</p>\n<p>श्रद्धा कुछ पल उसे पढ़ती रही।</p>\n<p>अब वह उस निगाह को पहचानने लगा था।</p>\n<p>बगीचे वाली वही निगाह।</p>\n<p>धैर्य से देखने वाली।</p>\n<p>“फेरों के दौरान आप कुछ देर कहीं और थे।”</p>\n<p>विक्रम का गला सूख गया।</p>\n<p>“मैंने देखा।”</p>\n<p>“माफ़ करना।”</p>\n<p>“मुझे आपसे माफ़ी नहीं चाहिए।”</p>\n<p>श्रद्धा ने बहुत साधारण स्वर में कहा।</p>\n<p>“बस बता रही हूँ कि मैंने देखा था।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“मुझे लगा शुरुआत में ही आपको पता होना चाहिए कि मैं चीज़ें नोटिस करती हूँ।”</p>\n<p>श्रद्धा की आवाज़ में न आरोप था, न नाटक।</p>\n<p>“आज रात मुझे उसकी वजह नहीं चाहिए।”</p>\n<p>एक पल।</p>\n<p>“अपनी शादी का दिन मैं उस भूत के नाम नहीं करूँगी जो कुछ सेकंड के लिए आपके चेहरे से गुज़र गया था।”</p>\n<p>विक्रम की आँखें उससे नहीं हटीं।</p>\n<p>“लेकिन ये बता देना ज़रूरी था।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“ताकि पूरी शादी इस ग़लतफ़हमी में मत रहिएगा कि चीज़ें छिपाने में आप उतने अच्छे हैं जितना ख़ुद को समझते हैं।”</p>\n<p>विक्रम के पास तत्काल कोई जवाब नहीं था।</p>\n<p>श्रद्धा ने जवाब माँगा भी नहीं था।</p>\n<p>दूर से किसी ने श्रद्धा का नाम पुकारा।</p>\n<p>जाने से पहले श्रद्धा ने बस विक्रम का हाथ पकड़ा और एक बार हल्के से दबाया।</p>\n<p>न कोई सवाल।</p>\n<p>न कोई माँग।</p>\n<p>बस एक छोटा-सा स्पर्श—</p>\n<p>जैसे यह कहना काफी हो कि उसने जो देखा है, उसे अभी उसी जगह रहने देगी।</p>\n<p>फिर वह चली गई।</p>\n<p>और विक्रम वहीं कुछ क्षण खड़ा रहा, पहली बार इस असहज एहसास के साथ कि उसने जिस स्त्री से अभी शादी की है—</p>\n<p>उसे धोखा देना उसकी कल्पना से कहीं मुश्किल होने वाला है।</p>\n<p>आने वाले दिनों में सामान अपनी जगह रखे जाते समय, कमरे की एक दराज़ में विक्रम का एक पुराना फोन वैसे ही पड़ा रह गया।</p>\n<p>बंद।</p>\n<p>उसके भीतर पुरानी सिम अब भी लगी हुई थी।</p>\n<p>एक बीती हुई ज़िंदगी की छोटी-सी चीज़—</p>\n<p>जिसका दरवाज़ा पूरी तरह बंद किए बिना उसने एक नया दरवाज़ा खोल दिया था।</p>\n<p>विक्रम भूल चुका था कि वह फोन वहाँ है।</p>\n<p>और आगे चलकर—</p>\n<p>यही बात सबसे ज़्यादा मायने रखने वाली थी।</p>"}, {"chapter": 37, "title": "अध्याय 34 — पुरानी सिम", "content": "<h1>अध्याय 34 — पुरानी सिम</h1>\n<p>शादी को पाँच दिन हो चुके थे। दोपहर शांत थी और विक्रम अपने पिता के साथ किसी काम से बाहर गया हुआ था। श्रद्धा उस कमरे को समेट रही थी जो अब आधिकारिक तौर पर उसका भी था, तभी अलमारी की निचली दराज़ में, किताबों के एक ढेर के पीछे उसे एक पुराना फोन मिला—धूल में पड़ा, उस तरह अनछुआ जैसे घर कुछ चीज़ों को फेंकता नहीं, बस धीरे-धीरे देखना बंद कर देता है।</p>\n<p>खिड़की पर पीतल का एक छोटा-सा दिया बुझा पड़ा था। बाहर नीम पर एक कौवे ने दो बार आवाज़ दी और फिर सर्द दोपहर वापस अपनी ख़ामोशी में डूब गई।</p>\n<p>उसी ढेर के नीचे फीके कपड़े की एक छोटी पोटली थी। पहली नज़र में श्रद्धा ने उसे पूजा-पाठ की कोई चीज़ समझा, मगर खोलने पर भीतर कुछ पुराने खत मिले। पोटली से नैफ़थलीन और पुराने काग़ज़ की मिली-जुली गंध उठी। लिफ़ाफ़ों की तहें नरम पड़ चुकी थीं; काग़ज़ उस तरह पतला हो गया था जैसा बार-बार खोले, पढ़े और फिर बहुत संभालकर रखे गए काग़ज़ का हो जाता है।</p>\n<p>एक पल के लिए उसने दोनों चीज़ें वहीं छोड़ देने का सोचा। आख़िर हर घर में कुछ पुराने फोन, कुछ खत, कुछ ऐसी चीज़ें होती हैं जिन्हें कोई फेंकता नहीं और जिनके बारे में पूछना भी ज़रूरी नहीं लगता।</p>\n<p>फिर भी उनके रखे होने के ढंग ने उसे रोक लिया। जानबूझकर छिपाए गए थे या बस लापरवाही से रख दिए गए थे—वह तय नहीं कर सकी। उसने फोन हाथ में पलटकर देखा, खत ठीक उसी तरह वापस रख दिए और कमरे का बाकी काम पूरा करती रही।</p>\n<p>लेकिन मन के भीतर कोई बहुत धीमी-सी आशंका अपना काम शुरू कर चुकी थी।</p>\n<p>शाम को, जब विक्रम बाहर अपने पिता के साथ खेतों की किसी बात में लगा था, श्रद्धा फिर उस फोन के पास गई। इस बार केवल जिज्ञासा में उसने पुराने मॉडल का चार्जर ढूँढ़ा—दूसरी दराज़ में, तारों के एक उलझे गुच्छे के नीचे—और फोन को लगा दिया। कुछ देर बाद स्क्रीन पर बैटरी का लाल निशान टिमटिमाया। उसने पावर बटन दबाया। उसे उम्मीद नहीं थी कि फोन चलेगा।</p>\n<p>फोन चल गया।</p>\n<p>पुरानी सिम अब भी भीतर थी।</p>\n<p>और उसके बाद जो संदेश एक-एक करके सामने आए, उन्होंने उस शाम की पूरी शक्ल बदल दी।</p>\n<p>कुछ देर बाद उसने खत भी निकाल लिए। अब वह आधी बात जानकर उन्हें वापस नहीं रख सकती थी। उसे समझना था कि यह जो कुछ भी है—पूरा क्या है।</p>\n<p>ज़्यादातर खत वैसे ही थे जैसे पुराने प्रेम-पत्र किसी तीसरे इंसान को लगते हैं—साधारण अपनापन, कुछ तारीख़ें, कुछ जगहों के नाम जिन्हें अब वह फोन के संदेशों से पहचान रही थी, दूरी और ड्यूटी की छोटी शिकायतें।</p>\n<p>फिर नीचे की ओर रखा एक खत खुलते ही उसके हाथ रुक गए।</p>\n<p>उस पर लिखे अक्षर बाकी खतों की नीली-काली स्याही जैसे नहीं थे। रंग फीका पड़कर जंग लगे भूरेपन में बदल चुका था। श्रद्धा उसे बहुत देर तक देखती रही, जैसे आँखें अर्थ समझ चुकी हों लेकिन मन अभी उसे स्वीकार करने से इनकार कर रहा हो।</p>\n<p>तीन पंक्तियाँ थीं—</p>\n<p><b>मैं इंतज़ार कर रही हूँ।</b></p>\n<p><b>तुमने वादा किया है कि लौटोगे।</b></p>\n<p><b>ज़िंदा लौटना, विक्रम।</b></p>\n<p>उसने उन्हें एक बार पढ़ा।</p>\n<p>फिर दोबारा।</p>\n<p>फिर जाने कितनी बार।</p>\n<p>हर बार वह फीका भूरा रंग थोड़ा और साफ़ अर्थ लेने लगा, और उसी के साथ उसके भीतर ठंडक-सी उतरती गई।</p>\n<p>वह स्याही नहीं थी।</p>\n<p>बाहर कहीं मंदिर की घंटी ने शाम का समय बताया। आवाज़ बहुत हल्की थी, बिल्कुल सामान्य—जैसे दुनिया को उस कमरे में मिले सच से कोई वास्ता न हो।</p>\n<p>श्रद्धा ने खत को उसी तह में वापस मोड़ा जिसमें मिला था। हाथ अब पूरी तरह स्थिर नहीं थे।</p>\n<p>वह रोई नहीं।</p>\n<p>अभी नहीं।</p>\n<p>बस पुराने फोन और खतों की उस छोटी-सी गठरी को गोद में रखे बैठी रही, उस इंसान की तरह जिसे अचानक इतनी बड़ी बात मालूम हो गई हो कि पहली प्रतिक्रिया के लिए भी जगह न बची हो।</p>\n<p>कमरे की रोशनी धीरे-धीरे कम होती गई।</p>\n<p>और वह वहीं बैठी रही।</p>\n<p>रात को विक्रम लौटा तो उसने श्रद्धा को पलंग के किनारे बैठे देखा। पुराना फोन और खत उसकी गोद में थे।</p>\n<p>श्रद्धा ने कुछ नहीं कहा था, फिर भी श्रद्धा के कंधों की स्थिरता देखकर विक्रम समझ गया कि क्या हो चुका है।</p>\n<p>“नैना।”</p>\n<p>श्रद्धा ने फोन से नज़र नहीं उठाई। नाम श्रद्धा ने ऐसे कहा जैसे कबूलनामे का पहला शब्द हो।</p>\n<p>फिर श्रद्धा ने पूछा—</p>\n<p>“कौन है?”</p>\n<p>विक्रम दरवाज़े पर ही रुक गया। एक साथ कई जवाब उसके भीतर आए, मगर उनमें से कोई पर्याप्त नहीं था।</p>\n<p>“श्रद्धा…”</p>\n<p>“दरवाज़े पर खड़े-खड़े पूरी कहानी समझाने को नहीं कह रही।”</p>\n<p>श्रद्धा की आवाज़ ऊँची नहीं थी। यही बात उस क्षण को और भारी बना रही थी।</p>\n<p>“बैठिए। और मुझे सच बताइए। पूरा।”</p>\n<p>अब श्रद्धा ने पहली बार विक्रम की ओर देखा।</p>\n<p>“शादी के पाँच दिन बाद इतना हक तो बनता है मेरा कि कम-से-कम यह जान सकूँ मैंने जिस इंसान से शादी की है, वह असल में कौन है।”</p>\n<p>विक्रम कमरे में आया और उसके पास बैठ गया, मगर थोड़ी दूरी पर। उस क्षण करीब बैठने का अधिकार भी उसे अपना नहीं लगा।</p>\n<p>“उसका नाम नैना है।”</p>\n<p>वह रुका।</p>\n<p>“तुमसे पहले करीब दो साल हम साथ थे। मैं उससे प्यार करता था। उससे शादी करना चाहता था।”</p>\n<p>श्रद्धा सुनती रही।</p>\n<p>“उसके पिता ने मना कर दिया। आर्मी की ज़िंदगी… परिवार पर उसका असर। उन्होंने ख़ुद वह ज़िंदगी जी थी और अपनी बेटी के लिए नहीं चाहते थे।”</p>\n<p>एक साँस।</p>\n<p>“तुमसे मिलने से कुछ महीने पहले उसकी शादी किसी और से हो गई।”</p>\n<p>कमरे में फिर चुप्पी हुई।</p>\n<p>श्रद्धा ने कहा—</p>\n<p>“बस इतना नहीं है।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>“मुझे महसूस हो रहा है कि बस इतना नहीं है।”</p>\n<p>वह कुछ क्षण चुप रहा।</p>\n<p>फिर विक्रम ने कविता के बारे में भी बताया।</p>\n<p>नैना से पहले के वे साल। वह रिश्ता। उसका अंत। और अपने अतीत की वह पूरी उलझी हुई शक्ल जिसे उसने अब तक किसी के सामने पूरा नहीं रखा था।</p>\n<p>इस बार विक्रम ने अपने लिए कोई सफाई नहीं दी।</p>\n<p>जो था, वैसा कहा।</p>\n<p>हर बात के बाद वह श्रद्धा के चेहरे पर कुछ खोजता—गुस्सा, आँसू, कोई सवाल—मगर वहाँ केवल एक नियंत्रित स्थिरता थी।</p>\n<p>वही स्थिरता उसे गुस्से से ज़्यादा डरा रही थी।</p>\n<p>जब वह ख़त्म हुआ, कमरे में पूरी तरह अँधेरा हो चुका था। सिर्फ पुराने फोन की स्क्रीन की कमज़ोर रोशनी श्रद्धा की गोद के पास अब भी जल रही थी—जैसे जो कुछ उसने इतने वर्षों तक अपने भीतर रखा था, उसका आख़िरी छोटा गवाह अभी बुझने को तैयार न हो।</p>\n<p>बहुत देर बाद श्रद्धा ने पूछा—</p>\n<p>“फिर मुझसे शादी क्यों की?”</p>\n<p>विक्रम ने सिर उठाया।</p>\n<p>“जब ये सब आपके भीतर अभी भी था… अधूरा… तो मुझसे शादी क्यों की?”</p>\n<p>इस सवाल का कोई अच्छा जवाब नहीं था।</p>\n<p>और पहली बार विक्रम ने अच्छा जवाब ढूँढ़ने की कोशिश भी नहीं की।</p>\n<p>“घरवाले चाहते थे कि मैं घर बसा लूँ।”</p>\n<p>विक्रम ने अपने हाथों की ओर देखा।</p>\n<p>“और मुझे लगता था मेरे भीतर अब किसी ऐसे इंसान को देने के लिए कुछ बचा ही नहीं है जिससे मैं सच में प्यार करूँ।”</p>\n<p>शब्द कठिन थे, फिर भी उसने उन्हें नरम बनाने की कोशिश नहीं की।</p>\n<p>“इसलिए मैंने ख़ुद को समझाया कि एक अच्छी, समझदार शादी कर लेना ज़्यादा ईमानदार होगा—उससे बेहतर कि मैं यह दिखावा करूँ कि पहले की तरह फिर किसी से प्यार कर सकता हूँ।”</p>\n<p>वह कुछ क्षण चुप रहा।</p>\n<p>“मुझे अपनी उस सोच पर गर्व नहीं है।”</p>\n<p>फिर विक्रम ने श्रद्धा की ओर देखा।</p>\n<p>“लेकिन तुमने सच पूछा है। उसे अच्छा दिखाने वाला कोई दूसरा रूप नहीं दूँगा।”</p>\n<p>श्रद्धा ने फोन और खत दोनों उठाकर सिरहाने की मेज़ पर रख दिए। बहुत संभलकर। जैसे किसी चीज़ को फेंक नहीं रही हो—बस तय कर रही हो कि अभी उसे कहाँ रखना है।</p>\n<p>“मुझे सोचने के लिए वक्त चाहिए।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“आज रात गुस्से में बैठकर ऐसी बातें नहीं कहना चाहती जिनका मतलब कल ख़ुद मुझे न समझ आए।”</p>\n<p>श्रद्धा ने साँस ली।</p>\n<p>“एक-दो दिन।”</p>\n<p>उसकी आवाज़ अब भी स्थिर थी, मगर विक्रम सुन सकता था कि उस स्थिरता को बनाए रखने में उसे कितनी ताकत लग रही है।</p>\n<p>“मैं यह दिखावा नहीं करूँगी कि इससे आपको देखने का मेरा तरीका नहीं बदला।”</p>\n<p>श्रद्धा ने साफ़ कहा।</p>\n<p>“और मुझे इतनी जगह चाहिए कि उस बदलाव के साथ ईमानदारी से बैठ सकूँ—इससे पहले कि आप मुझे जल्दी माफ़ कर देने की तरफ धकेलें। मुझे ख़ुद तय करना है कि मैं कर भी सकती हूँ या नहीं।”</p>\n<p>“जितना वक्त चाहिए, लो।”</p>\n<p>“ले रही हूँ।”</p>\n<p>उस रात श्रद्धा आख़िर लेट गई।</p>\n<p>पीठ विक्रम की ओर थी।</p>\n<p>दोनों ने फिर कुछ नहीं कहा।</p>\n<p>विक्रम बहुत देर तक अँधेरे में जागता रहा, अपने बगल में उस शादी की अनजानी ख़ामोशी सुनते हुए जो एक ही शाम में सरल रहना बंद कर चुकी थी।</p>\n<p>रात के किसी पहर सिरहाने रखे फोन की स्क्रीन बुझ गई—जैसे आख़िरी गवाह ने भी चुप रहना चुन लिया।</p>\n<p>सुबह तक श्रद्धा क्या तय करेगी, विक्रम को नहीं मालूम था।</p>\n<p>यह भी नहीं कि उसके बगल में लेटी स्त्री सुबह भी उसकी पत्नी रहेगी—या एक शाम की देर से आई ईमानदारी में वह वही सब खो चुका था जो उसके परिवार और कर्नल ने उसके लिए खड़ा करना चाहा था।</p>"}, {"chapter": 38, "title": "अध्याय 35 — मोहलत, माफ़ी नहीं", "content": "<h1>अध्याय 35 — मोहलत, माफ़ी नहीं</h1>\n<p>पूरा एक दिन श्रद्धा ने उस बात का फिर ज़िक्र नहीं किया।</p>\n<p>लेकिन ख़ामोशी गायब नहीं हुई थी।</p>\n<p>वह घर में उनके साथ ही रही—कमरों से गुज़रती, खाने की मेज़ पर बैठती, रोज़मर्रा के छोटे कामों के बीच अपनी जगह बनाए हुए; बिल्कुल उस मौसम की तरह जिसका नाम कोई नहीं लेता, मगर जिसके हिसाब से घर का हर इंसान अपने कपड़े चुनने लगता है।</p>\n<p>विक्रम ने भी उसे छेड़ा नहीं।</p>\n<p>न यह पूछा कि उसने क्या तय किया।</p>\n<p>न अपने बचाव में कोई नई बात रखी।</p>\n<p>श्रद्धा ने समय माँगा था।</p>\n<p>और पहली बार विक्रम समझ रहा था कि किसी को समय देना केवल उसे अकेला छोड़ देना नहीं होता—</p>\n<p>कई बार ख़ुद अपनी बेचैनी के साथ चुप बैठना भी होता है।</p>\n<p>अगली रात विक्रम के माता-पिता सो चुके थे।</p>\n<p>श्रद्धा शॉल में लिपटी थी। दोनों बरामदे में अकेले बैठे थे।</p>\n<p>सामने बगीचा अँधेरे में डूबा हुआ था। कहीं दूर जलते अलाव के धुएँ की हल्की गंध ठंडी होती हवा में धीरे-धीरे फैल रही थी। कहीं बाहर कोई आवारा कुत्ता रात के लिए जगह बनाते हुए एक बार धीमे से कराहा और फिर आसपास सब शांत हो गया।</p>\n<p>बीच की तिपाई पर दो प्याले रखे थे—चाय कब की ठंडी हो चुकी थी, पर किसी ने उठाकर हटाए नहीं।</p>\n<p>श्रद्धा की आँखें बगीचे पर थीं।</p>\n<p>“मैंने सोचा है।”</p>\n<p>श्रद्धा ने बिना भूमिका के कहा।</p>\n<p>विक्रम ने श्रद्धा की ओर देखा।</p>\n<p>“जितना एक दिन में सोचा जा सकता है, उतना।”</p>\n<p>फिर कुछ क्षण बाद—</p>\n<p>“और सच कहूँ तो मुझे नहीं लगता सोच ख़त्म हुई है।”</p>\n<p>श्रद्धा की आवाज़ बिल्कुल स्थिर थी।</p>\n<p>“शायद एक साल बाद भी किसी साधारण दोपहर में अचानक इसकी कोई बात याद आए और मैं फिर उसके बारे में सोचने लगूँ।”</p>\n<p>“अगर ऐसा हुआ तो मैं समझूँगा।”</p>\n<p>श्रद्धा ने विक्रम की तरफ देखे बिना कहा—</p>\n<p>“आप अभी शायद नहीं समझेंगे।”</p>\n<p>फिर उसने हल्की-सी साँस ली।</p>\n<p>“लेकिन अगर ये शादी इतनी लंबी चली कि आप मुझे ऐसा करते देख सकें, तो एक दिन समझ जाएँगे।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“फिलहाल मैं कहाँ पहुँची हूँ, वह बताना चाहती हूँ।”</p>\n<p>अब श्रद्धा ने विक्रम की तरफ देखा।</p>\n<p>“हो सकता है हमेशा यहीं न रहूँ। यह भी समझ लीजिए।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>पूरा ध्यान उसी पर था।</p>\n<p>श्रद्धा ने शब्द चुनने में समय लिया।</p>\n<p>“जो कुछ था, मेरे आने से पहले था।”</p>\n<p>उसने कहा।</p>\n<p>“नैना। और उससे पहले कविता। और आपकी कहानी में अगर अभी भी कुछ ऐसी जगहें हैं जिन्हें आपने कल रात नहीं खोला, तो वे भी।”</p>\n<p>एक छोटा-सा ठहराव।</p>\n<p>“हमारी शादी के दौरान उनमें से कुछ नहीं हुआ।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“कल रात से बार-बार इसी बात पर लौट रही हूँ।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“अभी मेरे पास खड़े रहने के लिए यही एक ठोस ज़मीन है।”</p>\n<p>श्रद्धा ने विक्रम की आँखों में देखा।</p>\n<p>“आपने मुझे धोखा नहीं दिया।”</p>\n<p>फिर तुरंत—</p>\n<p>“कम-से-कम उस अर्थ में नहीं, जिस अर्थ में कल रात गुस्से में मैं इस शब्द को इस्तेमाल करना चाहती थी।”</p>\n<p>विक्रम का चेहरा नहीं बदला।</p>\n<p>श्रद्धा ने आगे कहा—</p>\n<p>“आपने शादी से पहले किसी और से प्यार किया। बहुत किया। मुझसे मिलने से पहले किया।”</p>\n<p>श्रद्धा की आवाज़ में दर्द था, मगर आरोप नहीं।</p>\n<p>“यह अपने-आप में मेरे ख़िलाफ़ किया गया अपराध नहीं है।”</p>\n<p>फिर स्वर थोड़ा कठोर हुआ।</p>\n<p>“लेकिन आपने मेरे साथ ईमानदारी ज़रूर तोड़ी।”</p>\n<p>विक्रम की आँखें उस पर टिक गईं।</p>\n<p>“जो सच मुझे शादी से पहले मिलना चाहिए था, वह मुझे पाँच दिन बाद एक दराज़ और पुराने फोन से मिला।”</p>\n<p>उसने कहा।</p>\n<p>“दोनों बातों में फ़र्क़ है।”</p>\n<p>एक पल।</p>\n<p>“और मैं चाहती हूँ आप यह फ़र्क़ समझें। क्योंकि मैं उस बात पर गुस्सा नहीं हूँ जिस पर शायद आपको लगता है कि मुझे सबसे ज़्यादा गुस्सा होना चाहिए।”</p>\n<p>“मुझे पहले बता देना चाहिए था।”</p>\n<p>विक्रम ने कहा।</p>\n<p>विक्रम के भीतर एक स्पष्टीकरण तुरंत उठा—</p>\n<p>कि नैना का नाम लेना सिर्फ पुराने प्रेम को स्वीकार करना नहीं होता; उसे यह भी स्वीकार करना पड़ता कि वह इस विवाह में अपने भीतर का कितना छोटा हिस्सा लेकर आया था। शर्म थी। अपराधबोध था। और शायद यह उम्मीद भी कि जो बात बोलकर जीवित नहीं की जाएगी, वह समय के नीचे अपने-आप दब जाएगी।</p>\n<p>लेकिन विक्रम ने कुछ नहीं कहा।</p>\n<p>आज वे सारी बातें उसे वजहों से ज़्यादा बहाने लगीं।</p>\n<p>श्रद्धा ने सिर हिलाया।</p>\n<p>“हाँ।”</p>\n<p>श्रद्धा की आवाज़ एक पल के लिए तीखी हुई।</p>\n<p>“बता देना चाहिए था।”</p>\n<p>फिर वह शांत हुई।</p>\n<p>“मुझे नहीं पता आपने क्यों नहीं बताया।”</p>\n<p>उसने कहा।</p>\n<p>“कुछ अंदाज़े हैं।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“अहंकार हो सकता है।”</p>\n<p>एक क्षण।</p>\n<p>“शर्म।”</p>\n<p>फिर—</p>\n<p>“या शायद इंसान की वह शांत-सी कायरता जिसमें वह सोचता है कि किसी बात को ज़ुबान न दे तो वह ज़मीन के नीचे दबी रहेगी।”</p>\n<p>विक्रम की नज़र झुक गई।</p>\n<p>“लेकिन मैं पूरी ज़िंदगी आपकी वजहें अनुमान से नहीं बनाना चाहती।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“आप ख़ुद उन्हें देखिए।”</p>\n<p>“ईमानदारी से।”</p>\n<p>“मैं देखूँगा।”</p>\n<p>“अच्छा।”</p>\n<p>अब श्रद्धा पूरी तरह उसकी ओर मुड़ी।</p>\n<p>घर के भीतर की हल्की रोशनी उसके चेहरे के एक हिस्से तक पहुँच रही थी, बाकी अँधेरे में था।</p>\n<p>“तो आज रात के लिए मेरा फ़ैसला सुन लीजिए।”</p>\n<p>विक्रम स्थिर हो गया।</p>\n<p>“मैं रह रही हूँ।”</p>\n<p>विक्रम कुछ क्षण कुछ नहीं बोल सका।</p>\n<p>श्रद्धा तुरंत बोली—</p>\n<p>“इसका अर्थ यह मत निकालिएगा कि मैंने आपको पूरी तरह माफ़ कर दिया है।”</p>\n<p>श्रद्धा की आँखें विक्रम से नहीं हटीं।</p>\n<p>“नहीं किया।”</p>\n<p>“और सिर्फ हम दोनों को सहज महसूस कराने के लिए ऐसा कहूँगी भी नहीं।”</p>\n<p>विक्रम ने धीरे से सिर हिलाया।</p>\n<p>“मैं इसलिए रह रही हूँ क्योंकि जितने तथ्य मेरे सामने हैं, उन्हें ईमानदारी से देखने के बाद मुझे अभी जाने की पर्याप्त वजह नहीं दिखती।”</p>\n<p>उसने कहा।</p>\n<p>“हमारी शादी के भीतर आपने मुझसे झूठ नहीं बोला।”</p>\n<p>एक पल।</p>\n<p>“आप मुझसे मिलने से पहले किसी और से प्यार करते थे। दुनिया में बहुत लोग अपने जीवनसाथी से मिलने से पहले किसी और से प्यार कर चुके होते हैं।”</p>\n<p>श्रद्धा ने गहरी साँस ली।</p>\n<p>“कल रात लेटे-लेटे मैं इसे आपका सबसे बड़ा अपराध बनाना चाहती थी।”</p>\n<p>विक्रम ने पूछा—</p>\n<p>“अब क्या लगता है सबसे बड़ा अपराध क्या था?”</p>\n<p>श्रद्धा ने बिना एक क्षण गंवाए कहा—</p>\n<p>“ख़ामोशी।”</p>\n<p>एक शब्द।</p>\n<p>साफ़।</p>\n<p>बिना किसी मुलायम परत के।</p>\n<p>“आपने मुझे अपने अधूरे परिचय के साथ इस शादी में आने दिया।”</p>\n<p>वह बोली।</p>\n<p>“मुझे लगा मैं जिस इंसान को हाँ कह रही हूँ, उसके बारे में जितना जानना ज़रूरी है उतना जानती हूँ।”</p>\n<p>उसके जबड़े में हल्का तनाव आया।</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“आपकी हिम्मत से मुझे मिलने के बजाय वह मुझे एक दराज़ में मिला।”</p>\n<p>एक पल।</p>\n<p>“दुर्घटना से।”</p>\n<p>विक्रम की आँखें झुक गईं।</p>\n<p>“यही बात याद रखिएगा, विक्रम।”</p>\n<p>श्रद्धा का स्वर अब थोड़ा नरम था, अर्थ नहीं।</p>\n<p>“मुझसे पहले किसी से प्यार करना ग़लत नहीं था।”</p>\n<p>फिर—</p>\n<p>“मुझसे उसे छिपाना ग़लत था।”</p>\n<p>“समझ गया।”</p>\n<p>“उम्मीद है आप सच में समझे हैं।”</p>\n<p>श्रद्धा ने विक्रम की आँखों में देखते हुए कहा।</p>\n<p>“क्योंकि जब आज हम इतनी ईमानदारी से बात कर ही रहे हैं, तो एक और बात बिल्कुल साफ़ कर देना चाहती हूँ।”</p>\n<p>विक्रम ने प्रतीक्षा की।</p>\n<p>“आज मैं आपको एक मोहलत दे रही हूँ।”</p>\n<p>उसने कहा।</p>\n<p>“यह मेरा चुनाव है।”</p>\n<p>“लेकिन यह कोई ऐसी उधारी नहीं है जिसे आप ज़िंदगी भर खर्च करते रहें और मैं हर बार नया हिसाब खोलती रहूँ।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“अगर आगे कभी मुझे पता चला कि कोई और बड़ी बात थी जो आपने जानबूझकर नहीं बताई—नैना के बारे में, किसी और के बारे में, अतीत की या वर्तमान की—तो यह मोहलत दूसरी बार नहीं मिलेगी।”</p>\n<p>उसकी आँखों में कोई गुस्सा नहीं था।</p>\n<p>इसलिए बात और अंतिम लगी।</p>\n<p>“इसे धमकी मत समझिएगा।”</p>\n<p>उसने कहा।</p>\n<p>“मैं धमकियाँ नहीं देती।”</p>\n<p>एक छोटा-सा ठहराव।</p>\n<p>“मैं पहले से बता देती हूँ कि मुझसे क्या उम्मीद रखनी चाहिए।”</p>\n<p>श्रद्धा का स्वर ज़रा-सा सूखा हो गया।</p>\n<p>“ताकि बाद में कोई यह न कह सके कि उसे पता नहीं था।”</p>\n<p>“यह जायज़ है।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“जायज़ से थोड़ा ज़्यादा है।”</p>\n<p>श्रद्धा ने उत्तर दिया।</p>\n<p>“उदार भी है।”</p>\n<p>श्रद्धा का चेहरा फिर सख़्त हो गया।</p>\n<p>“शायद अभी आपको पूरा अंदाज़ा नहीं कि आज मैं क्या-क्या नहीं कर रही।”</p>\n<p>विक्रम उसकी ओर देखता रहा।</p>\n<p>“मैं जा सकती थी।”</p>\n<p>“आपकी माँ को जाकर बता सकती थी कि उनके बेटे ने किस तरह अपनी शादी शुरू की है।”</p>\n<p>“आपको सबके सामने शर्मिंदा कर सकती थी।”</p>\n<p>उसने शांत स्वर में कहा।</p>\n<p>“इनमें से कुछ भी नहीं कर रही।”</p>\n<p>एक साँस।</p>\n<p>“मैं हम दोनों के लिए चुप गरिमा चुन रही हूँ।”</p>\n<p>फिर बहुत स्पष्ट—</p>\n<p>“अब आगे आपका काम है कि इस चुनाव को कमाएँ।”</p>\n<p>“सिर्फ इसका फ़ायदा न उठाइएगा।”</p>\n<p>बरामदे में फिर कुछ पल ख़ामोशी रही।</p>\n<p>अलाव की गंध अब और गहरी लग रही थी।</p>\n<p>रात पूरी तरह उतर चुकी थी।</p>\n<p>श्रद्धा उठ खड़ी हुई।</p>\n<p>शॉल कंधे पर कसकर लपेटा।</p>\n<p>बात उसके लिए समाप्त हो चुकी थी।</p>\n<p>दरवाज़े तक पहुँचकर रुकी।</p>\n<p>“और कल जो कहा था, वह अब भी सच है।”</p>\n<p>विक्रम ने श्रद्धा की ओर देखा।</p>\n<p>“मुझे वक्त चाहिए।”</p>\n<p>उसने कहा।</p>\n<p>“आज मैं आपको कोरा पन्ना नहीं दे रही।”</p>\n<p>एक पल।</p>\n<p>“बस मौका दे रही हूँ—कि आप धीरे-धीरे उसके लायक बन सकें।”</p>\n<p>फिर वह भीतर चली गई। दरवाज़ा उसने भिड़ाया, बंद नहीं किया।</p>\n<p>विक्रम बरामदे में अकेला रह गया।</p>\n<p>काफी देर तक।</p>\n<p>रात उसके चारों ओर वैसे उतरती रही जैसे कभी-कभी किसी इंसान के चारों ओर कोई ऐसा सच उतरता है जिसे सुन लेने के बाद वह अपने पुराने रूप में वापस नहीं जा सकता।</p>\n<p>श्रद्धा ने उसे माफ़ नहीं किया था।</p>\n<p>कम-से-कम अभी नहीं।</p>\n<p>उसने उससे अतीत मिटाने को भी नहीं कहा था।</p>\n<p>न नैना को भूलने को।</p>\n<p>न यह साबित करने को कि जो प्रेम कभी था, वह झूठ था।</p>\n<p>उसने उससे केवल एक चीज़ माँगी थी—</p>\n<p>कि आगे से उसकी ज़िंदगी में मौजूद सच उसे किसी बंद दराज़ से न मिले।</p>\n<p>वह उसके अतीत से लड़ नहीं रही थी।</p>\n<p>वह अपने वर्तमान में अपनी जगह माँग रही थी—</p>\n<p>पूरी,</p>\n<p>जानकारी के साथ,</p>\n<p>और बिना किसी छिपे हुए दरवाज़े के।</p>\n<p>उस रात उनकी शादी माफ़ी पर नहीं, एक शर्त वाली मोहलत पर टिकी थी—जिसे श्रद्धा ने पूरे होश में दिया था, और जिसका हकदार विक्रम को आगे के वर्षों में अपनी ईमानदारी से बनना था।</p>"}, {"chapter": 39, "title": "अध्याय 36 — बंद दरवाज़े के उस पार", "content": "<h1>अध्याय 36 — बंद दरवाज़े के उस पार</h1>\n<p>अगली ही सुबह विक्रम चला गया।</p>\n<p>छुट्टी का सातवाँ और आख़िरी दिन इतनी जल्दी आ गया था कि दोनों में से कोई उसके लिए ठीक से तैयार नहीं था।</p>\n<p>गेट पर श्रद्धा उसके सामने खड़ी थी।</p>\n<p>पिछली दो रातों की सारी बातें उनके बीच अब भी मौजूद थीं—पुराना फोन, नैना, कविता, वह खून से लिखा खत, श्रद्धा की दी हुई मोहलत और उसके साथ रखी वह साफ़ शर्त कि अब कोई बड़ा सच उसे किसी बंद दराज़ से नहीं मिलना चाहिए।</p>\n<p>लेकिन विदा के उस छोटे-से पल में दोनों ने उनमें से किसी का नाम नहीं लिया।</p>\n<p>“जब हो सके, लिखिएगा।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>फिर जैसे बात सुधारते हुए बोली—</p>\n<p>“या फोन कीजिएगा।”</p>\n<p>एक पल।</p>\n<p>“अगर चुनने का मौका हो तो आपके नपे-तुले वाक्य पढ़ने से अच्छा आपकी आवाज़ सुनना पसंद करूँगी।”</p>\n<p>विक्रम के होंठों पर हल्की मुस्कान आई।</p>\n<p>“फोन करूँगा।”</p>\n<p>“अच्छा।”</p>\n<p>श्रद्धा ने उसे वैसे छूकर विदा नहीं किया जैसे प्रेम में पड़ी पत्नी करती।</p>\n<p>और विक्रम ने उससे इसकी उम्मीद भी नहीं की।</p>\n<p>अभी नहीं।</p>\n<p>लेकिन श्रद्धा की आँखें उसकी आँखों पर उस विदाई की ज़रूरत से कुछ पल ज़्यादा ठहरी रहीं।</p>\n<p>उन कुछ पलों में कुछ था—</p>\n<p>अभी इतना नया कि दोनों उसका नाम नहीं जानते थे,</p>\n<p>लेकिन इतना वास्तविक कि उसे अनदेखा भी नहीं किया जा सकता था।</p>\n<p>जाते-जाते विक्रम ने एक बार मुड़कर देखा। श्रद्धा गेट पर वैसी ही खड़ी थी—हाथ अपने ही हाथों में बँधे हुए।</p>\n<p>फिर विक्रम चला गया।</p>\n<p>दो दिन के भीतर वह यूनिट में वापस था।</p>\n<p>और लगभग तुरंत फिर ऑपरेशनल रोटेशन में।</p>\n<p>उसी हफ्ते वह ऑपरेशन आया जिसने सब बदल दिया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>टारगेट हासिल हो चुका था।</p>\n<p>कैंप न्यूट्रलाइज़ कर दिया गया था।</p>\n<p>टीम वापस निकल रही थी।</p>\n<p>सब कुछ लगभग ख़त्म हो चुका था—</p>\n<p>तभी उस पोज़िशन से फायर का एक बर्स्ट आया जिसे पूरी तरह क्लियर मान लिया गया था।</p>\n<p>गोली लगने से पहले विक्रम ने आवाज़ सुनी भी या नहीं, उसे बाद में याद नहीं रहा।</p>\n<p>उसे पहले सिर्फ एक ज़ोरदार चोट महसूस हुई—</p>\n<p>पेट के निचले हिस्से में।</p>\n<p>इतनी अचानक कि शरीर ने दर्द को समझने से पहले ही उसका असर दर्ज कर लिया।</p>\n<p>ट्रेनिंग ने बाकी काम किया।</p>\n<p>वह गिरा नहीं।</p>\n<p>अपने साथ दो जवानों को तत्काल फायर लाइन से बाहर निकाला और आड़ तक पहुँच गया।</p>\n<p>तभी घाव ने ख़ुद को पूरी तरह ज़ाहिर किया।</p>\n<p>वर्दी पर खून तेज़ी से फैल रहा था।</p>\n<p>फॉरवर्ड पोस्ट पर उसे स्टेबलाइज़ किया गया।</p>\n<p>वहाँ से कई चरणों में इवैकुएशन हुआ।</p>\n<p>और आख़िर उसे दिल्ली के रिसर्च एंड रेफरल हॉस्पिटल पहुँचाया गया।</p>\n<p>दिल्ली पहुँचने के कुछ ही घंटों के भीतर वह ऑपरेशन थिएटर में था।</p>\n<p>बेहोश।</p>\n<p>अपने आसपास हो रही हर चीज़ से पूरी तरह अनजान।</p>\n<p>और उसी दौरान उसके पिता का फोन बजा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दोपहर ढलने को थी।</p>\n<p>घर का आँगन रोज़ की तरह लोगों से भरा था।</p>\n<p>माँ और श्रद्धा धूप सरकती चारपाई पर बैठी मटर छील रही थीं। बड़ा भाई खेत से लौट चुका था और हैंडपंप पर हाथ-मुँह धो रहा था।</p>\n<p>फोन विक्रम के पिता ने उठाया।</p>\n<p>बाकी किसी ने दूसरी ओर की आवाज़ नहीं सुनी।</p>\n<p>लेकिन कुछ ही क्षणों में उनके चेहरे पर जो बदला, उसे सबने देख लिया।</p>\n<p>और पूरा आँगन जैसे एक साथ स्थिर हो गया।</p>\n<p>कई घरों में बुरी ख़बर शब्द बनकर पहुँचने से पहले ही पहचानी जाती है।</p>\n<p>विक्रम के घर में भी उस दोपहर ऐसा ही हुआ।</p>\n<p>फोन कट गया।</p>\n<p>पिता ने कुछ क्षण मोबाइल हाथ में ही पकड़े रखा।</p>\n<p>फिर बहुत संभली हुई आवाज़ में बोले—</p>\n<p>“विक्रम को गोली लगी है।”</p>\n<p>माँ के हाथ रुक गए।</p>\n<p>श्रद्धा की उँगलियों के बीच आधी खुली मटर की फली वैसी ही रह गई।</p>\n<p>“ऑपरेशन में।”</p>\n<p>उन्होंने कहा।</p>\n<p>“दिल्ली ले गए हैं। अस्पताल में है।”</p>\n<p>कुछ पल कोई नहीं हिला।</p>\n<p>उसने कहा था—फोन करूँगा। फोन आया था। बस उसकी आवाज़ में नहीं।</p>\n<p>श्रद्धा के भीतर जैसे अचानक सब कुछ शांत हो गया।</p>\n<p>विचार नहीं।</p>\n<p>आँसू नहीं।</p>\n<p>डर भी अभी अपने पूरे नाम के साथ नहीं।</p>\n<p>बस एक ठंडी, गहरी ख़ामोशी—</p>\n<p>जिसने उसके भीतर बाकी हर चीज़ के लिए जगह बंद कर दी।</p>\n<p>बरामदे वाली रात का गुस्सा वहीं था।</p>\n<p>श्रद्धा ने विक्रम को माफ़ नहीं किया था।</p>\n<p>न अपनी चोट अचानक छोटी हो गई थी।</p>\n<p>बस उस क्षण उसका कोई महत्व नहीं बचा था।</p>\n<p>उस पल केवल एक सवाल था—</p>\n<p><b>विक्रम जीवित है?</b></p>\n<p>श्रद्धा उठ खड़ी हुई।</p>\n<p>“मैं जा रही हूँ।”</p>\n<p>चप्पलों की ओर हाथ बढ़ाते हुए श्रद्धा ने कहा।</p>\n<p>“हम सब जा रहे हैं।”</p>\n<p>पिता ने जवाब दिया।</p>\n<p>बड़ा भाई तब तक दीवार के हुक से गाड़ी की चाबी उठा चुका था।</p>\n<p>कुछ ही मिनटों में पूरा परिवार रास्ते पर था।</p>\n<p>पीछे की सीट पर श्रद्धा के दोनों हाथ उसकी गोद में इतनी कसकर जुड़े थे कि उँगलियों के जोड़ सफ़ेद पड़ गए थे।</p>\n<p>बगल में माँ बैठी थीं।</p>\n<p>बिल्कुल चुप।</p>\n<p>सीधे सामने देखते हुए—</p>\n<p>जैसे सड़क नहीं, किसी ऐसी जगह को देख रही हों जहाँ बाकी किसी की नज़र नहीं पहुँच सकती।</p>\n<p>ट्रैफिक में दिल्ली पहुँचने में करीब दो घंटे लगे।</p>\n<p>श्रद्धा ने पूरे रास्ते लगभग कुछ नहीं कहा।</p>\n<p>उसका मन किसी एक विचार को पूरा पकड़ ही नहीं पा रहा था।</p>\n<p>कभी पटौदी के उस बगीचे में खड़ा विक्रम सामने आ जाता—</p>\n<p>हल्की मुस्कान के साथ, तयशुदा सवालों के लिए अपने “आकर्षक जवाब” तैयार किए हुए।</p>\n<p>और अगले ही क्षण—</p>\n<p>कुछ नहीं।</p>\n<p>सिर्फ एक खाली जगह।</p>\n<p>इतनी पूरी कि किसी निश्चित डर से भी ज़्यादा भयावह।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>जब वे अस्पताल पहुँचे, दिल्ली पर शाम उतर रही थी।</p>\n<p>विक्रम की सर्जरी हो चुकी थी।</p>\n<p>उसे आईसीयू में शिफ्ट कर दिया गया था।</p>\n<p>वहाँ एक समय में केवल एक अटेंडेंट को, वह भी कुछ देर के लिए, भीतर जाने की अनुमति थी।</p>\n<p>श्रद्धा ने उसे पहली बार आईसीयू के दरवाज़े में लगे छोटे-से शीशे से देखा।</p>\n<p>चेहरा बहुत पीला था।</p>\n<p>इतना कि उस एक दृश्य ने उसे उन सारी बातों से ज़्यादा डरा दिया जो रास्ते भर उसके दिमाग में आती रही थीं।</p>\n<p>वह सो रहा था।</p>\n<p>डॉक्टर ने कहा—सचमुच सो रहा है; बड़ी सर्जरी के बाद दवाओं से आने वाली गहरी नींद।</p>\n<p>पर बंद दरवाज़े के बाहर बैठे इंसान के लिए “सो रहा है” और “जागेगा” के बीच की दूरी कई बार पूरी दुनिया जितनी लगती है।</p>\n<p>परिवार आईसीयू के बाहर कॉरिडोर में बैठ गया।</p>\n<p>श्रद्धा प्लास्टिक की कुर्सी पर थी।</p>\n<p>हाथ फिर उसी तरह गोद में जुड़े हुए।</p>\n<p>नज़र बंद दरवाज़े पर।</p>\n<p>और वहीं, उस दरवाज़े के सामने, उसका मन उस जगह चला गया जहाँ जाने की उसने उसे कोई इजाज़त नहीं दी थी।</p>\n<p>नैना।</p>\n<p>नैना ने एक लड़के से पेड़ के नीचे प्रेम किया था।</p>\n<p>उस समय, जब प्रेम को अभी किसी गोली, अस्पताल या बंद आईसीयू दरवाज़े से बचकर निकलना नहीं पड़ा था।</p>\n<p>नैना का प्रेम उससे एक पिता के डर ने छीना था—</p>\n<p>मौत ने नहीं।</p>\n<p>कविता।</p>\n<p>कविता ने विक्रम से वैसे प्रेम किया था जैसे कोई बरसात से करता है—</p>\n<p>पूरी तरह,</p>\n<p>यह जानते हुए भी कि मौसम हमेशा नहीं रहता।</p>\n<p>कम-से-कम कविता को उस अंत की आहट मिली थी जिसकी ओर वह बढ़ रही थी।</p>\n<p>और श्रद्धा?</p>\n<p>वह एक प्लास्टिक की कुर्सी पर बैठी थी।</p>\n<p>उस इंसान से शादी किए अभी मुश्किल से दो हफ्ते हुए थे।</p>\n<p>सामने एक दरवाज़ा था जिसे वह खोल नहीं सकती थी।</p>\n<p>उसके पीछे उसका पति था।</p>\n<p>और उसके पास न कोई साफ़ अंत था, न कोई तय मौसम—</p>\n<p>सिर्फ इंतज़ार।</p>\n<p>सिर्फ न जानना।</p>\n<p>और उस जीवन का पहला असली हिसाब, जिस पर उसने अपना नाम तो लिख दिया था मगर जिसकी कीमत अभी तक पूरी तरह समझी नहीं थी।</p>\n<p>अगर विक्रम उस दरवाज़े के पीछे से वापस नहीं आया—</p>\n<p>तो क्या बचेगा?</p>\n<p>एक बहुत कम उम्र की विधवा—</p>\n<p>जिसे लोग सांत्वना देते हुए भी शायद ठीक से न समझ पाएँ कि वह किस चीज़ का शोक मना रही है।</p>\n<p>एक ऐसे इंसान का,</p>\n<p>जिसने ख़ुद स्वीकार किया था कि उसका दिल उससे पहले दो बार कहीं और पूरी तरह जा चुका था।</p>\n<p>और श्रद्धा को शायद यह जानने का समय ही न मिले कि उस दिल में उसके लिए आख़िर कितनी जगह बन सकती थी।</p>\n<p>उसी कॉरिडोर में उसने विक्रम से प्रेम करने का कोई फ़ैसला नहीं किया।</p>\n<p>प्रेम फ़ैसले से आता भी कहाँ है।</p>\n<p>उसे केवल इतना समझ आया—</p>\n<p>जो कुछ उसके भीतर विक्रम के लिए बन चुका है, वह अब केवल इसलिए मिटने से इनकार कर रहा है कि उसका समय ग़लत था, उसका रास्ता उलझा हुआ था, या उससे पहले उस रास्ते पर दो और लड़कियाँ चल चुकी थीं।</p>\n<p>यह समझ उसे इंतज़ार से भी ज़्यादा डरा गई।</p>\n<p>विक्रम के पिता आकर उसके पास बैठ गए।</p>\n<p>“कुछ देर ऐसा ही रहेगा।”</p>\n<p>उन्होंने धीमे से कहा।</p>\n<p>“डॉक्टर कह रहा था सर्जरी ठीक हुई है।”</p>\n<p>फिर—</p>\n<p>“गोली ऐसी किसी जगह नहीं लगी जिसे वे ठीक न कर सकें।”</p>\n<p>श्रद्धा ने सिर हिला दिया।</p>\n<p>शब्द उसने सुने।</p>\n<p>लेकिन वे अभी उसके भीतर उस जगह तक नहीं पहुँच पा रहे थे जहाँ डर बैठा था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>आधी रात के बाद कहीं विक्रम को ठीक से होश आया।</p>\n<p>नर्स बाहर आई।</p>\n<p>“माँ को बुला रहा है।”</p>\n<p>एक बार में एक ही इंसान जा सकता था।</p>\n<p>पहले माँ गईं।</p>\n<p>कुछ मिनट बाद लौटीं तो आँखें भीगी हुई थीं।</p>\n<p>उन्होंने श्रद्धा को देखा।</p>\n<p>“तुझे भी बुला रहा है।”</p>\n<p>फिर लगभग उतावली में—</p>\n<p>“जा। नर्स फिर मना कर दे उससे पहले।”</p>\n<p>श्रद्धा उठी।</p>\n<p>दरवाज़ा खुला।</p>\n<p>वह भीतर गई।</p>\n<p>आवाज़ सुनकर विक्रम ने बहुत धीरे सिर उसकी तरफ मोड़ा।</p>\n<p>श्रद्धा को देखकर विक्रम के चेहरे पर साफ़ आश्चर्य आया।</p>\n<p>जैसे उसके किसी हिस्से ने सचमुच उम्मीद नहीं की थी कि वह आएगी।</p>\n<p>श्रद्धा उसके पास पहुँची।</p>\n<p>श्रद्धा ने विक्रम का खाली हाथ अपने दोनों हाथों में ले लिया।</p>\n<p>पकड़ ज़रूरत से कुछ ज़्यादा कस गई।</p>\n<p>विक्रम ने श्रद्धा को देखा।</p>\n<p>श्रद्धा की आवाज़ ने उस क्षण उसका साथ उतना नहीं दिया जितना वह चाहती थी।</p>\n<p>“मैं आ गई।”</p>\n<p>बस इतना कहकर वह रुकी।</p>\n<p>फिर लगभग उसी साँस में—</p>\n<p>“और कहाँ जाती?”</p>\n<p>श्रद्धा की आँखें भर आईं, मगर उसने नज़र नहीं हटाई।</p>\n<p>“दोबारा मुझे ऐसा डर मत दीजिएगा।”</p>\n<p>आवाज़ टूट गई।</p>\n<p>“ज़िंदगी में कभी नहीं।”</p>\n<p>विक्रम के पास उस बात का पूरा जवाब देने की ताकत नहीं थी।</p>\n<p>नींद उसे फिर नीचे खींच रही थी।</p>\n<p>कुछ मिनट बाद नर्स ने श्रद्धा के कंधे को हल्के से छुआ।</p>\n<p>समय ख़त्म हो गया था।</p>\n<p>श्रद्धा ने उसका हाथ छोड़ा।</p>\n<p>और बाहर आ गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दूसरे दिन विक्रम को आईसीयू से वार्ड में शिफ्ट कर दिया गया।</p>\n<p>अब नियम कुछ ढीले थे।</p>\n<p>एक सामान्य बेड।</p>\n<p>उसके पास एक कुर्सी।</p>\n<p>ऐसी कुर्सी जिस पर कोई कई घंटे बैठ सकता था—</p>\n<p>और श्रद्धा ने पहली ही शाम से रातें अपने हिस्से में ले लीं।</p>\n<p>आगे के दिनों में उनके बीच जो बदला, वह किसी एक बड़ी बातचीत में नहीं बदला।</p>\n<p>न किसी घोषणा में।</p>\n<p>न किसी अचानक किए गए वादे में।</p>\n<p>वह उन छोटी, बिल्कुल साधारण चीज़ों में बदलता गया जिन्हें बाहर से देखने वाला प्रेम की कहानी का हिस्सा भी न माने।</p>\n<p>श्रद्धा ने बिना पूछे सीख लिया कि पानी का गिलास विक्रम किस तरफ रखना पसंद करता है।</p>\n<p>एक सुबह नर्स के राउंड से पहले ही उसने देख लिया कि हल्के बुखार के कारण ड्रेसिंग समय से पहले बदलनी चाहिए; डॉक्टर के आने तक वह किसी को बुला चुकी थी।</p>\n<p>दूसरे दिन विक्रम का मिज़ाज ख़राब था—</p>\n<p>उस खास तरह की चिड़चिड़ाहट जिसमें एक आत्मनिर्भर इंसान सबसे छोटी ज़रूरत के लिए भी किसी और पर निर्भर होने को अपमान की तरह महसूस करने लगता है।</p>\n<p>श्रद्धा ने वह दिन भी उसके साथ काट लिया।</p>\n<p>बिना उसे यह महसूस कराए कि मदद की ज़रूरत ने उसे किसी तरह छोटा कर दिया है।</p>\n<p>लेकिन असली मोड़ चौथी रात आया।</p>\n<p>रात के दो बजे के बाद विक्रम की नींद खुली।</p>\n<p>दर्द की एक तेज़ लहर पेट से उठी।</p>\n<p>विक्रम का जबड़ा कस गया।</p>\n<p>उसने आवाज़ नहीं की।</p>\n<p>सैनिक की पुरानी आदत थी—</p>\n<p>तकलीफ़ हो तो पहले देखो कितनी देर अकेले सह सकते हो।</p>\n<p>वह बिल्कुल स्थिर पड़ा रहा।</p>\n<p>साँस को नापकर भीतर-बाहर करता हुआ।</p>\n<p>उसे लगा श्रद्धा बगल की कुर्सी पर सो रही है।</p>\n<p>वह सो नहीं रही थी।</p>\n<p>कई मिनट से उसे देख रही थी।</p>\n<p>आँखों के आसपास आया वह मामूली तनाव।</p>\n<p>शरीर की वह ज़रूरत से ज़्यादा सख़्त स्थिरता।</p>\n<p>वह नियंत्रित साँस—</p>\n<p>जिसमें इंसान दर्द छिपा तो सकता है, मिटा नहीं सकता।</p>\n<p>श्रद्धा ने एक भी सवाल नहीं पूछा।</p>\n<p>बस उठी।</p>\n<p>कॉरिडोर में गई।</p>\n<p>और विक्रम यह तय भी नहीं कर पाया था कि दर्द के बारे में किसी को बताए या नहीं, उससे पहले वह नाइट नर्स और दवा की अगली डोज़ के साथ वापस आ चुकी थी।</p>\n<p>दर्द कुछ कम हुआ तो विक्रम ने कहा—</p>\n<p>“तुम्हें ये करने की ज़रूरत नहीं थी।”</p>\n<p>श्रद्धा ने उसकी ओर देखा।</p>\n<p>“मैं माँगने वाला नहीं था।”</p>\n<p>“मुझे पता है।”</p>\n<p>वह फिर कुर्सी पर बैठ गई।</p>\n<p>विक्रम का हाथ अपने हाथ में लेते हुए बोली—</p>\n<p>“इसीलिए तो किया।”</p>\n<p>बस इतना।</p>\n<p>लेकिन विक्रम उसे काफी देर देखता रहा।</p>\n<p>वार्ड की धुँधली रोशनी में, दवा के धीरे-धीरे असर करते हुए, उसके भीतर कोई ऐसी बात अपनी जगह बना रही थी जिसका दवा से कोई संबंध नहीं था।</p>\n<p>किसी का उसे इतनी जल्दी,</p>\n<p>इतनी ठीक तरह,</p>\n<p>बिना उसके कहे पढ़ लेना—</p>\n<p>यह उसके लिए नया था।</p>\n<p>नैना के साथ लगभग दो वर्षों में भी किसी ने उसके मौन को इस तरह नहीं पढ़ा था कि शब्द आने से पहले ही ज़रूरत पहचान ली जाए।</p>\n<p>और जिस स्त्री को उसने अपनी शादी के शुरुआती दिनों में अपने से सावधानी से दूर रखा था—</p>\n<p>वही अब उसके चेहरे की एक छोटी-सी सिकुड़न से वह बात समझ रही थी जिसे वह बोलना नहीं चाहता था।</p>\n<p>विक्रम के पास अभी इसका कोई नाम नहीं था।</p>\n<p>न वह जानता था यह कहाँ जाएगा।</p>\n<p>बस इतना महसूस हुआ कि श्रद्धा और अपने बीच जो दूरी वह इतने दिनों से नापकर रख रहा था—</p>\n<p>वह अचानक ज़रूरी नहीं लग रही।</p>\n<p>विक्रम ने बहुत धीमे कहा—</p>\n<p>“मैं इसके लायक नहीं हूँ।”</p>\n<p>वह एक पल रुका, जैसे बात अभी पूरी न हुई हो।</p>\n<p>“अभी नहीं। शायद बहुत समय तक नहीं।”</p>\n<p>श्रद्धा की उँगलियाँ उसके हाथ के आसपास वैसे ही रहीं। थकान के बीच भी उसके चेहरे का तनाव ज़रा ढीला पड़ा।</p>\n<p>“लायक तो हैं, असल में।”</p>\n<p>उसने कहा।</p>\n<p>“मेरी देखभाल के तो लायक हैं, विक्रम।”</p>\n<p>फिर हल्के-से व्यंग्य में—</p>\n<p>“गोली खाकर आने का बहुत असुविधाजनक इनाम समझ लीजिए।”</p>\n<p>विक्रम उसे देखता रहा।</p>\n<p>“मैं यहाँ हूँ।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“आप बहस करें या न करें, देखभाल तो मैं करूँगी।”</p>\n<p>श्रद्धा ने उसके हाथ पर अपनी पकड़ हल्की-सी कस दी।</p>\n<p>“अब सो जाइए।”</p>\n<p>“बाकी मुझे देखने दीजिए।”</p>\n<p>विक्रम ने और कुछ नहीं कहा।</p>\n<p>उसकी उँगलियाँ श्रद्धा की उँगलियों के चारों ओर बस थोड़ा-सा कस गईं।</p>\n<p>फिर उसने आँखें बंद कर लीं।</p>\n<p>वार्ड शांत था।</p>\n<p>दवा अपना काम कर रही थी।</p>\n<p>दर्द धीरे-धीरे पीछे हट रहा था।</p>\n<p>और उसके साथ ही विक्रम के भीतर भी कुछ ऐसा ढीला पड़ रहा था जिसे उसने बहुत समय से कसकर पकड़ रखा था।</p>\n<p>पहली बार उसे किसी की देखभाल में होना कमज़ोरी नहीं लगा।</p>\n<p>शायद इसलिए कि श्रद्धा उससे बदले में कुछ नहीं माँग रही थी।</p>\n<p>न कोई स्वीकारोक्ति।</p>\n<p>न प्रेम।</p>\n<p>न नैना और कविता पर जीत।</p>\n<p>वह बस वहाँ थी।</p>\n<p>और कई बार किसी रिश्ते में पहला घर शब्दों से नहीं बनता—</p>\n<p>किसी अस्पताल की आधी रात में रखी एक कुर्सी से बनता है,</p>\n<p>पानी के गिलास की सही तरफ से,</p>\n<p>बिना माँगे बुला ली गई नर्स से,</p>\n<p>और उस हाथ से—</p>\n<p>जो आपका दर्द आपसे पहले पहचान ले।</p>"}, {"chapter": 40, "title": "अध्याय 37 — जो बचा रहा", "content": "<h1>अध्याय 37 — जो बचा रहा</h1>\n<p>ग्यारह दिन बाद विक्रम को अस्पताल से छुट्टी मिली।</p>\n<p>शरीर में अभी कमज़ोरी थी। पेट का घाव पूरी तरह भरा नहीं था और चलते समय उसके कदमों में वह सावधानी आ गई थी जो किसी इंसान की आदत नहीं, दर्द सिखाता है। फिर भी डॉक्टरों को भरोसा था कि अब बाकी स्वास्थ्य-लाभ घर पर हो सकता है।</p>\n<p>वापसी के पूरे रास्ते श्रद्धा उसके बगल में बैठी रही।</p>\n<p>आधे से कुछ आगे पहुँचने पर विक्रम का सिर अनायास उसके कंधे पर टिक गया। शायद थकान थी, शायद दवाओं का असर। श्रद्धा ने उसे हटाया नहीं। बस अपना एक हाथ उसके बाजू पर रख दिया—इतना हल्का कि घाव के आसपास कहीं दबाव न पड़े, और इतना स्थिर कि स्पर्श बना रहे।</p>\n<p>उसके बाद के महीने उनकी शादी को मिला एक ऐसा लंबा, अखंड समय बन गए जो फौजी ज़िंदगी शायद ही किसी दंपती को आसानी से देती है।</p>\n<p>शुरुआती हफ्तों में रातें सबसे मुश्किल थीं।</p>\n<p>घाव उसे देर तक एक ही करवट नहीं रहने देता। नींद आती, दर्द जगाता, फिर कुछ देर चुप्पी रहती।</p>\n<p>और अक्सर उस चुप्पी में श्रद्धा भी जाग रही होती।</p>\n<p>अब यह केवल पत्नी होने का कर्तव्य नहीं था।</p>\n<p>दोनों धीरे-धीरे यह समझने लगे थे कि रात के वे घंटे, जिन्हें दर्द ने उनसे नींद की तरह छीन लिया था, वही घंटे उन्हें एक-दूसरे के लिए समय की तरह वापस मिल रहे हैं।</p>\n<p>एक दोपहर विक्रम ने बिना बुलाए उठकर अपना कोई काम ख़ुद करने की कोशिश की।</p>\n<p>कोशिश बुरी तरह नाकाम रही।</p>\n<p>श्रद्धा ने उसे वापस तकियों से टिकाते हुए कहा—</p>\n<p>“बहुत ख़राब मरीज़ हैं आप।”</p>\n<p>“मुझे कोई संभाले, ये पसंद नहीं।”</p>\n<p>“किसी को पसंद नहीं होता।”</p>\n<p>श्रद्धा ने चादर ठीक की।</p>\n<p>“बस ज़्यादातर लोगों में इतनी अक्ल होती है कि पेट में गोली का छेद अभी पूरी तरह बंद न हुआ हो तो कुछ दिन अपनी पसंद को आराम दे दें।”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>श्रद्धा वहीं पलंग के किनारे बैठ गई।</p>\n<p>चेहरे पर सख़्ती थी, लेकिन उसके नीचे अब वह नरमी भी थी जिसे दोनों पहचानने लगे थे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उन महीनों में दोनों ने जितनी बातें कीं, उतनी शादी के उस पहले छोटे-से हफ्ते में मिलाकर भी नहीं की थीं।</p>\n<p>श्रद्धा ने अपने बारे में धीरे-धीरे बताया।</p>\n<p>एक साथ नहीं।</p>\n<p>जैसे इंसान किसी नए घर की खिड़कियाँ एक ही दिन नहीं खोलता—एक-एक करके खोलता है, ताकि भीतर की हवा भी बदले और आँखें भी रोशनी की आदी होती जाएँ।</p>\n<p>बचपन में वह पाँच अलग-अलग स्कूलों में पढ़ी थी। पिता की नौकरी में हर कुछ वर्षों में तबादला होता रहता था। माँ हर बार घर समेटतीं, बच्चों को साथ ले जातीं और नई जगह पर फिर से जीवन खड़ा कर देतीं।</p>\n<p>“उन्होंने हमारे सामने कभी शिकायत नहीं की।”</p>\n<p>श्रद्धा ने एक रात कहा।</p>\n<p>फिर ख़ुद ही बात सुधारी—</p>\n<p>“इसका मतलब ये नहीं कि उनके लिए सब आसान था।”</p>\n<p>एक पल।</p>\n<p>“अनुशासन था। आसानी नहीं। उन्होंने हर दिन तय किया कि बच्चों को उनकी थकान का बोझ नहीं उठाना पड़ेगा।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>श्रद्धा ने उसे अपने साहित्य में किए एम.ए. के बारे में बताया—वह डिग्री जिसके बारे में शादी के बाद लोगों ने लगभग पूछना बंद कर दिया था।</p>\n<p>और उस इच्छा के बारे में भी जो अभी ख़त्म नहीं हुई थी।</p>\n<p>“कभी कॉलेज में पढ़ाना है।”</p>\n<p>उसने कहा।</p>\n<p>“बस किसी पोस्टिंग पर इतना समय मिल जाए कि ज़िंदगी दो साल तक एक ही शहर में टिक सके।”</p>\n<p>विक्रम ने पूछा—</p>\n<p>“शादी से पहले ये बताया था किसी को?”</p>\n<p>श्रद्धा ने उसे देखा।</p>\n<p>“पूछा किसने था?”</p>\n<p>उस छोटे-से जवाब के बाद विक्रम कुछ देर चुप रहा।</p>\n<p>पहली बार उसे समझ आया कि किसी व्यक्ति के बारे में बहुत कुछ न जानना हमेशा उसके छिपाने की वजह से नहीं होता।</p>\n<p>कई बार हमने पूछा ही नहीं होता।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम भी खुलने लगा।</p>\n<p>नैना और कविता की पूरी कहानी फिर से नहीं।</p>\n<p>अभी नहीं।</p>\n<p>लेकिन उनके नीचे दबा वह इंसान—</p>\n<p>जिसके बारे में उसने ख़ुद भी बहुत कम सोचा था।</p>\n<p>विक्रम ने बताया कि बड़ा भाई खेत और ज़मीन की ज़िम्मेदारी में धीरे-धीरे अपनी जगह पा गया था। छोटे भाई से घर को पढ़ाई और किसी अकादमिक दिशा की उम्मीद थी।</p>\n<p>और विक्रम?</p>\n<p>वह दोनों के बीच कहीं था।</p>\n<p>उसे बस वर्दी मिल गई—</p>\n<p>एक ऐसी संरचना जिसमें वह बहुत अच्छा हो सकता था, बिना यह पूछे कि वह असल में चाहता क्या है।</p>\n<p>एक शाम दोनों बरामदे में बैठे थे जब विक्रम ने कहा—</p>\n<p>“मुझे नहीं लगता मैंने आर्मी को वैसे चुना था जैसे लोग मानते हैं कि सैनिक चुनते हैं।”</p>\n<p>श्रद्धा ने उसकी ओर देखा।</p>\n<p>“फिर?”</p>\n<p>“मैं उसमें चला गया।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“क्योंकि वहाँ नियम थे। लक्ष्य थे। मेहनत करो तो पता रहता था अच्छा कर रहे हो या बुरा।”</p>\n<p>उसने कुछ क्षण सामने देखा।</p>\n<p>“और शायद इसलिए भी कि वहाँ मुझे उस मुश्किल सवाल का जवाब नहीं देना पड़ता था कि मैं ज़िंदगी से सच में चाहता क्या हूँ।”</p>\n<p>श्रद्धा काफी देर चुप रही।</p>\n<p>फिर बोली—</p>\n<p>“एक बात कहूँ?”</p>\n<p>“कहो।”</p>\n<p>“उस रात से सोच रही हूँ।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>श्रद्धा ने बहुत सहज स्वर में कहा—</p>\n<p>“पुराने मकबरे कितने भी खूबसूरत हों, उनमें घर नहीं बसाए जाते।”</p>\n<p>विक्रम स्थिर हो गया।</p>\n<p>“आप वहाँ जा सकते हैं।”</p>\n<p>वह बोली।</p>\n<p>“याद कर सकते हैं। जिसे वहाँ दफनाया है उसके लिए दुख भी मना सकते हैं।”</p>\n<p>एक पल।</p>\n<p>“लेकिन अपना बिस्तर वहाँ ले जाकर नहीं रखते।”</p>\n<p>विक्रम की आँखें उससे नहीं हटीं।</p>\n<p>“मुझे लगता है आपका एक हिस्सा दो पुराने मकबरों में एक साथ रहने की कोशिश करता रहा है, विक्रम।”</p>\n<p>श्रद्धा ने नाम लिए।</p>\n<p>“कविता।”</p>\n<p>फिर—</p>\n<p>“नैना।”</p>\n<p>श्रद्धा के स्वर में न ईर्ष्या थी, न किसी मृत या बीते प्रेम के लिए तिरस्कार।</p>\n<p>“आप मन में वहाँ इतनी बार जाते रहे कि जिस घर में अब सचमुच रहते हैं, उसे पूरा बनाना शुरू ही नहीं कर पाए।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>श्रद्धा की आवाज़ थोड़ी नरम हुई।</p>\n<p>“मैं आपको वहाँ जाना बंद करने को नहीं कह रही।”</p>\n<p>“यादों पर मेरा कोई हक नहीं है।”</p>\n<p>फिर श्रद्धा ने विक्रम की आँखों में देखते हुए कहा—</p>\n<p>“बस इतना चाहती हूँ कि आपको पता रहे—आपने रहने के लिए कौन-सा घर चुना है।”</p>\n<p>काफी देर तक विक्रम चुप रहा।</p>\n<p>वर्षों से भीतर कोई चीज़ जिस जगह अटकी हुई थी, जैसे वहाँ पहली बार थोड़ी जगह बनी।</p>\n<p>श्रद्धा ने बात बदलने के बजाय उसे आगे बढ़ाया।</p>\n<p>“फिर शुरुआत कहाँ हुई थी?”</p>\n<p>“किसकी?”</p>\n<p>“आर्मी की।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“कुछ तो पहली चिंगारी रही होगी।”</p>\n<p>विक्रम के चेहरे पर हल्की, लगभग लड़कपन वाली मुस्कान आई।</p>\n<p>“एक फिल्म।”</p>\n<p>“फिल्म?”</p>\n<p>“मैं शायद तेरह-चौदह साल का था। रविवार की रात अकेला टीवी देख रहा था। घर में बाकी लोग सो चुके थे।”</p>\n<p>वह कुछ याद करते हुए बोला—</p>\n<p>“एलओसी: कारगिल आ रही थी।”</p>\n<p>“उस रात कुछ अटक गया दिमाग में।”</p>\n<p>फिर विक्रम ने कहा—</p>\n<p>“उसके बाद जितनी जंग वाली फिल्में मिल सकती थीं, ढूँढ़-ढूँढ़कर देखीं। पता ही नहीं चला कब वह चीज़, जिसे मैंने कभी बैठकर बाकायदा तय नहीं किया था, धीरे-धीरे फ़ैसला बन गई कि मुझे यही बनना है।”</p>\n<p>श्रद्धा ने पूछा—</p>\n<p>“और अब?”</p>\n<p>“अब क्या?”</p>\n<p>“अब पता है कि आप ज़िंदगी से क्या चाहते हैं?”</p>\n<p>विक्रम ने जवाब देने में समय लिया।</p>\n<p>“लगता है समझना शुरू कर रहा हूँ।”</p>\n<p>फिर—</p>\n<p>“धीरे-धीरे।”</p>\n<p>“धीरे ठीक है।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“मुझे कोई साफ़-सुथरा, पहले से तैयार जवाब देने से अच्छा है कि आप सच में उसे समझें।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>ऐसी रातें पूरे स्वास्थ्य-लाभ के दौरान लौटती रहीं।</p>\n<p>हर रात नहीं।</p>\n<p>लेकिन इतनी बार कि जब तक विक्रम की ताकत वापस आई, दोनों के बीच छोटी-छोटी स्वीकारोक्तियों का अपना एक निजी संग्रह बन चुका था—सवाल जिन्हें जल्दी में नहीं पूछा गया, जवाब जिन्हें अच्छा दिखने के लिए सँवारा नहीं गया।</p>\n<p>विक्रम ने जाना कि कुछ किताबों के अंत पर श्रद्धा रोती है और फिर ऐसे व्यवहार करती है जैसे कुछ हुआ ही न हो।</p>\n<p>यह भी कि शादी से पहले वह घूमना चाहती थी; शादी ने उस इच्छा को पूरी तरह ख़त्म नहीं किया था, बस योजनाओं को छोटा कर दिया था। उसे दुख इस बात का कम था कि वह नहीं जा सकी—</p>\n<p>इस बात का ज़्यादा कि किसी ने उससे पूछा ही नहीं कि वह जाना चाहती थी या नहीं।</p>\n<p>और श्रद्धा ने विक्रम को जाना।</p>\n<p>सिर्फ उस इंसान की सीमित रूपरेखा नहीं जो पुरानी सिम वाली रात उसके सामने बैठा था।</p>\n<p>उसके नीचे का इंसान।</p>\n<p>उसका अनुशासन।</p>\n<p>उसकी चुप्पियाँ।</p>\n<p>वह आदत जिसमें वह हर महत्वपूर्ण बात का जवाब देने से पहले एक छोटा-सा ठहराव लेता था, जैसे शब्द बाहर भेजने से पहले उनकी कीमत तौलता हो।</p>\n<p>धीरे-धीरे वही अनुशासन, जो कभी कवच था, श्रद्धा के सामने भरोसे में बदलने लगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>करीब चार महीने बाद की एक शाम थी।</p>\n<p>विक्रम की ताकत लगभग लौट चुकी थी, हालांकि मेडिकल बोर्ड ने अभी उसे पूरी तरह फिट घोषित नहीं किया था।</p>\n<p>श्रद्धा ने उसे खिड़की के पास खड़े देखा।</p>\n<p>खिड़की के बाहर नीम पर नई कोंपलें फूट आई थीं।</p>\n<p>वही पुरानी दूर चली गई नज़र।</p>\n<p>वह उसके पास आकर खड़ी हो गई।</p>\n<p>“अभी कहाँ चले गए थे?”</p>\n<p>विक्रम ने कुछ देर बाहर देखा।</p>\n<p>“सोच रहा था कितने करीब था।”</p>\n<p>“क्या?”</p>\n<p>“गोली।”</p>\n<p>उसने पेट की तरफ हल्का इशारा किया।</p>\n<p>“कुछ इंच इधर-उधर होती…”</p>\n<p>वाक्य पूरा नहीं किया।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>“तो ये सब नहीं होता।”</p>\n<p>श्रद्धा ने धीरे से उसका हाथ पकड़ लिया।</p>\n<p>“मैं भी सोचती हूँ।”</p>\n<p>उसने स्वीकार किया।</p>\n<p>“जितना मानना चाहती हूँ, उससे ज़्यादा।”</p>\n<p>फिर पूछा—</p>\n<p>“और आपको क्या महसूस होता है?”</p>\n<p>विक्रम ने कहा—</p>\n<p>“शुक्र।”</p>\n<p>एक पल बाद—</p>\n<p>“डर।”</p>\n<p>श्रद्धा ने उसकी ओर देखा।</p>\n<p>“अपनी मौत से इस तरह कभी नहीं डरा।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“क्योंकि पहले मेरी ज़िंदगी के साथ ऐसा कुछ जुड़ा ही नहीं था जिसे खोने से मैं डरता।”</p>\n<p>अब वह पूरी तरह श्रद्धा की तरफ मुड़ा।</p>\n<p>“अब है।”</p>\n<p>श्रद्धा की उँगलियाँ उसके हाथ में स्थिर हो गईं।</p>\n<p>“फिर से कहिए।”</p>\n<p>उसने धीमे से कहा।</p>\n<p>“इस बार सीधा।”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“तुम।”</p>\n<p>एक शब्द।</p>\n<p>फिर वह बात जिसे पिछले महीनों ने उसके भीतर धीरे-धीरे पूरा किया था—</p>\n<p>“अब मरने से डर लगता है।”</p>\n<p>“सच में।”</p>\n<p>“क्योंकि अगर मर गया तो तुम्हें खो दूँगा—इससे पहले कि ठीक से समझ भी पाऊँ कि तुम्हारे लायक कैसे बनना है।”</p>\n<p>श्रद्धा उसके करीब आई।</p>\n<p>घाव वाली तरफ का ध्यान रखते हुए सिर उसके सीने पर रख दिया।</p>\n<p>और उस छोटे-से क्षण में दोनों समझ गए कि यह विवाह अब वहाँ नहीं था जहाँ शुरू हुआ था।</p>\n<p>न यह सिर्फ परिवारों की तय की हुई व्यवस्था रह गया था।</p>\n<p>न ज़िम्मेदारी।</p>\n<p>न किसी पुराने प्रेम के बाद चुनी गई समझदार ज़मीन।</p>\n<p>अस्पताल के एक कॉरिडोर, कई अधूरी रातों, दर्द, पानी के गिलासों, किताबों, पुराने मकबरों और धीरे-धीरे बोले गए सचों के बीच—</p>\n<p>कुछ और बन चुका था।</p>\n<p>विक्रम ने बहुत धीमे कहा—</p>\n<p>“मैं तुमसे प्यार करता हूँ।”</p>\n<p>श्रद्धा बिल्कुल स्थिर रही।</p>\n<p>विक्रम ने आगे कहा—</p>\n<p>“शायद अस्पताल में ही समझना शुरू कर दिया था।”</p>\n<p>“तुम्हें उस बेकार-सी कुर्सी पर पूरी रात बैठे देखता था। तुम जाती नहीं थीं।”</p>\n<p>उसकी आवाज़ में कोई प्रदर्शन नहीं था।</p>\n<p>“तब नाम नहीं दे पाया।”</p>\n<p>एक साँस।</p>\n<p>“अब दे सकता हूँ।”</p>\n<p>“मैं तुमसे प्यार करता हूँ।”</p>\n<p>श्रद्धा ने चेहरा उसके सीने से नहीं हटाया।</p>\n<p>जब बोली तो आवाज़ में वह नमी थी जिसे उसने छिपाने की कोशिश नहीं की।</p>\n<p>“मैं भी आपसे प्यार करती हूँ।”</p>\n<p>कुछ क्षण बाद—</p>\n<p>“शायद जितने समय से मान रही हूँ, उससे ज़्यादा समय से।”</p>\n<p>वह हल्का-सा हँसी, मगर आवाज़ भर्रा गई।</p>\n<p>“बस आपको खोने के डर ने सिखाया कि इसे ज़ुबान से भी कहना चाहिए।”</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>उस क्षण किसी पुराने प्रेम को मिटाया नहीं गया।</p>\n<p>किसी याद को झूठा नहीं कहा गया।</p>\n<p>बस वर्तमान ने पहली बार अपना पूरा नाम लिया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>जब डॉक्टरों ने आख़िर उसे पूरी तरह फिट घोषित किया, घाव बंद हो चुका था, ताकत लौट आई थी और उस गोली की सिर्फ एक निशानी बची थी—</p>\n<p>एक दाग़,</p>\n<p>जो अब जीवन भर उसके शरीर पर रहने वाला था।</p>\n<p>उस पहली रात श्रद्धा हमेशा की तरह उसके सीने से लगकर लेटी।</p>\n<p>सिर उसी परिचित जगह, दिल के पास।</p>\n<p>मगर महीनों में पहली बार अब उनके बीच कोई ऐसा घाव नहीं था जिसका ध्यान रखना पड़े।</p>\n<p>विक्रम की उँगलियाँ आदतन उसके बालों में चली गईं।</p>\n<p>धीरे।</p>\n<p>फिर वह स्पर्श अनजाने में बदलने लगा।</p>\n<p>बालों से नीचे उतरते हुए उसकी उँगलियाँ श्रद्धा के चेहरे के पास ठहरीं।</p>\n<p>इस बार उनमें वह अनुपस्थित सहजता नहीं थी जो पिछले महीनों में होती थी।</p>\n<p>इरादा था।</p>\n<p>श्रद्धा ने वह फ़र्क़ दोनों के कुछ कह पाने से पहले ही महसूस कर लिया।</p>\n<p>कई महीनों से उसने वह बात चुपचाप किनारे रखी थी—उस शरीर के सम्मान में जिसे अभी ठीक होना था।</p>\n<p>अब वह वजह नहीं रही थी।</p>\n<p>उसने सिर उठाया।</p>\n<p>विक्रम पहले से उसे देख रहा था।</p>\n<p>“अब ठीक हैं?”</p>\n<p>आवाज़ बहुत धीमी थी।</p>\n<p>सवाल कम।</p>\n<p>पुष्टि ज़्यादा।</p>\n<p>“पूरी तरह।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“आज दोपहर से।”</p>\n<p>फिर हल्की मुस्कान—</p>\n<p>“अब सावधानी की ज़रूरत नहीं।”</p>\n<p>श्रद्धा ने उसके चेहरे के पास ठहरे हाथ पर अपना हाथ रखा।</p>\n<p>उसे हटाया नहीं।</p>\n<p>बहुत धीरे अपनी ओर खींच लिया।</p>\n<p>शब्दों की ज़रूरत नहीं रही।</p>\n<p>विक्रम झुका।</p>\n<p>ठहरा।</p>\n<p>श्रद्धा ने उसे रोका नहीं।</p>\n<p>इस बार उनके बीच न परिवारों का फ़ैसला था,</p>\n<p>न किसी घाव का डर,</p>\n<p>न किसी और की याद से पैदा हुई दूरी।</p>\n<p>दोनों वहाँ अपनी इच्छा से थे।</p>\n<p>महीनों से जो स्पर्श केवल सहारा था, उसी ने पहली बार अपना दूसरा अर्थ लिया।</p>\n<p>और उन्होंने उसे आने दिया।</p>\n<p>बिना जल्दबाज़ी के।</p>\n<p>बिना कुछ साबित किए।</p>\n<p>जैसे इतने महीनों की निकटता अब शरीर की भाषा में भी वही बात कह रही हो जिसे दोनों कुछ समय पहले शब्दों में स्वीकार कर चुके थे—</p>\n<p><b>मैं यहाँ हूँ।</b></p>\n<p><b>और इस बार, अपनी इच्छा से।</b></p>\n<p>बाद में श्रद्धा फिर उसके सीने पर लेटी थी।</p>\n<p>उसकी उँगलियाँ विक्रम के पेट पर बने नए निशान के ऊपर बहुत धीरे चल रही थीं।</p>\n<p>“एक बात कहूँ?”</p>\n<p>“कहो।”</p>\n<p>“आज पहली बार सच में शादीशुदा महसूस हो रहा है।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>श्रद्धा ने कहा—</p>\n<p>“सिर्फ घरवालों का तय किया हुआ नहीं।”</p>\n<p>“किसी के सँभाले हुए रिश्ते जैसा नहीं।”</p>\n<p>एक पल।</p>\n<p>“बस… चुना हुआ।”</p>\n<p>श्रद्धा ने विक्रम की आँखों में देखा।</p>\n<p>“ऐसे इंसान का, जो आख़िरकार इसे दिल से मानता है।”</p>\n<p>“मानता हूँ।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“पूरे दिल से।”</p>\n<p>फिर बहुत शांत स्वर में—</p>\n<p>“ज़िंदगी में किसी बात को इतने पूरे मन से पहले कभी नहीं माना।”</p>\n<p>श्रद्धा कुछ क्षण चुप रही।</p>\n<p>फिर उसकी वही पुरानी व्यावहारिक आवाज़ लौट आई—</p>\n<p>“तो साधारण दोपहरों में भी मुझसे सवाल पूछते रहिएगा।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>“क्या?”</p>\n<p>“सिर्फ गोली लगने के बाद या किसी संकट के बीच मुझे समझने की कोशिश मत कीजिएगा।”</p>\n<p>उसने कहा।</p>\n<p>“मुझे तभी भरोसा होगा कि यह टिकेगा, जब ज़रूरत ख़त्म होने के बाद भी आप मुझे देखते रहेंगे।”</p>\n<p>विक्रम ने उसकी ओर देखते हुए कहा—</p>\n<p>“बहुत लंबा समय तुम्हें देखते रहने का इरादा है।”</p>\n<p>इस बार श्रद्धा ने कोई जवाब नहीं दिया।</p>\n<p>बस फिर उसके सीने से लग गई।</p>\n<p>शांत।</p>\n<p>बिना किसी अधूरे हिसाब के उस क्षण को बिगाड़े।</p>\n<p>उनकी शादी वहाँ पहुँच गई थी जहाँ उसे पहले दिन से पहुँचना था—बस सबसे लंबे रास्ते से।</p>\n<p>पीछे स्मृतियाँ थीं।</p>\n<p>कुछ सुंदर।</p>\n<p>कुछ दुखती हुई।</p>\n<p>कुछ ऐसी जिन्हें मिटाना न संभव था, न ज़रूरी।</p>\n<p>लेकिन घर—</p>\n<p>घर अब यहीं था।</p>"}, {"chapter": 41, "title": "अंतराल — फ़ैसला", "content": "<h1>अंतराल — फ़ैसला</h1>\n<p>कामथ ने बिना कुछ कहे फाइल अपने वरिष्ठ अधिकारी की मेज़ पर रख दी।</p>\n<p>वही फाइल जिसे वह महीनों से चुपचाप भरता आ रहा था।</p>\n<p>वरिष्ठ अधिकारी ने अभी उसे खोला भी नहीं था कि कामथ बोला—</p>\n<p>“ऑपरेशनल तौर पर जिन तीन लोगों को हमने छाँटा था, उनमें सबसे बेहतर यही है।”</p>\n<p>कामथ की आवाज़ में कोई उत्साह नहीं था।</p>\n<p>सिर्फ निष्कर्ष।</p>\n<p>“9 पैरा एसएफ़। ऐसा स्ट्राइक रिकॉर्ड जो उससे दोगुनी उम्र के बहुत-से लोगों के पास भी नहीं है। और उसका कर्नल बिना एक पल सोचे उसकी ज़मानत लेगा।”</p>\n<p>वरिष्ठ अधिकारी ने फाइल खोली।</p>\n<p>पन्ने पलटते हुए पूछा—</p>\n<p>“और निजी ज़िंदगी?”</p>\n<p>कामथ कुछ क्षण चुप रहा।</p>\n<p>“उलझी हुई।”</p>\n<p>फिर बिल्कुल सपाट स्वर में—</p>\n<p>“पत्नी से पहले दो रिश्ते। एक लड़की के पिता के इनकार की वजह से गया। दूसरा परिस्थितियों में ख़त्म हुआ।”</p>\n<p>वरिष्ठ अधिकारी की नज़र पन्नों पर रही।</p>\n<p>“उसके बाद शादी हुई।”</p>\n<p>कामथ ने कहा।</p>\n<p>“और वह शादी उस चोट के बाद भी टिकी जिसने किसी भी रिश्ते की बुनियाद हिला दी होती।”</p>\n<p>एक छोटा-सा विराम।</p>\n<p>“हर बार कुछ टूटा।”</p>\n<p>“हर बार इस अफसर ने ख़ुद को फिर खड़ा किया।”</p>\n<p>अब वरिष्ठ अधिकारी ने पहली बार उसकी ओर देखा।</p>\n<p>कामथ ने कहा—</p>\n<p>“मेरे लिए यह उसके स्ट्राइक रिकॉर्ड से ज़्यादा दुर्लभ है, सर।”</p>\n<p>कमरे में कुछ देर सिर्फ काग़ज़ पलटने की आवाज़ रही।</p>\n<p>वरिष्ठ अधिकारी आख़िरी पन्ने तक पहुँचा।</p>\n<p>उसे धीरे से पढ़ा।</p>\n<p>फिर फाइल बंद कर दी।</p>\n<p>“बुलाओ इसे।”</p>\n<p>एक पल।</p>\n<p>“यही अफसर है।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>"}, {"chapter": 42, "title": "अध्याय 38 — वह फाइल", "content": "<h1>अध्याय 38 — वह फाइल</h1>\n<p>उस बैठक के कुछ हफ्ते बाद—जिसके बारे में विक्रम को बहुत बाद तक कुछ पता नहीं चलना था—एक साधारण मंगलवार को उसकी यूनिट में फोन आया।</p>\n<p>फोन सीओ के ऑफिस के रास्ते आया था, लेकिन जिस चैनल से आया था वह इतना असामान्य था कि कॉल उठाने वाले ड्यूटी ऑफिसर ने नंबर दो बार जाँचा, फिर ख़ुद चलकर कर्नल तक पहुँचा।</p>\n<p>करीब एक घंटे बाद विक्रम को बुलाया गया।</p>\n<p>कर्नल के कमरे में पुराने काग़ज़ों और ठंडी पड़ चुकी चाय की मिली-जुली गंध थी। ऊपर पंखा धीमे-धीमे घूम रहा था और बाहर की दोपहर की गर्मी बंद कमरे तक अपनी मौजूदगी पहुँचा रही थी।</p>\n<p>कर्नल ने उसे देखते ही कहा—</p>\n<p>“कैप्टन राठौड़, तुम्हें बुलाया गया है।”</p>\n<p>विक्रम रुका।</p>\n<p>“सर?”</p>\n<p>“आर्मी हेडक्वार्टर्स।”</p>\n<p>कर्नल की आवाज़ में वह सावधानी थी जिसे विक्रम इतने वर्षों में पहचानना सीख चुका था।</p>\n<p>“दिल्ली में कोई तुम्हें इस हफ्ते के भीतर देखना चाहता है।”</p>\n<p>“किस सिलसिले में, सर?”</p>\n<p>“यही तो नहीं बताया।”</p>\n<p>कर्नल ने मेज़ पर रखा एक काग़ज़ उसकी ओर सरका दिया।</p>\n<p>आधिकारिक लेटरहेड।</p>\n<p>यात्रा के आदेश।</p>\n<p>एक तारीख़।</p>\n<p>एक जगह।</p>\n<p>और साफ़ निर्देश—</p>\n<p>सादे कपड़ों में रिपोर्ट करना है।</p>\n<p>विक्रम ने पूरा काग़ज़ पढ़ा।</p>\n<p>“कोई यूनिट नहीं लिखी।”</p>\n<p>कर्नल ने कहा।</p>\n<p>“रिपोर्टिंग ऑफिसर नहीं।”</p>\n<p>फिर उँगली से काग़ज़ की तीन पंक्तियों की ओर इशारा किया।</p>\n<p>“सिर्फ एक नाम, एक इमारत और एक समय।”</p>\n<p>वह कुर्सी पर थोड़ा पीछे हुए।</p>\n<p>“बीस साल की सर्विस में ऐसे आदेश ठीक दो बार देखे हैं।”</p>\n<p>विक्रम ने कर्नल की ओर देखा।</p>\n<p>“और दोनों बार जिस अफसर को मिले, वह लौटकर मुझे यह बताने नहीं आया कि असल में किसलिए बुलाया गया था।”</p>\n<p>विक्रम ने काग़ज़ एक बार पलटकर पीछे भी देखा, जैसे सामने छूटी हुई कोई बात वहाँ लिखी हो।</p>\n<p>कुछ नहीं था।</p>\n<p>“मुझे चिंतित होना चाहिए, सर?”</p>\n<p>कर्नल ने उसे कुछ क्षण देखा।</p>\n<p>“पता नहीं।”</p>\n<p>फिर बिना किसी दिखावे के—</p>\n<p>“यही ईमानदार जवाब है।”</p>\n<p>उन्होंने मेज़ पर उँगलियाँ हल्के से रखीं।</p>\n<p>“तुम्हारा रिकॉर्ड अच्छा है, राठौड़। दो साल पहले वाली स्ट्राइक। नॉर्थ ईस्ट का वह मामला, जिसके होने की ख़बर आधे देश को आज तक आधिकारिक तौर पर नहीं है।”</p>\n<p>एक पल।</p>\n<p>“अगर दिल्ली में किसी ने तुम्हारी फाइल पर ध्यान दिया है तो हो सकता है कोई कमेंडेशन हो जिसकी सूचना अभी मुझे नहीं दी गई।”</p>\n<p>कर्नल रुके।</p>\n<p>“या कुछ और।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“सच कहूँ तो मुझे नहीं पता।”</p>\n<p>कर्नल ने कहा।</p>\n<p>“और मैंने तय किया है कि तुम्हारे सामने बैठकर अनुमान लगाने से बेहतर है अनुमान न लगाऊँ।”</p>\n<p>विक्रम ने काग़ज़ सावधानी से तह किया और जेब में रख लिया।</p>\n<p>“कब निकलना है, सर?”</p>\n<p>“परसों।”</p>\n<p>फिर कर्नल ने उसे रोक लिया—</p>\n<p>“और राठौड़।”</p>\n<p>विक्रम ने मुड़कर देखा।</p>\n<p>“जो भी निकले, फिलहाल अपने तक रखना।”</p>\n<p>उनकी आँखें विक्रम पर कुछ पल ज़्यादा ठहरीं।</p>\n<p>“दूसरे ऑफिसर्स से बात मत करना।”</p>\n<p>फिर—</p>\n<p>“ज़रूरत पड़े तो अपनी पत्नी से भी उतना ही कहना जितना तुम्हें कहने के लिए दिया जाए।”</p>\n<p>विक्रम के चेहरे पर बहुत हल्का बदलाव आया।</p>\n<p>कर्नल ने देखा, लेकिन उस पर कुछ कहा नहीं।</p>\n<p>“इतनी सावधानी से लिखे गए आदेशों के पीछे वजहें भी आम तौर पर उतनी ही सावधानी से छिपाई जाती हैं।”</p>\n<p>विक्रम सावधान की मुद्रा में खड़ा हुआ।</p>\n<p>“यस, सर।”</p>\n<p>फिर वह मुड़कर बाहर निकल गया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसी शाम विक्रम ने श्रद्धा को फोन किया।</p>\n<p>उसके पास बताने के लिए वही था जो उसे ख़ुद बताया गया था—</p>\n<p>शायद किसी कमेंडेशन रिव्यू के लिए दिल्ली बुलाया गया है।</p>\n<p>श्रद्धा ने सिर्फ इतना पूछा था—“सब ठीक है न?”</p>\n<p>विक्रम ने कहा था—“हाँ।”</p>\n<p>फोन के उस पार की चुप्पी बस एक साँस ज़्यादा ठहरी थी।</p>\n<p>बात तकनीकी रूप से झूठ नहीं थी।</p>\n<p>लेकिन फोन रखने के बाद वह कुछ देर चुप बैठा रहा।</p>\n<p>कुछ महीने पहले श्रद्धा ने उससे कहा था कि अब कोई बड़ा सच उसे किसी बंद दराज़ से नहीं मिलना चाहिए।</p>\n<p>और उसने हामी भरी थी।</p>\n<p>अब उसने श्रद्धा से एक आधा सच कहा था।</p>\n<p>मजबूरी में।</p>\n<p>आदेश के भीतर।</p>\n<p>फिर भी—</p>\n<p>आधा सच।</p>\n<p>उसे पहली बार ऐसा लगा जैसे किसी दीवार का पहला पत्थर उसके हाथ में रख दिया गया हो।</p>\n<p>अभी दीवार कहीं नहीं थी।</p>\n<p>सिर्फ एक छोटा-सा पत्थर था।</p>\n<p>और विक्रम को ज़रा भी अंदाज़ा नहीं था कि आने वाले वर्षों में उसके और श्रद्धा के बीच वही दीवार कितनी ऊँची होने वाली है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दो दिन बाद वह दिल्ली के लिए निकल गया।</p>\n<p>बैग में वही एक काग़ज़ था और दिमाग में इतने अनुमान कि रास्ते भर कोई भी टिक नहीं पाया।</p>\n<p>कुछ बिल्कुल साधारण।</p>\n<p>कुछ हल्के-से चिंताजनक।</p>\n<p>लेकिन उनमें से एक भी उस चीज़ के करीब नहीं था जो दिल्ली में उसका इंतज़ार कर रही थी।</p>\n<p>जिस इमारत तक वह पहुँचा, उसे देखकर कुछ समझ नहीं आता था।</p>\n<p>दिल्ली की एक शांत सड़क पर साधारण-सी सरकारी इमारत।</p>\n<p>बाहर ऐसा कोई बोर्ड नहीं जो बताए भीतर क्या होता है।</p>\n<p>प्रवेश द्वार पर गार्ड ने उसका नाम एक सूची से मिलाया।</p>\n<p>सूची में जैसे केवल वही एक नाम था।</p>\n<p>“तीसरी मंज़िल।”</p>\n<p>बस इतना कहा गया।</p>\n<p>विक्रम सादे कपड़ों में सीढ़ियाँ चढ़ा।</p>\n<p>खाली कंक्रीट की सीढ़ियों पर उसके कदमों की आवाज़ ज़रूरत से ज़्यादा साफ़ सुनाई दे रही थी। इमारत की सादगी इतनी सोची-समझी लग रही थी कि उसी के बीच वह ख़ुद असामान्य महसूस करने लगा।</p>\n<p>ऊपर उसे एक छोटे कमरे में भेजा गया।</p>\n<p>एक मेज़।</p>\n<p>दो कुर्सियाँ।</p>\n<p>एक कुर्सी पर पहले से एक इंसान बैठा था।</p>\n<p>उम्र पचास के आसपास।</p>\n<p>कनपटियों पर सफ़ेदी।</p>\n<p>कपड़े इतने साधारण कि कमरे से बाहर निकलने के पाँच मिनट बाद शायद उसका हुलिया ठीक से याद करना मुश्किल हो।</p>\n<p>उसने विक्रम को देखा।</p>\n<p>“कैप्टन राठौड़।”</p>\n<p>वह खड़ा नहीं हुआ।</p>\n<p>सिर्फ सामने की खाली कुर्सी की ओर इशारा किया।</p>\n<p>“बैठिए।”</p>\n<p>विक्रम बैठ गया।</p>\n<p>“काफी बातें करनी हैं।”</p>\n<p>उस इंसान ने कहा।</p>\n<p>“और ऐसी औपचारिकताओं में समय बर्बाद करने का कोई फ़ायदा नहीं जिनकी हम दोनों को ज़रूरत नहीं।”</p>\n<p>“मैं जान सकता हूँ आप कौन हैं, सर?”</p>\n<p>उस इंसान के चेहरे पर कोई खास प्रतिक्रिया नहीं आई।</p>\n<p>“पूछ सकते हैं।”</p>\n<p>फिर—</p>\n<p>“जितना जानना ज़रूरी है, उतना बताऊँगा।”</p>\n<p>उसने विक्रम की आँखों में देखते हुए कहा—</p>\n<p>“हमारे बीच मेरा नाम कामथ है।”</p>\n<p>एक छोटा-सा विराम।</p>\n<p>“उससे आगे मेरे बारे में जितना कम जानेंगे, हम दोनों के लिए उतना अच्छा रहेगा।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>कामथ ने कहा—</p>\n<p>“आप सोच रहे हैं यहाँ क्यों बुलाया गया है।”</p>\n<p>“जी, सर।”</p>\n<p>“उसका पूरा जवाब आज नहीं मिलेगा।”</p>\n<p>कामथ ने मेज़ पर रखी एक पतली फाइल खोली।</p>\n<p>उसे विक्रम की तरफ नहीं घुमाया।</p>\n<p>“आज आपको एक प्रस्ताव मिलेगा।”</p>\n<p>“और इतना संदर्भ कि आप तय कर सकें उसे स्वीकार करना है या नहीं।”</p>\n<p>विक्रम की नज़र फाइल पर गई।</p>\n<p>कामथ ने आगे कहा—</p>\n<p>“मैं एक ऐसे संगठन का प्रतिनिधित्व करता हूँ जिसके बारे में आपने अगर कभी सुना भी होगा तो बहुत अस्पष्ट शब्दों में।”</p>\n<p>“हम रक्षा मंत्रालय के तहत काम नहीं करते।”</p>\n<p>“आपकी मौजूदा चेन ऑफ कमांड जिस ढाँचे को जानती या देख सकती है, उसके भीतर भी नहीं।”</p>\n<p>वह थोड़ा आगे झुका।</p>\n<p>“हम बहुत कम, बहुत सोच-समझकर चुने गए लोगों के साथ काम करते हैं।”</p>\n<p>“ऐसा काम जिसके लिए इस देश की सेना, पुलिस या कोई दूसरा आधिकारिक ढाँचा या तो बना नहीं है—”</p>\n<p>एक क्षण।</p>\n<p>“या उसे करने की अनुमति नहीं है।”</p>\n<p>विक्रम ने कहा—</p>\n<p>“इंटेलिजेंस।”</p>\n<p>“उसमें भी।”</p>\n<p>कामथ का स्वर थोड़ा कठोर हुआ।</p>\n<p>“लेकिन मैं यह दिखावा करके आपका अपमान नहीं करूँगा कि उस एक शब्द में सब कुछ आ जाता है।”</p>\n<p>विक्रम चुपचाप सुनता रहा।</p>\n<p>“काग़ज़ों पर आपको आर्मी हेडक्वार्टर्स से जुड़ा एक स्पेशल ऑफिसर दिखाया जाएगा।”</p>\n<p>कामथ ने कहा।</p>\n<p>“ऑपरेशनल प्लानिंग और तैयारी।”</p>\n<p>“पूरी तरह वैध पोस्टिंग।”</p>\n<p>“ऐसी कि कोई सवाल न करे।”</p>\n<p>“अटैचमेंट मंज़ूर होते ही आपकी पुरानी यूनिट से आगे कोई सीधा संबंध नहीं दिखेगा।”</p>\n<p>फिर कामथ ने खुली फाइल पर हाथ रखा।</p>\n<p>“लेकिन आपके दिन वास्तव में जिस काम में गुजरेंगे, उसका उस आधिकारिक विवरण से लगभग कोई संबंध नहीं होगा।”</p>\n<p>विक्रम की आँखें उस पर टिकी थीं।</p>\n<p>“आपकी सर्विस फाइल पढ़ने वाले किसी भी सामान्य व्यक्ति के लिए वह हिस्सा मौजूद ही नहीं होगा।”</p>\n<p>कामथ ने कहा।</p>\n<p>“लेकिन उसके नीचे—”</p>\n<p>एक छोटा-सा विराम।</p>\n<p>“आप हमारे होंगे।”</p>\n<p>“और ज़रूरत पड़ने पर ऐसे काम के लिए बुलाए जाएँगे जिसका ज़िक्र किसी ऐसी फाइल में कभी नहीं होगा जिसे बाकी लोग पढ़ सकें।”</p>\n<p>विक्रम ने पूछा—</p>\n<p>“मेरे परिवार समेत?”</p>\n<p>कामथ ने बिना नरमी के कहा—</p>\n<p>“खासकर आपका परिवार।”</p>\n<p>कमरे की ख़ामोशी अचानक कुछ भारी हो गई।</p>\n<p>कामथ ने विक्रम को देखा।</p>\n<p>“मैं यह नहीं कहूँगा कि यह हिस्सा आसान है।”</p>\n<p>“और न यह दिखावा करूँगा कि मुझे समझ नहीं कि मैं उस इंसान से क्या माँग रहा हूँ जिसने, जहाँ तक मेरी जानकारी है, हाल ही में अपनी पत्नी के साथ एक स्थिर रिश्ता बनाने में काफी मेहनत की है।”</p>\n<p>विक्रम का चेहरा स्थिर रहा।</p>\n<p>लेकिन कामथ ने बात यहीं नहीं छोड़ी।</p>\n<p>“इसलिए स्वीकार करने से पहले बिल्कुल साफ़ सुन लीजिए।”</p>\n<p>“इस काम में आपको अपनी पत्नी से झूठ बोलना पड़ेगा।”</p>\n<p>एक क्षण।</p>\n<p>“कभी-कभार नहीं।”</p>\n<p>“आपकी ज़िंदगी की स्थायी बनावट के हिस्से की तरह।”</p>\n<p>कमरे में कोई आवाज़ नहीं थी।</p>\n<p>“जब तक आप हमारे लिए उपयोगी हैं।”</p>\n<p>कामथ ने कहा।</p>\n<p>“अगर यह कीमत आप नहीं देना चाहते तो अभी बता दीजिए।”</p>\n<p>“आज यहीं से अलग हो जाएँगे।”</p>\n<p>“और इसके बाद इस बातचीत का कोई अस्तित्व नहीं रहेगा।”</p>\n<p>विक्रम काफी देर चुप रहा।</p>\n<p>कुछ महीने पहले कही श्रद्धा की बात उसके भीतर साफ़ गूँजी—</p>\n<p><b>यह मोहलत दूसरी बार नहीं मिलेगी।</b></p>\n<p>और सामने बैठा इंसान उसे ऐसी ज़िंदगी दे रहा था जिसमें कुछ सच दराज़ों से भी गहरी जगहों पर बंद रखने पड़ेंगे।</p>\n<p>उसने कामथ से पूछा—</p>\n<p>“मैं ही क्यों?”</p>\n<p>कामथ ने जवाब देने में समय नहीं लिया।</p>\n<p>“क्योंकि हमने देखा कि आपने उन चीज़ों के बाद क्या किया जिन्हें किसी इंसान को तोड़ देना चाहिए था।”</p>\n<p>विक्रम स्थिर हो गया।</p>\n<p>“और हर बार हमें एक ऐसा इंसान मिला जिसने बिखरने के बजाय ख़ुद को दोबारा बनाया।”</p>\n<p>कामथ की आवाज़ में अब भी कोई प्रशंसा नहीं थी।</p>\n<p>सिर्फ मूल्यांकन।</p>\n<p>“कच्ची काबिलियत से ज़्यादा दुर्लभ चीज़ है यह, कैप्टन।”</p>\n<p>“काबिलियत हम सिखा सकते हैं।”</p>\n<p>फिर कामथ ने धीरे से फाइल बंद कर दी।</p>\n<p>“लेकिन असली नुकसान अपने भीतर लेकर दूसरी तरफ निकलना—और सिर्फ पुराने मलबे पर ज़िंदा रहने के बजाय फिर से कुछ नया बना पाना—यह ट्रेनिंग में नहीं सिखाया जाता।”</p>\n<p>विक्रम की नज़र बंद फाइल पर थी।</p>\n<p>“हम उन लोगों को नहीं चुनते जिनकी कभी परीक्षा नहीं हुई।”</p>\n<p>कामथ ने कहा।</p>\n<p>“हम उन्हें चुनते हैं जिनकी परीक्षा पहले ही हो चुकी हो।”</p>\n<p>“निजी तौर पर।”</p>\n<p>“ऐसी जगहों पर जहाँ कोई ट्रेनिंग एक्सरसाइज़ उन्हें ले ही नहीं जा सकती।”</p>\n<p>एक क्षण।</p>\n<p>“और जो वहाँ से लौटे हों।”</p>\n<p>विक्रम ने पूछा—</p>\n<p>“अगर मैं मना कर दूँ?”</p>\n<p>“कुछ नहीं होगा।”</p>\n<p>कामथ ने कहा।</p>\n<p>“आप अपनी यूनिट में लौटेंगे।”</p>\n<p>“सामान्य तरीके से अपनी सर्विस पूरी करेंगे।”</p>\n<p>“इस ऑफिस से फिर कभी कोई संपर्क नहीं होगा।”</p>\n<p>कामथ की आँखें विक्रम पर स्थिर थीं।</p>\n<p>“मना करने की कोई सज़ा नहीं है।”</p>\n<p>“मैं उस इंसान को लेना पसंद करूँगा जो हाँ इसलिए कहे क्योंकि उसने सचमुच हाँ चुनी है—न कि इसलिए कि उसे लगा मना करने का रास्ता ही नहीं था।”</p>\n<p>फिर बहुत हल्का-सा विराम।</p>\n<p>“हालाँकि मुझे नहीं लगता आप मना करेंगे।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>“आपकी फाइल काफी ध्यान से पढ़ी है।”</p>\n<p>कामथ बोला।</p>\n<p>“आप जैसे लोग जब एक बार समझ लेते हैं कि सामने रखा काम सच में मायने रखता है, तो आम तौर पर उससे मुँह नहीं मोड़ते।”</p>\n<p>कमरे में फिर ख़ामोशी उतर आई।</p>\n<p>विक्रम बैठा रहा।</p>\n<p>उस विवाह के बारे में सोचते हुए जिसे उसने अभी-अभी सच में बनाना शुरू किया था।</p>\n<p>उस पत्नी के बारे में जिसने उससे केवल एक चीज़ माँगी थी—</p>\n<p>ईमानदारी।</p>\n<p>और उस काम के बारे में जो अब उसी ईमानदारी की पूरी कीमत माँग रहा था।</p>\n<p>वह जानता था इसकी कीमत होगी।</p>\n<p>अभी यह नहीं जानता था कितनी।</p>\n<p>लेकिन उसी ख़ामोशी में उसे यह भी समझ आ गया कि कामथ एक बात में सही है।</p>\n<p>जिस क्षण उसने प्रस्ताव का असली अर्थ समझा था, उसके भीतर कहीं फ़ैसला लगभग हो चुका था।</p>\n<p>विक्रम ने कामथ की आँखों में देखा।</p>\n<p>“मैं तैयार हूँ।”</p>\n<p>कामथ के चेहरे पर एक भाव आया—</p>\n<p>शायद संतोष।</p>\n<p>इतना नियंत्रित कि ठीक से भाव बनने से पहले ही गायब हो गया।</p>\n<p>“अच्छा।”</p>\n<p>कामथ ने बंद फाइल पर हाथ रखा।</p>\n<p>“तो अब बात करते हैं कि व्यवहार में इसका अर्थ क्या है।”</p>\n<p>फिर बिल्कुल सपाट स्वर में—</p>\n<p>“सबसे पहली बात।”</p>\n<p>“आप मुझे उस नाम के अलावा किसी नाम से नहीं बुलाएँगे जो मैंने अभी आपको दिया है।”</p>\n<p>एक पल।</p>\n<p>“और इस कमरे में अब से जो कुछ कहा जाएगा—”</p>\n<p>कामथ की नज़र उससे नहीं हटी।</p>\n<p>“इस कमरे के बाहर उसका कोई अस्तित्व नहीं है।”</p>"}, {"chapter": 43, "title": "अध्याय 39 — जो साल छूटते गए", "content": "<h1>अध्याय 39 — जो साल छूटते गए</h1>\n<p>ट्रेनिंग तीन महीने चली।</p>\n<p>एक साथ नहीं—अलग-अलग हिस्सों में, ताकि श्रद्धा को वे बस कुछ “स्पेशलाइज़्ड कोर्स” लगें। कभी लीडरशिप डेवलपमेंट, कभी टैक्टिकल रिफ्रेशर; ऐसे सरकारी नाम जिनमें इतनी जानकारी होती थी कि सामने वाला सवाल न करे, और इतनी कम कि असल बात का एक सिरा भी हाथ न आए।</p>\n<p>कामथ के लोग आर्मी की तरह ट्रेनिंग नहीं देते थे।</p>\n<p>वहाँ कोई चिल्लाता नहीं था।</p>\n<p>कोई आवाज़ ऊँची नहीं होती थी।</p>\n<p>बस हर फ़ैसला खोला जाता था—ठंडे दिमाग से, बेरहमी की हद तक बारीकी से। दबाव में उसने क्या चुना, जवाब देने से पहले कितनी देर रुका, झूठ बोलते समय आँखों या चेहरे ने कौन-सी छोटी-सी बात कह दी जिसे ज़ुबान छिपा ले गई थी।</p>\n<p>दूसरे महीने के आख़िर में एक खिड़कीहीन कमरे में उसका इंस्ट्रक्टर रिकॉर्डेड इंटेरोगेशन एक्सरसाइज़ दोबारा चला रहा था। कमरे में ठंडी पड़ चुकी कॉफी और पुराने कार्पेट की मिली-जुली गंध थी।</p>\n<p>स्क्रीन पर विक्रम का चेहरा रुका।</p>\n<p>“अब भी चौंकते हो।”</p>\n<p>इंस्ट्रक्टर ने कहा।</p>\n<p>वीडियो कुछ सेकंड पीछे गया।</p>\n<p>“यहाँ।”</p>\n<p>सामने बैठे इंसान ने परिवार का ज़िक्र किया था।</p>\n<p>बस उतना।</p>\n<p>लेकिन स्क्रीन पर विक्रम के चेहरे में एक बेहद मामूली-सा बदलाव आया था।</p>\n<p>“किसी मँजी हुई आँख के लिए इतना काफी है। इसी से वह तुम्हारा पूरा खाका खींच लेगा।”</p>\n<p>विक्रम ने स्क्रीन से नज़र नहीं हटाई।</p>\n<p>“ठीक कर लूँगा।”</p>\n<p>“करना पड़ेगा।”</p>\n<p>इंस्ट्रक्टर का स्वर वैसा ही सपाट रहा।</p>\n<p>“क्योंकि जब सच में वक्त आएगा, यही ज़रा-सा चौंकना किसी और की जान ले सकती है।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>ट्रेनिंग के दौरों के बीच विक्रम घर लौटता।</p>\n<p>और हर बार श्रद्धा उसे थोड़ा और ध्यान से देखती।</p>\n<p>श्रद्धा ने सवाल करना बंद नहीं किया था; उसने सिर्फ यह सीख लिया था कि कहाँ सवाल को वहीं छोड़ देना है जहाँ सामने वाला उसका जवाब नहीं दे सकता।</p>\n<p>एक रात दोनों अँधेरे में जाग रहे थे।</p>\n<p>श्रद्धा ने कहा—</p>\n<p>“इन कोर्सेज़ के बाद आप हर बार थोड़े अलग लौटते हैं।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>“कैसे?”</p>\n<p>“पता नहीं।”</p>\n<p>वह कुछ देर शब्द ढूँढ़ती रही।</p>\n<p>“ज़्यादा चौकन्ने। जैसे कमरे में आते ही पहले उसे पढ़ते हैं, फिर उसमें बैठते हैं।”</p>\n<p>विक्रम ने हल्के स्वर में कहा—</p>\n<p>“ट्रेनिंग लोगों को बदलती है। मकसद ही वही होता है।”</p>\n<p>“मुझे पता है।”</p>\n<p>श्रद्धा चुप हुई।</p>\n<p>फिर बोली—</p>\n<p>“मैं आपसे समझाने को नहीं कह रही।”</p>\n<p>एक पल।</p>\n<p>“बस यह बता रही हूँ कि मैं देख रही हूँ।”</p>\n<p>श्रद्धा ने विक्रम की ओर करवट ली।</p>\n<p>“पहले भी कहा था—मेरा कुरेदना छोड़ देना और मेरा कुछ न देखना, इन दोनों को एक मत समझ लीजिएगा।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>फ़र्क़ वह बहुत अच्छी तरह समझता था।</p>\n<p>शायद ज़रूरत से ज़्यादा अच्छी तरह।</p>\n<p>जिस दीवार को गिराने में दोनों को इतना समय लगा था, उसकी जगह अब वह अपने ही हाथों दूसरी दीवार खड़ी कर रहा था।</p>\n<p>पहली दीवार उसकी अपनी ख़ामोशी की थी।</p>\n<p>यह वाली आदेश की थी।</p>\n<p>फ़र्क़ बहुत बड़ा था।</p>\n<p>लेकिन जिस इंसान को दूसरी तरफ रहना पड़े, उसके लिए दोनों दीवारें आख़िर दीवारें ही होती हैं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>ट्रेनिंग शुरू हुए एक साल पूरा होने से कुछ पहले विक्रम दिल्ली के बेस हॉस्पिटल में लेबर वार्ड के बाहर करीब छह घंटे तक कॉरिडोर नापता रहा।</p>\n<p>कई बार उससे बैठने को कहा गया।</p>\n<p>हर बार उसने मना कर दिया।</p>\n<p>जैसे बैठ जाने से इंतज़ार और लंबा हो जाएगा।</p>\n<p>आख़िर एक नर्स बाहर आई। उसके चेहरे पर विक्रम की बेचैनी देखकर मुस्कान आ गई।</p>\n<p>“अब अंदर जा सकते हैं।”</p>\n<p>विक्रम कमरे में पहुँचा।</p>\n<p>श्रद्धा थकी हुई थी। बाल पसीने से भीगकर तकिए से लगे थे। मगर दरवाज़ा खुलते ही उसकी आँखें विक्रम को खोजती हुई उस पर आ टिकीं, और चेहरे की थकान के बीच कुछ ढीला पड़ा—</p>\n<p>जैसे अब वह सचमुच मान सकती हो कि मुश्किल हिस्सा ख़त्म हो गया है।</p>\n<p>विक्रम अभी उसके पास ठीक से पहुँचा भी नहीं था कि नर्स ने बच्ची उसकी बाँहों में रख दी।</p>\n<p>उनकी बेटी।</p>\n<p>इतनी छोटी कि उसे पकड़ते हुए पहली बार उसे अपने ही हाथ ज़रूरत से ज़्यादा बड़े लगे।</p>\n<p>चेहरा लाल।</p>\n<p>कपड़े में लिपटा शरीर।</p>\n<p>एक नन्ही-सी मुट्ठी कपड़े से बाहर निकलने की ज़िद में लगी हुई।</p>\n<p>विक्रम बिल्कुल स्थिर खड़ा रहा।</p>\n<p>बहुत देर तक।</p>\n<p>फिर उसकी आवाज़ निकली तो उसमें वह खुरदरापन था जिसे श्रद्धा ने उससे पहले केवल एक और अस्पताल में सुना था।</p>\n<p>“कितनी प्यारी है… बिल्कुल पूरी।”</p>\n<p>उसने श्रद्धा की ओर देखा।</p>\n<p>आँखों में आँसू थे।</p>\n<p>इस बार उन्हें छिपाने की कोई कोशिश नहीं।</p>\n<p>विक्रम ने बच्ची की ओर फिर देखा।</p>\n<p>“मुझे पता ही नहीं था कि ऐसा भी कुछ महसूस किया जा सकता है।”</p>\n<p>श्रद्धा हँसी भी, रोई भी।</p>\n<p>“तो उससे ठीक से मिलिए।”</p>\n<p>“नौ महीने से इंतज़ार कर रही है आपका।”</p>\n<p>उन्होंने उसका नाम रखा—</p>\n<p><b>अदिति।</b></p>\n<p>उस पहली रात विक्रम ने उसे लगभग अपनी बाँहों से उतरने ही नहीं दिया। नर्सें आतीं, श्रद्धा कहती कुछ देर सो जाइए, लेकिन वह हर बार किसी न किसी बहाने उसे अपने पास रख लेता।</p>\n<p>और अदिति से धीमे-धीमे बातें करता रहा।</p>\n<p>मौसम के बारे में।</p>\n<p>अस्पताल आते वक्त रास्ते के बारे में।</p>\n<p>उसके नाम के बारे में।</p>\n<p>ऐसी बातें जिनका कोई अर्थ उस बच्ची के लिए नहीं था।</p>\n<p>शायद विक्रम के लिए भी नहीं।</p>\n<p>मगर जैसे उसे लगता हो कि दुनिया में आने के पहले ही घंटे से अपनी आवाज़ उसके पास छोड़ना भी पिता होने का कोई कर्ज है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अदिति ने पहला कदम घर के उसी आँगन में रखा।</p>\n<p>दादी ने बाँहें फैलाकर उसे छोड़ा और वह तीन डगमगाते कदम चली—</p>\n<p>सीधे विक्रम की ओर।</p>\n<p>विक्रम उस समय छुट्टी पर घर आए सिर्फ चार दिन हुए थे।</p>\n<p>बाद में वह कई बार कहता कि उसकी पूरी सर्विस में उससे बेहतर समय पर मिली छुट्टी कोई नहीं थी।</p>\n<p>कुछ ही समय बाद अदिति ने पहली बार उसे “पापा” कहा।</p>\n<p>कमरे के दूसरे छोर से उँगली उसकी तरफ उठाकर—</p>\n<p>“पापा।”</p>\n<p>विक्रम उसी क्षण उसके पास गया, उसे उठाकर बाँहों में भर लिया।</p>\n<p>फिर पूरे दिन कोई न कोई बहाना बनाता रहा कि बच्ची दोबारा बोले।</p>\n<p>“कौन?”</p>\n<p>“पापा।”</p>\n<p>“कहाँ हैं पापा?”</p>\n<p>“पापा!”</p>\n<p>हर बार वह ऐसे खुश होता जैसे पहली बार सुन रहा हो।</p>\n<p>तीन साल की हुई तो उसकी वर्दी वाली टोपी पर उसका कब्ज़ा हो गया।</p>\n<p>टोपी उसके सिर से कई साइज़ बड़ी थी, लेकिन अदिति उसे पहनकर पूरे घर में घूमती और विक्रम हर बार उसके सामने आते ही बिल्कुल गंभीर चेहरा बनाकर सैल्यूट करता।</p>\n<p>एक दोपहर श्रद्धा रसोई के दरवाज़े से दोनों को देखती रही, फिर बोली—</p>\n<p>“आप इसे यही समझाकर बड़ा करेंगे कि आर्मी कोई फैंसी ड्रेस का खेल है?”</p>\n<p>विक्रम ने अदिति को फिर सैल्यूट किया।</p>\n<p>“कुछ साल और समझने दो।”</p>\n<p>फिर विक्रम की आवाज़ में अनजाने ही कुछ गंभीर उतर आया।</p>\n<p>“असल कीमत तो एक दिन ख़ुद समझ जाएगी।”</p>\n<p>विक्रम ने बेटी की तरफ देखा।</p>\n<p>“पहली याद टोपी की रहे तो बेहतर है।”</p>\n<p>चार साल की उम्र में उसने अदिति को बिना सहारे वाले छोटे पहियों के साइकिल चलाना सिखाया।</p>\n<p>आँगन की लंबाई में उसके साथ दौड़ता रहा—एक हाथ सीट के पास, मगर छुए बिना।</p>\n<p>अदिति डगमगाई।</p>\n<p>फिर संतुलन मिला।</p>\n<p>और अचानक वह विक्रम के हाथ से आगे निकल गई।</p>\n<p>उसकी चीखती हुई खुशी पूरे आँगन में फैल गई।</p>\n<p>विक्रम बीच में खड़ा हँसता रहा, पीछे से आवाज़ देता रहा।</p>\n<p>उस क्षण उसके चेहरे पर जितना गर्व था, उतना अपनी ज़िंदगी की बहुत कम उपलब्धियों पर रहा होगा।</p>\n<p>कुछ जीतों के लिए कोई मेडल नहीं मिलता।</p>\n<p>शायद इसीलिए वे इंसान के भीतर ज़्यादा देर तक रहती हैं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>इन्हीं सालों में, घर से बहुत दूर, विक्रम का असली काम चलता रहा—उस असाइनमेंट में जिसका सरकारी काग़ज़ों में कोई वास्तविक अस्तित्व नहीं था।</p>\n<p>काग़ज़ों पर वह एक लॉजिस्टिक्स कंपनी का एग्ज़िक्यूटिव था।</p>\n<p>ईरान और अफ़ग़ानिस्तान के बीच कारोबार के सिलसिले में आता-जाता हुआ एक इंसान।</p>\n<p>लेकिन उसका काम माल ढोना नहीं था।</p>\n<p>वह ऐसे लोगों को ढूँढ़ रहा था जिनकी जगह मायने रखती हो और जिनका भरोसा धीरे-धीरे जीता जा सके—ऐसे लोग जो सत्ता, ज़मीन या उन नेटवर्क्स के इतने करीब हों कि आज उनसे बनी एक ख़ामोश पहचान किसी आने वाले कल में देश के काम आ सके।</p>\n<p>ऐसे रिश्ते जल्दी नहीं बनते।</p>\n<p>उन्हें समय चाहिए।</p>\n<p>कभी पैसे से शुरू होते हैं।</p>\n<p>कभी किसी मदद से।</p>\n<p>और अगर सचमुच टिक जाएँ, तो एक दिन उस पहली वजह से बहुत आगे निकल जाते हैं।</p>\n<p>ऐसे ही लोगों में एक था—</p>\n<p>एक छोटे जिले का मौलवी, <b>हबीबुल्लाह</b>।</p>\n<p>विक्रम उससे उस आतंकी हमले के तीन दिन बाद मिला जिसमें उसके दोनों बेटे मारे गए थे।</p>\n<p>उनका अपराध सिर्फ इतना था कि ग़लत दोपहर में ग़लत मदरसे में मौजूद थे।</p>\n<p>विक्रम ने उसके घर को दोबारा खड़ा करने लायक पैसे का इंतज़ाम कराया। उसकी पत्नी की बीमारी का इलाज स्थानीय क्लिनिक से संभव नहीं था, इसलिए दिल्ली में इलाज की व्यवस्था करवाई।</p>\n<p>इतना करने के बाद उसका काम ख़त्म हो सकता था।</p>\n<p>लेकिन वह लौटता रहा।</p>\n<p>तब भी, जब दोनों एहसान बहुत पहले चुक चुके थे।</p>\n<p>धीरे-धीरे मदद पहचान बनी।</p>\n<p>पहचान भरोसा।</p>\n<p>और भरोसा एक ऐसी दोस्ती में बदल गया जो उस पूरे साल दोनों की ज़िंदगी की सबसे सच्ची चीज़ों में से एक थी।</p>\n<p>अपने दोनों बेटों को उसी कट्टरता में खो देने के बाद हबीबुल्लाह के भीतर कुछ बदल चुका था।</p>\n<p>वह उन विचारों से भीतर ही भीतर दूर जा चुका था जिन्होंने उसके अपने घर को उजाड़ा था।</p>\n<p>लेकिन बाहर किसी को इसका आभास नहीं होने देता।</p>\n<p>उन नेटवर्क्स के सामने वह अब भी वही था—</p>\n<p>एक सहयोगी, साधारण मौलवी।</p>\n<p>इतना साधारण कि लोग उसे देखते थे और फिर देखना भूल जाते थे।</p>\n<p>शायद यही उसकी सबसे बड़ी सुरक्षा थी।</p>\n<p>उसका दूसरा चेहरा सिर्फ विक्रम जानता था।</p>\n<p>और विक्रम का दूसरा चेहरा शायद हबीबुल्लाह।</p>\n<p>दोनों ने कभी एक-दूसरे से साफ़ शब्दों में नहीं पूछा कि उनके बीच यह रिश्ता आख़िर है क्या।</p>\n<p>कुछ रिश्ते नाम माँगते ही छोटे हो जाते हैं।</p>\n<p>दोनों यह जानते थे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उन्हीं वर्षों में छुट्टियाँ अब छुट्टियाँ कम, घर से चुराए हुए कुछ दिन ज़्यादा हो गई थीं।</p>\n<p>कभी चार दिन।</p>\n<p>कभी दो।</p>\n<p>कभी इतने अचानक कि परिवार उसके आने की आदत बना भी न पाए और वापसी की तारीख़ सामने आ जाए।</p>\n<p>अदिति बड़ी हो रही थी।</p>\n<p>श्रद्धा उसके साथ घर की लय संभाल रही थी।</p>\n<p>और विक्रम बीच-बीच में उस जीवन में लौटता जिसे उसने चुना था—</p>\n<p>मगर जिसका हर दिन जी पाने का अधिकार उसके पास नहीं था।</p>\n<p>फिर एक दिन वह घर से बहुत दूर था।</p>\n<p>ऐसी जगह जिसका नाम वह अपने पिता तक को नहीं बता सकता था।</p>\n<p>उसे वहाँ पहुँचे तीन हफ्ते हो चुके थे जब परिवार के लिए छोड़े गए एकमात्र बेहद नियंत्रित चैनल से संदेश आया।</p>\n<p>बहुत छोटा।</p>\n<p>बहुत औपचारिक।</p>\n<p><b>पत्नी ने स्वस्थ बेटे को जन्म दिया है। माँ और बच्चा दोनों ठीक हैं।</b></p>\n<p>विक्रम एक कॉरिडोर में खड़ा वह संदेश पढ़ता रहा।</p>\n<p>उसे अचानक वर्षों पुराना एक दूसरा कॉरिडोर याद आया—</p>\n<p>नैना के पिता का घर।</p>\n<p>और अगले ही क्षण उसके भीतर दो भाव ऐसे टकराए कि कुछ पल के लिए खड़ा रहना भी मुश्किल हो गया।</p>\n<p>उसका बेटा स्वस्थ था।</p>\n<p>श्रद्धा ठीक थी।</p>\n<p>इससे बड़ी राहत उस समय कोई नहीं हो सकती थी।</p>\n<p>और उसी राहत के ठीक भीतर एक ऐसा दुख था जिसने उसके घुटनों से ताकत खींच ली।</p>\n<p>वह वहाँ नहीं था।</p>\n<p>उसने श्रद्धा का हाथ नहीं पकड़ा था।</p>\n<p>उसने अपने बेटे की पहली साँस नहीं सुनी थी।</p>\n<p>उसके जीवन के पहले मिनट अब हमेशा ऐसे मिनट रहने वाले थे जिनके बारे में विक्रम दूसरों से सुनकर जानेगा।</p>\n<p>कुछ अनुपस्थितियाँ बाद में पूरी नहीं की जा सकतीं।</p>\n<p>इंसान लौट सकता है।</p>\n<p>बच्चे को बाँहों में उठा सकता है।</p>\n<p>तस्वीरें देख सकता है।</p>\n<p>हर कहानी दस बार सुन सकता है।</p>\n<p>लेकिन जिस पल में वह नहीं था—</p>\n<p>उस पल में वह फिर कभी नहीं पहुँच सकता।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसी शाम उसे फोन की अनुमति मिली।</p>\n<p>तीन मिनट से कम।</p>\n<p>लाइन जुड़ी।</p>\n<p>विक्रम ने श्रद्धा को कुछ कहने का मौका भी नहीं दिया।</p>\n<p>“मुझे माफ़ कर दो।”</p>\n<p>दूसरी तरफ कुछ क्षण चुप्पी रही।</p>\n<p>“मुझे वहाँ होना चाहिए था।”</p>\n<p>उसकी आवाज़ भर्रा गई।</p>\n<p>“मैंने ख़ुद से वादा किया था कि इस बार रहूँगा।”</p>\n<p>श्रद्धा थकी हुई थी।</p>\n<p>आवाज़ में वही थकान थी जो किसी कठिन काम को पूरा कर लेने के बाद आती है।</p>\n<p>लेकिन उसके नीचे एक स्थिरता भी थी—</p>\n<p>जैसे उसने विक्रम के माफ़ी माँगने से पहले ही उसे माफ़ करने का मुश्किल काम कर लिया हो।</p>\n<p>“आप कुछ नहीं कर सकते थे।”</p>\n<p>उसने कहा।</p>\n<p>“जब आप गए थे, मुझे पता था इस पोस्टिंग का मतलब क्या है।”</p>\n<p>फिर सच से बचने की कोशिश किए बिना—</p>\n<p>“मैं डर गई थी, विक्रम।”</p>\n<p>“आपके बिना ये सब करना आसान नहीं था।”</p>\n<p>एक साँस।</p>\n<p>“लेकिन हो गया।”</p>\n<p>उसकी आवाज़ थोड़ी नरम हुई।</p>\n<p>“वो ठीक है।”</p>\n<p>“बहुत सुंदर है।”</p>\n<p>“आप जल्दी मिलेंगे उससे।”</p>\n<p>फिर हल्की-सी थकी हँसी—</p>\n<p>“उसे इसमें से कुछ याद भी नहीं रहेगा।”</p>\n<p>एक पल।</p>\n<p>“आपको रहेगा।”</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>“कैसा दिखता है?”</p>\n<p>“ज़्यादातर आपके जैसा।”</p>\n<p>श्रद्धा हँसी।</p>\n<p>“ठुड्डी तो अभी से आपकी तरह ज़िद्दी है।”</p>\n<p>फिर—</p>\n<p>“अदिति ने तय कर लिया है कि भाई उसी की ज़िम्मेदारी है। किसी और को ज़्यादा देर गोद में रखने नहीं देती।”</p>\n<p>विक्रम की आँखों के सामने वह दृश्य बना—</p>\n<p>एक ऐसा दृश्य जिसमें वह मौजूद नहीं था।</p>\n<p>“काश देख पाता।”</p>\n<p>“देखिएगा।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“बस सही-सलामत घर लौट आइए।”</p>\n<p>उसकी आवाज़ अब बहुत धीमी थी।</p>\n<p>“जो कुछ छूट गया है, सब दिखाऊँगी आपको।”</p>\n<p>“एक-एक चीज़।”</p>\n<p>कॉल ख़त्म हो गई।</p>\n<p>तीन मिनट पूरे होने से पहले।</p>\n<p>और कुछ देर तक विक्रम फोन हाथ में लिए खड़ा रहा—</p>\n<p>जैसे लाइन कट जाने के बाद भी उस घर की आवाज़ उसमें कहीं बची हो।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उन्होंने बेटे का नाम रखा—</p>\n<p><b>अर्जुन।</b></p>\n<p>विक्रम ने उसे पहली बार छह हफ्ते बाद बाँहों में लिया।</p>\n<p>तस्वीर में जिस बच्चे को देखा था, सामने वह उससे थोड़ा दुबला लग रहा था।</p>\n<p>चेहरा भी बदल चुका था।</p>\n<p>सिर्फ छह हफ्ते।</p>\n<p>लेकिन बच्चे के जीवन में छह हफ्ते बहुत होते हैं।</p>\n<p>इतने कि पिता पहली बार उसे गोद में लेकर भी समझ जाए कि उसके बेटे की कहानी पहले ही कई पन्ने आगे बढ़ चुकी है।</p>\n<p>और वह उन शुरुआती पन्नों में मौजूद नहीं था।</p>\n<p>विक्रम उसे बहुत देर तक पकड़े रहा।</p>\n<p>कुछ खास नहीं कहा।</p>\n<p>बस देखता रहा।</p>\n<p>कभी उसके चेहरे को।</p>\n<p>कभी छोटी उँगलियों को।</p>\n<p>कभी उस छाती को जो उसकी बाँहों में बहुत हल्के-हल्के उठ-गिर रही थी।</p>\n<p>कमरे के दूसरी तरफ श्रद्धा उसे देख रही थी।</p>\n<p>श्रद्धा ने कुछ नहीं पूछा।</p>\n<p>अब तक वह विक्रम की बहुत-सी चुप्पियाँ पढ़ना सीख चुकी थी।</p>\n<p>यह वाली भी।</p>\n<p>वह जानती थी कि विक्रम की बाँहों में केवल उसका बेटा नहीं है।</p>\n<p>वहाँ वे छह हफ्ते भी हैं जिन्हें वह वापस नहीं पा सकता।</p>\n<p>और यही उस जीवन की असली कीमत थी जिसे विक्रम ने चुना था—</p>\n<p>देश हमेशा उसकी जान ही नहीं माँगता था।</p>\n<p>कभी-कभी वह इससे भी छोटी चीज़ें माँगता था।</p>\n<p>एक जन्म।</p>\n<p>एक पहली साँस।</p>\n<p>पत्नी का हाथ थामे बिताए जाने वाले कुछ घंटे।</p>\n<p>अपने बेटे के चेहरे के वे शुरुआती दिन जो दोबारा कभी वैसे नहीं लौटेंगे।</p>\n<p>ऐसी चीज़ें जिनके लिए कोई शहीद नहीं कहलाता।</p>\n<p>जिनका कोई मेडल नहीं बनता।</p>\n<p>जिनका ज़िक्र सर्विस रिकॉर्ड में नहीं आता।</p>\n<p>बस एक दिन इंसान घर लौटता है—</p>\n<p>और पाता है कि जिन लोगों के लिए वह सब कर रहा था,</p>\n<p>उनकी ज़िंदगी उसके बिना भी आगे बढ़ना सीख चुकी है।</p>"}, {"chapter": 44, "title": "अध्याय 40 — सब-इंस्पेक्टर कविता", "content": "<h1>अध्याय 40 — सब-इंस्पेक्टर कविता</h1>\n<p>सर्विस में कई साल बिताने के बाद कविता सब-इंस्पेक्टर बनी थी।</p>\n<p>वह पद उसे किसी की मेहरबानी से नहीं मिला था। उसने उसे कमाया था—धीरे, मुश्किल रास्ते से, उसी तरह जैसे उस दिन के बाद अपनी ज़िंदगी में लगभग हर चीज़ कमाई थी, जब विक्रम ने पहली बार एक ग़लत नंबर पर उसकी आवाज़ सुनी थी।</p>\n<p>और कभी जो वह विक्रम के लिए रही थी, उसकी कहानी उतनी सीधी नहीं थी जितनी दोनों ने वर्षों तक दूसरों के सामने रहने दी।</p>\n<p>तब तक दोनों परिवारों के बीच ज़मीन की हदबंदी को लेकर एक पुराना विवाद धीरे-धीरे फिर सिर उठाने लगा था। कोई बड़ा झगड़ा नहीं—बस नाप, निशान, पुराने काग़ज़, खेत की मेड़ और पीढ़ियों से चली आ रही उस ग्रामीण ज़िद का मेल जिसमें कई बार ज़मीन के कुछ फीट से ज़्यादा अहम यह हो जाता है कि झुका कौन।</p>\n<p>उसी दौरान एक रविवार विक्रम गुरुग्राम की एक कार मार्केट गया।</p>\n<p>गाड़ी सड़क किनारे खड़ी की और एक घंटे से भी कम समय के लिए भीतर चला गया।</p>\n<p>लौटा तो पहली नज़र में सब सामान्य था।</p>\n<p>फिर उसकी नज़र पीछे की खिड़की पर गई।</p>\n<p>शीशा फ्रेम में थोड़ा ढीला बैठा था।</p>\n<p>विक्रम ने दरवाज़ा खोला।</p>\n<p>फोन गायब था।</p>\n<p>मार्केट के कैमरे में कुछ नहीं मिला।</p>\n<p>मामला वहीं ख़त्म हो सकता था, लेकिन कुछ हफ्तों बाद किसी और विवाद की फुटेज देखते समय उसे सड़क पर थोड़ा आगे लगा दूसरा कैमरा मिला।</p>\n<p>उसने पुरानी तारीख़ निकलवाई।</p>\n<p>फुटेज चली।</p>\n<p>और स्क्रीन पर एक चेहरा आया जिसे पहचानने में उसे एक क्षण भी नहीं लगा।</p>\n<p>कविता।</p>\n<p>उसके साथ दो लोग थे।</p>\n<p>एक घंटे से भी कम समय में तीनों उसी हिस्से से चार बार गुज़रे थे।</p>\n<p>बाद में पता चला, उस महीने के कम-से-कम दो और रविवार को वही तीन लोग वहाँ दिखाई दिए थे।</p>\n<p>विक्रम चाहता तो उसी समय पुलिस में जा सकता था।</p>\n<p>उसके पास पर्याप्त वजह थी।</p>\n<p>उसने नहीं किया।</p>\n<p>कुछ रिश्ते ख़त्म होने के बहुत बाद तक इंसान के फ़ैसलों में बचे रहते हैं।</p>\n<p>उसने चुप रहना चुना।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कुछ ही दिन बाद उस घटना को याद करते हुए विक्रम ने कहा था—</p>\n<p>“मामला ज़मीन का कभी था ही नहीं।”</p>\n<p>उसकी आवाज़ में उस समय एक अजीब दूरी उतर आई थी—वैसी दूरी, जो किसी पुराने घाव की बात करते हुए आती है जब इंसान को अचानक पता चले कि जिसे वह पूरी तरह भर चुका समझता था, भीतर कहीं उसकी सिलाई अब भी बाकी है।</p>\n<p>“ये बात मुझे बाद में समझ आई।”</p>\n<p>फोन में कुछ असाधारण नहीं था।</p>\n<p>श्रद्धा के साथ संदेश।</p>\n<p>बच्चों की तस्वीरें।</p>\n<p>घर की छोटी-छोटी बातें।</p>\n<p>एक साधारण ज़िंदगी का साधारण रिकॉर्ड।</p>\n<p>लेकिन कविता के लिए वही उसकी सबसे असाधारण चीज़ थी।</p>\n<p>क्योंकि वह उस पूरी ज़िंदगी को देख रही थी जिसमें उसे कभी जगह नहीं मिली थी।</p>\n<p>एक पत्नी।</p>\n<p>बच्चे।</p>\n<p>घर।</p>\n<p>वर्षों की तस्वीरें।</p>\n<p>वे छोटे दिन जिन्हें कोई बाहर वाला महत्वहीन कह सकता था, लेकिन जो मिलकर किसी इंसान की पूरी ज़िंदगी बनाते हैं।</p>\n<p>विक्रम ने बाद में समझा कि कविता ने उस फोन को सिर्फ चुराई हुई चीज़ की तरह नहीं देखा था।</p>\n<p>कहीं बहुत भीतर उसने उसे उस जीवन की तरह देखा जो उससे छिन गया था।</p>\n<p>दुख अगर बहुत लंबे समय तक भीतर पड़ा रहे, और ग़लत लोग उसे समय-समय पर कुरेदते रहें, तो वह हमेशा दुख नहीं रहता।</p>\n<p>कभी उसका रंग बदल जाता है।</p>\n<p>और फिर एक दिन इंसान ख़ुद भी पहचान नहीं पाता कि जिस चीज़ को वह अब न्याय कह रहा है, वह कब बदले में बदल चुकी।</p>\n<p>उस समय विक्रम को अंदाज़ा नहीं था कि कविता कितनी दूर जा चुकी है—</p>\n<p>और उसके पीछे खड़े लोग उसे और कितनी दूर ले जाने वाले हैं।</p>\n<p>फिर कविता की ओर से एक छोटा-सा संदेश आया—बस इतना कि उस फोन को वापस पाने की कीमत क्या होगी, यह वह अपने वक्त पर ख़ुद बताएगी।</p>\n<p>फिर दो हफ्ते कोई ख़बर नहीं आई।</p>\n<p>इतना लंबा सन्नाटा कि विक्रम ने ख़ुद को यह मानने दिया कि शायद उसका गुस्सा उतर गया है।</p>\n<p>शायद उसने बात छोड़ दी।</p>\n<p>फिर एक रात उनके खेत में खड़ी दस एकड़ गेहूँ की फसल जल गई।</p>\n<p>पूरा मौसम।</p>\n<p>एक ही रात में।</p>\n<p>आग खेत के किनारे जिस बराबरी से फैली थी, उसे देखकर दुर्घटना मानना मुश्किल था।</p>\n<p>पिता सुबह देर तक मेड़ पर खड़े राख को मुट्ठी में भरकर देखते रहे। कुछ नहीं बोले।</p>\n<p>और स्थानीय थाने में कविता के पुराने संबंध इतने थे कि जाँच हुई भी तो बस उतनी, जितनी काग़ज़ को यह कहने के लिए चाहिए कि जाँच हुई थी।</p>\n<p>उसी सुबह विक्रम ने श्रद्धा को फोन किया।</p>\n<p>और पहली बार—</p>\n<p>सब कुछ बताया।</p>\n<p>बिना काटे।</p>\n<p>बिना किसी हिस्से को छोटा किए।</p>\n<p>बिना यह तय किए कि कौन-सा सच उसे बचाने के लिए उससे छिपाया जा सकता है।</p>\n<p>श्रद्धा डर गई थी।</p>\n<p>उसने डर छिपाया भी नहीं।</p>\n<p>लेकिन जो उसने कहा, वह विक्रम के भीतर जस का तस ठहर गया—</p>\n<p>“अब आप इसका सामना अकेले नहीं कर रहे।”</p>\n<p>फिर—</p>\n<p>“ये जो भी बनेगा, हम दोनों मिलकर झेलेंगे।”</p>\n<p>उनकी शादी उस सुबह एक बार फिर बदली थी।</p>\n<p>श्रद्धा अब वह नहीं थी जिसे विक्रम सच से बचाकर सुरक्षित रखने की कोशिश कर रहा था।</p>\n<p>वह सच के बाहर खड़ी उसकी पत्नी नहीं थी।</p>\n<p>अब वह उसके साथ उसी सच के भीतर खड़ी थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>लेकिन कविता की कहानी का एक हिस्सा ऐसा था जिसे विक्रम ने भी देर से समझा।</p>\n<p>कविता ने उसे कभी सीधे नहीं बताया।</p>\n<p>दूर से देखते-सुनते, अलग-अलग बातों को जोड़कर विक्रम ने उसकी शक्ल बनाई थी।</p>\n<p>और उस हिस्से के बीच में था—</p>\n<p><b>कमल।</b></p>\n<p>कमल का ज़िक्र पहले भी आया था।</p>\n<p>वर्षों पहले कमल ने ख़ुद विक्रम को फोन करके बताया था कि उसकी ज़िंदगी में कोई है।</p>\n<p>और पहले ही फोन पर नाम भी कह दिया था—</p>\n<p>कविता।</p>\n<p>विक्रम ने तब यह बात अपने तक रखी थी।</p>\n<p>पर आज रात से पहले उसने दोस्तों को कभी नहीं बताया था कि उस नाम का उसके लिए असल में क्या अर्थ था।</p>\n<p>कमल पहले से शादीशुदा था।</p>\n<p>कविता को नहीं पता था।</p>\n<p>कई महीनों तक नहीं।</p>\n<p>तब तक नहीं, जब तक वह उस रिश्ते में अपने भीतर का इतना कुछ नहीं दे चुकी थी कि सच सामने आने पर चोट सिर्फ एक असफल प्रेम की नहीं रह सकती थी।</p>\n<p>कमल ने जानबूझकर अपनी शादी छिपाई थी।</p>\n<p>उसने कविता को अपनी ज़िंदगी का वह हिस्सा दिखाया ही नहीं जिस पर पत्नी और बच्चों का नाम लिखा था।</p>\n<p>सच भी उससे कमल ने नहीं कहा।</p>\n<p>किसी और ने कहा।</p>\n<p>एक सहकर्मी ने बातों-बातों में उसकी पत्नी और बच्चों का ज़िक्र कर दिया—उसे ज़रा भी अंदाज़ा नहीं था कि सामने खड़ी कविता के भीतर वह साधारण-सा वाक्य क्या तोड़ने वाला है।</p>\n<p>इसके बाद भी कुछ समय दोनों की बातचीत चलती रही।</p>\n<p>मगर ख़राब ढंग से।</p>\n<p>कविता ने उससे जवाब माँगा।</p>\n<p>कमल ने ठीक से माफ़ी तक नहीं माँगी।</p>\n<p>बल्कि जब वह ख़ुद को घिरा हुआ महसूस करने लगा, तो गुस्से में कमल ने एक और बात उसके सामने फेंक दी—</p>\n<p>एक ऐसी बात जो मूल धोखे से भी ज़्यादा भीतर गई।</p>\n<p>कमल ने कहा कि विक्रम को उन दोनों के बारे में वर्षों से पता था।</p>\n<p>उस पहले फोन से ही।</p>\n<p>विक्रम जानता था कि कमल की ज़िंदगी में कविता है।</p>\n<p>और उसने कविता से कभी कुछ नहीं कहा।</p>\n<p>वहीं उसे पहली बार पता चला—</p>\n<p>कमल ने उससे झूठ बोला था।</p>\n<p>और विक्रम ने सच जानते हुए चुप्पी चुनी थी।</p>\n<p>दोनों अपराध एक जैसे नहीं थे।</p>\n<p>लेकिन चोट को हमेशा कानून की धाराओं की तरह अलग-अलग नाम नहीं दिए जा सकते।</p>\n<p>कविता कमल पर भड़की—</p>\n<p>उस शादी के लिए जिसे उसने छिपाया था।</p>\n<p>और विक्रम पर भी—</p>\n<p>उस सच के लिए जिसे वह जानता था, फिर भी वर्षों तक उसके सामने कभी नहीं रखा।</p>\n<p>शायद उस गुस्से के नीचे अपराधबोध भी था।</p>\n<p>विक्रम को बाद में ऐसा लगा।</p>\n<p>कविता शायद ख़ुद भी उस अपराधबोध को कभी वह नाम नहीं देती।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>इस बात ने कविता के भीतर वह कर दिया, जो रामफल के साथ बीते बरस भी कभी नहीं कर पाए थे।</p>\n<p>रामफल के साथ उसकी शादी पहले ही उसे बहुत कम दे पाई थी।</p>\n<p>शादी बहुत जल्दी हो गई थी।</p>\n<p>रामफल उसके बराबर कभी नहीं बन पाया—न सोच में, न ज़िम्मेदारी में, न उस जीवन को संभालने की इच्छा में जिसे दोनों को मिलकर उठाना था।</p>\n<p>कविता तेज़ थी।</p>\n<p>खूबसूरत थी।</p>\n<p>अपने होने का एहसास रखने वाली लड़की थी।</p>\n<p>और रामफल धीरे-धीरे शराब, उदासीनता और अपनी जिम्मेदारियों से बचने में डूबा रहा।</p>\n<p>घर कविता ने उठाया।</p>\n<p>रिश्ता कविता ने ढोया।</p>\n<p>और बदले में उसे वह साधारण सम्मान तक बहुत कम मिला जिसकी किसी विवाह में माँग भी नहीं करनी पड़नी चाहिए।</p>\n<p>इसीलिए वह वर्षों पहले विक्रम की तरफ खिंची थी।</p>\n<p>क्योंकि वह साफ़ तौर पर वह सब था जो रामफल नहीं था।</p>\n<p>और शायद बाद में कमल की तरफ भी इसी वजह से।</p>\n<p>विक्रम को अब लगता था—</p>\n<p>कविता असल में प्रेम के पीछे नहीं भाग रही थी।</p>\n<p>वह उस बहुत साधारण गरिमा की तलाश में थी जिसमें उसके साथ खड़ा इंसान उसके बराबर हो।</p>\n<p>कमल ने उसी जगह उसे धोखा दिया।</p>\n<p>जानबूझकर।</p>\n<p>आँखों में देखकर।</p>\n<p>उसे एक ऐसे झूठ पर सच्चा रिश्ता बनाने दिया जिसे उसने ख़ुद रचा था।</p>\n<p>और उसके बाद विक्रम की चुप्पी सामने आई—</p>\n<p>कम शोर वाली, लेकिन अपनी जगह वास्तविक।</p>\n<p>वह सच जिसे विक्रम ने वर्षों तक इसलिए नहीं कहा क्योंकि उसे लगा चुप रहना बेहतर है, आख़िर कविता तक सच बनकर नहीं पहुँचा।</p>\n<p>एक गुस्साए इंसान के हाथ में हथियार बनकर पहुँचा।</p>\n<p>और कई बार सच देर से मिले तो सिर्फ देर नहीं होती—</p>\n<p>उसका अर्थ भी बदल चुका होता है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम ने यह सब सुनाते हुए अपने दोस्तों की तरफ देखा था।</p>\n<p>जैसे आगे की बात कहने से पहले वह चाहता हो कि वे कविता के किए को देखने से पहले उस लड़की को भी एक बार देख लें जो वहाँ तक पहुँची थी।</p>\n<p>“एक बात समझना।”</p>\n<p>उसने कहा।</p>\n<p>“उसके बाद जो हुआ, उसे सही ठहराने से पहले नहीं।”</p>\n<p>एक पल।</p>\n<p>“उसे समझने से पहले।”</p>\n<p>उस समय तक कविता ने अपनी ज़िंदगी में एक चीज़ ऐसी बनाई थी जिसे वह बिना किसी संदेह के अपना कह सकती थी—</p>\n<p>उसकी वर्दी।</p>\n<p>उसका पद।</p>\n<p>उसका अधिकार।</p>\n<p>बाकी लगभग हर जगह उसे किसी न किसी ने कम दिया था।</p>\n<p>रामफल के साथ विवाह ने उसे बराबरी नहीं दी।</p>\n<p>विक्रम के साथ प्रेम पूरा होकर भी उसका नहीं हो सकता था।</p>\n<p>कमल के साथ जो उसने सच माना, वह झूठ निकला।</p>\n<p>लेकिन उसकी नौकरी—</p>\n<p>वह उसकी थी।</p>\n<p>उसने कमाई थी।</p>\n<p>हर सीढ़ी ख़ुद चढ़ी थी।</p>\n<p>फिर ज़मीन के विवाद ने वर्षों बाद विक्रम को उसके सामने दोबारा ला खड़ा किया।</p>\n<p>अब स्मृति की तरह नहीं।</p>\n<p>एक वास्तविक इंसान की तरह।</p>\n<p>और उसके सामने वह ज़िंदगी थी जो किसी तरह पूरी हो गई थी—</p>\n<p>श्रद्धा।</p>\n<p>बच्चे।</p>\n<p>घर।</p>\n<p>एक स्थिरता, जिसकी ओर कविता ने ज़िंदगी में एक से ज़्यादा बार हाथ बढ़ाया था और हर बार उसकी मुट्ठी खाली रह गई थी।</p>\n<p>विक्रम को नहीं लगता था कि <b>सुरेश मलिक</b> ने कविता का गुस्सा पैदा किया।</p>\n<p>गुस्सा पहले से था।</p>\n<p>मलिक ने बस उसे पहचान लिया।</p>\n<p>और उससे भी ख़तरनाक बात—</p>\n<p>उसे मालूम था कि उस गुस्से के पास माचिस कहाँ रखनी है।</p>\n<p>मलिक विक्रम के अपने गाँव का था, उसके पिता की पीढ़ी का।</p>\n<p>विक्रम और मलिक के परिवारों के बीच दशकों पहले ज़मीन के एक दूसरे टुकड़े को लेकर विवाद हुआ था।</p>\n<p>बहुत पुराना।</p>\n<p>कब का निपट चुका।</p>\n<p>बाकी सब लगभग भूल चुके थे।</p>\n<p>मलिक नहीं।</p>\n<p>वह उन लोगों में था जो रंजिश को सालों में नहीं, दशकों में गिनते हैं—और फिर बिना शोर किए उस एक मौके का इंतज़ार करते हैं जब पुराना हिसाब किसी नए बहाने से फिर खोला जा सके।</p>\n<p>विक्रम ने कहा—</p>\n<p>“जब कविता के परिवार का हमारे साथ विवाद शुरू हुआ, मलिक को वही मौका दिख गया जिसका वह इतने साल से इंतज़ार कर रहा था।”</p>\n<p>उसका चेहरा सख़्त हो गया।</p>\n<p>“उसने कोई नई दुश्मनी पैदा नहीं की।”</p>\n<p>एक छोटा-सा विराम।</p>\n<p>“उसने पुरानी दुश्मनी को बस दोबारा काम दे दिया।”</p>\n<p>कविता का दुख उसका अपना था।</p>\n<p>उसका गुस्सा भी।</p>\n<p>लेकिन अब उनके बीच कोई तीसरा इंसान खड़ा था—</p>\n<p>जो उसके घाव भरना नहीं चाहता था।</p>\n<p>बस यह जानता था कि उन्हें खुला कैसे रखा जाए।</p>"}, {"chapter": 45, "title": "अध्याय 41 — उसे असल में क्या चाहिए था", "content": "<h1>अध्याय 41 — उसे असल में क्या चाहिए था</h1>\n<p>कार का शीशा टूटने और फोन गायब होने के बाद भी विक्रम यह नहीं समझ पाया था कि कविता को उस फोन से आख़िर चाहिए क्या था।</p>\n<p>जवाब कई हफ्तों बाद आया।</p>\n<p>एक अनजान नंबर से फोन बजा।</p>\n<p>विक्रम ने उठाया।</p>\n<p>दूसरी तरफ कविता थी।</p>\n<p>इस बार किसी कैमरे की धुँधली फुटेज में दिखता चेहरा नहीं, किसी तीसरे इंसान के पीछे छिपी मौजूदगी नहीं—</p>\n<p>सीधे कविता की आवाज़।</p>\n<p>उस बातचीत को दोहराते हुए भी विक्रम का लहजा संभल जाता था। बात जब भी उन जगहों पर लौटती थी जहाँ उसके भीतर की ज़मीन अब भी पूरी तरह समतल नहीं हुई थी, विक्रम की आवाज़ अपने आप थोड़ी सावधान हो जाती थी।</p>\n<p>कविता शांत थी।</p>\n<p>और उसी ने विक्रम को सबसे ज़्यादा परेशान किया।</p>\n<p>न गुस्सा।</p>\n<p>न कोई ऊँची आवाज़।</p>\n<p>न आरोपों का शोर।</p>\n<p>जिस तूफान के लिए वह ख़ुद को तैयार करके बैठा था, दूसरी तरफ वैसा कुछ नहीं था।</p>\n<p>सिर्फ एक ठहरी हुई, सोच-समझकर रखी गई शांति।</p>\n<p>वैसी शांति जो अक्सर तब आती है जब इंसान फ़ैसला करने की अवस्था से बहुत आगे निकल चुका हो।</p>\n<p>कविता ने उसे बताया कि फोन में जो कुछ था, अब उसके पास है।</p>\n<p>श्रद्धा के साथ तस्वीरें।</p>\n<p>उनके बीच के संदेश।</p>\n<p>बच्चों की तस्वीरें।</p>\n<p>घर की बातें।</p>\n<p>और कुछ बहुत पुराने संदेश भी, जो हर नए फोन के साथ बैकअप में चलते आए थे और कभी ठीक से मिटाए नहीं गए थे—उस समय के, जब नैना उसकी ज़िंदगी में थी।</p>\n<p>हर संदेश।</p>\n<p>हर तस्वीर।</p>\n<p>सब कुछ।</p>\n<p>एक फोन पहले भी उसकी शादी के बीच गवाह बनकर खड़ा हो चुका था। अब दूसरा फोन किसी और के हाथ में था।</p>\n<p>कविता ने उन्हें वैसे सँभालकर रखा था जैसे पुलिस की ट्रेनिंग पा चुकी कोई अफसर सबूत सँभालती है।</p>\n<p>फिर कविता ने बताया कि उन्हें वहीं बंद रखने की कीमत क्या होगी।</p>\n<p>पैसा नहीं।</p>\n<p>पैसा होता तो शायद विक्रम के लिए बात समझना आसान होता।</p>\n<p>कविता को ज़मीन चाहिए थी।</p>\n<p>सिर्फ विवाद ख़त्म नहीं करना था।</p>\n<p>समझौता भी नहीं।</p>\n<p>उसके परिवार के पक्ष में कोई उदार बँटवारा तक नहीं।</p>\n<p>वह चाहती थी कि विक्रम का परिवार पूरी तरह पीछे हटे।</p>\n<p>हदबंदी पर अपना दावा औपचारिक रूप से छोड़े।</p>\n<p>काग़ज़ पर लिखकर दे।</p>\n<p>और सबके सामने माने कि शुरू से सही पक्ष कविता के परिवार का था।</p>\n<p>उसी क्षण विक्रम समझ गया—</p>\n<p>उसे ज़मीन के उस टुकड़े से उतना मतलब नहीं था।</p>\n<p>उसे <b>जीत</b> चाहिए थी।</p>\n<p>सिर्फ जीत भी नहीं।</p>\n<p>जीत की पूरी शक्ल।</p>\n<p>काग़ज़ पर, लोगों के सामने—ऐसी कि कोई बाद में यह न कह सके कि दोनों पक्ष थोड़ा-थोड़ा झुके थे।</p>\n<p>ज़िंदगी ने उसे बहुत-सी जगहों पर अधूरा छोड़ा था।</p>\n<p>इस बार वह आधा कुछ नहीं चाहती थी।</p>\n<p>वह चाहती थी कि एक बार कोई दूसरा हारे—</p>\n<p>और दुनिया साफ़ देखे कि जीती वह है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम ने मना किया तो क्या होगा, इस पर भी कविता बिल्कुल साफ़ थी।</p>\n<p>फोन की सारी चीज़ें श्रद्धा के पास पहुँच जाएँगी।</p>\n<p>नैना और कविता के बारे में श्रद्धा पहले से जानती थी।</p>\n<p>इसलिए सिर्फ नामों से कोई घर टूटने वाला नहीं था।</p>\n<p>मगर कविता के पास नामों से ज़्यादा था।</p>\n<p>निजी संदेश।</p>\n<p>तस्वीरें।</p>\n<p>पुरानी बातचीत।</p>\n<p>ऐसी चीज़ें जिन्हें संदर्भ से अलग करके, सही जगह काटकर, ग़लत रोशनी में रखकर किसी भी पुराने सच को नया शक बनाया जा सकता था।</p>\n<p>विक्रम को लगा, कविता अब सिर्फ यह नहीं चाहती थी कि श्रद्धा उसका अतीत जाने।</p>\n<p>वह यह साबित करना चाहती थी कि विक्रम ने जो विवाह इतने वर्षों में बनाया है, वह उतना मजबूत नहीं जितना दिखाई देता है।</p>\n<p>कि पर्याप्त ज़ोर सही दरार पर लगाया जाए—</p>\n<p>तो वह भी टूट सकता है।</p>\n<p>लेकिन इसके बाद कविता ने जो कहा, उसने विक्रम को सचमुच डरा दिया।</p>\n<p>कविता ने विक्रम को याद दिलाया कि वह पुलिस में है।</p>\n<p>उसके पास सिर्फ फोन नहीं है।</p>\n<p><b>पद भी है।</b></p>\n<p>संबंध भी।</p>\n<p>ऐसे लोग भी जो कभी न कभी उससे कोई एहसान ले चुके हैं और अब बदले में उसके लिए एक दरवाज़ा खोल सकते हैं।</p>\n<p>अगर विक्रम ज़मीन के मामले में पीछे नहीं हटा, तो उसके ख़िलाफ़ झूठा मुकदमा दर्ज कराया जाएगा।</p>\n<p>कोई मामूली मामला नहीं।</p>\n<p>ऐसा आरोप जो एक साथ उसकी नौकरी, उसकी इज़्ज़त और उस काम को भी ख़त्म करने के लिए काफी हो जिसका ज़िक्र किसी फाइल में नहीं था।</p>\n<p>कविता ने यह नहीं बताया कि आरोप क्या होगा।</p>\n<p>उसे बताने की ज़रूरत भी नहीं पड़ी।</p>\n<p>उसके स्वर की सपाट निश्चितता से विक्रम समझ गया कि वह सिर्फ संभावना नहीं गिना रही।</p>\n<p>वह विकल्प चुन चुकी है।</p>\n<p>और इसी वजह से धमकी अधिक वास्तविक लगी।</p>\n<p>खाली धमकियाँ अक्सर शोर करती हैं।</p>\n<p>यह वाली नहीं कर रही थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>बाद में जब विक्रम ने यह हिस्सा अपने दोस्तों को सुनाया, कमरे में अचानक कोई कुछ नहीं बोला।</p>\n<p>वह ऐसी ख़ामोशी थी जिसमें हर इंसान एक ही समय पर समझ जाता है कि बात अब पुराने प्रेम, टूटे रिश्ते या ज़मीन की मेड़ से बहुत आगे निकल चुकी है।</p>\n<p>कविता अब केवल वह चीज़ वापस नहीं चाहती थी जिसे वह अपना मानती थी।</p>\n<p>वह उस चीज़ को चोट पहुँचाना चाहती थी जो विक्रम ने उसके बाद बनाई थी।</p>\n<p>इसलिए नहीं कि उस पर उसका कोई अधिकार था।</p>\n<p>बल्कि इसलिए कि उस पर उसका कोई अधिकार नहीं था।</p>\n<p>जो उसका नहीं हो सका, वह विक्रम का बनकर रहे—</p>\n<p>यह उसे मंज़ूर नहीं था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस फोन पर विक्रम ने उससे पूछा था—</p>\n<p>“अब क्यों?”</p>\n<p>इतने वर्षों बाद।</p>\n<p>कमल के बाद।</p>\n<p>उन दोनों के बीच सब ख़त्म हो जाने के बाद।</p>\n<p>कविता की अपनी शादी में जो कुछ हुआ, उसके बाद।</p>\n<p>“अभी ही क्यों, कविता?”</p>\n<p>दूसरी तरफ कुछ क्षण ख़ामोशी रही।</p>\n<p>फिर कविता ने जो कहा, वह विक्रम के कानों में अटका रह गया।</p>\n<p>कविता की आवाज़ अब भी शांत थी।</p>\n<p>लगभग भावहीन।</p>\n<p>“क्योंकि अब मेरे पास खोने के लिए कुछ नहीं बचा, विक्रम।”</p>\n<p>एक विराम।</p>\n<p>“और तुम्हारे पास अब भी सब कुछ है।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>कविता ने आख़िरी बात उसी ठंडे ठहराव में कही—</p>\n<p>“ये बराबरी की लड़ाई नहीं है।”</p>\n<p>फिर—</p>\n<p>“मैं इसे बराबर करके रहूँगी।”</p>\n<p>कॉल ख़त्म होने के बाद भी विक्रम कुछ देर फोन कान से लगाए बैठा रहा।</p>\n<p>कभी जिस लड़की ने उससे प्रेम करते हुए अपने हिस्से का भविष्य ख़ुद पीछे रख दिया था, वही अब उसके वर्तमान को दाँव पर रखने को तैयार थी।</p>\n<p>बीच में सिर्फ साल नहीं गुज़रे थे।</p>\n<p>बहुत कुछ सड़कर अपना नाम बदल चुका था।</p>\n<p>और पहली बार विक्रम को पूरी तरह समझ आया—</p>\n<p>ज़मीन तो केवल वह जगह थी जहाँ लड़ाई दिखाई दे रही थी।</p>\n<p>असली लड़ाई कहीं और थी।</p>"}, {"chapter": 46, "title": "अध्याय 42 — जंगल की आग", "content": "<h1>अध्याय 42 — जंगल की आग</h1>\n<p>उस रात कविता अपने क्वार्टर में अकेली बैठी थी।</p>\n<p>विक्रम का वह फोन, जो कभी उसके पास वापस नहीं पहुँचा, उसकी दराज़ में बंद था।</p>\n<p>कमरे में कोई आवाज़ नहीं थी।</p>\n<p>और वर्षों में पहली बार कविता ने अपनी यादों को सिर्फ सहा नहीं—</p>\n<p>उन्हें बैठकर ठीक से याद किया।</p>\n<p>दो साल तक उसके आने के समय के आसपास उठती चाय की ट्रे।</p>\n<p>वह आँगन।</p>\n<p>सरसों का खेत।</p>\n<p>अपने ही कमरे में बिताई वह एक बेपरवाह रात।</p>\n<p>कुछ स्मृतियाँ ऐसी होती हैं जिन्हें इंसान चाहे जितनी भी देर दबाकर रखे, वे पुरानी नहीं होतीं। बस भीतर कहीं तह करके रख दी जाती हैं—और जिस दिन खुलती हैं, अपनी उम्र से कहीं कम पुरानी लगती हैं।</p>\n<p>कविता ने एक-एक कर उन्हें उठने दिया।</p>\n<p>कुछ देर अपने पास रहने दिया।</p>\n<p>फिर वापस रख दिया।</p>\n<p>उसने विक्रम से पूरा प्रेम किया था।</p>\n<p>उस तरह, जैसे कोई लड़की जिसे जीवन में ठीक से चुना ही न गया हो, पहली बार चुने जाने पर करती है—बिना हिसाब लगाए, बिना अपने लिए कुछ बचाकर।</p>\n<p>और इसी प्रेम की वजह से उसने कभी नैना का नंबर विक्रम को दिया था।</p>\n<p>प्रेम कम होने की वजह से नहीं।</p>\n<p>प्रेम इतना होने की वजह से कि उसने ख़ुद को समझा लिया था—</p>\n<p>विक्रम उस सामान्य भविष्य का हकदार है जो वह उसे नहीं दे सकती।</p>\n<p>उसने सोचा था, वह उसे वही दे रही है जो ख़ुद कभी उसका हो ही नहीं सकता था।</p>\n<p>उसे यह नहीं मालूम था कि जिस दरवाज़े को वह उसके लिए खोल रही है, विक्रम सचमुच उसके पार चला जाएगा।</p>\n<p>और वहाँ किसी और लड़की से प्रेम कर बैठेगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>रामफल के साथ उसकी शादी बहुत जल्दी हो गई थी।</p>\n<p>उस विवाह ने उससे बहुत कुछ लिया।</p>\n<p>लौटाया लगभग कुछ नहीं।</p>\n<p>रामफल की उपेक्षा।</p>\n<p>उसकी शराब।</p>\n<p>एक ऐसा घर जिसका भार कविता ने उठाया और जिसके लिए किसी ने कभी ठीक से उसका धन्यवाद तक नहीं किया।</p>\n<p>फिर कमल आया।</p>\n<p>और कुछ समय के लिए कविता ने फिर वही ग़लती की—</p>\n<p>विश्वास कर लिया कि इस बार कोई इंसान उसे आधा नहीं चुनेगा।</p>\n<p>लेकिन कमल पहले से शादीशुदा था।</p>\n<p>जितने समय तक उसने कविता को अपने से प्रेम करने दिया, उतने समय तक वह सच छिपाता रहा।</p>\n<p>और सच सामने आया तो वह भी कमल की ज़बान से नहीं।</p>\n<p>फिर आख़िर में, अपने ही गुस्से में घिरकर, कमल ने उसे यह भी बता दिया कि विक्रम को उन दोनों के बारे में वर्षों से पता था।</p>\n<p>विक्रम जानता था।</p>\n<p>और उसने कभी कुछ नहीं कहा।</p>\n<p>कविता को अपनी ही बेइज़्ज़ती का एक हिस्सा कमल से पता चला, जो उसी बेइज़्ज़ती की वजह था—</p>\n<p>और दूसरा हिस्सा विक्रम की चुप्पी से, जिसे उसने कभी अपने जीवन में सबसे ज़्यादा भरोसा दिया था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>लेकिन एक और अपमान था।</p>\n<p>शायद ज़्यादा शांत।</p>\n<p>और इसीलिए ज़्यादा देर तक रहने वाला।</p>\n<p>विक्रम और अपने बीच के पुराने सच को कविता ने वर्षों तक बचाकर रखा था।</p>\n<p>अपने ससुराल में कभी एक शब्द नहीं।</p>\n<p>पति के परिवार के सामने कभी कोई चूक नहीं।</p>\n<p>जो हुआ था, उसकी पूरी ज़िम्मेदारी, उसका पूरा राज़, उसने अपने हिस्से में अकेले उठाए रखा।</p>\n<p>जैसे कोई इंसान उस आख़िरी चीज़ को बचाती है जिसे वह दूसरी बार खोने का जोखिम नहीं उठा सकती।</p>\n<p>उसे विश्वास था कि कम-से-कम इस एक बात में विक्रम भी वही करेगा।</p>\n<p>राज़ दोनों का था।</p>\n<p>तो हिफ़ाज़त भी दोनों की होनी चाहिए थी।</p>\n<p>मगर बात उसकी तरफ से नहीं टूटी।</p>\n<p>विक्रम की तरफ से टूटी।</p>\n<p>श्रद्धा को किसी तरह कविता और विक्रम के बारे में पता चला।</p>\n<p>उसके बाद की कड़वाहट में श्रद्धा ने विक्रम की माँ को बताया।</p>\n<p>वहाँ से बात आगे बढ़ी।</p>\n<p>और आख़िर कविता की सास तक पहुँच गई।</p>\n<p>कुछ ही हफ्तों में उस घर में कविता के लिए जो थोड़ा-बहुत सम्मान बचा था, वह भी पतला पड़ने लगा।</p>\n<p>न कोई बड़ा ऐलान हुआ।</p>\n<p>न किसी ने घर के बीच खड़े होकर उसे कटघरे में रखा।</p>\n<p>कई बार सम्मान इसी तरह ख़त्म होता है—</p>\n<p>आवाज़ के लहजे में थोड़ा-सा फ़र्क़ आ जाता है।</p>\n<p>बात करते समय आँखें बदल जाती हैं।</p>\n<p>और जिस घर में आप बरसों से रहते हों, वहाँ अचानक आपको महसूस होने लगता है कि लोग अब आपके बारे में वह भी जानते हैं जिसे आपने कभी उन्हें जानने का अधिकार नहीं दिया था।</p>\n<p>कविता ने उस राज़ को बचाया था।</p>\n<p>अपने लिए भी।</p>\n<p>विक्रम के लिए भी।</p>\n<p>उसे लगा था वह भी बचाएगा।</p>\n<p>वह नहीं बचा पाया।</p>\n<p>यही वह घाव था जहाँ दुख ने पहली बार अपना रूप बदलना शुरू किया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>और दूसरी तरफ—</p>\n<p>विक्रम की ज़िंदगी आगे बढ़ती रही।</p>\n<p>गाँव छोटा था।</p>\n<p>ख़बरें पहुँचती रहती थीं।</p>\n<p>उसकी शादी हर साल और मजबूत हुई।</p>\n<p>एक पत्नी थी जिसने न जाने किन-किन हालात में उसका साथ दिया था।</p>\n<p>दो बच्चे थे, जिनके बारे में सुनने वाली हर ख़बर यही कहती कि वे अच्छे हैं, खुश हैं।</p>\n<p>कविता को तकलीफ़ इस बात से नहीं थी कि विक्रम ने किसी और से प्रेम किया।</p>\n<p>नैना की ओर तो उसने ख़ुद उसे भेजा था—</p>\n<p>भले तब उसे यह अंदाज़ा नहीं था कि वह रिश्ता कितना गहरा हो जाएगा।</p>\n<p>दर्द कहीं और था।</p>\n<p>कविता की ज़िंदगी में हर नुकसान जैसे उसके भीतर रुक गया था।</p>\n<p>और विक्रम की ज़िंदगी से वही नुकसान ऐसे गुज़र गए जैसे पहाड़ के ऊपर से मौसम गुज़रता है—</p>\n<p>एक पल छाया।</p>\n<p>शायद कुछ देर ठहरा।</p>\n<p>फिर आगे निकल गया।</p>\n<p>और पहाड़ वहीं खड़ा रहा।</p>\n<p>उसकी ज़िंदगी बनती गई।</p>\n<p>कविता की ज़िंदगी में हर अधूरापन अपना निशान छोड़ता गया।</p>\n<p>उस रात अपने कमरे में बैठी कविता ख़ुद को ख़लनायिका नहीं समझ रही थी।</p>\n<p>वह ख़ुद को ऐसी स्त्री समझ रही थी जिसने अपनी पूरी जवान ज़िंदगी में बार-बार अपने हिस्से दिए—</p>\n<p>और बदले में किसी ने उसे उतना नहीं लौटाया।</p>\n<p>अब उसने तय कर लिया था—</p>\n<p>हर बार कीमत वही नहीं चुकाएगी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कभी विक्रम ने उसे <b>जंगल की आग</b> कहा था।</p>\n<p>उस समय, जब वह उससे प्रेम करता था।</p>\n<p>एक बेहद निजी, बेहद बेपरवाह पल में।</p>\n<p>“तुम तो आग हो, कविता—पूरी की पूरी आग।”</p>\n<p>वह बात कविता कभी नहीं भूली।</p>\n<p>तब उसे वह तारीफ लगी थी।</p>\n<p>उसने हँसकर स्वीकार कर लिया था।</p>\n<p>आज की रात, अपने कमरे में बैठी उसे लगा—</p>\n<p>किसी लड़की को अँधेरे में जंगल की आग कह देने वाला इंसान यह उम्मीद नहीं कर सकता कि एक दिन जब वही आग उसके सामने खड़ी हो, तो उसे उसकी गर्मी पर हैरानी हो।</p>\n<p>सामने लगे पूरे कद के आईने में कविता की नज़र अपने ही प्रतिबिंब से मिली।</p>\n<p>उसने नज़र नहीं हटाई।</p>\n<p><b>मेजर साहब।</b></p>\n<p>कभी यही संबोधन रात के फोन पर उसके होंठों से इतना नरम निकलता था कि दो शब्दों के बीच भी प्रेम सुनाई देता था।</p>\n<p>आज उसने वही शब्द विक्रम से नहीं—</p>\n<p>आईने में खड़ी अपनी ही परछाईं से कहे।</p>\n<p>और उनमें पुरानी नरमी का एक कण भी नहीं बचा था।</p>\n<p><b>मेरा प्यार तो आपने देख लिया, मेजर साहब।</b></p>\n<p>लोग कहते हैं—</p>\n<p>प्यार और जंग में सब जायज़ है।</p>\n<p>जैसे दोनों एक-दूसरे के उलट हों।</p>\n<p>जबकि कभी-कभी जंग उसी प्रेम का आख़िरी, सबसे कठोर रूप होती है जिसे बहुत देर तक घिसा गया हो।</p>\n<p>कविता ने प्रेम में हिसाब नहीं लगाया था।</p>\n<p>जो दिया था, पूरा दिया था।</p>\n<p>उसके जीवन में वही एक चीज़ थी जिसे उसने किसी इंसान को बिना किसी गणना के दिया था।</p>\n<p>लेकिन अब वह प्रेम ख़त्म हो चुका था।</p>\n<p>कम-से-कम उस रात आईने में अपना चेहरा देखते हुए उसने यही माना।</p>\n<p>और उसकी जगह जो शुरू हो रहा था—</p>\n<p>वह जंग थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दराज़ में एक बंद फोन था—आख़िरी गवाह की तरह चुप।</p>\n<p>और कविता के भीतर वर्षों के बंद नुकसान।</p>\n<p>अब उसे ज़मीन से ज़्यादा कुछ चाहिए था।</p>\n<p>वह बस एक बार चाहती थी कि किसी और की ज़िंदगी भी वैसे ही मुड़े जैसे उसकी बार-बार मुड़ी थी।</p>\n<p>कि विक्रम—</p>\n<p>जो उसे दूर से स्थिर, संभला हुआ, लगभग पूरा दिखाई देता था—</p>\n<p>एक बार समझे कि कैसा लगता है जब आपकी किसी प्यारी चीज़ पर अचानक किसी ऐसे हाथ का ख़तरा आ जाए जिसे आते हुए आपने देखा ही न हो।</p>\n<p>मलिक उसे रास्ता दे चुका था।</p>\n<p>सिर्फ पुराने ज़मीन विवाद में बढ़त का नहीं।</p>\n<p>उससे कहीं आगे का।</p>\n<p>अगर विक्रम उसकी बात नहीं मानता, तो उसके पास सिर्फ खेत या मेड़ की चिंता नहीं बचेगी।</p>\n<p>कविता ने उस विचार को अपने भीतर उतरने दिया।</p>\n<p>ठंडा।</p>\n<p>साफ़।</p>\n<p>सोचा-समझा।</p>\n<p>जैसे कोई इंसान ऐसे फ़ैसले के साथ बैठना सीख रही हो जिसका पछतावा भी उसने पहले ही स्वीकार कर लिया है।</p>\n<p>कुछ देर बाद उसने अपना फोन उठाया।</p>\n<p>मलिक का दिया नंबर खोला।</p>\n<p>उँगली कॉल के निशान पर ठहरी।</p>\n<p>एक पल के लिए आँगन फिर सामने आ सकता था।</p>\n<p>हाथ में चाय की ट्रे लिए वह लड़की—</p>\n<p>जो कप उठाने में बस एक क्षण ज़्यादा लगाती थी ताकि कोई लड़का उसे एक क्षण और देख ले।</p>\n<p>वह लड़की जिसने तब ज़िंदगी से बहुत कुछ नहीं माँगा था।</p>\n<p>सिर्फ इतना—</p>\n<p>कि कोई उसे ठीक से देखे।</p>\n<p>कविता ने उस लड़की के बारे में ख़ुद को दोबारा सोचने नहीं दिया।</p>\n<p>उसने मलिक को कॉल कर दिया।</p>"}, {"chapter": 47, "title": "अध्याय 43 — पहली बार की आवाज़", "content": "<h1>अध्याय 43 — पहली बार की आवाज़</h1>\n<p>उस रात से पहले की पूरी कहानी सिर्फ यादों में मौजूद थी।</p>\n<p>विक्रम की यादों में।</p>\n<p>दस साल से भी ज़्यादा समय तक वह उसे अपने भीतर अकेला लिए फिरा था—बिना किसी ऐसे इंसान के जिसके सामने उसका पूरा वज़न रख सके।</p>\n<p>लेकिन अब जो होने वाला था, वह सिर्फ स्मृति नहीं रहने वाला था।</p>\n<p>इतने वर्षों से चुप पड़ी कहानी पहली बार आवाज़ लेने वाली थी।</p>\n<p>और इस बार उसे अकेले विक्रम को नहीं उठाना था।</p>\n<p>तीन पुराने दोस्त उसके सामने बैठकर उसे सुनने वाले थे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कविता की उस धमकी भरी फोन कॉल के एक हफ्ते बाद की शनिवार की रात थी।</p>\n<p>नई दिल्ली के चाणक्यपुरी का घर रोशनी में खुला हुआ था।</p>\n<p>भीतर की गर्मी ड्राइववे तक फैल रही थी।</p>\n<p>विक्रम ख़ुद गेट पर खड़ा था।</p>\n<p>चौधरी उसके साथ।</p>\n<p>दोनों को कहीं जाने की जल्दी नहीं थी।</p>\n<p>कुछ देर बाद गाड़ी भीतर मुड़ी।</p>\n<p>शंकर उतरा।</p>\n<p>उसे देखते ही विक्रम के भीतर कोई गाँठ ढीली हुई—ऐसी गाँठ जिसके बँधे होने का एहसास भी उसे उसी क्षण हुआ।</p>\n<p>दो साल एक पल में सिमट गए।</p>\n<p>सामने वही इंसान खड़ा था जिसके साथ उसने कभी ऐसी ठंड में टेंट बाँटा था जहाँ छह घंटे साथ बैठे रहने के लिए बातचीत ज़रूरी नहीं होती थी।</p>\n<p>तब विक्रम, शंकर और पठानिया—तीनों एक ही यूनिट में थे।</p>\n<p>फिर ज़िंदगी तीन दिशाओं में निकल गई।</p>\n<p>“अबे, ओ मेजर साहब! अभी तक ज़िंदा है?”</p>\n<p>शंकर ने अपना बैग ठीक से नीचे रखने का इंतज़ार भी नहीं किया।</p>\n<p>विक्रम हँस पड़ा।</p>\n<p>बिना कोशिश के।</p>\n<p>ऐसी हँसी जो बहुत समय बाद उससे इतनी आसानी से निकली थी।</p>\n<p>दोनों गले मिले।</p>\n<p>सख़्ती से।</p>\n<p>बिना कुछ कहे।</p>\n<p>सामान्य से कुछ सेकंड ज़्यादा।</p>\n<p>लेकिन कुछ रिश्तों में इंसान यह हिसाब बहुत पहले छोड़ चुका होता है कि गले कितनी देर मिलना चाहिए।</p>\n<p>शंकर का हाथ उसकी पीठ के ऊपर, कंधे के पीछे कसकर टिका था।</p>\n<p>विक्रम को अचानक एक पुरानी रात याद आई—छह घंटे की पहरेदारी, दोनों साथ, लगभग एक शब्द नहीं।</p>\n<p>तब भी उस हाथ की मौजूदगी काफी थी।</p>\n<p>आज भी थी।</p>\n<p>और उसी क्षण विक्रम को महसूस हुआ कि पिछले वर्षों में उसने अपने कितने हिस्से बस इसलिए तह करके भीतर रख दिए थे क्योंकि आसपास कोई ऐसा नहीं था जिसे उन्हें समझाने की ज़रूरत न पड़ती।</p>\n<p>अलग हुए तो विक्रम ने कहा—</p>\n<p>“दो साल।”</p>\n<p>फिर हल्की-सी अविश्वसनीय हँसी के साथ—</p>\n<p>“पूरे दो साल, यार।”</p>\n<p>आख़िरी शब्द पर उसकी आवाज़ जरा-सी अटक गई।</p>\n<p>ख़ुद उसे भी इसकी उम्मीद नहीं थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>शंकर अब भी दुबला, चुस्त था—जैसे सुबह दौड़ना नौकरी की ज़रूरत नहीं, पुरानी आदत हो।</p>\n<p>कद औसत, कंधे विक्रम से कुछ संकरे, लेकिन खड़े होने में वही पुराना सीधापन।</p>\n<p>करीने से कटी दाढ़ी।</p>\n<p>पतले फ्रेम का चश्मा।</p>\n<p>चेहरा पहले से थोड़ा ज़्यादा तराशा हुआ—ऊँची गाल की हड्डियाँ, पतले होंठ जिन पर हमेशा कोई सूखा-सा जवाब तैयार लगता था।</p>\n<p>और आँखें—</p>\n<p>पहले पहाड़ों और घाटियों में छोटी-सी हलचल पकड़ती थीं।</p>\n<p>अब अदालत में गवाहों को पढ़ती थीं।</p>\n<p>उनकी धार कम नहीं हुई थी।</p>\n<p>विक्रम कुछ क्षण उसे देखता रहा।</p>\n<p>पुराने दोस्त वर्षों बाद मिलें तो सामने खड़े इंसान में अनजाने ही उस लड़के को खोजते हैं जिसे कभी जानते थे।</p>\n<p>शंकर में वह अब भी था।</p>\n<p>खासकर उसके खड़े होने के ढंग में—</p>\n<p>दोनों पैरों पर बराबर वज़न, जैसे किसी भी क्षण कुछ हो सकता हो।</p>\n<p>जबकि अब उसके सामने किसी मुश्किल फ़ैसले से ज़्यादा ख़तरनाक शायद ही कुछ आता था।</p>\n<p>“अच्छा दिख रहा है तू,” विक्रम ने कहा।</p>\n<p>शंकर ने उसे ऊपर से नीचे तक देखा।</p>\n<p>“मैं ऐसा लग रहा हूँ जैसे दिनभर अदालत की कुर्सी पर बैठता हूँ। तू ऐसा लग रहा है जैसे कहीं से लौटा है जिसके बारे में मुझे बताएगा नहीं।”</p>\n<p>बात सच के ज़रूरत से ज़्यादा करीब लगी।</p>\n<p>विक्रम ने उसे हँसी में ढक दिया।</p>\n<p>“अंदर चल। पड़ोसी पुलिस बुला देंगे कि दो लोग गेट पर खड़े शांति भंग कर रहे हैं।”</p>\n<p>अंदर कदम रखते ही चौधरी ने शंकर की पीठ पर हाथ मारा।</p>\n<p>“जज साहब। चेहरा अभी भी ऐसा रखता है जैसे सामने वाले को सज़ा सुनानी हो।”</p>\n<p>शंकर मुस्कराया और उसे गले खींच लिया।</p>\n<p>“और तू अभी भी ऐसा महकता है जैसे सीधे खेत जोतकर आया हो।”</p>\n<p>चौधरी की हँसी पूरे कमरे में गूँज गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>पठानिया करीब बीस मिनट बाद पहुँचा।</p>\n<p>और हमेशा की तरह, किसी से कुछ कहने से पहले उसने कमरे को पढ़ा।</p>\n<p>बाकी दोनों से कुछ साल छोटा था और दिखता भी था। साफ़ चेहरा, बाल थोड़े लंबे, माथे से पीछे किए हुए—कॉलेज के दिनों की वह हल्की लड़कपन वाली शक्ल जो जाने कैसे अब तक उसके साथ बची रही थी।</p>\n<p>कलाई पर ढीली घड़ी।</p>\n<p>आँखें गहरी, शांत और देखने वाली।</p>\n<p>एक बार कमरे पर फिरतीं तो अक्सर दूसरी बार देखने की ज़रूरत नहीं पड़ती।</p>\n<p>लोग अब भी उसे एक बार ज़्यादा देख लेते थे—उसकी किसी उपलब्धि की वजह से नहीं, बस इसलिए कि वह देखने में वैसा था।</p>\n<p>कभी यही आँखें पूरी रात क्षितिज पर उस एक छोटी-सी हरकत को तलाशती थीं जो बाकी सबकी नज़र से छूट जाए।</p>\n<p>अब उसका काम शब्दों के बीच वही चीज़ तलाशना था।</p>\n<p>विक्रम और शंकर की आवाज़ों में फौज की पुरानी काट अब भी बची हुई थी।</p>\n<p>पठानिया की आवाज़ बदल चुकी थी।</p>\n<p>धीमी।</p>\n<p>ठहरी हुई।</p>\n<p>शब्द चुनने वाली।</p>\n<p>वर्षों पहले एक ऐसी चोट, जिसे किसी मेडिकल रिपोर्ट में ठीक से लिखा नहीं जा सकता था, उसे सर्विस से धीरे-धीरे बाहर ले आई थी।</p>\n<p>फिर उसने बंदूक की जगह लिखने की मेज़ चुन ली।</p>\n<p>अब उसके नाम के पीछे तीन उपन्यास थे।</p>\n<p>कोई बहुत बड़ा बेस्टसेलर नहीं।</p>\n<p>लेकिन उन छोटे साहित्यिक हलकों में सम्मानित, जहाँ लोग किताबें सचमुच पढ़ते थे।</p>\n<p>इसलिए कि पठानिया की सबसे पुरानी आदत अब भी वही थी—</p>\n<p>जो बाकी लोग पार कर जाते थे, वह उसे देख लेता था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम का घर भी उस रात कुछ कह रहा था।</p>\n<p>चाणक्यपुरी की शांत सड़क पर एक बड़ा घर।</p>\n<p>ड्राइववे से खुलता ड्रॉइंग रूम।</p>\n<p>मेहराब के उस पार डाइनिंग टेबल, जिसे किसी अकेले इंसान के घर की अपेक्षा कहीं ज़्यादा करीने से लगाया गया था।</p>\n<p>गहरे रंग की लकड़ी का फर्नीचर—ऐसा जिसे बार-बार बदला नहीं जाता, बस बरसों सँभाला जाता है।</p>\n<p>घर में परिवार के रहने की जगह थी।</p>\n<p>लेकिन उस रात परिवार नहीं था।</p>\n<p>डाइनिंग टेबल की दूसरी कुर्सी बहुत समय से खाली लगती थी।</p>\n<p>उसका कुशन जैसे उस इंसान की बैठने की आदत याद रखे हुए था जो अब वहाँ नियमित नहीं बैठता।</p>\n<p>रसोई के पास कॉर्कबोर्ड पर बच्चे की एक ड्रॉइंग टँगी थी, एक कोना हल्का-सा मुड़ा हुआ।</p>\n<p>बस उतना-सा प्रमाण कि इस घर की ख़ामोशी स्थायी नहीं है।</p>\n<p>पठानिया ने सब देखा।</p>\n<p>कुछ पूछा नहीं।</p>\n<p>जिन लोगों पर कभी अपनी जान का भरोसा किया हो, उनकी चुप्पी में जबरन हाथ नहीं डाला जाता।</p>\n<p>ऐसी चुप्पी का ताला उसी के हाथ में रहने दिया जाता है—</p>\n<p>जब वह तैयार होता है, ख़ुद खोल देता है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>पठानिया और चौधरी पहली बार एक ही कमरे में थे, लेकिन दोनों एक-दूसरे की कहानियों में बरसों से मौजूद थे।</p>\n<p>चौधरी ने उसे ऊपर से नीचे देखा।</p>\n<p>“तो तू है उपन्यासकार?”</p>\n<p>पठानिया ने भौंह उठाई।</p>\n<p>“फिलहाल तो यही आरोप है।”</p>\n<p>“मैंने किसी लंबे-चौड़े इंसान की उम्मीद की थी। कम-से-कम ऐसा तो दिखता कि ज़िंदगी में कुछ झेला है जिसे लिखने लायक समझे। तू तो कॉलेज से रास्ता भूलकर इधर आया लगता है।”</p>\n<p>पठानिया ने बिल्कुल सपाट चेहरे से कहा—</p>\n<p>“और मुझे लगा था खेत जोतने वाले की खुशबू कुछ कम तेज़ होती होगी। लगता है दोनों की जानकारी सही थी।”</p>\n<p>चौधरी ज़ोर से हँसा और अगले ही पल उसे खींचकर गले लगा लिया।</p>\n<p>पहली मुलाक़ात की झिझक वहीं ख़त्म हो गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम के रसोइये ने चार लोगों की ज़रूरत से कहीं ज़्यादा खाना लगा रखा था।</p>\n<p>घी और जीरे में भुने मेवे, कबाब, ग्रिल से उतरे तंदूरी चिकन के टुकड़े, किनारों से हल्के जले पनीर टिक्के, भुने पापड़, मसाला मूँगफली, ताज़ा सलाद और फ्रिज में रखा फ्रूट रायता।</p>\n<p>और व्हिस्की—</p>\n<p><b>ब्लैक डॉग 12 इयर्स</b> की चार बोतलें।</p>\n<p>एक-एक हर किसी के नाम जैसी।</p>\n<p>विक्रम बस यह पक्का करना चाहता था कि रात उसके कहने से पहले ख़त्म न हो जाए।</p>\n<p>उन्होंने ज़रूरत से ज़्यादा पी।</p>\n<p>दूसरे दौर के बाद किसी ने गिलासों का हिसाब नहीं रखा।</p>\n<p>व्हिस्की में शहद-सी माल्ट की मिठास थी, हल्की टॉफ़ी, और हर घूँट के नीचे बहुत हल्का-सा धुआँ।</p>\n<p>पुराने नाम लौटते गए।</p>\n<p>कोई अब भी सर्विस में था।</p>\n<p>किसी ने रिलीज़ ले ली थी।</p>\n<p>किसी की शादी हो गई।</p>\n<p>कोई शहीद हो गया।</p>\n<p>बीच के खोए हुए वर्षों की साधारण इमारत एक शाम में फिर खड़ी होने लगी—एक याद दूसरी को खींचती, दूसरी तीसरी को, और धीरे-धीरे बीच के खाली हिस्से छोटे पड़ते गए।</p>\n<p>सिर्फ विक्रम कुछ सवालों से बड़ी सफाई से निकलता रहा।</p>\n<p>पिछले वर्षों में ठीक कहाँ पोस्टेड था?</p>\n<p>यह “सरकारी सेवा” असल में थी क्या?</p>\n<p>दिनभर करता क्या था?</p>\n<p>कोई इतना नहीं कुरेदा कि बचना साफ़ दिखाई देने लगे।</p>\n<p>लेकिन पठानिया ने देखा।</p>\n<p>और उसने यह भी देखा कि विक्रम की नज़र बीच-बीच में अनजाने उस खाली दूसरी कुर्सी की तरफ चली जाती थी।</p>\n<p>उसने तब भी कुछ नहीं पूछा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दस बज चुके थे जब बातचीत की रफ्तार अपने आप धीमी हुई।</p>\n<p>वह समय आ गया था जब पुराने दोस्त एक-दूसरे के सामने अच्छा दिखना छोड़ देते हैं और सचमुच बात करना शुरू करते हैं।</p>\n<p>विक्रम के गिलास की आख़िरी बर्फ़ कब की पिघल चुकी थी।</p>\n<p>बाहर कहीं कोई कुत्ता कुछ देर बेवजह भौंका, फिर चुप हो गया।</p>\n<p>छत का पंखा धीमे घूम रहा था।</p>\n<p>जैसे वह भी सुनने के लिए ठहर रहा हो।</p>\n<p>विक्रम ने अपना गिलास मेज़ पर रखा।</p>\n<p>ज़रूरत से ज़्यादा सावधानी से।</p>\n<p>बस वही पहला संकेत था।</p>\n<p>उसने नीचे देखा।</p>\n<p>हाथ पूरी तरह स्थिर नहीं था।</p>\n<p>मेज़ के नीचे हथेली घुटने पर दबा दी।</p>\n<p>इतने वर्षों की चुप्पी के बाद उसे अचानक अजीब लगा कि सामने तीन ऐसे लोग बैठे हैं जो शायद उसके भीतर रखे इस वज़न का थोड़ा हिस्सा सचमुच उठा सकते हैं।</p>\n<p>“एक बात बतानी है तुम लोगों को।”</p>\n<p>तीनों की नज़र उसकी तरफ उठी।</p>\n<p>“एक कहानी।”</p>\n<p>उसने थोड़ा रुककर कहा—</p>\n<p>“जो मैंने कभी किसी को पूरी तरह नहीं बताई।”</p>\n<p>कमरा शांत हो गया।</p>\n<p>बाहर चाणक्यपुरी की रात का ट्रैफिक अपनी रफ्तार से चलता रहा—इन चार दीवारों के भीतर क्या खुलने वाला है, उससे बिल्कुल बेख़बर।</p>\n<p>चौधरी थोड़ा आगे झुका।</p>\n<p>“बता।”</p>\n<p>विक्रम ने सामने किसी खास चीज़ को नहीं देखा।</p>\n<p>बस ख़ुद को समेटा।</p>\n<p>ठीक वैसे जैसे कभी किसी ज़रूरी ऑपरेशन से पहले करता था।</p>\n<p>डर नहीं।</p>\n<p>उससे अलग एक ठहराव—</p>\n<p>जब इंसान जानता है कि अगला कदम उठाने के बाद वापस उसी जगह नहीं लौटेगा।</p>\n<p>“पठानिया।”</p>\n<p>उसने उसकी तरफ देखे बिना कहा।</p>\n<p>“अगर ये कभी काग़ज़ पर जाए…”</p>\n<p>अब उसकी नज़र पठानिया से मिली।</p>\n<p>“उसके गाँव का नाम कभी मत लिखना।”</p>\n<p>पठानिया ने उसकी आँखें थामे रखीं।</p>\n<p>“कभी नहीं।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>फिर नज़र हटा ली।</p>\n<p>कुछ क्षण आवाज़ नहीं आई।</p>\n<p>फिर कहानी शुरू हुई—कविता से।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस रात पठानिया को नहीं मालूम था कि इसे लिखने में उसे कितने महीने लगेंगे।</p>\n<p>न यह—</p>\n<p>कि पूरी हो जाने के बाद यह कहानी दुनिया तक तो पहुँचेगी ही—</p>\n<p>और एक ऐसे पाठक तक भी, जिसके बारे में उस रात कोई सोच भी नहीं सकता था।</p>\n<p>विक्रम ने सब बताया।</p>\n<p>शुरू से आख़िर तक।</p>\n<p>पहले कविता।</p>\n<p>फिर नैना।</p>\n<p>दो पूरी ज़िंदगियाँ जिन्हें उसने दस साल से भी ज़्यादा समय तक अपने भीतर तह करके रखा था, उस रात उन तीन दोस्तों के सामने खोल दीं जिन पर उसे इतना भरोसा था कि वे उन्हें देखकर भी उसका फ़ैसला नहीं करेंगे।</p>\n<p>उसने वे बातें भी बताईं जिन्हें वह ख़ुद बाद में जोड़ पाया था—</p>\n<p>कविता इन वर्षों में कहाँ पहुँच गई।</p>\n<p>क्यों।</p>\n<p>और उस पूरे सफ़र ने उससे लगभग क्या छीन लिया था।</p>\n<p>आधी रात बहुत पीछे छूट चुकी थी।</p>\n<p>व्हिस्की लगभग ख़त्म थी।</p>\n<p>आख़िर विक्रम चुप हुआ।</p>\n<p>बहुत देर तक।</p>\n<p>फिर बोला—</p>\n<p>“बस।”</p>\n<p>एक साँस।</p>\n<p>“यही सब है।”</p>\n<p>उसने कमरे को देखा।</p>\n<p>“आज की रात तक।”</p>\n<p>पठानिया ने धीरे से कहा—</p>\n<p>“इसलिए बुलाया था हमें?”</p>\n<p>“पुराने वक्त को एक बार आवाज़ देकर कहना ज़रूरी था।”</p>\n<p>विक्रम ने जवाब दिया।</p>\n<p>“उससे पहले कि जो अभी हो रहा है, उसका सामना करूँ।”</p>\n<p>पठानिया उसे देखता रहा।</p>\n<p>और तभी उसे वह बात साफ़ दिखाई दी जिसे वह पूरी रात महसूस तो कर रहा था, नाम नहीं दे पाया था।</p>\n<p>कहानी सुनाते-सुनाते कई जगह विक्रम पुराना किस्सा बता नहीं रहा था।</p>\n<p>वह उसमें वापस चला गया था।</p>\n<p>ऑपरेशन की बातें करते समय उसकी आवाज़ सपाट, नियंत्रित रहती।</p>\n<p>लेकिन एक आँगन का ज़िक्र आते ही—</p>\n<p>या चाय की वह ट्रे, जो एक पल ज़्यादा हाथ में ठहरी थी—</p>\n<p>उसी आवाज़ में ऐसी नरमी उतर आती जिसे वह छिपाने की कोशिश भी नहीं करता।</p>\n<p>बाद में पठानिया ने अपनी उस नोटबुक में, जिसे वह पांडुलिपि से अलग रखता था, लिखा—</p>\n<p><b>इतनी कहानी सुनाने के बाद भी उसने आज एक बार भी ‘नफ़रत’ शब्द नहीं कहा। जबकि इस कहानी ने उसे यह हक पूरा दिया था। इस बात पर नज़र रखनी होगी।</b></p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसी रात कानूनी रास्ते की बात सबसे पहले शंकर ने उठाई।</p>\n<p>“उसके ख़िलाफ़ सही केस बनाना पड़ेगा।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“मतलब?”</p>\n<p>“कानूनी। दस्तावेजों वाला। साफ़।”</p>\n<p>शंकर का स्वर अब दोस्त से ज़्यादा जज का था।</p>\n<p>“ख़ुद कैमरे की फुटेज वाले लोगों के पीछे भागना नहीं। कोई अपना हिसाब नहीं। फोन की चोरी, खेत की आग, ज़मीन की वैध दोबारा पैमाइश को अपने पद का इस्तेमाल करके रुकवाना—सब कुछ काग़ज़ पर। ठीक से केस बना तो विभाग के पास कार्रवाई न करने की गुंजाइश बहुत कम बचेगी।”</p>\n<p>“तू करेगा?”</p>\n<p>शंकर ने उसे देखा।</p>\n<p>“मैं अब जज हूँ, विक्रम। मैं ख़ुद केस बनाऊँगा तो वही ग़लत होगा। और ये बात तू भी जानता है।”</p>\n<p>वह कुछ पल चुप रहा।</p>\n<p>चेहरे पर कोई निजी बात आकर ठहरी।</p>\n<p>“लेकिन मैं एक ऐसी वकील को जानता हूँ जो इसे ठीक से बना सकती है।”</p>\n<p>“कौन?”</p>\n<p>“मीनल कश्यप।”</p>\n<p>पठानिया की नज़र उठी।</p>\n<p>“मीनल…”</p>\n<p>पुरानी याद जैसे कहीं जुड़ी।</p>\n<p>“ये नाम पहले सुना है न?”</p>\n<p>शंकर कुछ ज़्यादा देर चुप रहा।</p>\n<p>फिर सिर्फ एक शब्द कहा—</p>\n<p>“पुणे।”</p>\n<p>जैसे फिलहाल उससे ज़्यादा बताना ज़रूरी न हो।</p>\n<p>फिर उसके चेहरे पर बहुत हल्की मुस्कान आई।</p>\n<p>“हम तीनों के एक-दूसरे को ठीक से जानने के काफी बाद की बात है। पोस्टिंग के दौरान मिली थी। तब लॉ पढ़ रही थी।”</p>\n<p>आवाज़ थोड़ी नरम हुई।</p>\n<p>“आठ महीने थे।”</p>\n<p>उसने गिलास की तरफ देखा।</p>\n<p>“उसके कॉलेज के पास एक छोटा-सा उडुपी रेस्टोरेंट था। उसका दावा था कि पूरे शहर में उससे अच्छा खाना कहीं नहीं मिलता। एक बार फिल्म देखने गए और उसने आधी फिल्म मुझे ये समझाने में निकाल दी कि कहानी क्यों बेकार है। नदी के किनारे लंबी-लंबी सैर… बिना किसी खास वजह के।”</p>\n<p>शंकर ने गिलास को हल्का-सा घुमाया।</p>\n<p>“कुछ बड़ा नहीं था।”</p>\n<p>फिर कुछ सोचकर बोला—</p>\n<p>“बस अच्छा था। आसान। ऐसी चीज़ जिसकी कीमत अक्सर तब समझ आती है जब बहुत साल बाद पलटकर देखते हो।”</p>\n<p>विक्रम उसे आश्चर्य से देख रहा था।</p>\n<p>“आठ महीने? हमें सिर्फ नाम बताया था तूने।”</p>\n<p>“नाम बताया था। बाकी नहीं।”</p>\n<p>“क्यों?”</p>\n<p>शंकर ने कंधे उचकाए।</p>\n<p>“तब बताने की कोई खास वजह नहीं लगी। और जिन चीज़ों का हिसाब मैं ख़ुद ठीक से न लगा पाऊँ, उनके बारे में बोलने में कभी अच्छा नहीं रहा।”</p>\n<p>पठानिया उसे ध्यान से देख रहा था।</p>\n<p>“अब भी सोचता है उसके बारे में?”</p>\n<p>शंकर ने एक क्षण उसकी तरफ देखा।</p>\n<p>“जितना तुम लोगों को कभी बताया, उससे ज़्यादा।”</p>\n<p>फिर ख़ुद ही बात को हल्का किया।</p>\n<p>“छोटा जवाब चाहिए तो—हम दोस्त हैं। आज रात इतना ही रहने दो। बाकी कभी तब बताऊँगा जब बाकी बताने लायक कुछ हुआ।”</p>\n<p>कुछ देर बाद वह फिर बोला—</p>\n<p>“दिल्ली में प्रैक्टिस करती है। उसके फ़ैसले पर इस पेशे में लगभग किसी से ज़्यादा भरोसा है मुझे।”</p>\n<p>वह बात बहुत सहजता से कह गया।</p>\n<p>लेकिन उसकी सहजता उस तथ्य से पूरी तरह मेल नहीं खाती थी कि उसे आज भी मालूम था—</p>\n<p>वह किस शहर में है।</p>\n<p>क्या करती है।</p>\n<p>और कैसी वकील बन चुकी है।</p>\n<p>पठानिया ने पूछा—</p>\n<p>“हममें से कोई मिला है उससे?”</p>\n<p>“नहीं।”</p>\n<p>शंकर ने बात वहीं बंद कर दी।</p>\n<p>“नाम सुन लिया। थोड़ा बाकी भी। आज के लिए काफी है।”</p>\n<p>फिर—</p>\n<p>“कल फोन करूँगा उसे। जो आगे होगा, ठीक से होगा तो तुम सबको पता चल जाएगा।”</p>\n<p>किसी ने और नहीं पूछा।</p>\n<p>पुराने दोस्त कई बार यह भी जानते हैं कि किस चुप्पी को वहीं छोड़ देना चाहिए।</p>\n<p><b>पुणे</b> के पीछे जो कुछ था, वह फिलहाल शंकर का था।</p>\n<p>और इतना कहना ही उसका वादा था कि किसी दिन वह ख़ुद बताएगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>आधी रात के बाद, जब व्हिस्की अपना काम कर चुकी थी और कमरे पर उससे कहीं शांत चीज़ उतर आई थी, विक्रम बिना कुछ कहे उठा।</p>\n<p>रसोई में गया।</p>\n<p>लौटा तो हाथ में आइसक्रीम का छोटा डिब्बा था।</p>\n<p>साथ में चार चम्मच।</p>\n<p>उसने उसे बीच में रख दिया—</p>\n<p>ऐसे, जैसे कोई इंसान आख़िर उस इच्छा से शर्माना छोड़ दे जिसे कभी ख़ुद ही बेवकूफ़ी कहा करता था।</p>\n<p>शंकर कुछ क्षण डिब्बे को देखता रहा।</p>\n<p>उसके चेहरे पर अविश्वास और अपनापन एक साथ आया।</p>\n<p>“तू?”</p>\n<p>विक्रम ने ढक्कन खोल दिया।</p>\n<p>“हाँ।”</p>\n<p>“वही इंसान जो इसे ‘भेष बदलकर आई चीनी’ कहता था?”</p>\n<p>विक्रम ने पहला चम्मच भर लिया।</p>\n<p>“वही।”</p>\n<p>“फिर ये चमत्कार?”</p>\n<p>विक्रम खाते हुए मुस्कराया।</p>\n<p>“एक लड़की ने कभी कहा था कि वह मेरी ये आदत ठीक करके रहेगी।”</p>\n<p>एक छोटा-सा विराम।</p>\n<p>“लगता है मैंने करने दी।”</p>\n<p>कमरे में जो आया वह पूरी तरह हँसी नहीं था।</p>\n<p>लेकिन उसमें हँसी की सारी गर्माहट थी।</p>\n<p>तीनों समझ गए।</p>\n<p>कुछ आदतें उस हाथ से भी ज़्यादा देर तक ज़िंदा रहती हैं जिसने पहली बार उन्हें हमारे भीतर रखा था।</p>\n<p>जैसे कोई पौधा उस रोशनी की तरफ बढ़ता रहता है जिधर कभी किसी ने उसका गमला घुमा दिया था—</p>\n<p>उस हाथ के चले जाने के बहुत बाद तक भी।</p>\n<p>चौधरी ने बिना पूछे एक चम्मच उठा लिया।</p>\n<p>किसी ने रोका नहीं।</p>\n<p>रात उसके बाद भी देर तक चली।</p>\n<p>बोतलें खाली थीं।</p>\n<p>और वर्षों से बंद कहानी, पहली बार, पूरी कही जा चुकी थी।</p>\n<p>एक-एक कर सबने अपना सामान उठाया।</p>\n<p>दरवाज़े पर विदा भी वैसी ही थी जैसी बहुत पुराने दोस्तों के बीच होती है—</p>\n<p>सहज।</p>\n<p>बिना किसी रस्म के।</p>\n<p>बिना यह कहे कि आज की रात ने कुछ बदल दिया है।</p>\n<p>लेकिन जब वे बाहर निकले—</p>\n<p>आसमान का रंग बदल चुका था।</p>\n<p>पूरब में हल्की लाली उतर रही थी—पाँच बजे के आसपास की वह धुँधली गुलाबी-सुनहरी रोशनी, जिसमें सड़क की बत्तियाँ अब भी जल रही थीं, पर उनकी ज़रूरत ख़त्म होने लगी थी।</p>\n<p>कंक्रीट की सड़क पर रात भर की ठंडक अब भी बिछी थी।</p>\n<p>फिर एक ठंडी हवा आई—हल्की, नम—जैसे रात भर कमरे में बंद रही साँस को किसी ने बाहर का रास्ता दिखा दिया हो।</p>\n<p>कहीं दूर झाड़ू की सरसराहट।</p>\n<p>चाणक्यपुरी की सड़क पर अख़बार वाले का स्कूटर धीमे गुज़र गया।</p>\n<p>फिर पहली बस का हॉर्न, बहुत दूर से।</p>\n<p>सुबह हो चुकी थी।</p>\n<p>हर कोई अपने साथ उस रात से कुछ ज़्यादा वज़न लेकर गया था, जितना लेकर वह भीतर आया था।</p>"}, {"chapter": 48, "title": "अध्याय 44 — अड़तीस पन्ने", "content": "<h1>अध्याय 44 — अड़तीस पन्ने</h1>\n<p>उसी दिन देर सुबह शंकर ने उसे फोन किया।</p>\n<p>दूसरी घंटी पर कॉल उठ गया।</p>\n<p>“शंकर यादव।”</p>\n<p>मीनल की आवाज़ में ऐसी गर्माहट थी, जैसे वर्षों ने उनके बीच की किसी पुरानी चीज़ को पूरी तरह मिटाया न हो।</p>\n<p>“सोच रही थी, आख़िर कब तुम्हें मुझसे कोई काम पड़ेगा।”</p>\n<p>“निजी काम नहीं है।”</p>\n<p>शंकर ने कहा ज़रूर, लेकिन उसकी अपनी आवाज़ ने बात को उतना सच नहीं रहने दिया।</p>\n<p>“एक केस है। दोस्त के परिवार को एक सब-इंस्पेक्टर निजी दुश्मनी में निशाना बना रही है। अपने पद का इस्तेमाल भी कर रही है। मुझे कोई ऐसा चाहिए जो केस को ठीक से बनाए—साफ़, मजबूत। बाद में कोई उसे प्रोसीजर की ख़ामी बताकर गिरा न सके।”</p>\n<p>“जो है भेज दो।”</p>\n<p>मीनल का जवाब सीधा था।</p>\n<p>“आज रात देख लूँगी।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कुछ दिन बाद मीनल ने विक्रम को ख़ुद फोन किया।</p>\n<p>शंकर से बात करते समय मीनल की आवाज़ में जो पुरानी गर्माहट थी, विक्रम से बात करते हुए उसका कोई निशान नहीं था।</p>\n<p>यह स्वर अलग था।</p>\n<p>तेज़।</p>\n<p>साफ़।</p>\n<p>पूरी तरह पेशेवर।</p>\n<p>पहले ही मिनट में विक्रम समझ गया कि सामने ऐसी वकील है जिसने अपना पूरा करियर विरोधी वकील के लिए कोई खुला सिरा न छोड़ने की आदत पर बनाया है।</p>\n<p>“शंकर ने जो भेजा था, सब देख लिया है।”</p>\n<p>मीनल बिना भूमिका के मुद्दे पर आ गई।</p>\n<p>“कुछ फाइल करने से पहले आपको ठीक-ठीक समझना होगा कि हम बना क्या रहे हैं। क्योंकि केस का ढाँचा ही आगे की हर चीज़ तय करेगा।”</p>\n<p>वह तेज़ी से बोलती थी, लेकिन एक शब्द भी जल्दबाज़ी में नहीं लगता था।</p>\n<p>कानून की भाषा उसके लिए अब खोजने की चीज़ नहीं रही थी।</p>\n<p>वह उसमें सोचती थी।</p>\n<p>“कविता की सर्विस <b>पंजाब पुलिस रूल्स, 1934</b>, जिन्हें हरियाणा में अपनाया और समय-समय पर संशोधित किया गया है, उनके तहत आती है। आज भी उस कैडर के राज्य पुलिस अफसरों के डिसिप्लिन के नियम यही हैं—भले लोगों को लगे कि आधुनिक पुलिस के साथ उसके डिसिप्लिन का ढाँचा भी पूरी तरह बदल चुका होगा।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“<b>चैप्टर 16 ऑफ द रूल्स</b> के तहत जो उसने किया है, वह माइनर पेनल्टी का मामला नहीं बनता। सीधे मेजर पेनल्टी की श्रेणी में आता है। अपने सरकारी पद का इस्तेमाल ऐसे निजी उद्देश्य के लिए करना जिसका उसकी ड्यूटी से कोई संबंध नहीं, और आगजनी के मामले में—जहाँ उसका अपना निजी हित काग़ज़ों में दर्ज है—एफआईआर या ठीक से इन्वेस्टिगेशन सुनिश्चित न करना।”</p>\n<p>“मेजर पेनल्टी का मतलब असल में क्या हो सकता है?”</p>\n<p>“माइनर प्रोसीडिंग्स होतीं तो ज़्यादा से ज़्यादा सर्विस रिकॉर्ड में वार्निंग जैसी चीज़ की बात होती।”</p>\n<p>मीनल का स्वर बिल्कुल स्थिर रहा।</p>\n<p>“मेजर पेनल्टी प्रोसीडिंग्स में रैंक कम हो सकती है, सीनियॉरिटी छिन सकती है, और सबसे गंभीर स्थिति में नौकरी से डिसमिसल तक हो सकती है।”</p>\n<p>फिर उसी सहज निश्चितता से बोली—</p>\n<p>“लेकिन उसके ख़िलाफ़ पहले कोई एडवर्स एंट्री नहीं है और बाकी सर्विस उसकी साफ़ रही है। इसलिए असल में मुझे लगता है कि बात ज़्यादा से ज़्यादा डिमोशन तक जाएगी।”</p>\n<p>विक्रम कुछ पल चुप रहा।</p>\n<p>मीनल आगे बढ़ गई।</p>\n<p>“और एक बात समझ लीजिए। डिपार्टमेंटल इन्क्वायरी में क्रिमिनल ट्रायल वाला स्टैंडर्ड नहीं लगता। हमें <b>प्रूफ बियॉन्ड रीज़नेबल डाउट</b> नहीं चाहिए।”</p>\n<p>“फिर?”</p>\n<p>“<b>प्रीपॉन्डरेंस ऑफ प्रोबेबिलिटी।</b>”</p>\n<p>उसने शब्दों को थोड़ा अलग करके कहा।</p>\n<p>“इन्क्वायरी ऑफिसर को यह दिखना चाहिए कि उपलब्ध मटीरियल के आधार पर चार्ज का सही होना ग़लत होने से ज़्यादा संभव है। क्रिमिनल स्टैंडर्ड से काफी नीचे है। लेकिन तभी काम करेगा जब काग़ज़ों की कड़ी में कोई ढील न हो।”</p>\n<p>फिर उसने तीन चीज़ें गिनाईं।</p>\n<p>“फोन चोरी की एफआईआर की सर्टिफाइड कॉपी।”</p>\n<p>“खेत में लगी आग की फायर ब्रिगेड की रिपोर्ट—जो भी सरकारी रिपोर्ट बनी हो।”</p>\n<p>“और काग़ज़ी सबूत कि ज़मीन की दोबारा पैमाइश रुकवाने में कविता ने ख़ुद दखल दिया था। राजस्व दफ़्तर की चिट्ठी-पत्री मिल जाए तो सबसे अच्छा।”</p>\n<p>एक छोटा विराम।</p>\n<p>“ये तीनों चीज़ें ठीक से सर्टिफाइड दिलवा दीजिए। चार्जशीट मेमो पंद्रह दिन के भीतर तैयार होगा।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले कुछ दिनों में विक्रम ने तीनों दस्तावेज़ जुटाए।</p>\n<p>फोन चोरी की सर्टिफाइड एफआईआर।</p>\n<p>खेतों में लगी आग की रिपोर्ट।</p>\n<p>और राजस्व दफ़्तर के वे काग़ज़ जिनसे कविता के दखल की कड़ी बनती थी।</p>\n<p>आख़िरी सर्टिफाइड कॉपी हाथ में लेकर वह राजस्व दफ़्तर के बाहर खड़ा था।</p>\n<p>गाड़ी कुछ ही दूर थी।</p>\n<p>फिर भी कई क्षण तक उसके पैर उस तरफ नहीं बढ़े।</p>\n<p>उसके भीतर कोई बहुत छोटा, बहुत ज़िद्दी हिस्सा अब भी यह नहीं करना चाहता था।</p>\n<p>कविता ने जो किया था, उसका कोई बचाव नहीं था।</p>\n<p>फोन।</p>\n<p>धमकी।</p>\n<p>दस एकड़ खड़ी गेहूँ की फसल।</p>\n<p>उसके बच्चों के भविष्य तक पहुँचता डर।</p>\n<p>सब सामने था।</p>\n<p>फिर भी—</p>\n<p>वह उस इंसान की जगह खड़ा नहीं होना चाहता था जिसके हाथ से कविता के करियर में जो कुछ बचा था, उस पर आख़िरी औपचारिक चोट पड़े।</p>\n<p>एक पल के लिए उसे एक आँगन याद आया।</p>\n<p>और चाय की वह ट्रे—</p>\n<p>जो किसी लड़की के हाथों में ज़रूरत से बस एक क्षण ज़्यादा ठहरी थी।</p>\n<p>याद उतनी ही देर रही।</p>\n<p>विक्रम ने काग़ज़ कसकर पकड़े और गाड़ी की तरफ चल पड़ा।</p>\n<p>क्योंकि उसके भीतर का वह छोटा हिस्सा चाहे जो चाहता हो, जली हुई दस एकड़ फसल कुछ और कह रही थी।</p>\n<p>उसके बच्चों के भविष्य में उतर आया डर कुछ और कह रहा था।</p>\n<p>और इस बार—</p>\n<p>उस पर पुराने प्रेम से ज़्यादा हक वर्तमान का था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>मीनल ने जो कहा था, वही किया।</p>\n<p>आख़िर जो चार्जशीट तैयार हुई, वह <b>अड़तीस पन्नों</b> की थी।</p>\n<p>तीनों चार्जेज़ को चैप्टर 16 के संबंधित रूल्स से ठीक-ठीक जोड़ा गया था।</p>\n<p>हर सबूत अलग नंबर वाले एनेक्सर में।</p>\n<p>तारीख़।</p>\n<p>स्रोत।</p>\n<p>चेन ऑफ कस्टडी।</p>\n<p>काग़ज़ इस तरह लगाए गए थे कि विक्रम को कम-से-कम अपनी समझ से प्रोसीजर की ऐसी कोई ख़ामी दिखाई नहीं दी जिसे बचाव पक्ष का प्रतिनिधि आसानी से पकड़ सके।</p>\n<p>मीनल ने दो सबसे संभावित ऑब्जेक्शंस पहले ही पहचान ली थीं।</p>\n<p>पहली—</p>\n<p>कि कंप्लेनेंट को यह मामला उठाने का लोकस ही नहीं है।</p>\n<p>दूसरी—</p>\n<p>कि खेत की आग वाली रिपोर्ट डायरेक्ट एविडेंस नहीं, सरकमस्टैंशियल है।</p>\n<p>दोनों के जवाब चार्जशीट में पहले से मौजूद थे।</p>\n<p>और दोनों के लिए उसने हरियाणा कैडर की पिछली डिपार्टमेंटल इन्क्वायरी के ऐसे उदाहरण लगाए थे जहाँ हाई कोर्ट वही ऑब्जेक्शन पहले ही ख़ारिज कर चुका था।</p>\n<p>ड्राफ्ट पुलिस कमिश्नर, गुरुग्राम को भेजा जाना था। शंकर पास बैठा देख रहा था—फाइल को बिना छुए, सिर्फ दोस्त की हैसियत से।</p>\n<p>कविता के रैंक पर नियुक्ति का अधिकार उन्हीं के पास था।</p>\n<p>फिर उसने पन्ने पलटती मीनल की तरफ देखा।</p>\n<p>“तुम सिर्फ कंप्लेंट दर्ज नहीं कर रही।”</p>\n<p>मीनल एनेक्सर्स की सूची दोबारा जाँच रही थी।</p>\n<p>“तो?”</p>\n<p>“उसने अभी चार्जशीट देखी भी नहीं है, और तुम पहले से उसके बचाव की पूरी रणनीति का जवाब दे रही हो।”</p>\n<p>मीनल ने सिर नहीं उठाया।</p>\n<p>“वही तो करना है।”</p>\n<p>उसने अगला एनेक्सर मिलाया।</p>\n<p>“साफ़ रिकॉर्ड वाली एक सेवारत अफसर के ख़िलाफ़ मेजर पेनल्टी का केस है। इन्क्वायरी ऑफिसर उसे तब तक गंभीरता से नहीं लेगा, जब तक फाइल पहले दिन से हर जाँच-परख झेलने लायक न हो।”</p>\n<p>अब उसने शंकर की तरफ देखा।</p>\n<p>“इन्क्वायरी ऑफिसर को प्रोसीजर का एक छोटा-सा बहाना दे दो और फाइल वहीं पड़ी रहेगी। क्योंकि अपने ही विभाग के अफसर के ख़िलाफ़ असुविधाजनक फ़ैसला लेना—संस्थाएँ अक्सर ऐसे फ़ैसले करने से ज़्यादा उन्हें टालना पसंद करती हैं।”</p>\n<p>फिर उसकी नज़र वापस काग़ज़ पर चली गई।</p>\n<p>“मैं ऐसे केस नहीं बनाती जिनमें वह दरवाज़ा खुला रह जाए।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>चार्जशीट पूरी होने के तीन दिन बाद मीनल ने कंप्लेंट दर्ज कर दी।</p>\n<p>बाद में कमिश्नर दफ़्तर से नियुक्त इन्क्वायरी ऑफिसर ने चार्जशीट देखी।</p>\n<p>मीनल तक एक पुराने पेशेवर जानकार के ज़रिए उसकी निजी टिप्पणी पहुँची—</p>\n<p>उस साल उसकी मेज़ पर पहुँचे मेजर-पेनल्टी के मामलों में यह सबसे साफ़ और व्यवस्थित फाइलों में से एक थी।</p>\n<p>फाइल इतनी मजबूत थी कि उसका गंभीर बचाव करने के लिए विभाग को उस अफसर पर काफी संसाधन खर्च करने पड़ते जिसके रिकॉर्ड को अब ठीक से देखने पर बचाने की वजहें बहुत कम रह गई थीं।</p>\n<p>विक्रम पूरी प्रक्रिया को आगे बढ़ते देखता रहा।</p>\n<p>बिना शोर।</p>\n<p>बिना किसी निजी बदले की भाषा के।</p>\n<p>सिर्फ काग़ज़।</p>\n<p>रूल्स।</p>\n<p>तारीख़ें।</p>\n<p>सबूत।</p>\n<p>और ऐसी तैयारी जिसमें ग़लती के लिए लगभग कोई जगह नहीं छोड़ी गई थी।</p>\n<p>तभी उसे समझ आया कि शंकर ने मीनल का नाम इतनी निश्चितता से क्यों लिया था।</p>\n<p>पुणे में उन दोनों के बीच जो भी रहा हो—</p>\n<p>और वर्षों बाद भी जो कुछ पूरी तरह ख़त्म न हुआ हो—</p>\n<p>वह इस समय महत्वपूर्ण नहीं था।</p>\n<p>महत्वपूर्ण यह था कि मीनल कश्यप सिर्फ वह नहीं थी जिससे शंकर ने कभी प्रेम किया था।</p>\n<p>वह अपने काम में असाधारण थी।</p>\n<p>इतनी कि कविता के वर्षों से बने करियर को गिराने के लिए उसे आवाज़ ऊँची करने, कोई चाल चलने या रूल से एक कदम बाहर जाने की ज़रूरत नहीं पड़ी।</p>\n<p>उसने बस हर चीज़ ठीक जगह रख दी।</p>\n<p>और कानून को अपना काम करने दिया।</p>\n<p>जंगल की आग को फैलने से रोकना हो, तो उसके चारों ओर एक रेखा खींची जाती है—सूखी, सीधी, बिना किसी दरार की।</p>\n<p>मीनल ने वह रेखा काग़ज़ से खींच दी थी।</p>"}, {"chapter": 49, "title": "अध्याय 45 — जान जाओगे", "content": "<h1>अध्याय 45 — जान जाओगे</h1>\n<p>कामथ का बुलावा हमेशा की तरह आया—</p>\n<p>एक लाइन।</p>\n<p>कोई वजह नहीं।</p>\n<p>सिर्फ एक वक्त और एक जगह।</p>\n<p>दूसरी तरफ क्या इंतज़ार कर रहा है, इसका कोई अंदाज़ा नहीं।</p>\n<p>विक्रम तय समय पर पहुँचा तो कामथ ने बिना भूमिका बाँधे एक पतली-सी फाइल उसकी तरफ सरका दी।</p>\n<p>“इस बार का काम अब तक तुम्हारे किए हर काम से बड़ा है।”</p>\n<p>विक्रम ने फाइल पर हाथ रखा, खोली नहीं।</p>\n<p>कामथ आगे बोला—</p>\n<p>“तुम एक ऐसे एसेट के साथ काम करोगे जो पिछले तीन साल से टारगेट के नेटवर्क के भीतर है।”</p>\n<p>एक क्षण का विराम।</p>\n<p>“मीरा आनंद।”</p>\n<p>फिर उसने विक्रम को देखा।</p>\n<p>“तुम उसे जानते हो।”</p>\n<p>विक्रम की भौंह हल्की-सी सिकुड़ी।</p>\n<p>“मैं इस नाम के किसी इंसान को नहीं जानता।”</p>\n<p>कामथ का चेहरा ज़रा-सा बदल गया।</p>\n<p>बहुत थोड़ा।</p>\n<p>लगभग इतना कि कोई और देख भी न पाता।</p>\n<p>फिर इतने वर्षों में पहली बार विक्रम ने उसे सचमुच मुस्कराते देखा—छोटी-सी, निजी मुस्कान; जैसे सामने बैठा इंसान अभी यह जानने वाला हो कि वह कितनी बुरी तरह ग़लत है।</p>\n<p>“जान जाओगे।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>चार मिनट बाद ब्रीफिंग रूम का दरवाज़ा खुला।</p>\n<p>वर्षों की ट्रेनिंग ने विक्रम को किसी कमरे में पूरी तरह दाखिल होने से पहले उसे पढ़ना सिखा दिया था।</p>\n<p>अब वह कोशिश करके ऐसा नहीं करता था।</p>\n<p>शरीर ख़ुद करता था।</p>\n<p>पहले उसने भीतर आती लड़की का कद देखा।</p>\n<p>फिर चलने का ढंग।</p>\n<p>सीधी।</p>\n<p>बिना जल्दबाज़ी।</p>\n<p>उस आत्मविश्वास के साथ जो उस इंसान में आता है जिसे बहुत पहले दूसरों को यह साबित करने की ज़रूरत ख़त्म हो चुकी हो कि वह उस जगह का हकदार है जहाँ खड़ा है।</p>\n<p>फिर विक्रम ने उसका चेहरा देखा।</p>\n<p>और उसके भीतर सब कुछ एक पल के लिए बिल्कुल स्थिर हो गया।</p>\n<p>कमरे में कुछ नहीं हिला।</p>\n<p>पर भीतर एक पूरी ज़िंदगी एक साँस में घूम गई—</p>\n<p>नैना की हँसी।</p>\n<p>चाय के दो प्याले।</p>\n<p>गुलमोहर की वह छाया।</p>\n<p>बरसों से बंद दराज़ को किसी ने एक इंच खींच दिया था।</p>\n<p>नहीं।</p>\n<p>यह नैना की बहन नहीं हो सकती।</p>\n<p>दुनिया का कोई हिसाब ऐसा नहीं था जिसमें नैना की बहन इस कमरे में हो सकती थी।</p>\n<p>सुनैना दरवाज़े के भीतर आकर रुकी।</p>\n<p>उसके साथ अंदर आया पूरा संयम एक क्षण के लिए टूट गया।</p>\n<p>“ओह…”</p>\n<p>आँखें फैल गईं।</p>\n<p>“तुम।”</p>\n<p>फिर जैसे वर्षों का फ़ासला एक ही साँस में पहचान बनकर लौटा।</p>\n<p>“विक्रम। इतने साल बाद।”</p>\n<p>“तुम…”</p>\n<p>शब्द उससे सोचने से पहले निकला।</p>\n<p>लेकिन ख़ुद को सँभालने में सुनैना विक्रम से तेज़ निकली।</p>\n<p>चेहरे पर वही ठहराव वापस आ गया जिसके साथ वह कमरे में दाखिल हुई थी।</p>\n<p>“हैलो, विक्रम।”</p>\n<p>विक्रम एक पूरा सेकंड ज़रूरत से ज़्यादा जड़ बैठा रहा।</p>\n<p>किसी ऑपरेटिव के लिए एक सेकंड भी बहुत होता है।</p>\n<p>“सुनैना।”</p>\n<p>उसकी आवाज़ तुरंत बदल गई।</p>\n<p>सपाट।</p>\n<p>सटीक।</p>\n<p>ऐसी आवाज़ विक्रम ने उससे पहले कभी नहीं सुनी थी।</p>\n<p>“इस कमरे में वह नाम मौजूद नहीं है।”</p>\n<p>उसने उसकी आँखों में देखते हुए कहा—</p>\n<p>“यहाँ मैं <b>मीरा आनंद</b> हूँ।”</p>\n<p>फिर बिना किसी दिखावे के—</p>\n<p>“तीन साल से मीरा आनंद हूँ। इस कमरे से कहीं ज़्यादा ख़तरनाक जगहों में इसी नाम से आती-जाती रही हूँ। और चाहूँगी कि आगे भी ऐसा ही रहे।”</p>\n<p>“तीन साल?”</p>\n<p>विक्रम अब भी सामने खड़ी सच्चाई को पुराने परिचय के साथ जोड़ने की कोशिश कर रहा था।</p>\n<p>“तुम ये सब… इतने समय से कर रही हो?”</p>\n<p>“और मुझे कभी पता नहीं चला।”</p>\n<p>“पता चलना भी नहीं था।”</p>\n<p>उसने अपनी फाइल मेज़ पर रखी।</p>\n<p>हर हरकत नपी हुई।</p>\n<p>“किसी को पता नहीं चलना था। इस काम का पूरा मतलब ही यही है।”</p>\n<p>उसकी आँखों में एक क्षण के लिए हल्की चमक आई।</p>\n<p>“कामथ ने तुम्हें पहले न बताकर काफी मज़ा लिया होगा।”</p>\n<p>विक्रम ने अपनी हैरानी पर पुरानी ट्रेनिंग की परत वापस चढ़ाई।</p>\n<p>“मुझे भी यही लगता है।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सुनैना—या इस कमरे में मीरा—कुछ क्षण चुप रही।</p>\n<p>फिर बोली—</p>\n<p>“एक बात पहले साफ़ कर लेते हैं।”</p>\n<p>स्वर अब भी पेशेवर था, लेकिन उसके नीचे कोई पुरानी बात आकर खड़ी हो गई थी।</p>\n<p>“तुम्हारे साथ काम करना मेरे लिए आसान है, ऐसा दिखावा नहीं करूँगी।”</p>\n<p>विक्रम शांत रहा।</p>\n<p>“जो कुछ हुआ था, मैं भूली नहीं हूँ, विक्रम।”</p>\n<p>“वे साल भी नहीं।”</p>\n<p>“मेरी बहन किससे गुज़री, वह भी नहीं।”</p>\n<p>और फिर सबसे सीधी बात—</p>\n<p>“और यह भी नहीं कि आख़िर में तुम वह इंसान नहीं बने जिससे उसकी शादी हो सकती थी।”</p>\n<p>विक्रम की आँखें उससे नहीं हटीं।</p>\n<p>सुनैना ने बात को वहीं रखा जहाँ उसका मतलब था।</p>\n<p>“मैं यह सब आज पुरानी कहानी फिर खोलने के लिए नहीं कह रही।”</p>\n<p>“फिर?”</p>\n<p>“इसलिए कह रही हूँ ताकि तुम्हें ठीक-ठीक पता रहे कि तुम्हारे साथ पेशेवर तौर पर काम करने के लिए मैं अपने भीतर क्या अलग रख रही हूँ।”</p>\n<p>“समझता हूँ।”</p>\n<p>सुनैना की नज़र कुछ पल उसके चेहरे पर ठहरी रही।</p>\n<p>“सच में?”</p>\n<p>उस एक क्षण में कोई पुरानी, अब तक अधूरी बात उसकी आँखों में कौंध गई।</p>\n<p>फिर मीरा आनंद वापस आ गई।</p>\n<p>“अच्छा है।”</p>\n<p>“तो हम दोनों यह दिखावा नहीं करेंगे कि हमारे बीच वह सब कभी था ही नहीं।”</p>\n<p>उसने फाइल की तरफ देखा।</p>\n<p>“और अब काम करेंगे।”</p>\n<p>विक्रम ने हल्का-सा सिर हिलाया।</p>\n<p>फिर भी एक सवाल उससे निकलने लगा—</p>\n<p>“क्या नैना—”</p>\n<p>“नहीं।”</p>\n<p>शब्द ने सवाल पूरा होने से पहले ही उसे काट दिया।</p>\n<p>इस बार आवाज़ में कोई गुंजाइश नहीं थी।</p>\n<p>“उसे नहीं पता मैं क्या करती हूँ।”</p>\n<p>फिर और दृढ़ स्वर में—</p>\n<p>“और अगर यह मेरे हाथ में रहा तो उसे कभी पता नहीं चलेगा।”</p>\n<p>उसका चेहरा अब सख़्त हो गया था।</p>\n<p>लेकिन वह सख़्ती विक्रम के लिए नहीं थी।</p>\n<p>वह सुरक्षा की सख़्ती थी।</p>\n<p>विक्रम ने उसे पहचाना।</p>\n<p>वर्षों पहले गुरुग्राम के एक फ्लैट में उसने इसी लड़की के चेहरे पर अपनी बहन के लिए यही तीखापन देखा था।</p>\n<p>समय बदल गया था।</p>\n<p>वह नहीं।</p>\n<p>“बहुत पहले तय कर लिया था,” सुनैना ने कहा, “इस काम की जो भी कीमत होगी, मैं दूँगी।”</p>\n<p>एक साँस।</p>\n<p>“लेकिन इसकी कीमत नैना तक कभी नहीं पहुँचेगी।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>सुनैना अभी ख़त्म नहीं हुई थी।</p>\n<p>“और एक बात।”</p>\n<p>अब उसने उसकी नज़र सीधे थाम ली।</p>\n<p>“इस पूरे काम में—चाहे जितना समय लगे—तुम मुझसे उसके बारे में दोबारा नहीं पूछोगे।”</p>\n<p>“एक बार भी नहीं।”</p>\n<p>विक्रम के चेहरे पर कोई बदलाव नहीं आया।</p>\n<p>“मैं तुम्हारे साथ काम करूँगी क्योंकि काम की ज़रूरत है।”</p>\n<p>उसकी आवाज़ धीमी थी, लेकिन हर शब्द अपनी जगह साफ़ बैठ रहा था।</p>\n<p>“इसलिए नहीं कि हमारे बीच कभी चुप्पी असहज हो जाए और मैं हर बार तुम्हारे लिए अपनी बहन की ज़िंदगी में एक खिड़की खोल दूँ।”</p>\n<p>कुछ पल दोनों के बीच सिर्फ कमरा था।</p>\n<p>फिर विक्रम ने बहुत धीमे कहा—</p>\n<p>“समझ गया।”</p>\n<p>और इस बार वह सचमुच समझ गया था।</p>\n<p>उसने सामने बैठी सुनैना को फिर देखा।</p>\n<p>पहली बार बिना नैना के रिश्ते से उसकी पहचान तय किए।</p>\n<p>यह सिर्फ नैना की छोटी बहन नहीं थी।</p>\n<p>न वह लड़की जिससे वर्षों पहले फोन पर उसकी कुछ बातचीत हुई थी।</p>\n<p>उसके सामने एक ऐसी लड़की बैठी थी जिसने दुनिया की नज़र से बचाकर अपनी एक पूरी दूसरी ज़िंदगी खड़ी कर ली थी—</p>\n<p>पहली ज़िंदगी के बिल्कुल साथ-साथ।</p>\n<p>इतने समय से वह किसी और नाम से ऐसे कमरों में जाती रही थी जहाँ एक ग़लत शब्द, एक ग़लत नज़र, एक ग़लत ठहराव की कीमत बहुत बड़ी हो सकती थी।</p>\n<p>और उसके अपने घरवालों तक को इसकी ख़बर नहीं थी।</p>\n<p>विक्रम ने उसे उसके पूरे आकार में देखा।</p>\n<p><b>सुनैना—अपने नाम से।</b></p>\n<p>नैना की परछाईं बनकर नहीं।</p>\n<p>किसी पुरानी कहानी के सहायक किरदार की तरह नहीं।</p>\n<p>अपने फ़ैसलों, अपने जोखिम और अपने रहस्यों के साथ।</p>\n<p>एक मुकम्मल ज़िंदगी।</p>\n<p>जिसके बारे में वह कुछ नहीं जानता था।</p>\n<p>विक्रम ने फाइल की तरफ हाथ बढ़ाया।</p>\n<p>“तो काम शुरू करें।”</p>\n<p>“बिल्कुल।”</p>\n<p>उसकी आँखों के पीछे पुरानी सावधानी अब भी थी।</p>\n<p>बीती हुई बातों का तनाव भी पूरी तरह गया नहीं था।</p>\n<p>लेकिन उसने उन सबको वहीं रहने दिया जहाँ वे थे और फाइल अपनी तरफ खींच ली।</p>\n<p>मीरा आनंद फिर पूरी तरह सामने थी।</p>\n<p>दोनों के बीच पुराना इतिहास मौजूद था।</p>\n<p>मगर मेज़ पर अब काम रखा था।</p>\n<p>और फिलहाल—</p>\n<p>उसी का हक पहले था।</p>"}, {"chapter": 50, "title": "अध्याय 46 — सावधानी ज़िंदा रखती है", "content": "<h1>अध्याय 46 — सावधानी ज़िंदा रखती है</h1>\n<p>उस ब्रीफिंग के दो दिन बाद, जिसमें सुनैना पहली बार उसके सामने मीरा आनंद बनकर आई थी, विक्रम ने उसे सिक्योर लाइन पर फोन किया।</p>\n<p>दो घंटे बाद मिलने की जगह तय हुई—</p>\n<p>ऐसी जगह जहाँ उन दोनों में से किसी के होने की कोई खास वजह दिखाई न दे।</p>\n<p>विक्रम पहुँचा तो वह पहले से मौजूद थी।</p>\n<p>एक मामूली-सा कैफे।</p>\n<p>न बहुत भीड़।</p>\n<p>न इतना खाली कि दो लोग याद रह जाएँ।</p>\n<p>ठीक वैसी जगहें जिन्हें उनका काम पसंद करता था।</p>\n<p>विक्रम बैठा तो सुनैना ने उसे गौर से देखा।</p>\n<p>वर्षों पहले फोन पर अपनी बहन बनकर उसे छेड़ने वाली लड़की की तुलना में अब उसका चेहरा सख़्त हो आया था।</p>\n<p>“थके हुए लग रहे हो।”</p>\n<p>“हूँ।”</p>\n<p>विक्रम कुर्सी पर पीछे हुआ।</p>\n<p>“पिछले कुछ हफ्ते लंबे रहे हैं। एक से ज़्यादा मोर्चों पर।”</p>\n<p>“तो कम-से-कम ये वाला थोड़ा आसान कर लेते हैं।”</p>\n<p>सुनैना की आवाज़ तुरंत बदल गई।</p>\n<p>वही सपाट, सावधान लहजा जो विक्रम अब समझ चुका था—</p>\n<p>यह मीरा आनंद की आवाज़ थी।</p>\n<p>“देवराज शर्मा का भाई।”</p>\n<p>“आशीष?”</p>\n<p>“हाँ। असल में सब कुछ वही चला रहा है।”</p>\n<p>उसने सामने रखे कप को छुआ तक नहीं।</p>\n<p>“मंत्री नहीं। मुझे सच में लगता है देवराज को अंदाज़ा भी नहीं कि उसके अपने भाई ने क्या खड़ा कर रखा है।”</p>\n<p>विक्रम शांत रहा।</p>\n<p>“पिछले तीन साल में आशीष ने ऐसा नेटवर्क बनाया है जिसकी पहुँच उन जगहों तक है जिनसे लोगों को जितना डरना चाहिए, फिलहाल वे उसका आधा भी नहीं समझते।”</p>\n<p>“कैसा नेटवर्क?”</p>\n<p>“विदेशी पैसा।”</p>\n<p>सुनैना ने कहा।</p>\n<p>“पैसा पहले शेल कंपनियों के ज़रिए आता है। काग़ज़ पर वे बिल्कुल मामूली सांस्कृतिक आदान-प्रदान वाली संस्थाएँ दिखती हैं। वहाँ से होल्डिंग कंपनियों की दूसरी परत में जाता है। जब तक पैसा भारत की ज़मीन छूता है, इतना साफ़ दिखाई देता है कि कोई सामान्य ऑडिट उसे देखकर आगे बढ़ जाएगा।”</p>\n<p>“और यहाँ आने के बाद?”</p>\n<p>“हजारों सोशल मीडिया चैनल।”</p>\n<p>“हजारों?”</p>\n<p>“ज़्यादातर छोटे। अलग-अलग देखो तो किसी में कुछ खास नहीं लगेगा।”</p>\n<p>वह थोड़ा आगे झुकी।</p>\n<p>“लेकिन पूरे नेटवर्क को एक साथ देखो तो पैटर्न दिखाई देता है। सबको अलग-अलग समय पर, अलग-अलग संस्थाओं को अस्थिर करने के लिए एक साथ चलाया जाता है।”</p>\n<p>“जैसे?”</p>\n<p>“कहीं कोई कोर्ट केस।”</p>\n<p>“कहीं किसी राज्य का चुनाव।”</p>\n<p>“जहाँ जो उसके बड़े मकसद के काम आए।”</p>\n<p>विक्रम ने कुछ क्षण उसे देखा।</p>\n<p>“और बड़ा मकसद?”</p>\n<p>सुनैना का चेहरा कठोर हो गया।</p>\n<p>“आख़िर में?”</p>\n<p>“ताकत।”</p>\n<p>“अक्सर बात वहीं पहुँचती है।”</p>\n<p>उसने धीमे लेकिन स्पष्ट स्वर में कहा—</p>\n<p>“आशीष ऐसी ताकत चाहता है जिसे पाने के लिए किसी ने उसे चुना नहीं। और उसे लगता है वहाँ पहुँचने का सबसे तेज़ रास्ता ऐसी अराजकता पैदा करना है जिसे वह ख़ुद पर्दे के पीछे तैयार करे और सामने खड़े होकर उससे इनकार कर सके।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“काफी संस्थाओं को कमज़ोर कर दो। सही लोगों की साख ख़त्म कर दो। इतनी अफरा-तफरी मचा दो कि आख़िर कोई तुम्हीं से कहे—आओ, व्यवस्था वापस लाओ।”</p>\n<p>एक छोटा विराम।</p>\n<p>“तुम्हारी शर्तों पर।”</p>\n<p>“बिना किसी को जवाब दिए।”</p>\n<p>तभी विक्रम के भीतर एक और बात पूरी तरह जुड़ी।</p>\n<p>“तुम पत्रकार हो।”</p>\n<p>सुनैना की नज़र उठी।</p>\n<p>“मीरा आनंद।”</p>\n<p>“वह तुम हो।”</p>\n<p>“मेरा कवर है।”</p>\n<p>उसके चेहरे पर थकी हुई, मगर असली मुस्कान आई।</p>\n<p>“तीन साल से।”</p>\n<p>फिर जैसे कोई बहुत पुरानी बात उसे याद आई।</p>\n<p>“नैना के फ्लैट में उस दिन मैंने तुमसे कहा था न—जब मैं ठीक से वापस आऊँगी तो देखना चाहूँगी तुम्हारी कहानी कहाँ तक पहुँची।”</p>\n<p>मुस्कान में हल्की विडंबना घुल गई।</p>\n<p>“मुझे नहीं लगता हममें से किसी ने सोचा था कि दोबारा मिलना इतना उलझा हुआ होगा।”</p>\n<p>“मुझसे क्या चाहिए?”</p>\n<p>“कुछ खास लेन-देन की पुष्टि। पैसे को मैं एक जगह तक ट्रेस कर सकती हूँ। उसके आगे मेरे रास्ते ख़त्म हो जाते हैं।”</p>\n<p>“और मेरे नहीं।”</p>\n<p>“इसीलिए तुम यहाँ हो।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“ठीक है।”</p>\n<p>“शुरू करते हैं।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस रात घर लौटते हुए विक्रम ने ज़रूरत से लंबा रास्ता लिया।</p>\n<p>एक और ऑपरेशन।</p>\n<p>एक और राज़।</p>\n<p>श्रद्धा से छिपी हुई बाकी बातों के ऊपर रखा गया एक और सच।</p>\n<p>अगर कुछ ग़लत हुआ—</p>\n<p>अगर आशीष के लोग पुष्टि की उस कड़ी को पीछे तक जोड़ते हुए उस मेजर तक पहुँच गए जो चुपचाप <b>रॉ</b> के लिए काम कर रहा था—</p>\n<p>तो ख़तरा सिर्फ उसके करियर या उसकी जान तक नहीं रहता।</p>\n<p>श्रद्धा।</p>\n<p>अदिति।</p>\n<p>अर्जुन।</p>\n<p>वह पूरी साधारण ज़िंदगी जिसे उसने इतने वर्षों की चुप्पियों के बीच बड़ी मुश्किल से बनाया था।</p>\n<p>घर पहुँचकर उसने श्रद्धा से कुछ नहीं कहा।</p>\n<p>हर शाम की तरह बेटी के माथे पर प्यार से होंठ रखे, उसे गुडनाइट कहा।</p>\n<p>और उसी साधारण-से क्षण में उसे महसूस हुआ कि उसकी पत्नी जिस इंसान को अपना पति समझती है और वह इंसान वास्तव में जो करता है—</p>\n<p>उन दोनों के बीच की दूरी चुपचाप एक इंच और बढ़ गई है।</p>\n<p>एक और इंच—</p>\n<p>जिसका वज़न उसे अकेले उठाना था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले कुछ हफ्तों में उनकी मुलाक़ातों की अपनी लय बन गई।</p>\n<p>हर बार अलग कैफे।</p>\n<p>अलग वक्त।</p>\n<p>दो ऐसे लोगों की नपी हुई चाल, जिन्हें ट्रेनिंग ने सिखाया था कि एक ढर्रे पर चलना भी ख़तरा हो सकता है।</p>\n<p>विक्रम जो वेरिफाई कर सकता था, लेकर आता।</p>\n<p>सुनैना उसे उस बड़े ढाँचे में लगाती जिसे फिलहाल पूरा सिर्फ वही देख पा रही थी।</p>\n<p>धीरे-धीरे नेटवर्क की शक्ल उभरने लगी—</p>\n<p>जैसे डार्करूम में कोई तस्वीर पहले धुँधली-सी जन्म ले, फिर एक-एक रेखा सामने आए और अचानक वही चीज़, जो कुछ क्षण पहले सिर्फ धब्बे थी, साफ़ चेहरा बन जाए।</p>\n<p>इन मुलाक़ातों में सुनैना ने विक्रम के बारे में कुछ ऐसी बातें देखीं जिनकी उसने उम्मीद नहीं की थी।</p>\n<p>वह हर जानकारी देने से पहले दो बार वेरिफाई करता।</p>\n<p>सिर्फ उपयोगी दिखाई देने के लिए कभी आधी-पक्की लीड आगे नहीं बढ़ाता।</p>\n<p>सुनैना उसके सोर्सेज को जितनी बार, जितनी बारीकी से क्रॉस-क्वेश्चन करती, वह कभी नाराज़ नहीं होता।</p>\n<p>उसमें एक ठहरी हुई, लगभग बेरंग-सी काबिलियत थी।</p>\n<p>न दिखावा।</p>\n<p>न अपने काम का शोर।</p>\n<p>और यह उस आकर्षण से बिल्कुल अलग थी जिसकी उसने उस इंसान से उम्मीद की थी जिसे उसकी बहन ने कभी इतना गहरा प्रेम किया था।</p>\n<p>कई मुलाक़ातों के बाद एक दिन सुनैना ने कहा—</p>\n<p>“तुम बहुत सावधान हो।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>उसकी आवाज़ में हल्का आश्चर्य था।</p>\n<p>“मुझे इसकी उम्मीद नहीं थी।”</p>\n<p>“क्या उम्मीद थी?”</p>\n<p>सुनैना ने सोचा।</p>\n<p>“पता नहीं।”</p>\n<p>फिर—</p>\n<p>“किसी ज़्यादा लाउड इंसान की।”</p>\n<p>विक्रम के चेहरे पर बहुत हल्की मुस्कान आई।</p>\n<p>“सावधानी लोगों को ज़िंदा रखती है।”</p>\n<p>कुछ क्षण बाद वह फिर बोला—</p>\n<p>“एक से ज़्यादा बार मुश्किल तरीके से सीखा है।”</p>\n<p>सुनैना ने नहीं पूछा कैसे।</p>\n<p>विक्रम ने नहीं बताया।</p>\n<p>लेकिन उस छोटे-से संवाद के बाद दोनों के बीच कुछ अपनी जगह से थोड़ा सरक गया।</p>\n<p>बहुत ज़्यादा नहीं।</p>\n<p>बस इतना कि पुराने संदेह के पास अब एक नया शब्द आकर बैठ गया था—</p>\n<p><b>सम्मान।</b></p>\n<p>दोनों में से किसी ने उसे नाम नहीं दिया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>ऑपरेशन लगभग पुरानी दिल्ली में टूट गया।</p>\n<p>सदर बाज़ार के पास थोक कपड़े की दुकानों की एक कतार के पीछे छिपा पुराना गोदाम।</p>\n<p>सुनैना का एक सोर्स लगभग एक साल से उसके साथ था—</p>\n<p>शेल स्ट्रक्चर्स में से एक का मिड-लेवल अकाउंटेंट।</p>\n<p>कम-से-कम वह यही मानती रही थी।</p>\n<p>असल में आशीष के लोग उसे महीनों पहले अपनी तरफ कर चुके थे।</p>\n<p>चाल बहुत साफ़ थी।</p>\n<p>इतने समय तक उसे सच दिया गया कि जब आख़िरी झूठ आए तो वह भी सच जैसा लगे।</p>\n<p>उसने सुनैना को बताया कि अंतिम ज़रूरी डॉक्यूमेंट उसके पास है।</p>\n<p>प्राइवेसी के लिए वेयरहाउस में मिलने पर ज़ोर दिया।</p>\n<p>और सुनैना—</p>\n<p>अंत के इतना करीब पहुँच चुकी थी कि इस बार उसने उतना धीमा होकर नहीं सोचा जितना उसे सोचना चाहिए था।</p>\n<p>उसकी गाड़ी गोदाम के पीछे की संकरी गली में पूरी तरह रुकी भी नहीं थी कि चार हथियारबंद लोग उसके चारों ओर आ गए।</p>\n<p>बहुत तेज़ी से।</p>\n<p>हथियार इतने साफ़ दिखाई दे रहे थे कि वहीं विरोध करना बेकार था।</p>\n<p>लेकिन उसे गाड़ी से बाहर खींचे जाने से पहले कुछ सेकंड मिले।</p>\n<p>उतने काफी थे।</p>\n<p>उसकी उँगली फोन के इमरजेंसी सिग्नल तक पहुँची।</p>\n<p>लोकेशन।</p>\n<p>डिस्ट्रेस कोड।</p>\n<p>एक बटन।</p>\n<p>बिना स्क्रीन देखे।</p>\n<p>इतनी बार ड्रिल किया हुआ कि दिमाग से पहले हाथ को रास्ता याद था।</p>\n<p>फिर वे उसे भीतर ले गए।</p>\n<p>गोदाम के पीछे एक बंद स्टोररूम।</p>\n<p>पुरानी जूट और डीज़ल की मिली-जुली गंध।</p>\n<p>हाथ बाँध दिए गए।</p>\n<p>दरवाज़ा बंद हुआ।</p>\n<p>दो लोग बाहर रह गए।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अलर्ट विक्रम तक कुछ ही मिनट में पहुँचा।</p>\n<p>साथ में उसकी आख़िरी कन्फर्म्ड लोकेशन।</p>\n<p>उसने ऑथराइजेशन का इंतज़ार नहीं किया।</p>\n<p>सोचने के लिए कुछ बचा भी नहीं था।</p>\n<p>पुरानी ट्रेनिंग ने शरीर अपने हाथ में ले लिया।</p>\n<p>वह ख़ुद गाड़ी चलाकर वहाँ पहुँचा।</p>\n<p>सिग्नल सही था।</p>\n<p>स्टोररूम के बाहर दो लोग।</p>\n<p>अंदर सुनैना।</p>\n<p>बाहर के दोनों से निपटने में उसे कुछ सेकंड लगे।</p>\n<p>तेज़।</p>\n<p>बिना किसी बेकार हरकत के।</p>\n<p>शरीर को अब भी वे चीज़ें याद थीं जिन्हें करने के लिए दिमाग की अनुमति ज़रूरी नहीं रह गई थी।</p>\n<p>अगले ही पल उसने दरवाज़ा खोला।</p>\n<p>सुनैना भीतर थी।</p>\n<p>हिली हुई।</p>\n<p>लेकिन घायल नहीं।</p>\n<p>विक्रम ने उसके हाथ खोल दिए।</p>\n<p>सुनैना की साँस अभी बराबर नहीं हुई थी।</p>\n<p>उसने दरवाज़े के पास पड़े दोनों की तरफ देखा।</p>\n<p>“मार दिया?”</p>\n<p>“नहीं।”</p>\n<p>विक्रम ने बिना पीछे देखे कहा।</p>\n<p>“बस बेहोश किया है।”</p>\n<p>फिर उसके हाथ की आख़िरी गाँठ खोली।</p>\n<p>“इनके पास जो जानकारी है, वह हमें चाहिए।”</p>\n<p>एक क्षण रुककर—</p>\n<p>“और ज़मीन पर बेहोश पड़ा इंसान जितने सवाल खड़े करता है, लाश उससे कहीं ज़्यादा करती है।”</p>\n<p>बाकी सब बाद की बात थी।</p>\n<p>उस पल बस इतना मायने रखता था—</p>\n<p>वह उसे ज़िंदा वहाँ से निकाल लाया था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस रात वह उसे उसके फ्लैट पर वापस नहीं ले गया।</p>\n<p>न किसी ऐसे रास्ते पर जहाँ उसका आना-जाना पहले से जाना जाता हो।</p>\n<p>उसकी लोकेशन उजागर हो चुकी थी।</p>\n<p>कवर कितना बचा था, इसका अंदाज़ा नहीं था।</p>\n<p>और विक्रम उसकी जान को अनुमान पर नहीं छोड़ने वाला था।</p>\n<p>कामथ के नेटवर्क का एक सेफ हाउस था—</p>\n<p>बंद पड़ी प्रिंटिंग शॉप के ऊपर छोटा-सा फ्लैट।</p>\n<p>कम फर्नीचर।</p>\n<p>कोई पहचान नहीं।</p>\n<p>शहर के ऐसे हिस्से में जहाँ उन दोनों का कोई काम नहीं होना चाहिए था।</p>\n<p>वह उसे वहीं ले गया।</p>\n<p>बाकी रात ख़ुद भी वहीं रहा।</p>\n<p>सीढ़ियों से आने वाली हर आवाज़ पर कान लगाए।</p>\n<p>सुबह होने तक।</p>\n<p>कामथ के लोग पहुँचे तो आगे की स्थिति का जायज़ा लिया गया और सुनैना को दूसरी, ज़्यादा सुरक्षित जगह ले जाने की तैयारी हुई।</p>\n<p>वह संकरे बिस्तर के किनारे बैठी थी।</p>\n<p>एड्रेनलिन उतर रहा था।</p>\n<p>हाथ अब भी पूरी तरह स्थिर नहीं थे।</p>\n<p>उसने विक्रम की तरफ देखा।</p>\n<p>“तुम्हें अकेले नहीं आना चाहिए था।”</p>\n<p>विक्रम ने जवाब देने में एक क्षण भी नहीं लिया।</p>\n<p>“तुम्हें भी उस गोदाम में अकेले नहीं जाना चाहिए था।”</p>\n<p>फिर—</p>\n<p>“हिसाब बराबर।”</p>\n<p>सुनैना उसे कुछ देर देखती रही।</p>\n<p>उस नज़र में कृतज्ञता थी।</p>\n<p>लेकिन सिर्फ वही नहीं।</p>\n<p>कुछ और भी था—</p>\n<p>जैसे वह समझ रही हो कि आज की रात ने उसके भीतर विक्रम के नाम के सामने कोई पुराना हिसाब मिटाया नहीं है, लेकिन एक नया हिसाब ज़रूर खोल दिया है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगली रात सुनैना ने नैना को फोन किया।</p>\n<p>तब तक कामथ के लोग उसे नए सुरक्षित ठिकाने में पहुँचा चुके थे।</p>\n<p>उस रात की सबसे बुरी घड़ी कम-से-कम पीछे थी।</p>\n<p>आमतौर पर वह नैना से वीकेंड पर बात करती थी।</p>\n<p>एक ऐसी ज़िंदगी में, जिसका बाकी कोई तय शेड्यूल नहीं था, यह एक स्थायी जगह थी।</p>\n<p>लेकिन इस बार वीकेंड तक इंतज़ार नहीं हो सकता था।</p>\n<p>वर्षों से उनकी बातों की अपनी आदत थी।</p>\n<p>नैना ज़्यादा बोलती।</p>\n<p>अपनी ज़िंदगी की साधारण बातें।</p>\n<p>घर।</p>\n<p>बच्चे।</p>\n<p>दिनभर की छोटी परेशानियाँ।</p>\n<p>और सुनैना सुनती।</p>\n<p>बीच-बीच में वही छोटे सवाल पूछती जो बताते थे कि सामने वाला सिर्फ आवाज़ नहीं सुन रहा—</p>\n<p>वह पूरी ज़िंदगी याद रख रहा है।</p>\n<p>उस रात नैना अपने बेटे की शिकायत कर रही थी।</p>\n<p>होमवर्क ख़त्म करने से उसका फिर झगड़ा हुआ था।</p>\n<p>इतनी मामूली बात।</p>\n<p>इतनी सामान्य।</p>\n<p>“कहता है, होमवर्क बाद में कर लूँगा। बाद में, सुनैना। इतना-सा है और अभी से ‘बाद में’ सीख गया है।”</p>\n<p>“तुम पर गया है।”</p>\n<p>“मुझ पर? मैं तो हर काम समय से करती हूँ।”</p>\n<p>उसकी हँसी हल्की थी। थकी हुई।</p>\n<p>“और घर में सब?”</p>\n<p>“सब हैं।”</p>\n<p>सुनैना ने एक पल रुककर पूछा—</p>\n<p>“वह भी?”</p>\n<p>“वह भी।”</p>\n<p>नैना ने उससे आगे कुछ नहीं कहा।</p>\n<p>सुनैना ने पूछा भी नहीं।</p>\n<p>और सुनैना फोन कान से लगाए उस कृतज्ञता के साथ बैठी थी जिसे वह अपनी बहन से कह नहीं सकती थी।</p>\n<p>एक दिन पहले जिस इंसान ने बंद वेयरहाउस में घुसकर दो हथियारबंद लोगों को उतने समय में ज़मीन पर पहुँचा दिया था जितने में ज़्यादातर लोग यह तय करते कि उन्हें डरना चाहिए या नहीं—</p>\n<p>शायद उसी ने उसकी जान बचाई थी।</p>\n<p>और वह इसके लिए कभी ठीक से धन्यवाद भी नहीं माँगता।</p>\n<p>एक क्षण के लिए उसके भीतर बहुत तेज़ इच्छा उठी—</p>\n<p>नैना को बता दे।</p>\n<p><b>मैं उससे मिली, नैना।</b></p>\n<p><b>विक्रम से।</b></p>\n<p><b>वह बिल्कुल वैसा ही है जैसा तुम हमेशा कहती थीं।</b></p>\n<p><b>शायद उससे भी ज़्यादा।</b></p>\n<p>शब्द भीतर तक आए।</p>\n<p>बाहर नहीं निकले।</p>\n<p>नैना ने अपने लिए जो भी शांति बनाई थी, सुनैना को वह कितनी भी अधूरी क्यों न लगती हो, वह उसकी अपनी थी।</p>\n<p>उसे किसी ऐसे सच से हिलाने का अधिकार सुनैना का नहीं था, जो नैना की ज़िंदगी को और उलझाने के अलावा कुछ नहीं करता।</p>\n<p>सुनैना इतने वर्षों में यह सीख चुकी थी—</p>\n<p>कुछ मेहरबानियाँ बाहर से बिल्कुल चुप्पी जैसी दिखाई देती हैं।</p>\n<p>कुछ देर बाद नैना ने पूछा—</p>\n<p>“आज बड़ी चुप हो।”</p>\n<p>“दिन भारी था।”</p>\n<p>सुनैना ने बात वहीं छोड़ दी।</p>\n<p>छोड़ देनी चाहिए थी।</p>\n<p>लेकिन दोनों तरफ की ख़ामोशी एक क्षण ज़रूरत से ज़्यादा खिंच गई।</p>\n<p>और फिर सुनैना ने वही आवाज़ इस्तेमाल की जो वह किसी सोर्स से ऐसा सवाल पूछते समय करती थी जिसका जवाब उसके लिए ज़रूरत से ज़्यादा मायने रखता हो।</p>\n<p>“नैना।”</p>\n<p>“हूँ?”</p>\n<p>“क्या तुम अब भी उससे प्यार करती हो?”</p>\n<p>नाम नहीं लिया।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>लाइन चुप हो गई।</p>\n<p>पीछे कहीं टीवी चल रहा था।</p>\n<p>सीढ़ियों पर किसी बच्चे के कदम सुनाई दिए।</p>\n<p>एक पूरा जीवन फोन के उस पार मौजूद था।</p>\n<p>और उसके बीच एक ऐसा नाम था जिसे बोलना ज़रूरी नहीं था।</p>\n<p>कुछ देर बाद नैना ने पूछा—</p>\n<p>“आज ये क्यों पूछ रही हो?”</p>\n<p>“कहा न, दिन भारी था।”</p>\n<p>सुनैना की आवाज़ हल्की हुई।</p>\n<p>“जवाब दे दो।”</p>\n<p>नैना की हँसी बहुत धीमी आई।</p>\n<p>लेकिन वह हँसी जैसी नहीं लगी।</p>\n<p>“कुछ चीज़ें जाती नहीं हैं, सुनैना।”</p>\n<p>फिर थोड़ी देर बाद—</p>\n<p>“कुछ तरह का प्यार… कुछ एहसास… कभी भूलते नहीं।”</p>\n<p>“बस इंसान उनका नाम लेना बंद कर देता है।”</p>\n<p>एक साँस।</p>\n<p>“मैं रोज़ सुबह उठती हूँ। बच्चों को स्कूल भेजती हूँ। सब कुछ ठीक से करती हूँ।”</p>\n<p>फिर बहुत धीमे—</p>\n<p>“फिर भी कहीं एक दरवाज़ा है जो बंद ही नहीं होता, सुनैना।”</p>\n<p>सुनैना ने आँखें बंद कर लीं।</p>\n<p>“जानती हूँ।”</p>\n<p>“तुम ठीक हो न?”</p>\n<p>“हाँ।”</p>\n<p>उतनी ही जल्दी, जितनी जल्दी नैना ने कहा था—सब हैं।</p>\n<p>फिर धीरे से कहा—</p>\n<p>“जाओ, अपने बेटे को देखो।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>फोन कटने के बाद नैना बहुत देर रसोई में बैठी रही।</p>\n<p>फोन मेज़ पर उल्टा रखा था।</p>\n<p>घर की बाकी बत्तियाँ बुझ चुकी थीं। बेटे के कमरे का दरवाज़ा आधा खुला था, जैसा वह हर रात छोड़ती थी।</p>\n<p>उसने अपने लिए चाय बनाई थी।</p>\n<p>फिर उसे ठंडा होने दिया।</p>\n<p>सुनैना का सवाल अब भी वहीं बैठा था।</p>\n<p><i>क्या तुम अब भी उससे प्यार करती हो?</i></p>\n<p>जवाब वह दे चुकी थी।</p>\n<p>पर जवाब देना एक बात थी।</p>\n<p>उसे जीना दूसरी।</p>\n<p>ग्यारह साल बीत चुके थे।</p>\n<p>फिर भी सारी यादें उसके दिल में आज भी वैसी ही थीं, जैसे कल की बात हों।</p>\n<p>सीने में कहीं दर्द उठा।</p>\n<p>वैसा दर्द नहीं जो चोट से होता है। वह जो बरसों दबा रहे, और किसी एक सवाल से अचानक करवट बदल ले।</p>\n<p>उसने अनजाने में बाएँ अंगूठे को दाएँ हाथ से दबा लिया।</p>\n<p>वहाँ कोई निशान नहीं था।</p>\n<p>पर पोर आज भी जानता था—</p>\n<p>पेंसिल छीलने वाला वह छोटा-सा ब्लेड। मेज़ की लैंप का गोल उजाला। और इंतज़ार की वह चुप्पी, जो हर शाम थोड़ी और भारी होती गई थी।</p>\n<p>और तीन पंक्तियाँ।</p>\n<p><i>मैं इंतज़ार कर रही हूँ।</i></p>\n<p><i>तुमने वादा किया है कि लौटोगे।</i></p>\n<p><i>ज़िंदा लौटना, विक्रम।</i></p>\n<p>तीसरी पंक्ति तक पहुँचते-पहुँचते खून इतना हल्का पड़ गया था कि अक्षर काँपने लगे थे।</p>\n<p>उसके हाथ भी तब ऐसे ही काँपे थे।</p>\n<p>लाल डिब्बे में चिट्ठी गिरने की वह धीमी-सी आवाज़ उसे आज भी सुनाई दे जाती थी।</p>\n<p>और उसके बाद के वे दिन, जब हर घंटी एक उम्मीद थी और हर ख़ामोशी एक डर।</p>\n<p>फोन की हर घंटी पर दिल का उछलना। हर अनजान नंबर पर साँस का रुक जाना। और रात को वह चुप्पी, जिससे वह एक बार भी जीत नहीं पाई थी।</p>\n<p>गला भर आया।</p>\n<p>उसने आँखें नहीं पोंछीं।</p>\n<p>पहला आँसू बिना आवाज़ के गाल से उतरा और ठोड़ी पर आकर ठहर गया।</p>\n<p>फिर अस्पताल की ट्यूबलाइट।</p>\n<p><i>वो ढाई हजार किलोमीटर है, विक्रम।</i></p>\n<p><i>हवाई दूरी पंद्रह सौ है।</i></p>\n<p>ड्रिप लगे हाथ के बावजूद वह हँस पड़ी थी।</p>\n<p>और फिर उसका सिर उसकी गोद में था, और उसकी उँगलियाँ उसके बालों में धीरे-धीरे चल रही थीं—</p>\n<p><i>तीन दिन अकेले ख़ुद को सँभालती रही। अब अकेली नहीं हो, तो मत सँभालो।</i></p>\n<p>वह उसी वाक्य पर टूट गई थी।</p>\n<p>इतने बरस बाद भी उस स्पर्श की गरमी माथे पर वैसी की वैसी थी।</p>\n<p>उसने अपनी उँगलियाँ बालों में फिराईं।</p>\n<p>वे उसकी उँगलियाँ नहीं थीं।</p>\n<p>इस एक बात ने उसे इतना खाली कर दिया कि वह कुछ देर साँस लेना भूल गई।</p>\n<p>और गुलमोहर।</p>\n<p>सिर्फ हल्की हरी कोंपलों वाला नंगा पेड़। सीमेंट की बेंच। उसके जूते की नोक से खिसकता एक सूखा पत्ता।</p>\n<p><i>अगली बार भी यही गुलमोहर?</i></p>\n<p><i>यही गुलमोहर।</i></p>\n<p>उसने कभी नहीं पूछा था कि \"अगली बार\" कब आएगा।</p>\n<p>अब समझ आता था कि क्यों नहीं पूछा था।</p>\n<p>पूछ लेती, तो जवाब मिल जाता। और जवाब मिलते ही इंतज़ार का भी एक अंत तय हो जाता।</p>\n<p>फिर वह आख़िरी शाम।</p>\n<p>हरा कुर्ता। नीचे से जलता पानी। और दरवाज़े पर दो हाथ, जिनमें से कोई भी पहले ढीला नहीं पड़ना चाहता था।</p>\n<p>पहले उसने किया था।</p>\n<p>सिर्फ इसलिए कि कोई तो करे।</p>\n<p><i>ये अलविदा है। अगली बार तक नहीं।</i></p>\n<p>उस रात उसे लगा था कि कोई उसके भीतर से कुछ खींचकर ले जा रहा है, और वह उसे रोकने के लिए हाथ तक नहीं उठा सकती।</p>\n<p>वही खिंचाव आज भी था।</p>\n<p>अब वह रो रही थी, चुपचाप।</p>\n<p>कंधे नहीं हिले। साँस की आवाज़ नहीं आई। बस आँसू गिरते रहे, एक के बाद एक, और चाय के ठंडे प्याले में उनकी कोई आहट तक नहीं हुई।</p>\n<p>उसने हथेली के पिछले हिस्से से आँखें पोंछीं।</p>\n<p>बेटे के कमरे की ओर देखा।</p>\n<p>दरवाज़ा वैसे ही आधा खुला था।</p>\n<p>और उसका वह वादा—</p>\n<p><i>एक दिन मैं तुम तक पहुँचूँगा। न फोन पर। न दरवाज़े पर दस्तक देकर।</i></p>\n<p><i>ये नामुमकिन वादा है।</i></p>\n<p><i>शायद। फिर भी कर रहा हूँ।</i></p>\n<p>इसलिए उसने कभी दस्तक का इंतज़ार नहीं किया।</p>\n<p>पर दरवाज़ा बंद भी नहीं किया।</p>\n<p>उसने सुनैना से झूठ नहीं बोला था।</p>\n<p>बस पूरा सच नहीं बोला था।</p>\n<p>पूरा सच यह था कि वह उससे अब भी प्यार करती थी—</p>\n<p>ऐसे, जैसे कोई उस घर से करता है जिसमें अब रहता नहीं, पर जिसकी चाबी अब भी तकिये के नीचे रखी है।</p>\n<p>और यह प्यार अब हक नहीं माँगता था।</p>\n<p>बस दुखता था।</p>\n<p>रसोई की बत्ती बुझाने से पहले उसने खिड़की से बाहर देखा।</p>\n<p>अँधेरे में कुछ नहीं दिखा।</p>\n<p>फिर भी वह देर तक देखती रही।</p>\n<p>यही रसोई थी, जहाँ वह सबसे ज़्यादा अपनी हो पाती थी।</p>\n<p>जहाँ वह किसी की पत्नी या किसी की माँ से पहले, बस नैना थी।</p>\n<p>यहीं वह रो भी सकती थी।</p>\n<p>किसी को पता चले बिना।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कॉल ख़त्म होने के बाद सुनैना बहुत देर वहीं बैठी रही।</p>\n<p>उसके पास अब एक ऐसा जवाब था जिसे उसने माँगा नहीं था—</p>\n<p>और जिसे विक्रम तक पहुँचा देना दुनिया का सबसे आसान काम होता।</p>\n<p>एक दिन पहले वही इंसान उसके लिए बंद कमरे तक आया था।</p>\n<p>आज उसके पास उसके लिए शायद उससे भी ज़्यादा कीमती चीज़ थी—</p>\n<p>एक उत्तर।</p>\n<p>सुनैना ने उसे अपने पास रखा।</p>\n<p>उस रात भी।</p>\n<p>अगली सुबह भी।</p>\n<p>और उसके बाद आने वाले हर महीने में भी।</p>\n<p>विक्रम और उसके बीच कई बार ऐसी खामोशियाँ आईं जिनमें वह सवाल मौजूद था।</p>\n<p>दोनों में से किसी ने उसका नाम नहीं लिया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सुनैना ने काम नहीं रोका।</p>\n<p>रफ्तार भी नहीं घटाई।</p>\n<p>केस को इतना मजबूत बनाने में दो महीने और लगे कि उसे आगे सौंपा जा सके।</p>\n<p>पैसों की कड़ियाँ।</p>\n<p>पुष्ट सूत्र।</p>\n<p>इतना मोटा काग़ज़ी रिकॉर्ड कि आशीष जितना भी महँगा वकील खड़ा कर ले, उसमें से साफ़ रास्ता निकालना आसान न हो।</p>\n<p>एक सुबह तीन बड़े अख़बारों और चैनलों पर स्टोरी एक साथ आई।</p>\n<p>नीचे शांत-सा नाम था—</p>\n<p><b>मीरा आनंद।</b></p>\n<p>एक हफ्ते के भीतर आशीष शर्मा गिरफ्तार हो गया।</p>\n<p>दो दिन बाद उसके भाई, मंत्री देवराज शर्मा ने इस्तीफा दे दिया।</p>\n<p>उस पर ख़ुद कोई चार्ज नहीं था।</p>\n<p>लेकिन उसके अपने खून ने उसकी जानकारी के बिना जो कुछ खड़ा किया था, उसका राजनीतिक बोझ वह झेल नहीं पाया।</p>\n<p>सार्वजनिक रूप से इस्तीफे को जवाबदेही का कदम कहा गया।</p>\n<p>देश की प्रेस ने भी उसे उसी रूप में स्वीकार करने में देर नहीं की।</p>\n<p>पूरी कहानी के सरकारी रिकॉर्ड में कहीं विक्रम का नाम नहीं था।</p>\n<p>न सुनैना का।</p>\n<p>और यही तो इस काम का मतलब था।</p>\n<p>जिस दिन सब ख़त्म हुआ, विक्रम गाड़ी चलाकर घर लौटा।</p>\n<p>उसे जीत जैसा कुछ महसूस नहीं हो रहा था।</p>\n<p>राहत थी।</p>\n<p>बहुत शांत किस्म की।</p>\n<p>सिर्फ इसलिए नहीं कि एक ख़तरनाक इंसान आख़िर रुक गया था—</p>\n<p>हालाँकि वह भी ज़रूरी था।</p>\n<p>बल्कि इसलिए कि उसके अपने घर के ऊपर इतने समय से एक ख़तरा चुपचाप टँगा हुआ था।</p>\n<p>श्रद्धा को उसकी ख़बर नहीं थी।</p>\n<p>बच्चों को भी नहीं।</p>\n<p>और अब—</p>\n<p>उन्हें कभी जानने की ज़रूरत पड़े बिना ही वह ख़तरा हट गया था।</p>\n<p>कुछ जीतें शोर नहीं करतीं।</p>\n<p>बस एक शाम इंसान घर लौटता है—</p>\n<p>और पहली बार उसे लगता है कि दरवाज़े के उस पार सो रहे लोगों पर मंडराती कोई अदृश्य चीज़ अब वहाँ नहीं है।</p>"}, {"chapter": 51, "title": "अध्याय 47 — आख़िरी धागा", "content": "<h1>अध्याय 47 — आख़िरी धागा</h1>\n<p>कविता का डिपार्टमेंटल ऑर्डर लगभग उसी समय आया जब आशीष शर्मा वाला मामला अपने अंत तक पहुँच रहा था।</p>\n<p>मीनल की शिकायत दर्ज हुए दो महीने हो चुके थे।</p>\n<p>एक अलग घड़ी थी जो पीछे कहीं चुपचाप चलती रही थी, जबकि विक्रम का लगभग पूरा ध्यान दूसरी तरफ लगा हुआ था।</p>\n<p>ऑर्डर बिल्कुल वैसा था जैसे सरकारी ऑर्डर होते हैं—</p>\n<p>औपचारिक।</p>\n<p>प्रक्रियागत।</p>\n<p>और उस इंसान के लिए लगभग मामूली, जिसने वहाँ तक पहुँचने वाले वर्षों को जिया न हो।</p>\n<p><b>सब-इंस्पेक्टर कविता देवी को तत्काल प्रभाव से हेड कॉन्स्टेबल के पद पर डिमोट किया जाता है। कंडक्ट से जुड़े अन्य आरोपों की डिपार्टमेंटल इन्क्वायरी पेंडिंग है।</b></p>\n<p>मीनल ने बाद में बताया, अगर कविता इसे चुनौती देना चाहे तो अपील कमिश्नर से ऊपर सीधे <b>डीजीपी, हरियाणा</b> के पास जाएगी।</p>\n<p>उस पद तक पहुँचे बहुत कम अफसर वह रास्ता चुनने की हिम्मत करते थे।</p>\n<p>विक्रम को ख़बर शंकर ने फोन पर दी।</p>\n<p>ऐसी ख़बर जिसे किसी भी सामान्य हिसाब से जीत जैसा लगना चाहिए था।</p>\n<p>“हो गया।”</p>\n<p>शंकर ने कहा।</p>\n<p>“ठीक तरीके से। कानूनी तौर पर। ऐसा कुछ नहीं छोड़ा जिसे बाद में आसानी से चुनौती दी जा सके।”</p>\n<p>एक क्षण रुककर उसने कहा—</p>\n<p>“उसकी रैंक चली गई।”</p>\n<p>“जानता हूँ।”</p>\n<p>दूसरी तरफ कुछ पल चुप्पी रही।</p>\n<p>“तुझे राहत मिली हो, ऐसा नहीं लग रहा।”</p>\n<p>विक्रम अपने बगीचे की तरफ देख रहा था।</p>\n<p>बगीचे में नीम की पत्तियाँ शाम की हवा में हिल रही थीं।</p>\n<p>इतने दिनों बाद घर पूरी तरह महफ़ूज़ था, और वह अपने भीतर कोई एहसास तलाशने की कोशिश कर रहा था।</p>\n<p>कुछ नहीं आ रहा था।</p>\n<p>“मुझे नहीं लगता राहत सही शब्द है।”</p>\n<p>“क्यों?”</p>\n<p>विक्रम ने जवाब देने से पहले थोड़ा समय लिया।</p>\n<p>“मीनल ने उससे वह चीज़ ले ली जिसे बनाने में उसने अपनी ज़िंदगी के बहुत साल लगाए थे, शंकर।”</p>\n<p>फिर उसने ख़ुद ही बात साफ़ की—</p>\n<p>“मैं ये नहीं कह रहा कि काग़ज़ पर जो हुआ वह ग़लत था। सब कानूनी तौर पर सही हुआ।”</p>\n<p>उसकी नज़र अब भी बगीचे में थी।</p>\n<p>“मैं बस ये सोच रहा हूँ कि तुम दोनों में से कोई सच में समझता भी है कि कविता उस तरह के नुकसान के साथ क्या करती है?”</p>\n<p>“गुस्सा आएगा उसे।”</p>\n<p>शंकर का स्वर व्यावहारिक था।</p>\n<p>“आना स्वाभाविक है। इससे डिमोशन ग़लत नहीं हो जाती।”</p>\n<p>“मुझे पता है उसे गुस्सा आएगा।”</p>\n<p>विक्रम की उँगलियाँ फोन पर थोड़ी कस गईं।</p>\n<p>“मुझे उसका गुस्सा परेशान नहीं कर रहा।”</p>\n<p>“फिर?”</p>\n<p>“तूने उसे हमेशा फाइल में एक नाम की तरह जाना है, शंकर।”</p>\n<p>“एक केस।”</p>\n<p>“जिसे बनाना है, फिर जीतना है—भले तू जज की कुर्सी से उसे देख रहा हो।”</p>\n<p>उसने धीमे कहा—</p>\n<p>“मैं उसे तब से जानता हूँ जब वह सिर्फ कविता थी, और मैं बस एक लड़का।”</p>\n<p>आँगन अचानक बहुत दूर से लौट आया।</p>\n<p>एक लड़की।</p>\n<p>हाथ में चाय की ट्रे।</p>\n<p>हर बार ज़रूरत से बस एक क्षण ज़्यादा ठहरती हुई।</p>\n<p>“उसने आँगन में मुझे हर बार चाय ऐसे दी थी जैसे वही उसकी ज़िंदगी में बची इकलौती जगह हो जहाँ कोई फ़ैसला उसका अपना था।”</p>\n<p>विक्रम की आवाज़ धीमी पड़ गई।</p>\n<p>“उस ज़िंदगी में उसके पास ताकत बहुत कम थी।”</p>\n<p>“और मैं जानता हूँ, उस पर क्या बीतती है जब वह एक चीज़, जो उसने पूरी तरह अपने दम पर बनाई थी—उसकी रैंक, उसका काम, उसका रुतबा—उसी सिस्टम के हाथों छिन जाए, जिसमें उसने एक-एक कदम लड़कर अपनी जगह बनाई थी।”</p>\n<p>फोन के दूसरी तरफ शंकर कुछ देर चुप रहा।</p>\n<p>फिर बहुत संभलकर बोला—</p>\n<p>“तू अब भी उसके बारे में ऐसे बात करता है जैसे वह तेरे लिए मायने रखती हो।”</p>\n<p>एक छोटा विराम।</p>\n<p>“इतना सब होने के बाद भी।”</p>\n<p>विक्रम ने तुरंत जवाब नहीं दिया।</p>\n<p>उसे गुरुग्राम का एक होटल कमरा याद आया।</p>\n<p>दोपहर की रोशनी।</p>\n<p>कार्पेट पर गिरती धूप।</p>\n<p>और उसका नाम—</p>\n<p>कविता की आवाज़ में ऐसे, जैसे उस क्षण दुनिया की पूरी भाषा में वही एक शब्द पर्याप्त हो।</p>\n<p>फिर आँगन याद आया।</p>\n<p>वही ट्रे।</p>\n<p>बिना नाम का वह देखना जिसे दोनों ने समझा था और दोनों ने कभी कहा नहीं था।</p>\n<p>“वह पहली इंसान थी जिसने मुझे ऐसे देखा था जैसे मेरा चाहा जाना अपने-आप में काफी हो।”</p>\n<p>शंकर चुप रहा।</p>\n<p>“शादी के लायक नहीं।”</p>\n<p>“ज़िंदगी बसाने के लायक नहीं।”</p>\n<p>“बस…”</p>\n<p>विक्रम शब्द ढूँढ़ते हुए रुका।</p>\n<p>“चाहे जाने के लायक।”</p>\n<p>“सीधे।”</p>\n<p>“बिना किसी हिसाब के।”</p>\n<p>उसका अंगूठा फोन की किनारी पर रुक गया।</p>\n<p>“बाकी पूरी ज़िंदगी में वह बहुत सँभलकर चलती थी, शंकर।”</p>\n<p>“ख़ुद को बाँधकर रखती थी।”</p>\n<p>“चाय डालते हुए उसका हाथ एक बार नहीं काँपता था।”</p>\n<p>फिर उसकी आवाज़ में कोई पुरानी गर्मी आई और उसी के भीतर पुराना दुख भी।</p>\n<p>“लेकिन जब वह सावधानी टूटती थी…”</p>\n<p>विक्रम कुछ पल चुप रहा।</p>\n<p>“पूरी टूटती थी।”</p>\n<p>“उसमें आधा कुछ था ही नहीं।”</p>\n<p>“वह जंगल की आग की तरह प्रेम करती थी।”</p>\n<p>“पूरा। कुछ बचाकर नहीं।”</p>\n<p>“मैंने उससे पहले भी और उसके बाद भी किसी को एक पल में ख़ुद को इतनी पूरी तरह सौंपते नहीं देखा।”</p>\n<p>वह फिर चुप हुआ।</p>\n<p>“तब मैं भी कच्ची उम्र का था।”</p>\n<p>“इतनी कच्ची कि लगा, प्यार का पूरा मतलब बस यही है।”</p>\n<p>“बेकाबू। दोनों तरफ कुछ बचा हुआ नहीं।”</p>\n<p>उसने दूर कहीं देखते हुए कहा—</p>\n<p>“वह भी मुझसे वैसे ही प्यार करती थी, शंकर।”</p>\n<p>“इन सारे सालों में मुझे उस पर एक बार भी शक नहीं हुआ।”</p>\n<p>उसकी आवाज़ अब ज़्यादा स्थिर थी।</p>\n<p>“आज वह जो भी बन गई है…”</p>\n<p>“मेरे परिवार के साथ उसने जो भी किया…”</p>\n<p>“उससे यह झूठ नहीं हो जाता कि उन सालों में हमारे बीच जो था, वह सच था।”</p>\n<p>विक्रम का जबड़ा तन गया।</p>\n<p>“और यही बात मुझे सबसे ज़्यादा डराती है।”</p>\n<p>“वही कविता जो प्यार में जंगल की आग थी,” उसने धीमे से कहा, “आज भी वैसी ही है।”</p>\n<p>“बस अब उसका नाम प्यार नहीं रहा।”</p>\n<p>“उसने कभी कुछ आधा करना सीखा ही नहीं।”</p>\n<p>“न प्यार।”</p>\n<p>“न ये।”</p>\n<p>शंकर को अब बात समझ आने लगी थी।</p>\n<p>“इसीलिए तूने इतनी देर की।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“इसीलिए तू हमें फाइल नहीं करने दे रहा था।”</p>\n<p>“तू केस नहीं बचा रहा था।”</p>\n<p>“न किसी दबाव के मौके का इंतज़ार कर रहा था।”</p>\n<p>शंकर की आवाज़ और धीमी हुई।</p>\n<p>“तू उसे बचा रहा था।”</p>\n<p>“तेरे अंदर का कोई हिस्सा अब भी वह इंसान नहीं बनना चाहता था जो आख़िर में उसे चोट पहुँचाए।”</p>\n<p>विक्रम ने इनकार नहीं किया।</p>\n<p>“जितना रोक सकता था, रोका।”</p>\n<p>फिर कुछ देर बाद—</p>\n<p>“शायद ज़रूरत से ज़्यादा।”</p>\n<p>“मैं ख़ुद से कहता रहा कि सही सबूत चाहिए।”</p>\n<p>“सही वक्त चाहिए।”</p>\n<p>“कुछ हद तक वह सच भी था।”</p>\n<p>उसने साँस छोड़ी।</p>\n<p>“लेकिन उसके नीचे एक और सच था।”</p>\n<p>“उसकी ज़िंदगी में पहले ही बहुत कुछ उससे लिया जा चुका था।”</p>\n<p>“मुझे बहुत साफ़ याद था कि मेरे उसकी ज़िंदगी में आने से पहले, इतने लंबे समय तक इतना कम प्यार पाकर उसने क्या-क्या चुकाया था।”</p>\n<p>“मैं नहीं चाहता था कि आख़िर में उससे कुछ छीनने वालों की सूची में मेरा नाम भी हो।”</p>\n<p>“इतना सब होने के बाद भी?”</p>\n<p>“इतना सब होने के बाद भी।”</p>\n<p>शंकर ने धीरे से पूछा—</p>\n<p>“फिर बदला क्या?”</p>\n<p>इस बार विक्रम का चेहरा सख़्त हो गया।</p>\n<p>“उसने हर लाइन पार की जिसे मैं सालों से उसके लिए थोड़ा-थोड़ा पीछे खिसकाता रहा था।”</p>\n<p>“पहले मेरी जानकारी के बिना हफ्तों मुझ पर नज़र रखवाई।”</p>\n<p>“फिर फोन।”</p>\n<p>“तब भी मैंने ख़ुद से कहा—उसका दर्द समझता हूँ। उसने हाथ बढ़ाया है, जाने दो।”</p>\n<p>उसकी आवाज़ सपाट होती गई।</p>\n<p>“फिर एक रात दस एकड़ खड़ी गेहूँ जल गई।”</p>\n<p>“मैंने ख़ुद से कहा—पुरानी ज़मीन की लड़ाई है। पुराना गुस्सा है। इसे भी समझने की जगह बची है।”</p>\n<p>फिर वह रुका।</p>\n<p>“लेकिन जब मलिक के लोगों ने मेरे परिवार को सीधे धमकी दी…”</p>\n<p>उसके स्वर में अब कोई दुविधा नहीं थी।</p>\n<p>“जब बात मुझसे हटकर श्रद्धा तक पहुँची।”</p>\n<p>“मेरे बच्चों तक।”</p>\n<p>“उन लोगों तक जिन्होंने उसके दुख में फँसने के लिए कभी कुछ किया ही नहीं था…”</p>\n<p>“वहीं ख़त्म हो गया।”</p>\n<p>कुछ क्षण तक सिर्फ उसकी साँस थी।</p>\n<p>“जिस कविता से मैंने कभी प्यार किया था, उससे प्यार करते रहना अब उस कविता को बचाने की वजह नहीं हो सकता था जो वह बन चुकी थी।”</p>\n<p>बहुत देर से भीतर पड़ा कोई वाक्य आख़िर अपनी जगह पा गया था।</p>\n<p>“मैं उससे प्यार करता था, शंकर।”</p>\n<p>विक्रम ने पहली बार बिना बचाव के कहा।</p>\n<p>“यह बात साफ़ समझना।”</p>\n<p>“क्योंकि मुझे लगता है जब कभी ये पूरी कहानी याद की जाए, यह फ़र्क़ मायने रखेगा।”</p>\n<p>उसकी आँखें बगीचे पर थीं।</p>\n<p>“मैंने उससे पूरा प्यार किया था।”</p>\n<p>“उस बेकाबू तरीके से, जिस तरह इंसान तब करता है जब उसे पहली बार समझ आता है कि किसी को चाहना क्या होता है।”</p>\n<p>“वह प्यार सच था।”</p>\n<p>“बाद के साल उसे झूठ नहीं बना सकते।”</p>\n<p>“आज भी नहीं।”</p>\n<p>फिर उसका स्वर बदल गया।</p>\n<p>“लेकिन किसी प्यार का सच होना उसे मेरे परिवार की सुरक्षा की कीमत माँगने का हक नहीं देता।”</p>\n<p>एक छोटा विराम।</p>\n<p>“मैंने उन्हें चुना है।”</p>\n<p>“श्रद्धा को।”</p>\n<p>“अपने बच्चों को।”</p>\n<p>“और हर बार चुनूँगा।”</p>\n<p>“चाहे उस पुराने प्यार का कितना भी हिस्सा मेरे भीतर कहीं अधूरा पड़ा रहे।”</p>\n<p>उसने बहुत धीरे कहा—</p>\n<p>“पहला प्यार कभी पूरा ख़त्म होता भी नहीं।”</p>\n<p>“इंसान उससे बहुत दूर निकल आता है…”</p>\n<p>“फिर भी उसका कोई छोटा-सा हिस्सा हमेशा थोड़ा अधूरा वहीं रह जाता है, जहाँ वह पहली बार था।”</p>\n<p>उसकी नज़र आख़िरी बार बगीचे पर गई।</p>\n<p>चेहरे पर दुख था।</p>\n<p>लेकिन कविता की डिमोशन का नहीं।</p>\n<p>न जीते हुए केस का।</p>\n<p>वह दुख उस लड़की के लिए था जिसे उसने कभी एक आँगन में जाना था।</p>\n<p>और अब यह बात कहते हुए उसे पहली बार समझ आया कि उस लड़की को वह बहुत पहले अलविदा कह चुका था—</p>\n<p>उससे भी पहले, जब दोनों में से किसी को पता नहीं था कि वह विदाई हमेशा के लिए है।</p>\n<p>“एक बार, कम-से-कम एक बार, यह बात कहीं दर्ज रहे—”</p>\n<p>उसकी आवाज़ बहुत धीमी थी।</p>\n<p>“मैंने कभी यह समझना बंद नहीं किया कि वह यहाँ तक कैसे पहुँची।”</p>\n<p>“लेकिन मैं अपनी समझ को अपने परिवार को ख़तरे में रखने की वजह नहीं बना सकता था।”</p>\n<p>उसने आँखें बंद कीं, फिर खोलीं।</p>\n<p>“मेरे लिए यह यहीं ख़त्म होता है, शंकर।”</p>\n<p>“कानून ने तय किया इसलिए नहीं।”</p>\n<p>“मैंने तय किया इसलिए।”</p>\n<p>फिर बहुत देर बाद जैसे अपने ही भीतर किसी आख़िरी गाँठ को खोलते हुए बोला—</p>\n<p>“कुछ प्यार इंसान पूरी ज़िंदगी अपने साथ रखता है।”</p>\n<p>“वे भी, जिन्हें आख़िर एक दिन पूरी तरह छोड़ना पड़ता है।”</p>\n<p>विक्रम की आवाज़ लगभग फुसफुसाहट में उतर गई।</p>\n<p>“कविता मेरे लिए वैसा ही प्यार है, शंकर।”</p>\n<p>एक क्षण रुककर—</p>\n<p>“और आज मैं उसकी आख़िरी डोर छोड़ रहा हूँ।”</p>\n<p>फोन कटने के बाद वह बहुत देर बगीचे में खड़ा रहा।</p>\n<p>नीम से एक पत्ता टूटकर नीचे आया।</p>\n<p>उसने उसे उठाया नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>एक हफ्ते बाद मीनल ख़ुद घर आई।</p>\n<p>केस के आख़िरी सर्टिफाइड काग़ज़ कुरियर से भेजे जा सकते थे।</p>\n<p>विक्रम ने दरवाज़ा खोलते ही समझ लिया कि उन्हें ख़ुद लेकर आना बस एक बहाना था—</p>\n<p>और उतना मजबूत भी नहीं, जितना मीनल को शायद लग रहा था।</p>\n<p>श्रद्धा ने उसे चाय के लिए रोक लिया।</p>\n<p>मीनल ने रस्मी-सा विरोध किया, फिर मान गई।</p>\n<p>दोनों को बात करते देखते हुए विक्रम को शंकर की पुरानी बातें याद आईं।</p>\n<p>मीनल सचमुच वैसी ही थी—</p>\n<p>तेज़।</p>\n<p>बिना जल्दबाज़ी के।</p>\n<p>ऐसी मौजूदगी जिसे कमरे में जगह बनाने के लिए आवाज़ ऊँची करने की ज़रूरत नहीं पड़ती।</p>\n<p>बातों के बीच श्रद्धा ने सहजता से कहा—</p>\n<p>“शंकर आपके बारे में काफी बात करते हैं।”</p>\n<p>मीनल की आँखें एक पल को चौंकीं, फिर उसने उसे छिपा लिया।</p>\n<p>“अच्छा?”</p>\n<p>“हाँ।”</p>\n<p>श्रद्धा ने उसके कप में चाय डालते हुए मुस्कराकर कहा—</p>\n<p>“शायद जितना उन्हें ख़ुद एहसास नहीं है, उससे ज़्यादा।”</p>\n<p>मीनल चुप रही।</p>\n<p>“एक इंसान जो बार-बार कहता है कि आप दोनों सिर्फ पुराने दोस्त हैं,” श्रद्धा ने बिल्कुल मासूमियत से आगे कहा, “उसे यह बड़ी अच्छी तरह पता रहता है कि आप आजकल किस अदालत में पेश हो रही हैं, कौन-से मुक़दमे लड़ रही हैं…”</p>\n<p>विक्रम ने मुस्कान दबाई।</p>\n<p>श्रद्धा अभी ख़त्म नहीं हुई थी।</p>\n<p>“और आपके दफ़्तर के पास किस रेस्टोरेंट में आप अब भी हर शुक्रवार जाती हैं।”</p>\n<p>कुछ क्षण मीनल उसे देखती रही।</p>\n<p>फिर अचानक हँस पड़ी।</p>\n<p>सचमुच की हँसी।</p>\n<p>जैसे बात ने उसे पकड़ लिया हो।</p>\n<p>विक्रम ने धीरे से कहा—</p>\n<p>“उसने हमें बताया था कि तुम दोनों पुराने दोस्त हो।”</p>\n<p>फिर मीनल के चेहरे को देखकर जो बात अब साफ़ थी, उसे पूरा किया—</p>\n<p>“और ज़ाहिर है, कहानी सिर्फ इतनी नहीं है।”</p>\n<p>मीनल ने कप को दोनों हाथों से थाम लिया।</p>\n<p>कुछ देर बाद पहली बार जैसे किसी और से नहीं, ख़ुद से सच बोल रही हो—</p>\n<p>“असल में वह कभी पूरी तरह ख़त्म हुआ ही नहीं।”</p>\n<p>श्रद्धा चुपचाप सुनती रही।</p>\n<p>“हम दोनों के लिए।”</p>\n<p>मीनल के चेहरे पर अब एक अजीब-सी राहत थी।</p>\n<p>“हालाँकि सालों से हम बड़ी सावधानी से हर पूछने वाले के सामने यह दिखाते रहे कि सब ख़त्म हो चुका है।”</p>\n<p>हल्की मुस्कान आई।</p>\n<p>“ज़्यादातर समय एक-दूसरे के सामने भी।”</p>\n<p>“तुम दोनों मिलते रहे हो?”</p>\n<p>विक्रम ने पूछा।</p>\n<p>“जितना हमने कभी किसी को बताया उससे कहीं ज़्यादा।”</p>\n<p>“चुपचाप।”</p>\n<p>“बिना कोई नाम दिए।”</p>\n<p>उसने कप नीचे रखा।</p>\n<p>“शायद इसलिए कि हम दोनों में से किसी ने उस रिश्ते को दोबारा नाम देने की हिम्मत ही नहीं की।”</p>\n<p>फिर उसने दोनों को देखा।</p>\n<p>“लगता है आज मैंने आख़िर आप दोनों को जानने की इजाज़त दे दी।”</p>\n<p>श्रद्धा के स्वर में कोई फ़ैसला नहीं था।</p>\n<p>सिर्फ जिज्ञासा।</p>\n<p>“लेकिन छिपाना क्यों?”</p>\n<p>“आदत।”</p>\n<p>मीनल ने कहा।</p>\n<p>फिर कुछ सोचकर—</p>\n<p>“और डर।”</p>\n<p>कुछ पल वह चुप रही।</p>\n<p>“अगर बिल्कुल सच बोलूँ तो हमने एक बार इसे बाकायदा ख़त्म किया था।”</p>\n<p>“दोनों को उस समय पूरा यकीन था कि वही समझदारी है।”</p>\n<p>उसकी उँगली कप के किनारे पर ठहरी रही।</p>\n<p>“मुश्किल यह हुई कि हमने ऊपर से रिश्ता ख़त्म कर दिया…”</p>\n<p>“अंदर से कोई भी रुक नहीं पाया।”</p>\n<p>विक्रम शांत सुनता रहा।</p>\n<p>“और यह मान लेना कि हम रुके ही नहीं,” मीनल ने हल्की कड़वी मुस्कान के साथ कहा, “इसका मतलब होता कि इतने साल पहले जिस चीज़ को हमने समझदारी कहा था, उसके बारे में हम दोनों ग़लत थे।”</p>\n<p>“और हम दोनों में से कोई भी अपनी ग़लती मानने में खास अच्छा नहीं है।”</p>\n<p>इतनी भावनात्मक थकान के बाद भी विक्रम के चेहरे पर मुस्कान आ गई।</p>\n<p>“उसे बहुत गुस्सा आएगा कि तुमने हमें बता दिया।”</p>\n<p>“झेल लेगा।”</p>\n<p>मीनल का चेहरा बहुत नरम हो गया।</p>\n<p>फिर जैसे अचानक उसने अपने लिए भी कोई छोटा-सा फ़ैसला कर लिया हो—</p>\n<p>“बल्कि उससे कहना, मैंने यही कहा है।”</p>\n<p>वह मुस्कराई।</p>\n<p>“शब्द बदलना मत।”</p>\n<p>एक क्षण रुकी।</p>\n<p>फिर बोली—</p>\n<p>“मुझे लगता है अब हम दोनों में से किसी एक को तो इतना सँभलकर चलना छोड़ देना चाहिए।”</p>"}, {"chapter": 52, "title": "अध्याय 48 — नैना की ख़ामोशी", "content": "<h1>अध्याय 48 — नैना की ख़ामोशी</h1>\n<p>केस ख़त्म होने के बाद विक्रम और सुनैना एक आख़िरी बार मिले।</p>\n<p>वैसा ही एक कैफे।</p>\n<p>लेकिन इस बार दोनों ने जगह चुनने में पहले जैसी सावधानी नहीं बरती।</p>\n<p>फिलहाल ख़तरा पीछे छूट चुका था।</p>\n<p>सुनैना काफी देर तक अपने कप को दोनों हाथों के बीच धीरे-धीरे घुमाती रही, फिर बोली—</p>\n<p>“मुझे तुमसे माफ़ी माँगनी है।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“काम के लिए नहीं,” उसने कहा। “उस सोच के लिए जो मैं इतने सालों तक तुम्हारे बारे में रखती रही। तुम्हें ठीक से जाने बिना।”</p>\n<p>“तुम्हें मुझसे किसी बात की माफ़ी माँगने की ज़रूरत नहीं है।”</p>\n<p>“तुम्हें नहीं, मुझे ज़रूरत है।”</p>\n<p>उसने कप घुमाना रोक दिया।</p>\n<p>“सालों तक मुझे लगता रहा कि तुम ठीक वैसे इंसान हो जो किसी लड़की को ख़ुद से पूरी तरह प्यार करने देगा… और फिर बिना पीछे देखे चला जाएगा।”</p>\n<p>उसकी नज़र विक्रम पर टिकी रही।</p>\n<p>“मैं ग़लत थी।”</p>\n<p>फिर उसका चेहरा ज़रा-सा बदल गया।</p>\n<p>“लेकिन एक बात में मैं सही थी।”</p>\n<p>“किसमें?”</p>\n<p>“उस दोपहर नैना के फ्लैट में मैंने उससे जो कहा था।”</p>\n<p>“तुमसे मिले मुश्किल से एक घंटा हुआ था और मैंने उससे कहा था—तुम ऐसे इंसान हो जो उसे चलाने की कोशिश नहीं करेगा… उसे संभाल सकता है।”</p>\n<p>एक क्षण रुककर—</p>\n<p>“और तुम्हें जाने देना उसकी ज़िंदगी की सबसे बड़ी ग़लती होगी।”</p>\n<p>विक्रम की आँखें पल भर को पुराने दिनों में लौट गईं।</p>\n<p>“मुझे पता है।”</p>\n<p>“उसने कई महीने बाद मुझे बताया था।”</p>\n<p>“शायद एक-एक शब्द।”</p>\n<p>“तो फिर तुम्हें यह भी पता है कि मैंने उसका एक शब्द भी सिर्फ कहने के लिए नहीं कहा था।”</p>\n<p>सुनैना के स्वर में अब कोई पुरानी तल्ख़ी नहीं थी।</p>\n<p>“बाकी सब जितना भी उलझा रहा हो, तुम्हारे बारे में उस पहली राय को मुझे आज तक बदलना नहीं पड़ा।”</p>\n<p>फिर अचानक उसकी आँखों में शरारत चमक उठी।</p>\n<p>“और वैसे…”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“अगर तुम पहले से शादीशुदा नहीं होते तो शायद मैं ख़ुद ही तुम्हारे घर रिश्ता लेकर आ जाती।”</p>\n<p>विक्रम एक क्षण उसे देखता रहा।</p>\n<p>“क्या?”</p>\n<p>“मैं अब भी अविवाहित हूँ, अगर तुम्हारी नज़र से यह बात निकल गई हो।”</p>\n<p>उसने बिल्कुल सहजता से कहा—</p>\n<p>“और मुझे उसका कभी अफसोस नहीं हुआ। लेकिन तुम्हारे जैसा इंसान बहुत बार नहीं मिलता।”</p>\n<p>कई हफ्तों बाद विक्रम सचमुच हँसा।</p>\n<p>इतना अचानक कि जैसे सीने में बहुत दिनों से कसा हुआ कुछ एक पल के लिए ढीला पड़ गया हो।</p>\n<p>“आराम से, सुनैना।”</p>\n<p>“मैं शादीशुदा हूँ। बच्चे भी हैं। कहीं तुम्हारी इतनी सारी ख़ुफ़िया मेहनत में ये छोटी-सी बात छूट तो नहीं गई?”</p>\n<p>“छूटी नहीं।”</p>\n<p>वह मुस्कराई।</p>\n<p>“मैंने ‘अगर’ कहा था, विक्रम।”</p>\n<p>मुस्कान कुछ पल रही।</p>\n<p>फिर धीरे-धीरे उसके चेहरे से उतर गई।</p>\n<p>“वैसे शादी न करने वाली बात मज़ाक नहीं थी।”</p>\n<p>उसका स्वर गंभीर हो गया।</p>\n<p>“मैंने बहुत छोटी उम्र में नैना को देखकर एक फ़ैसला कर लिया था।”</p>\n<p>“कौन-सा?”</p>\n<p>“कि मैं कभी किसी और की ज़िंदगी में फिट होने के लिए ख़ुद को छोटा नहीं करूँगी।”</p>\n<p>वह कुछ क्षण चुप रही।</p>\n<p>“मैंने अपनी बहन को उस साल बदलते देखा था जब उसने मान लिया कि प्यार का मतलब किसी और की बनाई ज़िंदगी में अपने हिस्से की जगह कम करते जाना है।”</p>\n<p>“तभी तय किया था—जो भी बनाऊँगी, अपने पूरे रूप में बनाऊँगी।”</p>\n<p>“वरना नहीं बनाऊँगी।”</p>\n<p>उसकी आँखों में कोई पछतावा नहीं था।</p>\n<p>लेकिन कीमत की पहचान थी।</p>\n<p>“उस फ़ैसले की कीमत भी दी है मैंने।”</p>\n<p>“मुझे अफसोस नहीं है।”</p>\n<p>“लेकिन यह दिखावा भी नहीं करती कि वह फ़ैसला मुफ्त था।”</p>\n<p>फिर उसकी आँखें नरम हो गईं।</p>\n<p>“हम तुम्हारे बारे में बात करते थे, पता है?”</p>\n<p>विक्रम शांत हो गया।</p>\n<p>“बहुत।”</p>\n<p>“जितना मुझे कभी पता नहीं चला, उससे ज़्यादा?”</p>\n<p>“बहुत ज़्यादा।”</p>\n<p>उसकी मुस्कान हल्की थी।</p>\n<p>“वह तुमसे प्यार करती थी, विक्रम।”</p>\n<p>फिर बिना रुके बोली—</p>\n<p>“बहुत ज़्यादा।”</p>\n<p>“इस दुनिया में शायद किसी भी चीज़ से ज़्यादा।”</p>\n<p>“और हम दोनों जितना चाहते थे, उससे कहीं ज़्यादा समय तक।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>“कभी-कभी मुझे उससे थोड़ी नाराज़गी भी होती थी,” सुनैना ने स्वीकार किया, “कि वह इतना भारी कुछ ऐसे इंसान के लिए ढो रही है जो उसे ढोते हुए देखने के लिए वहाँ था ही नहीं।”</p>\n<p>विक्रम का हाथ कप की तरफ बढ़ते-बढ़ते रुक गया।</p>\n<p>महीनों की पेशेवर दूरी उसे इस एक साधारण वाक्य के लिए तैयार नहीं कर पाई थी।</p>\n<p>और फिर सवाल उसके मुँह से सोचने से पहले निकल गया—</p>\n<p>“वह कैसी है?”</p>\n<p>सुनैना स्थिर हो गई।</p>\n<p>विक्रम ने नाम लिया।</p>\n<p>“नैना।”</p>\n<p>उनके बीच कुछ क्षण वही पुरानी सीमा आकर खड़ी हो गई जिसे सुनैना ने पहली ब्रीफिंग में इतनी साफ़ रेखा की तरह खींच दिया था—</p>\n<p><b>उसके बारे में मुझसे मत पूछना।</b></p>\n<p>सुनैना ने बहुत देर तक उसे देखा।</p>\n<p>फिर पहली बार उस सीमा को थोड़ा-सा खोल दिया।</p>\n<p>“उस घर में अब बहुत कुछ है जो उसे होने की इजाज़त नहीं है।”</p>\n<p>विक्रम का चेहरा बदल गया।</p>\n<p>“क्या मतलब?”</p>\n<p>“शादी के बाद वह गुरुग्राम से करीब दो सौ किलोमीटर दूर अपने पति के परिवार के घर चली गई।”</p>\n<p>सुनैना का स्वर शांत था, लेकिन उस शांति के नीचे वर्षों का जमा हुआ गुस्सा था।</p>\n<p>“इतनी दूर कि मैं उसे सिर्फ मिलने जाने पर देख पाती हूँ।”</p>\n<p>“और इतनी दूर कि उसके करीब रहने वालों में किसी ने धीरे-धीरे बदलती चीज़ों को देखा ही नहीं।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“शुरू में शादी सामान्य थी।”</p>\n<p>“फिर दो-तीन साल बाद उसने अपने पति को तुम्हारे बारे में बता दिया।”</p>\n<p>विक्रम की नज़र तुरंत उठी।</p>\n<p>“सब कुछ?”</p>\n<p>“हर बात नहीं।”</p>\n<p>“लेकिन इतना कि उससे कुछ छिपा न रहे।”</p>\n<p>“उसने बताया कि तुमसे पहले उसकी ज़िंदगी में कोई था।”</p>\n<p>“गहरा रिश्ता था।”</p>\n<p>“जिससे वह पूरी तरह प्यार करती थी।”</p>\n<p>“और जिसे उसने इसलिए खोया क्योंकि उसके पिता ने शादी से इनकार कर दिया था।”</p>\n<p>सुनैना ने धीरे से कहा—</p>\n<p>“शायद उसे सच में लगा था कि ईमानदारी शादी की सही नींव होती है।”</p>\n<p>“उसे उम्मीद थी कि वह इंसान उस सच को उतनी ही गरिमा से स्वीकार करेगा जितनी गरिमा की वह किसी बेहतर इंसान से उम्मीद करती थी।”</p>\n<p>विक्रम ने बहुत धीमे पूछा—</p>\n<p>“उसने नहीं किया?”</p>\n<p>“बिल्कुल नहीं।”</p>\n<p>सुनैना का चेहरा कठोर हो गया।</p>\n<p>“सबसे ज़्यादा उसका अहंकार।”</p>\n<p>“यह बात कि उसने ऐसी लड़की से शादी की है जिसने कभी किसी और को उससे कहीं ज़्यादा पूरी तरह चाहा था जितना वह अब अपने पति को चाहने का दावा करती है।”</p>\n<p>“लेकिन कोई एक बड़ा हादसा नहीं हुआ।”</p>\n<p>“ऐसा कुछ नहीं जिसे एक तारीख़ देकर कहा जा सके—हाँ, इसी दिन सब बदल गया।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“पहले उसकी नौकरी गई।”</p>\n<p>“सज़ा कहकर नहीं। फ़िक्र कहकर।”</p>\n<p>“फिर अकेले कहीं आने-जाने की आज़ादी थोड़ी-थोड़ी कम हुई।”</p>\n<p>“इतने हल्के कि शायद उसे ख़ुद याद नहीं कि आख़िरी बार वह उस घर से उसके बिना कब निकली थी।”</p>\n<p>सुनैना ने कप की किनारी पर उँगली फेरते हुए कहा—</p>\n<p>“पूरे दिन में बच्चों के साथ की शाम ही अब शायद उसका अकेला वक्त है, जो पूरी तरह उसका लगता है।”</p>\n<p>“कभी-कभी अपने पति के दफ़्तर के पास एक छोटी-सी दुकान में किताबें खरीदने जाती है।”</p>\n<p>“शायद इसीलिए उसका यह बाहर जाना अब तक बचा हुआ है—क्योंकि वह उसे ऐसी किसी जगह नहीं ले जाता, जिस पर उसे पहले से भरोसा न हो।”</p>\n<p>विक्रम के चेहरे पर कोई भाव नहीं था।</p>\n<p>बस उसकी आँखें बदल गई थीं।</p>\n<p>“और उसका पति उसे डाँटता है, विक्रम।”</p>\n<p>“छोटी-छोटी बातों पर।”</p>\n<p>“खाना देर से हुआ। कोई चीज़ अपनी जगह नहीं मिली।”</p>\n<p>“ऐसी बातें जिनका एक समझदार बड़े इंसान के लिए कोई मतलब नहीं होना चाहिए।”</p>\n<p>एक विराम।</p>\n<p>“लेकिन हर बार होता है।”</p>\n<p>“नैना जवाब देती है?”</p>\n<p>सुनैना ने सिर हिलाया।</p>\n<p>“अब नहीं।”</p>\n<p>दो शब्द।</p>\n<p>और शायद अब तक कही गई हर बात से भारी।</p>\n<p>“वह नैना जिसने पूरी ज़िंदगी हर बात पर, हर किसी से बहस की…”</p>\n<p>सुनैना की आवाज़ पहली बार थोड़ी कमज़ोर हुई।</p>\n<p>“अब जवाब नहीं देती।”</p>\n<p>“इतनी धीरे चुप हुई है कि मुझे नहीं लगता उसे ख़ुद भी पता चला कि वह कब चुप होने लगी।”</p>\n<p>“मैंने देखा है।”</p>\n<p>“हर साल थोड़ा और।”</p>\n<p>“लेकिन कोई एक दिन नहीं है जिसकी तरफ उँगली उठाकर मैं कह सकूँ—”</p>\n<p>उसने साँस ली।</p>\n<p>“बस।”</p>\n<p>“इसी दिन मेरी बहन ने लाउड होना छोड़ दिया।”</p>\n<p>वह शब्द कहीं बहुत पीछे से, किसी और शाम की अपनी ही आवाज़ में उसके कानों में लौटा।</p>\n<p>विक्रम ने एक पल को आँखें बंद कर लीं।</p>\n<p>फिर नज़र उठाई, और वह सुनैना से नहीं हटी।</p>\n<p>“क्या वह उसके साथ क्रूर है?”</p>\n<p>सुनैना ने तुरंत जवाब नहीं दिया।</p>\n<p>“अपनी नज़र में?”</p>\n<p>उसने धीरे से कहा—</p>\n<p>“नहीं।”</p>\n<p>“मुझे नहीं लगता अगर तुम उसके सामने वह शब्द रख भी दो तो वह ख़ुद को उसमें पहचान पाएगा।”</p>\n<p>“उसे सच में लगता है कि वह जो करता है, सही है।”</p>\n<p>“कि अगर उसकी पत्नी कभी किसी और से उससे ज़्यादा गहरा प्यार करती थी, तो उस कबूलनामे ने उसे हमेशा के लिए कुछ अधिकार दे दिए।”</p>\n<p>उसकी आवाज़ सपाट रही।</p>\n<p>“और उन अधिकारों का इस्तेमाल करना उसके लिए क्रूरता नहीं है।”</p>\n<p>“उसके हिसाब से वह हर्ज़ाना है।”</p>\n<p>“धीरे-धीरे वसूला गया।”</p>\n<p>“एक छोटा फ़ैसला करके।”</p>\n<p>“फिर दूसरा।”</p>\n<p>“अब वह ऐसी चीज़ें तय करता है जो कभी नैना ख़ुद तय करती थी।”</p>\n<p>“घर से बाहर क्या पहनेगी। किन दोस्तों से मिलेगी। बच्चे कैसे पलेंगे।”</p>\n<p>“इतनी छोटी-छोटी बातें कि अलग-अलग बोलो तो शायद बेहूदा लगें।”</p>\n<p>“लेकिन मिलकर वे किसी की पूरी ज़िंदगी का आकार बदल देती हैं।”</p>\n<p>“और नैना?”</p>\n<p>“विरोध नहीं करती।”</p>\n<p>“इसलिए नहीं कि वह सहमत है।”</p>\n<p>“इसलिए कि धीरे-धीरे उसने सीख लिया कि हर विरोध की कीमत होती है।”</p>\n<p>सुनैना ने विक्रम की आँखों में देखते हुए कहा—</p>\n<p>“और जो माँ आख़िर में बच्चों के लिए उसी घर में रहने का फ़ैसला करती है, वह बहुत जल्दी सीख जाती है कि कौन-सी लड़ाई लड़ने की कीमत वह अब भी चुका सकती है… और कौन-सी नहीं।”</p>\n<p>विक्रम की आवाज़ बहुत धीमी थी।</p>\n<p>“मुझे तो यह क्रूरता ही लगती है।”</p>\n<p>“मुझे भी।”</p>\n<p>इस बार सुनैना की आवाज़ भर्रा गई।</p>\n<p>“मैंने ख़ुद इस शब्द को जाने कितनी बार उलट-पलटकर देखा है।”</p>\n<p>“सोचा है, क्या सच में यही नाम है इसका?”</p>\n<p>“मेरे पास इससे बेहतर नाम नहीं है।”</p>\n<p>वह रुकी।</p>\n<p>“उस लड़की की सारी बेबाक़ी…”</p>\n<p>“वह सारी आवाज़ जिसे तुम उससे प्यार करते हुए इतना पसंद करते थे…”</p>\n<p>“एक-एक शांत साल में उससे थोड़ी-थोड़ी लेकर चली गई।”</p>\n<p>“और उसे ख़ुद पता नहीं चला।”</p>\n<p>सुनैना की आँखें अब कप पर थीं।</p>\n<p>“मैंने अपनी बहन को टुकड़ा-टुकड़ा छोटा होते देखा है, विक्रम।”</p>\n<p>“ऐसे घर में जहाँ कोई भी यह स्वीकार नहीं करेगा कि उसे छोटा कौन कर रहा है।”</p>\n<p>बाहर ट्रैफिक का शोर चलता रहा।</p>\n<p>फिर भी उस क्षण कैफे जैसे उन दोनों के आसपास कहीं दूर हो गया।</p>\n<p>“संविधान ने उसे जन्म से ही काग़ज़ पर बराबरी दी थी।”</p>\n<p>सुनैना ने कहा।</p>\n<p>“लेकिन काग़ज़ किसी औरत के साथ उसके घर के भीतर नहीं जाता।”</p>\n<p>उसने नज़र उठाई।</p>\n<p>“उसे असल में जो बचा सकता था, वह था अपने पैरों पर खड़े रहने का रास्ता।”</p>\n<p>“आर्थिक आज़ादी।”</p>\n<p>“मैंने अपनी कमाई इसीलिए कभी किसी के हाथ में नहीं दी।”</p>\n<p>“मेरी बहन को उस परिवार के लिए अपनी नौकरी छोड़नी पड़ी, यह कहकर कि उसकी फ़िक्र है।”</p>\n<p>“उसी परिवार ने धीरे-धीरे उसे सिखाया कि प्यार का मतलब चुप रहना है।”</p>\n<p>“जिस दिन उसकी अपनी कमाई गई, उसी दिन उसकी आख़िरी असली आज़ादी भी चली गई।”</p>\n<p>“क्योंकि उसके बाद हर ‘नहीं’ की एक कीमत थी।”</p>\n<p>सुनैना की आवाज़ धीमी हो गई।</p>\n<p>“और वह कीमत अब वह ख़ुद नहीं चुका सकती थी।”</p>\n<p>विक्रम के भीतर ठंडक-सी उतर गई।</p>\n<p>कोई नई बात नहीं।</p>\n<p>बल्कि बहुत पुरानी बात—</p>\n<p>जो वर्षों का पूरा चक्कर काटकर उसी मेज़ पर लौट आई थी।</p>\n<p>“मैंने उसे चेताया था।”</p>\n<p>सुनैना चुप रही।</p>\n<p>“उस आख़िरी शाम।”</p>\n<p>“शादी से पहले।”</p>\n<p>“मैंने साफ़ कहा था—हमारे बारे में उसे कभी मत बताना।”</p>\n<p>“चाहे तुम दोनों कितने भी करीब हो जाओ।”</p>\n<p>“चाहे तुम्हें लगे कि शादी में पूरा सच होना चाहिए।”</p>\n<p>“मैंने उससे कहा था, मत बताना।”</p>\n<p>“मुझे पता है।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“उसने मुझे एक बार बताया था।”</p>\n<p>“सालों पहले।”</p>\n<p>“बस वही एक बार था, जब वह तुम्हारे बारे में सचमुच बोलने के करीब आई थी।”</p>\n<p>सुनैना ने कहा—</p>\n<p>“उसने यह भी बताया था कि उसने तुम्हारी बात नहीं मानी।”</p>\n<p>“क्योंकि उसे सच में लगता था कि जिस शादी की नींव पूरी ईमानदारी पर न हो, वह शादी ही किस काम की।”</p>\n<p>“उसके बाद उसने यह बात दोबारा कभी नहीं छेड़ी।”</p>\n<p>“मेरे सामने भी नहीं।”</p>\n<p>“जहाँ तक मुझे पता है, किसी के सामने नहीं।”</p>\n<p>“उस फ़ैसले का जो कुछ भी वह अपने भीतर उठाए फिरती है…”</p>\n<p>एक छोटा विराम।</p>\n<p>“अकेले उठाती है।”</p>\n<p>विक्रम बहुत देर तक कुछ नहीं बोला।</p>\n<p>उसकी उँगलियाँ मेज़ के किनारे पर कसती गईं, पोर सफ़ेद पड़ने तक। उसे ख़ुद पता नहीं चला।</p>\n<p>दुख था। और उसके नीचे, अपने ही ऊपर आती कोई शांत, अनचाही नाराज़गी।</p>\n<p>उसने कहा था, मत बताना।</p>\n<p>नैना ने बताया।</p>\n<p>और जिस चीज़ के सामने वह सच बताकर जा खड़ी हुई, उसका आकार विक्रम उससे बहुत पहले देख चुका था।</p>\n<p>चेतावनी दी गई थी।</p>\n<p>चेतावनी नहीं मानी गई थी।</p>\n<p>और अब दोनों के बीच कोई ऐसा अधूरा हिसाब बचा था जिसे शायद वे कभी बैठकर बराबर नहीं कर सकते थे।</p>\n<p>सुनैना ने हाथ बढ़ाकर उसकी उँगलियों पर अपना हाथ रख दिया।</p>\n<p>“तुमने जितनी दूर से जो कर सकते थे, किया।”</p>\n<p>उसकी आवाज़ नरम थी।</p>\n<p>“बाकी कभी तुम्हारे बस में था ही नहीं, विक्रम।”</p>\n<p>“आज भी नहीं है।”</p>\n<p>कुछ देर बाद विक्रम ने पूछा—</p>\n<p>“क्या उसे पता है कि मैं अब भी उसके बारे में पूछता हूँ?”</p>\n<p>“नहीं।”</p>\n<p>जवाब बिना किसी विराम के आया।</p>\n<p>“और मेरी तरफ से कभी पता नहीं चलेगा।”</p>\n<p>सुनैना ने उसे कुछ क्षण देखा।</p>\n<p>अब उनके बीच पेशेवर दूरी का आख़िरी हिस्सा भी नहीं बचा था।</p>\n<p>“एक बात पूछूँ?”</p>\n<p>“पूछो।”</p>\n<p>“फाइल के लिए नहीं।”</p>\n<p>“किसी रिपोर्ट के लिए भी नहीं।”</p>\n<p>विक्रम इंतज़ार करता रहा।</p>\n<p>“क्या तुम अब भी उससे प्यार करते हो?”</p>\n<p>सुनैना की नज़र उसके चेहरे पर थी।</p>\n<p>“इतना सब होने के बाद भी?”</p>\n<p>“श्रद्धा।”</p>\n<p>“बच्चे।”</p>\n<p>“इतने साल।”</p>\n<p>“तुम दोनों के बीच खड़ी पूरी ज़िंदगी के बाद भी?”</p>\n<p>विक्रम ने तुरंत जवाब नहीं दिया।</p>\n<p>कैफे के शीशे के पार शाम का सामान्य ट्रैफिक चलता रहा।</p>\n<p>लोग अपने-अपने घरों की तरफ जा रहे थे।</p>\n<p>दुनिया को उन दोनों के बीच बैठे किसी पुराने नाम से कोई मतलब नहीं था।</p>\n<p>जब विक्रम बोला तो उसकी आवाज़ से वे सारी सावधानियाँ उतर चुकी थीं जिनमें वह आमतौर पर अपने भीतर की बातें लपेटकर रखता था।</p>\n<p>“हाँ।”</p>\n<p>सुनैना स्थिर रही।</p>\n<p>“मैं श्रद्धा से पूरा प्यार करता हूँ।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“अलग तरह से।”</p>\n<p>“उस प्यार में कोई कमी नहीं है।”</p>\n<p>“और मैंने कभी अपने भीतर जो है उसके आकार के बारे में ख़ुद से झूठ नहीं बोला।”</p>\n<p>उसने कुछ क्षण बाहर देखा।</p>\n<p>“लेकिन कुछ प्यार छोड़कर जाते ही नहीं, सुनैना।”</p>\n<p>“साल चाहे जितने गुज़र जाएँ।”</p>\n<p>“वे ख़त्म नहीं होते।”</p>\n<p>“बस उस कमरे में चुपचाप बैठना सीख लेते हैं जिसका दरवाज़ा इंसान ने खोलना बंद कर दिया हो।”</p>\n<p>उसकी आवाज़ और धीमी हुई।</p>\n<p>“फिर कभी बिना बताए वह दरवाज़ा खुल जाता है।”</p>\n<p>“और वह वहीं होती है।”</p>\n<p>“बिल्कुल वैसी…”</p>\n<p>“जैसी आख़िरी बार थी।”</p>\n<p>विक्रम की आँखें अब भी बाहर थीं।</p>\n<p>“और हर बार मुझे फिर समझ आता है कि जिस दिन उसने किसी और से शादी की थी, मेरा कोई हिस्सा उसके साथ चला गया था।”</p>\n<p>“और तब से उसी घर के बाहर खड़ा है…”</p>\n<p>“उस दरवाज़े के इंतज़ार में जो उसकी तरफ से कभी खुलना ही नहीं था।”</p>\n<p>सुनैना ने कुछ नहीं कहा।</p>\n<p>“मुझे नहीं लगता यह कभी पूरी तरह जाएगा।”</p>\n<p>विक्रम ने कहा।</p>\n<p>फिर एक लंबा विराम।</p>\n<p>“और सच कहूँ तो मैं चाहता भी नहीं कि जाए।”</p>\n<p>अब उसने सुनैना की तरफ देखा।</p>\n<p>“क्योंकि जिस दिन वह पूरी तरह चला गया…”</p>\n<p>“उसका मतलब होगा कि मैं यह महसूस करने की ताकत भी खो चुका हूँ कि कभी वह मेरे लिए कितनी बड़ी थी।”</p>\n<p>उसके स्वर में कोई नाटकीयता नहीं थी।</p>\n<p>सिर्फ एक बहुत पुराना सच था जिसे पहली बार पूरा वाक्य मिला था।</p>\n<p>“मैं इसे बाकी ज़िंदगी चुपचाप अपने साथ रख लेना पसंद करूँगा।”</p>\n<p>“लेकिन यह दिखावा नहीं करूँगा कि वह इतना छोटा था कि बस एक दिन नीचे रख देता।”</p>\n<p>कुछ क्षण बाद उसके स्वर में हल्की-सी रक्षात्मक कठोरता आ गई।</p>\n<p>जैसे वह पहले से उस अविश्वास के लिए तैयार हो जिससे दुनिया ऐसे सचों को सुनती है।</p>\n<p>“तुम नहीं समझ सकती, सुनैना।”</p>\n<p>“शायद कोई नहीं समझ सकता।”</p>\n<p>“बाद में कोई कितना भी करीब क्यों न रहा हो।”</p>\n<p>“जो वह था…”</p>\n<p>विक्रम रुका।</p>\n<p>“जितना बड़ा वह था…”</p>\n<p>“उस समय वहाँ हम दोनों के अलावा कोई नहीं था।”</p>\n<p>“बाकी ज़िंदगी बाद में उसके चारों तरफ बनी।”</p>\n<p>सुनैना बहुत देर तक चुप रही।</p>\n<p>उसकी आँखों के पीछे कोई परछाईं हिली—</p>\n<p>आँसू नहीं गिरे।</p>\n<p>बस वहीं संभले रहे।</p>\n<p>जब उसने आख़िर कहा तो आवाज़ पहले से पतली थी।</p>\n<p>“काश…”</p>\n<p>वह रुकी।</p>\n<p>“किसी दिन उसे यह पता चल जाए।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“कुछ बदलने के लिए नहीं।”</p>\n<p>सुनैना ने कहा।</p>\n<p>“कुछ वापस माँगने के लिए भी नहीं।”</p>\n<p>“बस इसलिए कि उस शांत घर में बैठे हुए उसे कभी इतना पता हो…”</p>\n<p>उसकी आवाज़ बहुत धीमी हो गई।</p>\n<p>“कि जो कुछ उसने इतने साल अकेले ढोया…”</p>\n<p>“वह दूसरी तरफ भी ढोया गया था।”</p>\n<p>फिर वह चुप हो गई।</p>\n<p>एक और बात थी जो उसकी आँखों के पीछे आई और वहीं रह गई।</p>\n<p>वह जानती थी कि इस मेज़ पर वह एक ‘हाँ’ के बदले दूसरी ‘हाँ’ रख सकती है।</p>\n<p>उसने नहीं रखी।</p>\n<p>कुछ जवाब किसी और के होते हैं। वे हमारे हाथ में रखे जाते हैं, हमारे नहीं हो जाते।</p>\n<p>कुछ दरवाज़े वर्षों तक बंद रहते हैं—</p>\n<p>लेकिन हर बंद दरवाज़े पर ताला नहीं लगा होता।</p>\n<p>और किसी बहुत भीतर की जगह पर सुनैना अब भी उस मूर्ख, ज़िद्दी उम्मीद को पूरी तरह मार नहीं पाई थी कि जो दो लोग इतने साल अलग-अलग तरफ खड़े रहे—</p>\n<p>किसी दिन उनमें से कोई एक बस हाथ बढ़ाकर देखे कि दरवाज़ा सचमुच बंद है भी या नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम चला गया।</p>\n<p>सुनैना शीशे के पार उसे सड़क पार करते देखती रही।</p>\n<p>उसने एक बार भी पलटकर नहीं देखा।</p>\n<p>सुनैना जानती थी कि वह नहीं देखेगा। जिसे छोड़ना होता था, उसे वह पीठ फेरकर ही छोड़ता था।</p>\n<p>उसने फोन उठाया।</p>\n<p>स्क्रीन पर नैना का नाम चमक रहा था। आख़िरी बार बात तीन दिन पहले हुई थी। <i>“सब ठीक है, तुम बताओ।”</i> नैना ने यही कहा था। और सुनैना जानती थी कि “सब ठीक है” उस घर का सबसे पुराना झूठ है।</p>\n<p>वह लिखने लगी।</p>\n<p><i>आज मैं</i></p>\n<p>उँगली रुकी। उसने मिटा दिया।</p>\n<p><i>एक बात बतानी थी—</i></p>\n<p>वह भी मिटा दी।</p>\n<p>क्या लिखती? कि जिसे तुम ग्यारह साल से सीने में सँभाले बैठी हो, वह भी तुम्हारा नाम उसी तरह सँभाले बैठा है? कि वह आज भी उस दरवाज़े के बाहर खड़ा है जिसे तुमने उसके लिए कभी खोला नहीं, और बंद भी नहीं किया?</p>\n<p>बीच में सिर्फ दो सौ किलोमीटर।</p>\n<p>गाड़ी से एक दिन का रास्ता भी नहीं।</p>\n<p>और उनके बीच ग्यारह साल।</p>\n<p>वह हँस पड़ी—टूटी हुई, बेतुकी हँसी।</p>\n<p>तीन साल उसने झूठे नाम के सहारे उन कमरों में काटे थे जहाँ एक ग़लत साँस की कीमत जान हो सकती थी। और अपनी ही बहन के दिल की इतनी सीधी-सी बात दो लोगों तक नहीं पहुँचा पा रही थी।</p>\n<p>हँसी थम गई।</p>\n<p>पहला आँसू बिना आवाज़ के ढुलका। फिर दूसरा।</p>\n<p>उसने झट से हथेली के पिछले हिस्से से उन्हें पोंछ लिया, जैसे कोई देख न ले।</p>\n<p>कैफे में कोई उसकी तरफ देख भी नहीं रहा था।</p>\n<p>पर यह पुरानी आदत थी। मीरा आनंद कभी नहीं रोती थी।</p>\n<p>आज मीरा आनंद यहाँ नहीं थी।</p>\n<p>यहाँ सिर्फ नैना की छोटी बहन थी। जिसके एक हाथ में एक सच था, दूसरे में दूसरा, और जिसके पास उन्हें एक-दूसरे तक पहुँचाने की हिम्मत नहीं थी।</p>\n<p>उसने फोन औंधा रख दिया।</p>\n<p>बाहर शाम ढलने लगी थी।</p>"}, {"chapter": 53, "title": "अध्याय 49 — आख़िरी ऑपरेशन से पहले", "content": "<h1>अध्याय 49 — आख़िरी ऑपरेशन से पहले</h1>\n<p>संदेश उस सिक्योर लाइन पर आया जिसे कामथ का दफ़्तर तभी इस्तेमाल करता था जब कोई मामला बातचीत की सीमा पार कर चुका हो।</p>\n<p>सिर्फ दो लाइनें थीं—</p>\n<p><b>ब्रीफिंग अठारह सौ बजे।</b></p>\n<p><b>सादे कपड़ों में आना।</b></p>\n<p>और फिर—</p>\n<p><b>यह वाला कहीं लिखा नहीं जाएगा। उस फाइल में भी नहीं जिसे इस देश में सिर्फ तीन लोगों को पढ़ने की इजाज़त है।</b></p>\n<p>उस शाम कामथ ने शब्द हमेशा की तरह कम खर्च किए।</p>\n<p>और जितने किए, बहुत सोचकर किए।</p>\n<p>“एक सवाल तुम आख़िर पूछोगे,” उसने कहा। “इसलिए पहले ही जवाब दे देता हूँ।”</p>\n<p>विक्रम शांत बैठा रहा।</p>\n<p>“इतने साल बाद तुम्हें फिर ऐसी टीम में क्यों खींचा जा रहा है, जबकि पैरा एसएफ़ में आज ऐसे जवान हैं जो इसी तरह की ज़मीन पर लगातार ट्रेनिंग कर रहे हैं और इस काम में तुमसे कहीं ज़्यादा धारदार हैं।”</p>\n<p>कामथ ने उसे सवाल पूछने का मौका नहीं दिया।</p>\n<p>“झूठी तसल्ली देकर तुम्हारा अपमान नहीं करूँगा, विक्रम। सच यही है।”</p>\n<p>“वे साल भर, हर हफ्ते इसी के लिए ड्रिल करते हैं।”</p>\n<p>“और तुमने पिछले कुछ साल दूसरी तरह का असली काम किया है—काबुल, तेहरान… ऐसी जगहों पर, जहाँ असॉल्ट राइफल से ज़्यादा सब्र और झूठे नाम की ज़रूरत पड़ती है।”</p>\n<p>उसने कुर्सी पर पीछे टिकते हुए कहा—</p>\n<p>“उनमें से कोई भी जवान आज रात उस इलाके से तुमसे तेज़ और साफ़ निकल आएगा।”</p>\n<p>“तुम उनके साथ चलो, तब भी।”</p>\n<p>विक्रम ने पूछा—</p>\n<p>“फिर मुझे वापस बुलाया ही क्यों?”</p>\n<p>कामथ ने उसकी तरफ देखा।</p>\n<p>“क्योंकि इस ऑपरेशन को सबसे ज़्यादा जिसकी ज़रूरत है, वह यह नहीं कि कोई उस ज़मीन पर कितनी तेज़ी से चल सकता है।”</p>\n<p>एक छोटा विराम।</p>\n<p>“इस बार नहीं।”</p>\n<p>“तो वहाँ मुझे असल में मिलेगा क्या?”</p>\n<p>कामथ कुछ क्षण चुप रहा।</p>\n<p>जैसे तौल रहा हो कि सरहद पार भेजने से एक दिन पहले किसी इंसान को कितना सच बताया जा सकता है।</p>\n<p>“टारगेट नहीं।”</p>\n<p>फिर—</p>\n<p>“एक इंसान।”</p>\n<p>विक्रम की आँखें उस पर टिक गईं।</p>\n<p>“सालों पहले, अफ़ग़ानिस्तान में, जब तुम उस नाम से घूम रहे थे जो हमने तुम्हें दिया था, तुमने वहाँ एक रिश्ता खड़ा किया था।”</p>\n<p>कामथ ने कहा—</p>\n<p>“मौलवी हबीबुल्लाह।”</p>\n<p>नाम सुनते ही विक्रम के भीतर कोई पुराना कमरा खुल गया।</p>\n<p>एक छोटा जिला।</p>\n<p>धूल।</p>\n<p>एक मामूली मदरसा।</p>\n<p>और एक ऐसा इंसान, जिसके चेहरे पर दो बेटों को खो देने का दुख इतना गहरा बैठ चुका था कि उसके ऊपर हर दूसरा भाव कुछ पल का मेहमान लगता था।</p>\n<p>“बाकी दुनिया के लिए एक मामूली मौलवी,” कामथ बोला, “जो ऐसे जिले में छोटा-सा मदरसा चलाता है जिसकी परवाह ख़ुद काबुल भी मुश्किल से करता है।”</p>\n<p>“लेकिन तुमने उसे धीरे-धीरे अपना बनाया।”</p>\n<p>“जैसा तुम्हें सिखाया गया था।”</p>\n<p>“महीनों में।”</p>\n<p>“और आज तक उसे यही लगता है कि वह बस दो इंसानों की दोस्ती थी, जिन्हें एक-दूसरे पर भरोसा हो गया था।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>उसे मालूम था—</p>\n<p>वह रिश्ता पूरी तरह झूठ भी नहीं था।</p>\n<p>शायद इस काम की सबसे मुश्किल बात हमेशा यही रही थी।</p>\n<p>कभी-कभी जिस भरोसे को किसी मकसद से बनाया जाता है, वह रास्ते में सच बन जाता है।</p>\n<p>और फिर इंसान ख़ुद तय नहीं कर पाता कि उसने एसेट बनाया था—</p>\n<p>या दोस्त।</p>\n<p>कामथ आगे झुका।</p>\n<p>“अब पहली बार हमें उसकी ज़रूरत पड़ी है।”</p>\n<p>“इस पूरे काम में वह सिर्फ एक इंसान पर भरोसा करता है, विक्रम। इस दफ़्तर पर नहीं। इसके पीछे खड़े संगठन पर भी नहीं। सिर्फ तुम पर—तुम्हारे नाम पर, तुम्हारे चेहरे पर।”</p>\n<p>“अभी कहाँ है वह?”</p>\n<p>“एलओसी के ठीक उस पार, उन्हीं के एक कैंप में। वहाँ लड़कों को तोड़ा जाता है और फिर कैंप चलाने वालों के काम का बनाकर दोबारा गढ़ा जाता है। और तोड़ने-गढ़ने के बीच उन्हें यकीन भी दिला दिया जाता है कि वे इसी के लिए पैदा हुए थे।”</p>\n<p>कामथ की आवाज़ में कोई उतार-चढ़ाव नहीं था।</p>\n<p>“हफ्ते में दो बार उसे वहाँ दीनी तालीम के लिए बुलाया जाता है, ताकि लड़कों का ईमान उसी साँचे में ढलता रहे। यानी वह उस कैंप में उस हैसियत से बैठता है जो कोई सिपाही या जासूस किसी कीमत पर नहीं ख़रीद सकता। और हर बार वहाँ से निकल भी आता है, बिना किसी के एक सवाल पूछे।”</p>\n<p>“वहाँ गिनती हर घंटे बदलती है। कौन मौजूद है, किसे कहीं और भेज दिया गया, किस रात कौन किस बैरक में सोएगा—यह ऐसी जानकारी नहीं जो लिखकर तीन दिन बाद ऊपर पहुँचाई जाए और तब भी सच रहे। उसे हमारे जवानों तक तभी पहुँचना है जब वह सच हो। वरना पहुँचते-पहुँचते बेकार हो चुकी होती है।”</p>\n<p>विक्रम ने धीरे से कहा—</p>\n<p>“तो वह यह मुझे देगा। किसी और को नहीं।”</p>\n<p>“ठीक यही।”</p>\n<p>कामथ की नज़र उस पर टिकी रही।</p>\n<p>“रेडियो पर किसी अनजान आवाज़ को नहीं। किसी ऐसे इंसान को नहीं जिसके पास तुम्हारा अधिकार तो हो, पर तुम्हारा चेहरा न हो। सिर्फ तुम्हें। इतने पास खड़े होकर कि जिस पल जानकारी सच हो, तुम उसे उसके हाथ से लो और सीधे उन जवानों तक ले जाओ जो कार्रवाई के लिए तैयार बैठे हैं। गिनती फिर बदलने से पहले।”</p>\n<p>एक पल।</p>\n<p>“इसीलिए यह काम पैरा एसएफ़ को नहीं दिया जा रहा, चाहे वे कितने भी काबिल हों। वे वह कैंप एक दोपहर में साफ़-सुथरे ढंग से उधेड़ सकते हैं, और उसी में उस इकलौते इंसान को खो देंगे जो उस कैंप के भीतर ठीक उसी पल जानता है कि किसे ख़त्म करना ज़रूरी है और किसे अब भी बचाया जा सकता है।”</p>\n<p>उसने धीमे से कहा—</p>\n<p>“ऐसा भरोसा किसी रेजिमेंट के बिल्ले तक नहीं जाता। वह सिर्फ उस चेहरे तक जाता है, जिस पर वह पहले ही यकीन कर चुका हो।”</p>\n<p>विक्रम कुछ देर चुप रहा। बात को अपने भीतर पूरी तरह बैठ जाने दिया।</p>\n<p>“समझ गया।”</p>\n<p>कामथ ने आख़िर फाइल बंद कर दी।</p>\n<p>फिर कुछ क्षण विक्रम को देखता रहा।</p>\n<p>“परसों सुबह रिपोर्ट करना है।”</p>\n<p>“जी।”</p>\n<p>विक्रम उठने लगा।</p>\n<p>“विक्रम।”</p>\n<p>वह रुका।</p>\n<p>कामथ की आवाज़ बदल गई थी।</p>\n<p>बहुत नहीं।</p>\n<p>बस इतनी कि विक्रम ने वापस उसकी तरफ देखा।</p>\n<p>“घर जाओ।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>“कल का दिन घर पर रहो।”</p>\n<p>कामथ ने धीमे कहा।</p>\n<p>“परसों निकलने से पहले घर को ठीक से जागने देना।”</p>\n<p>“ऐसा मत करना कि सबके नाश्ता करने से पहले चुपचाप निकल जाओ।”</p>\n<p>फिर एक छोटा विराम।</p>\n<p>“जो साधारण बातें तुम किसी और, ज़्यादा सुरक्षित दिन के लिए छोड़ देते हो…”</p>\n<p>“आज कह देना।”</p>\n<p>विक्रम उसे देखता रहा।</p>\n<p>कामथ ने शायद उसकी आँखों में आया सवाल पढ़ लिया।</p>\n<p>“मैं यह इसलिए नहीं कह रहा कि मुझे आगे के बारे में कुछ ऐसा पता है जो तुम्हें नहीं पता।”</p>\n<p>उसने बिल्कुल साफ़ कहा।</p>\n<p>“मैंने बस बहुत सालों में इस तरह के कमरों से बहुत से जवानों को बाहर भेजा है।”</p>\n<p>“और कुछ रातों में जिनके बारे में अब भी सोचता हूँ…”</p>\n<p>कामथ की आवाज़ और धीमी हुई।</p>\n<p>“वे हमेशा वही होते हैं जिन्हें लगा था कि साधारण बातें ठीक से कहने के लिए बाद में बहुत वक्त होगा।”</p>\n<p>इतने वर्षों में विक्रम ने कामथ के मुँह से ऐसा कोई वाक्य कभी नहीं सुना था।</p>\n<p>उसने उससे उसका मतलब दोबारा नहीं पूछा।</p>\n<p>कुछ लोगों की नरमी बड़ी मुश्किल से एक बार शब्द बन पाती है।</p>\n<p>उसे दोबारा कहलवाने की कोशिश करो—</p>\n<p>तो वह वहीं मर जाती है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम ने पूरा दिन घर पर बिताया।</p>\n<p>एक सीधा-सा दिन।</p>\n<p>वैसा दिन जिसकी कीमत उसने वर्षों में इसलिए समझी थी क्योंकि वह उसकी ज़िंदगी में अक्सर बिना जल्दी के आता ही नहीं था।</p>\n<p>नाश्ते के बाद किसी समय अदिति उसकी गोद में चढ़ आई और लगभग एक घंटा वहीं रही।</p>\n<p>स्कूल की किसी सहेली की कहानी।</p>\n<p>एक ड्रॉइंग जो उसने बनाई थी।</p>\n<p>किसी टीचर की बात।</p>\n<p>फिर कोई दूसरी बात जो पहली से बिल्कुल जुड़ी नहीं थी—</p>\n<p>लेकिन उसकी अपनी दुनिया में सब एक ही कहानी थी।</p>\n<p>विक्रम बीच-बीच में सवाल पूछता रहा।</p>\n<p>ज़्यादातर उन जगहों पर जहाँ शायद सवाल ज़रूरी भी नहीं था।</p>\n<p>सिर्फ इसलिए कि वह बोलती रहे।</p>\n<p>दोपहर में अर्जुन ने फ़ैसला कर लिया कि उसे पूरे आँगन में पिता के कंधों पर ही घूमना है।</p>\n<p>विक्रम उसे उठाकर चलता रहा।</p>\n<p>हर बार गेट की ऊपरी चौखट के नीचे पहुँचकर जानबूझकर थोड़ा झुकता—</p>\n<p>और हर बार बच्चा ऐसे चीखकर हँसता जैसे वही खेल उसने पहली बार खोजा हो।</p>\n<p>श्रद्धा दरवाज़े पर खड़ी थी, हाथ में कलछी लिए। रसोई में विक्रम की पसंद की दाल चढ़ी थी, जो उसने सुबह किसी को बताए बिना ही चढ़ा दी थी।</p>\n<p>वह कुछ बोली नहीं। बस दोनों को देखती रही।</p>\n<p>एक ऐसा दिन जिसमें पति घर पर था, बच्चे उसके आसपास थे और किसी घड़ी को उनसे जल्दी नहीं थी।</p>\n<p>शायद परिवार की असली दौलत अक्सर इतनी ही साधारण दिखाई देती है।</p>\n<p>जब तक वह पास होती है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस रात चारों एक ही कमरे में सोए।</p>\n<p>चौड़े बिस्तर पर दोनों बच्चे बीच में।</p>\n<p>अदिति की बाँह अपने छोटे भाई की छाती पर पड़ी थी।</p>\n<p>अर्जुन की मुट्ठी कंबल की एक सिलवट पकड़े बंद थी।</p>\n<p>विक्रम बहुत देर तक जागता रहा।</p>\n<p>अँधेरे में तीन लोगों की साँसें सुनता हुआ।</p>\n<p>एक ऐसी आवाज़ जिसे उसने ज़िंदगी भर सुना था—</p>\n<p>और पहली बार सचमुच सुन रहा था।</p>\n<p>श्रद्धा भी जाग रही थी।</p>\n<p>गोद में किताब खुली थी।</p>\n<p>लेकिन एक घंटे से वही पन्ना सामने था।</p>\n<p>“आज आप बहुत चुप हैं।”</p>\n<p>“नींद नहीं आ रही।”</p>\n<p>श्रद्धा ने हल्की रोशनी में उसका चेहरा पढ़ा।</p>\n<p>वर्षों की शादी इंसान को सामने वाले के उन हिस्सों की भाषा भी सिखा देती है जो कभी शब्द नहीं बनते।</p>\n<p>“जो आने वाला है…”</p>\n<p>उसने पूछा—</p>\n<p>“बुरा है क्या?”</p>\n<p>“अभी नहीं जानता।”</p>\n<p>विक्रम ने कहा।</p>\n<p>और जितना उसने कहा, उतना पूरी तरह सच था।</p>\n<p>“पहले से शायद ही कभी बताते हैं।”</p>\n<p>श्रद्धा ने आगे कुछ नहीं पूछा।</p>\n<p>वह वर्षों में सीख चुकी थी कि पति की ज़िंदगी में किन दरवाज़ों पर दस्तक दी जा सकती है—</p>\n<p>और किनके बाहर सिर्फ भरोसा रखकर खड़ा होना पड़ता है।</p>\n<p>उसने अँधेरे में हाथ बढ़ाया।</p>\n<p>विक्रम का हाथ पकड़ लिया।</p>\n<p>और वही कहा जो उनके बीच हमेशा से बाकी हर बात से ज़्यादा ज़रूरी था।</p>\n<p>“मेरे पास वापस आना, विक्रम।”</p>\n<p>उसकी उँगलियाँ उसके हाथ पर थोड़ी कस गईं।</p>\n<p>“बाहर जो भी हो…”</p>\n<p>“इसी गेट से वापस आना।”</p>\n<p>“जितना भी वक्त लगे।”</p>\n<p>“मैं इंतज़ार करूँगी।”</p>\n<p>विक्रम ने उसका हाथ थामे रखा।</p>\n<p>“हमेशा आता हूँ।”</p>\n<p>फिर बहुत धीरे—</p>\n<p>“बहुत पहले इसी आँगन में तुमसे यह वादा किया था।”</p>\n<p>“तब हम दोनों को नहीं पता था कि कभी इसे निभाने की कीमत क्या होगी।”</p>\n<p>उसकी आवाज़ में हल्की मुस्कान थी।</p>\n<p>“अब तोड़ने का इरादा नहीं है।”</p>\n<p>कुछ देर बाद श्रद्धा की साँसें नींद में उतर गईं।</p>\n<p>विक्रम उसका हाथ फिर भी पकड़े रहा।</p>\n<p>उसके शब्द अँधेरे में बार-बार लौटते रहे—जैसे कोई इंसान जेब में पड़े अपने इकलौते सिक्के को उँगलियों में बार-बार पलटता है—यही उसकी सारी पूँजी है—</p>\n<p><b>इसी गेट से वापस आना।</b></p>\n<p>उसने मन में पूरा गेट फिर बनाया।</p>\n<p>एक-एक तख़्ता।</p>\n<p>शाम के समय आँगन में उतरती रोशनी का वही गर्म रंग।</p>\n<p>उसके पीछे कहीं अदिति की हँसी।</p>\n<p>और उसने चुपचाप तय किया—</p>\n<p>कल उसे जहाँ भी ले जाए,</p>\n<p>घर की यही तस्वीर वह अपने साथ रखेगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सुबह उसने किसी को जल्दी नहीं जगाया।</p>\n<p>तीनों को देर तक सोने दिया।</p>\n<p>ख़ुद तैयार होने से पहले काफी देर बिस्तर के पास खड़ा उन्हें देखता रहा—</p>\n<p>श्रद्धा और दोनों बच्चे नींद में एक-दूसरे में उलझे हुए।</p>\n<p>जैसे कोई इंसान किसी ऐसी चीज़ को आँखों में भर रहा हो जिसे पाना उसका हक कभी नहीं था—</p>\n<p>सिर्फ एक नेमत थी।</p>\n<p>श्रद्धा उसके कपड़े पहनते समय जाग गई।</p>\n<p>उसे बताने की ज़रूरत नहीं पड़ी कि अब उनके पास कुछ ही शांत मिनट हैं।</p>\n<p>वह उठकर उसके पास आई।</p>\n<p>विक्रम ने उसे बाँहों में भर लिया।</p>\n<p>इस बार कोई शब्द नहीं थे।</p>\n<p>कहने के लिए कुछ नया बचा भी नहीं था।</p>\n<p>बस दिन की रोशनी में उसका रोज़ वाला वज़न उसके सीने से लगा हुआ—</p>\n<p>और उसकी बाँहें सामान्य सुबह से थोड़ी ज़्यादा कसकर उसके चारों ओर।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>जब विक्रम आँगन पार करके बाहर की तरफ बढ़ा, सूरज दीवार से काफी ऊपर चढ़ चुका था।</p>\n<p>घर में सुबह अपने रोज़ के काम में लग चुकी थी।</p>\n<p>रसोई से कुछ तलने की खुशबू आ रही थी।</p>\n<p>गली में किसी पड़ोसी का रेडियो।</p>\n<p>आँगन में आम, जामुन और कोने का वह नीम, जिन्हें उसके दादा ने दशकों पहले लगाया था—</p>\n<p>ठीक उसी जगह पूरी छाया फैलाए हुए जहाँ वे हर रोज़ इस वक्त फैलाते थे।</p>\n<p>कभी इसी घर में विक्रम ख़ुद बच्चा था।</p>\n<p>इन्हीं पेड़ों पर चढ़ता था।</p>\n<p>तब न कोई वर्दी थी।</p>\n<p>न कोई जंग।</p>\n<p>न कामथ—</p>\n<p>जो उसकी ज़िंदगी को एक दूसरा नाम दे सके।</p>\n<p>वह कभी इन्हीं दीवारों के भीतर छोटा और अधूरा बड़ा हुआ था—</p>\n<p>ठीक वैसे ही जैसे अब उसके अपने बच्चे हो रहे थे।</p>\n<p>और उसके भीतर का कोई हिस्सा आज तक इस बात पर हैरान होना बंद नहीं कर पाया था कि घर इन सब बातों से कितना बेपरवाह रहता है।</p>\n<p>साल गुज़रते हैं।</p>\n<p>वर्दियाँ बदलती हैं।</p>\n<p>लोग आते-जाते हैं।</p>\n<p>और वही आँगन एक और राठौड़ बच्चे को बड़ा करता रहता है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अदिति काफी देर से गेट पर थी।</p>\n<p>नाश्ता कर चुकी थी और सामने फैली पूरी चमकीली सुबह के साथ बेचैन थी।</p>\n<p>वह गेट पर चढ़कर उसे अपने वज़न से आगे-पीछे झुला रही थी।</p>\n<p>हर झूले पर क़ब्ज़े वही पुरानी शिकायत करते।</p>\n<p>उसके नंगे पैर धूल में लकीर खींचते।</p>\n<p>वही गेट—</p>\n<p>जिस पर कभी विक्रम ख़ुद झूलता था।</p>\n<p>एक पूरी उम्र पहले।</p>\n<p>किसी और छोटे लड़के की तरह।</p>\n<p>“आप अभी से जा रहे हो?”</p>\n<p>उसने झूलना बंद नहीं किया।</p>\n<p>“अभी।”</p>\n<p>विक्रम ने चलते गेट से ही उसे उठा लिया।</p>\n<p>ज़रूरत से कुछ पल ज़्यादा बाँहों में रखा।</p>\n<p>उसके बालों की जानी-पहचानी खुशबू साँस में भरी—</p>\n<p>धूल।</p>\n<p>धूप।</p>\n<p>और वही साबुन जो श्रद्धा उसके लिए इस्तेमाल करती थी।</p>\n<p>अदिति ने एक बार उसकी बाँहों में मचलकर उसका कॉलर खींचा।</p>\n<p>जैसे यह सुनिश्चित करना हो कि अब जो कहेगी, वह ठीक से सुन रहा है।</p>\n<p>“वापस आते वक्त मेरे लिए चॉकलेट लाना।”</p>\n<p>“कौन-सी?”</p>\n<p>“सुनहरे रैपर वाली।”</p>\n<p>उसने तुरंत कहा।</p>\n<p>फिर गंभीर होकर—</p>\n<p>“सस्ती वाली नहीं।”</p>\n<p>विक्रम हँस पड़ा।</p>\n<p>पल भर को सीने की सारी सख़्ती पिघल गई।</p>\n<p>“सुनहरे वाली।”</p>\n<p>उसने कहा।</p>\n<p>“पक्का। वादा रहा।”</p>\n<p>श्रद्धा भी तब तक गेट तक आ गई थी।</p>\n<p>पूरी सुबह की रोशनी में वहीं खड़ी रही—</p>\n<p>उस फौजी की पत्नी की स्थिरता के साथ जो यह विदाई पहले भी कई बार कर चुकी हो,</p>\n<p>और फिर भी उसे आसान करना कभी न सीख पाई हो।</p>\n<p>विक्रम अदिति को लेकर आख़िरी कुछ कदम उसके पास आया।</p>\n<p>फिर बेटी को अपनी बाँहों से श्रद्धा की बाँहों में दे दिया।</p>\n<p>“बच्चों का ख़याल रखना।”</p>\n<p>ऊपर से यह सबसे सीधा वाक्य था, जो कोई पति जाते हुए अपनी पत्नी के पास छोड़ सकता है।</p>\n<p>लेकिन उसके भीतर विक्रम ने जैसे वह सब समेट दिया था जो वह उसका ऋणी था—</p>\n<p>इतने छोटे शब्दों में कि दोनों बिना टूटे उन्हें कह और सुन सकें।</p>\n<p>श्रद्धा ने सिर्फ सिर हिलाया।</p>\n<p>अदिति को अपने पास कसकर भींच लिया।</p>\n<p>जवाब देने के लिए उसने अपनी आवाज़ पर भरोसा नहीं किया।</p>\n<p>एक मिनट बाद विक्रम उसी गेट से बाहर निकला।</p>\n<p>सामने देर सुबह की साधारण, बेपरवाह रोशनी थी—</p>\n<p>वैसी ही जैसी किसी भी दूसरे दिन होती।</p>\n<p>उसे नहीं मालूम था कि बिना ऐसा करने का इरादा किए,</p>\n<p>वह लगभग वह सब कह चुका था—</p>\n<p>जो कुछ कहने का मौका ज़िंदगी उसे कभी भी देने वाली थी।</p>"}, {"chapter": 54, "title": "अध्याय 50 — जहाँ वह नहीं पहुँच सका", "content": "<h1>अध्याय 50 — जहाँ वह नहीं पहुँच सका</h1>\n<p>घर से निकलने के अगले ही दिन विक्रम ने उधमपुर के बाहर बने उस साधारण-से कम्पाउंड में रिपोर्ट किया जहाँ टीम इकट्ठी हो रही थी।</p>\n<p>ठंड में बैरकों के ऊपर चीड़ के धुएँ और डीज़ल की गंध नीचे तक ठहरी हुई थी।</p>\n<p>वर्षों हो चुके थे उसे ऐसी ज़मीन पर खड़े हुए, और शरीर ने उसे यह बात एक साथ नहीं, टुकड़ों में याद दिलाई—रकसैक की पट्टी का उस कंधे पर बैठना जो उसका वज़न लगभग भूल चुका था; गन ऑयल और भीगी ऊन की वह मिली-जुली गंध जिसे दिल्ली का कोई दफ़्तर उसकी याद से पूरी तरह मिटा नहीं पाया था।</p>\n<p>असेम्बली हॉल में कुछ चेहरे पहचाने हुए थे।</p>\n<p>एक हवलदार जिसके साथ उसने बरसों पहले ट्रेनिंग की थी, अब कनपटियों पर सफ़ेदी लिए सामने खड़ा था। कमरे के पार दोनों की नज़र मिली तो उसने बस इतना-सा सिर हिलाया कि उसे अभिवादन भी कहा जा सके और आधिकारिक तौर पर कुछ कहा भी न गया हो।</p>\n<p>दो और चेहरे थे जिनके नाम याद आने में विक्रम को कुछ क्षण लगे।</p>\n<p>बाकी ज़्यादातर जवान थे।</p>\n<p>अनजान।</p>\n<p>उनकी आँखों में वही सपाट, परखती हुई उत्सुकता थी जिससे सैनिक अक्सर उस इंसान को देखते हैं जिसका नाम कमरे में उससे पहले पहुँच चुका हो।</p>\n<p>ऑपरेशन को लेफ्टिनेंट कर्नल रुद्र प्रताप सिंह ख़ुद लीड कर रहे थे।</p>\n<p>एक घंटे के भीतर उन्होंने विक्रम को इक्विपमेंट स्टोर्स के पास ढूँढ़ लिया।</p>\n<p>छह साल पहले दोनों एक से ज़्यादा बार दुश्मन की ज़मीन पर साथ चल चुके थे—उस समय, जब दोनों में से किसी के कंधे पर आज वाली रैंक नहीं थी।</p>\n<p>“राठौड़।”</p>\n<p>रुद्र ने बिना जल्दबाज़ी उसे सिर से जूते तक देखा।</p>\n<p>“दिल्ली तुम्हें अच्छा खिला रही है, मेजर।”</p>\n<p>विक्रम ने भौंह उठाई।</p>\n<p>“सर?”</p>\n<p>“पिछली बार जब सामने खड़े होकर देखा था, उससे वज़न बढ़ा है।”</p>\n<p>उनके होंठ के कोने पर सूखी-सी मुस्कान आई।</p>\n<p>“बहुत नहीं।”</p>\n<p>“इतना कि मेरी नज़र में आ गया।”</p>\n<p>फिर उन्होंने बिल्कुल उसी सहजता से कहा—</p>\n<p>“दफ़्तर की कुर्सी इंसान के साथ यही करती है, चाहे वह कभी कितना भी अच्छा क्यों न रहा हो।”</p>\n<p>विक्रम कुछ कहता, उससे पहले रुद्र आगे बोले—</p>\n<p>“फ़िक्र मत करो। इस ज़मीन को फ़र्क़ नहीं पड़ता तुम्हारा वज़न कितना है।”</p>\n<p>“इसे सिर्फ यह देखना है कि एक ख़राब रात के अंत में तुम अब भी क्या कर सकते हो।”</p>\n<p>उनकी आँखों में हल्की चुनौती थी।</p>\n<p>“जल्दी पता चल जाएगा।”</p>\n<p>“यस, सर।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>पहले हफ्ते टीम में किसी को नहीं बताया गया कि आख़िर उन्हें किस इलाके के लिए तैयार किया जा रहा है।</p>\n<p>उस स्तर की तैयारी उस समय तक दर्जन भर संभावित सरहदों में से किसी के लिए भी हो सकती थी।</p>\n<p>असली लक्ष्य आख़िरी दौर में सामने आया—</p>\n<p>कैंप।</p>\n<p>मौलवी।</p>\n<p>और वह ठीक-ठीक रास्ता जिसे पार करके वहाँ पहुँचना था।</p>\n<p>उसी दोपहर सभी फोन जमा करा लिए गए।</p>\n<p>उसके बाद ट्रेनिंग सिर्फ उसी एक टारगेट के इर्द-गिर्द सिमट गई।</p>\n<p>कम्पाउंड के पीछे पथरीली ज़मीन पर पूरे इलाके का छोटा मॉडल तैयार किया गया। हर अप्रोच दोहराई गई। फिर दोबारा। फिर टॉर्च की रोशनी में इतनी बार कि पैरों के नीचे कुचली चीड़ की पत्तियों की गंध भी रास्ते का हिस्सा बन गई।</p>\n<p>अंत में हर जवान को उस रास्ते पर आँखें बंद करके भी चल सकना था—</p>\n<p>बिना आवाज़।</p>\n<p>सिर्फ पैरों की याद से।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस आख़िरी दौर के नौवें दिन, जब फोन दिए हुए काफी समय हो चुका था, ख़बर फिर भी विक्रम तक पहुँच गई।</p>\n<p>वह रिहर्सल के बीच था जब ड्यूटी सिग्नलर उसे ढूँढ़ता हुआ आया।</p>\n<p>“दिल्ली से अर्जेंट है, सर।”</p>\n<p>“नाम से क्लियर हुआ है।”</p>\n<p>छोटे-से साइड रूम तक जाते हुए विक्रम को किसी के कुछ कहने से पहले ही मालूम हो गया कि बात छोटी नहीं होगी।</p>\n<p>इंसान का कोई हिस्सा कभी-कभी दिमाग से पहले जान लेता है।</p>\n<p>रिसीवर उठाते ही दूसरी तरफ कामथ था।</p>\n<p>उसने कोई भूमिका नहीं बाँधी।</p>\n<p>“तुम्हारी बेटी गिर गई है।”</p>\n<p>विक्रम का हाथ रिसीवर पर स्थिर हो गया।</p>\n<p>“सिर पर गंभीर चोट लगी है।”</p>\n<p>एक क्षण।</p>\n<p>“स्कैन में ब्लीड दिखा है। अभी सर्जरी चल रही है।”</p>\n<p>कमरा जैसे अचानक उसके आसपास से आवाज़ खो बैठा।</p>\n<p>रिसीवर पकड़े उसका हाथ बिल्कुल ठंडा पड़ गया।</p>\n<p>वह ठंड कमरे की नहीं थी।</p>\n<p>वह कहीं भीतर से आई थी—</p>\n<p>एक पिता के भीतर की वह असहाय ठंड, जिसे एक ही पल में समझ आ जाए कि ड्यूटी उसे उस एक जगह से कितनी दूर ले आई है जहाँ खड़े होने के लिए वह इस समय दुनिया की कोई भी कीमत दे सकता था।</p>\n<p>विक्रम के सवाल पूछने से पहले कामथ बोला—</p>\n<p>“तुम यह ऑपरेशन छोड़कर नहीं जा सकते।”</p>\n<p>फिर पहली बार उसकी आवाज़ में वह बात आई जो शब्द से ज़्यादा उसके पीछे की चुप्पी में थी।</p>\n<p>“मुझे अफसोस है।”</p>\n<p>“यह कॉल सिर्फ इसलिए दे रहा हूँ ताकि तुम उसकी आवाज़ सुन सको।”</p>\n<p>“इससे ज़्यादा तुम्हें देना मेरे हाथ में नहीं है।”</p>\n<p>अगले ही क्षण लाइन पर श्रद्धा थी।</p>\n<p>दूर।</p>\n<p>बहुत पतली-सी आवाज़, जैसे जाने कितने तारों और कितनी दूरी को पार करके उस छोटे कमरे तक पहुँच रही हो।</p>\n<p>“विक्रम…”</p>\n<p>“मैं हूँ।”</p>\n<p>उसकी आवाज़ तुरंत निकली।</p>\n<p>“कैसी है वो?”</p>\n<p>“अभी सर्जरी में है।”</p>\n<p>श्रद्धा की साँस अटकी।</p>\n<p>उसने उसे सँभाला।</p>\n<p>फिर दोबारा अटक गई।</p>\n<p>“अभी किसी ने कुछ नहीं बताया।”</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>“मैं जानती हूँ तुम नहीं आ सकते।”</p>\n<p>श्रद्धा ने कहा।</p>\n<p>“मुझे बस… इससे पहले कि यह भी मुमकिन न रहे, तुम्हारी आवाज़ सुननी थी।”</p>\n<p>“मुझे माफ़ कर दो, श्रद्धा।”</p>\n<p>“मैं तुम्हारे लिए इसे और मुश्किल बनाने के लिए फोन नहीं कर रही।”</p>\n<p>उसकी आवाज़ किसी तरह टिकी हुई थी।</p>\n<p>बस किसी तरह।</p>\n<p>“तुम घर आओगे तब तक मैं संभाल लूँगी।”</p>\n<p>फिर बहुत हल्के से—</p>\n<p>“हमेशा संभालती हूँ।”</p>\n<p>लाइन बंद होने से पहले विक्रम ने जल्दी से कहा—</p>\n<p>“कामथ।”</p>\n<p>“हाँ।”</p>\n<p>“चौधरी तक ख़बर पहुँचाओ।”</p>\n<p>“उसे गुरुग्राम भेजो।”</p>\n<p>“हो गया।”</p>\n<p>और लाइन कट गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम वह ख़बर अपने साथ वापस रिहर्सल में ले गया।</p>\n<p>क्योंकि इंसान ऐसी चीज़ को और कहाँ रख सकता है?</p>\n<p>उससे सैकड़ों किलोमीटर दक्षिण, मेदांता के किसी वार्ड में उसकी बेटी शायद तब तक सबसे बड़े ख़तरे से बाहर आ चुकी थी—</p>\n<p>या शायद नहीं।</p>\n<p>और उसे कुछ मालूम नहीं था।</p>\n<p>मेदांता।</p>\n<p>वही अस्पताल, जहाँ कभी किसी और बिस्तर के पास उसने रात गुज़ारी थी।</p>\n<p>रातों को वह छत की उस एक दरार को घूरता रहता, जिसे वह अब तक गिन चुका था।</p>\n<p>कभी-कभी मन अपने आप एक बहुत पुरानी बातचीत तक चला जाता—</p>\n<p>एक मेज़।</p>\n<p>उसके सामने नैना के पिता।</p>\n<p>एक अस्पताल जहाँ वे समय पर नहीं पहुँच पाए थे।</p>\n<p>एक घाव जिसे वे दशकों से अपने भीतर उठाए फिरते रहे थे और जिसे उस दिन, बिना ऐसा चाहे, उन्होंने विक्रम के सामने रख दिया था।</p>\n<p>तब विक्रम ने उस कहानी को सुना था।</p>\n<p>अब पहली बार वह उसके भीतर खड़ा था।</p>\n<p>ठीक उसी दूरी पर।</p>\n<p>एक पिता।</p>\n<p>एक अस्पताल।</p>\n<p>और बीच में वर्दी की ऐसी ज़िम्मेदारी जिसे चाहकर भी उतारकर किनारे नहीं रखा जा सकता था।</p>\n<p>उस ठंडी रात में उसे पहली बार समझ आया—</p>\n<p>यह संयोग नहीं था।</p>\n<p>यह विरासत थी।</p>\n<p>कोई पुराना कर्ज जो सालों तक एक हाथ से दूसरे हाथ जाता रहता है और आख़िर उसी बेटे से वसूला जाता है जिसने उस समय वर्दी पहन रखी हो—</p>\n<p>चाहे उसने कभी कितने ही यकीन से क्यों न सोचा हो कि वह अपने से पहले वालों से अलग होगा।</p>\n<p>कि जब उसका समय आएगा—</p>\n<p>वह पहुँच जाएगा।</p>\n<p>विक्रम नहीं पहुँच सका।</p>\n<p>और उस रात उसे पहली बार नैना के पिता का वह पुराना घाव बाहर से नहीं, भीतर से समझ आया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>छह दिन बाद फिर ख़बर आई।</p>\n<p>इस बार विक्रम को सीधे कॉल की इजाज़त नहीं मिली।</p>\n<p>ड्यूटी सिग्नलर ने कामथ का संदेश टुकड़ों में उस तक पहुँचाया।</p>\n<p>अदिति ख़तरे से बाहर थी।</p>\n<p>विक्रम कुछ क्षण उसे देखता रहा।</p>\n<p>“सर… उसे डिस्चार्ज भी कर दिया गया है।”</p>\n<p>उसी सुबह।</p>\n<p>घर भेज दिया गया था।</p>\n<p>चौधरी अस्पताल में ज़्यादातर दिन रहा था, जब तक वहाँ किसी का पहरे पर रहना ज़रूरी था।</p>\n<p>एक लड़ाई वहाँ मोर्चे पर थी।</p>\n<p>एक यहाँ, अस्पताल के गलियारे में।</p>\n<p>यहाँ श्रद्धा अकेली डटी रही। उसे डटना ही था।</p>\n<p>श्रद्धा संभली हुई थी।</p>\n<p>मुश्किल से।</p>\n<p>लेकिन संभली हुई।</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>राहत इतनी तेज़ी से भीतर आई कि एक पल को लगा शरीर में उसके लिए जगह कम पड़ जाएगी।</p>\n<p>उसने उसे पूरा महसूस किया।</p>\n<p>फिर बहुत सावधानी से अपने भीतर एक तरफ रख दिया—</p>\n<p>जैसे इंसान उस चीज़ को रखता है जिसे वह आगे जहाँ जा रहा हो, वहाँ अपने साथ उठाकर नहीं ले जा सकता।</p>\n<p>उसकी बेटी घर पर थी।</p>\n<p>अपने छोटे-से बिस्तर में।</p>\n<p>ठीक होने में जितना भी वक्त बाकी था, कम-से-कम अब उन दीवारों के भीतर होनी थी जो उसे जानती थीं।</p>\n<p>उसके खिलौने वहीं होंगे। उसका तकिया।</p>\n<p>वही आँगन। वही गेट, जिस पर झूलते हुए अदिति ने उससे सुनहरे रैपर वाली चॉकलेट माँगी थी।</p>\n<p>विक्रम ने उस आख़िरी तस्वीर को वहीं रोक दिया।</p>\n<p>अब ऑपरेशन उससे जो भी माँगने वाला था—</p>\n<p>कम-से-कम उस एक खुले डर के साथ नहीं माँगेगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>तीन रात बाद वह मौका आख़िर मिल गया जिसका वे इंतज़ार कर रहे थे।</p>\n<p>मौसम सही था।</p>\n<p>ख़ुफ़िया जानकारी अपनी जगह पर बैठने लगी थी।</p>\n<p>और मौलवी का सिग्नल भी आ गया।</p>\n<p>आधी रात के कुछ देर बाद टीम निकल पड़ी।</p>"}, {"chapter": 55, "title": "अध्याय 51 — आख़िरी ऑपरेशन", "content": "<h1>अध्याय 51 — आख़िरी ऑपरेशन</h1>\n<p>हेलिकॉप्टर उन्हें एलओसी से काफी पहले, अपनी ही तरफ की पहाड़ियों के बीच एक ऐसी ओट में उतारकर लौट गया जहाँ से आगे किसी इंजन की आवाज़ नहीं जा सकती थी। बाकी रास्ता पैदल तय होना था—अँधेरे में, बिना कोई निशान छोड़े, बिना उस रात को यह ख़बर दिए कि कुछ लोग उसकी ख़ामोशी के भीतर से गुज़र रहे हैं।</p>\n<p>रुद्र प्रताप सिंह की आवाज़ पूरे रास्ते कॉम्स पर विक्रम के कान में बनी रही—धीमी, स्थिर और बिना किसी ग़ैरज़रूरी शब्द के। छह साल पहले भी वह इसी आवाज़ के पीछे दुश्मन की ज़मीन पर चला था। तब दोनों जवान थे, रैंक छोटी थीं और शायद यह भ्रम थोड़ा बड़ा कि इंसान हर ऑपरेशन से वैसा ही लौटता है जैसा उसमें गया था।</p>\n<p>सीमा पार करने के बाद रुद्र ने हाथ उठाया।</p>\n<p>“यहीं रुकेंगे। एसेट का कॉल आने तक कोई मूवमेंट नहीं।”</p>\n<p>सब जहाँ थे, वहीं ज़मीन का हिस्सा हो गए।</p>\n<p>रात दो बजे के कुछ बाद सैटेलाइट फोन में हल्की खरखराहट हुई।</p>\n<p>दूसरी तरफ मौलवी हबीबुल्लाह था।</p>\n<p>वर्षों पहले विक्रम ने जिस इंसान तक धीरे-धीरे पहुँच बनाई थी, आज वही इंसान किसी मस्जिद के आसपास अँधेरे में खड़ा अपनी जान की कीमत पर उन्हें रास्ता बता रहा था।</p>\n<p>“कैंप यहाँ से तीन सौ मीटर है। दो घंटे पहले मूवमेंट हुई थी… रोज़ से ज़्यादा।”</p>\n<p>उसकी आवाज़ में घबराहट नहीं थी। उसने गिनती ऐसे बताई जैसे मदरसे के बच्चों की हाज़िरी पढ़ रहा हो—पहले बैरक में करीब चालीस लोग; दूसरे में, जो अब तक हर बार खाली मिला था, लगभग बीस और। उनमें एक शख़्स ऐसा था जिसके सामने बाकी लोगों का बर्ताव बदल जाता था। मौलवी के हिसाब से वह कोई मामूली ट्रेनर नहीं, तंज़ीम का बड़ा कमांडर था।</p>\n<p>दोनों बैरकों पर अब नाइट गार्ड भी थे।</p>\n<p>पहले नहीं थे।</p>\n<p>लाइन कट गई।</p>\n<p>कुछ क्षण तक रुद्र ने कुछ नहीं कहा।</p>\n<p>फिर बहुत हल्के से बोले, “जितना सोचा था, उससे बड़ा है।”</p>\n<p>विक्रम ने उनकी तरफ देखा।</p>\n<p>रुद्र की आँखें अँधेरे में सामने कहीं टिकी थीं।</p>\n<p>“और शायद उससे ज़्यादा कीमती भी। ऐसा कमांडर ऐसे कैंप में बेवजह रात नहीं काटता। आज इसे छोड़ दिया तो यही मौका दोबारा मिले, ज़रूरी नहीं।”</p>\n<p>फ़ैसला वहीं हो गया।</p>\n<p>दस जवान दूसरे, मजबूत बैरक की तरफ। बीस पहले की तरफ।</p>\n<p>“मेरे मार्क पर दोनों रॉकेट साथ जाएँगे। उनके लगते ही बाकी लोग अंदर। उन्हें समझने का वक्त नहीं मिलना चाहिए कि हुआ क्या है।”</p>\n<p>कुछ मिनट बाद मार्क मिला।</p>\n<p>पहले रॉकेट की आवाज़ ने रात को बीच से चीर दिया। नारंगी लकीर अँधेरे में निकली और आँख उसे पूरा पकड़ पाती, उससे पहले सामने वाले बैरक की एक दीवार भीतर बैठ चुकी थी। छत एक पल को ऊपर उठी, जैसे गिरने से पहले ख़ुद को सँभालने की कोशिश कर रही हो, फिर मलबे के साथ नीचे आ गई।</p>\n<p>दूसरा रॉकेट लगभग उसी साँस में दूसरे बैरक से टकराया।</p>\n<p>आग और मलबा रात में ऊपर उछले।</p>\n<p>विक्रम तब तक दौड़ चुका था।</p>\n<p>हथियार सामने था। पैरों के नीचे टूटी ज़मीन थी, मगर अब उसे देखने की ज़रूरत नहीं थी। वर्षों की ट्रेनिंग शरीर के भीतर कहीं इतनी गहरी बैठ जाती है कि कुछ रातों में इंसान सोचता बाद में है, करता पहले है।</p>\n<p>उस समय विक्रम के लिए दुनिया में बस तीन चीज़ें बची थीं—</p>\n<p>सामने की ज़मीन, अगला कदम और लक्ष्य।</p>\n<p>फिर प्लान ख़त्म हो गया और लड़ाई शुरू हुई।</p>\n<p>टूटे हुए दोनों बैरकों से लोग बाहर निकले। कुछ अँधेरे में अंदाज़े से फायर करते हुए, कुछ जान बचाने के लिए भागते हुए। कुछ ही सेकंड में पूरा कम्पाउंड ट्रेसर फायर की उलझी लकीरों, तीन अलग दिशाओं से उठते मज़ल फ्लैश, दो भाषाओं में चिल्लाए जा रहे आदेशों और पास की पत्थर की दीवारों से टकराकर लौटती ऑटोमैटिक फायर की कर्कश आवाज़ से भर गया।</p>\n<p>पहली गोली उसी क्रॉस-फायर में आई।</p>\n<p>विक्रम उसे आते नहीं देख पाया।</p>\n<p>बेल्ट से थोड़ा ऊपर लगी और इतनी ताकत से लगी कि वह पूरा एक कदम बगल में लड़खड़ा गया। गिरने से पहले शरीर ने ख़ुद को वापस खड़ा कर लिया। उसे यह समझने की फुर्सत भी नहीं मिली कि भीतर क्या हुआ है।</p>\n<p>दूसरी गोली लगभग उसी के पीछे आई—पहली से करीब छह इंच ऊपर, पसलियों के पास।</p>\n<p>तीसरी जाँघ में लगी।</p>\n<p>इस बार शरीर आधा घूम गया। घुटना लगभग जवाब दे चुका था, मगर उसने उसे जवाब देने नहीं दिया।</p>\n<p>पहली गोली किसने चलाई थी, वह उसे कभी दिखाई नहीं दिया।</p>\n<p>फिर भी शरीर समझ चुका था।</p>\n<p>तीनों में फ़ैसला वही पहली गोली करने वाली थी।</p>\n<p>लेकिन उस समय मौत भी उसके लिए अगला काम नहीं थी।</p>\n<p>सामने एक मज़ल फ्लैश चमका। विक्रम ने उसी तरफ दो राउंड छोड़े। कोई गिरा। बाद में शायद उसे याद भी न रहता कि उसने किसी इंसान को देखा था या सिर्फ रोशनी को।</p>\n<p>वह आगे बढ़ गया।</p>\n<p>क्योंकि लक्ष्य अभी बाकी था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>ग्यारह मिनट में सब ख़त्म हो गया।</p>\n<p>दोनों ढाँचे साफ़ हो चुके थे। कमांडर मारा जा चुका था। मौलवी की दी हुई गिनती आख़िरी आदमी तक सही निकली।</p>\n<p>वापसी के आख़िरी हिस्से में विक्रम अपने पैरों पर नहीं चल पाया।</p>\n<p>उसे उठाकर हेलिकॉप्टर तक लाया गया।</p>\n<p>ऑल-क्लियर के कुछ ही मिनट बाद हेलिकॉप्टर पहाड़ियों से ऊपर उठ चुका था। भीतर विक्रम रुद्र प्रताप सिंह के पास पट्टों से बँधा था और मेडिक उसके तीन घावों में सबसे ख़राब—बेल्ट के ऊपर वाले—पर लगातार काम कर रहा था। पहली ड्रेसिंग खून से पूरी भीग चुकी थी। उसके ऊपर दूसरी बाँधी गई।</p>\n<p>खून फिर भी रास्ता बना रहा था।</p>\n<p>करीब बीस किलोमीटर निकलने के बाद नीचे सिर्फ पहाड़ बचे—काले, बेनाम, एक-दूसरे में घुलते हुए।</p>\n<p>ऑपरेशन पूरा हो चुका था।</p>\n<p>अब कोई अगला कमरा नहीं था जिसे क्लियर करना हो। कोई अगला आदेश नहीं। कोई अगला कदम नहीं जिसे बाकी हर चीज़ से पहले रखना पड़े।</p>\n<p>कई घंटों में पहली बार उसके दिमाग को ड्यूटी ने खाली छोड़ा।</p>\n<p>और उस खाली जगह में घर चला आया।</p>\n<p>पहले गेट।</p>\n<p>सुबह की हल्की धूसर रोशनी में उस पर झूलती अदिति, पैरों से नीचे की धूल कुरेदती हुई। क़ब्ज़े हर बार उसी पुरानी आवाज़ में शिकायत करते और वह हर झूले के साथ फिर लौट आती। एक हाथ उसे विदा कहने के लिए उठा था, मगर झूलना बंद नहीं हुआ था।</p>\n<p>फिर न जाने कब वह याद सपना बन गई और विक्रम सचमुच घर पहुँच गया।</p>\n<p>वही गेट खुला।</p>\n<p>रसोई से श्रद्धा के हाथ के खाने की महक आई।</p>\n<p>आँगन में शाम की वह सुनहरी रोशनी फैली थी जिसे वह दुनिया के किसी भी देश में, किसी भी उम्र में आँखें बंद करके पहचान सकता था।</p>\n<p>अदिति उसे देखते ही दौड़ी।</p>\n<p>विक्रम उसके बराबर झुक भी नहीं पाया था कि उसकी बाँहें उसके गले तक पहुँच गईं। उसने उसे उठा लिया। सीने पर बेटी का वज़न इतना साफ़ महसूस हुआ कि उस एक क्षण के लिए हेलिकॉप्टर, खून, पट्टियाँ—सब किसी दूसरी ज़िंदगी की चीज़ें लगने लगे।</p>\n<p>उसने उसके सिर पर होंठ रख दिए।</p>\n<p>अदिति हँसी।</p>\n<p>वही खुली, बेफ़िक्र हँसी।</p>\n<p>जैसे दुनिया में कोई ऐसी जगह ही न हो जहाँ उसके पिता उससे दूर जा सकते हों।</p>\n<p>अर्जुन भी आ गया। अभी तीन साल का भी नहीं हुआ था। विक्रम बैठा तो वह बिना पूछे उसके सीने पर चढ़कर जम गया, छोटी मुट्ठियों में पिता का कॉलर पकड़ लिया—उसे क्या पता कि इस आँगन के बाहर दुनिया उसके पिता से क्या-क्या माँगती रही है।</p>\n<p>श्रद्धा दरवाज़े पर खड़ी थी।</p>\n<p>हाथ दुपट्टे से पोंछते हुए।</p>\n<p>चेहरे पर वह मुस्कान जो शायद सिर्फ तब आती थी जब घर से गया हुआ इंसान बिना ख़बर दिए थोड़ा जल्दी लौट आए।</p>\n<p>“आज जल्दी आ गए?”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“आना था।”</p>\n<p>और उसी आवाज़ के पीछे एक दूसरी रात से श्रद्धा की आवाज़ चली आई—</p>\n<p><b>इसी गेट से वापस आना, विक्रम। जितना भी वक्त लगे। मैं इंतज़ार करूँगी।</b></p>\n<p>उस रात उसने बिना सोचे जवाब दिया था—</p>\n<p><b>हमेशा आता हूँ।</b></p>\n<p>कुछ वादे इंसान इसलिए नहीं निभाता कि वे आसान होते हैं, बल्कि इसलिए कि वह उनके टूटने की बात कभी सोचता ही नहीं।</p>\n<p>विक्रम ने भी नहीं सोची थी।</p>\n<p>याद फिर पीछे चली गई।</p>\n<p>इस बार घर वही था, उम्र दूसरी।</p>\n<p>माँ चूल्हे के सामने बैठी बाजरे की रोटियाँ सेंक रही थी। हथेलियों के बीच थपथपाकर रोटी पतली करती, तवे पर डालती और फिर चिमटे से उठाकर सीधी आँच पर फुला देती। लकड़ी के धुएँ और सिकते बाजरे की मिली-जुली महक पूरी रसोई में भरी थी।</p>\n<p>विक्रम अभी बैठा भी नहीं था कि थाली भर चुकी थी—गरम रोटी पर पिघलता ताज़ा मक्खन, साथ में सरसों का साग और हाथ में ठंडी छाछ का लंबा गिलास।</p>\n<p>माँ ने उसे ऊपर से नीचे तक देखा था।</p>\n<p>“दुबला हो गया है।”</p>\n<p>वही शिकायत। वही चिंता।</p>\n<p>“तेरी ये आर्मी तुझे ढंग से खिलाती भी है के नहीं? वहाँ जो मिल गया पेट में डाल लिया, उसे खाना थोड़े कहते हैं।”</p>\n<p>उस दिन उसने बहस नहीं की थी।</p>\n<p>आज भी मन ने कोई जवाब नहीं दिया।</p>\n<p>बस कुछ देर वहीं बैठा रहा—</p>\n<p>माँ की रसोई में।</p>\n<p>जैसे बेटा कभी बड़ा हुआ ही न हो।</p>\n<p>फिर रसोई की महक कहीं खो गई और सामने एक दूसरा आँगन आ गया।</p>\n<p>हाथ में चाय की ट्रे लिए कविता।</p>\n<p>उन दिनों की कविता—उससे पहले की, जब ज़िंदगी ने उसके चेहरे पर वे सारी बातें लिखी भी नहीं थीं जिन्हें बाद में मिटाना किसी के बस में नहीं रहा।</p>\n<p>उन दिनों में बस उस एक दिन चाय डालते समय उसका हाथ हल्का-सा काँपा था—जैसे उसने मन-ही-मन तय कर लिया हो कि किसी दिन इतनी हिम्मत जुटाएगी कि जानबूझकर छलका दे। तश्तरी ज़रूरत से कुछ ज़्यादा भर गई थी।</p>\n<p>और फिर वह नज़र—</p>\n<p>बस एक पल ज़्यादा ठहरी हुई।</p>\n<p>इतना ही।</p>\n<p>कभी-कभी पूरी जवानी याद रखने के लिए ज़िंदगी इंसान को बस इतना ही देती है।</p>\n<p>एक काँपता हाथ।</p>\n<p>चाय की एक तश्तरी।</p>\n<p>और एक नज़र जो समय पर हट नहीं पाई।</p>\n<p>कविता की याद चली गई।</p>\n<p>नैना की याद एकदम से नहीं आई।</p>\n<p>पहले गुलमोहर आया।</p>\n<p>फिर उसके नीचे की बेंच।</p>\n<p>और तब, जैसे उन दोनों चीज़ों के बिना उसका आना पूरा न होता—</p>\n<p>नैना।</p>\n<p>बाकी यादें जैसे आई थीं, वह वैसे नहीं आई। वह सबसे धीरे आई—और आई तो बाकी सब यादों को मिलाकर भी उनसे ज़्यादा देर ठहरी। उसकी पूरी ज़िंदगी की सबसे लंबी याद।</p>\n<p>वही गुलमोहर—कभी सूनी शाखाओं वाला, फिर अचानक फूलों से भर जाने वाला, फिर मौसम बदलते ही दोबारा खाली। उसके नीचे विक्रम का अपना एक पुराना रूप भी खड़ा था—वह विक्रम, जो मान बैठा था कि ज़िंदगी उसे चाहे जहाँ ले जाए, भीतर से वह हमेशा यही रहेगा।</p>\n<p>फिर हाईवे का ढाबा था।</p>\n<p>नैना उँगलियों से रोटी तोड़ रही थी और अपनी नानी की वह बात सुना रही थी कि इंसान कैसे खाता है, उससे भी जाना जा सकता है कि वह कैसा इंसान है।</p>\n<p>और फिर वही बेंच।</p>\n<p>उन दोनों की आख़िरी पूरी शाम।</p>\n<p>तब दोनों में से किसी को नहीं मालूम था कि किसी दिन उसी शाम को याद करते हुए उसके आगे <b>आख़िरी</b> शब्द लगाना पड़ेगा।</p>\n<p>नैना रो रही थी।</p>\n<p>उस पूरे साल में पहली बार इस तरह कि उसने अपने आँसू उससे छिपाने की कोशिश छोड़ दी थी। विक्रम उसके बाल चेहरे से पीछे करता रहा था। शायद तब उसे ऐसा करने का कोई अधिकार नहीं बचा था।</p>\n<p>उसी शाम उसने उससे एक बात कही थी।</p>\n<p>इतनी निजी कि उसके बाद उसने उसे किसी और के सामने कभी नहीं खोला—</p>\n<p><b>इसके बाद मैं जो भी बनूँ, ज़िंदगी मुझे जहाँ भी ले जाए… जिस दिन मैं आख़िर तुम तक दोबारा पहुँचूँगा, तुम्हें यही आदमी मिलेगा। यही विक्रम। अपने भीतर की कोई चीज़ कहीं और देकर नहीं आऊँगा।</b></p>\n<p>फिर रंग बदल गए।</p>\n<p>लाल।</p>\n<p>सोना।</p>\n<p>शादी का हॉल।</p>\n<p>लोग।</p>\n<p>आवाज़ें।</p>\n<p>लेकिन विक्रम का मन वहाँ नहीं था।</p>\n<p>वह अब भी उसी बेंच पर बैठा था।</p>\n<p>कुछ दूरियाँ किलोमीटर में इतनी छोटी होती हैं कि नापी जा सकती हैं।</p>\n<p>और ज़िंदगी में इतनी बड़ी कि पार नहीं होतीं।</p>\n<p>फिर अस्पताल का कमरा आया।</p>\n<p>और काग़ज़ का वह टुकड़ा।</p>\n<p>स्याही नहीं थी उस पर।</p>\n<p>नैना का अपना खून सूखकर तीन पंक्तियाँ बन गया था—</p>\n<p><b>मैं इंतज़ार कर रही हूँ।</b></p>\n<p><b>तुमने वादा किया है कि लौटोगे।</b></p>\n<p><b>ज़िंदा लौटना, विक्रम।</b></p>\n<p>विक्रम उन तीन पंक्तियों को कभी फेंक नहीं पाया।</p>\n<p>क्योंकि उसने उनका जवाब भी कभी नहीं दिया था।</p>\n<p>कम-से-कम शब्दों में नहीं।</p>\n<p>अब, हेलिकॉप्टर की उस लगातार काँपती आवाज़ के बीच, जब शरीर से खून जा रहा था और समय शायद उससे भी तेज़ी से, अचानक उसे एक ऐसी बात समझ आई जिसे समझने में पूरी ज़िंदगी लग गई थी—</p>\n<p>वह इतने साल चुप नहीं रहा था।</p>\n<p>वह जवाब देता रहा था।</p>\n<p>बस लिख नहीं पाया था।</p>\n<p>हर बार जब उसने किसी पुराने प्यार को छोटा कहकर अपने आज को आसान बनाने से इनकार किया था; हर बार जब उसने श्रद्धा को पूरी तरह चुना था; हर बार जब किसी रिश्ते का सच उसके लिए सुविधाजनक नहीं था फिर भी उसने उसे सच ही रहने दिया; हर निभाया हुआ वादा, हर चुपचाप उठाया हुआ बोझ—</p>\n<p>सब मिलकर उन्हीं तीन पंक्तियों का जवाब बनते रहे थे।</p>\n<p>नैना ने कभी तीन पंक्तियाँ लिखी थीं।</p>\n<p>विक्रम को उनका जवाब देने के लिए पूरी ज़िंदगी चाहिए थी।</p>\n<p>और अब ज़िंदगी ख़त्म होने लगी थी।</p>\n<p>उसने पास बैठे रुद्र प्रताप सिंह की तरफ देखा।</p>\n<p>“सर…”</p>\n<p>आवाज़ कमज़ोर थी, मगर उसमें घबराहट नहीं थी।</p>\n<p>“मुझे नहीं लगता मैं इससे बचूँगा।”</p>\n<p>रुद्र तुरंत झुके।</p>\n<p>“ऐसी बात मत करो, मेजर। तुम—”</p>\n<p>“सुन लीजिए, सर।”</p>\n<p>बस इतना।</p>\n<p>डरने के लिए भी वक्त चाहिए होता है। विक्रम के पास अब जितना था, वह उसे किसी और काम में लगाना चाहता था।</p>\n<p>“कुछ वादे किए हैं… छोटे-छोटे। उन्हें पूरा होना चाहिए। मैं न कर पाऊँ तो कोई और कर दे।”</p>\n<p>उसने साँस सँभाली।</p>\n<p>“मेरी बेटी के लिए चॉकलेट ले जाइएगा।”</p>\n<p>होंठों पर बहुत हल्की मुस्कान आई।</p>\n<p>“सुनहरे रैपर वाली। सस्ती वाली नहीं।”</p>\n<p>रुद्र ने कुछ नहीं कहा।</p>\n<p>विक्रम की आँखें उनके चेहरे पर थीं।</p>\n<p>“और… मुझे घर उसी गेट से ले जाइएगा।”</p>\n<p>रुद्र का हाथ उसके कंधे पर और कस गया।</p>\n<p>“श्रद्धा से वादा किया था। उसी गेट से लौटूँगा।”</p>\n<p>एक साँस और।</p>\n<p>“जिस तरह भी लौटूँ… उसी से।”</p>\n<p>कुछ पल वह चुप रहा। फिर जैसे भीतर किसी और पुराने वादे तक पहुँचा।</p>\n<p>“श्रद्धा से कहिएगा, हमारी बेटी को लाउड बड़ा करे।”</p>\n<p>उसने बहुत धीरे कहा—</p>\n<p>“शांत नहीं। सावधान नहीं।”</p>\n<p>और फिर, लगभग अपने आप से—</p>\n<p>“लाउड… जैसी उसे हमेशा होना चाहिए था।”</p>\n<p>नैना का नाम उसने नहीं लिया।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>“और उससे कहिएगा… दोनों बच्चों का ख़याल रखे। जैसे सिर्फ वही रख सकती है।”</p>\n<p>फिर माँ याद आई।</p>\n<p>इस बार उसके चेहरे पर जो मुस्कान आई उसमें मेजर विक्रम राठौड़ नहीं था।</p>\n<p>सिर्फ एक बेटा था।</p>\n<p>“माँ से कहिएगा, उनकी बाजरे की रोटियाँ याद आती थीं।”</p>\n<p>उसने रुद्र की तरफ देखा।</p>\n<p>“हर पोस्टिंग पर।”</p>\n<p>हल्की साँस।</p>\n<p>“यही कहिएगा।”</p>\n<p>रुद्र का जबड़ा कस चुका था।</p>\n<p>“मैं ख़ुद कहूँगा।”</p>\n<p>विक्रम ने आँखें मूँद लीं।</p>\n<p>मगर बात अभी ख़त्म नहीं हुई थी।</p>\n<p>कुछ क्षण बाद उसने फिर आँखें खोलीं।</p>\n<p>“एक और काम है।”</p>\n<p>“बोलो।”</p>\n<p>“एक कर्ज बाकी है।”</p>\n<p>रुद्र झुककर और पास आए।</p>\n<p>“तीन लाइनें।”</p>\n<p>विक्रम की नज़र अब टिकने में मेहनत कर रही थी।</p>\n<p>“किसी को मेरी तरफ से तीन लाइनों का जवाब मिलना है।”</p>\n<p>रुद्र के चेहरे पर सवाल था।</p>\n<p>विक्रम ने उसे पढ़ लिया, मगर समझाने के लिए जितनी कहानी चाहिए थी, उतना समय अब उसके पास नहीं था।</p>\n<p>“पठानिया को बता दीजिएगा।”</p>\n<p>साँस बहुत हल्की हो चुकी थी।</p>\n<p>“वो समझ जाएगा।”</p>\n<p>उसकी उँगलियों ने रुद्र की बाँह पकड़ी।</p>\n<p>बस एक बार।</p>\n<p>“उससे कहिएगा… मेरा कर्ज चुका दे।”</p>\n<p>फिर जैसे वह बात रुद्र से नहीं, कहीं बहुत दूर किसी और से कह रहा हो—</p>\n<p>“मेरा कर्ज चुक जाएगा।”</p>\n<p>इसके बाद यादें भी थक गईं।</p>\n<p>अब जो आया, वह बहुत शांत था।</p>\n<p>वही गेट था।</p>\n<p>सुबह की वही धूसर रोशनी।</p>\n<p>उस पर सात साल का एक बच्चा झूल रहा था—लगभग अदिति जितना।</p>\n<p>पीछे आम और जामुन के पेड़ अपनी शाखाएँ फैलाए खड़े थे। उनके पार वही आँगन था जिसमें कितनी पीढ़ियों के बच्चे बड़े हुए थे और जिसे किसी के जाने से अपना होना बंद करना नहीं आता था।</p>\n<p>विक्रम ने उस बच्चे को देखा।</p>\n<p>उस आख़िरी पल में वह ख़ुद भी नहीं कह सकता था कि किसे देख रहा है।</p>\n<p>अदिति को?</p>\n<p>अपने बचपन को?</p>\n<p>या उस छोटी-सी, साबुत ज़िंदगी को जो एक पीढ़ी से दूसरी पीढ़ी तक पहुँचती रहती है—कभी किसी पिता की बाँहों से बेटी तक, कभी किसी बेटे से उसके बच्चों तक—और इंसान चला भी जाए तो घर में कहीं रह जाती है।</p>\n<p>फिर गेट चला गया।</p>\n<p>आँगन भी।</p>\n<p>आम और जामुन के पेड़।</p>\n<p>सुबह की रोशनी।</p>\n<p>बच्चे की हँसी।</p>\n<p>सब।</p>\n<p>जो बचा, उसमें कोई आवाज़ नहीं थी।</p>\n<p>न गोलियों की।</p>\n<p>न हेलिकॉप्टर की।</p>\n<p>न किसी आदेश की।</p>\n<p>एक बहुत गहरा सन्नाटा था—इतना पूरा कि अब उसमें किसी चीज़ के आने की जगह नहीं थी।</p>\n<p>वह सन्नाटा अब विक्रम का था।</p>\n<p>उससे न कोई कुछ छीन सकता था,</p>\n<p>न उसमें कुछ और भर सकता था।</p>\n<p>बस एक रास्ता अभी बाकी था।</p>\n<p>बहुत लंबा।</p>\n<p>विक्रम से नैना तक—</p>\n<p>जो कहीं बहुत दूर, ग्यारह साल बाद भी यह नहीं जानती थी कि उसके अपने खून से लिखी तीन पंक्तियाँ कभी भुलाई नहीं गईं; कि उनका जवाब तीन पंक्तियों में नहीं आया, क्योंकि शायद तीन पंक्तियाँ उनके लिए कभी काफी थीं ही नहीं; और जो अब भी उस वादे को थामे बैठी थी, जिसे निभाने वाला अब लौट नहीं रहा था।</p>\n<p>वह जवाब उस तक पहुँचेगा या नहीं—</p>\n<p>उस हेलिकॉप्टर में कोई नहीं जानता था।</p>\n<p>रुद्र भी नहीं।</p>\n<p>और विक्रम—</p>\n<p>अब जानने की जगह से बहुत दूर जा चुका था।</p>"}, {"chapter": 56, "title": "अध्याय 52 — जो श्रद्धा कभी नहीं जान पाई", "content": "<h1>अध्याय 52 — जो श्रद्धा कभी नहीं जान पाई</h1>\n<p>हेलिकॉप्टर के रिज लाइन पार करते ही रुद्र प्रताप सिंह ने सिक्योर लिंक खोला।</p>\n<p>“कमांड, दिस इज़ चीता।”</p>\n<p>आवाज़ में वही सपाट अनुशासन था जिसके सहारे इंसान अपने भीतर टूटती किसी चीज़ को थोड़ी देर और टूटने से रोक सकता है—कम-से-कम तब तक, जब तक काम पूरा न हो जाए।</p>\n<p>“टारगेट अचीव्ड। ऑब्जेक्टिव कन्फर्म्ड डिस्ट्रॉयड। उस ग्राउंड से अब कोई थ्रेट नहीं है।”</p>\n<p>इतना कहने के बाद वे कुछ पल चुप रहे। जितनी देर कम्युनिकेशन के लिए ज़रूरी नहीं थी, उससे थोड़ी ज़्यादा। गला रुँध गया। अगला वाक्य बनने से पहले उन्होंने उसे भीतर ही सँभाल लिया।</p>\n<p>“कैज़ुअल्टी साइड पर… वी लॉस्ट विक्टर रोमियो।”</p>\n<p>फिर एक और विराम।</p>\n<p>इस बार छोटा।</p>\n<p>और जानबूझकर।</p>\n<p>“उसके घरवालों को ठीक तरीके से बताया जाए। फोन पर नहीं।”</p>\n<p>रुद्र की आवाज़ और धीमी हो गई।</p>\n<p>“किसी ऐसे इंसान को भेजना जो बात कहते वक्त उनकी आँखों में देख सके।”</p>\n<p>देश के रिकॉर्ड के लिए विक्रम की कहानी लगभग यहीं ख़त्म हो जाती थी।</p>\n<p>एक पूरा इंसान, जिसकी ज़िंदगी को किसी रेडियो लॉग में उसके नाम के दो अक्षरों से ज़्यादा जगह कभी मिली ही नहीं, अब किसी ऐसी फाइल में चुपचाप बंद होने वाला था जिसे खोलने की इजाज़त बहुत कम लोगों को थी।</p>\n<p>उसने क्या किया था, कहाँ किया था, क्यों किया था—देश को उसका पूरा सच कभी बताया ही नहीं जा सकता था।</p>\n<p>उस शाम किसी बड़े चैनल की हेडलाइन में उसके लिए जगह नहीं बनी। इस देश में लगभग हर दिन कहीं न कहीं वर्दी पहने कोई जवान इसी तरह मर रहा था; इसी नियमितता की वजह से विक्रम जैसी कहानी को भी वह एक घंटा कभी नहीं मिला, जिसकी वह हकदार थी।</p>\n<p>एक चैनल ने उसे ग्यारह सेकंड दिए।</p>\n<p>शाम की असली हेडलाइन्स निकल जाने के काफी बाद।</p>\n<p>एंकर ने उसी अभ्यास की हुई हमदर्द आवाज़ में पढ़ा जिसमें कभी मौसम की चेतावनी पढ़ी जाती है, कभी किसी मामूली रेल देरी की ख़बर—</p>\n<p>“आर्मी ने लाइन ऑफ कंट्रोल के पास एक ऑपरेशन में मेजर विक्रम राठौड़ के मारे जाने की पुष्टि की है…”</p>\n<p>कुछ आवाज़ें उस एक वाक्य पर सचमुच धीमी हुईं।</p>\n<p>फिर अगली ख़बर आ गई।</p>\n<p>अगली सुबह कुछ अख़बारों में एक छोटा-सा पैराग्राफ छपा—फ्रंट पेज से बहुत भीतर, किसी सिविक ख़बर और एक विज्ञापन के बीच दबा हुआ। एक दिन बाद गुरुग्राम के एक लोकल पेज ने भी ख़बर उठाई। उसे लिखने वाला शायद कभी राठौड़ परिवार के घर के पास वाले ही स्कूल में पढ़ा था, इसलिए उसने दो-चार पंक्तियाँ कुछ ज़्यादा सम्मान से लिख दीं—वही सम्मान जो कभी-कभी मोहल्ला उस इंसान को दे देता है जिसे बाकी देश ने नोटिस करना लगभग बंद कर दिया हो।</p>\n<p>विक्रम ने क्या किया था और उसकी कीमत क्या थी—</p>\n<p>दुनिया के सामने उसका लगभग पूरा रिकॉर्ड इतना ही रहा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>तीन दिन से श्रद्धा ने विक्रम की आवाज़ नहीं सुनी थी।</p>\n<p>उसने एक बार तय चैनल से पूछा भी था। जवाब मिला—रूटीन कम्युनिकेशन ब्लैकआउट है।</p>\n<p>वर्षों में उसने ऐसे जवाबों पर भरोसा करना सीख लिया था। फौजी की पत्नी होने का एक हिस्सा शायद यही भी था—कुछ चुप्पियों को सवाल बनाए बिना सह लेना, क्योंकि हर बार उनका मतलब ख़तरा नहीं होता।</p>\n<p>और इतने वर्षों में सबसे डरावना मतलब कभी सच निकला भी तो नहीं था।</p>\n<p>उस सुबह दस बजे के कुछ बाद वह रसोई में थी जब बाहर गेट खुलने की आवाज़ आई।</p>\n<p>वही पुरानी चरमराहट।</p>\n<p>हजार बार सुनी हुई।</p>\n<p>और श्रद्धा के भीतर एक उम्मीद बिना पूछे जाग उठी।</p>\n<p>इतने सालों में विक्रम जाने कितनी बार बिना ठीक समय बताए लौटा था। कभी रात में, कभी सुबह, कभी उस समय जब उसे अगले दिन आना था। इसलिए खिड़की तक पहुँचने से पहले ही चेहरे पर मुस्कान का एक बहुत छोटा-सा हिस्सा आ गया—</p>\n<p>बेकार।</p>\n<p>मासूम।</p>\n<p>पुरानी आदत जैसा।</p>\n<p>शायद वह आ गया।</p>\n<p>खिड़की से बाहर देखते ही मुस्कान वहीं रुक गई।</p>\n<p>विक्रम नहीं था।</p>\n<p>आँगन में दो अफसर खड़े थे।</p>\n<p>इस्त्री की हुई वर्दी। चेहरे पर बहुत सँभली हुई ख़ामोशी। वह ख़ामोशी जो सिर्फ उन लोगों के चेहरे पर आती है जो यह काम पहले भी कर चुके हों और हर बार यह जानकर आए हों कि अभ्यास इसे आसान नहीं बनाता।</p>\n<p>दोनों में से लंबा अफसर दरवाज़े तक पहुँचने से पहले ही अपनी कैप उतार चुका था।</p>\n<p>बस उसी क्षण श्रद्धा जान गई।</p>\n<p>दिमाग को अभी बताया नहीं गया था।</p>\n<p>शरीर जान चुका था।</p>\n<p>बाद में उसे याद नहीं रहा कि अफसर ने ठीक-ठीक क्या कहा था।</p>\n<p>कुछ शब्द बचे—</p>\n<p>ऑपरेशन।</p>\n<p>ड्यूटी के दौरान।</p>\n<p>देश आपका आभारी है।</p>\n<p>लेकिन पूरा वाक्य नहीं।</p>\n<p>उसे बस उसके हाथ में घूमती वह कैप याद रही।</p>\n<p>और आँगन में बिखरी सुबह की सुनहरी धूप।</p>\n<p>वही धूप जो रोज़ इसी वक्त वहाँ आती थी।</p>\n<p>न एक रंग कम।</p>\n<p>न एक किरण ज़्यादा।</p>\n<p>जैसे घर की दुनिया में कुछ बदला ही न हो।</p>\n<p>जबकि श्रद्धा जिस ज़िंदगी के भीतर अब तक खड़ी थी, वह उसी सुबह बिना आवाज़ किए दो हिस्सों में बँट चुकी थी—</p>\n<p>एक जिसमें विक्रम था।</p>\n<p>और एक जो अब उसके बिना शुरू हो चुकी थी।</p>\n<p>पता नहीं कितनी देर बाद अदिति ने उसे दरवाज़े पर वैसे ही खड़ा पाया।</p>\n<p>“मम्मा?”</p>\n<p>श्रद्धा ने जवाब देने की कोशिश नहीं की।</p>\n<p>उसे अपनी आवाज़ पर भरोसा नहीं था।</p>\n<p>वह बस घुटनों के बल बैठी, बेटी को अपनी बाँहों में खींच लिया और इतनी मज़बूती से सीने से लगा लिया जैसे उस एक बच्चे को थामे रहना ही अभी पूरी दुनिया को बिखरने से रोकने का आख़िरी तरीका हो।</p>\n<p>उसे लगा, विक्रम भी उस पल अपनी बेटी को ठीक इसी तरह थामना चाहता—अगर इस बात में उससे कुछ पूछा गया होता।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले दिन विक्रम घर लौटा।</p>\n<p>पहले दिल्ली।</p>\n<p>फिर गुरुग्राम।</p>\n<p>पूरे रास्ते तिरंगे में लिपटा हुआ।</p>\n<p>आगे-पीछे आर्मी एस्कॉर्ट था। आगे वाली गाड़ी के खुले हिस्से में जवान बिल्कुल सीधे खड़े थे। जिस वाहन में विक्रम था, उसके दोनों तरफ गेंदे की मोटी मालाएँ लगी थीं; तिरंगे के ऊपर भी ढीली पंखुड़ियाँ बिखरी थीं—रास्ते में किसी ने शायद बिना किसी से पूछे तय कर लिया था कि एक वीर की घर वापसी में झंडा हो तो फूल भी होने चाहिए।</p>\n<p>काफिला गुरुग्राम से बादशाहपुर की तरफ मुड़ा।</p>\n<p>मुख्य सड़क तक पहुँचते-पहुँचते ऐसा लगा जैसे पूरे इलाके को पहले ही ख़बर मिल चुकी थी।</p>\n<p>हजारों लोग थे।</p>\n<p>घर से ख़ुद निकलकर आए हुए।</p>\n<p>किसी बुलावे के बिना।</p>\n<p>गुरुग्राम से बादशाहपुर तक सड़क के दोनों ओर लोग धूप में खड़े थे। मोटरसाइकिलें और कारें अपने आप काफिले के आगे जुड़ती चली गईं। दोपहर के उजाले में भी हेडलाइट्स जल रही थीं और पीछे बनती कतार इतनी लंबी थी कि उसका आख़िरी सिरा दिखाई नहीं देता था।</p>\n<p>कुछ मौकों पर भीड़ को बुलाना नहीं पड़ता।</p>\n<p>लोग ख़ुद समझ जाते हैं कि आज घर के भीतर बैठे रहना ठीक नहीं होगा।</p>\n<p>किसी ने ट्रक पर डीजे लगवा दिया था।</p>\n<p>ऊँचे स्पीकर्स से देशभक्ति के गीत पूरे रास्ते पर फैल रहे थे। लोग साथ गा रहे थे—पूरे गले से, पूरे जोश से। एक दोपहर के लिए हजारों अलग-अलग ज़िंदगियाँ अपने रोज़मर्रा के छोटे दायरों से निकलकर किसी एक बड़े दुख का हिस्सा बन गई थीं।</p>\n<p>देश उसी साँस में शोक भी मना रहा था और गर्व भी कर रहा था।</p>\n<p>शायद सार्वजनिक दुख के पास यही भाषा होती है।</p>\n<p>वह किसी बेटे की मौत को <b>कुर्बानी</b> कहता है।</p>\n<p>उसे दिल से दिया गया बलिदान कहता है।</p>\n<p>क्योंकि हजारों लोगों के सामने खड़े होकर रोने के लिए उसके पास इससे बेहतर शब्द हमेशा नहीं होते।</p>\n<p>श्रद्धा गेट के भीतर खड़ी यह सब देखती रही।</p>\n<p>बाद में वह कभी तय नहीं कर पाई कि वह शोर एक घंटे चला था या पूरी उम्र।</p>\n<p>गीत उसके भीतर नहीं पहुँचे।</p>\n<p>झंडे भी नहीं।</p>\n<p>बाहर हजारों अजनबी उसके पति को अपने हिस्से का शहीद बनाकर रो रहे थे—खुले में, ऊँची आवाज़ में, दिन की पूरी रोशनी के सामने।</p>\n<p>और उनसे बस कुछ कदम दूर खड़ी श्रद्धा समझ रही थी कि उसका अपना दुख इतना निजी, इतना भीतर और इतना शांत हो चुका है कि बाहर का कोई शोर वहाँ तक पहुँच ही नहीं सकता।</p>\n<p>पूरे समय उसका हाथ अदिति के हाथ पर था।</p>\n<p>बाद में उसने देखा तो बच्ची की त्वचा पर उसकी उँगलियों के निशान पड़ गए थे।</p>\n<p>शायद उस पूरे उधार के शोर के बीच यही एक चीज़ थी जिस पर अभी भी उसका बस चलता था—</p>\n<p>उसकी बेटी का हाथ उसके हाथ से न छूटे।</p>\n<p>और आख़िर—</p>\n<p>विक्रम उसी गेट से घर आया।</p>\n<p>जिससे लौटने का वादा करके गया था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अंतिम संस्कार के लिए 18 ग्रेनेडियर्स ने दिल्ली कैंटोनमेंट से अपना कंटिन्जेंट भेजा—वही बटालियन जिसने कभी कारगिल की पहाड़ियों पर अपने चौंतीस जवान खोए थे।</p>\n<p>लेफ्टिनेंट कर्नल रुद्र प्रताप सिंह ख़ुद आए।</p>\n<p>यूनिट के कुछ और अफसर भी साथ थे।</p>\n<p>पूरी रस्म के दौरान रुद्र खड़े रहे—उस तरह, जैसे कभी-कभी किसी इंसान के पास देने को कुछ नहीं बचता तो वह अपनी मौजूदगी दे देता है।</p>\n<p>उसी आँगन में जहाँ विक्रम ख़ुद बड़ा हुआ था, और जहाँ अब उसकी बेटी उसी मिट्टी पर अपना बचपन जी रही थी, श्रद्धा और विक्रम की माँ साथ बैठी थीं।</p>\n<p>अब दोनों में से कोई दूसरी के लिए मजबूत बने रहने की कोशिश नहीं कर रही थी।</p>\n<p>एक ने उसे जन्म दिया था।</p>\n<p>दूसरी ने उसके साथ अपना घर बनाया था।</p>\n<p>दोनों ने उसे अलग-अलग तरह से प्यार किया था, और आज एक ही समय में दोनों उस प्यार की पूरी कीमत समझ रही थीं।</p>\n<p>पता नहीं कब विक्रम की माँ का हाथ श्रद्धा के हाथ तक आया।</p>\n<p>फिर वहीं रह गया।</p>\n<p>दोनों ने कुछ नहीं कहा।</p>\n<p>कहने को बचा भी क्या था?</p>\n<p>जिस बेटे को एक ने बड़ा किया था और जिस इंसान के साथ दूसरी ने ज़िंदगी बाँटी थी, उसके बारे में अब ऐसा कोई दुख नहीं था जिसे एक दूसरी को समझा सकती।</p>\n<p>दोनों पहले से जानती थीं।</p>\n<p>अदिति ज़्यादातर समय माँ के पास खड़ी रही।</p>\n<p>इतनी बड़ी कि समझ सके कुछ बहुत ग़लत हो गया है।</p>\n<p>इतनी छोटी कि यह न समझ सके कि <b>हमेशा के लिए</b> कितनी लंबी चीज़ होती है।</p>\n<p>“सब रो क्यों रहे हैं, मम्मा?”</p>\n<p>उसने एक से ज़्यादा बार पूछा।</p>\n<p>हर बार श्रद्धा के भीतर कोई जवाब बना।</p>\n<p>और होंठों तक पहुँचने से पहले टूट गया।</p>\n<p>हर बार उसने बस बेटी का हाथ थोड़ा और कसकर पकड़ लिया।</p>\n<p>अर्जुन अभी तीन साल का भी नहीं हुआ था।</p>\n<p>उसे इनमें से कुछ भी समझ नहीं आ रहा था।</p>\n<p>लेकिन आख़िर में अग्नि उसी के हाथ से दिलाई गई।</p>\n<p>परंपरा घर में मौजूद सबसे बड़े बेटे से यह माँग रही थी, और उस छोटे बच्चे के अलावा वहाँ कोई ऐसा बेटा नहीं था जिससे वह माँग पूरी हो सकती।</p>\n<p>विक्रम के बड़े भाई ने अर्जुन की छोटी-सी हथेली अपने हाथ में ली।</p>\n<p>उनके अपने हाथ काँप रहे थे।</p>\n<p>उन्होंने बच्चे का हाथ सँभालकर आगे बढ़ाया।</p>\n<p>अर्जुन ने वही किया जो बच्चे तब करते हैं जब चारों तरफ खड़े बड़े लोगों के चेहरे इतने गंभीर हों कि उनकी बात न मानने का ख़याल ही न आए।</p>\n<p>उसे नहीं मालूम था उसने अभी क्या किया है।</p>\n<p>न यह कि एक दिन वह बड़ा होगा—</p>\n<p>और उस एक मासूम हरकत का पूरा अर्थ भी उसके साथ बड़ा होता जाएगा।</p>\n<p>श्रद्धा कुछ कदम दूर खड़ी देखती रही।</p>\n<p>शरीर का हर हिस्सा नज़र फेर लेना चाहता था।</p>\n<p>उसने नहीं फेरी।</p>\n<p>भीतर कोई आख़िरी ज़िद थी—</p>\n<p>अगर विक्रम अपने बेटे को यह करते देखने के लिए यहाँ नहीं हो सकता, तो उन दोनों में से कम-से-कम एक को पूरा देखना होगा।</p>\n<p>आख़िर तक।</p>\n<p>बिना नज़र चुराए।</p>\n<p>ताबूत से तिरंगा उतारा गया।</p>\n<p>पूरी सावधानी से मोड़कर आख़िरी त्रिकोण बनाया गया और एक अफसर ने श्रद्धा के हाथों में रख दिया।</p>\n<p>वह उसकी आँखों में ठीक से नहीं देख पाया।</p>\n<p>श्रद्धा ने झंडा दोनों हाथों में थाम लिया।</p>\n<p>उस तरह जैसे कोई ऐसी चीज़ पकड़ता है जिसे अभी यह तय करने का हक नहीं मिला कि उसे कभी नीचे रखा भी जा सकता है या नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>गुरुग्राम में अपने क्वार्टर में, बादशाहपुर से मुश्किल से दस किलोमीटर दूर, कविता तक वह दिन पहले आवाज़ बनकर पहुँचा—ख़बर बाद में बना।</p>\n<p>खिड़की से भीतर आता एक दूर का, फूलता हुआ शोर। मोटरसाइकिलों के इंजन। कुछ ऐसा, जो संगीत भी हो सकता था। कहीं पास ही जमा होती भीड़।</p>\n<p>वह छोटी-सी बालकनी में निकल आई। इतनी दूर से भी उसे एक जानी-पहचानी सड़क लोगों से भरती दिखाई दी—दोपहर के उजाले में जलती हेडलाइटें, और सारी भीड़ उसी एक गाँव की तरफ बढ़ती हुई, जिसका नाम उसने हफ्तों से अपनी ज़ुबान पर नहीं आने दिया था।</p>\n<p>फोन कब उसके हाथ में आया, उसे पता भी नहीं चला। कुछ ही मिनटों में लोकल चैनल की लाइव स्ट्रीम सामने थी—किसी के फोन से ली गई हिलती हुई तस्वीरें, मगर उनमें कोई शक नहीं था। तिरंगे में लिपटा एक शरीर। गाड़ी के चारों ओर उमड़ती भीड़। और स्क्रीन के बाहर से आती एक आवाज़, जो वह नाम पढ़ रही थी जिसे कभी कविता ने अँधेरे में फोन पर फुसफुसाकर पुकारा था।</p>\n<p>आज ही।</p>\n<p>उसका अंतिम संस्कार।</p>\n<p>इसी वक्त।</p>\n<p>बस दस किलोमीटर दूर—इतना पास कि वह पैदल चलकर पहुँच जाती—और वह अपनी बालकनी में खड़ी उसे हथेली जितनी स्क्रीन पर आते देख रही थी।</p>\n<p>हिलती तस्वीरों के नीचे एक पट्टी चल रही थी—</p>\n<p><b>मेजर विक्रम राठौड़, 9 पैरा एसएफ़, बादशाहपुर—ड्यूटी के दौरान वीरगति को प्राप्त</b></p>\n<p>कविता के भीतर एक पल को सब थम गया। वह उन शब्दों को वैसे देखती रही, जैसे कोई उस दीवार को देखता है जिससे वह अभी-अभी टकराया हो।</p>\n<p>वह बिल्कुल जड़ बैठी रही। साँस अपने आप पूरी नहीं हो रही थी। फोन हाथ में था, पर जैसे भूल गई हो कि हाथ में है।</p>\n<p><i>तुम मर नहीं सकते, विक्रम।</i></p>\n<p>ख़याल सपाट आया—अविश्वास में डूबा हुआ, बिना उस आकार के जो किसी ख़याल का होता है।</p>\n<p><i>तुम्हें अपनी कुर्बानी देने का हक नहीं। अभी नहीं। अभी तो मेरी जंग शुरू ही हुई थी। अभी तो मैंने तय ही किया था कि मेरा बदला कैसा होगा। मैदान छोड़कर जाने का हक तुम्हें नहीं—इससे पहले कि मैं तुमसे किसी एक बात का भी हिसाब ले सकूँ।</i></p>\n<p>पहला आँसू कब गिरा, उसे पता ही नहीं चला।</p>\n<p>पहले चुपचाप।</p>\n<p>फिर बिल्कुल चुपचाप नहीं।</p>\n<p>वह अजनबियों को उसके लिए रोते देख रही थी, जिसे अभी कुछ हफ्ते पहले तक वह पूरी तरह टूटा हुआ देखना चाहती थी।</p>\n<p>उसने स्ट्रीम देखी। फिर देख नहीं पाई। फोन लॉक करके बगल की गद्दी पर उल्टा रख दिया—और बीस मिनट बाद फिर उठा लिया। उससे ज़्यादा देर उसे छोड़ पाना उसके बस में नहीं था। खिड़की के बाहर रोशनी दोपहर के सुनहरेपन से शाम से पहले वाले सपाट धूसर रंग में बदलती रही, और उसे यह ऐसे दूर से महसूस होता रहा, जैसे यह सब उसके साथ नहीं, सिर्फ कमरे के साथ हो रहा हो।</p>\n<p>उसका मन किसी एक आकार में टिक ही नहीं रहा था। कुछ देर गुस्सा आता—पूरा, अपने को सही मानता हुआ। फिर बिना चेतावनी के ढहकर किसी दुख जैसा हो जाता। फिर सख़्त होकर एक ठंडी, संतुष्ट-सी चीज़ बन जाता, जिसे अपने भीतर पहचानना उसे अच्छा नहीं लगा। और फिर पिघलकर एक ऐसी याद बन जाता—इतनी साधारण और इतनी पूरी तरह उसकी अपनी—कि उसे अब भी साथ लिए फिरने पर उसे शर्म आई।</p>\n<p>सर्दियों में सुनहरे हो चुके सरसों के खेत।</p>\n<p>एक होटल की वह दोपहर, जब उसने बार-बार बस उसका नाम लिया था और कुछ नहीं—उसके भीतर का इकलौता शब्द, जिसे समझाने के लिए कभी किसी शब्दकोश की ज़रूरत नहीं पड़ी।</p>\n<p><i>तुम तो आग हो, कविता—पूरी की पूरी आग।</i></p>\n<p>उसने कभी इसे तारीफ समझा था।</p>\n<p>तब उसे नहीं पता था कि जंगल की आग भी आख़िर में सिर्फ राख होती है—और एक झुलसा हुआ खेत, जो इंतज़ार करता है कि कोई उसे बताए, अब उसमें क्या उगेगा।</p>\n<p>काफी देर तक वह ख़ुद से यही कहती रही कि विक्रम और उसके बीच जो कुछ हुआ था, उसकी मौत उससे कुछ मिटा नहीं देती। आख़िर उस रिश्ते को ख़त्म करने का फ़ैसला बहुत पहले उसी ने लिया था। महीनों तक उसने चाहा था कि जिस तरह उसकी ज़िंदगी लहूलुहान हुई, विक्रम की ज़िंदगी भी उसका कुछ स्वाद चखे।</p>\n<p>और फिर उसी के भीतर कहीं वह बहुत पुरानी लड़की भी ज़िंदा थी—</p>\n<p>जिसने कभी एक मानसून को यह जानते हुए भी पूरा प्यार किया था कि मौसम आख़िर बदल जाएगा।</p>\n<p>कविता बार-बार ख़ुद को समझाती रही—</p>\n<p>वह इतनी आसानी से उसे माफ़ नहीं करेगी।</p>\n<p>आज नहीं।</p>\n<p>इतने लंबे समय तक ढोई गई बेइज़्ज़ती, इतने जतन से पाला गया गुस्सा सिर्फ इसलिए ज़मीन पर नहीं रखा जा सकता कि एक ताबूत किसी गेट से गुज़र गया है।</p>\n<p>वह उसके लिए दुखी हो सकती थी।</p>\n<p>माफ़ नहीं करेगी।</p>\n<p>कम-से-कम आज रात नहीं।</p>\n<p>लेकिन रात काफी बीत चुकी थी जब फोन की छोटी-सी स्क्रीन पर चिता ने आग पकड़ी।</p>\n<p>पहले धीरे।</p>\n<p>फिर एक साथ।</p>\n<p>आसपास की भीड़ की आवाज़ भी जैसे उसी के साथ नीचे उतर गई।</p>\n<p>और कविता भी भीतर से शांत पड़ गई।</p>\n<p>गुस्से ने उसे इतने महीनों में जितना शांत नहीं किया था, उससे कहीं ज़्यादा।</p>\n<p>वह जो कुछ शाम भर ख़ुद से कहती रही थी—कि माफ़ नहीं करेगी, कि इतना आसान नहीं होगा—वह सब उस एक असावधान पल में टूट गया।</p>\n<p>जैसे देर तक रोकी हुई साँस को आख़िर शरीर ख़ुद बाहर निकाल देता है।</p>\n<p>उसने स्क्रीन लॉक कर दी।</p>\n<p>हाथ अब भी काँप रहा था।</p>\n<p>फोन को उल्टा करके सीने से लगा लिया और अकेली अपने क्वार्टर में हल्का-सा आगे-पीछे झूलती रही।</p>\n<p>“विक्रम…”</p>\n<p>आवाज़ उसकी अपनी नहीं लगी।</p>\n<p>“मैंने तुम्हें माफ़ किया।”</p>\n<p>शब्द टूटकर निकले।</p>\n<p>बहुत छोटे।</p>\n<p>“तुम भी मुझे माफ़ कर देना…”</p>\n<p>और फिर लगभग फुसफुसाहट में—</p>\n<p>“जहाँ भी हो।”</p>\n<p>वह बहुत देर वैसे ही बैठी रही।</p>\n<p>साँसें छोटी और बेतरतीब आती रहीं।</p>\n<p>जब तक रोने के लिए भी उसके भीतर कुछ बाकी नहीं रहा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>बादशाहपुर में ज़िंदगी ने शोक को भी धीरे-धीरे कामों में बाँटना शुरू कर दिया।</p>\n<p>देश ऐसे मरने वाले जवान के बाद जो कुछ करता है, उसकी अपनी एक बेरहम दक्षता होती है।</p>\n<p>साइटेशन पढ़ा गया—वर्दी पहने एक ऐसे अफसर ने जो विक्रम से कभी मिला तक नहीं था, लेकिन कुछ मिनट उसके बारे में ऐसे बोलता रहा जैसे उसे जानता हो।</p>\n<p>शंकर आया।</p>\n<p>चौधरी आया।</p>\n<p>गेट पर काफी देर खड़ा रहा, फिर कहीं जाकर भीतर आने की हिम्मत जुटा पाया।</p>\n<p>पठानिया भी आया।</p>\n<p>बाकी दोनों से ज़्यादा शांत।</p>\n<p>उस पूरे दिन लगभग कुछ नहीं बोला।</p>\n<p>छोटी डाइनिंग टेबल के पास खाली पड़ी दूसरी कुर्सी के आसपास वह जिस तरह कुछ देर खड़ा रहा—वही कुर्सी जिसके बारे में विक्रम ने उसे कभी कुछ नहीं बताया था—उसे देखकर लगता था कि वह बाकी लोगों से थोड़ा ज़्यादा समझ रहा है कि इस घर में असल में क्या खाली हुआ है।</p>\n<p>कामथ नहीं आया।</p>\n<p>तीन दिन बाद एक पुष्पचक्र पहुँचा।</p>\n<p>कोई कार्ड नहीं।</p>\n<p>कोई नाम नहीं।</p>\n<p>फिर भी श्रद्धा को जाने कैसे समझ आ गया कि वह किसका है।</p>\n<p>शायद कुछ लोग दुख जताना भी उसी तरह सीखते हैं जैसे उन्होंने पूरी ज़िंदगी बाकी सब किया होता है—</p>\n<p>बिना अपना नाम छोड़े।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>चौथे दिन रुद्र प्रताप सिंह फिर आए।</p>\n<p>इस बार वर्दी में नहीं।</p>\n<p>सादे कपड़ों में।</p>\n<p>उन्होंने श्रद्धा और विक्रम की माँ—दोनों से साथ बैठने को कहा।</p>\n<p>छोटे सोफे पर दोनों पास-पास बैठ गईं।</p>\n<p>शायद रुद्र समझते थे कि आज वे जो लेकर आए हैं, उसे इन दोनों में से किसी एक को अकेले नहीं सुनना चाहिए।</p>\n<p>उनकी आवाज़ में उस दिन वह लोहे जैसी कठोरता नहीं थी जिससे लोग उन्हें जानते थे। शुरू से आख़िर तक बहुत नरम रहे, और उस नरमी को बनाए रखना जैसे उन्हें ख़ुद कुछ कीमत दे रहा था।</p>\n<p>कुछ भी कहने से पहले उन्होंने पूछा—</p>\n<p>“बिटिया यहीं है?”</p>\n<p>अदिति को बुलाया गया।</p>\n<p>रुद्र उसके सामने घुटनों के बल बैठ गए।</p>\n<p>जैकेट के भीतर से एक छोटा-सा डिब्बा निकाला।</p>\n<p>सुनहरे काग़ज़ में लिपटा हुआ।</p>\n<p>“ये तुम्हारे पापा ने तुम्हारे लिए भेजी हैं।”</p>\n<p>बच्ची ने उनकी तरफ देखा।</p>\n<p>रुद्र की आवाज़ और धीमी हो गई।</p>\n<p>“उन्होंने खास कहा था—सुनहरे रैपर वाली ही होनी चाहिए।”</p>\n<p>अदिति ने दोनों हाथों से डिब्बा ले लिया।</p>\n<p>चेहरा गंभीर था—बच्चों वाली वह गंभीरता जिसे उन्हें कोई सिखाता नहीं।</p>\n<p>उसे नहीं मालूम था कि दोनों हथेलियों के बीच पकड़ी वह छोटी-सी चीज़ उसके पिता की तरफ से उसके लिए किया गया आख़िरी इंतज़ाम था।</p>\n<p>श्रद्धा देखती रही।</p>\n<p>तिरंगा उसे नहीं तोड़ पाया था।</p>\n<p>चिता नहीं।</p>\n<p>हजारों लोगों का शोर नहीं।</p>\n<p>लेकिन वह छोटा-सा सुनहरा डिब्बा—</p>\n<p>ठीक समय पर घर पहुँची कुछ चॉकलेट्स—</p>\n<p>उसके भीतर उस जगह तक पहुँच गया जहाँ बाकी सब नहीं पहुँच पाए थे।</p>\n<p>एक बहुत मामूली वादा।</p>\n<p>जिस इंसान ने किया था, वह उसे ख़ुद निभाने के लिए ज़िंदा नहीं रहा।</p>\n<p>फिर भी वादा घर पहुँच गया।</p>\n<p>अदिति को बाहर भेज दिए जाने के बाद रुद्र ने श्रद्धा और माँ की तरफ देखा।</p>\n<p>कुछ देर चुप रहे।</p>\n<p>“वह चट्टान था।”</p>\n<p>उन्होंने धीरे से कहा।</p>\n<p>“इससे आपको कोई तसल्ली मिले या न मिले… मैंने ज़िंदगी में बहुत लोगों के साथ सेवा की है। बहुत कम इंसान ऐसे मिले जिन्हें मैं उस तरह चट्टान कह सकूँ जैसे आपका पति… आपका बेटा था।”</p>\n<p>एक क्षण।</p>\n<p>“आख़िर तक।”</p>\n<p>श्रद्धा की उँगलियाँ गोद में इतनी कसकर जुड़ी थीं कि पोर सफ़ेद पड़ चुके थे।</p>\n<p>“उनके साथ हुआ क्या था?”</p>\n<p>रुद्र ने उसकी तरफ देखा।</p>\n<p>श्रद्धा ने फिर कहा—</p>\n<p>“सच में।”</p>\n<p>“वह नहीं जो समारोह में पढ़ा गया।”</p>\n<p>काफी देर तक रुद्र कुछ नहीं बोले।</p>\n<p>उनके सँभले हुए चेहरे के पीछे एक क्षण के लिए अपना दुख भी दिखाई दिया—जैसे वे तय कर रहे हों कि इन दोनों के सामने अपने भीतर का कितना हिस्सा खुलने देना चाहिए।</p>\n<p>फिर उन्होंने सिर हल्का-सा झुका दिया।</p>\n<p>“वह मैं आपको नहीं बता सकता।”</p>\n<p>कुछ क्षण बाद उन्होंने फिर कहा—</p>\n<p>“लेकिन उसके आख़िरी शब्द बता सकता हूँ।”</p>\n<p>उनकी नज़र पहले श्रद्धा पर गई।</p>\n<p>“और उन्हें मैं ठीक वैसे ही कहना चाहता हूँ जैसे उसने कहे थे। इसी कमरे में। आप दोनों के सामने। उसके बाद ही यहाँ से जाऊँगा।”</p>\n<p>रुद्र ने जैसे वे शब्द पूरे रास्ते मन में दोहराए हों, ताकि उनमें से एक भी रास्ते में छूट न जाए।</p>\n<p>“उसने कहा था—अपनी बेटी को लाउड बड़ा करना।”</p>\n<p>श्रद्धा बिल्कुल स्थिर बैठी रही।</p>\n<p>“शांत नहीं। सावधान नहीं।”</p>\n<p>रुद्र की आवाज़ बहुत सावधान थी।</p>\n<p>“लाउड। जैसी उसे हमेशा होना चाहिए था।”</p>\n<p>और फिर—</p>\n<p>“दोनों बच्चों का ख़याल रखना। उस तरह जैसे सिर्फ तुम रख सकती हो।”</p>\n<p>बस उस एक शब्द पर—</p>\n<p><b>लाउड</b>—</p>\n<p>श्रद्धा टूट गई।</p>\n<p>जिस श्रद्धा ने तिरंगा दोनों हाथों में थाम लिया था।</p>\n<p>जिसने चिता देखी थी।</p>\n<p>जिसने हजारों लोगों को अपने पति का नाम पुकारते सुना था।</p>\n<p>वही श्रद्धा उस एक शब्द के सामने हाथ मुँह पर रखकर बैठी रह गई।</p>\n<p>काफी देर तक आवाज़ भी नहीं निकली।</p>\n<p>रुद्र ने उसे सँभालने के लिए कोई शब्द नहीं दिया।</p>\n<p>कुछ दुखों को शब्द देकर छोटा नहीं करना चाहिए।</p>\n<p>वे फिर विक्रम की माँ की तरफ मुड़े।</p>\n<p>इस बार आवाज़ और नरम थी।</p>\n<p>“और आपके लिए, माताजी…”</p>\n<p>बूढ़ी माँ ने उनकी तरफ देखा।</p>\n<p>“उसने कहा था—आपकी बाजरे की रोटियाँ उसे याद आती थीं।”</p>\n<p>रुद्र रुके।</p>\n<p>“हर पोस्टिंग पर।”</p>\n<p>फिर जैसे विक्रम की हिदायत अब भी उनके कान में हो—</p>\n<p>“उसने खास कहा था कि मैं आपको यही बात ठीक इसी तरह बताऊँ।”</p>\n<p>माँ का चेहरा बहुत धीरे से बदल गया।</p>\n<p>तिरंगा जहाँ नहीं पहुँच पाया था।</p>\n<p>चिता जहाँ नहीं पहुँच पाई थी।</p>\n<p>लंबा अंतिम संस्कार जहाँ नहीं पहुँच पाया था—</p>\n<p>वहाँ बाजरे की कुछ रोटियाँ पहुँच गईं।</p>\n<p>उन्होंने रोना शुरू नहीं किया।</p>\n<p>बस एक बार अपना हाथ मुँह पर रखा।</p>\n<p>सिर हिलाया।</p>\n<p>और कुछ क्षण के लिए उनके चेहरे पर सैनिक की माँ नहीं थी।</p>\n<p>वहाँ सिर्फ वह माँ थी जिसने कभी चूल्हे के पास बैठकर एक छोटे लड़के को अपने हाथ से खिलाया था—</p>\n<p>और वह लड़का न जाने कब बड़ा होकर ऐसा इंसान बन गया था जिसे दूसरे जवान <b>चट्टान</b> कहते थे।</p>\n<p>रुद्र कुछ देर दोनों को देखते रहे।</p>\n<p>फिर बोले—</p>\n<p>“बाकी जो बातें मुझे कहने की इजाज़त नहीं है, उन्हें छोड़कर इतना बता सकता हूँ…”</p>\n<p>उन्होंने साँस ली।</p>\n<p>“वह हिचका नहीं था।”</p>\n<p>“और आगे जो भी आया… उसमें वह चुपचाप नहीं गया।”</p>\n<p>इसके कुछ देर बाद रुद्र चले गए।</p>\n<p>शायद उस कमरे में उतनी ही देर रह पाए जितनी देर संदेश पहुँचाने के लिए ज़रूरी थी।</p>\n<p>वे फिर नहीं आए।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले हफ्तों में श्रद्धा ने जाना कि इंसान के चले जाने के बाद उसकी सबसे ज़्यादा कमी हमेशा बड़ी चीज़ों में नहीं मिलती।</p>\n<p>कई बार वह एक कमीज़ मोड़ते हुए मिलती है।</p>\n<p>विक्रम की शर्ट वह अब भी उसी खास तरीके से मोड़ती थी जिस पर वह कभी हँसकर कहता था कि उससे यह काम ज़िंदगी में ठीक से नहीं होगा।</p>\n<p>हर शाम डाइनिंग टेबल पर उसकी कुर्सी भी लगा देती।</p>\n<p>आदत को अभी यह मानना नहीं आया था कि वह विधवा हो चुकी है।</p>\n<p>कुर्सी खाली रहती।</p>\n<p>फिर भी कमरे में उसकी खाली जगह किसी मौजूद चीज़ जितनी साफ़ दिखाई देती।</p>\n<p>देशभक्ति के गीत कुछ ही दिनों में बंद हो गए।</p>\n<p>जैसे हमेशा होते हैं।</p>\n<p>स्पीकर्स उतरे।</p>\n<p>जिस ट्रक पर आए थे, उसी या किसी दूसरे ट्रक में वापस चले गए।</p>\n<p>उस दोपहर सड़क पर खड़े हजारों लोग—जिन्होंने रोया था, गीत गाए थे, इसे दिल से दी गई कुर्बानी कहा था—सब अपनी-अपनी ज़िंदगी में लौट गए।</p>\n<p>अपने खाने की मेज़ों पर।</p>\n<p>अपने बच्चों के पास।</p>\n<p>अपने साबुत परिवारों में।</p>\n<p>श्रद्धा ने उनमें से किसी चेहरे को फिर कभी नहीं देखा।</p>\n<p>कुछ दिन बाद अदिति ने उसकी बाँह खींची।</p>\n<p>उस उम्मीद के साथ जो सिर्फ बच्चे कर सकते हैं—जब कोई चीज़ उन्हें इतनी बड़ी और अद्भुत लगे कि वे मान लें वह फिर ज़रूर होगी।</p>\n<p>“मम्मा… वो सारे लोग फिर आएँगे?”</p>\n<p>श्रद्धा इस सवाल का जवाब भी नहीं दे पाई।</p>\n<p>इसलिए नहीं कि शब्द निकलते हुए टूट जाते।</p>\n<p>बल्कि इसलिए कि वह सचमुच नहीं जानती थी कि सात साल की बच्ची को यह कैसे समझाया जाए—</p>\n<p>कि पूरे देश का दुख कभी-कभी एक दिन के लिए बहुत बड़ा होकर तुम्हारे घर आता है।</p>\n<p>पूरा।</p>\n<p>शोर से भरा।</p>\n<p>तुम्हारे गेट से भीतर तक।</p>\n<p>और फिर चला जाता है।</p>\n<p>क्योंकि किसी दूसरे दिन, किसी दूसरे शहर में, किसी दूसरे घर की बारी आने वाली होती है।</p>\n<p>जिस गेट को उस दिन आधे शहर के लिए खोल दिया गया था, वह अब रोज़ बंद रहने लगा।</p>\n<p>आँगन में अब एक विधवा थी।</p>\n<p>और उसके दो बच्चे।</p>\n<p>अर्जुन अभी पूरी तरह समझ नहीं पाया था कि पापा घर क्यों नहीं आ रहे।</p>\n<p>अदिति शायद उतना समझ गई थी जितना कोई नहीं चाहता था कि इतनी छोटी बच्ची समझे।</p>\n<p>उसने तस्वीरें बनानी शुरू कर दी थीं।</p>\n<p>हर तस्वीर में लगभग वही चीज़ होती—</p>\n<p>एक गेट।</p>\n<p>उससे कुछ दूर खड़ा एक इंसान।</p>\n<p>वह हर बार घर की तरफ आता हुआ दिखाई देता।</p>\n<p>लेकिन दरवाज़े तक कभी नहीं पहुँचता।</p>\n<p>श्रद्धा ने उन तस्वीरों में से एक रसोई के कॉर्कबोर्ड के पास लगा दी।</p>\n<p>कुछ शामों में वह उसे अपनी ज़रूरत से ज़्यादा देर तक देखती रहती।</p>\n<p>गेट।</p>\n<p>आँगन।</p>\n<p>दूर खड़ा इंसान।</p>\n<p>और अपने पति की वह घर-वापसी जो, जहाँ तक श्रद्धा जानती थी, कभी हुई ही नहीं।</p>\n<p>लेकिन अदिति की तस्वीर पूरी तरह ग़लत नहीं थी।</p>\n<p>श्रद्धा को यह कभी नहीं बताया गया।</p>\n<p>और पूरी ज़िंदगी कभी बताया भी नहीं जाएगा।</p>\n<p>वह कभी नहीं जान पाती कि विक्रम को मिले आख़िरी साफ़ क्षणों में—</p>\n<p>वह घर आया था।</p>\n<p>ठीक वैसे ही जैसे उनकी बेटी बार-बार उसे काग़ज़ पर घर लाती थी।</p>\n<p>वही गेट था।</p>\n<p>वही रोशनी।</p>\n<p>और दरवाज़े पर श्रद्धा थी—</p>\n<p>बिना डरी हुई।</p>\n<p>उसका इंतज़ार करती हुई।</p>\n<p>विक्रम सचमुच लौट आया था।</p>\n<p>बस उस आख़िरी जगह पर—</p>\n<p>जहाँ से किसी इंसान को दोबारा बाहर जाने की ज़रूरत नहीं पड़ती।</p>"}, {"chapter": 57, "title": "अंतराल — फाइल का आख़िरी पन्ना", "content": "<h1>अंतराल — फाइल का आख़िरी पन्ना</h1>\n<p>फाइल उसी तरह बंद हुई जैसे ऐसी फाइलें आख़िर एक दिन बंद हो ही जाती हैं—बिना किसी रस्म के, बिना किसी आवाज़ के; उस इंसान के हाथों, जिसकी पूरी नौकरी का एक हिस्सा यही था कि कुछ चीज़ों के बंद होने की आहट बाहर तक न जाए।</p>\n<p>कामथ उस दिन अपने दफ़्तर में अकेला था।</p>\n<p>उसने फाइल पर आख़िरी दस्तख़त ख़ुद किए। हस्ताक्षर करने के बाद कलम रोककर बैठा नहीं रहा, न उन अक्षरों को देर तक देखता रहा। शायद कोई दूसरा इंसान ऐसा करता और उसे सम्मान समझता; कामथ जानता था कि कुछ लोगों के लिए सम्मान का मतलब देर तक काग़ज़ देखते रहना नहीं होता।</p>\n<p>फ़ोल्डर के ऊपर बाईं तरफ जन्म की तारीख़ पहले से दर्ज थी। बरसों पहले किसी क्लर्क ने अपनी सपाट, अभ्यास की हुई लिखावट में लिखी होगी—</p>\n<p><b>15 अगस्त 1992।</b></p>\n<p>दूसरी तारीख़ के लिए कामथ ने किसी क्लर्क को नहीं बुलाया।</p>\n<p>वह उसने ख़ुद लिखी।</p>\n<p>ऊपर दाईं तरफ।</p>\n<p><b>15 अगस्त 2025।</b></p>\n<p>कुछ क्षण दोनों तारीख़ें एक ही फ़ोल्डर पर आमने-सामने पड़ी रहीं।</p>\n<p>जन्म भी पंद्रह अगस्त।</p>\n<p>मृत्यु भी पंद्रह अगस्त।</p>\n<p>बीच में पूरे तैंतीस साल।</p>\n<p>दोनों तरफ वही दिन जिसे देश आज़ादी के नाम से याद करता है।</p>\n<p>संयोग इतना अजीब था कि किसी दूसरी जगह शायद कोई उस पर ठहरता, उसका कोई अर्थ ढूँढ़ता, शायद उसे नियति कह देता। मगर उस दफ़्तर में किसी के पास संयोगों को अजीब मानने की फुर्सत नहीं थी।</p>\n<p>कामथ ने फ़ोल्डर बंद कर दिया।</p>\n<p>फिर उसे उस दराज़ में रख दिया जहाँ से, बहुत मुमकिन था, अब वह कभी बाहर न निकले।</p>\n<p>न कामथ उसे दोबारा खोलता।</p>\n<p>न कभी उसकी कुर्सी पर बैठने वाला अगला अफसर।</p>\n<p>न उसके बाद आने वाला कोई और।</p>\n<p>सिवाय इसके कि शायद कई दशक बाद कोई ऐसा संकट आ जाए जिसका आज वहाँ बैठे किसी इंसान को अंदाज़ा भी न हो—और तेहरान या काबुल में विक्रम का कभी चुपचाप बनाया हुआ कोई एसेट, कोई ऐसा नाम जो फाइल के बाद के पन्नों में अब भी सक्रिय पड़ा हो, अचानक फिर ज़रूरी हो जाए। तब शायद किसी को पुरानी दराज़ों में उतरकर इस फाइल को दोबारा निकालना पड़े।</p>\n<p>वरना नहीं।</p>\n<p>जिस देश ने विक्रम से यह सब माँगा था, उसके हिसाब से यह अंत किसी भी तरह असाधारण नहीं था।</p>\n<p>एक फाइल बंद हुई थी।</p>\n<p>बस।</p>\n<p>देश के किसी दूसरे हिस्से में, किसी दूसरे दफ़्तर की ऐसी ही किसी दराज़ में, शायद उसी दिन किसी और सैनिक की फाइल भी इसी तरह बंद हुई होगी—किसी ऐसे सैनिक की, जिसका नाम भी किसी शाम की न्यूज़ में कभी ठीक से नहीं लिया जाएगा।</p>\n<p>ऐसी खामोशियाँ इस व्यवस्था में अपवाद नहीं थीं।</p>\n<p>वे उसका हिस्सा थीं।</p>\n<p>देश जितने समय से अपने कुछ लोगों से ऐसी ज़िंदगियाँ माँगता आया था, उतने ही समय से कुछ फाइलें इसी तरह बंद होती आई थीं—</p>\n<p>चुपचाप।</p>\n<p>और अगली फाइल के लिए दराज़ में थोड़ी-सी जगह छोड़कर।</p>"}, {"chapter": 58, "title": "अध्याय 53 — एक राज़ जो सौंपा गया, एक जो रखा गया", "content": "<h1>अध्याय 53 — एक राज़ जो सौंपा गया, एक जो रखा गया</h1>\n<p>सुनैना को विक्रम की मौत की ख़बर किसी ने बाकायदा दी नहीं थी।</p>\n<p>उसे पहले ही मालूम हो गया था।</p>\n<p>ऑपरेशन के बाद की उस ख़ामोश दुनिया के वह इतनी करीब थी कि उसके पास ख़बर लगभग घटना के साथ ही पहुँच गई—उस एंकर की आवाज़ से बहुत पहले, जिसने ग्यारह सेकंड में बाकी देश को बताया कि मेजर विक्रम राठौड़ अब नहीं रहा।</p>\n<p>उसके बाद पूरे दो महीने सुनैना ने यह बात किसी से नहीं कही।</p>\n<p>न नैना से।</p>\n<p>न किसी ऐसे इंसान से जिसके सामने कह देने भर से शायद उसका अपना बोझ थोड़ा हल्का हो जाता।</p>\n<p>कामथ के लोगों ने उसे वर्षों में बहुत कुछ सिखाया था। उनमें एक हुनर यह भी था कि जो बात सबसे ज़्यादा भीतर उतर जाए, उसे चेहरे तक न आने दिया जाए; उसे अपने ही किसी बंद हिस्से में तह करके रख दिया जाए और रोज़मर्रा की ज़िंदगी उसके ऊपर से वैसे ही चलती रहे जैसे वहाँ कुछ रखा ही न हो।</p>\n<p>विक्रम की मौत भी उसने वहीं रख दी।</p>\n<p>अकेले।</p>\n<p>बिना किसी घोषणा के।</p>\n<p>दो महीने बाद एक दिन उसने कामथ को फोन किया।</p>\n<p>उसने हालचाल नहीं पूछा।</p>\n<p>“उसकी पत्नी को जानने का हक है कि उसका पति असल में था क्या।”</p>\n<p>दूसरी तरफ कुछ क्षण चुप्पी रही।</p>\n<p>सुनैना ने आगे कहा—</p>\n<p>“वह नहीं जो समारोह में उसे बताया गया। असली विक्रम।”</p>\n<p>कामथ की आवाज़ में कोई हैरानी नहीं आई।</p>\n<p>“उसके पास इसकी मंज़ूरी नहीं है।”</p>\n<p>फिर उसी सपाट लहजे में—</p>\n<p>“और कायदे से तुम्हारे पास भी नहीं है।”</p>\n<p>यह किसी बहस की शुरुआत नहीं थी। वह बस एक नियम बता रहा था—शायद ऐसा नियम जिसे अपनी नौकरी में वह इतने लोगों को बता चुका था कि अब शब्दों को सोचने की ज़रूरत नहीं पड़ती थी।</p>\n<p>“कुछ चीज़ों को वहीं छोड़ देना ज़्यादा रहमदिल होता है, सुनैना। एक मोड़ा हुआ तिरंगा और एक प्रशस्ति-पत्र।”</p>\n<p>उसने बहुत शांत स्वर में कहा—</p>\n<p>“उसे वहीं रहने दो।”</p>\n<p>सुनैना ने आगे बहस नहीं की।</p>\n<p>और आख़िर उसकी बात मानी भी नहीं।</p>\n<p>निर्णय को अपने भीतर पूरी तरह बैठने देने में उसे एक हफ्ता और लगा।</p>\n<p>फिर एक दिन वह सादे कपड़ों में बादशाहपुर पहुँची और उस गेट के सामने खड़ी हो गई जिसे उसने इससे पहले कभी देखा नहीं था—फिर भी पहचानती थी।</p>\n<p>विक्रम के घर और उसके इस गेट का वर्णन उसने बरसों पहले सुना था।</p>\n<p>अब वही गेट उसके सामने था।</p>\n<p>उसने उसे खोला और भीतर चली गई।</p>\n<p>घर में वह मामूली शोर भी नहीं था जो किसी बसे हुए घर में बिना कोशिश के पैदा होता रहता है।</p>\n<p>रेडियो नहीं।</p>\n<p>रसोई से बर्तनों की कोई आवाज़ नहीं।</p>\n<p>किसी कमरे से आती बातचीत नहीं।</p>\n<p>दरवाज़े के पास रखे जूतों में बड़े काले फौजी जूते अब भी वैसे ही रखे थे—पॉलिश किए हुए, जैसे किसी ने उन्हें हर सुबह झाड़ा हो और फिर वहीं रख दिया हो।</p>\n<p>छोटी डाइनिंग टेबल पर सारी कुर्सियाँ करीने से लगी थीं। सबसे सिरे वाली पर कोई नहीं बैठा था, फिर भी वह वहीं रखी थी, जैसे उसे हटाने की किसी की हिम्मत न हुई हो।</p>\n<p>रसोई के कॉर्कबोर्ड पर बच्चे की बनाई एक तस्वीर टँगी थी। एक गेट। और उससे कुछ दूर खड़ा एक इंसान, जो घर की तरफ आ रहा था।</p>\n<p>सुनैना उसे कुछ पल देखती रही। उसे नहीं पता था कि उसके सामने से हट जाना उसे क्यों ठीक लगा।</p>\n<p>आँगन की दूर वाली दीवार के पास बस दोनों बच्चे बैठे थे—एक-दूसरे के करीब, असामान्य रूप से शांत। अर्जुन के हाथ में एक खिलौना ट्रक था, जिसे वह चला नहीं रहा था, बस पकड़े बैठा था। अदिति बार-बार गेट की तरफ देखती और फिर नज़र हटा लेती, जैसे ख़ुद को मना कर रही हो। बच्चों की वह ख़ामोशी जिसमें मासूमियत पूरी तरह ख़त्म नहीं हुई होती, लेकिन चौकन्नापन बहुत जल्दी आ गया होता है; जैसे कुछ ही महीनों में उन्होंने सीख लिया हो कि घर में कोई ऐसी चीज़ बदल गई है जो अब वापस अपनी पुरानी जगह नहीं आने वाली।</p>\n<p>अंदर आधे खुले दरवाज़े से सुनैना को एक बुज़ुर्ग महिला की झलक मिली।</p>\n<p>विक्रम की माँ।</p>\n<p>वे अलमारी से किसी की कमीज़ निकालतीं, उसे तह करतीं, फिर वापस रख देतीं। और फिर निकालतीं।</p>\n<p>अकेली।</p>\n<p>अपने हिस्से का दुख अपने ढंग से उठाती हुईं—और शायद अभी इस हालत में नहीं कि कोई उन्हें वह दुख उठाते हुए देखे।</p>\n<p>दरवाज़ा श्रद्धा ने खोला।</p>\n<p>सामने खड़ी महिला को उसने कभी नहीं देखा था।</p>\n<p>न कोई वर्दी थी जिससे पहचान का सहारा मिलता।</p>\n<p>न कोई परिचित चेहरा।</p>\n<p>बस सादे कपड़ों में खड़ी एक अजनबी महिला, जिसका चेहरा ज़रूरत से कुछ ज़्यादा सँभला हुआ था।</p>\n<p>सुनैना ने पहले कहा—</p>\n<p>“बिना बताए आने के लिए माफ़ कीजिए।”</p>\n<p>फिर एक पल रुककर श्रद्धा की आँखों में देखा।</p>\n<p>“मेरा नाम उतना ज़रूरी नहीं है जितना वह जिसके लिए मैं आई हूँ।”</p>\n<p>“मैं आपके पति के साथ काम करती थी।”</p>\n<p>एक छोटा-सा विराम।</p>\n<p>“आख़िर के दिनों में… काफी करीब से।”</p>\n<p>इतना कहकर वह रुक सकती थी।</p>\n<p>यह आसान आधा सच था।</p>\n<p>लेकिन इतनी दूर वह आधा सच देने नहीं आई थी।</p>\n<p>“और मैं नैना की छोटी बहन हूँ।”</p>\n<p>इस बार चुप्पी श्रद्धा की तरफ से आई।</p>\n<p>सुनैना ने बात पूरी की—</p>\n<p>“उस नैना की, जिसे विक्रम आपसे मिलने से बहुत पहले जानता था।”</p>\n<p>नैना का नाम सुनते ही श्रद्धा का चेहरा ज़रा-सा बदल गया।</p>\n<p>बहुत थोड़ा।</p>\n<p>न नाराज़गी।</p>\n<p>न ईर्ष्या।</p>\n<p>न वह पुराना सवाल जिसे सुनैना शायद वहाँ आते हुए कहीं मन में तैयार करके लाई थी।</p>\n<p>बस एक गहरी, पुरानी-सी स्थिरता।</p>\n<p>जैसे कोई पत्नी बरसों पहले अपने घर के एक भूत से समझौता कर चुकी हो और एक सुबह वही भूत किसी दूसरे चेहरे में उसके दरवाज़े पर आ खड़ा हुआ हो।</p>\n<p>श्रद्धा ने उसे भीतर बुला लिया।</p>\n<p>दोनों बैठीं तो सुनैना ने बात घुमाई नहीं।</p>\n<p>“विक्रम रॉ के लिए काम करता था।”</p>\n<p>श्रद्धा की आँखें उसके चेहरे पर बनी रहीं।</p>\n<p>“कई साल से।”</p>\n<p>“इतने साल से कि उसके बाहर मुट्ठी भर लोगों को ही इसकी पूरी जानकारी थी।”</p>\n<p>सुनैना की आवाज़ धीमी थी, लेकिन उसमें हिचक अब नहीं थी।</p>\n<p>“जिस ऑपरेशन में उसकी जान गई… उसमें उसने वह सरहद पार की थी, जिसके बारे में यह देश आधिकारिक तौर पर कभी नहीं मानेगा कि उसने पार की।”</p>\n<p>उसने श्रद्धा को देखते हुए अगला वाक्य बहुत सँभालकर कहा—</p>\n<p>“आपके पति असल में जो थे, वह उनके अंतिम संस्कार में पढ़े गए साइटेशन से बहुत बड़ा था।”</p>\n<p>कुछ पल बाद—</p>\n<p>“और उससे कहीं ज़्यादा बहादुर भी, जितना उस साइटेशन को कभी कहने की इजाज़त मिल सकती थी।”</p>\n<p>श्रद्धा ने बीच में कोई सवाल नहीं किया।</p>\n<p>वह वैसे ही बैठी रही—दोनों हाथ गोद में जुड़े हुए, उसी तरह जैसे पिछले कुछ महीनों में हर मुश्किल वाक्य सुनते समय उन्हें जोड़े बैठी थी।</p>\n<p>सुनैना शायद किसी हैरानी का इंतज़ार कर रही थी।</p>\n<p>वह नहीं आई।</p>\n<p>काफी देर बाद श्रद्धा बोली—</p>\n<p>“मुझे हमेशा मालूम था कि उसका एक हिस्सा ऐसा है जो मुझे दिखाया नहीं जा रहा।”</p>\n<p>उसकी आवाज़ में शिकायत नहीं थी।</p>\n<p>बस बहुत थका हुआ सच था।</p>\n<p>“मैंने ख़ुद से बस यह पूछा था कि क्या मुझे सच में वह हिस्सा देखना है।”</p>\n<p>उसने एक क्षण के लिए नज़र नीचे की।</p>\n<p>“और मैंने उस बंद दरवाज़े के साथ जीना सीख लिया।”</p>\n<p>फिर उसने सिर उठाया।</p>\n<p>अब उसकी आँखों में पहले से कुछ ज़्यादा स्थिरता थी।</p>\n<p>“फिर भी…”</p>\n<p>उसने बहुत हल्के से कहा—</p>\n<p>“उसे खोलने के लिए शुक्रिया।”</p>\n<p>आँगन की तरफ उसकी नज़र चली गई।</p>\n<p>दोनों बच्चे अब भी वहीं बैठे थे।</p>\n<p>अभी इतने छोटे कि उनके पिता का पूरा सच उनके हाथ में नहीं रखा जा सकता था। कुछ विरासतें भी शायद उम्र माँगती हैं—उन्हें पाने वाले हाथ पहले थोड़े बड़े होने चाहिए।</p>\n<p>श्रद्धा उन्हें कुछ देर देखती रही।</p>\n<p>फिर बोली—</p>\n<p>“मुझे अपने पति पर गर्व है।”</p>\n<p>वाक्य सुनैना से कहा गया था।</p>\n<p>लेकिन पूरा शायद उससे नहीं।</p>\n<p>जैसे उसका एक हिस्सा उस इंसान तक भी जा रहा हो जो अब उस घर में कहीं दिखाई नहीं देता था।</p>\n<p>“एक दिन ये दोनों बड़े होंगे।”</p>\n<p>“तब जो आपने आज मुझे बताया है, मैं इन्हें बताऊँगी।”</p>\n<p>उसके चेहरे पर पहली बार दुख के नीचे से एक और भाव झलका।</p>\n<p>“इन्हें भी अपने पिता पर गर्व होगा।”</p>\n<p>एक बहुत छोटी साँस।</p>\n<p>“जैसा मुझे अभी है।”</p>\n<p>सुनैना ने जवाब में कुछ नहीं कहा।</p>\n<p>शायद कहने की ज़रूरत नहीं थी।</p>\n<p>कुछ देर बाद वह उठी और उसी गेट से बाहर चली गई जिससे भीतर आई थी।</p>\n<p>मगर बाहर निकलते समय वह अपने साथ वह चीज़ ले जा रही थी जिसकी उसने उम्मीद नहीं की थी—</p>\n<p>श्रद्धा से थोड़ी-सी ईर्ष्या।</p>\n<p>किसी ज़िंदगी की नहीं।</p>\n<p>किसी रिश्ते की भी नहीं।</p>\n<p>सिर्फ उस सहजता की, जिससे श्रद्धा ने कह दिया था—</p>\n<p><b>मुझे अपने पति पर गर्व है।</b></p>\n<p>दो महीने से सुनैना उसी की मौत अपने भीतर लिए घूम रही थी और किसी एक इंसान के सामने भी इतनी सीधी बात नहीं कह पाई थी।</p>\n<p>श्रद्धा ने कह दी।</p>\n<p>बिना किसी पर्दे के।</p>\n<p>बिना अपने दुख को उससे छोटा किए।</p>\n<p>गेट से कुछ दूर पहुँचते-पहुँचते एक दूसरा नाम उसके भीतर उठा।</p>\n<p>नैना।</p>\n<p>इन दो महीनों में दो बार उसने फोन उठाया था।</p>\n<p>दोनों बार नैना को फोन करने के लिए।</p>\n<p>और दोनों बार नंबर डायल करने से पहले रख दिया था।</p>\n<p>जहाँ तक सुनैना जानती थी, उसकी बहन आज भी यही मानती थी कि गुलमोहर और उस बेंच वाला विक्रम दुनिया में कहीं अपनी साधारण-सी ज़िंदगी जी रहा है।</p>\n<p>शायद पत्नी के साथ।</p>\n<p>बच्चों के साथ।</p>\n<p>शायद कभी-कभी पुरानी बातें याद करता हुआ।</p>\n<p>मगर ज़िंदा।</p>\n<p>सुनैना के पास अब उस भ्रम को ख़त्म करने वाला सच था।</p>\n<p>सिर्फ कुछ शब्द कहने थे—</p>\n<p><b>विक्रम नहीं रहा।</b></p>\n<p>लेकिन उसके बाद?</p>\n<p>इतनी बड़ी ख़बर फोन की एक लाइन पार करके बहन तक पहुँचा देना आसान था।</p>\n<p>उसके बाद उस दुख के साथ उसके पास बैठने के लिए वह दूरी कैसे पार करती?</p>\n<p>उस रात नैना किसके सामने टूटती?</p>\n<p>कौन उसके पास होता जब ग्यारह साल पुराना एक नाम अचानक वर्तमान बनकर उसे दूसरी बार छोड़ जाता?</p>\n<p>और सबसे बढ़कर—</p>\n<p>क्या हर सच सिर्फ इसलिए दे देना चाहिए क्योंकि वह सच है?</p>\n<p>श्रद्धा को सच देकर लौटते हुए सुनैना को अपने इस सवाल का जवाब आख़िर मिल गया।</p>\n<p>नैना को वह कभी नहीं बताएगी।</p>\n<p>यह फ़ैसला आसान नहीं था।</p>\n<p>न शायद कभी पूरी तरह हल्का होने वाला था।</p>\n<p>लेकिन पहली बार उसने उसे आधा नहीं, पूरा स्वीकार किया।</p>\n<p>कुछ कहानियाँ सामने लाकर उनका बोझ कम नहीं होता।</p>\n<p>कभी-कभी राज़ बने रहें तो कम-से-कम एक इंसान की ज़िंदगी वैसी ही बनी रह सकती है जैसी वह अब तक उसे समझता आया है।</p>\n<p>सुनैना जानती थी कि इस फ़ैसले की कीमत उसे ख़ुद उठानी होगी।</p>\n<p>शायद सारी ज़िंदगी।</p>\n<p>वह उठा लेगी।</p>\n<p>विक्रम की मौत का दुख अपने भीतर रखकर वह नैना को उस दुख से बचाए रखेगी, जिसमें अब न कोई जवाब बचा था, न कोई मुलाक़ात, न कोई आख़िरी विदाई।</p>\n<p>वह सड़क पर आगे बढ़ गई।</p>\n<p>पीछे वही गेट धीरे से बंद हो गया।</p>\n<p>आज उसने एक घर के भीतर एक राज़ सौंप दिया था।</p>\n<p>और उसी गेट से बाहर निकलते हुए दूसरा—</p>\n<p>हमेशा के लिए अपने पास रख लिया।</p>"}, {"chapter": 59, "title": "अध्याय 54 — वह किताब नहीं, एक खत था", "content": "<h1>अध्याय 54 — वह किताब नहीं, एक खत था</h1>\n<p>पठानिया ने अपनी डाइनिंग टेबल की उस खाली कुर्सी की पूरी कहानी कभी किसी को नहीं बताई थी।</p>\n<p>जिसने भी कभी उस पर ध्यान दिया होगा, उसने अपनी तरफ से कोई साधारण-सा कारण मान लिया होगा। पठानिया ने भी किसी की ग़लतफ़हमी दूर करने की कोशिश नहीं की।</p>\n<p>मगर विक्रम की कहानी लिखते-लिखते, महीनों के दौरान, उसकी अपनी कहानी भी कभी-कभी टुकड़ों में बाहर आ जाती थी।</p>\n<p>कॉलेज के दिनों की एक लड़की। तब भी उतनी ही तेज़, अपनी राह को लेकर उतनी ही अडिग। वह उससे प्यार करती थी—मगर आख़िर में उसने पठानिया के साथ ज़िंदगी बसाने के बजाय सिविल सेवा की परीक्षा को चुना। वह अपनी ज़िंदगी किसी और की दिनचर्या के चारों ओर नहीं बनाना चाहती थी, जबकि उसकी अपनी महत्वाकांक्षाएँ बिल्कुल उलटी दिशा माँग रही थीं।</p>\n<p>अब वह हिमाचल में कहीं एसडीएम थी। कभी-कभार किसी अख़बार में उसका नाम दिखाई दे जाता तो पठानिया उसे पढ़कर आगे बढ़ जाता, फिर जाने किस आदत या किस पुराने हिस्से के कहने पर वापस लौटकर वही नाम एक बार और पढ़ता, और उसके बाद ख़ुद को आगे बढ़ने के लिए मजबूर करता।</p>\n<p>शायद इसीलिए विक्रम की कहानी उसके भीतर इतनी गहराई तक उतरती चली गई थी। वह अपने ढंग से उस कीमत को जानता था, जो इंसान एक अधूरे प्रेम को साथ लिए चुकाता है—जबकि ज़िंदगी उसके बावजूद आगे बढ़ती रहती है। वह जानता था कि किसी नाम को बरसों बाद भी अख़बार में छपे नामों के बीच तलाश लेना क्या होता है—ठीक वैसे ही, जैसे विक्रम इतना कुछ बीत जाने के बाद भी कभी नैना के बारे में पूछ लेता था।</p>\n<p>चाणक्यपुरी की उस लंबी रात को शब्दों में ढालते-ढालते पठानिया लगभग दो सौ पन्ने लिख चुका था। विक्रम की कही हुई बातें अब बिखरे नोट्स नहीं, एक बाकायदा किताब की शक्ल लेने लगी थीं।</p>\n<p>तभी चौधरी का फोन आया।</p>\n<p>उसने जो ख़बर दी, उसके बाद कुछ देर के लिए कमरे की हर चीज़ अपनी जगह होते हुए भी पठानिया से बहुत दूर चली गई।</p>\n<p>विक्रम नहीं रहा था।</p>\n<p>अगले तीन हफ्ते तक पठानिया ने अधूरी पांडुलिपि एक बार भी नहीं खोली।</p>\n<p>वह ख़ुद से कहता रहा कि वह अपने दोस्त का शोक मना रहा है। यह सच भी था।</p>\n<p>मगर उस दुख के नीचे एक लेखक का अपना डर छिपा था। मरे हुए इंसान की कहानी पूरी करने के लिए जिस निर्मम ईमानदारी की ज़रूरत थी, क्या अब भी उसे उसका अधिकार था? वह इंसान अब सामने बैठकर यह नहीं कह सकता था कि यहाँ तुमने मुझे ग़लत समझा, यहाँ यह बात ऐसे नहीं हुई थी। अगर पठानिया से कुछ ग़लत हो गया, तो अब विक्रम न उसे सुधार सकता था—न उसके लिए उसे माफ़ कर सकता था।</p>\n<p>आख़िर उसे फिर से लिखने के लिए श्रद्धा ने कहा।</p>\n<p>फोन उसी ने किया और बस इतना कहा कि विक्रम की कुछ चीज़ें हैं जिन्हें वह किसी और के हाथ भेजने के बजाय ख़ुद उसके हाथों में देना चाहती है।</p>\n<p>पठानिया जब घर पहुँचा तो श्रद्धा उसी छोटे कमरे में उसका इंतज़ार कर रही थी। मेज़ पर दो बंडल रखे थे—एक पुराने कपड़े में लिपटा हुआ, साधारण डोरी से इस तरह बँधा जैसे किसी ऐसी चीज़ को बाँधा जाता है जिसे खोलना कम और सँभालकर रखना ज़्यादा हो; दूसरा उससे पतला था, जिसके काग़ज़ों के किनारे वर्षों तक हाथ लगते रहने से मुलायम पड़ चुके थे।</p>\n<p>श्रद्धा ने दोनों उसकी तरफ सरका दिए।</p>\n<p>“ये उसके थे। दोनों।”</p>\n<p>उसने पुराने कपड़े वाले बंडल पर हाथ रखा।</p>\n<p>“ये अंतिम संस्कार के बाद उसके ट्रंक में बाकी निजी सामान के साथ वापस आया था। नैना के लिए उसके अपने जवाब हैं—कुछ पूरे, ज़्यादातर अधूरे। लिखता रहा, सँभालता रहा… मगर शायद एक भी कभी भेजा नहीं।”</p>\n<p>उसकी उँगलियाँ कपड़े पर ठहरी रहीं।</p>\n<p>“मैंने पहला पढ़ना शुरू किया था। तब मुझे समझ नहीं आया था कि वह क्या है, लेकिन एक पन्ने के भीतर समझ गई और वहीं रुक गई। वह मेरे पढ़ने के लिए लिखा ही नहीं गया था। किसी और के लिए था।”</p>\n<p>फिर उसने दूसरे, पतले बंडल की तरफ हाथ बढ़ाया।</p>\n<p>“और ये नैना के खत हैं। ये हमेशा से इसी घर में थे। हमारी शादी के लगभग शुरू में ही मुझे मिल गए थे। मैंने ख़ुद पाए थे, और फिर इनके साथ अपने ढंग से समझौता कर लिया—जिन सवालों के जवाब मैं सुनना नहीं चाहती थी, उन्हें पूछा ही नहीं।”</p>\n<p>उसने बंडल को हल्के से छुआ।</p>\n<p>“उसने एक भी खत नहीं फेंका। सब रखे।”</p>\n<p>एक पल रुककर उसने कहा—</p>\n<p>“सबसे नीचे पहला वाला है। वही एक पन्ना जो नैना ने अपने खून से लिखा था।”</p>\n<p>उसके बाद कमरे में कुछ देर कोई आवाज़ नहीं हुई।</p>\n<p>“मुझे नहीं पता किताब को उससे क्या चाहिए, पठानिया। किताब को जैसे ज़रूरत हो, वैसे इस्तेमाल करना।”</p>\n<p>दोनों बंडलों पर श्रद्धा का हाथ कुछ क्षण और टिका रहा, जैसे किसी ऐसी चीज़ को आख़िरी बार छू रही हो जो उसकी कभी थी ही नहीं, मगर फिर भी इतने वर्षों से उसके घर और उसकी शादी की चुप्पियों के बीच रखी रही थी; फिर उसने हाथ हटा लिया।</p>\n<p>“उसने मुझे किताब का एक पन्ना भी कभी नहीं दिखाया और मैंने कभी माँगा भी नहीं। लेकिन आख़िर के दिनों में उसने एक बात कही थी—कुछ चीज़ें इंसान पूरी ज़िंदगी उठाए फिरता है, और उन्हें ठीक से नीचे रख देना चाहिए इससे पहले कि उन्हें उठाने वाला ख़ुद न रहे।”</p>\n<p>श्रद्धा ने पठानिया की तरफ देखा।</p>\n<p>“मुझे लगता है वह इसी जवाब की बात कर रहा था।”</p>\n<p>फिर बहुत शांत स्वर में बोली—</p>\n<p>“इसे पूरा करो, पठानिया। ईमानदारी से पूरा करने में जो भी कीमत लगे, लगने दो।”</p>\n<p>कुछ समय बाद लेफ्टिनेंट कर्नल रुद्र प्रताप सिंह ख़ुद पठानिया को ढूँढ़ते हुए उसके घर पहुँचे।</p>\n<p>पठानिया उस चेहरे को अच्छी तरह जानता था। 9 पैरा एसएफ़ के वे पुराने साल, जिनमें वह ख़ुद भी विक्रम और शंकर के साथ रहा था, उन्हें किसी परिचय की ज़रूरत नहीं छोड़ते थे।</p>\n<p>मगर उस दिन रुद्र सादे कपड़ों में उसके दरवाज़े पर खड़े थे, और उनके चेहरे पर एक सैनिक की वह असहजता थी, जिसे ऐसा संदेश पहुँचाना हो जिसकी भाषा की ट्रेनिंग उसे कभी नहीं मिली।</p>\n<p>वे बैठे भी नहीं।</p>\n<p>“आख़िरी कुछ मिनटों में विक्रम ने तुम्हारे लिए एक बात कही थी।”</p>\n<p>पठानिया चुपचाप उसे देखता रहा।</p>\n<p>“कहा था उसका एक कर्ज बाकी है। तीन लाइनें। और कहा—तुम समझ जाओगे कि वह क्या कह रहा है, चाहे मैं न समझूँ।”</p>\n<p>पठानिया को समझने में एक क्षण भी नहीं लगा।</p>\n<p>चाणक्यपुरी की वह पहली लंबी रात उसके भीतर खुल गई—पंद्रह दिन की चुप्पी, नैना, काग़ज़ और अपने खून से लिखी तीन पंक्तियाँ। विक्रम उसे पूरी कहानी पहले ही सुना चुका था और शायद उसी रात पठानिया के भीतर कहीं यह बात भी बैठ गई थी कि किताब ख़त्म होने से पहले उन तीन पंक्तियों का जवाब किसी तरह पूरा होना चाहिए।</p>\n<p>बस तब वह नहीं जानता था कि उसे पूरा कौन करेगा।</p>\n<p>काफी देर तक वह कुछ नहीं बोला; गला भर आया था, उसे सँभालने में कुछ देर लगी।</p>\n<p>फिर उसने कहा—</p>\n<p>“मैं ठीक-ठीक समझता हूँ वह क्या कह रहा था।”</p>\n<p>उसी हफ्ते पठानिया ने विक्रम के वे जवाब पढ़े। अकेले। एक ही बैठक में। आधी रात कब निकल गई, उसे पता तक नहीं चला।</p>\n<p>एक के बाद एक पन्ने खुलते गए—कहीं सिर्फ एक पैराग्राफ और उसके बाद बीच वाक्य में ख़त्म होती बात, कहीं तीन पन्ने, कहीं चार; अलग-अलग वर्षों में लिखे और दोबारा लिखे गए जवाब, जिनमें स्याही बदलती थी, काग़ज़ बदलता था, लिखावट कभी ज़्यादा स्थिर दिखाई देती और किसी बाद के साल में फिर काँपती हुई लौट आती, ऐसी वजह से जिसका कलम से कोई लेना-देना नहीं था।</p>\n<p>एक भी खत कभी भेजा नहीं गया था।</p>\n<p>और हैरानी की बात यह थी कि उनमें कुछ खत पूरे भी थे—शुरू से आख़िर तक, बाकायदा भेजे जा सकने लायक—मगर वे भी उस ट्रंक से बाहर नहीं निकले थे, जैसे खत पूरा कर लेना विक्रम के लिए कभी असली मुश्किल रहा ही न हो; मुश्किल उसे भेज देना था।</p>\n<p>अलग-अलग वर्षों में लिखे उन सारे पन्नों के भीतर, शब्द बदलते रहने के बावजूद, कुछ बातें बार-बार एक ही जगह लौटती थीं—कि उसने कभी पूरी तरह छोड़ा नहीं; कि न कहने की कीमत, कह देने की कीमत से कहीं ज़्यादा रही; और कि उसके भीतर कोई हिस्सा उस जवाब की तैयारी उसी दिन से करता रहा था जिस दिन उसने इतने वर्षों बाद फोन पर अचानक नैना का नाम सुना था।</p>\n<p>रात के दो बजे काफी पीछे छूट चुके थे जब पठानिया ने आख़िरी पन्ना मेज़ पर रखा और अँधेरे में देर तक बैठा रहा।</p>\n<p>अब उसे पहली बार पूरी तरह समझ आया कि उसकी पांडुलिपि अब तक जिस बात को दूर से छूती रही थी, उसका असली आकार कितना बड़ा था। बात सिर्फ इतनी नहीं थी कि विक्रम नैना से प्यार करता था—इतना तो किताब पहले से जानती थी—बात यह थी कि वह प्यार <b>कितना</b> था; एक पूरी ज़िंदगी जैसे चुपचाप नैना की तीन पंक्तियों और उनके उस जवाब के चारों तरफ व्यवस्थित होती चली गई थी जिसे भेजने का हक विक्रम हर गुज़रते साल के साथ जैसे कमाने की कोशिश करता रहा।</p>\n<p>पठानिया उसी हफ्ते फिर पांडुलिपि पर लौट आया और लौटते ही उसे एक और कमी दिखाई दी।</p>\n<p>प्रेम-कहानी अधूरी नहीं थी। वह उसके पास लगभग पूरी थी।</p>\n<p>अधूरे वे साल थे जो उसके बाद आए थे—नैना और विक्रम की कहानी जहाँ रुक गई थी, उसके बाद विक्रम जिस ज़िंदगी में आगे बढ़ा, उसका वह हिस्सा जिसे चाणक्यपुरी की रात भी पूरा नहीं कर पाई थी।</p>\n<p>तभी उसे महीनों पहले लगभग यूँ ही कही विक्रम की एक बात याद आई—नैना की एक छोटी बहन थी, बचपन से तेज़ ज़ुबान वाली, जो दिल्ली में पत्रकारिता या उससे मिलता-जुलता कुछ करती थी।</p>\n<p>उस एक धागे को पकड़कर किसी इंसान तक पहुँचना आसान नहीं था।</p>\n<p>करीब छह हफ्ते लगे।</p>\n<p>बीच में इतने रास्ते बंद हुए कि पठानिया ने गिनना छोड़ दिया।</p>\n<p>आख़िर वह धागा उसे एक ऐसी महिला तक ले गया जो बहुत सावधानी के बाद उससे मिलने को तैयार हुई—शहर के एक शांत हिस्से में, ऐसी जगह जहाँ जाने का दोनों में से किसी के पास कोई और कारण नहीं था।</p>\n<p>पहली मुलाक़ात में उसने अपना असली काम नहीं बताया।</p>\n<p>पठानिया ने पूछा भी नहीं।</p>\n<p>उसने सिर्फ इतना कहा कि वह विक्रम को आख़िर के दिनों में थोड़े समय के लिए, मगर ठीक से, जानती थी; और अपने ढंग से वह भी शायद इस बात का इंतज़ार कर रही थी कि कोई एक दिन सही सवाल पूछता हुआ उसके पास आए।</p>\n<p>मेज़ पर रखी चाय ठंडी हो चुकी थी जब उसने पठानिया से पूछा—</p>\n<p>“आप ये सब लिख ही क्यों रहे हैं?”</p>\n<p>पठानिया ने कुछ क्षण उसे देखा।</p>\n<p>“क्योंकि उसने मुझसे कहा था।”</p>\n<p>फिर हल्की-सी साँस लेकर कहा—</p>\n<p>“उस ढंग से जिसमें उसके जैसा इंसान किसी से कुछ माँगता है—आख़िरी टुकड़ा छोड़कर बाकी सब तुम्हारे सामने रख देता है, फिर भरोसा करता है कि उसके बाद तुम ख़ुद उस टुकड़े को ढूँढ़ने निकलोगे।”</p>\n<p>उस जवाब के बाद सामने बैठी महिला ने जैसे मन-ही-मन उसके पक्ष में फ़ैसला कर लिया।</p>\n<p>अगली दो मुलाक़ातों में उसने जितना दे सकती थी, दिया—अपनी बहन की ज़िंदगी के वे हिस्से जिन्हें पठानिया नहीं जानता था, और विक्रम के साथ बिताई अपनी उस एक शाम की बातें, जिनसे किताब के भीतर छूटी हुई जगह धीरे-धीरे भरने लगी।</p>\n<p>उसने अपना असली नाम कभी नहीं बताया।</p>\n<p>पठानिया ने कभी जानने की कोशिश नहीं की।</p>\n<p>तब तक वह इतना समझ चुका था कि कुछ चुप्पियाँ किसी पांडुलिपि को पूरा करने की ज़रूरत से बहुत बड़ी वजहों से रखी जाती हैं।</p>\n<p>आख़िरी मुलाक़ात के अंत में उस महिला ने कहा—</p>\n<p>“उसे कभी पता नहीं चलना चाहिए कि इनमें से कुछ भी मेरी तरफ से आया है।”</p>\n<p>उसकी आवाज़ में कोई हिचक नहीं थी।</p>\n<p>“आप जो लिखें, जैसे लिखें—अगर वह इसे कभी पाए, तो वैसे पाए जैसे कोई अजनबी किसी चीज़ को अचानक पा लेता है।”</p>\n<p>फिर और साफ़ कहा—</p>\n<p>“मेरे ज़रिए नहीं। कभी नहीं।”</p>\n<p>पठानिया समझ गया कि वह सच छिपाना नहीं चाहती थी; बस इतना चाहती थी कि अगर वह कभी नैना तक पहुँचे, तो उसके हाथों से नहीं।</p>\n<p>पठानिया ने वादा किया।</p>\n<p>और निभाया।</p>\n<p>उसने एक पुराना वादा भी निभाया—वह जो चाणक्यपुरी के लैम्प की रोशनी वाले कमरे में कहानी शुरू होने से पहले विक्रम ने उससे लिया था।</p>\n<p><b>उसका गाँव कभी नहीं।</b></p>\n<p>पठानिया ने तब सिर्फ एक शब्द में हामी भरी थी।</p>\n<p>इसलिए किताब में नैना का गाँव नहीं आया।</p>\n<p>वह जगह भी नहीं जहाँ उसकी शादी हुई थी—गुरुग्राम से लगभग दो सौ किलोमीटर दूर।</p>\n<p>वह शहर भी नहीं जहाँ वह अब रहती थी।</p>\n<p>न कोई नाम।</p>\n<p>न कोई ऐसा सुराग़ जिससे कोई उन जगहों तक पहुँच सके।</p>\n<p>पूरी किताब में वह एक चीज़ ऐसी थी जिस पर फ़ैसला करने का हक पठानिया का कभी था ही नहीं।</p>\n<p>पांडुलिपि लगभग पूरी हो चुकी थी, मगर आख़िरी पन्ने लिखने से पहले कोई छोटी-सी बेचैनी उसे छोड़ नहीं रही थी। कहानी अब पूरी दिखाई देती थी, फिर भी उसका अपना अंत जैसे कहीं और पड़ा था।</p>\n<p>और तब पठानिया ने तय किया कि उसे वह जगह अपनी आँखों से देखनी होगी।</p>\n<p>वही बेंच।</p>\n<p>वही पेड़।</p>\n<p>उस कहानी के शुरू होने के ग्यारह साल बाद।</p>\n<p>उसने ख़ुद से कहा कि वह बस एक ब्योरा जाँचने जा रहा है—लेखक का अपनी किताब के प्रति उतना-सा फर्ज।</p>\n<p>मगर पार्क में कदम रखते ही वह जानता था कि बात सिर्फ इतनी नहीं है।</p>\n<p>लेज़र वैली पार्क, सेक्टर 29, गुरुग्राम इन ग्यारह वर्षों में वैसे ही बदला था जैसे पार्क बदलते हैं—कहीं नई पगडंडियाँ, प्रवेश के पास खेलते बच्चों के चेहरे दूसरे, जहाँ कभी चाट वाला खड़ा होता था वहाँ अब कॉफी की ठेली।</p>\n<p>मगर बेंच वहीं थी।</p>\n<p>उसी कोने में।</p>\n<p>लगभग भुला दी गई।</p>\n<p>सिरे से सिरे तक ठोस सीमेंट की पुरानी बेंच, जिसकी सतह उम्र के साथ खुरदरी और धूसर हो गई थी; एक तरफ लंबी दरार चली गई थी और जहाँ धूप ठीक से नहीं पहुँचती थी वहाँ काई उसके भीतर उतर आई थी। ऊपर धूल और सूखे पत्तों की ऐसी परत जमी थी जिससे लगता था कि अब वहाँ शायद ही कोई बैठता है।</p>\n<p>पठानिया ने जेब से रूमाल निकाला और बिना किसी खास इरादे के बैठने भर की जगह साफ़ करने लगा।</p>\n<p>फिर उसका हाथ रुक गया।</p>\n<p>साफ़ हुई सतह के नीचे एक कोने में दो नाम उभरे थे।</p>\n<p>बहुत हल्के।</p>\n<p>बारिश और धूल ने ग्यारह साल में उनके किनारों को लगभग घिस दिया था।</p>\n<p>बीच में एक छोटा-सा बेढंगा दिल खरोंचा हुआ था।</p>\n<p><b>नैना ♥ विक्रम</b></p>\n<p>पठानिया बहुत देर तक वैसे ही बैठा रहा।</p>\n<p>शाम की हवा ठंडी थी, मगर उसके भीतर से गुज़री सिहरन का उससे कोई लेना-देना नहीं था।</p>\n<p>विक्रम ने इसका ज़िक्र कभी नहीं किया था।</p>\n<p>व्हिस्की के साथ गुज़री उस पूरी लंबी रात में भी नहीं, जब उसने इतने छोटे-छोटे विवरण तक उसके सामने रख दिए थे कि पठानिया को लगा था अब शायद कुछ बचा नहीं।</p>\n<p>तो ये नाम किसने लिखे?</p>\n<p>नैना ने?</p>\n<p>किसी ऐसी दोपहर में जिसके बारे में विक्रम को कभी पता ही नहीं चला?</p>\n<p>या विक्रम ने ख़ुद?</p>\n<p>और पूरी ज़िंदगी बताने के बाद भी यह एक छोटी-सी बात अपने पास रख ली?</p>\n<p>या दोनों ने साथ मिलकर—एक छोटी-सी, निजी शरारत, जिसे किसी ने कभी किसी से कहने लायक नहीं समझा?</p>\n<p>एक ऐसा राज़, जो कहानी को भी नहीं सौंपा गया?</p>\n<p>पठानिया के पास जवाब नहीं था।</p>\n<p>उसने उँगलियाँ उन घिसी हुई लकीरों पर रखीं और पहली बार उसे लगा कि सबसे ईमानदारी से कही गई कहानी भी अपने भीतर कुछ ऐसा बचा सकती है जो किसी दूसरे इंसान को कभी पूरा नहीं मिलता।</p>\n<p>और उसके ऊपर वही गुलमोहर खड़ा था।</p>\n<p>पहचानने में कोई शक नहीं था।</p>\n<p>तना अब पहले से कहीं मोटा था और उम्र ने उसकी छाल में गहरी लकीरें उतार दी थीं, मगर पेड़ लगभग पूरी तरह नंगा था—वह मौसमी नंगापन नहीं जिसके बाद फिर हरियाली लौटने की उम्मीद रहती है, बल्कि कुछ और; बची हुई शाखाएँ धूसर और भुरभुरी-सी, कहीं एक फूल नहीं, एक कली तक नहीं।</p>\n<p>अगर किसी पेड़ को देखकर ऐसा कहा जा सकता, तो वह ऐसा लगता था जैसे उसने कोशिश करना छोड़ दिया हो—</p>\n<p>मगर गिरना अब भी स्वीकार न किया हो।</p>\n<p>साधारण हिसाब से उसे वर्षों पहले काट दिया जाना चाहिए था।</p>\n<p>सार्वजनिक पार्क में सूखी लकड़ी का क्या काम?</p>\n<p>फिर भी वह खड़ा था।</p>\n<p>अपनी ज़मीन का वही छोटा-सा हिस्सा पकड़े हुए।</p>\n<p>जैसे कोई अधूरा काम अब भी बाकी हो जिसे पूरा किए बिना वह जाने को तैयार न हो।</p>\n<p>पठानिया लौटने के लिए मुड़ा ही था कि उसकी नज़र नीचे पड़ी।</p>\n<p>पुराने पेड़ की जड़ों से कुछ दूर, घास के बीच तीन-चार छोटे गुलमोहर उग आए थे।</p>\n<p>घुटने से भी छोटे।</p>\n<p>उनकी पत्तियाँ रास्ते की धूल के बीच इतनी साफ़ हरी थीं कि लगभग ज़िद जैसी लगती थीं।</p>\n<p>शायद पुराने पेड़ के उन्हीं आख़िरी वर्षों के बीजों से, जब उसमें अब भी फूल आते रहे होंगे।</p>\n<p>पठानिया उनके पास बैठ गया।</p>\n<p>एक छोटी-सी, अभी पूरी तरह खुली भी न हुई पत्ती के पास उसकी उँगलियाँ जाकर ठहर गईं।</p>\n<p>और उसी क्षण उसे वह अंत मिल गया जिसकी तलाश में वह इतने समय से शब्दों के भीतर भटक रहा था।</p>\n<p>उसके मन में एक बात आई जिसे वह जानता था कि किताब में साबित नहीं कर सकता।</p>\n<p>इसलिए बाद में उसने उसे पांडुलिपि में नहीं, अपनी निजी नोटबुक में लिखा—</p>\n<p><b>यह बूढ़ा पेड़ मर रहा है, मगर इसने उम्मीद करना नहीं छोड़ा।</b></p>\n<p>उसे लगा, अपने धीमे और बेआवाज़ ढंग से वह गुलमोहर अब भी मानता है कि किसी दिन वे दोनों वापस आएँगे और फिर उसी के नीचे बैठेंगे; और इसीलिए, अपने ख़त्म होने से पहले, उसने उन दोनों की याद इन छोटे पौधों में उतार दी है—ताकि जिस दिन वह इंतज़ार पूरा हो, अगर पुराना पेड़ तब तक न बचे, तो कोई और उसकी जगह खड़ा हो सके।</p>\n<p>शायद कुछ इंतज़ार ऐसे ही बचते हैं।</p>\n<p>पुरानी शाखाओं में नहीं—</p>\n<p>उनके नीचे उग आई उस छोटी-सी हरियाली में, जिसे अभी यह भी नहीं मालूम कि एक दिन उसे किस कहानी की छाँव बनना है।</p>\n<p>पठानिया उसी रात घर लौटा।</p>\n<p>और पांडुलिपि पूरी कर दी।</p>\n<p>आख़िरी बार उसे बंद करते हुए वह जानता था कि एक इंसान शब्दों में जितना कुछ किसी दूसरे को सौंप सकता है, विक्रम लगभग सब सौंप चुका था—हर इक़रार, हर शांत नाकामी, ज़िंदगी का वह पूरा बेपर्दा आकार जो अध्याय-दर-अध्याय ऐसे बाहर आया था जैसे बहुत समय से रोका हुआ पानी आख़िर अपनी सतह ख़ुद ढूँढ़ ले।</p>\n<p>फिर भी कुछ बातें ऐसी थीं जिन्हें विक्रम ने कभी कहा ही नहीं।</p>\n<p>पठानिया से भी नहीं।</p>\n<p>और नैना से तो बिल्कुल नहीं।</p>\n<p>उसने पठानिया को ग्यारह वर्षों का दबा हुआ सच दे दिया था, मगर वह एक बात कभी नैना तक नहीं पहुँची, जिसे उसकी सबसे ज़्यादा ज़रूरत थी—इन सारे वर्षों में नैना ने कभी पूरा जाना ही नहीं कि वह विक्रम के लिए क्या थी।</p>\n<p>और अब वह बात विक्रम के अपने मुँह से उसके पास पहुँचने वाली भी नहीं थी।</p>\n<p>इसलिए जो कुछ दोनों के बीच अनकहा रह गया था, उसे कोई दूसरा रास्ता ढूँढ़ना था।</p>\n<p>काग़ज़ का।</p>\n<p>अजनबियों के हाथों का।</p>\n<p>एक ऐसी कहानी का जिसे ठीक से कहना सीखने में पठानिया को लगभग पूरा साल लग गया था।</p>\n<p>नैना इसे कभी ढूँढ़े या नहीं, सच कभी उसके हाथ पहुँचे या नहीं—पठानिया को जाने क्यों यकीन था कि अगर वह इसे पढ़ेगी तो पहचान लेगी।</p>\n<p>किसी कहानी की तरह नहीं।</p>\n<p>एक खत की तरह—</p>\n<p>जो बस उस तक पहुँचने के लिए बहुत लंबा रास्ता लेकर आया हो।</p>\n<p>और पांडुलिपि ख़त्म करते हुए उसे फिर रुद्र प्रताप सिंह याद आए, जो महीनों पहले उसके दरवाज़े पर विक्रम का छोड़ा हुआ कर्ज लेकर आए थे।</p>\n<p>तीन लाइनें।</p>\n<p>एक बाकी कर्ज।</p>\n<p>तभी पठानिया को पहली बार पूरी तरह समझ आया कि वह इतने महीनों से असल में लिख क्या रहा था।</p>\n<p>वह किताब नहीं लिख रहा था।</p>\n<p>वह एक खत लिख रहा था।</p>\n<p>तीन सौ पन्नों का एक खत, एक ऐसी औरत के नाम जिसे शायद यह भी कभी मालूम न हो कि वह मौजूद है।</p>\n<p>और यह सीधी-सी बात उसे तब समझ आई जब रुद्र ने उसके दरवाज़े पर वे तीन शब्द कहे थे—</p>\n<p><b>तीन लाइनें। कर्ज बाकी।</b></p>\n<p>बरसों पहले पंद्रह दिनों की चुप्पी नैना से सहन नहीं हुई थी और उसने अपने खून से लिखा था—</p>\n<p><b>मैं इंतज़ार कर रही हूँ।</b></p>\n<p><b>तुमने वादा किया है कि लौटोगे।</b></p>\n<p><b>ज़िंदा लौटना, विक्रम।</b></p>\n<p>विक्रम को अपने हाथ से उनका जवाब लिखकर भेजने का मौका कभी नहीं मिला।</p>\n<p>लेकिन अब पठानिया को एक और, उससे भी बेचैन करने वाली बात समझ आई—</p>\n<p>विक्रम यह बात उससे पहले समझ चुका था।</p>\n<p>चाणक्यपुरी की उस लंबी रात वह सिर्फ कहानी नहीं सुना रहा था।</p>\n<p>वह जवाब लिखवा रहा था।</p>\n<p>धीरे-धीरे।</p>\n<p>बिना जल्दी किए।</p>\n<p>एक इक़रार के बाद दूसरा।</p>\n<p>उस कर्ज का आकार सिर्फ विक्रम जानता था, और इसीलिए वह अपने दोस्त के सामने ज़िंदगी खोलता गया था—इस भरोसे में कि जिस खत को भेजने तक वह ख़ुद न पहुँच सके, उसे कोई दूसरा पूरा कर देगा।</p>\n<p>अब किताब को वही खत बनना था।</p>\n<p>तीन लाइनों के बदले तीन सौ पन्ने।</p>\n<p>खून के बदले स्याही।</p>\n<p>हाथ किसी और का।</p>\n<p>मगर जवाब फिर भी उसी का।</p>\n<p>क्योंकि आख़िर में जवाब कितना लंबा था, यह कभी मायने नहीं रखने वाला था।</p>\n<p>मायने यह रखता था कि वह कितना गहरा था।</p>\n<p>किताब का नाम रखते समय पठानिया आख़िर उसी एक बात तक पहुँचा जो शुरू से इस पूरी कहानी का भार उठाती आई थी—उन तमाम औरतों के लिए जो कविता थीं, श्रद्धा थीं, उसकी अपनी माँ थीं, नैना थीं; जिन्होंने किसी वर्दी वाले से प्रेम किया, चाहे उस प्रेम को ज़िंदगी में जो भी रूप मिला, और फिर अपने-अपने हिस्से का वह युद्ध उठाया जिसका नाम देश ने कभी रखा ही नहीं—चुपचाप, बिना किसी को बताए।</p>\n<p>उसने किताब का नाम रखा—</p>\n<p><b>जो वह कभी कह नहीं पाया, और वह कितना गहरा था</b></p>\n<p>और उसके नीचे, छोटे अक्षरों में—</p>\n<p><b>एक जवाब, बहुत देर से</b></p>\n<p>आभार के पन्नों के भी बाद, आख़िरी पन्ने पर उसने एक छोटा-सा पैराग्राफ जोड़ा।</p>\n<p>उसे ग्यारह बार दोबारा लिखा।</p>\n<p>फिर आख़िर उसे वहीं छोड़ दिया।</p>\n<p>क्योंकि पूरी किताब उम्मीद की कहानी रही थी, मगर उसके आख़िरी सिरे पर एक ऐसा सच था जिसे सिर्फ इसलिए छिपाया नहीं जा सकता था कि उसे कहने का कोई दयालु तरीका नहीं बचा था।</p>\n<p>किताब जनवरी 2026 में छपकर आई।</p>\n<p>बिना किसी शोर के, वैसे ही जैसे ज़्यादातर किताबें दुनिया में आती हैं—बस एक दिन उनका नाम उन जगहों पर दिखाई देने लगता है जहाँ किताबें रखी जाती हैं, और फिर वे चुपचाप इंतज़ार करती हैं कि जिसे कभी उनकी ज़रूरत पड़े, वह उन्हें ढूँढ़ ले।</p>\n<p>जनवरी के उस बिल्कुल साधारण हफ्ते में न पठानिया जानता था, न शंकर, न चौधरी, न श्रद्धा—कि कुछ ही हफ्तों बाद, उनसे बहुत दूर, एक स्त्री किसी किताबों की दुकान में संयोग से चली जाएगी।</p>\n<p>वह किताब लेने नहीं गई होगी।</p>\n<p>उसे रोकने के लिए सिर्फ कवर पर बनी एक वर्दी काफी होगी।</p>\n<p>वह किताब हाथ में उठा लेगी।</p>\n<p>और कई अध्याय बीत जाने तक उसे पूरी तरह समझ नहीं आएगा कि जिन पन्नों को वह पढ़ रही है, उनमें किसकी ज़िंदगी उसके हाथों में खुल रही है—</p>\n<p>और न यह कि उसके आख़िरी पन्ने पर, चुपचाप, क्या उसका इंतज़ार कर रहा है।</p>"}, {"chapter": 60, "title": "एपिलॉग — बहुत देर से", "content": "<h1>एपिलॉग — बहुत देर से</h1>\n<p>विक्रम की मौत के छह महीने बाद, फरवरी की एक सोमवार की शाम, नैना को वह किताब मिली। पति के दफ़्तर के पास की एक छोटी-सी दुकान में—गुरुग्राम से दो सौ किलोमीटर दूर। पति की मीटिंग देर तक चलनी थी, और ऐसे में वह वक्त काटने इसी तरह की किसी दुकान में चली आती थी: बिना कुछ खरीदने के इरादे के, अलमारियों के बीच यूँ ही घूमती हुई।</p>\n<p>सबसे पहले कवर ने उसकी नज़र पकड़ी। जलते हुए सूर्यास्त के नीचे, फूलों से लदे गुलमोहर के पास दो स्त्रियाँ साथ-साथ खड़ी थीं। एक पुलिस की वर्दी में, जिसके कंधे से खाकी के बावजूद दुल्हन का लाल दुपट्टा ढलका पड़ा था; दूसरी टील रंग के कपड़ों में, जिसकी आँखें सामने देखकर भी कहीं बहुत दूर टिकी थीं।</p>\n<p><b>हवलदारनी।</b></p>\n<p>बिना पढ़े उपन्यासों की कतार में बस एक और उपन्यास। वह उसे छोड़कर आगे बढ़ ही गई थी।</p>\n<p>फिर पाँव रुक गए। वर्दी की वजह से। कभी उसने भी पहनी थी, और बरसों से किसी के सामने, यहाँ तक कि अपने सामने भी, यह नहीं माना था कि उसे उसकी कितनी याद आती है। यह वह खाकी नहीं थी। पर इतनी करीब ज़रूर थी कि उसके कुछ तय करने से पहले ही हाथ किताब तक पहुँच गया।</p>\n<p>अलमारियों के बीच उस तंग जगह में, किताब हाथ में लिए खड़ी नैना के भीतर सब कुछ एकाएक थम गया। न कोई आवाज़ हुई, न कोई वजह थी—बस उतनी-सी चुप्पी, जितनी साँस रोक लेने पर भीतर उतर आती है। उसने उसे शाम की थकान और दुकान का सन्नाटा समझ लिया, और फिर उसके बारे में दोबारा नहीं सोचा।</p>\n<p>खरीदने का फ़ैसला उसने पूरे मन से नहीं किया था, फिर भी किताब उसके साथ चली आई। दुकानदार ने उसे सादे भूरे काग़ज़ में लपेट दिया। नैना ने उसे बैग की सबसे नीचे वाली जेब में रखा और पति के सामने नहीं निकाला। यह उसने सोचकर नहीं किया था; हाथ बस वही करते थे, जिनकी उन्हें आदत पड़ चुकी थी।</p>\n<p>उसी रात, जब ऊपर पति टेलीविज़न देख रहा था और बच्चे सो चुके थे, उसने रसोई की मेज़ पर, अकेले, पहला अध्याय खोला। उस घर में उसके हिस्से की बस वही एक जगह थी, जहाँ कोई झाँकने नहीं आता था।</p>\n<p>किताब उसे चार दिन में ख़त्म करनी थी—हर रात उसी मेज़ पर। और चौथी रात उसके भीतर जो टूटा, उसका सुराग़ उसे उसी शाम मिल गया था, जब वह अलमारियों के बीच अचानक चुप हो गई थी। बस तब उसने सुना नहीं।</p>\n<p>करीब साठ पन्नों के बाद उसने ख़ुद को पहचान लिया।</p>\n<p>नाम से नहीं, अभी नहीं। गुलमोहर के नीचे बेंच पर बैठी उस लड़की में, जो तेज़ ज़ुबान थी, जिसने अपने चारों ओर दीवार खड़ी कर रखी थी, और जो धीरे-धीरे एक ऐसे सैनिक की ओर खिंच रही थी जो बोलता कम और देखता ज़्यादा था।</p>\n<p>फिर उसका अपना मज़ाक आया, ठीक उन्हीं शब्दों में—</p>\n<p><i>“पेड़ को देख लो। पेड़ों को देखना आसान होता है।”</i></p>\n<p>आगे उसके बालों का ज़िक्र था—ड्यूटी की तरह कसकर बँधे नहीं, उस दिन खुले हुए। उसे किताब नीचे रखनी पड़ी। कुछ देर वह हथेली खुले पन्ने पर दबाए बैठी रही, तब जाकर आगे पढ़ने की हिम्मत जुटा पाई।</p>\n<p>भीतर जो उठ रहा था, उसका कोई एक नाम नहीं था। पहले सदमा—ठंडा, पूरा: उसकी अपनी ज़िंदगी किसी अजनबी के वाक्यों में बिछी हुई थी, जैसे वह कभी किसी और की कहानी रही हो। फिर उसी सदमे के बीच, उसकी मर्ज़ी के बिना, एक चमकीली-सी खुशी उठी—बरसों बाद लौटी, हल्की, चक्कर-सी देती हुई। कि किसी ने उसे देखा था। इतना देखा था कि वह स्याही में उतर सके।</p>\n<p>रसोई की मेज़ पर अकेली बैठी नैना के मुँह से अचानक एक छोटी, चौंकी हुई हँसी निकल गई—और वह आवाज़ उसे अपनी नहीं लगी।</p>\n<p>अब रुकना मुमकिन नहीं था। यह उसकी ज़िंदगी थी—छपी हुई, जिल्द में बँधी, किसी अजनबी की दुकान की अलमारी में रखी हुई। यानी इन पन्नों के बाकी लोग भी कल्पना नहीं थे। वे भी सच थे।</p>\n<p>वह सरसों के उन खेतों तक पहुँची, जहाँ वह ख़ुद कभी नहीं गई थी। धीरे-धीरे समझ आया कि यह किसी और की कहानी भी है—और कुछ पन्ने बाद एक नाम आया, जिसने उसे वहीं रोक दिया।</p>\n<p><i>ओह, कविता।</i></p>\n<p>ख़याल इतनी तेज़ी से आया कि वह उसे रोक भी नहीं पाई। पूरा एक साल दोनों एक कमरे में साथ रही थीं—एक कमरा, एक चूल्हा, और ज़्यादातर रातों की साझा चुप्पी। फिर भी नैना ने विक्रम से कभी ज़ोर देकर नहीं पूछा था कि उसे उसका नंबर मिला कहाँ से। कविता ने भी कभी कुछ नहीं बताया। उसने बस एक दरवाज़ा खोला और ख़ुद पीछे हट गई।</p>\n<p>फिर पन्नों ने उसका एक पुराना डर उठाकर उसी के सामने रख दिया—किसी और के सधे हुए वाक्यों में। एक जवान लड़की का डर, कि शादी उसकी क्रिकेट वाली पुरानी तस्वीर की उस बेख़ौफ़, लाउड लड़की को धीरे-धीरे मिटा देगी; कि एक दिन वह अपनी माँ जैसी हो जाएगी—एक साथ नहीं, एक-एक छोटी चीज़ छोड़ते हुए।</p>\n<p><i>“मुझे लाउड ही रखना, विक्रम।”</i></p>\n<p><i>“हमारे साथ जो भी हो… ज़िंदगी हम दोनों को जहाँ भी ले जाए, मुझसे वादा करो कि मुझे लाउड ही रहने दोगे।”</i></p>\n<p><i>“वादा।”</i></p>\n<p>उसे याद था। सब कुछ। वह तस्वीर उसकी गोद में थी, विक्रम के हाथ उसके हाथों को घेरे हुए थे, और उसने सोलह साल की उस लड़की की तस्वीर बाकी सबके ऊपर रख दी थी—जैसे उसे सबसे ऊँची जगह देना ज़रूरी हो।</p>\n<p>वे शब्द वह कभी नहीं भूली थी। भूली थी तो वह लड़की, जो किसी से भी इतनी सीधी, इतनी पूरी बात कह सकती थी। ग्यारह बरस एक सँभली हुई, नपी-तुली ज़िंदगी बनाते-बनाते वह उसे कहीं पीछे छोड़ आई थी। बिना सोचे उसका हाथ अपने गले तक चला गया।</p>\n<p>फिर माँ की बात आई, शब्द-दर-शब्द—</p>\n<p><i>“बाकी सब सँभालने से पहले अपने दिल को सँभालकर रखना, बेटा।”</i></p>\n<p>नैना का दिल जैसे चटककर खुल गया। माँ ने उस दिन जो कहा था, वह उसने विक्रम को कभी नहीं बताया था। किसी को नहीं बताया था।</p>\n<p>फिर उसके अपने पिता आए—बरामदे की वह पूरी रात, पच्चीस साल पुराना वह घाव, जो उन्होंने आख़िर उसके सामने खोलकर रख दिया था। विक्रम को उसने बस नतीजा बताया था—<i>मना कर दिया। ख़त्म।</i> और यहाँ लगभग पूरी बात मौजूद थी।</p>\n<p>यानी विक्रम इतने बरस सिर्फ अपना दुख नहीं उठाए रहा। नैना के हिस्से की कीमत का भी एक निजी, बहुत सँभालकर रखा हिसाब वह अपने भीतर लिए फिरता रहा था।</p>\n<p>उसने अपना वादा निभाया था। बस निभाते वक्त नैना के साथ एक कमरे में खड़े होने का मौका उसे नहीं मिला।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>पन्ना एक सौ नब्बे पर नैना को अपनी ही विदा मिली।</p>\n<p><i>“मुझे नहीं पता तुम्हारे बिना अपनी ज़िंदगी कैसे जीऊँगी।”</i></p>\n<p>ठीक यही शब्द उसने कहे थे—एक रिसॉर्ट की मेज़ पर, किसी और की पत्नी बनने से तीन दिन पहले।</p>\n<p>उसी अध्याय में थोड़ा आगे वह वाक्य आया, जिस पर कुछ पल के लिए उसके शरीर को साँस लेना भी याद नहीं रहा।</p>\n<p><i>“एक दिन मैं तुम तक पहुँचूँगा।”</i></p>\n<p><i>“सालों बाद। बिना हमारे रास्ते दोबारा मिले। बिना मेरे सामने आए।”</i></p>\n<p><i>“न फोन पर।”</i></p>\n<p><i>“न दरवाज़े पर दस्तक देकर।”</i></p>\n<p><i>“उसका वक्त मैं तय नहीं कर पाऊँगा। वह पहले से ख़बर देकर नहीं आएगा। किसी चिट्ठी की तरह अपना नाम लेकर भी नहीं।”</i></p>\n<p><i>“वह ऐसे आएगा जैसे बहुत लंबे सूखे के बाद पहली बारिश आती है। बिना बुलाए। बिना तारीख़ बताए। लेकिन पहली बूँद गिरने से पहले ही मिट्टी जैसे जान लेती है कि पानी आने वाला है।”</i></p>\n<p><i>“तुम किसी बिल्कुल साधारण जगह पर होगी। किसी ऐसे काम में लगी हुई जिसका मुझसे कोई रिश्ता नहीं होगा।”</i></p>\n<p><i>“और अचानक तुम्हारे भीतर सब कुछ एक पल के लिए शांत हो जाएगा।”</i></p>\n<p><i>“वैसा ठहराव… जैसे बारिश से ठीक पहले हवा साँस रोक लेती है और आसमान को याद आता है कि उसे बरसना है।”</i></p>\n<p><i>“वह ठहराव मैं होऊँगा।”</i></p>\n<p><i>“तुम तक पहुँचने का मेरा आख़िरी तरीका।”</i></p>\n<p><i>“और उस पल तुम्हें समझ आएगा कि हमारे बीच जो था, वह कितना गहरा था।”</i></p>\n<p>किताब काँप रही थी—या उसके हाथ, अब वह फ़र्क़ नहीं कर पा रही थी। <i>यही है,</i> उसने सोचा। <i>यही वह पहुँचना है।</i></p>\n<p>न फोन। न दरवाज़े पर दस्तक। <i>ये नामुमकिन वादा है,</i> उसने उससे कहा था—और उसने फिर भी वादा किया था। और उसने यह भी निभाया था; या अभी निभा रहा था—पन्नों के रास्ते, किसी दूसरे इंसान के हाथ से, नैना के और अपने शब्दों को ग्यारह साल की चुप्पी पार कराकर, पति के दफ़्तर के पास की उस छोटी-सी दुकान तक, जहाँ वह सिर्फ वक्त काटने रुकी थी।</p>\n<p>उसने किताब सीने से लगा ली—वैसे, जैसे किसी जीवित इंसान का खत लगाया जाता है। <i>तुमने इंतज़ार किया,</i> उसने सोचा। <i>इतने बरस… तुम भी इंतज़ार कर रहे थे।</i></p>\n<p>ग्यारह साल से जिस दरवाज़े पर उसने भीतर से कुंडी चढ़ा रखी थी, वह कब्ज़ों समेत उखड़ गया। पर उसके पीछे दुख नहीं था। उम्मीद थी—अचानक, बेवजह, बहुत तेज़ रोशनी जैसी। और उस उम्मीद ने दुख से कहीं ज़्यादा दर्द दिया।</p>\n<p>बस उस खुशी के नीचे एक छोटी-सी, ठंडी बात चुभती रही, जो शांत होने को तैयार नहीं थी। <i>“ताकि तुम्हें पता हो—मैंने अपना वादा निभाया,”</i> उसने कहा था। मगर यह नहीं कहा था कि उसे निभाने की कीमत क्या होगी।</p>\n<p>और फिर उसी अध्याय के आख़िर के पास उसे अपना वह वादा मिला, जिसे उसने तोड़ा था—सीधे शब्दों में छपा हुआ, एक तथ्य की तरह।</p>\n<p><i>“हमारे बारे में उसे मत बताना।”</i></p>\n<p><i>“कभी नहीं, नैना। मुझसे वादा करो।”</i></p>\n<p><i>“वादा करती हूँ।”</i></p>\n<p>वह काफी देर उन शब्दों के सामने बैठी रही। किसी और की सधी हुई भाषा में अपना टूटा वादा पढ़ने की शर्म कुछ और ही होती है। जिस शाम उसने पति को सब बता दिया था, उसने ख़ुद को बहादुर समझा था, उसूलों वाली।</p>\n<p>उसने सोचा था कि पति को सब बताकर वह उसे सम्मान दे रही है। उस रात उसने जो सौंप दिया था, उसकी कीमत वह बरसों से चुका रही थी—यह माने बिना कि वह कोई कीमत है। विक्रम यह जानता था। इसीलिए उसने कहा था—<i>मुझसे वादा करो।</i> नैना ने सुनने का वादा किया था, और सुना नहीं।</p>\n<p>फिर उसने पढ़ा कि इस सबसे बरसों पहले एक ऑपरेशन में विक्रम को गोली लगी थी। वह एक शब्द—<i>गोली</i>—पन्ने से उठकर उसके गले पर कस गया। एक पंक्ति में ग्यारह साल की दूरी का कोई मतलब नहीं रहा। फिर दो पंक्ति नीचे: <i>ख़तरे से बाहर</i>—और जो साँस वह अनजाने में रोके बैठी थी, एक साथ निकल गई। उसका हाथ अपनी छाती पर जाकर दब गया, जैसे उस राहत को वहीं थाम लेना चाहता हो, इससे पहले कि वह भी फिसल जाए।</p>\n<p>और उस बिस्तर के पास, उसने पढ़ा, श्रद्धा नाम की एक महिला बैठी थी, जो पूरी रात नहीं उठी—एक ऐसी कुर्सी पर, जो आरामदेह हो ही नहीं सकती थी। उसकी पत्नी।</p>\n<p>नैना इंतज़ार करती रही कि उसे वह महसूस हो, जो महसूस होना चाहिए। जो आया, वह खुशी थी—सच्ची, बिना शर्म की; वैसी खुशी, जिसकी कुछ कीमत चुकानी पड़ती है और जो फिर भी दी जाती है। एक पत्नी, जो रुकी रही। अदिति नाम की बेटी, अर्जुन नाम का बेटा। वह आख़िर किसी घर लौटा था।</p>\n<p>श्रद्धा ने रात भर जागकर जो बचाया था, वह उसका सुहाग था। नैना के मन में उसके लिए सम्मान उमड़ आया।</p>\n<p><i>अच्छा हुआ,</i> उसने सोचा—और आँखें फिर भी भर आईं, क्योंकि यही तो वह उसके लिए चाहती थी, और इसमें उसके लिए कोई जगह नहीं थी। <i>अच्छा हुआ। तुम अकेले नहीं थे।</i></p>\n<p>आख़िरी अध्यायों ने उसके भीतर वह तोड़ दिया, जिसे बाकी किताब सिर्फ चटका पाई थी।</p>\n<p>उसने मीरा आनंद नाम की एक पत्रकार के बारे में पढ़ा, जो ब्रीफिंग रूम के दरवाज़े पर आते ही ठिठक गई थी। दो वाक्यों के भीतर नैना समझ गई कि पन्ने पर किसकी ज़िंदगी खुल रही है—हालाँकि नाम ने ख़ुद को एक पल और छिपाए रखा, उसे वैसे ही छेड़ता हुआ, जैसे किताब ने शुरू में उसी का अक्स दिखाकर छेड़ा था।</p>\n<p>बरसों पहले फोन पर किसी और की आवाज़ बनने की एक ख़राब-सी कोशिश। गुरुग्राम का वह फ्लैट। दरवाज़े पर बाँहें बाँधे खड़ी एक तीखी, हिफ़ाज़त करने वाली छोटी बहन।</p>\n<p><i>“बहुत पहले तय कर लिया था,” सुनैना ने कहा, “इस काम की जो भी कीमत होगी, मैं दूँगी।”</i></p>\n<p><i>“लेकिन इसकी कीमत नैना तक कभी नहीं पहुँचेगी।”</i></p>\n<p><i>सुनैना।</i></p>\n<p>खाली रसोई में उसने वह नाम एक बार सचमुच बोल दिया। आवाज़ साँस से ज़रा-सी ही ज़्यादा निकली।</p>\n<p>वह पढ़ती रही। दिल अब पसलियों के भीतर ज़ोर से और बेतरतीब धड़क रहा था। फिर वह उस छोटे-से कैफे की बातचीत तक पहुँची—दो लोग, जिनसे वह प्यार करती थी, किसी तीसरे की बात करते हुए, जिसका नाम शुरू की कई पंक्तियों तक किसी ने सीधे नहीं लिया। मगर दो वाक्यों में ही नैना समझ गई कि उस छोटी-सी मेज़ पर उन दोनों के बीच जो ज़िंदगी खुली पड़ी थी, वह उसकी अपनी थी।</p>\n<p><i>“पहले उसकी नौकरी गई।”</i></p>\n<p><i>“सज़ा कहकर नहीं।”</i></p>\n<p><i>“फ़िक्र कहकर।”</i></p>\n<p><i>“फिर अकेले कहीं आने-जाने की आज़ादी थोड़ी-थोड़ी कम हुई।”</i></p>\n<p><i>“इतनी धीरे कि शायद उसे ख़ुद याद नहीं कि आख़िरी बार वह उस घर से उसके बिना कब निकली थी।”</i></p>\n<p>फिर एक और पंक्ति, और नैना की साँस वहीं रुक गई—</p>\n<p><i>“कभी-कभी अपने पति के दफ़्तर के पास एक छोटी-सी दुकान में किताबें खरीदने जाती है।”</i></p>\n<p>उसने नज़र उठाई। रसोई की मेज़ पर वही भूरा काग़ज़ पड़ा था, जिसमें दुकानदार ने किताब लपेटी थी। किसी ने उसे इतने पास से देखा था कि उसकी दुकान तक जान ली थी—और उसे कभी पता नहीं चला था कि कोई देख रहा है।</p>\n<p><i>“नैना जवाब देती है?”</i></p>\n<p><i>“अब नहीं।”</i></p>\n<p>दो शब्द। पूरी किताब के सबसे भारी दो शब्द, और वे उसके अपने बारे में थे।</p>\n<p><i>“मैंने अपनी बहन को टुकड़ा-टुकड़ा छोटा होते देखा है, विक्रम।”</i></p>\n<p><i>“जिस दिन उसकी अपनी कमाई गई, उसी दिन उसकी आख़िरी असली आज़ादी भी चली गई।”</i></p>\n<p><i>“क्योंकि उसके बाद हर ‘नहीं’ की एक कीमत थी।”</i></p>\n<p><i>“और वह कीमत अब वह ख़ुद नहीं चुका सकती थी।”</i></p>\n<p>किताब थामे नैना की उँगलियाँ ठंडी पड़ गईं। उसने वह हिस्सा एक बार पढ़ा। फिर दोबारा, इस बार धीरे—जैसे धीरे पढ़ने से शायद शब्द बदल जाएँ। वे नहीं बदले।</p>\n<p>और उसी पन्ने पर विक्रम की आवाज़—बहुत धीमी, बिना किसी नरमी के—उस चीज़ को उसका नाम देती हुई, जिसे नैना ग्यारह साल से बड़ी सावधानी से, ख़ुद से भी, कोई नाम देने से बचती रही थी:</p>\n<p><i>“मुझे तो यह क्रूरता ही लगती है।”</i></p>\n<p><i>“मुझे भी।”</i></p>\n<p>उसने दोनों हथेलियाँ अपनी छाती पर कसकर दबा लीं, जैसे भीतर से छूट चुकी किसी चीज़ को वापस रोक सके। नहीं रोक पाई। पैरों ने साथ छोड़ दिया और वह धीरे-धीरे नीचे खिसकती हुई रसोई के फर्श पर आ बैठी—पीठ अलमारी से लगी, किताब अब भी सीने से लगी।</p>\n<p>काफी देर वह वहीं पड़ी दीवार घड़ी की टिक-टिक सुनती रही। ग्यारह साल एक साथ लौट रहे थे—हर वह छोटी-सी इजाज़त, जो उसे माँगनी पड़ी थी; उसकी शादी की हर साधारण सुबह, जो अचानक एक ऐसा नाम पहने खड़ी थी, जो उसने उसे कभी पहनने नहीं दिया था।</p>\n<p>और इन सबके नीचे, किसी बहुत पुराने साल से, उस इकलौते इंसान की आवाज़, जिसने उससे कभी धीमा होने को नहीं कहा था: <i>तुम्हें ऊँची आवाज़ में बहस करनी है तो करो। मैं उसी कमरे में बैठकर सुनना चाहूँगा, तुम्हें चुप कराने के लिए नहीं।</i></p>\n<p>ऊपर उसके बच्चे सो रहे थे। उन्हें क्या मालूम कि उनकी माँ ने कभी उस इंसान से, जो उससे प्यार करता था, कहा था कि उसे लाउड ही रखना—और फिर ग्यारह साल चुपचाप उसके उलट बनते जाने पर हामी भरती रही थी।</p>\n<p>आधी रात के करीब, जब उसने आख़िर ख़ुद को फर्श से उठाया, तो भीतर बस इतना बचा था—<i>ओह, विक्रम। तुम सिर्फ मुझसे प्यार नहीं कर रहे थे। तुम पूरे समय मुझे चेता भी रहे थे। और सुनैना—इतने बरस तुम ऐसी लड़ाइयाँ लड़ती रही, जिनके होने तक का मुझे पता नहीं था, और फिर भी मेरे लिए इस एक लड़ाई की जगह बचाए रही। चुपचाप।</i></p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसने किताब फिर उठाई और पठानिया के पन्नों तक पहुँची—ग्यारह साल बाद उसी पार्क की उसी बेंच तक, जहाँ वह एक ब्योरा जाँचने गया था और जानता था कि बात सिर्फ इतनी नहीं है।</p>\n<p><i>साफ़ हुई सतह के नीचे एक कोने में दो नाम उभरे थे। बहुत हल्के। बारिश और धूल ने ग्यारह साल में उनके किनारों को लगभग घिस दिया था। बीच में एक छोटा-सा बेढंगा दिल खरोंचा हुआ था।</i></p>\n<p><b>नैना ♥ विक्रम</b></p>\n<p><i>तो ये नाम किसने लिखे? नैना ने? किसी ऐसी दोपहर में जिसके बारे में विक्रम को कभी पता ही नहीं चला?</i></p>\n<p>नैना एकदम स्थिर हो गई। उसे मालूम था—ठीक-ठीक—किसने, और कब। दोपहर नहीं थी। शाम थी। और विक्रम उसके बगल में बैठा था।</p>\n<p>उस बेंच पर उनकी आख़िरी शाम, जिस शाम पिता का पूरा जवाब आख़िर उस तक पहुँचा था। वह सीमेंट के किनारे घुटनों के बल बैठी थी और एक की-चेन से, जिसे उसने कभी ठीक से चाबियों के लिए इस्तेमाल ही नहीं किया था, दोनों के नाम खुरच रही थी। <i>शायद हम साथ न रह पाएँ, विक्रम। लेकिन मैं चाहती हूँ कि हमारे नाम यहीं रहें—बाकी ज़िंदगी हमसे चाहे जो ले जाए।</i> यह बात उसने कभी किसी को नहीं बताई थी।</p>\n<p>आज भी वह घुटनों के नीचे वह खुरदरा सीमेंट महसूस कर सकती थी, की-चेन की वह सूखी-सी खरखराहट—और पास बैठा विक्रम, उसके हाथ को ऐसे देखता हुआ, जैसे उससे कहा गया हो कि इन दो नामों को याद कर ले।</p>\n<p>विक्रम ने उसे ग्यारह साल अपने पास रखा। पठानिया को भी नहीं बताया—उस पूरी रात में भी नहीं, जब उसने अपनी पूरी ज़िंदगी उसके सामने खोलकर रख दी थी।</p>\n<p>फिर वह पेड़ आया—लगभग नंगा, मगर खड़ा। <i>यह बूढ़ा पेड़ मर रहा है, मगर इसने उम्मीद करना नहीं छोड़ा।</i> और उसके नीचे, घास के बीच, घुटने से भी छोटे तीन-चार नए गुलमोहर।</p>\n<p>कुछ पन्ने बाद, जहाँ पठानिया को आख़िर समझ आता है कि वह असल में क्या लिख रहा था—</p>\n<p><i>वह किताब नहीं लिख रहा था।</i></p>\n<p><i>वह एक खत लिख रहा था।</i></p>\n<p><i>तीन सौ पन्नों का एक खत, एक ऐसी औरत के नाम जिसे शायद यह भी कभी मालूम न हो कि वह मौजूद है।</i></p>\n<p><i>तीन लाइनों के बदले तीन सौ पन्ने। खून के बदले स्याही। हाथ किसी और का। मगर जवाब फिर भी उसी का।</i></p>\n<p><i>क्योंकि आख़िर में जवाब कितना लंबा था, यह कभी मायने नहीं रखने वाला था। मायने यह रखता था कि वह कितना गहरा था।</i></p>\n<p>वह औरत वह ख़ुद थी।</p>\n<p>उसने किताब मेज़ पर रख दी और दोनों हथेलियाँ उसके कवर पर रख दीं। उनके नीचे दिल बहुत तेज़ धड़क रहा था। और वह बहुत देर वैसे ही बैठी रही—ग्यारह वर्षों में पहली बार पूरे दिल से शोक मनाती हुई। सिर्फ उस ज़िंदगी का नहीं, जो उसे कभी मिली ही नहीं; उन वर्षों का भी, जो मिले थे—और जिनमें वह धीरे-धीरे अपने ही भीतर से गायब होती रही, अपनी चुप्पी को शांति समझते हुए।</p>\n<p>आख़िर उसने पठानिया के आख़िरी अध्याय के आगे पन्ना पलटा—आभार के पन्ने तक। हर किताब में आने वाला वह साधारण पन्ना, जिसे शायद ही कोई पूरा पढ़ता है—संपादकों का धन्यवाद, शुरुआती पाठकों का, पत्नी के धैर्य का। नैना ने भी उसे दिलचस्पी से नहीं, लगभग आदतन पढ़ा। आँखें थक चुकी थीं।</p>\n<p>और वहीं, उस पन्ने के भी आगे, एक छोटा-सा पैराग्राफ था—इतना साधारण, इतने बिना किसी ऐलान के रखा हुआ कि उसकी आँखें लगभग उसके ऊपर से फिसल ही गई थीं। फिर शब्दों ने धीरे-धीरे अपना अर्थ बनाया—और जो अर्थ बना, उसे समझने से उसका मन अब इनकार नहीं कर सकता था।</p>\n<p><i>विक्रम राठौड़ इस किताब का एक भी शब्द पढ़ने के लिए जीवित नहीं रहा। किताब के छपने से पाँच महीने पहले उसकी मृत्यु एक ऐसे ऑपरेशन में हुई, जिसका नाम यह पांडुलिपि नहीं बता सकती, एक ऐसे देश में, जिसका नाम भी यह पांडुलिपि नहीं बता सकती—वह काम करते हुए, जिसे उससे प्यार करने वालों में से लगभग किसी ने कभी पूरी तरह नहीं जाना कि वह कर रहा था। इस कहानी के आख़िरी सिरे पर जो सच है, उसे कहने का कोई दयालु तरीका लेखक को नहीं मिला। इसलिए उसे नरम नहीं किया गया—उस इकलौती जगह में, जो इसके लिए बची थी।</i></p>\n<p><i>उसकी आख़िरी बातों में एक संदेश उसकी पत्नी के लिए था: “श्रद्धा से कहिएगा, हमारी बेटी को लाउड बड़ा करे।”</i></p>\n<p><i>और एक, लेखक के लिए: “किसी को मेरी तरफ से तीन लाइनों का जवाब मिलना है।” “पठानिया को बता दीजिएगा।” “वो समझ जाएगा।” “मेरा कर्ज चुक जाएगा।”</i></p>\n<p>उसने एक बार पढ़ा। फिर दूसरी बार—बहुत धीरे, जैसे सँभलकर दोबारा पढ़ने से शायद वही शब्द किसी कम आख़िरी अर्थ में बैठ जाएँ।</p>\n<p><i>नहीं,</i> उसके भीतर कुछ तुरंत बोला—पूरी तरह बेतुका, वैसे ही जैसे दिल अपना हिसाब तब भी नहीं छोड़ता, जब दिमाग जोड़ पूरा कर चुका हो। <i>नहीं। यह ख़त्म नहीं हुआ। मैं फिर भी उसका इंतज़ार करूँगी। ग्यारह साल कर चुकी हूँ। अगर इसकी कीमत बाकी पूरी ज़िंदगी है, तो पूरी ज़िंदगी सही।</i></p>\n<p>और फिर उसके दिमाग से पहले उसके शरीर ने सच समझ लिया। एक ही टूटी हुई साँस में उसके भीतर की सारी हवा बाहर निकली और वैसे नहीं लौटी, जैसे लौटनी चाहिए थी। जो आवाज़ उसके भीतर से फटी, वह उसने ख़ुद कभी नहीं सुनी थी—पहले धीमी, फिर उठती हुई; कच्ची, किसी घायल जानवर की पुकार जैसी। वह पूरी रसोई में भर गई, दीवारों से टकराई और वैसी ही उसके पास लौट आई।</p>\n<p>उसने मुँह पर हाथ नहीं रखा। न यह सोचा कि रात कितनी हो चुकी है, न यह कि घर में कौन सुन लेगा। वह वैसे रोई, जैसे इंसान रोना भूल जाने के बाद पहली बार रोता है—बिना किसी लय के, एक साथ, पूरा। ठंडी मेज़ पर दोहरी होकर, किताब सीने से कुचली हुई, सिसकियाँ पूरे शरीर को झकझोरती हुई।</p>\n<p>और उसके भीतर अब बस एक शब्द बचा था—<i>विक्रम… विक्रम…</i>—बार-बार, जैसे उसकी सीखी हुई पूरी भाषा में यही एक शब्द बचा हो, जो उसे अब भी आता था। इतनी बार, कि आख़िर वह नाम भी नहीं रहा। बस खो देने की आवाज़ बन गया।</p>\n<p>उसके आँसू उस कवर में उतरते रहे, जहाँ अब विक्रम के होने की आख़िरी जगह बची थी। ग्यारह साल नैना चुप रही थी। आज आख़िर वह लाउड थी—इतनी कि घर काँप जाए। विक्रम के लिए। और बहुत देर हो चुकी थी।</p>\n<p>ऊपर से कोई नीचे नहीं आया।</p>\n<p><i>लाउड।</i> यह उसका शब्द था। सोलह साल की अपनी तस्वीर गोद में रखकर उसने विक्रम से कहा था कि उसे ऐसा ही रखना—और विक्रम उस एक शब्द को ग्यारह बरस उठाए फिरा, अपनी ज़िंदगी के आख़िरी घंटे तक। अपने लिए उसने कुछ नहीं माँगा। उसने बस यह माँगा कि एक छोटी-सी लड़की, जिससे नैना कभी मिलेगी भी नहीं, उसे वही बनने दिया जाए, जिसे खो देने से नैना डरती थी।</p>\n<p><i>तुम चाहते थे कि वह मेरे जैसी बने।</i></p>\n<p>यह कोई कर्ज नहीं था। यह उसका सबसे पूरा तरीका था यह कहने का, कि क्रिकेट की उस तस्वीर वाली लड़की से उसने कभी प्यार करना बंद नहीं किया।</p>\n<p><i>तीन लाइनें।</i> इसे दोबारा पढ़ने की ज़रूरत नहीं थी। इंसान अपने आख़िरी मिनटों में जाने क्या-क्या याद कर सकता है—विक्रम को वह खून याद रहा, जिससे इक्कीस साल की नैना ने लिखा था।</p>\n<p>पंद्रह सौ किलोमीटर। एक बार वह बुखार में पड़ी नैना के लिए इतना रास्ता पार करके आया था—एयर फोर्स के विमान में माँगी हुई सीट पर—और पहुँचते ही उसकी बताई दूरी भी ठीक की थी, क्योंकि तब भी उसके लिए सही संख्या मायने रखती थी। नैना हँस पड़ी थी।</p>\n<p>आज वह कोई भी दूरी पार कर लेती। मगर किसी रास्ते के आख़िर में अब शीशे के दरवाज़े वाला कोई वार्ड नहीं था, न बिस्तर के पास खिंची कोई कुर्सी। बस एक रसोई थी, एक किताब—और एक ऐसा इंसान, जो हमेशा ख़ुद उसके पास आया था।</p>\n<p>उसने उसका चेहरा याद करने की कोशिश की—सिर्फ चेहरा—और उसे थामे नहीं रख पाई। एक जबड़ा। ध्यान से सुनते वक्त उसकी आँखों के बीच पड़ने वाली वह हल्की-सी शिकन। टुकड़े आते रहे; पूरा चेहरा नहीं। ग्यारह साल तक उसने माना था कि एक बार और होगा—किसी दरवाज़े पर, किसी भीड़ भरी सड़क पर, कोई ऐसा पल, जब वह नज़र उठाएगी और बस उसे पहचान लेगी।</p>\n<p>अब पार करने को कोई दूरी ही नहीं बची थी।</p>\n<p>रसोई का नल अब भी चल रहा था—घंटा भर पहले गिलास भरते वक्त वह उसे बंद करना भूल गई थी। काफी देर तक वही आवाज़ दुनिया की इकलौती साफ़ आवाज़ बनी रही—पतली, मामूली, घरेलू, उसके दुख से बिल्कुल बेपरवाह। बाकी सब जैसे किसी ने बहुत दूर कर दिया था, हर आवाज़ धीमी करके, सिवाय पानी की उस एक पतली धार के।</p>\n<p>उसने नल के पास रखा गिलास उठाने को हाथ बढ़ाया। वह उँगलियों से कब छूटा, उसे पता भी नहीं चला। गिलास टूटा नहीं—काउंटर के किनारे से धीरे-धीरे, जैसे सोच-समझकर, लुढ़का और फर्श पर जा गिरा; पानी टाइलों पर एक पतली, गहरी परत की तरह फैल गया। नैना ने उसे साफ़ नहीं किया। वहीं उसके पास बैठ गई—किताब अब भी आख़िरी पन्ने पर खुली, हाथ में। पानी धीरे-धीरे उसकी साड़ी के किनारे तक पहुँचा और कपड़ा गहरा हो गया। उसे पता भी नहीं चला।</p>\n<p>किसी ने उसे नहीं बताया था कि चिता कहाँ जली, कौन-सा घाट था। तेरहवीं में उसे किसी ने नहीं बुलाया, और बुलाने को उसके पास था ही क्या: वह उसकी विधवा नहीं थी, बहन नहीं, बेटी नहीं। दुनिया के किसी रिश्ते में उसके लिए रोने की जगह नहीं बनी थी।</p>\n<p>फर्श पर पानी फैला था। नैना ने उसमें हथेली डुबोई और दोनों हाथों में उठाकर वापस उसी में छोड़ दिया—एक बार, दो बार, तीन बार—<i>विक्रम राठौड़।</i> हर बार पूरा नाम। उसे कोई मंत्र नहीं आता था। उसे बस एक ही नाम आता था।</p>\n<p>यही उसका तर्पण था—चुराया हुआ, रसोई के फर्श पर, अकेले, पति के घर में।</p>\n<p>उसका हाथ अपने ही बालों में चला गया—बहुत धीरे, बिना जल्दी—ठीक वैसे, जैसे कभी विक्रम का हाथ चलता था: अस्पताल के वार्ड में, पहाड़ की उस रिज पर, उस बेंच पर—जब भी उसे बस रो लेने देना ज़रूरी होता था। यह वैसा नहीं था। मगर अब यही इकलौती चीज़ बची थी, जो वह अपने लिए वैसे कर सकती थी, जैसे कभी विक्रम ने उसके लिए की थी। और एक ही बात भीतर बार-बार लौटती रही—हर बार पहले से धीमी—जब तक वह वाक्य कम और प्रार्थना ज़्यादा नहीं बन गई।</p>\n<p><i>तुम लौट आए।</i></p>\n<p><i>तुम लौट आए… और मुझे एक बार भी पता नहीं चला।</i></p>\n<p><i>ज़िंदा लौटना,</i> उसने कभी लिखा था। विक्रम लौटा था। ज़िंदा नहीं। उसके पास भी नहीं। और नैना दो सौ किलोमीटर दूर थी—बेख़बर।</p>\n<p>किताब उसके घुटनों पर खुली पड़ी थी। उसने उसे उठाया तो सामने का कवर रोशनी की तरफ हो गया। चार दिन पहले भी उसने यही कवर देखा था—उसे बस एक सूर्यास्त दिखा था, पुराने ज़ंग जैसे रंग का जलता आसमान—और उसने दोबारा ध्यान नहीं दिया था। आज देखा।</p>\n<p>वह रंग सूर्यास्त नहीं था। पूरे आसमान पर तीन बहुत हल्की पंक्तियाँ दौड़ रही थीं, छपाई में इतनी नरम कर दी गई थीं कि बादल लगती थीं। शब्द पहचानने से पहले नैना ने लिखावट पहचान ली—अपनी। इक्कीस साल की उम्र की। अपने खून से लिखी हुई। वही पन्ना, जो उसने विक्रम को भेजा था, और जिसे विक्रम ने पूरी उम्र सँभालकर रखा।</p>\n<p>किसी को पता था। किसी ने वह खत रोशनी के सामने उठाया था और उसे आसमान बन जाने दिया था।</p>\n<p>आधी रात बीत चुकी थी। नैना अब भी उसी ठंडे फर्श पर बैठी थी, जब एक बहुत पुरानी, लगभग भुला दी गई आदत बिना उसकी इजाज़त के लौट आई—वही, जिसने ग्यारह साल पहले उसका हाथ उस छोटे ब्लेड तक पहुँचाया था, जिससे वह पेंसिलें छीलती थी। उसने ऊपर की दराज़ से एक छोटा चाकू निकाला और अँगूठे पर एक छोटा-सा चीरा लगाया—दूसरा हाथ अब भी छाती पर दबाए, जैसे ऐसा करते हुए भी वह अपने दिल को पूरी तरह बिखरने से रोक सकती हो।</p>\n<p>किताब के आख़िरी खाली पन्ने पर—वही पन्ना, जिसे प्रकाशक सबसे पीछे बेवजह खाली छोड़ देते हैं—उसने काँपते हाथ से वही तीन पंक्तियाँ लिखीं, जो ग्यारह साल पहले लिखी थीं। शब्दशः।</p>\n<p><i>I am waiting.</i></p>\n<p><i>You promised me you will come back.</i></p>\n<p><i>Come back alive, Vikram.</i></p>\n<p><b>मैं इंतज़ार कर रही हूँ।</b><br/>\n<b>तुमने वादा किया है कि लौटोगे।</b><br/>\n<b>ज़िंदा लौटना, विक्रम।</b></p>\n<p>पहली बार तीसरी पंक्ति तक पहुँचते-पहुँचते खून हल्का पड़ गया था। इस बार नहीं पड़ा।</p>\n<p>वह बहुत देर उसे देखती रही। खून धीरे-धीरे काग़ज़ में सूख रहा था—वैसे ही, जैसे ग्यारह साल पहले सूखा था, जब वह वादा अभी निभाया जा सकता था।</p>\n<p>कहीं भीतर, उस हिस्से के नीचे जो फिर भी लिखे जा रहा था, वह जानती थी कि इस बार यह काम नहीं करेगा। पहली बार भी इसने सचमुच काम नहीं किया था। विक्रम तब अपने दम पर लौटा था, अपने वादे के दम पर; इसलिए नहीं कि खून में कभी ऐसी ताकत थी कि जंग जहाँ भी किसी इंसान को ले जाए, वहाँ से उसे घर बुला ले। वह यह सब साफ़-साफ़ जानती थी—जैसे शोक में डूबा मन बहुत-सी सच्ची बातें जानता है, और उस रात उन पर यकीन करने का उसका कोई इरादा नहीं होता।</p>\n<p>उसने फिर भी लिखा। क्योंकि लिखना—कितना भी बेकार हो—विक्रम के लिए उसके प्रेम के पास बची वह इकलौती शक्ल थी, जिसे लेने की उसे अब भी इजाज़त थी।</p>\n<p>विक्रम ने उसकी तीन लाइनों का जवाब देने का वादा किया था।</p>\n<p><i>तीन लाइनों में नहीं।</i></p>\n<p><i>इतना बड़ा जवाब जितना उन तीन लाइनों का हक है।</i></p>\n<p>नैना ने किताब दोनों हाथों में थामी और आख़िर उसका वज़न समझा। और उसने ख़ुद कहा था, बिल्कुल आख़िर में—<i>मेरा कर्ज चुक जाएगा।</i></p>\n<p>यह उसके बारे में लिखी कहानी नहीं थी। यह विक्रम का जवाब था—इसका हर पन्ना। और बदले में देने के लिए उसके पास बस वही तीन पंक्तियाँ बची थीं, उसी ज़ंग के रंग की लिखावट में।</p>\n<p>फोन पास ही टाइलों पर उल्टा पड़ा था। उसने बिना सोचे उसे पलटा, और अँगूठा अपने आप चलने लगा—वे दस अंक दबाता हुआ, जिन्हें उसे कभी सेव करने की ज़रूरत नहीं पड़ी थी; वही नंबर, जिससे एक दिन आया था—<i>सॉरी, ग़लत नंबर।</i> ग़लत नंबर, जो उसकी ज़िंदगी का सबसे सही नंबर निकला। कुछ नंबर उँगलियों में तब भी बसे रहते हैं, जब हर दूसरी जगह से मिट चुके हों।</p>\n<p>आख़िरी अंक के ऊपर अँगूठा रुक गया। उसने नंबर नहीं मिलाया। फोन नहीं बजेगा, यह विक्रम ने पहले ही बता दिया था—और वह दोनों में से कोई जवाब नहीं सह पाती: न कोई ऐसी आवाज़, जो विक्रम की नहीं थी; न कोई ऐसी चुप्पी, जो विक्रम की थी।</p>\n<p>उसे गुलमोहर याद आया। किताब में लिखा हुआ नहीं—अपनी याद वाला, जो अब ग्यारह साल पुरानी थी: नंगा और धूसर, जैसा उसने आख़िरी बार उसके पास खड़े होकर देखा था, इससे पहले कि उसने उस पार्क के सामने से गुज़रना ही छोड़ दिया। आज उसे वह बात समझ आई, जो वहाँ खड़े होकर समझ नहीं आई थी। पेड़ तब भी ज़िंदा था। नंगा, हर दिखने वाले पैमाने पर मरता हुआ—मगर ज़िंदा। टिका हुआ, जैसे पुरानी, ज़िद्दी चीज़ें टिकी रहती हैं; एक ऐसे वसंत के इंतज़ार में, जिसने अभी आने का फ़ैसला नहीं किया था।</p>\n<p>विक्रम के हिस्से वह वसंत नहीं आया।</p>\n<p><i>बाकी हर वादा भूल जाओ, जो तुमने मुझसे कभी किया, विक्रम,</i> उसने सोचा—शब्द अब प्रार्थना कम और एक थकी हुई ज़िद ज़्यादा बनकर आ रहे थे। <i>बस वह एक निभाओ, जो पंद्रहवें दिन निभाया था। मैंने पंद्रह दिन इंतज़ार किया था, और फोन पर तुम्हारी आवाज़ आई थी—</i></p>\n<p><i>“मैं ठीक हूँ।”</i></p>\n<p><i>“एक खरोंच तक नहीं है। बिल्कुल ठीक हूँ।”</i></p>\n<p><i>वही फिर कहो। बस एक बार और। मैं अब भी मानती हूँ—कहीं ऐसी जगह, जहाँ से कोई तर्क मुझे बाहर नहीं निकाल सकता—कि तुम कहोगे।</i></p>\n<p>उस धूसर पहर में कहीं, बिना किसी आवाज़ के, उसके भीतर सब कुछ ठहर गया। यह थकान वाला ठहराव नहीं था—उसे वह अच्छी तरह पहचानती थी। यह कुछ और था। रसोई ने साँस रोक ली। नल, घड़ी, यहाँ तक कि उसकी अपनी नब्ज़ भी जैसे रुककर इंतज़ार करने लगी।</p>\n<p>यह पहली बार नहीं था। चार दिन पहले, अलमारियों के बीच उस सँकरी जगह में, यही किताब हाथ में लिए, उसके भीतर ठीक ऐसे ही सब कुछ शांत हुआ था—और उसने उसे शाम की थकान मान लिया था।</p>\n<p><i>और अचानक तुम्हारे भीतर सब कुछ एक पल के लिए शांत हो जाएगा।</i></p>\n<p><i>वैसा ठहराव… जैसे बारिश से ठीक पहले हवा साँस रोक लेती है और आसमान को याद आता है कि उसे बरसना है।</i></p>\n<p><i>वह ठहराव मैं होऊँगा।</i></p>\n<p><i>तुम तक पहुँचने का मेरा आख़िरी तरीका।</i></p>\n<p><i>ये नामुमकिन वादा है,</i> उसने उससे कहा था।</p>\n<p><i>शायद।</i></p>\n<p><i>फिर भी कर रहा हूँ।</i></p>\n<p>वह हिली नहीं। साँस लेने की हिम्मत भी नहीं की—कहीं साँस लेने से यह टूट न जाए। और बहुत हल्के-से, एक ऐसे शहर की रसोई में, जहाँ आसपास कहीं चीड़ का एक पेड़ तक नहीं था—हवा में चीड़ की हल्की-सी राल जैसी महक थी।</p>\n<p>उस दिन उसने कहा था—<i>“मुझे तो कुछ अलग नहीं लग रहा।”</i> आज लगा।</p>\n<p><i>यही वह ठहराव है,</i> उसने सोचा। <i>यही तुम हो।</i></p>\n<p><i>और उस पल तुम्हें समझ आएगा कि हमारे बीच जो था, वह कितना गहरा था।</i></p>\n<p><b>उनके बीच जो था—वह कितना गहरा था।</b></p>\n<p>सब कुछ। यह हमेशा से सब कुछ था। और अब, बिना किसी शक के, ख़त्म भी—एक ऐसा सच, जिसे वह बाकी पूरी उम्र चुपचाप अपने भीतर लेकर चलेगी।</p>\n<p>गुलमोहर ने अपनी लंबी सर्दियाँ ख़ुद झेलीं—उस वसंत के इंतज़ार में, जो विक्रम के लिए कभी आने वाला नहीं था—और फिर भी हर साल खिलता रहा, उन सबके लिए, जो बाद में आए और कभी नहीं जान पाए कि उनके लिए वहाँ खड़े रहने की खातिर वह पेड़ पहले क्या-क्या सह चुका था। उसके नीचे अब छोटे-छोटे नए गुलमोहर उग आए थे।</p>\n<p>वह वहीं बैठी रही, जब तक सुबह की पहली धूसर रोशनी रसोई की दीवार पर नहीं चढ़ आई। दोनों हाथ आख़िरकार स्थिर, आख़िरकार शांत—एक के ऊपर एक, अपनी ही छाती पर रखे हुए—जैसे उस पूरे घर में उसे आख़िर वह इकलौती चीज़ मिल गई हो, जो अब भी पूरी तरह, सिर्फ उसकी थी, थामने के लिए।</p>\n<p><b>उनके बीच जो था—वह कितना गहरा था।</b></p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p><i>कुछ मोहब्बतें ख़ामोश थीं, और ख़ामोश ही रह गईं।</i></p>"}];
